% Elementary spectral estimates for $\bG^{(2)}$ imply that up to adjusting parameters, $\bsig\in S(\gamma,\delta)$ is equivalent (with probability $1-e^{-cN}$) to the $L^1$-deviation requirement.
% \[
% \frac{1}{N}
% \sum_{i=1}^N
% \big(\gamma-\sigma_i L_i(\bsig)\big)_+
% \leq
% \delta.
% \]
% On the sphere, a similar reformulation holds for the eigenvalues using Proposition~\ref{prop:gradients-bounded}.
% The spherical definition can also be reformulated using e.g.\ \cite[Lemma 3]{subag2018following}, which states that the bulk spectral Hessian of a spherical spin glass is essentially a semicircular distribution deterministically shifted by the radial derivative $\nabla_{\rd} H_N(\bsig)=\la \nabla H_N(\bsig),\bsig)\ra/N$.
% Namely it implies that up to adjusting parameters, $\bsig\in W(\gamma,\delta)$ is equivalent to requiring that $\|\nabla_{\sph} H_N(\bsig)\|\leq \delta\sqrt{N}$ and $ \nabla_{\rd}H_N(\bsig)\geq 2\sqrt{\xi''(1)}+\gamma$.







Our first main result, Theorem~\ref{thm:SK-hardness-LDP}, shows gapped states for the SK model cannot be found using large classes of efficient algorithms.
We provide three separate statements, which trade-off the power of the algorithm class with the bound obtained on the algorithm's success probability.
For our purposes, an ``algorithm'' means a measurable function $\cA^{\circ}:(H_N,\omega)\mapsto \bsig\in\bSig_N$, where $\omega$ is an independent random variable in some Polish space $\Omega_N$.
The variable $\omega$ enables $\cA$ to be randomized; we say $\cA$ is deterministic if it does not depend on $\omega$.
Since the most relevant classes of algorithms for us naturally have continuous outputs, we turn such an $\cA^{\circ}:(H_N,\omega)\mapsto \bx\in\bbR^N$ into a $\bSig_N$-valued algorithm $\cA$ using a randomized rounding scheme.
With $\vec U=(U_1,\dots,U_N)\stackrel{IID}{\sim}\Unif([-1,1])$ independent of $(H_N,\omega)$, we analyze the performance of
\begin{equation}
\label{eq:round-stable-alg}
\cA(H_N,\omega,\vec U)
\equiv
\round_{\vec U}(\cA^{\circ}(H_N,\omega)).
\end{equation}
Here we define the coordinate-wise function $\round_{\vec U}(\bx)=\big(\round_{U_1}(x_1),\dots,\round_{U_N}(x_N)\big)$ for
\begin{align*}
\round_U(x)
=
\begin{cases}
1,\quad x\geq U,
\\
-1 \quad x<U.
\end{cases}
\end{align*}
Below, we say $\cA^{\circ}$ is $C$-Lipschitz if it is $C$-Lipschitz for each fixed $\omega$, where the domain $H_N\simeq (\bG^{(k)})_{2\leq k\leq \bar k}$ and codomain are metrized by the unnormalized Euclidean norm.
We say $\cA^{\circ}$ is a degree $D$ polynomial if each of its $N$ output coordinates is a degree $D$ polynomial in the coefficients of $H_N$, for any fixed $\omega$.


\begin{theorem}
\label{thm:SK-hardness-LDP}
For any $\gamma>0$ there exists $\delta>0$ such that for any fixed $C>0$ and $N$ sufficiently large:
\begin{enumerate}[label=(\Roman*)]
    \item
    \label{it:lipschitz-alg-conseq}
    If $\cA^{\circ}$ is $C$-Lipschitz, then $\cA$ (as defined in \eqref{eq:round-stable-alg}) satisfies for some $c(\gamma,\delta,C)>0$:
    \[
    \bbP[\cA(H_N,\omega,\vec U)\in S(\gamma,\delta;H_N)]\leq e^{-cN}.
    \]
    \item
    \label{it:low-degree-strong-conseq}
    If $\cA^{\circ}$ is a deterministic degree $D\leq \frac{\log N}{11}$ polynomial with $\bbE^{H_N}[\|\cA^{\circ}(H_N)\|^2]\leq CN$, then $\cA$ satisfies
    \[
    \bbP[\cA(H_N,\vec U)\in S(\gamma,\delta;H_N)]\leq e^{-\Omega(DN^{1/3D})}
    \leq
    N^{-\Omega(1)}.
    \]
    \item
    \label{it:low-degree-ultimate-conseq}
    If $\cA^{\circ}$ is a deterministic degree $D\leq o_{N\to\infty}(N)$ polynomial with $\bbE^{H_N}[\|\cA^{\circ}(H_N)\|^2]\leq CN$, then
    \[
    \bbP[\cA(H_N,\vec U)\in S(\gamma,\delta;H_N)]\leq
    (D/N)^{c(\gamma,\delta,C)}
    \leq
    o_{N\to\infty}(1).
    \]
\end{enumerate}
\end{theorem}


Theorem~\ref{thm:SK-hardness-LDP}\ref{it:lipschitz-alg-conseq} is proved using an ensemble version of the overlap gap property (OGP); this technique was first used in \cite{chen2019suboptimality}, following the introduction of the OGP in \cite{gamarnik2014limits}.
As discussed in Subsection~\ref{subsec:strong-hardness-discussion}, parts \ref{it:low-degree-strong-conseq},\ref{it:low-degree-ultimate-conseq} establish \emph{strong low degree hardness} of finding gapped states, and are the first such results for any random search problem without planted structure.
We also mention that from part~\ref{it:low-degree-ultimate-conseq}, it trivially follows that for any \emph{randomized} degree $D\leq o(N)$ polynomial $\cA^{\circ}$ satisfying the averaged bound $\bbE^{H_N,\omega}[\|\cA^{\circ}(H_N,\omega)\|^2]\leq CN$, the rounded algorithm $\cA$ has success probability $o(1)$; just apply the Markov inequality to $\omega\mapsto \bbE[\|\cA^{\circ}(H_N,\omega)\|^2\,|\,\omega]$ to reduce to the deterministic case.




\begin{remark}
\label{rem:rounding-schemes}
    While we used randomized rounding above for concreteness, the precise choice of rounding scheme is not important: one just needs a random function from $\bbR^N$ to $\bSig_N$ which is stable with high probability.
    To illustrate the flexibility, we recall that in \cite[Definition 2.3]{gamarnik2020optimization} a $\bbR^N$-valued algorithm is said to solve a random optimization problem with domain $\bSig_N$ if its coordinate-wise sign solves the problem, and additionally only an $\eta$-fraction of coordinates have absolute value at most $\lambda$. (Here both $\eta$ and $\lambda$ are small dimension-free constants, and the latter is denoted $\gamma$ therein.)
    Given such an solution, one can multiply its output by $1/\lambda$, and then its randomized rounding will almost surely lie within $2\sqrt{\eta N}$ of its coordinate-wise sign.
    In both our setting and that of \cite{gamarnik2020optimization}, this $2\sqrt{\eta N}$ distance has a negligible effect on the algorithm's performance.
    Therefore our results obstruct low degree algorithmic solutions in this sense as well.
    Similar comments apply to the formalizations in \cite{wein2020independent,bresler2021ksat}, who treat coordinates of $\cA^{\circ}(\cdot)$ in a certain interval as ``errors''; this roughly corresponds to worst-case rounding rather than our randomized rounding (and so hardness in our sense implies hardness in theirs).
    Finally if the independent coordinates $U_i$ are non-uniform but drawn from a bounded density, all of our results still apply.
    % (Even $\sup_{a\in\bbR}\bbP[U_i\in [a,a+\eps]]\leq \eps^{\Omega(1)}$ is fine.)
\end{remark}


Turning to spherical spin glasses, we consider the canonical Langevin dynamics (with initialization independent of $H_N$), and prove that this method cannot find wells on dimension-free time-scales.
The Langevin dynamics at inverse temperature $\beta\in\bbR$ are given by the SDE
\begin{equation}
    \label{eq:langevin-dynamics}
    \de \bx_t
    =
    \lt(\beta \nabla_{\sph} H_N(\bx_t)
    -
    \frac{(N-1)\bx_t}{2N}\rt)
    \de t
    +
    P_{\bx_t}^{\perp}\sqrt{2}~\de \bB_t.
\end{equation}
Here $\bx_0$ is independent of the disorder and $P_{\bx}^{\perp}=I_N-\frac{\bx\bx^{\top}}{N}$ is a rank $N-1$ projection matrix, while $\bB_t$ is an independent Brownian motion in $\bbR^N$.
It is a standard fact (see e.g. \cite{hsu2002stochastic}) that $\bx_t$ remains on $\cS_N$ almost surely, and has stationary measure given by the Gibbs measure with density proportional to $e^{\beta H_N(\bx)}$.

\begin{theorem}
\label{thm:langevin-fails-pseudo-wells}
    Let $H_N$ be a mixed $p$-spin model Hamiltonian with covariance function $\xi$ (recall \eqref{eq:def-xi}).
    Then for any $\gamma>0$ there exists $\delta=\delta(\xi,\gamma)>0$ such that the following holds.
    For any $T,\beta>0$ there exists  $c=c(\xi,T,\beta,\gamma,\delta)>0$, such that for $N$ large, if $\bx_0$ is independent of $H_N$ and $\bx_t$ solves \eqref{eq:langevin-dynamics}, then
    \[
    \bbP[\bx_T\in W(\gamma,\delta)]\leq e^{-cN}.
    \]
\end{theorem}



In the pure case $\xi(t)=t^k$, Theorem~\ref{thm:langevin-fails-pseudo-wells} is closely related to the threshold results from \cite{huang2021tight,huang2023algorithmic,sellke2023threshold}.
While these works are focused specifically on the energy value obtained, Theorem~\ref{thm:langevin-fails-pseudo-wells} studies the qualitative behavior of the algorithmically reachable part of the landscape (see \cite{alaoui2024near} for another recent work in a related spirit).
We note that the threshold energy of pure spherical $p$-spin models was first predicted by physicists \cite{cugliandolo1994out,biroli1999dynamical} based on the idea that Langevin dynamics cannot find wells.
Theorem~\ref{thm:langevin-fails-pseudo-wells} therefore confirms the original physical intuition behind these predictions.


In both models, the landscape of local optima has been thoroughly studied in its own right.
On the sphere, the existence of wells has been understood for many $\xi$ via the Kac--Rice formula, which gives a general method to count critical points of random landscapes \cite{auffinger2013random,auffinger2013complexity,fyodorov2014topology,subag2017complexity,subag2017geometry,arous2021exponential,belius2022triviality,huang2023strong}.
In particular, this line of work showed that the ground states of spherical spin glasses are wells when $\xi$ is in the interior of the $1$-RSB or topologically trivial phase at zero temperature.
Recently in \cite{sellke2024marginal}, the second author characterized which spherical spin glasses have ground states that are wells, in terms of the RSB behavior in the Parisi formula.
On the cube, the analogous full RSB behavior is always true for mean-field spin glasses \cite{auffinger2020sk}, which may suggest that ground states are typically not gapped.
Indeed it was only shown recently that gapped states for the SK model exist at all by \cite{minzer2023perfectly,dandi2023maximally}, which in fact determined the maximum possible $\gamma$ (see also \cite{ferber2022friendly}).
Both \cite{behrens2022dis,minzer2023perfectly} conjectured the algorithmic hardness of finding gapped states in the SK model.




\subsection{Discussion of Strong Low Degree Hardness}
\label{subsec:strong-hardness-discussion}


Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-strong-conseq},\ref{it:low-degree-ultimate-conseq} show \emph{strong low degree hardness} of finding gapped states in the following sense.


\begin{definition}
\label{def:SLDH}
A sequence of random search problems, formally given by an $N$-indexed sequence of random input vectors $\by_N\in\bbR^{d_N}$ and random subsets $S_N=S_N(\by_N)\subseteq\bSig_N$, is said to exhibit \textbf{strong low degree hardness up to degree $D\leq o(D_N)$} if the following holds as $N\to\infty$.
If $\cA^{\circ}=\cA_N^{\circ}(H_N,\omega)\mapsto\bsig\in\bbR^N$ is a sequence of polynomial algorithms of degree $o(D_N)$ obeying $\bbE[\|\cA^{\circ}(\by_N,\omega)\|^2]\leq O(N)$, then for $\cA_N(\by_N,\omega,\vec U)$ as in \eqref{eq:round-stable-alg},
\[
\bbP[\cA_N(\by_N,\omega,\vec U)\in S_N(\by_N)]\leq o(1).
\]
\end{definition}


Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-strong-conseq}, \ref{it:low-degree-ultimate-conseq} are shown using the same problem-specific strategy as part \ref{it:lipschitz-alg-conseq}, but with a new general-purpose enhancement in implementing the ensemble OGP.
As a result both of these latter statements are qualitatively much stronger than any previous low degree hardness results for random search problems without planted structure.\footnote{
For problems with planted structure, e.g.\ tensor PCA with a hidden signal vector, a convenient approach to low degree hardness is to study the hypothesis-testing problem for the presence/absence of signal.
This can be studied via the low degree likelihood ratio test \cite{hopkins2018statistical,kunisky2019notes}, which gives evidence of hardness in a sense which is
somewhat different from
% slightly less direct than
our results.
The related sum-of-squares lower bounds can also provide evidence for computational hardness, see e.g.\ \cite{hopkins2015tensor,barak2019nearly}.
}
Previous results such as \cite{gamarnik2020optimization,wein2020independent,bresler2021ksat,gamarnik2022algorithms,li2024discrepancy} could at best establish that the success probability is bounded above by $1-f(D)$, where $f(D)>0$ for fixed $D$ but $\lim_{D\to\infty} f(D)=0$.
Our method seems to be compatible with essentially any stability argument based on the discrete-time intermediate value theorem.
Indeed in Section~\ref{sec:low-degree}, we improve results from all five of the papers just mentioned to strong low degree hardness.


\begin{theorem}{(Informal version of results in Subsections~\ref{subsec:prior-ogp-improve}, \ref{subsec:CSP}, \ref{subsec:dense-max-ind-set})}
\label{thm:informal}
    The following problems exhibit strong low degree hardness in a suitable range of parameters:
    \begin{enumerate}[label=(\alph*)]
    \item
    \label{it:informal-1}
    Optimization of pure Ising $k$-spin glasses for $k\geq 4$ even, up to $D\leq o(N)$.
    \item
    \label{it:informal-2}
    The symmetric binary perceptron, up to $D\leq o(N/\log N)$.
    \item
    \label{it:informal-3}
    The asymmetric Ising perceptron, up to $D\leq o(N/\log N)$.
    \item
    \label{it:informal-4}
    Large independent sets in sparse Erdős--Rényi graphs, up to $D\leq o(N)$.
    \item
    \label{it:informal-5}
    Random $k$-SAT, up to $D\leq o(N)$.
    \item
    \label{it:informal-6}
    Large independent sets in $G(N,1/2)$, up to $D\leq o(\log^2 N)$.
    \end{enumerate}
\end{theorem}


As discussed below, the low-degree prediction suggests that the above ranges of $D$ are optimal, except for the logarithmic factors in \ref{it:informal-2}, \ref{it:informal-3}.
These factors stem from Ramsey-theoretic arguments used in the more complicated multi-ensemble OGP, introduced by \cite{gamarnik2021partitioning,gamarnik2022algorithms}.


We do not know how to combine our method with the branching overlap gap property \cite{huang2021tight,huang2023algorithmic}, which gives a general technique to compute exact thresholds in mean-field random optimization problems, for the more restricted class of Lipschitz algorithms.
It would be extremely interesting to deduce strong low degree hardness from the branching OGP.


\paragraph{On the importance of high-probability guarantees in OGPs.}


As discussed further in Subsection~\ref{subsec:proof-ideas}, an important step in our implementation of the ensemble OGP is to replace certain costly union bounds by correlation inequalities.
This lower-bounds the probability that a putative algorithm succeeds and is stable across the full ensemble, by a quantity $q^K$ which decays exponentially in the number $K$ of correlated Hamiltonians used in the OGP obstruction.
Consequently the probability that the OGP obstruction holds is crucial to our argument.
In particular if such an obstruction holds with probability $1-p_{\OGP}$, then one can run the desired OGP argument so long as $K\ll \log(1/p_{\OGP})$.
In our arguments, this turns out to correspond to hardness up to degree $D\ll \log(1/p_{\OGP})$.
Thanks to concentration of measure, it is a ubiquitous feature of mean-field disordered systems that rare events have exponentially small probability of order $e^{-\Omega(N)}$.
This explains why we are able to obtain strong low degree hardness up to $D\leq o(N)$ in many settings.



Heuristically, degree $D$ polynomials are believed to often serve as a good proxy for the class of $e^{\tilde O(D)}$-time algorithms \cite{hopkins2018statistical,kunisky2019notes}.
Thus, our results may be taken as evidence that exponential $e^{\tilde\Omega(N)}$ time is required to find gapped states, and to solve the other problems mentioned in \ref{it:informal-1}-\ref{it:informal-5} above.
Conversely since solving any search problem over $\bSig_N$ in exponential time is trivial by brute-force, this heuristic suggests that the range $D\leq o(N)$ may be best possible in such problems.
Given the previous paragraph, our results lead us to propose the following rule of thumb:
\[
    \parbox{11cm}{\emph{If a random search problem exhibits an OGP with probability $1-p_{\OGP}$, then algorithms may require running time $p_{\OGP}^{-\Omega(1)}$ to find a solution.}}
\]
This rule of thumb is also consistent with the maximum clique problem in $G(N,1/2)$.
Here an overlap gap property holds with probability $1-e^{-\Theta(\log^2 N)}$, which leads to Theorem~\ref{thm:informal}\ref{it:informal-6}, while the best known algorithms (based on brute-force search) require running time $e^{\Theta(\log^2 N)}$.
However algebraic algorithms such as Gaussian elimination are known to contradict a fully general statement of the above rule of thumb in certain special cases such as XOR-SAT.


Finally we note that obtaining strong low degree hardness for random search problems has been highlighted recently as a missing link in our understanding of average-case hardness.
In December 2024, it was investigated as an open problem in the American Institute of Mathematics workshop \emph{Low degree polynomial methods in average-case complexity}.
\cite{li2024some} has argued that the lack of strong low degree hardness is a major drawback in the existing OGP literature, and demonstrated that the shortest path problem on randomly weighted graphs (which of course admits efficient algorithms) exhibits an overlap gap property with probability $1-O\big(\frac{\log\log N}{\log N}\big)$.
They ask whether it is possible to ``rule out degree-$O(\log N)$ algorithms which succeed with constant probability'' in emblematic random search problems such as maximum independent set, and whether there are ``additional conditions under which we expect that OGP is a good heuristic for hardness''.
Our results give a resoundingly positive resolution to the first question, and suggest ``OGP with probability $1-N^{-\omega(1)}$'' as a tentative answer to the second.





\subsection{Proof Ideas}
\label{subsec:proof-ideas}

We prove Theorem~\ref{thm:SK-hardness-LDP} via the ensemble overlap gap property \cite{chen2019suboptimality,gamarnik2021survey}.
Following this strategy, we will construct a correlated jointly Gaussian ensemble $(H_N^{(0)},\dots,H_N^{(K)})$ of SK Hamiltonians, and suppose for sake of contradiction that $\cA$ finds a gapped state in all of them.
We then argue that these solutions cannot have intermediate distance between each other, but also that $H_N^{(K)}$ has no gapped state close to $\cA(H_N^{(0)})$.
An unusual feature of our proof is that the main OGP obstruction only applies at very small perturbation levels, but restricts the movement of $\cA$ very harshly.


An interesting conceptual difference from previous work is that we centrally use the fact that $\cA(H_N^{(i)})$ depends only on $H_N^{(i)}$.
In all OGP arguments including ours, the first step is to argue that a putative algorithm $\cA$ should be able to construct a rich constellation of solutions, either for a single Hamiltonian or for a correlated ensemble.
Previous arguments then typically prove a \emph{global landscape obstruction}: with high probability, such ensembles do not exist at all.\footnote{Both \cite{wein2020independent,bresler2021ksat} use a ``chaos'' result of a similar conditional form, but the primary ``OGP'' obstruction is global.}
By contrast we establish what might be called a \emph{conditional landscape obstruction}: for any \emph{fixed} $\cA(H_N^{(i)})\in \bSig_N$, with high conditional probability given $H_N^{(i)}$, the correlated Hamiltonian $H_N^{(j)}$ has no solutions at medium distance from $\cA(H_N^{(i)})$.
As outlined in Remark~\ref{rem:BOGP}, in principle such arguments can also be expressed as global landscape obstructions. However this requires a more complicated ensemble similar to the branching OGP, and does not simplify the proof otherwise.

As mentioned previously, the strong low degree hardness of Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-strong-conseq},\ref{it:low-degree-ultimate-conseq} comes via another, broadly applicable improvement in the analysis of the ensemble overlap gap property.
Namely a naive implementation of the argument described above requires costly union bounds over the events that $\cA$ succeeds on each instance $H_N^{(i)}$, as well as stability of $\cA$ on adjacent pairs of instances.
Such arguments cannot establish success probabilities smaller than $1-O(1/K)$.
Works including \cite{gamarnik2014limits,rahman2017independent,gamarnik2020optimization,wein2020independent} improved upon this method by establishing positive-correlation properties of the ``success'' events, or of the ``stability'' events.
% However they were not able to overcome this $1-O(1/K)$ barrier, because the ``all success'' and ``all stable'' events might be negatively correlated.
These improvements cannot be directly combined, because one cannot fruitfully union bound the ``all success'' and ``all stable'' events together.
(Indeed, \cite{gamarnik2014limits,rahman2017independent} use a positive correlation bound over ``success'' events but take a union bound over ``stability'' events, while \cite{gamarnik2020optimization,wein2020independent} do the reverse.)
We identify a new positive-correlation property which simultaneously includes both success and stability events, thus circumventing this difficulty (see Lemma~\ref{lem:grand-correlation}).
% We identify a precise choice of parameters which ensures the $i$-th ``success and stability'' event for $(H_N^{(i)},H_N^{(i+1)})$ has positive probability.
% We then argue that these events are positively correlated along the ensemble, so that they hold simultaneously with positive probability.
Unlike previous implementations of the ensemble OGP, it is crucial that our sequence of Hamiltonians forms a reversible Markov chain.
% ; this allows us to recursively bisect the ensemble and apply Jensen's inequality to each half.



Theorem~\ref{thm:langevin-fails-pseudo-wells} is proved in a somewhat different way.
Instead of varying the disorder, we vary both the initialization $\bx_0$ and driving Brownian motion $\bB_{[0,T]}$.
A first attempt is to argue that if $\bx_T$ were in a well, then the endpoint $\wt\bx_{T,i}$ of some perturbed dynamics must have different gradient norm, which would contradict known concentration properties of Langevin dynamics.
This works if one uses the stronger definition of ``well'' which requires \emph{all} eigenvalues of the Hessian $\nabla_{\sph}^2 H_N(\bx_T)$ to be smaller than $-\gamma$.
In the presence of Hessian outliers, the same argument implies that the movement of perturbed dynamics away from $\bx_T$ must align strongly with the span of the outlier eigenvectors, which is a constant-dimensional subspace.
Hence if one considers many independently perturbed dynamics, there must exist some pair $\wt\bx_{T,i}, \wt\bx_{T,j}$ of perturbed endpoints which are much closer to each other than to $\bx_T$.
However such behavior turns out to be exponentially unlikely, thanks to a monotonicity property for expected overlaps of correlated trajectories.


Finally we mention a technical step for the analysis of Langevin dynamics, which is needed to show the perturbed dynamics actually move away from $\bx_T$: if $(\bx_0,\bB_{[0,T]})$ and $(\wt\bx_0,\wt\bB_{[0,T]})$ are independent, then the corresponding pairs of dynamics (for the same $H_N$) remain approximately orthogonal on bounded time-scales.
This is proved in Lemma~\ref{lem:langevin-orthogonal}, and is the only step in our proof of Theorem~\ref{thm:langevin-fails-pseudo-wells} which requires the external field to vanish.
This requirement is necessary in the sense that Theorem~\ref{thm:langevin-fails-pseudo-wells} is false for external fields $\gamma_1^2>\xi''(1)-\xi'(1)$ above the topological trivialization threshold; here low-temperature Langevin dynamics does rapidly reach a well, namely the global optimum of $H_N$ (\cite[Section 1.4]{huang2023strong}).
The case of non-zero external field below the topological trivialization threshold is left as an interesting open question, as is the extension to a broader class of algorithms.



\subsection{Notations and Preliminaries}
\label{subsec:notation}

We will sometimes identify $H_N$ with the vector consisting of its disorder coefficients, i.e. $(g_{i,j})_{1\le i,j\le N}$ in the case of \eqref{eq:SK-def}, and $(g_{i_1,\ldots,i_k})_{2\le k\le \bar k, 1\le i_1,\ldots,i_k\le N}$ in the case of \eqref{eq:def-hamiltonian}.
We thus let $\sH_N=\bbR^{N^2}$ or $\bbR^{N^2+\dots+N^{\bar k}}$ be the state space for $H_N$.

For vectors in $\bbR^N$, we write $\|\cdot\|_2=\|\cdot\|$ for the Euclidean norm, and $\|\cdot\|_1$ for the $\ell^1$ norm.
We use $\plim$ to denote in-probability limits.

For $p\in [0,1]$ we say the centered Gaussian vector $(Z,Z_p)$ is a $p$-correlated pair if $Z$ and $Z_p$ have the same marginal law, and all $1$-dimensional projections $\la Z,v\ra, \la Z_p,v\ra$ have covariance matrix proportional to $\big(\begin{smallmatrix} 1& p\\ p& 1\end{smallmatrix}\big)$.
Similarly, we say a pair of Hamiltonians $(H_N,H_{N,p})$ is $p$-correlated if they are $p$-correlated as elements of $\sH_N$.

We will use the multivariate Hermite polynomials, which form an orthonormal basis for the space of $L^2$ functions on $\bbR^d$ relative to the standard Gaussian measure; see \cite[Chapter 11]{donnell2014analysis} for an introduction.
These polynomials are denoted $\He_{\vec\alpha}(\vec x)=\prod_{i=1}^d \He_{\alpha_i}(x_i)$ for $\alpha=(\alpha_1,\dots,\alpha_d)\in\bbZ_{\geq 0}^d$ and $\vec x\in\bbR^d$, and have degree $|\vec\alpha|_1\equiv\sum_{i=1}^d \alpha_i$.
For $\bg,\bg'\sim\cN(0,I_d)$ which are $p$-correlated, they satisfy:
\begin{align}
\label{eq:hermite-gradient}
    \partial_{x_i} \He_{\vec \alpha}(\vec x)
    &=
    \alpha_i \He_{\alpha_1,\dots,\alpha_{i-1},\alpha_i - 1,\alpha_{i+1},\dots,\alpha_d}(\vec x)
    \\
\label{eq:hermite-L2-norm}
    \implies
    \bbE[\|\nabla \He_{\vec \alpha}(\bg)\|_2^2]
    &=
    \|\vec\alpha\|_2^2
    =
    \sum_{i=1}^d \alpha_i^2\geq \|\vec\alpha\|_1;
    \\
\label{eq:hermite-correlation}
    \bbE[\He_{\vec\alpha}(\bg)\He_{\vec\alpha}(\bg')]
    &=
    p^{|\vec\alpha|}.
\end{align}

We next state a standard, useful bound on the smoothness of a mixed $p$-spin Hamiltonian (which also applies to the SK model, since except for the different domain it is a special case of spherical mixed $p$-spin).
For a tensor $\bA \in (\bbR^N)^{\otimes k}$, define the operator norm
\[
    \tnorm{\bA}_\op =
    \max_{\|\bsig^1\|_2,\ldots,\|\bsig^k\|_2\leq 1}
    |\la \bA, \bsig^1 \otimes \cdots \otimes \bsig^k \ra|\,.
\]

\begin{proposition}{\cite[Corollary 59]{arous2020geometry}}
    \label{prop:gradients-bounded}
    For any $\xi$, there exists a constant $c=c(\xi)>0$ and sequence of constants $(C_k)_{k\ge 0}$ independent of $N$ such that the following holds for all $N$ sufficiently large.
    Defining the convex set
    \[
    K_N=\lt\{H_N\in\sH_N~:~\norm{\nabla^k H_N(\bsig)}_{\op} \le C_k N^{1-\frac{k}{2}}~~~~\forall\, k\geq 0,\norm{\bsig}_2 \le \sqrt{N}\rt\}\subseteq \sH_N,
    \]
    we have $\bbP[H_N \in K_N] \ge 1-e^{-cN}$.
\end{proposition}


