On the sphere, the relevant derivatives are the Riemannian gradient and radial derivative, and the Riemannian Hessian. These are defined as follows.
For each $\bsig \in S_N$, let $\{e_1(\bsig),\ldots,e_N(\bsig)\}$ be an orthonormal basis of $\bbR^N$ with $e_1(\bsig) = \bsig / \sqrt{N}$.
Let $\cT = \{2,\ldots,N\}$.
Let $\nabla_\cT H_N(\bsig) \in \bbR^\cT$ denote the restriction of $\nabla H_N(\bsig) \in \bbR^N$ to the space spanned by $\{e_2(\bsig),\ldots,e_N(\bsig)\}$, and $\nabla^2_{\cT \times \cT} H_N(\bsig) \in \bbR^{\cT \times \cT}$ analogously.
Define the radial and tangential derivatives
\begin{equation}
\label{eq:spherical-calculus-def}
    \partial_\rd H_N(\bsig) = \lt\la e_1(\bsig), \nabla H_N(\bsig)\rt\ra, \qquad
    \nabla_\sph H_N(\bsig) = \nabla_{\cT} H_N(\bsig).
\end{equation}
Further, define the Riemannian Hessian
\begin{equation}
\label{eq:riemannian-hessian}
    \nabla^2_{\sph} H_N(\bsig) = \nabla^2_{\cT \times \cT} H_N(\bsig) - \fr{1}{\sqrt{N}} \partial_\rd H_N(\bsig) I_{\cT \times \cT}.
\end{equation}

The next standard fact concerns the Hessian of a spherical spin glass.
It shows that aside from a constant number of potential outliers, the edge eigenvalues of the Hessian are essentially determined by the radial derivative, uniformly over $\cS_N$.


\begin{lemma}[{\cite[Lemma 3]{subag2018following}}]
\label{lem:spectrum-approx}
    For any $\eps>0$ there are $K=K(\xi,\eps)$ and $\delta=\delta(\xi,\eps)>0$ such that with probability $1-e^{-cN}$, the estimate
    \[
    \big|
    \blambda_j\big(\nabla_{\sph}^2 H_N(\bsig)\big)
    -
    2\xi''(1)
    -
    \fr{1}{\sqrt{N}}
    \partial_{\rd}H_N(\bsig)
    \big|
    \leq
    \eps
    \]
    holds simultaneously for all $K\leq j\leq \delta N$ and $\bsig\in\cS_N$.
\end{lemma}





\subsection{Stability of Lipschitz and Low Degree Algorithms}
\label{subsec:stability}


Here we establish stability properties of randomly rounded Lipschitz and low degree polynomial algorithms, which are relevant for Theorem~\ref{thm:SK-hardness-LDP}.
Throughout the below, we always take $\vec U=(U_1,\dots,U_N)\stackrel{IID}{\sim}\Unif([-1,1])$ and define $\cA$ in terms of $\cA^{\circ}$ as in \eqref{eq:round-stable-alg}.
We recall the following result, which is shown by Hermite polynomial expansions and hypercontractivity.
(In translating the statements, we use that $(1-\eps)^D\geq 1-D\eps$ and $3^4\geq 6\text{e}$, and replace their $L$ by $L^4$).
Recalling the notation of $p$-correlated Gaussian processes in Subsection~\ref{subsec:notation}, below we let $(H_N,H_{N,p})$ be a $p$-correlated pair of Hamiltonians.

\begin{proposition}[{\cite[Lemma 3.4 and Theorem 3.1]{gamarnik2020optimization}}]
\label{prop:low-degree-stable-basic}
Suppose $\cA^{\circ}:\sH_N\mapsto \bbR^N$ is a deterministic degree $D$ polynomial with $\bbE[\|\cA^{\circ}(H_N)\|^2]\leq CN$.
Then:
\begin{align}
\label{eq:low-degree-l2-stable}
\bbE[\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|^2]
&\leq
2CD\eps N;
\\
\label{eq:low-degree-hypercontractive}
\bbP[\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|^2\geq 2CL^2D\eps N]
&\leq
\exp\Big(-\frac{D L^{4/D}}{10}\Big),\quad\forall\, L\geq 3^D.
\end{align}
\end{proposition}


% Note that $\mathbb E^{\vec U}[\round_{\vec U}(\bx)]=\phi(\bx)$, where $\phi(x)\equiv\min(1,\max(-1,x))$ is applied coordinate-wise.
The next easy estimate shows that randomized rounding is stable with high probability.

\begin{proposition}
\label{prop:randomized-rounding-stable}
Fix $\bx,\bx'\in\bbR^N$.
Then for any $\tau>0$:
\begin{align}
\label{eq:stability-rounding-l2}
\bbE[\|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^2]
&\leq
2\|\bx-\bx'\|\sqrt{N},
\\
\label{eq:stability-rounding-l4}
\bbE[\|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^4]
&\leq
4\|\bx-\bx'\|^2 N + 8 \|\bx-\bx'\|\sqrt{N},
\\
\label{eq:stability-rounding-high-prob}
\bbP\big[\|\round_{\vec U}(\bx)-\round_{\vec U}(\bsig')\|^2
\geq
2\|\bx-\bx'\|\sqrt{N}+\tau^2 N\big]
&\leq
e^{-\tau^4 N/100}.
\end{align}
\end{proposition}

\begin{proof}
    Let $p_i = |x_i - x'_i|/2$ and
    \[
        Y_i = \ind\{x_i \ge U_i \ge x'_i\,\text{or}\, x'_i\ge U_i\ge x_i\},
    \]
    so that $Y_i \sim \Ber(p_i)$ are mutually independent and
    \begin{equation}
    \label{eq:Y-sum}
        \|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^2 = 4(Y_1 + \cdots + Y_N).
    \end{equation}
    Then, \eqref{eq:stability-rounding-l2} follows from Cauchy--Schwarz:
    \[
        \bbE[\|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^2]
        = 4 \sum_{i=1}^N p_i
        = 2\|\bx-\bx'\|_1
        \le 2\|\bx-\bx'\|\sqrt{N}.
    \]
    Similarly, \eqref{eq:stability-rounding-l4} follows because
    \begin{align*}
        \bbE[\|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^4]
        &= 16 \lt(\sum_{i=1}^N p_i\rt)^2 + 16 \sum_{i=1}^N (p_i - p_i^2) \\
        &\le 4 \|\bx-\bx'\|_1^2 + 8\|\bx-\bx'\|_1 \\
        &\le 4 \|\bx-\bx'\|_2^2 N + 8\|\bx-\bx'\|_2 \sqrt{N}.
    \end{align*}
    Finally \eqref{eq:stability-rounding-high-prob} follows from the (one-sided) Hoeffding's inequality, because \eqref{eq:Y-sum} represents the expected squared norm $\|\round_{\vec U}(\bx)-\round_{\vec U}(\bx')\|^2$ as a sum of independent $[0,4]$-valued random variables.
\end{proof}

Combining the above estimates, we obtain high-probability stability for low degree polynomials.
We note that the quartic scaling below (as opposed to quadratic) comes from the randomized rounding.

\begin{proposition}
\label{prop:low-degree-stable}
Suppose $\cA^{\circ}:\sH_N\mapsto \bbR^N$ is a degree $D$ polynomial with $\bbE[\|\cA^{\circ}(H_N,\omega)\|^2]\leq CN$, and let $\cA(H_N,\omega,\vec U)=\round_{\vec U}(\cA^{\circ})$.
Then for all $\eps\in (0,1)$, and for $L\geq 1$ in the former and $L\geq 2\cdot 3^D$ in the latter:
\begin{align}
\label{eq:stability-of-rounded-low-degree-l2}
\bbE[\|\cA(H_N,\vec U)-\cA(H_{N,1-\eps},\vec U)\|^4]
&\leq
12 \lt(CD\eps N^2 + \sqrt{CD\eps} N\rt),
\\
\label{eq:stability-of-rounded-low-degree-hypercontractivity}
\bbP[\|\cA(H_N,\vec U)-\cA(H_{N,1-\eps},\vec U)\|/\sqrt{N}
\geq
LC^{1/4}D^{1/4}\eps^{1/4}+ \tau
]
&\leq
\exp(-DL^{4/D}/200) + e^{-\tau^4 N/2000}
.
\end{align}
\end{proposition}

\begin{proof}
    The estimate \eqref{eq:stability-of-rounded-low-degree-l2} follows from:
    \begin{align*}
        &\bbE[\|\cA(H_N,\vec U)-\cA(H_{N,1-\eps},\vec U)\|^4] \\
        &\stackrel{\eqref{eq:stability-rounding-l4}}{\le}
        4\bbE [\|\cA^\circ(H_N) - \cA^\circ(H_{N,1-\eps})\|^2] N
        + 8 \bbE [\|\cA^\circ(H_N) - \cA^\circ(H_{N,1-\eps})\|] \sqrt{N} \\
        &\stackrel{\eqref{eq:low-degree-l2-stable}}{\le} 8CD\eps N^2 + 8\sqrt{2CD\eps} N
        \le 12 \lt(CD\eps N^2 + \sqrt{CD\eps} N\rt).
    \end{align*}
    (Note that although \eqref{eq:low-degree-l2-stable} is stated for deterministic $\cA^\circ$, the result holds just as well for randomized $\cA^\circ$ because the right-hand side of \eqref{eq:low-degree-l2-stable} is linear in $CN$.)
    % First, \eqref{eq:stability-of-rounded-low-degree-l2} is immediate from \eqref{eq:stability-rounding-l2} because $\phi$ is $1$-Lipschitz.
    For \eqref{eq:stability-of-rounded-low-degree-hypercontractivity}, with probability $1 - \exp(-DL^{4/D}/10) - e^{-\tau^4 N/100}$ we have by \eqref{eq:low-degree-hypercontractive} and \eqref{eq:stability-rounding-high-prob}:
    \begin{align*}
    \|\cA(H_N,\vec U)-\cA(H_{N,1-\eps})\|^4
    &\leq
    (2\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|\sqrt{N} + \tau^2 N)^2
    \\
    &\leq
    8\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|^2 N
    +
    2\tau^4 N^2
    \\
    &\leq
    16CL^2 D\eps N^2+2\tau^4 N^2
    \\
    &\leq
    (2C^{1/4}LD^{1/4}\eps^{1/4}+ 2\tau)^4 N^2
    .
    \end{align*}
    Adjusting both constants $L$ and $\tau$ by a factor of $2$ gives the desired result.
\end{proof}

Next we show a stronger estimate when $\cA^{\circ}$ is Lipschitz.

\begin{proposition}
\label{prop:lipschitz-algs-stable}
Suppose $\cA^{\circ}:\sH_N\mapsto \bbR^N$ is $L$-Lipschitz.
Then
\begin{equation}
\label{eq:stability-of-Lipschitz}
\bbP
\lt[\|\cA(H_N,\vec U)-\cA(H_{N,1-\eps},\vec U)\|/\sqrt{N}
\geq
2L^{1/4}\eps^{1/4} + \tau
\rt]
\leq
e^{-\tau^4 N/128L^2}
+
e^{-\tau^4 N/1000}
.
\end{equation}
\end{proposition}


\begin{proof}
    We first estimate the expected distance on $\cA^{\circ}$ and then apply concentration of measure.
    Decompose
    \[
    \cA^{\circ}=\sum_{k\geq 0} \cA_k^{\circ}
    \]
    where $\cA_k^{\circ}$ is a linear combination of degree $k$ Hermite polynomials (in each of the $N$ output coordinates), and let $\alpha_k=\bbE[\|\cA_k^{\circ}(H_N)\|^2]$.
    Since $\cA^{\circ}$ is assumed $L$-Lipschitz, with $J\cA^{\circ}$ the Jacobian matrix and $\|\cdot\|_F$ the Frobenius norm we have:
    \[
    \|J\cA_k^{\circ}(H_N)\|_F\leq \|J\cA_k^{\circ}(H_N)\|_{\op}\sqrt{N}\leq L\sqrt{N}.
    \]
    (The Jacobian has smaller dimension $N$, and the operator norm is at least the maximum norm of these $N$ vectors, while the Frobenius norm is at most $N^{1/2}$ times larger.)
    Applying \eqref{eq:hermite-L2-norm} and similar relations to a random $1$-dimensional projection of $\cA^{\circ}$ and averaging shows
    \begin{align*}
    \sum_k
    \alpha_k
    &\leq
    \bbE[\|\cA_k^{\circ}(H_N)\|^2]
    \leq
    N
    ,\\
    \sum_k k^2 \alpha_k
    &=
    \bbE[\|J\cA_k^{\circ}(H_N)\|^2_F]
    \leq
    L^2 N
    \\
    \implies
    \sum_k k \alpha_k
    &\leq
    L N
    .
    \end{align*}
    Applying \eqref{eq:low-degree-l2-stable} term-by-term (the increments are orthogonal by Hermite orthogonality):
    \begin{align*}
    \bbE[\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|^2]
    \leq
    2\eps \sum_{k} k\alpha_k
    &\leq
    2L\eps N
    \\
    \bbE[\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|]
    \leq
    \sqrt{2 L\eps N}
    \end{align*}
    Next we note that $\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|$ is a $2L$-Lipschitz function in the disorder.
    Therefore
    \[
    \bbP[\|\cA^{\circ}(H_N)-\cA^{\circ}(H_{N,1-\eps})\|
    \geq
    \sqrt{2 L\eps N}
    +
    \tau^2\sqrt{N}]
    \leq
    e^{-\tau^4 N/8L^2}.
    \]
    Combining with \eqref{eq:stability-rounding-high-prob}, we see that
    \[
    \bbP
    \lt[\|\cA(H_N,\vec U)-\cA(H_{N,1-\eps},\vec U)\|^2
    \geq
    2(\sqrt{2 L\eps }+\tau^2)N +\tau^2 N
    \rt]
    \leq
    e^{-\tau^4 N/8L^2}
    +
    e^{-\tau^4 N/100}.
    \]
    Finally, noting that
    \[
    2(\sqrt{2 L\eps }+\tau^2) +\tau^2
    \leq
    (2L^{1/4}\eps^{1/4} + 2\tau)^2
    \]
    and substituting $\tau/2$ for $\tau$ finishes the proof.
\end{proof}


\section{Hardness of Finding Gapped States for the SK Model}



In this section we prove Theorem~\ref{thm:SK-hardness-LDP}\ref{it:lipschitz-alg-conseq} using a version of the ensemble overlap gap property.
In fact, we show hardness for algorithms which are stable
% new:
in the sense below,
%
with suitably high probability
% new:
$1-\punstable$.



\begin{definition}
\label{def:approx-lipschitz}
    $\cA$ is $(L,\tau,\punstable)$-stable if for all $p\in [0,1]$ and $p$-correlated $(H_N,H_{N,p})$:
    \begin{equation}
    \label{eq:stability}
    \bbP^{H_N,\omega}[\|\cA(H_N)-\cA(H_{N,p})\|/\sqrt{N}\geq
    L(1-p)^{1/4}+\tau]
    \leq \punstable.
    \end{equation}
\end{definition}


\begin{theorem}
\label{thm:SK-hardness}
For any $\gamma>0$ there exists $\delta>0$ such that the following holds.
For $0<\tau\leq \tau_0(\gamma,\delta)$ sufficiently small and any $L>0$, for $N\geq N_0(\gamma,\delta,\tau,L,\punstable)$, any $(L,\tau,\punstable)$-stable algorithm satisfies
\[
\bbP[\cA(H_N)\in S(\gamma,\delta;H_N)]\leq e^{-cN} + 2\punstable^{c}
\]
for some $c=c(\gamma,\delta,\tau,L)>0$.
\end{theorem}


Theorem~\ref{thm:SK-hardness-LDP}\ref{it:lipschitz-alg-conseq} immediately follows from Theorem~\ref{thm:SK-hardness} by applying Proposition~\ref{prop:lipschitz-algs-stable} and adjusting constants.
However Theorem~\ref{thm:SK-hardness-LDP} parts \ref{it:low-degree-strong-conseq},\ref{it:low-degree-ultimate-conseq} are \textbf{not} direct consequences since $2\punstable^{c}$ may be too large; the value of $\punstable$ guaranteed by Proposition~\ref{prop:low-degree-stable} is a decreasing function of $L$, but $c$ also depends on $L$.
The refinement needed to obtain Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-strong-conseq},\ref{it:low-degree-ultimate-conseq} is explained in the next section.


To prove Theorem~\ref{thm:SK-hardness}, we consider a jointly Gaussian sequence $(H_N^{(0)},H_N^{(1)},\dots,H_N^{(K)})$ of SK Hamiltonians in which $H_N^{(j)}$ and $H_N^{(i)}$ are $(1-\eps)^{|i-j|}$-correlated for each $i,j$.
This can be generated by a (reversible) Markov chain, where we first sample $H_N^{(0)}$, and then obtain $H_N^{(i+1)}$ from $H_N^{(i)}$ by running Ornstein--Uhlenbeck flow on its disorder coefficients for time $\log \fr{1}{1-\eps}$.

We let $K$ be a large constant (independent of $N$).
We choose $N$-independent parameters in the order:
\begin{equation}
\label{eq:parameter-ordering-SK}
0<c\ll\eps=L^{-5}\ll L^{-1}\ll \tau \ll \delta \ll \gamma < 1.
\end{equation}
This means given $\gamma$, we choose $\delta$ sufficiently small, then choose $\tau$ sufficiently small, and so on (with $N$ large depending on all of them).
For simplicity we assume $\cA=\cA(H_N)$ is stable and deterministic, and aim to show it fails to find $(\gamma,\delta)$-gapped states.
(The proof for randomized algorithms $\cA(H_N,\omega)$ requires only one slight change as explained in Remark~\ref{rmk:positive-correlation-with-rounding}.)
Given this ensemble, we will carry out the following steps:

\begin{enumerate}[label=(\alph*)]
    \item
    \label{eq:sk-step-1}
    Adjacent Hamiltonians $H_N^{(i)},H_N^{(i+1)}$ have correlation close to $1$.
    By Definition~\ref{def:approx-lipschitz}, this means a stable algorithm $\cA$ must give similar outputs on these two inputs, with high probability.
    \item
    \label{eq:sk-step-2}
    For some constant $1\leq k\leq K$, conditionally on $H_N^{(i)}$, Lemma~\ref{lem:perturbed-gapped-state-separation} shows it is overwhelmingly likely that all gapped states for $H_N^{(i+1)}, \dots, H_N^{(i+k)}$ are either extremely close to $\cA(H_N^{(i)})$, or rather far away.
    Using \ref{eq:sk-step-1}, the intermediate value theorem then implies that $\cA(H_N^{(i)})$ and $\cA(H_N^{(i+k)})$ are extremely close together.
    \item
    \label{eq:sk-step-3}
    $K/k$ is not too large. Then repeatedly applying \ref{eq:sk-step-2}, the triangle inequality shows $\cA(H_N^{(0)})$ and $\cA(H_N^{(K)})$ are relatively close together.
    \item
    \label{eq:sk-step-4}
    $H_N^{(0)},H_N^{(K)}$ have correlation close to $0$.
    By Lemma~\ref{lem:SK-chaos}, this implies that conditionally on $H_N^{(0)}$, it is very unlikely for $H_N^{(K)}$ to have a gapped state close to $\cA(H_N^{(0)})$.
    \item
    \label{eq:sk-step-5}
    The previous points together imply that it is very unlikely for $\cA$ to find a gapped state on each Hamiltonian, such that the stability guarantee of Definition~\ref{def:approx-lipschitz} holds on all adjacent pairs $H_N^{(i)},H_N^{(i+1)}$.
    Using the positive correlation statement in Lemma~\ref{lem:positive-correlation}, this allows us to conclude the main result.
\end{enumerate}

In the analysis, we will mainly use the rescaled symmetrized matrix $\bG^{\sym} = (g^{\sym}_{i,j})_{1\le i,j\le N}$ defined by:
\[
    g^{\sym}_{i,j}=\frac{(g_{i,j}+g_{j,i})\cdot 1_{i\neq j}}{\sqrt{N-1}}.
\]
With this definition, the (rescaled) local fields $\wt L_i(\bsig) = L_i(\bsig)\sqrt{\frac{N}{N-1}}$ satisfy
\begin{equation}
    \label{eq:rescaled-local-field}
    \wt L_i(\bsig)
    % =
    % L_i(\bsig)\sqrt{\frac{N}{N-1}}
    =
    \sum_{j=1}^N g^{\sym}_{i,j}\sigma_j
    =
    (\bG^{\sym}\bsig)_i.
\end{equation}
% \end{equation}
% Here
% are the entries of the rescaled symmetrization $\bG^{\sym}$.
Note that the diagonal entries $g_{i,i}$ do not appear in $\bG^{\sym}$, as they do not affect the local fields.
The slight rescaling by $\sqrt{\frac{N}{N-1}}$ makes $\wt L_i(\bsig)$ have variance exactly $2$ for each $\bsig$.
Note that except for the diagonal entries, $\bG^{\sym}$ is a Wigner matrix rescaled by $\sqrt{2 \cdot \fr{N}{N-1}}$.

\subsection{Preliminary Estimates}


% Here we prove that all gapped states for $H_N$ are separated from each other by linear Hamming distance (with high probability).
% A similar observation was made in \cite{minzer2023perfectly}, which was already noted to be suggestive of algorithmic hardness.



We will use the following simple estimates.
First, for any $I\subseteq [N]$, we let $\bG^{\sym}_{I\times I}$ be the corresponding submatrix.
Then, for $\bsig,\bsig' \in \{-1,1\}^N$ differing only on (a subset of) coordinates $I$,
\begin{equation}
\label{eq:spectral-bound-trivial}
\|(\bG^{\sym}(\bsig-\bsig'))_I\|_1
\leq
\|(\bG^{\sym}(\bsig-\bsig'))_I\|_2
\cdot \sqrt{|I|}
\leq
2\|\bG^{\sym}_{I\times I}\|_{\op} \cdot |I|.
\end{equation}
Second, for $h(p)=p\log(1/p)+(1-p)\log\lt(\frac{1}{1-p}\rt)$ the entropy, we have from \cite[Lemma 2.2]{csiszar2004information}:
\begin{equation}
\label{eq:binomial-bound}
\binom{N}{M}
\leq
e^{N h(M/N)},\quad \forall\, 1\leq M\leq N
.
\end{equation}




\begin{proposition}
\label{prop:restricted-norm-bound}
% There exists $C>0$ such that for all $q\in (0,1/2)$, with probability $1-e^{-c(q)N}$ and for $N$ sufficiently large, the matrix $\bG^{\sym}$ satisfies
There is a universal (large) constant $C_{\ref{prop:restricted-norm-bound}} > 0$ such that the following holds.
For all $q\in (0,1/2)$, there exists $c(q) > 0$ such that for $N$ sufficiently large, the matrix $\bG^{\sym}$ satisfies
\[
    \sup_{|I|\leq q N}
    \|\bG^{\sym}_{I\times I}\|_{\op}
    \leq
    C_{\ref{prop:restricted-norm-bound}} \sqrt{q\log(1/q)}.
\]
\end{proposition}

\begin{proof}
    Note that $\|\bG^{\sym}_{I'\times I'}\|_{\op}\leq \|\bG^{\sym}_{I\times I}\|_{\op}$ if $I'\subseteq I$, so it suffices to consider the supremum over $|I| = \lfloor qN \rfloor$.
    For a fixed such $I$, it is classical that $\bbE \|\bG^{\sym}_{I\times I}\|_{\op}$ is of order $O(\sqrt{q})$.
    Moreover, $\|\bG^{\sym}_{I\times I}\|_{\op}$ is a $\fr{2}{\sqrt{N-1}}$-Lipschitz function of $(\hat g_{i,j})_{1\le i<j\le N}$, where $\hat g_{i,j} = \sqrt{\fr{2}{N-1}} g^\sym_{i,j}$, and therefore is subgaussian with variance proxy $O(1/N)$.
    Union bounding over the $\binom{N}{\lfloor q N\rfloor}\leq e^{O(Nq\log(1/q))}$ possible values of $I$ concludes the proof.
\end{proof}


