\subsection{Disappearance of Gapped States for Weakly Correlated Disorder}



The next preparatory lemma gives a convenient way to decouple the local fields $L_i(\bsig)$, which are slightly correlated due to the symmetrization defining $\bG^{\sym}$, by conditioning on a noisy Gaussian observation.
This will be convenient for first moment computations.


\begin{lemma}
\label{lem:make-fields-independent}
For any $\bsig\in\{-1,1\}^N$, conditionally on $Z=\frac{\la \bsig,\bG^{\sym}\bsig\ra}{2\sqrt{N-1}}+g\sqrt{\frac{N-2}{N-1}}$ for independent standard Gaussian $g$, the entries of $\bG^{\sym}\bsig$ are IID with mean $Z/\sqrt{N-1}$ and variance $V_N=\frac{2(N-2)}{N-1}\in [1,2]$.
\end{lemma}


\begin{proof}
By the transitive $\bbZ_2^N$-symmetry of $\bSig_N$ and joint Gaussianity, it suffices to set $\bsig=\bone$ and analyze the conditional joint distribution of any two distinct entries of $\bG^{\sym}\bsig$.
We consider the centered Gaussian vector
\[
(X,Y,Z)=\lt((\bG^{\sym}\bone)_i,(\bG^{\sym}\bone)_j,\frac{\la \bone,\bG^{\sym}\bone\ra}{2\sqrt{N-1}}+g\sqrt{\frac{N-2}{N-1}}\rt).
\]
A routine computation shows that its covariance matrix is
\[
\begin{pmatrix}
    2 & \frac{2}{N-1} & \frac{2}{\sqrt{N-1}} \\
    \frac{2}{N-1} & 2 & \frac{2}{\sqrt{N-1}} \\
    \frac{2}{\sqrt{N-1}} & \frac{2}{\sqrt{N-1}} & 2
\end{pmatrix}
.
\]
An easy Gram--Schmidt computation then shows that conditionally on $Z$, the pair $\big(X-\frac{Z}{\sqrt{N-1}},Y-\frac{Z}{\sqrt{N-1}}\big)$ is IID centered Gaussian with variance $\frac{2(N-2)}{N-1}$.
\end{proof}


Next we establish a ``chaos'' property: for $p$-correlated Hamiltonians $H_N,H_{N,p}$ with $p$ away from $1$, there is no way to predict the location of any gapped state for $H_{N,p}$ based only on $H_N$.
In the next lemma, $\omega$ plays the role of the internal randomness of the algorithm $\cA$, i.e. $(\omega,\vec U)$ in \eqref{eq:round-stable-alg}.

\begin{lemma}
    \label{lem:SK-chaos}
    There is a universal (small) constant $c_{\ref{lem:SK-chaos}} > 0$ such that the following holds.
    Let $\gamma \in (0,1)$ and $p\in [0,1/2]$.
    Let $(H_N,H_{N,p})$ be $p$-correlated SK Hamiltonians and $\omega$ be any random variable independent of $(H_N,H_{N,p})$.
    Suppose a $\bsig \in \{-1,1\}^N$ is a function of $(H_N,\omega)$.
    Then, with probability $1-e^{-cN}$, there does not exist $\bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p})$ with $\|\bsig'-\bsig\| \le \sqrt{c_{\ref{lem:SK-chaos}} N}$.
\end{lemma}
\begin{proof}
    Let $\bG^{\sym}_p$ denote the symmetrized disorder matrix of $H_{N,p}$, and write
    \[
        \bG^{\sym}_p = p \bG^\sym + \sqrt{1-p^2} \wt\bG^\sym
    \]
    for $\wt\bG^\sym$ an independent copy of $\bG^\sym$.
    It is classical that $\|\bG^{\sym}\|_{\op} \le 3$ with probability $1-e^{-cN}$.
    We condition on a realization of $\bG^{\sym}$ where this holds, so that for any $\bsig' \in \{-1,+1\}^N$,
    \[
        \|\bG^{\sym} \bsig'\|^2 \le 9N.
    \]
    Thus, there are at least $N/2$ coordinates $i\in [N]$ with $|\bG^{\sym} \bsig'| \le 6$.
    Let $I_0(\bsig') \subseteq [N]$ be the set of such coordinates.

    Consider any fixed $\bsig' \in \{-1,+1\}^N$.
    We will next control the probability over $\wt\bG^{\sym}$ that $\bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p})$.
    Let $\wt Z(\bsig') = \fr{\la \bsig', \wt\bG^{\sym} \bsig' \ra}{2\sqrt{N-1}} + g\sqrt{\fr{N-2}{N-1}}$ for independent $g\sim \cN(0,1)$.
    By Lemma~\ref{lem:make-fields-independent} (with $V_N \in [1,2]$ defined therein),
    \begin{align*}
        \bG^{\sym}_p \bsig'
        &= p \bG^\sym \bsig' + \sqrt{1-p^2} (\wt\bG^\sym \bsig') \\
        &\stackrel{d}{=}
        p \bG^\sym \bsig' + \sqrt{1-p^2} \cdot \fr{\wt Z(\bsig')}{\sqrt{N-1}} \bone + \sqrt{V_N(1-p^2)} \bg,
    \end{align*}
    where $\bg \sim \cN(0,I_N)$.
    Then, (recalling \eqref{eq:rescaled-local-field}) $\bG^{\sym}_p \bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p})$ if there exists $I \subseteq [N]$ with $|I| = \lceil (1-c_{\ref{lem:SK-chaos}}) N\rceil$ such that $(\bG^{\sym}_p \bsig')_i \ge \gamma \sqrt{N/(N-1)}$ for all $i\in I$.
    Then, (conditional on $\bG^{\sym}$)
    \begin{align*}
        &\bbP(\bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p}))
        \le \bbP(|\wt Z(\bsig')| \ge \sqrt{N-1}) \\
        &\qquad + \sum_{|I| = \lceil (1-c_{\ref{lem:SK-chaos}}) N\rceil}
        \bbP\lt((\bG^{\sym}_p \bsig')_i \ge \gamma \sqrt{N/(N-1)} \,\text{for all}\, i\in I \big| |\wt Z(\bsig')| \le \sqrt{N-1}\rt)
    \end{align*}
    Then $\bbP(|\wt Z(\bsig')| \ge \sqrt{N-1}) \le e^{-N/8}$, while the last probability is bounded by
    \begin{align*}
        &\bbP\lt((\bG^{\sym}_p \bsig')_i \ge 0 \,\text{for all}\, i\in I \cap I_0(\bsig') \big| |\wt Z(\bsig')| \le \sqrt{N-1}\rt) \\
        &\le \prod_{i\in I \cap I_0(\bsig')} \bbP\lt(
            \sqrt{V_N(1-p^2)} g_i \ge -6p - \sqrt{1-p^2}
        \rt)
        \le \Psi\lt(-2\sqrt{3} - 1\rt)^{|I\cap I_0(\bsig')|},
    \end{align*}
    where $\Psi$ is the complementary gaussian CDF.
    If we set $c_{\ref{lem:SK-chaos}} \le 1/4$, then $|I \cap I_0(\bsig')| \ge N/4$.
    Thus,
    \[
        \bbP(\bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p}))
        \le e^{-N/8} + \binom{N}{\lfloor c_{\ref{lem:SK-chaos}} N\rfloor} \Psi\lt(-2\sqrt{3} - 1\rt)^{N/4}.
    \]
    Finally, the binomial coefficient and the number of $\bsig' \in \{-1,1\}^N$ such that $\|\bsig'-\bsig\| \le \sqrt{c_{\ref{lem:SK-chaos}} N}$ are both $e^{O(c_{\ref{lem:SK-chaos}} \log (1/c_{\ref{lem:SK-chaos}})) N}$.
    Union bounding over such $\bsig'$ yields
    \[
        \bbP(\exists\,\bsig' \in S(\gamma,c_{\ref{lem:SK-chaos}};H_{N,p})\,\text{with}\,\|\bsig-\bsig'\| \le \sqrt{c_{\ref{lem:SK-chaos}} N})
        \le e^{O(c_{\ref{lem:SK-chaos}} \log (1/c_{\ref{lem:SK-chaos}})) N} \lt( e^{-N/8} + \Psi\lt(-2\sqrt{3} - 1\rt)^{N/4}\rt).
    \]
    This is exponentially small if $c_{\ref{lem:SK-chaos}}$ is a sufficiently small universal constant.
\end{proof}

