\subsection{Main Argument}



We now turn to the main arguments toward Theorem~\ref{thm:SK-hardness}.
The following lemma shows a form of the overlap gap property for pairs of Hamiltonians with large correlation $p\approx 1$.
Informally, if $\bsig$ is a \emph{fixed} gapped state of $H_N$, we show that with high probability all gapped states of $H_{N,p}$ are either extremely close to $\bsig$, or are rather far away.
Crucially, ``extremely close'' can be taken to be exponentially small in $(1-p)^{-1}$ (see the lower endpoint of the interval in \eqref{eq:perturbed-gapped-state-separation} below).
By taking the correlation strength between adjacent Hamiltonians in our sequence very close to $1$, this implies that a hypothetical stable algorithm finding gapped states is unable to move macroscopic distances, contradicting Lemma~\ref{lem:SK-chaos} above.

\begin{lemma}
    \label{lem:perturbed-gapped-state-separation}
    There exists a (large) universal constant $C_{\ref{lem:perturbed-gapped-state-separation}}$ such that, for any $\gamma \in (0,1)$, there exists a (small) $c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma) > 0$ such that the following holds for any $\delta \in (0,\min(\gamma,1/2))$ and $p \in [1/2,1]$.
    Let $(H_N,H_{N,p})$ be a pair of $p$-correlated SK Hamiltonians.
    Let $\bsig \in S(\gamma,\delta,H_N)$ be conditionally independent of $H_{N,p}$ given $H_N$.
    Finally, let
    \begin{align*}
        r_1 = r_1(\gamma,p) &= \exp\lt(-\fr{\gamma^2}{C_{\ref{lem:perturbed-gapped-state-separation}} (1-p)}\rt), &
        r_2 = r_2(\gamma,\delta) &= \fr{C_{\ref{lem:perturbed-gapped-state-separation}} (\delta \log(1/\delta))^{1/4}}{\gamma^{1/2}}.
    \end{align*}
    With probability $1-e^{-cN}$, there does not exist $\bsig' \in S(\gamma,\delta;H_{N,p})$ such that
    \begin{equation}
        \label{eq:perturbed-gapped-state-separation}
        \|\bsig-\bsig'\|/\sqrt{N} \in [\max(r_1,r_2), c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)].
    \end{equation}
\end{lemma}
We first prove a preparatory lemma, which bounds the total $L^1$ violation of the gappedness constraint.
\begin{lemma}
    \label{lem:l1-error-sum}
    With probability $1-e^{-cN}$ over an SK Hamiltonian $H_N$, the following holds for all $\gamma \in (0,1)$, $\delta > 0$.
    For all $\bsig \in S(\gamma,\delta;H_N)$, we have
    \[
        \sum_{i=1}^N (\gamma - (\bG^\sym \bsig)_i \bsig_i)_+ \le 4\sqrt{\delta} N.
    \]
\end{lemma}
\begin{proof}
    Let $J \subseteq [N]$ be the set of coordinates where $(\bG^\sym \bsig)_i \bsig_i < \gamma$, so that by definition $|J| \le \delta N$.
    Then, proceeding similarly to \eqref{eq:spectral-bound-trivial},
    \begin{align*}
        \sum_{i=1}^N (\gamma - (\bG^\sym \bsig)_i \bsig_i)_+
        &\le \gamma \delta
        + \|(\bG^\sym \bsig)_J\|_1 \\
        &\le \gamma |J|
        + \|(\bG^\sym \bsig)_J\|_2 \sqrt{|J|}
        \le \gamma |J|
        + \|\bG^\sym\|_{\op} \sqrt{|J|N}.
    \end{align*}
    With probability $1-e^{-cN}$, $\|\bG^\sym\|_{\op} \le 3$ and the result follows.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:perturbed-gapped-state-separation}]
    We condition on $H_N$ satisfying Lemma~\ref{lem:l1-error-sum}, and will bound the expected number of $\bsig' \in S(\gamma,\delta;H_{N,p})$ satisfying \eqref{eq:perturbed-gapped-state-separation}.
    To this end, we fix a $\bsig' \in \{-1,1\}^N$ satisfying \eqref{eq:perturbed-gapped-state-separation} and will control the (conditional on $H_N$) probability of $\bsig' \in S(\gamma,\delta;H_{N,p}))$.

    Let $I = I(\bsig,\bsig')\subseteq [N]$ denote the set of coordinates on which $\bsig,\bsig'$ disagree.
    Let $\eta = |I| / N = 4\|\bsig-\bsig'\|^2/N$, so that \eqref{eq:perturbed-gapped-state-separation} implies
    \begin{equation}
        \label{eq:eta-range}
        \eta \in [\max(4r_1^2,4r_2^2),4c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)^2].
    \end{equation}
    Let us abbreviate $\gamma_N = \gamma \sqrt{N/(N-1)}$.
    Note that
    \begin{align}
        \notag
        \sum_{i\in I} (\gamma_N + (\bG^\sym \bsig')_i \bsig'_i)_+
        &\le \sum_{i\in I} (\gamma_N + (\bG^\sym \bsig)_i \bsig'_i)_+ + \|(\bG^{\sym}(\bsig-\bsig'))_I\|_{L^1} \\
        \notag
        &= \sum_{i\in I} (\gamma_N - (\bG^\sym \bsig)_i \bsig_i)_+ + \|(\bG^{\sym}(\bsig-\bsig'))_I\|_{L^1} \\
        \label{eq:l1-error-sum-bound}
        &\le \lt(4\sqrt{\delta} + 2 C_{\ref{prop:restricted-norm-bound}}  \sqrt{\eta^3 \log (1/\eta)}\rt) N,
    \end{align}
    where we have bounded the first term using Lemma~\ref{lem:l1-error-sum}, and the second by \eqref{eq:spectral-bound-trivial} combined with Proposition~\ref{prop:restricted-norm-bound}.
    We set $C_{\ref{lem:perturbed-gapped-state-separation}}$ large enough and $c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)$ small enough such that the bounds $\eta \ge 4r_2^2$ and $\eta \le 4c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)^2$ imply (respectively)
    \[
        4\sqrt{\delta}, 2 C_{\ref{prop:restricted-norm-bound}}  \sqrt{\eta^3 \log (1/\eta)}
        \le \eta \gamma / 4
        \le \eta \gamma_N / 4.
    \]
    Thus \eqref{eq:l1-error-sum-bound} is bounded by $\eta \gamma_N/2$.
    So, there exist at least $\eta N / 2$ coordinates $i\in I$ such that
    \[
        (\gamma_N + (\bG^\sym \bsig')_i \bsig'_i)_+ \le \gamma_N,
    \]
    i.e. $(\bG^\sym \bsig')_i \bsig'_i \le 0$.
    Let $J\subseteq I$ be a set of such coordinates, with $|J| = \lfloor \eta N / 2\rfloor$.

    Next, let $\bG^{\sym}_p$ denote the symmetrized disorder matrix of $H_{N,p}$, and write $\bG^{\sym}_p = p \bG^\sym + \sqrt{1-p^2} \wt\bG^\sym$ as above.
    Then, for $i\in J$,
    \[
        (\bG^{\sym}_p \bsig')_i \bsig'_i
        \le \sqrt{1-p^2} (\wt \bG^{\sym}_p \bsig')_i \bsig'_i.
    \]
    Since $\bsig' \in S(\gamma,\delta;H_{N,p})$, there must exist $J' \subseteq J$ of size $|J'| = |J| - \lfloor \delta N \rfloor$, such that for all $i\in J'$,
    \[
        \sqrt{1-p^2}
        (\wt \bG^\sym \bsig')_i \bsig'_i
        \ge \gamma_N.
    \]
    Let $\wt Z(\bsig') = \fr{\la \bsig', \wt\bG^{\sym} \bsig' \ra}{2\sqrt{N-1}} + g\sqrt{\fr{N-2}{N-1}}$ for independent $g\sim \cN(0,1)$.
    Then, by Lemma~\ref{lem:make-fields-independent}, (for $V_N \in [1,2]$ defind therein)
    \[
        \wt \bG^\sym \bsig' \stackrel{d}{=} \fr{\wt Z(\bsig')}{\sqrt{N-1}} \bone + \sqrt{V_N} \bg
    \]
    for $\bg \sim \cN(0,I_N)$.
    Thus,
    \begin{align}
        \notag
        &\bbP(\bsig' \in S(\gamma,\delta;H_{N,p}))
        \le \bbP(\wt Z(\bsig') > \gamma_N \sqrt{N-1} / 2) \\
        \label{eq:ogp-prob-bsig-prime-gapped}
        &\qquad + \sum_{\substack{J' \subseteq J \\ |J'| = |J| - \lfloor \delta N \rfloor}}
        \bbP\lt(
            \sqrt{1-p^2}
            (\wt \bG^\sym \bsig')_i \bsig'_i
            \ge \gamma_N\,\forall\, i\in J'\,\,
            \big| \,\,
            \wt Z(\bsig') \le \gamma_N \sqrt{N-1} / 2
        \rt)
    \end{align}
    Then $\bbP(\wt Z(\bsig') > \gamma_N \sqrt{N-1} / 2) \le e^{-\gamma^2 N/16}$, while the last probability is bounded by
    \[
        \bbP\lt(\sqrt{(1-p^2) V_N} \bg_i \ge \gamma_N / 2 \,\forall\, i\in J'\rt)
        \le \exp\lt(-\fr{|J'| \gamma_N^2}{8 (1-p^2) V_N}\rt)
        \le \exp\lt(-\fr{|J'| \gamma^2}{32 (1-p)}\rt).
    \]
    Plugging into \eqref{eq:ogp-prob-bsig-prime-gapped}, and further taking a union bound over $\bsig'$ satisfying $I(\bsig,\bsig') = \eta N$, we find
    \[
        \bbE|\{\bsig' \in S(\gamma,\delta;H_{N,p}) : I(\bsig,\bsig') = \eta N\}|
        \le \binom{N}{\eta N} \lt(
            e^{-\gamma^2N/16}
            + \binom{|J|}{\lfloor \delta N \rfloor}
            \exp\lt(-\fr{|J'| \gamma^2}{32 (1-p)}\rt)
        \rt)
    \]
    By setting $c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)$ small enough, we can ensure that for $\eta \le 4c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)^2$,
    \[
        \binom{N}{\eta N}
        e^{-\gamma^2N/16}
        \stackrel{\eqref{eq:binomial-bound}}{\le}
        \exp\lt(
            O(\eta \log (1/\eta)) N - \gamma^2 N/16
        \rt)
        \le e^{-cN}.
    \]
    By setting $C_{\ref{lem:perturbed-gapped-state-separation}}$ large enough, we can ensure that for $\eta \ge 4r_2^2$, we have $\delta \le \eta/8$.
    Thus
    \[
        |J'| = |J| - \lfloor \delta N \rfloor
        = \lfloor \eta N / 2\rfloor - \lfloor \delta N \rfloor
        \ge \eta N / 4.
    \]
    Consequently
    \[
        \binom{N}{\eta N}
        \binom{|J|}{\lfloor \delta N \rfloor}
        \exp\lt(-\fr{|J'| \gamma^2}{32 (1-p)}\rt)
        \stackrel{\eqref{eq:binomial-bound}}{\le}
        \exp\lt(
            O(\eta \log (1/\eta)) N
            + O(\delta \log (\eta/\delta)) N
            - \fr{\eta \gamma^2 N}{128(1-p)}
        \rt)
    \]
    Since $\eta \ge 4r_1^2, 4r_2^2$, setting $C_{\ref{lem:perturbed-gapped-state-separation}}$ large enough ensures this is $e^{-cN}$.
    It follows that
    \[
        \bbE|\{\bsig' \in S(\gamma,\delta;H_{N,p}) : I(\bsig,\bsig') = \eta N\}| = e^{-cN}.
    \]
    Taking a final union bound over $\eta$ in the range \eqref{eq:eta-range} (which are multiples of $1/N$) completes the proof.
\end{proof}




