The next lemma gives a positive correlation property which allows us to avoid union-bounding over success events for $\cA$.
Here, the set $S$ plays the role of the event $\cA(H_N,\omega,\vec U) \in S(\gamma,\delta;H_N)$ (see Remark~\ref{rmk:positive-correlation-with-rounding} below for how to handle the auxiliary randomness $(\omega,\vec U)$).
Recall that we study the correlated ensemble $H_N=H_N^{(0)},H_N^{(1)},\dots,H_N^{(K)}$, where $H_N^{(j)}$ and $H_N^{(i)}$ are $(1-\eps)^{|i-j|}$-correlated.
% We note that the result essentially extends to all stationary reversible Markov chains $(Z_1,Z_2,\dots,Z_k)$.
% (The proof requires the construction of a coupling $(Z_i,Z_{i+1},Y)$ with an auxiliary random variable $Y$ such that $Z_i,Z_{i+1}$ are conditionally IID given $Y$, but we later


\begin{lemma}
\label{lem:positive-correlation}
    Let $j = \lfloor \log_2 K \rfloor$.
    For any set $S\subseteq\sH_N$ of SK Hamiltonians with $\bbP[H_N\in S]=q$, we have
    \[
        \bbP[H_N^{(i)}\in S\quad\forall\, 0\leq i\leq K]\geq
        q^{2^{j+1}} \ge q^{4K}.
    \]
\end{lemma}

\begin{proof}
    We induct on $j$.
    For the base case $j=0$ (i.e. $K=1$), we write
    \begin{align*}
        H_N^{(0)} &= \sqrt{1-\eps} \overline H_N + \sqrt{\eps} \wt H_N^{(0)}, &
        H_N^{(1)} &= \sqrt{1-\eps} \overline H_N + \sqrt{\eps} \wt H_N^{(1)},
    \end{align*}
    for IID copies $\overline H_N, \wt H_N^{(0)}, \wt H_N^{(1)}$ of $H_N$.
    Since $H_N^{(0)}$ and $H_N^{(1)}$ are conditionally independent given $\overline H_N$,
    \[
        \bbP(H_N^{(0)},H_N^{(1)} \in S)
        = \bbE\lt[\bbP(H_N^{(0)} \in S | \overline H_N)^2 \rt]
        \ge \bbE\lt[\bbP(H_N^{(0)} \in S | \overline H_N) \rt]^2
        = q^2,
    \]
    using Jensen's inequality.
    For the inductive step, define
    \begin{align*}
        Q_j &\equiv \bbP[H_N^{(i)}\in S\quad\forall\, 0\leq i\leq 2^j], &
        Q_j(H_N^{(0)}) &\equiv \bbP[H_N^{(i)}\in S\quad\forall\, 0\leq i\leq 2^j | H_N^{(0)} ].
    \end{align*}
    By reversibility of the Hamiltonian ensemble, the sequences
    \[
        (H^{(0)},H^{(1)},\ldots,H^{(2^j)}),
        (H^{(2^{j+1})},H^{(2^{j+1}-1)},\ldots,H^{(2^j)})
    \]
    are conditionally IID given $H^{(2^j)}$.
    By the tower rule of conditional expectations and another application of Jensen's inequality,
    \[
        Q_{j+1}
        = \bbE[\bbP[H_N^{(i)}\in S\quad\forall\, 0\leq i\leq 2^{j+1} | H_N^{(2^j)}]]
        = \bbE[Q_j(H_N^{(2^j)})^2]
        \ge \bbE[Q_j(H_N^{(2^j)})]^2
        = Q_j^2.
    \]
    This completes the induction.
    % To show the result for $j+1$, let $Z'$ be an IID Gaussian variable $Z$, we condition on
    % \[
    % \wh H_N=H_N^{(2^j)}+H_N^{(2^j+1)}+\alpha Z'
    % \]
    % Then the entry-wise correlations between $(H_N^{(i)},H_N^{(i+1)},\wh H_N)$ are:
    % \[
    % \begin{pmatrix}
