\begin{remark}
\label{rmk:positive-correlation-with-rounding}
    Lemma~\ref{lem:positive-correlation} extends to the setting in which there is an auxiliary independent random variable $\omega \in \Omega_N$ which is shared across the correlated Hamiltonians, and the success event is a set $S\subseteq \sH_N\times\Omega_N$.
    Namely, define
    \begin{align*}
        q &\equiv \bbP[(H_N^{(0)},\omega) \in S], &
        Q_j &\equiv \bbP[(H_N^{(i)},\omega) \in S \quad \forall\, 0\le i\le 2^j], \\
        q(\omega) &\equiv \bbP[(H_N^{(0)},\omega) \in S | \omega], &
        Q_j(\omega) &\equiv \bbP[(H_N^{(i)},\omega) \in S \quad \forall\, 0\le i\le 2^j | \omega].
    \end{align*}
    Then Lemma~\ref{lem:positive-correlation} implies that for all $\omega$, $Q_j(\omega) \ge q(\omega)^{2^{j+1}}$.
    By Jensen's inequality,
    \[
        Q_j = \bbE[Q_j(\omega)]
        \ge \bbE[q(\omega)^{2^{j+1}}]
        \ge \bbE[q(\omega)]^{2^{j+1}}
        = q^{2^{j+1}}.
    \]
    % Namely one has with the obvious definitions that $Q_j(\omega)\geq q(\omega)^{2^j}$, which by Jensen's inequality implies
    % \[
    % Q_j
    % =
    % \bbE^{\omega}[Q_j(\omega)]
    % \geq
    % (\bbE[q(\omega)])^{2^j}
    % =
    % q^{2^j}.
    % \]
    Using this slightly generalized Lemma~\ref{lem:positive-correlation}, the remainder of this section goes through without modification when $\cA$ depends also on independent auxiliary randomness $(\omega,\vec U)$.
\end{remark}

\subsection{Proof of Theorem~\ref{thm:SK-hardness}}

In the below proof, we always set the parameters $\delta,\tau,L,\eps$ in the order \eqref{eq:parameter-ordering-SK}, i.e. $\delta$ will be taken sufficiently small in terms of $\gamma$, and so on.
Note that for fixed $\gamma$, the value $r_2(\gamma,\delta)$ defined in Lemma~\ref{lem:perturbed-gapped-state-separation} tends to $0$ as $\delta \to 0$, so by taking $\delta$ small enough we can ensure $r_2(\gamma,\delta) \le c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)/2$ and $r_2(\gamma,\delta) \le r_1(\gamma,p=1/2)$.

Since $r_1(\gamma,p)$ is decreasing in $p$, there exists a unique $p_c = p_c(\gamma,\delta) \in [1/2,1]$ such that $r_1(\gamma,p_c) = r_2(\gamma,\delta)$.
Further, let $k = \lfloor \log p_c / \log(1-\eps) \rfloor$, so that $k$ is the largest integer such that $(1-\eps)^k \ge p_c$.
It is clear that
\begin{align*}
    1-p_c &\asymp \fr{\gamma^2}{\log(1/\delta)}, &
    k &\asymp \fr{\gamma^2}{\eps \log(1/\delta)}.
\end{align*}
Finally let $K = \lceil 1/\eps \rceil$.
Consider an ensemble of Hamiltonians $H_N^{(0)},\ldots,H_N^{(K)}$ where $H_N^{(i)},H_N^{(j)}$ are $(1-\eps)^{|i-j|}$-correlated, and let $(\omega,\vec U)$ be a sample of the auxiliary randomness of $\cA$.
For $0\le i\le K$, let $\bsig^{(i)} = \cA(H_N^{(i)},\omega,\vec U)$, and note that the $(\omega,\vec U)$ are shared across all $H^{(i)}$.
We now define several events:
\begin{align}
    \label{eq:ssolve-v1}
    \Ssolve &= \lt\{
        \bsig^{(i)} \in S(\gamma,\delta; H_N^{(i)}) \qquad \forall\, 0\le i\le K
    \rt\}, \\
    \Sstable &= \lt\{
        \|\bsig^{(i+1)} - \bsig^{(i)}\|/\sqrt{N}
        \leq
        L\eps^{1/4} + \tau,\quad\forall\, 0\leq 1\leq K-1
    \rt\}, \\
    \Schaos &= \lt\{
        \text{there does not exist $\bsig'\in S(\gamma,\delta; H_N^{(K)})$ such that $\|\bsig'-\bsig^{(0)}\| \le \sqrt{c_{\ref{lem:SK-chaos}} N}$}
    \rt\} \\
    \label{eq:sogp-v1}
    \Sogp &= \lt\{
        \begin{array}{l}
            \text{for all $0\le i\le j\le K$ with $|i-j| \le k$, there does not exist} \\
            \text{$\bsig' \in S(\gamma,\delta; H_N^{(j)})$ such that $\|\bsig'-\bsig^{(i)}\| / \sqrt{N} \in [r_2(\gamma,\delta),c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)]$}
        \end{array}
    \rt\}
\end{align}

\begin{lemma}
    \label{lem:no-intersection}
    We have $\Ssolve \cap \Sstable \cap \Schaos \cap \Sogp = \emptyset$.
\end{lemma}
\begin{proof}
    Suppose $\Ssolve \cap \Sstable \cap \Sogp$ holds.
    We will show this contradicts $\Schaos$.

    First, consider any $0\le i\le j\le K$ with $|i-j| \le k$.
    We will show that
    \begin{equation}
        \label{eq:low-movement-in-k}
        \|\bsig^{(i)} - \bsig^{(j)}\| / \sqrt{N} \le r_2(\gamma,\delta).
    \end{equation}
    By $\Ssolve$ and $\Sogp$, for any $\ell$ such that $i\le \ell \le j$,
    \[
        \|\bsig^{(i)} - \bsig^{(\ell)}\| / \sqrt{N}
        \not\in [c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma) / 2 , c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)]
        \subseteq
        [r_2(\gamma,\delta),c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)],
    \]
    where we recall that we set $r_2(\gamma,\delta)\le c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)/2$.
    We set $\tau,L,\eps=L^{-5}$ such that $L\eps^{1/4} + \tau \le c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)/2$.
    Then $\|\bsig^{(i)} - \bsig^{(\ell)}\| / \sqrt{N}$ and $\|\bsig^{(i)} - \bsig^{(\ell+1)}\| / \sqrt{N}$ can never be on opposite sides of $[c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)/2,c_{\ref{lem:perturbed-gapped-state-separation}}(\gamma)]$, proving \eqref{eq:low-movement-in-k}.
    Let $T = \lceil K/k\rceil \asymp \gamma^2 / \log(1/\delta)$.
    Then
    \[
        \|\bsig^{(0)} - \bsig^{(K)}\|
        \le \sum_{t=0}^{T-2} \|\bsig^{(tk)} - \bsig^{((t+1)k)}\|
        + \|\bsig^{((T-1)k)} - \bsig^{(K)}\|
        \le Tr_2(\gamma,\delta) \sqrt{N}
        \asymp \fr{\gamma^{3/2} \delta^{1/4}}{\log(1/\delta)^{3/4}} \sqrt{N}.
    \]
    For sufficiently small $\delta$ (depending on $\gamma$), this is less than $c_{\ref{lem:SK-chaos}} \sqrt{N}$.
    Then $\bsig^{(K)} \in S(\gamma,\delta; H_N^{(K)})$ and $\|\bsig{(K)}-\bsig^{(0)}\| \le \sqrt{c_{\ref{lem:SK-chaos}} N}$, contradicting $\Schaos$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:SK-hardness}]
    Let $q = \bbP(\cA(H_N,\omega,\vec U) \in S(\gamma,\delta; H_N))$ be the probability that $\cA$ succeeds on one Hamiltonian.
    By Lemma~\ref{lem:positive-correlation} (in combination with Remark~\ref{rmk:positive-correlation-with-rounding}), we have $\bbP[\Ssolve] \ge q^{4K}$.

    Recall $\punstable$ from Definition~\ref{def:approx-lipschitz}.
    By a union bound, $\bbP[\Sstable] \ge 1-K\punstable$.

    The correlation between $H_N^{(0)}$ and $H_N^{(K)}$ is $(1-\eps)^K = (1-\eps)^{\lceil 1/\eps \rceil} = e^{-1} + O(\eps) \le 1/2$.
    Thus, Lemma~\ref{lem:SK-chaos} implies $\bbP[\Schaos] \ge 1-e^{-cN}$.

    For any $|i-j| \le k$, the correlation between $H_N^{(i)}$ and $H_N^{(j)}$ is $p_{i,j} \equiv (1-\eps)^{|i-j|} \ge (1-\eps)^k \ge p_c$.
    Thus $r_1(\gamma,p_{i,j}) \le r_1(\gamma,p_c) = r_2(\gamma,\delta)$.
    By Lemma~\ref{lem:perturbed-gapped-state-separation}, the event in $\Sogp$ for this particular $(i,j)$ holds with probability $1-e^{-cN}$.
    By a union bound over these $(i,j)$, $\bbP[\Sogp] \ge 1-e^{-cN}$.
    However, by Lemma~\ref{lem:no-intersection},
    \[
        \bbP[\Ssolve] + \bbP[\Sstable] + \bbP[\Schaos] + \bbP[\Sogp] \le 3.
    \]
    It follows that
    \[
    q
    \le
    (e^{-cN} + K\punstable)^{1/4K}
    \leq
    e^{-cN/4K}+K^{1/4K}\punstable^{1/4K}
    \leq
    e^{-cN/4K}+2\punstable^{1/4K}
    .
    \]
    This implies the result after adjusting $c$.
\end{proof}

