\begin{remark}
\label{rem:BOGP}
As previously alluded to, the above argument can be phrased using a version of the branching overlap gap property.
This gives a ``global landscape obstruction'' that does not directly rely on the fact that $\cA(H_N)$ does not depend on the other Hamiltonians in the ensemble.
Namely, one can fix another large constant $W$ and consider not $K+1$ interpolated Hamiltonians but $1+W+\dots+W^K$ of them, indexed by the rooted tree $\bbT\equiv [W]^0 \cup [W]^1 \cup\dots\cup [W]^K$, with root Hamiltonian denoted $H_N^{\emptyset}$.
For each $1\leq k\leq K$ and $v\in [W]^k$, given $H_N^{(v)}$ we let $H_N^{(v1)},\dots,H_N^{(vK)}$ be conditionally independent Hamiltonians which are $1-\eps$-correlated with $H_N^{(v)}$.
Using Jensen's inequality as in \cite[Proof of Proposition 3.6(a)]{huang2021tight}, one can extend Lemma~\ref{lem:positive-correlation} to this ensemble, showing that if $\cA$ finds a gapped state with probability $q$, then it finds a gapped state on all these Hamiltonians simultaneously with probability at least $q^{4K|\bbT|}$.
From this it suffices to show that with exponentially good probability over the disorder, no ensemble of gapped states $(\bsig^{(v)})_{v\in\bbT}$ is such that the stability estimate of Definition~\ref{def:approx-lipschitz} applies to every pair $(v,v')$ such that $v$ is an ancestor of $v'$ in $\bbT$.


In the proof of Theorem~\ref{thm:SK-hardness}, we used both Lemma~\ref{lem:SK-chaos} and Lemma~\ref{lem:perturbed-gapped-state-separation} which crucially relied on the fact that $\cA(H_N^{(k)})$ depends only on $H_N^{(k)}$, and held with probability $1-e^{-cN}$.
We take $W$ large depending on this $c$.
Let us say $w\in W$ is \emph{nice} for some $\bsig\in S(\gamma,\delta;H_N^{\emptyset})$ if Lemma~\ref{lem:SK-chaos} holds for $H_N^{\emptyset}$ and $H_N^{(v)}$ for \emph{every} leaf $v\in [W]^K$ of $\bbT$ with first digit $w$.
Then for each $\bsig\in S(\gamma,\delta;H_N^{\emptyset})$, the probability that fewer than $2W/3$ digits $w$ are nice for $\bsig$ is at most
\[
2^{N+W} e^{-cWN/3}\leq 2^{-N}.
\]
Therefore with high probability over the ensemble, all $\bsig\in S(\gamma,\delta;H_N^{\emptyset})$ have at least $2W/3$ nice digits $w$.


Next let us say a correlated pair $(H_N,H_N')$ is \emph{good} with respect to $\bsig\in\bSig_N$ if the conclusion of Lemma~\ref{lem:perturbed-gapped-state-separation} holds for it in both directions, with $\bsig$ replacing $\cA(H_N)$ in one case and $\cA(H_N')$ in the other.
Because $W$ is large depending on $c$, we similarly find that the following holds with probability at least $1-e^{-N}$: for every $v\in [W]^0 \cup \dots\cup [W]^{K-1}$ and $\bsig\in\bSig_N$, there exist at least $2W/3$ digits $i\in [W]$ such that $(H_N^{(v)},H_N^{(u)})$ is a good pair with respect to $\bsig$, for all $u$ with initial substring $vi$ (i.e.\ for $H_N^{(vi)}$ and all its descendants).
This implies that for any given sequence $(\bsig^{\emptyset},\dots,\bsig^{(K)})\in \bSig_N^{K+1}$, there exists a root-to-leaf path in $\bbT$ to some $v_*\in [W]^K$ such that all pairs of Hamiltonians along the path are good relative to their corresponding $\bsig^{(i)}$, and such that Lemma~\ref{lem:SK-chaos} holds for $(H_N^{\emptyset},H_N^{(v_*)},\bsig^{(0)})$ and $(H_N^{(v_*)},H_N^{\emptyset},\bsig^{(K)})$.
Our preceding proof of Theorem~\ref{thm:SK-hardness} can then be applied along said path to obtain a contradiction.


We finally mention that despite the close similarity, the correlation structure in the branching ensemble of Hamiltonians described above differs from the one used in \cite{huang2021tight,huang2023algorithmic}, in the same way that an Ornstein--Uhlenbeck process differs from a Brownian motion.
\end{remark}


\section{Extension to Strong Low Degree Hardness}
\label{sec:low-degree}


In this section we prove Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-strong-conseq}, and explain how to improve several prior applications of the ensemble OGP to strong low degree hardness.
The central tool is an upgrade of Lemma~\ref{lem:positive-correlation} which simultaneously handles success and stability events, and thus avoids any need for $K$-fold union bounds along the ensemble.
(By contrast, we used the simple estimate $\bbP[\Sstable] \ge 1-K\punstable$ in proving Theorem~\ref{thm:SK-hardness}.)
Like before, let $H_N^{(0)},\ldots,H_N^{(K)}$ be an ensemble of Hamiltonians where $H_N^{(i)},H_N^{(j)}$ are $(1-\eps)^{|i-j|}$-correlated, and $(\omega,\vec U)$ be the auxiliary randomness of $\cA$.
Let
\begin{align*}
    \Ssolve(i)
    &\equiv
    \{\cA(H_N^{(i)},\omega,\vec U) \in S(\gamma,\delta;H_N^{(i)})\}, \\
    \Sstab(i)
    &\equiv
    \{\|\cA(H_N^{(i)},\omega,\vec U)-\cA(H_N^{(i+1)},\omega,\vec U)\|/\sqrt{N}
    \leq
    L\eps^{1/4}+\tau\}.
\end{align*}
Then define the ``success and stability'' event
\[
    \Sall(K) = \Big(\bigcap_{i=0}^K \Ssolve(i)\Big) \cap \Big(\bigcap_{i=0}^{K-1} \Sstab(i)\Big).
\]
The following elementary correlation inequality is the crux of our improved ensemble OGP.
\begin{lemma}
    \label{lem:grand-correlation}
    Let $\psolve=\bbP[\Ssolve(0)]$ and $\punstable = 1 - \bbP[\Sstab(0)]$.
    Then, for $j = \lfloor \log_2 K \rfloor$,
    \[
        \bbP[\Sall(K)]
        \geq (\psolve^2-\punstable)_+^{2^j}
        \geq (\psolve^2-\punstable)_+^{2K}.
    \]
\end{lemma}
\begin{proof}
    We first prove the statement for a deterministic function $\cA(H_N,\omega,\vec U) = \cA(H_N)$.
    The auxiliary randomness $(\omega,\vec U)$ can be addressed similarly to Remark~\ref{rmk:positive-correlation-with-rounding}.
    We will again induct on $j$.
    For the base case $j=0$ (i.e. $K=1$), we recall from the base case in Lemma~\ref{lem:positive-correlation} that
    \[
        \bbP(\Ssolve(0) \cap \Ssolve(1)) \ge \psolve^2.
    \]
    It follows that
    \[
        \bbP[\Sall(1)] \ge \psolve^2 - \punstable.
    \]
    We now proceed as in the proof of Lemma~\ref{lem:positive-correlation}.
    Let
    \begin{align*}
        Q_j &\equiv \bbP[\Ssolve(i)\,\,\forall\, 0\leq i\leq 2^j\,\text{and}\,\Sstab(i)\,\,\forall 0\le i\le 2^j-1], \\
        Q_j(H_N^{(0)}) &\equiv \bbP[\Ssolve(i)\,\,\forall\, 0\leq i\leq 2^j\,\text{and}\,\Sstab(i)\,\,\forall 0\le i\le 2^j-1 | H_N^{(0)} ].
    \end{align*}
    Recall that the sequences
    \[
        (H^{(0)},H^{(1)},\ldots,H^{(2^j)}),
        \quad
        (H^{(2^{j+1})},H^{(2^{j+1}-1)},\ldots,H^{(2^j)})
    \]
    are conditionally IID given $H_N^{(2^j)}$.
    It follows identically to before that
    \[
        Q_{j+1}
        = \bbE[\bbP[H_N^{(i)}\in S\quad\forall\, 0\leq i\leq 2^{j+1} | H_N^{(2^j)}]]
        = \bbE[Q_j(H_N^{(2^j)})^2]
        \ge \bbE[Q_j(H_N^{(2^j)})]^2
        = Q_j^2,
    \]
    which completes the induction.
    % Since $\Ssolve(i)$ and $\Ssolve(i+1)$ are positively correlated, we have
    % \[
    % \bbP[\Sall(1)]=\bbP[\hat S(i)]\geq \psolve^2 - \punstable.
    % \]
    % We now imitate the proof of Lemma~\ref{lem:positive-correlation}, using the events $\hat S(i)$ instead of the ``solve'' events considered there (i.e. using the edges of the path graph instead of the vertices).
    % After conditioning on $H_N^{(2^j)}$, the sequences
    % \[
    % (H_N^{(2^j)},\dots, H_N^{(1)}),\quad (H_N^{(2^j)},\dots, H_N^{(2^{j+1})})
    % \]
    % are conditionally IID, hence so are
    % \[
    % (\hat S(2^j -1),\dots,\hat S(0)),
    % \quad
    % (\hat S(2^j),\dots,\hat S(2^{j+1}-1)).
    % \]
    % Therefore we find that $\bbP[\Sall(2^{j+1})]\geq \bbP[\Sall(2^{j})]^2$ for each $j$, so $\bbP[\Sall(2^{j})]\geq (\psolve^2-\punstable)^{2^j}$.
    % Taking $j=\lceil \log_2(K)\rceil$ completes the proof.
    Finally, we address the possibility of auxiliary randomness $(\omega,\vec U)$, which we will rename to $\omega$ for this proof.
    Define
    \begin{align*}
        \psolve(\omega) &= \bbP[\Ssolve(0) | \omega], &
        \punstable(\omega) = 1 - \bbP[\Sstab(0) | \omega].
    \end{align*}
    The above argument shows that, conditional on any $\omega$,
    \[
        \bbP[\Sall(K) | \omega] \ge (\psolve(\omega)^2 - \punstable(\omega))_+^{2K}.
    \]
    By applying Jensen's inequality twice, to the functions $x\mapsto x_+^{2K}$ and $x\mapsto x^2$, we obtain:
    \begin{align*}
        \bbP[\Sall(K)]
        &= \bbE[\bbP[\Sall(K) | \omega]]
        \ge \bbE[(\psolve(\omega)^2 - \punstable(\omega))_+^{2K}] \\
        &\ge (\bbE[\psolve(\omega)^2] - \bbE[\punstable(\omega)])_+^{2K}
        \ge (\bbE[\psolve(\omega)]^2 - \bbE[\punstable(\omega)])_+^{2K} \\
        &= (\psolve^2 - \punstable)_+^{2K}. \qedhere
    \end{align*}
\end{proof}



