\subsection{Strong Low Degree Hardness for Other Mean-Field Models}
\label{subsec:prior-ogp-improve}

In this subsection and the next, we improve several existing results proved via the ensemble overlap gap property to strong low degree hardness.
We emphasize that in all of the cases below, we make essentially no changes to the \emph{landscape} properties already established, but only modify the way they are used to deduce algorithmic hardness.
% Additionally some of the parameter regimes given below are suboptimal, in the sense that improved (sharp) hardness can be established for the more constrained class of Lipschitz algorithms using the branching overlap gap property \cite{huang2021tight,huang2023algorithmic}.


For concreteness, we continue to use the randomized rounding scheme defined earlier to convert the outputs of low degree polynomials into $\bSig_N$-valued functions.
This is slightly different from what is done in the papers below, but does not affect the results.
Additionally, several of the works we adapt prove hardness for solving approximate versions of their respective problems, i.e. allowing a small constant fraction of the problem's constraints to be violated; this is analogous to the error tolerance parameter $\delta$ we have used and makes the obstructions stronger.
Our strengthenings also hold for these approximate results, but we suppress these for the sake of simplicity.

\subsubsection{Mean Field Spin Glasses}

For our first OGP improvement, we recall the pure $k$-spin Hamiltonian which is a special case of \eqref{eq:def-hamiltonian}:
\[
    H_N(\bsig)
    =
    N^{-\frac{k-1}{2}}
    \la \bG_N^{(k)}, \bsig^{\otimes k} \ra
    =
    N^{-\frac{k-1}{2}}
    \sum_{i_1,\dots,i_k=1}^N g_{i_1,\dots,i_k}\sigma_{i_1}\dots\sigma_{i_k}
    .
\]
The asymptotic maximum value is given by the Parisi formula \cite{parisi1979infinite,talagrand2006parisi,panchenko2013parisi}, and is denoted
\[
    \GS(k)
    =
    \lim_{N\to\infty}
    \bbE\lt[\max_{\bsig\in\bSig_N}H_N(\bsig)/N\rt].
\]

The next result shows that degree $o(N)$ polynomials have $o_N(1)$ probability to attain this asymptotic maximum value for $k\geq 4$ which are even.
(The result can be extended to all even mixed $p$-spin models exhibiting an overlap gap at zero temperature, by combining the below with the discussion from \cite[Section 6]{sellke2021optimizing}.)

\begin{corollary}{(Based on \cite[Theorem 2.4]{gamarnik2020optimization})}
\label{cor:GJW}
    Consider an Ising pure $k$-spin model with $k\geq 4$ even.
    There exists $\delta=\delta(k)>0$ and $c'>0$ such that the following holds.
    If $\cA^{\circ}$ is a
    degree $D\leq o(N)$ polynomial with $\bbE^{H_N}[\|\cA^{\circ}(H_N,\omega)\|^2]\le CN$, then for $\cA$ as in \eqref{eq:round-stable-alg},
    \[
    \bbP[H_N(\cA(H_N,\omega,\vec U))/N\geq \GS(k)-\delta]
    \leq
    (D/N)^{c'}
    \leq
    o_N(1).
    \]
\end{corollary}
The main landscape obstruction we will use is the following.
\begin{lemma}[{\cite[Theorem 2.10]{gamarnik2020optimization}}]
    \label{lem:kspin-ogp}
    There exist $N$-independent parameters $(\delta,\beta,\eta)$ such that uniformly in $p\in [0,1]$, the following holds.
    If $(H_N,H_{N,p})$ are $p$-correlated $k$-spin Hamiltonians, with probability $1-e^{-cN}$ there do not exist $\bsig,\bsig' \in \bSig_N$ such that
    \[
        H_N(\bsig),H_{N,p}(\bsig')\geq (\GS(k)-\delta)N,
    \]
    and $\|\bsig-\bsig'\|/\sqrt{N}\in [\beta-\eta,\beta]$.
\end{lemma}
\noindent (Note that our parameters are slightly different from theirs, as we work with Euclidean distances rather than overlaps.)
We consider an ensemble of ($k$-spin) Hamiltonians $H_N^{(0)},H_N^{(1)},\dots,H_N^{(K)}$ such that $H_N^{(i)},H_N^{(j)}$ are $(1-\eps)^{|i-j|}$-correlated.
Let $b$ be a small constant depending on $k,\delta,\beta,\eta$, which we will set below.
Let
\begin{align}
    \label{eq:eps-L-K-setting}
    \eps &= \frac{\log (N/D)}{N}, &
    L &= \fr{b}{\eps^{1/4}}, &
    K &= \lt\lceil \fr{1}{b\eps} \rt\rceil.
\end{align}
Let $\bsig^{(i)} = \cA(H_N^{(i)},\omega,\vec U)$, and define the events:
\begin{align*}
    \Ssolve &= \lt\{
        H_N^{(i)}(\bsig^{(i)}) \ge (\GS(k) - \delta)N
        \qquad \forall 0\le i\le K
    \rt\}, \\
    \Sstab &= \lt\{
        \|\bsig^{(i)} - \bsig^{(i+1)}\|/\sqrt{N} \leq L\eps^{1/4}
        \qquad \forall 0\le i\le K-1
    \rt\}, \\
    \Schaos &= \lt\{
        \begin{array}{l}
        \text{There do not exist $\bsig,\bsig' \in \bSig_N$ such that} \\
        \text{$H_N^{(0)}(\bsig), H_N^{(K)}(\bsig') \ge N(\GS(k) - \delta)$ and $\|\bsig-\bsig'\|/\sqrt{N} \le \beta - \eta$}
        \end{array}
    \rt\}, \\
    \Sogp &= \lt\{
        \text{For all $0\le i,j\le K$, the conclusion of Lemma~\ref{lem:kspin-ogp} holds for $H_N^{(i)}, H_N^{(j)}$}
    \rt\}.
\end{align*}
\begin{lemma}
    \label{lem:pspin-chaos-ogp-bounds}
    We have $\bbP(\Schaos), \bbP(\Sogp) = 1-e^{-cN}$.
\end{lemma}
\begin{proof}
    The bound on $\bbP(\Sogp)$ follows from union bounding Lemma~\ref{lem:kspin-ogp} over all $i,j$.
    For $\bbP(\Schaos)$, note that $(H_N^{(0)},H_N^{(K)})$ are $p$-correlated for
    \[
        p = (1-\eps)^{K} \le e^{-1/b}.
    \]
    We write $H_N^{(K)} = p H_N^{(0)} + \sqrt{1-p^2} \wt H_N$, where $\wt H_N$ is independent of $H_N^{(0)}$.
    By \cite[Theorem 2.10, Item 2]{gamarnik2020optimization} (applied to $H_N^{(0)}$ and $\wt H_N$), with probability $1-e^{-cN}$, there do not exist $\bsig,\bsig' \in \bSig_N$ such that $H_N^{(0)}(\bsig), \wt H_N(\bsig') \ge N(\GS(k) - \delta)$ and $\|\bsig-\bsig'\|/\sqrt{N} \le \beta - \eta$.
    Furthermore by Proposition~\ref{prop:gradients-bounded} with $k=0$, we have $\sup_{\bsig \in \bSig_N} H_N^{(0)}(\bsig) / N \le C$ with probability $1-e^{-cN}$, for some $C = O(1)$.
    Setting $b$ large enough that $Cp \le \delta/2$ implies the result (after adjusting $\delta$).
\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:GJW}]
    Like above, let $\psolve = \bbP[H_N^{(0)}(\bsig^{(0)})/N\ge \GS(k)-\delta]$, and $\punstable = \bbP[\|\bsig^{(0)} - \bsig^{(1)}\| / \sqrt{N} > L\eps^{1/4}]$.
    Note that $L\eps^{1/4} = b$, and we can set $b$ small enough that $b\le \eta$.
    Then, as argued in \cite[Proof of Theorem 2.4]{gamarnik2020optimization}, we have $\Ssolve \cap \Sstab \cap \Schaos \cap \Sogp = \emptyset$.
    Lemma~\ref{lem:grand-correlation} implies
    \[
        \bbP(\Ssolve \cap \Sstab) \ge (\psolve^2 - \punstable)^{2K}.
    \]
    Combining with Lemma~\ref{lem:pspin-chaos-ogp-bounds} shows
    \[
        (\psolve^2 - \punstable)^{2K} \le e^{-cN} \qquad \implies \qquad
        \psolve \le \punstable^{1/2} + e^{-cN/4K}.
    \]
    These two terms are bounded identically to the proof of Theorem~\ref{thm:SK-hardness-LDP}\ref{it:low-degree-ultimate-conseq}.
    For the choice of $\eps$ above, the right-hand side of \eqref{eq:stability-of-rounded-low-degree-l2} in Proposition~\ref{prop:low-degree-stable} is bounded by $16 CD\eps N^2$.
    Applying this estimate,
    \begin{equation}
        \label{eq:pspin-punstable}
        \punstable \le \fr{16CD\eps}{b^4}
        \asymp \fr{D\log(N/D)}{N}
        \le \sqrt{D/N}.
    \end{equation}
    Moreover, (for dimension-free but varying $c$),
    \begin{equation}
        \label{eq:pspin-exponential}
        e^{-cN/4K} = e^{-cN\eps} = e^{-c\log (N/D)} = (D/N)^c.
    \end{equation}
    It follows that $\psolve \le (D/N)^{c'} = o_N(1)$.
\end{proof}

