\subsubsection{Ising perceptron models}

Next we turn to the Ising perceptron.
Here we are given $M$ IID Gaussian vectors $\bg_1,\dots,\bg_M \sim \cN(0,I_N)$ with $\lim_{N\to\infty} M/N=\alpha\in(0,\infty)$, and a fixed $I\subseteq\bbR$.
For convenience we let $\bG$ be the $M\times N$ matrix with $\bg_i$ as the $i$-th row.
We say $\bsig\in\bSig_N$ is a solution, denoted $\bsig\in S(\bG;I)$, if
\[
    \la \bg_i,\bsig\ra/\sqrt{N} \in I,\quad\forall\, i\in [M].
\]
We obtain strong low degree hardness for two important cases of the random perceptron, based on \cite{gamarnik2022algorithms,li2024discrepancy}: the symmetric Ising perceptron, with $I = [-\kappa,\kappa]$ for small $\kappa$, and the negative Ising perceptron, with $I = [\kappa,\infty)$ for large negative $\kappa$.

Here the adaptation is somewhat more challenging; these results rely on the multi-ensemble overlap property and finiteness of multi-color Ramsey-numbers, via a technique introduced by \cite{gamarnik2021partitioning}.
Nevertheless we show low degree hardness up to the near-optimal level $D\leq o(N/\log N)$.
The logarithmic factor comes from the slightly faster than $\exp(R)$ growth in the following famous bound.

\begin{proposition}{(\cite{erdos1935combinatorial})}
\label{prop:ramsey-bound}
Let $K,m\in\bbZ_+$. Then given any $K$-coloring of the complete graph on $K^{Km}$ vertices, there exists a monochromatic $m$-clique.
\end{proposition}

\begin{corollary}{(Based on \cite[Theorem 3.2]{gamarnik2022algorithms})}
\label{cor:GKPX}
    There exists sufficiently small $\kappa_0 > 0$ such that for $\kappa\in (0,\kappa_0)$ and $\alpha\geq 10\kappa^2\log(1/\kappa)$, if $\cA^\circ$ is any degree $D\leq o(N/\log N)$ polynomial with $\bbE[\|\cA^{\circ}(H_N,\omega)\|^2]\le CN$, then $\cA$ as in \eqref{eq:round-stable-alg} has probability $o_N(1)$ to solve the Ising perceptron with $I=[-\kappa,\kappa]$.
\end{corollary}


The proof is based on the following landscape obstruction.
Let $I = [-\kappa,\kappa]$.
\begin{lemma}[{\cite[Theorem 2.4]{gamarnik2022algorithms}}]
    \label{lem:sbp-ogp}
    For any $\kappa,\alpha$ as in Theorem~\ref{cor:GKPX}, there exist $0 < \eta < \beta < 1$ and $m\in \bbZ_+$ such that the following holds for all $p_1,\ldots,p_m \in [0,1]$.
    Let $\wt\bG^0,\wt\bG^1,\ldots,\wt\bG^m$ be i.i.d. copies of $\bG$, and for $1\le i\le m$ let
    \[
        \bG^i = p_i \wt\bG^0 + \sqrt{1-p_i^2} \wt \bG^i.
    \]
    With probability $1-e^{-cN}$, there does not exist $(\bx^{(1)},\dots,\bx^{(m)}) \in \bSig_N^m$ such that:
    \begin{itemize}
        \item $\bx^{(i)}\in S(\bG^i;I))$ for all $1\le i\le m$;
        \item $\|\bx^{(i)}-\bx^{(j)}\|/\sqrt{N}\in [\beta-\eta,\beta]$ for all $1\le i,j\le m$.
    \end{itemize}
\end{lemma}
We will also require the following ``chaos'' obstruction.
\begin{lemma}[{Adaptation of \cite[Lemma 6.12]{gamarnik2022algorithms}}]
    \label{lem:sbp-chaos}
    For any $\kappa,\alpha$ as in Theorem~\ref{cor:GKPX}, there exists sufficiently small constant $\rho > 0$ such that the following holds.
    Let $\eta,\beta,m$ be as in Lemma~\ref{lem:sbp-ogp}.
    For all $p_1,\ldots,p_m \in [0,\rho]$, with probability $1-e^{-cN}$, there does not exist $(\bx^{(1)},\dots,\bx^{(m)}) \in \bSig_N^m$ such that:
    \begin{itemize}
        \item $\bx^{(i)}\in S(\bG^i;I))$ for all $1\le i\le m$;
        \item $\|\bx^{(i)}-\bx^{(j)}\|/\sqrt{N}\le \beta-\eta$ for all $1\le i,j\le m$.
    \end{itemize}
\end{lemma}
\begin{proof}
    This is shown in \cite{gamarnik2022algorithms} for $\rho = 0$, through a first moment computation.
    The effect on this first moment computation of taking $\rho$ positive is easily seen to affect their estimates by a factor of $e^{\delta(\rho) N}$, where $\delta(\rho) \to 0$ as $\rho \to 0$.
    The result follows by taking $\rho$ small enough that $\delta(\rho) \le c/2$ and adjusting $c$.
\end{proof}
Let $\psolve = \bbP[\cA(\bG,\omega,\vec U) \in S(\bG;I)]$.
We suppose for sake of contradiction that $\psolve = \Omega(1)$ (possibly along a subsequence of values $N$).


Let $\eps,L,K$ be set as in \eqref{eq:eps-L-K-setting} above, where $b$ is a sufficiently small constant depending on $\kappa,\alpha,\eta,\beta,m$.
We will set $W$ as in \eqref{eq:def-W} below.
We construct a jointly Gaussian family of $M\times N$ disorder matrices $\bG^{(0)}$ and $\bG^{(k,w)}$ for $0\leq k\leq K$ and $1\leq w\leq W$, each with the same marginal distribution as $\bG$.
To construct this family, we first sample $\bG^{(0)}=\bG^{(0,1)}=\dots=\bG^{(0,W)}$.
Then for each $1\leq w\leq W$, we let
\begin{equation}
    \label{eq:multi-OGP-interpolation}
    \Big(
        \bG^{(0,w)},
        \bG^{(1,w)},
        \ldots,
        \bG^{(K,w)}
    \Big)
\end{equation}
be a Markovian sequence as before where $(\bG^{(k,w)},\bG^{(k',w)})$ are $(1-\eps)^{|k-k'|}$-correlated, and where the sequences \eqref{eq:multi-OGP-interpolation} over different $w$ are conditionally independent given $\bG^{(0)}$.
Let $\bsig^{(k,w)} = \cA(\bG^{(k,w)},\omega,\vec U)$.
For $1\le w\le W$, define
\begin{align*}
    \Ssolve(w) &= \lt\{
        \bsig^{(k,w)} \in S(\bG^{(k,w)};I) \qquad \forall 0\le k\le K
    \rt\}, \\
    \Sstab(w) &= \lt\{
        \|\bsig^{(k,w)} - \bsig^{(k+1,w)}\| / \sqrt{N} \le L\eps^{1/4} \qquad
        \forall 0\le k\le K-1
    \rt\}, \\
    \Sall(w) &= \Ssolve(w) \cap \Sstab(w).
\end{align*}
Finally, let
\begin{align*}
    U &= \{w \le W : \Sall(w)\,\textup{holds}\}, &
    \Sramsey &= \lt\{
        |U| \ge (K+1)^{(K+1)m}
    \rt\}.
\end{align*}
\begin{lemma}
    \label{lem:ramsey-poisson}
    Let
    \begin{equation}
        \label{eq:def-W}
        W = 3\lceil (K+1)^{(K+1)m} / \bbP[\Sall(1)] \rceil.
    \end{equation}
    Then $W \le e^{o(N)}$, and $\bbP(\Sramsey) \ge e^{-o(N)}$.
\end{lemma}
\begin{proof}
    Let $\punstable = \bbP[\|\bsig^{(k,w)} - \bsig^{(k+1,w)}\| / \sqrt{N} > L\eps^{1/4}]$.
    Identically to \eqref{eq:pspin-punstable}, we have $\punstable = o_N(1)$.
    By Lemma~\ref{lem:grand-correlation},
    \[
        \bbP[\Sall(1)] \ge (\psolve^2 - \punstable)^{2K} \ge e^{-o(N)},
    \]
    where the last inequality follows from $\psolve = \Omega(1)$ and $K = \lceil 1/b\eps \rceil = o(N / \log N)$.
    Moreover
    \[
        (K+1)^{(K+1)m} \le N^{o(N / \log N)} = e^{o(N)}.
    \]
    This implies $W \le e^{o(N)}$.
    Next, let $p = \bbP[\Sall(1)]$.
    Note that
    \[
        \bbE[\bbP[\Sall(1) | \bG^{(0)}]] = p,
    \]
    and thus
    \[
        \bbP[\bbP[\Sall(1) | \bG^{(0)}] \ge p/2] \ge p/2.
    \]
    Conditional on a realization of $\bG^{(0)}$ such that $\bbP[\Sall(1) | \bG^{(0)}] \ge p/2$, $|U|$ stochastically dominates a $\Bin(W,p/2)$ random variable.
    By a standard Chernoff bound, $U \ge (K+1)^{(K+1)m}$ with high conditional probability.
    It follows that $\bbP(\Sramsey) \ge (1-o(1)) p/2 \ge e^{-o(N)}$.
\end{proof}
We further define the events:
\begin{align*}
    \Schaos &= \lt\{
        \begin{array}{l}
            \text{For any distinct $1\le w_1,\ldots,w_m \le W$, the conclusion of} \\
            \text{Lemma~\ref{lem:sbp-chaos} holds for $\bG^{(K,w_1)},\ldots,\bG^{(K,w_m)}$}
        \end{array}
    \rt\}, \\
    \Sogp &= \lt\{
        \begin{array}{l}
            \text{For any distinct $0\le k_1,\ldots,k_m \le K$, $1\le w_1,\ldots,w_m \le W$,} \\
            \text{the conclusion of Lemma~\ref{lem:sbp-ogp} holds for $\bG^{(k_1,w_1)},\ldots,\bG^{(k_m,w_m)}$}
        \end{array}
    \rt\}.
\end{align*}
\begin{lemma}
    \label{lem:sbp-chaos-ogp-bounds}
    We have $\bbP(\Schaos),\bbP(\Sogp) \ge 1-e^{-cN}$.
\end{lemma}
\begin{proof}
    Let $p = (1-\eps)^K \le e^{-1/b}$.
    We can set $b$ small enough that $p\le \rho$ for $\rho$ defined in Lemma~\ref{lem:sbp-chaos}, so that this lemma applies.
    Since $W \le e^{o(N)}$ by Lemma~\ref{lem:ramsey-poisson}, taking a union bound of Lemma~\ref{lem:sbp-chaos} over the $W^m \le e^{o(N)}$ choices of $(w_1,\ldots,w_m)$ implies $\bbP(\Schaos) \ge 1-e^{-cN}$.
    Similarly, taking a union bound of Lemma~\ref{lem:sbp-ogp} over the $(K+1)^mW^m \le e^{o(N)}$ choices of $(k_1,\ldots,k_m,w_1,\ldots,w_m)$ implies $\bbP(\Sogp) \ge 1-e^{-cN}$.
\end{proof}

\begin{lemma}
    \label{lem:sbp-no-intersection}
    We have $\Sramsey \cap \Schaos \cap \Sogp = \emptyset$.
\end{lemma}
\begin{proof}
    Suppose the event $\Sramsey$ holds.
    We color the edges $(u,u')$ of the complete graph on vertex set $U$ using the colors $\{0,\ldots,K\}$, as follows.
    If there exists $1\leq k\leq K$ such that
    \[
        \|\bsig^{(k,u)} - \bsig^{(k,u')}\|/\sqrt{N}
        \in [\beta-\eta,\beta]
    \]
    then we color $(u,u')$ by the minimal such $k$.
    Otherwise we color $(u,u')$ by $0$.
    Set $b$ small enough that $L\eps^{1/4} = b \le \eta/2$.
    Since $\Sstab(u),\Sstab(u')$ hold (by definition of $u,u' \in U$), the latter case implies
    \[
        \|\bsig^{(k,u)} - \bsig^{(k,u')}\|/\sqrt{N}
        < \beta - \eta
    \]
    for all $0\le k\le K$, and in particular for $k=K$.
    This coloring uses $K+1$ colors, so by Proposition~\ref{prop:ramsey-bound} there exists a monochromatic $m$-clique.
    However, if the color $0$ contains an $m$-clique, then $\Schaos$ does not hold, and if the color $k$ contains an $m$-clique for any $1\le k\le K$, then $\Sogp$ does not hold.
    % However as argued above, the validity of \eqref{eq:K-subexponential} implies both of the following except with probability $e^{-cN/2}$.
    % Firstly the $0$-color does not contain an $m$-clique thanks to the chaos event, and secondly each other color $1\leq k\leq K$ also does not contain an $m$-clique by the multi-OGP.
%     However since $(K+1)e^{-cN/2}$ is much smaller than the probability in \eqref{eq:decent-chance-of-many-arms}, we obtain a contradiction. This completes the proof.
\end{proof}
\begin{proof}[Proof of Corollary~\ref{cor:GKPX}]
    Lemmas~\ref{lem:ramsey-poisson}, \ref{lem:sbp-chaos-ogp-bounds}, and \ref{lem:sbp-no-intersection} yield the desired contradiction.
\end{proof}

