Exactly the same argument also yields strong low degree hardness for the asymmetric Ising perceptron considered in \cite{li2024discrepancy}, where $I=[\kappa,\infty)$ for $\kappa\ll 0$.
Indeed the implementation of the ensemble multi-OGP in \cite{li2024discrepancy} is identical to \cite{gamarnik2022algorithms} modulo the precise choice of $I$ and $(\beta,\eta)$ (and the moment computations used to establish the multi-OGP and chaos properties).
We thus obtain the following.

\begin{corollary}{(Based on \cite[Theorem 4.3]{li2024discrepancy})}
\label{cor:LSZ}
     There is an absolute constant $C_{\ref{cor:LSZ}}$ such that for $\kappa\leq -1$ and $\alpha\geq \frac{C_{\ref{cor:LSZ}} e^{\kappa^2/2} \log^2 |\kappa|}{\kappa}$, if $\cA^\circ$ is any degree $D\leq o(N/\log N)$ polynomial with $\bbE[\|\cA^{\circ}(H_N,\omega)\|^2]\le CN$, then $\cA$ as in \eqref{eq:round-stable-alg} has probability $o_N(1)$ to solve the Ising perceptron with $I=[\kappa,\infty)$.
\end{corollary}


\subsection{Sparse Constraint Satisfaction Problems}
\label{subsec:CSP}


In this subsection we consider two further adaptations of the ensemble OGP, where the disorder consists of sparse Bernoulli variables rather than Gaussians.
This requires a generalization of the $L^2$-stability estimate \eqref{eq:low-degree-l2-stable} for low degree polynomials, but does not otherwise add any difficulties.
Given a finite set $\Gamma$ equipped with a probability measure $\mu$, we say a pair $(y,\hat y)\in \Gamma^2$ is $p$-correlated for $p\in [0,1]$ if both have marginal law $\mu$ and $\hat y$ is given by resampling from $\mu$ with probability $1-p$.
That is, given $y$, the conditional law of $\hat y$ is given by $y$ with probability $p$ and an independent copy with probability $1-p$.
We say $\by,\hat\by\in\Gamma^d$ are $p$-correlated if their $i$-th entries are $p$-correlated for each $1\leq i\leq d$, and are otherwise independent.
The space of degree $D$ functions on $\Gamma^d$ is defined to be the span of all functions of the form
\begin{equation}
\label{eq:general-polynomial-def}
F(y_1,\dots,y_d)
=
\prod_{i\in I} f_i(y_i)
\end{equation}
where $|I|\leq D$ and $f_i:\Gamma\to\bbR$ are arbitrary.
We say $\cA^{\circ}:\Gamma^d\to\bSig_N$ is a degree $D$ function if each of its $N$ output coordinates is degree $D$.
As before we take $\cA$ to be a randomized rounding of $\cA^{\circ}$.

We also note in passing that a degree $D$ function is a slightly more general notion than a degree $D$ polynomial, because it only counts the number of \emph{distinct} input variables which participate in each term.

\begin{remark}
    By working with resampling rather than correlated Gaussian processes as in the proof below, Theorem~\ref{thm:SK-hardness}\ref{it:low-degree-ultimate-conseq} also extends to hardness for degree $o(N)$ functions.
\end{remark}


% Given $q\in (0,1)$, define $\phi_q:\{-1,1\}\to\bbR$ by $\phi_q(y) = \frac{y-(2q-1)}{2\sqrt{q(1-q)}}$.
% Given $S\subseteq [d]$, define
% \[
% \phi_S(\by) = \prod_{i\in S} \phi_q(y_i),\quad\forall\, \by=(y_1,\dots,y_d)\in\bSig_d.
% \]
% The $2^d$ functions $\{\phi_S\}_{S\subseteq [d]}$ form an orthonormal basis relative to the $q$-biased measure $\mu_q$ on $\bSig_d$, under which each coordinate equals $1$ independently with probability $q$.
% We say such $\bSig_d$-valued random variables are $q$-biased.
% We say a pair $(y,\hat y)$ of $q$-biased bits are $p$-correlated if their joint law is given by setting $\hat y=y$ with probability $p$, and otherwise setting $\hat y=y'$ to be an IID copy of $y$.
% Similarly a pair of $q$-biased strings are $p$-correlated if their $i$-th bits are $p$-biased for each $1\leq i\leq d$, and otherwise independent.
% We write $\mu_{q,p}$ for this measure.
% We say $\cA^{\circ}:\bSig_d\to\bSig_N$ is a degree $D$ polynomial if each of its $N$ output coordinates is a degree $D$ (or smaller) polynomial in its input.
% As before we take $\cA$ to be a randomized rounding of $\cA^{\circ}$.



\begin{proposition}
\label{prop:sparse-bernoulli-fourier}
    Let $\cA^{\circ}:\Gamma^d\to\bSig_N$ be a degree $D$ function such that $\bbE^{\by\sim\mu_q}[\|\cA^{\circ}(\by)\|^2]\leq CN$, and let $\cA$ be defined in terms of $\cA^\circ$ as in \eqref{eq:round-stable-alg}.
    Then if $(\by,\hat{\by})\in (\Gamma^d)^2$ is a $(1-\eps)$-correlated pair of $q$-biased bit strings:
    \begin{align*}
    \bbE[\|\cA(\by,\omega,\vec U)-\cA(\hat{\by},\omega,\vec U)\|^4]
    \leq
    12 \lt(CD\eps N^2 + \sqrt{CD\eps} N\rt).
    % 8CD\eps N^2.
    \end{align*}
\end{proposition}

\begin{proof}
    We recall from e.g. \cite[Chapter 8]{donnell2014analysis} that $L^2(\Gamma;\mu)$ has a Fourier basis, and that degree $D$ polynomials are exactly those functions with only degree $\leq D$ terms in this basis.
    (This basis for $L^2(\Gamma;\mu)$ is also known as the Hoeffding or functional ANOVA decomposition.)
    From \cite[Proposition 8.28]{donnell2014analysis}, we have that analogously to \eqref{eq:hermite-correlation}, for any degree $k$ Fourier basis function $\phi$:
    \[
    \bbE[\phi(\by)\phi(\hat{\by})]
    =
    (1-\eps)^k.
    \]
    Then the proof is exactly identical to that of \eqref{eq:low-degree-l2-stable}, \eqref{eq:stability-of-rounded-low-degree-l2}.
\end{proof}



We also have an exact analog of Lemma~\ref{lem:grand-correlation}.
Fix an arbitrary
finite
set $\Gamma$ and let $\mu$ be a probability measure supported on $\Gamma$.
Let $\by^{(0)},\dots,\by^{(K)}\in\Gamma^d$ be a Markovian sequence of strings with marginal law $\mu^{\otimes d}$ such that each adjacent pair is $p$-correlated.
As before, let $S=S(\by)\subseteq \Gamma^d$ be an arbitrary set-valued function.
 % and $S_2=S_2(\by,\hat \by)\subseteq (\Gamma^d)^2$ be arbitrary set-valued functions.
Given some $(L,\eps,\tau)$, define
\begin{align*}
    \Ssolve(i)
    &\equiv
    \{\cA(\by^{(i)},\omega,\vec U)\in S(\by^{(i)})\}, \\
    \Sstab(i)
    &\equiv
    \{\|\cA(\by^{(i)},\omega,\vec U)-\cA(\by^{(i+1)},\omega,\vec U)\|/\sqrt{N}
    \leq
    L\eps^{1/4}+\tau\}
\end{align*}
with probabilities $\psolve = \bbP(\Ssolve(0))$, $\punstable = 1 - \bbP(\Sstab(0))$.
% \[
% \psolve=\bbP[\cA(\by,\omega,\vec U)\in S(\by)]
% \]
% and
% \[
% \punstable
% =
% \bbP^{\by,\hat{\by}\,\text{$p$-correlated}}\Big[
%     \big(\cA(\by,\omega,\vec U),\cA(\hat{\by},\omega \vec U)\big)\in S_2(\by,\hat \by)
% \Big].
% \]
Define the ``success and stability'' event
\[
    \Sall(K) = \Big(\bigcap_{i=0}^K \Ssolve(i)\Big) \cap \Big(\bigcap_{i=0}^{K-1} \Sstab(i)\Big).
\]


\begin{lemma}
\label{lem:bernoulli-correlation}
With the definitions above,
\[
\bbP[\Sall(K)]
\geq
(\psolve^2-\punstable)_+^{2K}.
\]
\end{lemma}


\begin{proof}
    Like in the proof of Lemma~\ref{lem:grand-correlation}, we first consider the case where $\cA(\by,\omega,\vec U) = \cA(\by)$ does not use the auxiliary randomness $(\omega,\vec U)$, and argue by induction in powers of two.

    The pair of strings $(\by^{(0)},\by^{(1)})$ can be generated as follows.
    Sample $J \subseteq \{1,\ldots,d\}$ by including each element independently with probability $p$.
    For each $j\in J$, we sample $(y^{(0)}_j, y^{(1)}_j)$ to be equal, and otherwise sample them to be independent.

    Further, let $\by^{(0)}_J = (y^{(0)}_j : j\in J)$.
    Then $(\by^{(0)},\by^{(1)})$ are conditionally IID given $\by^{(0)}_J$.
    So, by Jensen's inequality,
    \[
        \bbP(\Ssolve(0) \cap \Ssolve(1))
        = \bbE(\bbP(\Ssolve(0) | \by^{(0)}_J)^2)
        \ge \bbE(\bbP(\Ssolve(0) | \by^{(0)}_J))^2
        = \psolve^2.
    \]
    It follows that $\bbP[\Sall(1)] \ge \psolve^2 - \punstable$, establishing the base case.
    The inductive step is identical to Lemma~\ref{lem:grand-correlation}, and the auxiliary randomness $(\omega,\vec U)$ is also addressed identically to that lemma.
    % by making each pair of coordinates $(y^{(0)}_j, y^{(1)}_j)$, for $1\le j\le d$, equal with probability $p$ and independent with probability $1-p$.
    % Conditioning on the indices which are set to be equal due to the first step makes $(\by^{(i)},\by^{(i+1)})$ conditionally IID.
    % This shows via Jensen's inequality that $\Ssolve(i),\Ssolve(i+1)$ are positively correlated; the remainder is exactly as in Lemma~\ref{lem:grand-correlation}.
\end{proof}

\subsubsection{Maximum independent set}

Next we turn to the maximum independent set problem, following the approach of \cite{wein2020independent}.
Here the random input is a sparse Erd\H{o}s--R\'enyi graph $\by\sim G(N,d/N)$, with $d$ large but constant while $N\to\infty$.
We consider deterministic algorithms $\cA^{\circ}:\bbR^{\binom{N}{2}}\to \bbR^N$ given by a degree $D$ function of $\by$ (identified with its adjacency matrix).
Let $\cA$ be the randomized rounding given by \eqref{eq:round-stable-alg}; we identify its output with the set $\{i\in [N]~:~\cA(\by,\omega,\vec U)_i=1\}$.

It is known that in the double limit $N\to\infty$ followed by $d\to\infty$, the maximum independent set has size $(1+o_d(1)) \cdot \fr{2 \log d}{d} N$ \cite{frieze1990independence}.
A simple greedy algorithm finds a roughly half-optimal independent set of size $(1+o_d(1)) \cdot \fr{2 \log d}{d} N$ \cite{karp1976probabilistic}, but there is now substantial evidence that algorithms cannot do better than this: \cite{rahman2017independent} showed that local algorithms cannot find larger independent sets with even small probability, while \cite{wein2020independent} showed that low degree polynomials cannot find such sets with probability too close to $1$.
We upgrade this latter result to strong low degree hardness.
Below, $\iota$ plays the role of $\eps$ in \cite{wein2020independent}.

\begin{corollary}{(Based on \cite[Theorem 1.3]{wein2020independent})}
    \label{cor:wein}
    For any $\iota>0$ there exists sufficiently large $d_*(\iota)$ such that for all $d\geq d_*(\iota)$, the following holds.
    If $\cA^\circ$ is a degree $D = o(N)$ function satisfying $\bbE[\|\cA^\circ(\by,\omega)\|^2] \le CN$, then for $\cA$ as in \eqref{eq:round-stable-alg},
    \begin{equation}
    	\label{eq:wein-conclusion}
    	\bbP\lt[\cA(\by,\omega,\vec U)\,\text{is an independent set of}\,\by\,\text{of size at least}\,\fr{(1+\iota) \log d}{d}\cdot N\rt] = o_N(1).
    \end{equation}
    % any degree $D = o(N)$ function computes an independent set of $\by\sim G(N,d/N)$ of size at least $\frac{(1+\iota)N\log d}{d}$ with probability most $o_N(1)$.
\end{corollary}

In the below proof, given $\iota>0$ sufficiently small (without loss of generality), we will choose $d$ sufficiently large depending on $\iota$ and $b$ sufficiently small depending on $(\iota,d)$.
We then set parameters:
\begin{align*}
    \eps &= \fr{\log (N/D)}{N}, &
    L &= \fr{b}{\eps^{1/4}}, &
    K &= \lt\lceil \fr{1}{b\eps} \rt\rceil, &
    m &= 1 + \lt\lceil \fr{5}{\iota^2} \rt\rceil, &
    b_0 &= bm.
\end{align*}
Generate a Markovian sequence $\by^{(0)},\ldots,\by^{(K)}$ where $\by^{(t+1)}$ is obtained by resampling each of the $\binom{N}{2}$ IID entries in $\by^{(t)}$ with probability $\eps$, so that $\by^{(t)},\by^{(t')}$ are $(1-\eps)^{|t-t'|}$-correlated.
The proof is based on the following landscape obstruction.
\begin{lemma}[{Adaptation of \cite[Proposition 2.3]{wein2020independent}}]
    \label{lem:indset-ogp}
    With probability $1-e^{-cN}$, there do not exist $0\leq t_1\leq \dots\leq t_m\leq K$ and subsets $S_1,\dots,S_m\subseteq [N]$ satisfying the following:
    \begin{enumerate}[label=(\roman*)]
        \item $S_j$ is an independent set in $\by^{(t_j)}$ for each $1\leq j\leq m$.
        \item $|S_j|\geq \frac{(1+\iota)N\log d}{d}$ for each $1\leq j\leq m$.
        \item $|S_j\backslash (\cup_{\ell<j} S_{\ell})|\in \lt[\frac{\iota N\log d}{4d},\frac{\iota N\log d}{2d}\rt]$ for all $2\leq j\leq m$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    This is proved by bounding the first moment of the number of such $(t_1,\ldots,t_m,S_1,\ldots,S_m)$.
    While \cite{wein2020independent} uses a slightly different correlated ensemble of $\by^{(t)}$, in both cases the first moment contribution of any $(t_1,\ldots,t_m)$ is upper bounded by the case $t_1=\cdots=t_m$, and in this case the event fails to hold with probability $e^{-cN}$.
	The result follows by a union bound over the $N^{O(1)}$ sequences of $t_j$.
\end{proof}
Next, we need a ``chaos'' result.
Let $S^{(t)}$ be the output of $\cA(\by^{(t)},\omega,\vec U)$, intepreted as a subset of $[N]$.
\begin{lemma}[{Adaptation of \cite[Lemma 2.4]{wein2020independent}}]
    \label{lem:indset-chaos}
    With probability $1-e^{-cN}$, there does not exist $j\le m$ and a sequence $0\leq t_1\leq \dots\leq t_j\leq K$ with $t_j\geq t_{j-1}+\frac{1}{b_0\eps}$ and set $S\subseteq [N]$ satisfying the following:
    \begin{enumerate}[label=(\roman*)]
        \item $S$ is an independent set in $\by^{(t_j)}$.
        \item $|S|\geq \frac{(1+\iota)N\log d}{d}$.
        \item \label{it:size-of-indsets-so-far} $|\cup_{\ell<j} S^{(t_\ell)}| \ge \frac{N\log d}{\iota^3 d}$.
        \item $|S \cap (\cup_{\ell<j} S^{(t_\ell)})| \ge \frac{\iota \log d}{d} \cdot N$.
    \end{enumerate}
\end{lemma}
Note that in this event, only $S$ is allowed to vary arbitrarily, while $S^{(t_1)},\ldots,S^{(t_{j-1})}$ must depend only on their respective input $\by^{(t_\ell)}$ and in particular not on $\by^{(t_j)}$.
\begin{proof}
    If $(\by^{(t)})_{t\leq t_{j-1}}$ were independent of $\by^{(t_j)}$, this follows directly from \cite[Lemma 2.4]{wein2020independent}, where $1/\iota^3$ plays the role of $a$ therein.
    Here the correlation between $\by^{(t_{j-1})}$ and $\by^{(t_j)}$ is at most $(1-\eps)^{1/b_0\eps} \le e^{-1/b_0} = e^{-1/bm}$ (and $(\by^{(t)})_{t\leq t_{j-1}}$ is conditionally independent of $\by^{(t_j)}$ given $\by^{(t_{j-1})}$).
    For sufficiently small $b$, the lemma can be proved by the same first moment computation.
\end{proof}
Finally, we need the following bound on the largest independent set.
\begin{lemma}[{\cite[Lemma 2.2]{wein2020independent}}]
    \label{lem:indset-max}
    With probability $1-e^{-cN}$ there is no independent set in any $\by^{(k)}$ of size larger than $\frac{(2+\iota)N\log d}{d}$.
\end{lemma}
Similarly to above, define
\begin{align*}
    \Ssolve &= \{\text{$S^{(t)}$ is an independent set of $\by^{(t)}$ of size $\ge (1+\iota)N \log d / d$, for all $0\le t\le K$}\}, \\
    \Sstab &= \{\text{$|S^{(t)} \Delta S^{(t+1)}| / N \le L^2\eps^{1/2}/4$ for all $0\le t\le K-1$}\},
\end{align*}
where $S^{(t)} \Delta S^{(t+1)}$ denotes the symmetric difference between sets $S^{(t)}, S^{(t+1)}$.
Let $\Sogp$, $\Schaos$, $\Smax$ be the events in Lemmas~\ref{lem:indset-ogp}, \ref{lem:indset-chaos}, and \ref{lem:indset-max}, which hold with probability $1-e^{-cN}$.
\begin{lemma}[{Adaptation of \cite[Proof of Theorem 1.3]{wein2020independent}}]
    \label{lem:indset-no-intersection}
    $\Ssolve \cap \Sstab \cap \Sogp \cap \Schaos \cap \Smax = \emptyset$.
\end{lemma}
\begin{proof}
    Suppose $\Ssolve, \Sstab, \Schaos, \Smax$ hold; we will contradict $\Sogp$.
    Let $t_1 = 0$ and recursively define $t_j$ for $2\leq j\leq m$ to be the smallest $t\geq t_{j-1}$ such that
    \begin{equation}
        \label{eq:ind-set-iterative-moats}
        |S^{(t)} \backslash (\cup_{\ell<j} S^{(t_\ell)})|\in \lt[\frac{\iota N\log d}{4d},\frac{\iota N\log d}{2d}\rt].
    \end{equation}
    Note that $L^2\eps^{1/2} / 4 = b^2/4$.
    We set $b$ small enough that this is smaller than $\fr{\iota\log d}{4d}$.
    Then, $\Sstab$ ensures that as $t$ advances, the left-hand side of \eqref{eq:ind-set-iterative-moats} never jumps over the right-hand interval.
    However, $\Schaos$ implies that $t_j \le t_{k-1} + \fr{1}{b_0\eps}$ is successfully chosen.
    (Note that \ref{it:size-of-indsets-so-far} in Lemma~\ref{lem:indset-chaos} holds since the rule \eqref{eq:ind-set-iterative-moats} was used to construct previous independent sets, while $\Smax$ upper bounds the size of $S^{(t_1)}$.)
    Therefore, $t_m \le \fr{m}{b_0 \eps} = \fr{1}{b\eps} \le K$, so this procedure finds $(t_1,\ldots,t_m)$ before exhausting the times $\{0,\ldots,K\}$.
    Then, the existence of $(t_1,\ldots,t_m)$ and $(S^{(t_1)},\ldots,S^{(t_m)})$ contradicts $\Sogp$.
\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:wein}]
    Let $\psolve$ denote the left-hand side of \eqref{eq:wein-conclusion} and
    \[
        \punstable = \bbP\lt[|S^{(1)} \Delta S^{(2)}| / N \ge L^2\eps^{1/2}/4\rt]
        = \bbP\lt[\|\cA(\by^{(1)},\omega,\vec U) - \cA(\by^{(2)},\omega,\vec U)\| / \sqrt{N} \ge L\eps^{1/4} \rt].
    \]
    By the above discussion, $\bbP(\Sogp \cap \Schaos \cap \Smax) = 1-e^{-cN}$.
    Lemmas~\ref{lem:bernoulli-correlation} and \ref{lem:indset-no-intersection} then imply
    \[
        (\psolve^2-\punstable)^{2K} \le \bbP(\Ssolve \cap \Sstab) \le e^{-cN} \qquad \implies \qquad
        \psolve \le \punstable^{1/2} + e^{-cN/4K}.
    \]
    We can bound $\punstable = o_N(1)$ similarly to \eqref{eq:pspin-punstable}, but using Proposition~\ref{prop:sparse-bernoulli-fourier} in place of Proposition~\ref{prop:low-degree-stable}
    The term $e^{-cN/4K}$ is bounded by $o_N(1)$ identically to \eqref{eq:pspin-exponential}.
\end{proof}

\subsubsection{Random $k$-SAT}

Next we consider random $k$-SAT.
Here the problem instance consists of $N$ Boolean variables $x_1,\ldots,x_N \in \{\ttT,\ttF\}$ and $M$ IID clauses, where $\lim_{N\to\infty} M/N = \alpha$.
Each clause is a boolean disjunction (``or'') of $k$ IID literals, sampled uniformly at random from $\Gamma = \{x_1,\ldots,x_N,\bar x_1,\ldots,\bar x_N\}$, where $\bar x_i$ denotes the negation of $x_i$ --- for example, when $k=3$ a possible clause is $x_1 \lor \bar x_3 \lor x_7$.
Thus a random $k$-SAT instance can be identified with a sample $\by \sim \mu^{\otimes kM}$, where $\mu = \mathsf{unif}(\Gamma)$.
The goal is to find an assignment $\bx = (x_1,\ldots,x_N) \in \{\ttT,\ttF\}^N$ such that all $M$ clauses evaluate to true.
We will identify the output space $\bSig_N = \{-1,1\}^N$ of $\cA$ with $\{\ttT,\ttF\}^N$ by identifying $+1$ with $\ttT$ and $-1$ with $\ttF$.

We consider the setting where $k$ is large but fixed and $N\to\infty$.
It is known that satisfying assignments exist precisely for $\alpha$ up to an explicit threshold $\alpha_\sat(k)$ \cite{mezard2002analytic,ding2022proof}, which has asymptotic $2^k \log 2 - \fr12 (1 + \log 2) + o_k(1)$, while the best algorithm known for this problem \cite{coja2010better} finds a satisfying assignment up to clause density $(1-o_k(1)) 2^k \log k / k$.
Bresler and the first author \cite{bresler2021ksat} showed that for an explicit $\kappa^* \approx 4.911$, random $k$-SAT is hard for low degree polynomials above clause density $(1+o_k(1)) \kappa^* 2^k \log k / k$, in the sense that such algorithms cannot succeed with probability too close to $1$ (and that the more restricted class of sequential local algorithms cannot succeed with even small probability).
We improve this result to strong low degree hardness.

\begin{corollary}{(Based on \cite[Theorem 2.6]{bresler2021ksat})}
\label{cor:BH}
	For any $\kappa > \kappa^* \approx 4.911$, there exists sufficiently large $k_*(\kappa)$ such that for all $k \ge k_*(\kappa)$ and $\alpha = \kappa 2^k \log k / k$, the following holds.
	If $\cA^\circ$ is a degree $D = o(N)$ function satisfying $\bbE[\|\cA^\circ(\by,\omega)\|^2] \le CN$, then for $\cA$ as in \eqref{eq:round-stable-alg},
	\begin{equation}
		\label{eq:BH-conclusion}
		\bbP\lt[\cA(\by,\omega,\vec U)\,\text{is a satisfying assignment of}\,\by\rt] = o_N(1).
	\end{equation}
\end{corollary}
In the below proof, given $\kappa > \kappa^*$ we will choose $k$ sufficiently large depending on $\kappa$ and $b$ sufficiently small depending on $(\kappa,k)$.
We set parameters:
\begin{align*}
	\eps &= \fr{\log (N/D)}{N}, &
	L &= \fr{b}{\eps^{1/4}}, &
	K &= \lt\lceil \fr{1}{b\eps} \rt\rceil, &
	b_0 &= bk.
\end{align*}
We generate a Markovian sequence $\by^{(0)},\ldots,\by^{(K)}$, where each $\by^{(t)}$ is marginally a sample from $\mu^{\otimes kM}$ and where $\by^{(t+1)}$ is obtained by resampling each of the $kM$ IID entries in $\by^{(t)}$ with probability $\eps$.
Let $h$ be the \emph{conditional overlap entropy} defined in \cite[Section 4.3]{bresler2021ksat} (and denoted $H(\cdots)$ therein).
The only property of it we will use Lemma~\ref{lem:conditional-overlap-entropy} below, which establishes a quantitative continuity estimate.
We use the following landscape obstruction.
\begin{lemma}[{Adaptation of \cite[Proposition 4.7(c)]{bresler2021ksat}}]
	\label{lem:ksat-ogp}
	There exist constants $(\beta,\eta)$ depending on $k,\kappa$ such that the following holds with probability $1-e^{-cN}$.
    There does not exist a sequence $0\le t_0 \le \cdots \le t_k \le K$ and assignments $\bx^0,\ldots,\bx^k \in \bSig_N$ such that:
    \begin{enumerate}[label=(\roman*)]
        \item For all $0\le \ell \le k$, $\bx^\ell$ satisfies the $k$-SAT formula $\by^{(t_\ell)}$.
        \item For all $1\le \ell \le k$, we have $h(\bx^\ell | \bx^0, \ldots, \bx^{\ell-1}) \in [\beta-\eta,\beta]$.
    \end{enumerate}
\end{lemma}
\begin{proof}
	This is proved by bounding the first moment of the number of such $(t_0,\ldots,t_k,\bx^0,\ldots,\bx^k)$.
	While \cite{bresler2021ksat} uses a slightly different correlated ensemble, the first moment contribution of any $(t_0,\ldots,t_k)$ is upper bounded by the case $t_0=\cdots=t_k$, and in this case the event fails to hold with probability $e^{-cN}$.
	The result follows by a union bound over the $N^{O(1)}$ sequences of $t_j$.
	We note that $[\beta-\eta,\beta]$ is denoted in \cite{bresler2021ksat} as $[\beta_+ \fr{\log k}{k}, \beta_+ \fr{\log k}{k}]$.
\end{proof}
We will need the following ``chaos" result.
Let $\bx^{(t)} = \cA(\by^{(t)},\omega,\vec U)$.
\begin{lemma}[{Adaptation of \cite[Proposition 4.7(b)]{bresler2021ksat}}]
	\label{lem:ksat-chaos}
	With probability $1-e^{-cN}$, there does not exist $j\le k$ and a sequence $0\le t_0 \le \cdots \le t_j \le K$, with $t_j \ge t_{j-1} + \fr{1}{b_0\eps}$ and assignment $\bx \in \Sigma_N$ satisfying the following:
	\begin{enumerate}[label=(\roman*)]
		\item $\bx$ satisfies $\by^{(t_j)}$.
		\item $h(\bx | \bx^{(t_0)},\ldots,\bx^{(t_{j-1})}) \le \beta$.
	\end{enumerate}
\end{lemma}
Note that we only allow $\bx$ to vary arbitrarily here, while $\bx^{(t_0)},\ldots,\bx^{(t_{j-1})}$ must depend only on their respective inputs $\by^{(t_\ell)}$, and not on $\by^{(t_j)}$.
\begin{proof}
	If $(\by^{(t)})_{t\le t_{j-1}}$ were independent of $\by^{(t_j)}$, this follows directly from \cite[Proposition 4.7(b)]{bresler2021ksat}.
	Here the correlation between $\by^{(t_{j-1})}$ and $\by^{(t_j)}$ is at most $(1-\eps)^{1/b_0\eps} \le e^{-1/b_0} = e^{-1/bk}$ (and $(\by^{(t)})_{t\leq t_{j-1}}$ is conditionally independent of $\by^{(t_j)}$ given $\by^{(t_{j-1})}$).
    For sufficiently small $b$, the lemma can be proved by the same first moment computation.
\end{proof}
Finally, we require the following continuity estimate on the conditional overlap entropy $h$.
For $\bx,\bx'\in \bSig_N$, let $\Delta(\bx,\bx') = \|\bx-\bx'\|^2/4 \in [0,N]$ denote the Hamming distance of $\bx,\bx'$.
\begin{lemma}[{\cite[Lemma 4.8]{bresler2021ksat}}]
	\label{lem:conditional-overlap-entropy}
	For any $\ell \in \bbN$ and $\bx,\bx',\by^0,\ldots,\by^{\ell-1} \in \bSig_N$ such that $\Delta(\bx,\bx') \le \fr{N}{2}$,
	\[
		\lt|
			h(\bx | \by^0,\ldots,\by^{\ell-1})
			- h(\bx' | \by^0,\ldots,\by^{\ell-1})
		\rt| \le h(\Delta(\bx,\bx')/N).
	\]
	The $h$ on the right-hand side denotes the binary entropy function $h(x) = - x \log x - (1-x) \log(1-x)$.
\end{lemma}
Similarly to above, we define ``success'' and ``stability'' events:
\begin{align*}
	\Ssolve &= \lt\{
		\text{$\bx^{(t)}$ satisfies $\by^{(t)}$ for all $0\le t\le K$}
	\rt\}, \\
	\Sstab &= \lt\{
		\text{$\Delta(\bx^{(t)},\bx^{(t+1)}) / N \le L^2 \eps^{1/2} / 4$ for all $0\le t\le K-1$}
	\rt\}.
\end{align*}
Let $\Sogp,\Schaos$ be the events in Lemmas~\ref{lem:ksat-ogp} and \ref{lem:ksat-chaos}, which hold with probability $1-e^{-cN}$.
\begin{lemma}[{Adaptation of \cite[Proof of Theorem 2.6]{bresler2021ksat}}]
    \label{lem:ksat-no-intersection}
    We have $\Ssolve \cap \Sstab \cap \Sogp \cap \Schaos = \emptyset$.
\end{lemma}
\begin{proof}
    Suppose $\Ssolve, \Sstab, \Schaos$ hold; we will contradict $\Sogp$.
    Let $t_0 = 0$ and recursively define $t_j$ for $1\leq j\leq k$ to be the smallest $t\geq t_{j-1}$ such that
    \begin{equation}
        \label{eq:ksat-iterative-moats}
        h(\bx^{(t)} | \bx^{(t_0)},\ldots,\bx^{(t_{j-1})}) \in [\beta-\eta,\beta].
    \end{equation}
    Note that $L^2\eps^{1/2} / 4 = b^2/4$.
    We set $b$ small enough that $b^2/4 \le 1/2$ and for $h$ the binary entropy function, $h(b^2/4) \le \eta$.
    Then, $\Sstab$ and Lemma~\ref{lem:conditional-overlap-entropy} ensure that as $t$ advances, the left-hand side of \eqref{eq:ksat-iterative-moats} never jumps over the right-hand interval.
    However, $\Schaos$ implies that $t_j \le t_{k-1} + \fr{1}{b_0\eps}$ is successfully chosen.
    Therefore, $t_k \le \fr{k}{b_0 \eps} = \fr{1}{b\eps} \le K$, so this procedure finds $(t_0,\ldots,t_k)$ before exhausting the times $\{0,\ldots,K\}$.
    Then, the existence of $(t_0,\ldots,t_k)$ and $(\bx^{(t_0)},\ldots,\bx^{(t_k)})$ contradicts $\Sogp$.
\end{proof}
\begin{proof}[Proof of Corollary~\ref{cor:BH}]
    Let $\psolve$ denote the left-hand side of \eqref{eq:BH-conclusion} and
    \[
        \punstable = \bbP\lt[\Delta(\bx^{(0)},\bx^{(1)}) / N \ge L^2\eps^{1/2}/4\rt]
        = \bbP\lt[\|\cA(\by^{(0)},\omega,\vec U) - \cA(\by^{(1)},\omega,\vec U)\| / \sqrt{N} \ge L\eps^{1/4} \rt].
    \]
    By the above discussion, $\bbP(\Sogp \cap \Schaos) = 1-e^{-cN}$.
    Lemmas~\ref{lem:bernoulli-correlation} and \ref{lem:indset-no-intersection} then imply
    \[
        (\psolve^2-\punstable)^{2K} \le \bbP(\Ssolve \cap \Sstab) \le e^{-cN} \qquad \implies \qquad
        \psolve \le \punstable^{1/2} + e^{-cN/4K}.
    \]
    These two terms are bounded similarly to \eqref{eq:pspin-punstable} (using Proposition~\ref{prop:sparse-bernoulli-fourier} in place of Proposition~\ref{prop:low-degree-stable}) and \eqref{eq:pspin-exponential}.
\end{proof}

\subsection{Maximum Independent Set in $G(N,1/2)$}
\label{subsec:dense-max-ind-set}

Finally, we turn to the maximum independent set problem on $G(N,1/2)$.
For this problem, the largest independent set has size $(2+o_N(1)) \log_2 N$, while a greedy algorithm finds an independent set of size $(1+o_N(1)) \log_2 N$ \cite{karp1976probabilistic}.
The latter value is conjectured to be the limit of all efficient algorithms, and \cite[Theorem 1.9]{wein2020independent} showed that surpassing this value is hard for degree $D\leq o(\log^2 N)$ polynomials, in that such algorithms fail with probability at least $e^{-\Omega(D)}N^{-2}$.
We upgrade this result to strong low degree hardness.
We note that the degree $\log^2 N$ arises because the main landscape obstruction occurs with probability $1-e^{-\Theta(\log^2 N)}$, which is consistent with the discussion in Subsection~\ref{subsec:strong-hardness-discussion}.
This range of degrees is expected to be sharp based on the low-degree prediction, since $e^{O(\log^2 N)}$ time suffices to find maximum independent sets via brute-force search.
% We also note that this degree is tight, as degree $\Omega(\log^2 N)$ is enough to find the maximum independent set by a brute force search.

In this application, we will treat $\by \sim G(N,1/2)$ as an element of $\Ber(1/2)^{\otimes \binom{N}{2}}$, and will identify a set of vertices $S\subseteq [N]$ with the element $\ind_S \in \{0,1\}^N$ (rather than $\{-1,1\}^N$ as above).
Rather than randomly rounding the output of $\cA^\circ$ as in \eqref{eq:round-stable-alg}, we will use a more stringent deterministic rounding scheme similar to \cite{gamarnik2020optimization,wein2020independent,bresler2021ksat}.
(This is because the stability estimates from Subsection~\ref{subsec:stability} are tailored for macroscopic distances of order $\sqrt{N}$ between solutions, which is not the case here.)
Define the function $\round : \bbR \to \{0,1,*\}$ by
\[
	\round(z) = \begin{cases}
		0 & |z| \le 1/2, \\
		1 & |z| \ge 1, \\
		* & \text{otherwise}.
	\end{cases}
\]
Furthermore, for $\bz \in \bbR^N$, let $\round(\bz) \in \{0,1,*\}^N$ denote the vector obtained by applying $\round$ entrywise to $\bz$.
Let $\Delta(\bx,\bx') = |\{i \in [N] : x_i \neq x'_i\}|$ denote the Hamming distance between $\bx,\bx' \in \{0,1,*\}^N$.
Let $\cP([N])$ denote the power set of $[N]$.
\begin{definition}
	For $b > 0$, a function $F : \{0,1,*\}^N \times \{0,1\}^{\binom{N}{2}} \to \cP([N]) \cup \{\err\}$ is \emph{$b$-repairing} if the following holds.
	If $F(\bz,\by) = S \neq \err$, then $S$ is an independent set of $\by$ and $\Delta(\ind_S,\round(\bz)) \le b \log_2 N$.
\end{definition}
We then let
\begin{equation}
	\label{eq:round-sparse-algorithm}
	\cA(\by,\omega) = F(\round(\cA^\circ(\by,\omega)),\by),
\end{equation}
for $F$ an arbitrary $b$-repairing function.
% We then define the following notion of solving the maximum independent set problem.
% \begin{definition}
% 	For $\iota,b > 0$, we say $\bx \in \bbR^N$ $(\iota,b)$-solves $\by$ if there exists $S\subseteq [N]$ such that:
% 	\begin{enumerate}[label=(\roman*)]
% 	 	\item $S$ is an independent set of $\by$.
% 	 	\item $|S| \ge (1+\iota) \log_2 N$.
% 	 	\item $\Delta(\ind_S,\round(\bx)) \le b \log_2 N$.
% 	 \end{enumerate}
% \end{definition}
In other words, we give $\cA$ the power to fix mistakes in $b \log_2 N$ entries of $\round(\cA^\circ(\by,\omega))$ in a computationally unbounded way, where all entries with value $*$ are considered mistakes.
(If there are too many mistakes, then $\cA$ must output $\err$ and fail.)
Our result in this setting is as follows.
\begin{corollary}[{Based on \cite[Theorem 1.9]{wein2020independent}}]
	\label{cor:wein-dense}
	For any $\iota > 0$, there exists a sufficiently small constant $b > 0$ such that the following holds.
	If $\cA^\circ$ is a degree $D = o(\log^2 N)$ function with $\bbE[\|\cA^\circ(\by,\omega)\|^2] \le C \log N$, then for any $\cA$ of the form \eqref{eq:round-sparse-algorithm} where $F$ is $b$-repairing,
	\begin{equation}
		\label{eq:wein-dense-conclusion}
		\bbP[\text{$\cA(\by,\omega)$ is an independent set of $\by$ of size at least $(1+\iota) \log_2 N$}] = o_N(1).
	\end{equation}
\end{corollary}
Throughout the below proof, we set $\iota$ sufficiently small and $b$ sufficiently small depending on $\iota$.
We then set parameters:
\begin{align*}
	\eps &= \fr{\log(\log^2 N / D)}{\log^2 N}, &
	% L &= BLAH, &
	K &= \lt\lceil \fr{1}{b\eps} \rt\rceil, &
	m &= 1 + \lt\lceil \fr{5}{\iota^2} \rt\rceil, &
	b_0 &= bm.
\end{align*}
We generate a Markovian sequence $\by^{(0)},\ldots,\by^{(K)}$ where $\by^{(t+1)}$ is obtained by resampling each entry of $\by^{(t)}$ with probability $\eps$.
Let $S^{(t)} = \cA(\by^{(t)},\omega)$ and $\bz^{(t)} = \cA^\circ(\by^{(t)},\omega)$.
The following three lemmas are analogous to Lemmas~\ref{lem:indset-ogp}, \ref{lem:indset-chaos}, and \ref{lem:indset-max}, and we omit their proofs.
\begin{lemma}
	\label{lem:indset-dense-ogp}
	With probability $1-e^{-c\log^2 N}$, there do not exist $0\le t_1 \le \cdots \le t_m \le K$ and subsets $S_1,\ldots,S_m \subseteq [N]$ satisfying the following:
	\begin{enumerate}[label=(\roman*)]
		\item $S_j$ is an independent set in $\by^{(t_j)}$ for each $1\le j\le m$.
		\item $|S_j| \ge (1+\iota) \log_2 N$ for each $1\le j\le m$.
		\item $|S_j \setminus (\cup_{\ell < j} S_\ell)| \in [\fr14 \iota \log_2 N, \fr12 \iota \log_2 N]$ for each $2\le j\le m$.
	\end{enumerate}
\end{lemma}
\begin{lemma}
	\label{lem:indset-dense-chaos}
	With probability $1-e^{-c\log^2 N}$ there does not exist $j\le m$ and a sequence $0\le t_1 \le \cdots \le t_j \le K$ with $t_j \ge t_{j-1} + \fr{1}{b_0 \eps}$ and set $S\subseteq [N]$ satisfying the following:
	\begin{enumerate}[label=(\roman*)]
		\item $S$ is an independent set in $\by^{(t_j)}$.
		\item $|S| \ge (1+\iota) \log_2 N$.
		\item $|\cup_{\ell < j} S^{(t_\ell)}| \ge \iota^{-3} \log_2 N$.
		\item $|S \cap (\cup_{\ell < j} S^{(t_\ell)})| \ge \iota \log_2 N$.
	\end{enumerate}
\end{lemma}
\begin{lemma}
	\label{lem:indset-dense-max}
	With probability $1-e^{-c\log^2 N}$, there is no independent set in any $\by^{(k)}$ of size larger than $(2+\iota) \log_2 N$.
\end{lemma}
Define analogously to above
\begin{align*}
	\Ssolve &= \lt\{
		\text{$S^{(t)}$ is an independent set of $\by^{(t)}$ of size $\ge (1+\iota) \log_2 N$, for all $0\le t\le K$}
	\rt\}\\
	\Sstab &= \lt\{
		\text{$|S^{(t)} \Delta S^{(t+1)}| \le \fr14 \iota \log_2 N$ for all $0\le t\le K-1$}
	\rt\},
\end{align*}
where by convention neither $\Ssolve$ nor $\Sstab$ holds if any of the $S^{(t)}$ are $\err$.
Let $\Sogp, \Schaos, \Smax$ be the events in Lemmas~\ref{lem:indset-dense-ogp}, \ref{lem:indset-dense-chaos}, and \ref{lem:indset-dense-max}.
Analogously to Lemma~\ref{lem:indset-no-intersection}:
\begin{lemma}
	\label{lem:indset-dense-no-intersection}
	We have $\Ssolve \cap \Sstab \cap \Sogp \cap \Schaos \cap \Smax = \emptyset$.
\end{lemma}
\begin{proof}[Proof of Corollary~\ref{cor:wein-dense}]
	Let $\psolve$ be the left-hand side of \eqref{eq:wein-dense-conclusion} and
	\[
		\punstable = \bbP\lt[|S^{(1)} \Delta S^{(2)}| \ge \fr14 \iota \log_2 N\rt],
	\]
	where the event in the probability does not hold if either of $S^{(1)}$ or $S^{(2)}$ is $\err$.
	Since $\bbP(\Sogp \cap \Schaos \cap \Smax) \ge 1-e^{-c\log^2 N}$, Lemmas~\ref{lem:bernoulli-correlation} and \ref{lem:indset-dense-no-intersection} imply
	\[
		(\psolve^2 - \punstable)^{2K} \le \bbP(\Ssolve \cap \Sstab) \le e^{-c\log^2 N} \qquad \implies \qquad
		\psolve \le \punstable^{1/2} + e^{-c\log^2 N / 4K}.
	\]
	Let $J_t$ be the set of coordinates where $\ind_{S^{(t)}}$ differs from $\round(\bz^{(t)})$.
	Since $F$ is $b$-repairing, if $S^{(t)} \neq \err$, then $|J_t| \le b\log_2 N$.
	Thus, (on the event $S^{(1)},S^{(2)} \neq \err$)
	\[
		|S^{(1)} \Delta S^{(2)}|
		\le \| (\round(\bz^{(1)}) - \round(\bz^{(2)}))_{[N]\setminus (J_1 \cup J_2)}\|_2^2 + |J_1| + |J_2|
		\le 4\|\bz^{(1)} - \bz^{(2)}\|_2^2 + 2b\log_2 N.
	\]
	We set $b \le \fr{1}{16} \iota$, so that $\fr14 \iota \log_2 N - 2b \log_2 N \ge \fr18 \log_2 N$, and thus
	\begin{align*}
		\punstable \le \bbP\lt[
			\|\bz^{(1)} - \bz^{(2)}\|_2^2
			\ge \fr{1}{32} \iota \log_2 N
		\rt]
		&\stackrel{\eqref{eq:low-degree-l2-stable}}{\le}
		\fr{2D\eps \cdot C \log N}{\fr{1}{32} \iota \log_2 N} \\
		&\asymp D\eps
		\le \sqrt{\fr{D}{\log^2 N}}
		= o_N(1).
	\end{align*}
	Furthermore, (for dimension-free but varying $c$)
	\[
		e^{-c\log^2 N / 4K}
		= e^{-c\eps \log^2 N }
		= (D/\log^2 N)^c
		= o_N(1).
	\]
	Combining concludes the proof.
\end{proof}





\section{Spherical Langevin Dynamics Does Not Find Wells}


In this section, we prove Theorem~\ref{thm:langevin-fails-pseudo-wells}, that Langevin dynamics does not find wells.
Below, $H_N$ will now be a mixed $p$-spin Hamiltonian from \eqref{eq:def-hamiltonian}, with fixed correlation function $\xi(t)=\sum_{k=2}^{\bar k} \gamma_k^2 t^k$.
In Subsection~\ref{subsec:main-langevin-proof} we state a few useful lemmas and use them to deduce Theorem~\ref{thm:langevin-fails-pseudo-wells}.
We then verify these lemmas in the following two subsections.



\subsection{Main Argument}
\label{subsec:main-langevin-proof}



Our proof of Theorem~\ref{thm:langevin-fails-pseudo-wells} studies multiple trajectories of Langevin dynamics on the same Hamiltonian $H_N$, but with correlated initialization and driving Brownian motion.
We first explain the pair-wise correlation structure that will be used.
Take $\bg,\wt\bg\stackrel{IID}{\sim}\cN(0,I_N)$ and $\bB_{[0,T]},\wt\bB_{[0,T]}$ to be IID Brownian motions on $\bbR^N$, and set:
\begin{equation}
\label{eq:langevin-interpolation}
\begin{aligned}
    \bg_{p}&=p\,\bg+\sqrt{1-p^2}\,\wt\bg,
    \\
    \bB_{t,p}&=p\,\bB_t + \sqrt{1-p^2}\,\wt\bB_{t}.
\end{aligned}
\end{equation}
We then let $\bx_{[0,T],p}$ be the trajectory of Langevin dynamics initialized at $\frac{\bg_{p}\sqrt{N}}{\|\bg_{p}\|}$ and driven by $\bB_{t,p}$.
Then $\bx_{[0,T],p}$ has the same law as $\bx_{[0,T]}$, even after conditioning on $H_N$.
We say this pair of Langevin trajectories is $p$-correlated.


The first lemma we will use ensures concentration of the overlaps between these correlated trajectories, and of the gradient norm for a single trajectory.
This is proved in Subsection~\ref{subsec:langevin-concentration}.


\begin{lemma}
\label{lem:quantities-concentrate}
For any $T$ the following quantities concentrate exponentially in the sense that for any $\delta > 0$, they lie in an interval $I_N(T,\delta)\subseteq \bbR$ of length $\delta$ with probability $1-e^{-cN}$ for some $c(T,\delta)$, when $N$ is sufficiently large. Furthermore the value of $c$ is uniform in the value $p\in [0,1]$.
\begin{enumerate}[label=(\Roman*)]
    \item
    \label{it:real-langevin-overlap-concentration}
    $\la\bx_{T},\bx_{T,p}\ra/N$.
    \item
    \label{it:real-langevin-gradient-concentration}
    $\|\nabla H_N(\bx_{T})\|/\sqrt{N}$.
\end{enumerate}
\end{lemma}

Next for each $N$ and time $T$, define the correlation function 
\[
\chi_{N,T}(p)
=
\bbE[\la\bx_{T},\bx_{T,p}\ra/N]
\]
We will use the following two lemmas on its behavior.
Lemma~\ref{lem:overlap-monotone} is proved here, while Lemma~\ref{lem:langevin-orthogonal} is proved in Subsection~\ref{subsec:orthogonal-langevin}.

\begin{lemma}
\label{lem:overlap-monotone}
For any $T>0$, the function $p\mapsto \chi_{N,T}(p)$
is increasing.
\end{lemma}


\begin{proof}[Proof of Lemma~\ref{lem:overlap-monotone}]
    We can identify $(H_N,\bg,\bB_{[0,T]})$ with a countably infinite sequence of IID standard Gaussian variables, as follows.
    We identify $H_N$ with its disorder coefficients $g_{i_1,\ldots,i_k}$ and $\bg$ with its Gaussian entries.
    We then identify each coordinate $(\bB_{[0,T]})_i$ (a one-dimensional standard Brownian motion on $[0,T]$) of $\bB_{[0,T]}$ with the countably infinite sequence $((\bB_T)_i / \sqrt{T}, G_{i,0}, G_{i,1}, \ldots)$ for $G_{i,j}$ defined as follows.
    Define the Brownian bridge
    \[
    	(\widehat \bB_t)_i = (\bB_t)_i - \fr{t}{T} (\bB_T)_i,
    \]
    and let $G_{i,j}$ be the normalized Fourier coefficient
    \[
    	G_{i,j} = Z_{i,j} / \bbE[Z_{i,j}^2]^{1/2}, \qquad
    	Z_{i,j} = \int_0^T \sin\lt(\fr{j \pi t}{T}\rt) (\widehat \bB_t)_i \,\de t.
    \]
    The multivariate Hermite polynomials corresponding to these Gaussians form an orthonormal basis of the space of $L^2$ functions of $(H_N,\bg,\bB_{[0,T]})$ (see e.g. \cite[Theorem 8.1.7]{lunardi2015infinite}).

    Each coordinate $(\bx_T)_i$ is a bounded, and thus $L^2$, function of $(H_N,\bg,\bB_{[0,T]})$.
    We can thus write $\bx_T$ in this Hermite basis.
    We write $\bx_{T,p}$ in the analogous Hermite basis for $(H_N,\bg_{p},\bB_{[0,T],p})$, where $\bg_{p},\bB_{[0,T],p}$ are $p$-correlated with $\bg,\bB_{[0,T]}$.
    The identity \eqref{eq:hermite-correlation} gives the desired monotonicity.
\end{proof}



\begin{lemma}
\label{lem:langevin-orthogonal}
For any fixed $T$ and $\xi$, we have $\lim_{N\to\infty} \chi_{N,T}(0)=0$.
\end{lemma}


We note that Lemma~\ref{lem:langevin-orthogonal} is the only place in this section where the absence of external field is used.
Additionally when $\xi$ is an even polynomial, one has $\chi_{N,T}(0)=0$ exactly at finite $N$ because $\bbE[\bx_T|H_N]=0$ by antipodal symmetry.
The proof for general $\xi$ requires more work, and is based on state evolution analysis of an associated approximate message passing iteration.



Now we turn to proving Theorem~\ref{thm:langevin-fails-pseudo-wells}.
We will consider $N$ simultaneously correlated trajectories (a large constant depending on other dimension-free parameters would also suffice).
Thus for $1\leq n\leq N$ let $\bx_{t,p,n}$ be a conditionally independent (given $(\bg,\bB_{[0,T]},H_N)$) copy of the correlated dynamics constructed previously:
\begin{align}
    \bg_{p,i}&=p\bg+\sqrt{1-p^2}\wt\bg_{n},
    \\
    \bB_{t,p,n}&=p\bB_t + \sqrt{1-p^2}\wt\bB_{t,n}.
\end{align}
Note that $(\bx_{T,p,n},\bx_{T,p,m})$ are $p^2$-correlated for $n\neq m$.



% \begin{proposition}
% For any $\xi$ and $\gamma>0$ there exists $\delta$ such that for any $\beta,T>0$ and $N$ sufficiently large, the probability that $\bx_{t,0}$ is a $(\gamma,\delta)$-well is at most $e^{-cN}$.
% \end{proposition}


\begin{proof}[Proof of Theorem~\ref{thm:langevin-fails-pseudo-wells}]
    We choose $\eps>0$ small depending on $(\gamma,\xi)$, and $\delta$ small depending on $(\eps,\gamma,\xi)$.
    We then let $\beta,T$ be arbitrary and take $N$ large depending on all of these quantities.
    In light of Lemma~\ref{lem:langevin-orthogonal} and the trivial identity $\chi_{N,T}(1)=1$, for large $N$ there exists $p\in (0,1)$ such that
    \[
    \chi_{N,T}(p)=1-\eps.
    \]
    Then Lemma~\ref{lem:overlap-monotone} implies that
    \begin{equation}
    \label{eq:almost-monotone-consequence}
    \chi_{N,T}(p^2)\leq 1-\eps.
    \end{equation}
    We fix this value of $p$ below and consider the behavior of $\bx_{T}$ as well as the correlated outputs $\breve\bx_{T,n}\equiv \bx_{T,p,n}$ for each $1\leq n\leq N$.
    We assume the conclusions of Proposition~\ref{prop:gradients-bounded} and Lemma~\ref{lem:spectrum-approx} hold, and the conclusion of Lemma~\ref{lem:quantities-concentrate} holds for all $\binom{N+1}{2}$ pairs among $(\bx_T,\breve\bx_{T,1},\ldots,\breve\bx_{T,N})$ (with correlation value $p$ for pairs $(\bx_T,\breve \bx_{T,n})$ and $p^2$ for pairs $(\bx_{T,m},\breve \bx_{T,n})$.)
    By a union bound, this occurs with probability $1-e^{-cN}$. (Note that the conclusion of Lemma~\ref{lem:spectrum-approx} is monotone in $\delta$, and therefore holds with probability $1-e^{-cN}$ if $\delta$ is taken sufficiently small.)

    We will show that on this event,  $\bx_{T}$ is a not $(\gamma,\delta)$-well.
    Assume otherwise for the sake of contradiction.

    % We will assume that $\bx_{T}$ is a $(\gamma,\delta)$-well, and that the guarantees of Proposition~\ref{prop:gradients-bounded}, Lemma~\ref{lem:spectrum-approx}, and Lemma~\ref{lem:quantities-concentrate} hold for all $\binom{N+1}{2}$ pairs with error parameter $\delta$ (with correlation value $p^2$ on all pairs not involving $\bx_{T}$, as mentioned above).
    % We will use these conditions to derive a (deterministic) contradiction.
    % Since the auxiliary assumptions hold with probability $1-e^{-cN}$, this implies Theorem~\ref{thm:langevin-fails-pseudo-wells}.


    For each $1\le n \le N$, let $\by_{n}\in \bx_{T}^{\perp}$ be the unit tangent vector to $\cS_N$ at $\bx_{T}$ in the direction pointing from $\bx_{T}$ to $\breve\bx_{T,n}$ (i.e. such that the shortest path geodesic from $\bx_{T}$ in direction $\by_n$ passes through $\wt\bx_{T,n}$ within distance $O(\sqrt{\eps N})$).
    We first argue that $\nabla_{\sph}^2 H_N(\bx_{T})\by_n$ must have small norm for each $n$.
    Indeed, an elementary Taylor expansion of the gradient (using Proposition~\ref{prop:gradients-bounded} to control the error term) shows
    \[
    \|\nabla_{\sph} H_N(\breve\bx_{T,n})\|
    \geq
    \sqrt{\eps N}
    \|\nabla_{\sph}^2 H_N(\breve\bx_{T,n})\cdot \by_n\|
    -
    O(\eps \sqrt{N})
    -
    \|\nabla_{\sph} H_N(\bx_{T})\|.
    \]
    As we assumed the conclusions of Lemma~\ref{lem:quantities-concentrate} hold and that $\bx_{T}$ is a $(\gamma,\delta)$-well, we have also
    \[
    \|\nabla_{\sph} H_N(\breve \bx_{T,n})\|
    \leq
    \|\nabla_{\sph} H_N(\bx_{T})\|+\delta\sqrt{N}
    \leq
    2\delta\sqrt{N}.
    \]
    Since $\delta$ is small depending on $\eps$, rearranging the preceding two displays shows that
    \begin{equation}
    \label{eq:yn-near-hessian-kernel}
    \|\nabla_{\sph}^2 H_N(\breve\bx_{T,n})\cdot \by_n\|
    \leq
    O(\sqrt{\eps}).
    \end{equation}
    Next we use Lemma~\ref{lem:spectrum-approx}, with the same constant $\delta$ as above.
    Combined with the definition of $(\gamma,\delta)$-wells, it implies that for a constant $K(\gamma,\eps,\delta)$ we have
    \[
    \lambda_K(\nabla_{\sph}^2 H_N(\bx_{T}))
    \leq -\gamma/2.
    \]
    Thus, let us define $S_K\subseteq \bx_{T}^{\perp}$ to be the span of the top $K$ eigenvectors of $\nabla_{\sph}^2 H_N(\bx_{T})$.
    Then we may decompose each $\by_n$ into
    \[
    \by_n = \bv_n + \bw_n
    \]
    with $\bv_n\in S_K$ and $\bw_n\in S_K^{\perp}\cap \bx_{T}^{\perp}$.
    Then \eqref{eq:yn-near-hessian-kernel} implies that for each $n$, we have:
    \[
    \|\bw_n\|\leq O(\sqrt{\eps}/\gamma).
    \]
    Since $N$ is much larger than $K$, the pigeonhole principle implies that there exist $n,m$ with $\|\bv_n-\bv_m\|\leq \eps$.
    This means
    \begin{equation}
    \label{eq:pigeonhole-tangent}
        \|\by_n-\by_m\|\leq O(\eps + \sqrt{\eps}/\gamma)\leq O(\sqrt{\eps}/\gamma)
    \end{equation}
    By the assumption that Lemma~\ref{lem:quantities-concentrate} is in force, the distances $\|\bx_{T}-\breve\bx_{T,n}\|$ and $\|\bx_{T}-\breve\bx_{T,m}\|$ differ by at most $\eps\sqrt{N}$, and are at each at most $O(\sqrt{\eps N})$.
    It follows from \eqref{eq:pigeonhole-tangent} that
    \begin{equation}
    \label{eq:pigeonhole-outputs}
        \|\breve\bx_{T,n}-\breve\bx_{T,m}\|\leq O(\eps\sqrt{N}).
    \end{equation}
    However this means $\la \breve\bx_{T,n},\breve\bx_{T,m}\ra/N \geq 1-O(\eps^2)$.
    This contradicts \eqref{eq:almost-monotone-consequence}, completing the proof.
\end{proof}




\subsection{Concentration Properties of Langevin Dynamics}
\label{subsec:langevin-concentration}
% Below, we view $\bx_T$ as a function of the triple $(\bx_0,\bB_{[0,T]},H_N)$.
% We metrize $\bx_0$ and $H_N$ via the (un-normalized) Euclidean norm, and $\bB_{[0,T]}$ by the supremum norm, so that such triples lie within a metric space $\cM$.
% We endow $\cM$ with the product measure $\mu$ which is uniform on $\cS_N$ in the first component, and the usual Gaussian and Wiener measures on the latter components.




Here we prove Lemma~\ref{lem:quantities-concentrate} on concentration of overlaps and gradient norms.
For our analysis, it will be useful to consider an approximation to the Langevin dynamics which enjoys additional Lipschitz properties.
Given $\bg\in\bbR^N$ we let
\[
\hat \bg
=
\frac{\bg}{\max(1/2,\|\bg\|/\sqrt{N})}.
\]
We take $\bg\sim\cN(0,I_N)$ and use it to couple the uniformly initialized Langevin dynamics with a proxy process $\bx_{[0,T]}^{(K)}$ using the same driving $\bB_{[0,T]}$ and initializations:
\begin{equation}
\label{eq:proxy-coupling-init}
\begin{aligned}
    \bx_0&=\bg\sqrt{N}/\|\bg\|,
    \\
    \bx_0^{(K)}&=\hat\bg.
\end{aligned}
\end{equation}
The point is simply that $\bx_0^{(K)}$ is a Lipschitz function of $\bg$ such that $\bx=\bx_0^{(K)}$ with probability $1-e^{-cN}$.
Here the constant $K>0$ is a parameter in the latter process. With $\bar k$ as in \eqref{eq:def-hamiltonian}, we define:
\[
f_K(r)=K(r-1)^2 + (r^2-1)^{\bar k}.
\]
Then the auxiliary full-space diffusion $\bx_{[0,T]}^{(K)}$ is defined by the SDE:
\begin{equation}
\label{eq:full-space-langevin}
\de \bx_t^{(K)}
=
\Big(
\beta \nabla H_N(\bx_t^{(K)})
-
f_K'(\|\bx_t^{(K)}\|^2/N)\bx_t^{(K)}
\Big)\de t
+
\sqrt{2}\,\de \bB_t.
\end{equation}


We will view $\bx_T^{(K)}$ as a function of $(\bg,\bG^{(2)},\dots,\bG^{(\bar k)},\bB_{[0,T]})$, typically abbreviated $(\bg,H_N,\bB_{[0,T]})$
We metrize $\bB_{[0,T]}$ by the supremum norm $\|\bB_{[0,T]}-\bB'_{[0,T]}\|=\sup_{t\in [0,T]}\|\bB_t-\bB'_t\|$, and the remaining arguments via the (un-normalized) Euclidean norm so that such triples lie within a metric space $\cM=\cM_N$.
We endow $\cM$ with the product measure $\mu$, which is given by the usual Wiener measure on the last component and standard Gaussian measure on the other components.
% Given $C>0$, we define
% \[
% \cM_C
% =
% \{(\bg,H_N,\bB_{[0,T]})~:~
% \|\bg\|\leq C\sqrt{N}, H_N\in K_N(C),
% \]
% We recall that $K_N(C)$ was defined in Proposition~\ref{prop:gradients-bounded}.

\begin{proposition}
\label{prop:langevin-approx-lipschitz}
For positive $T,\eps$, there exist constants $L,K,c$ such that for $N$ sufficiently large, there exists $\cM^{\circ}=\cM^{\circ}_N(T,\eps,L,K,c)\subseteq \cM$ with $\mu(\cM^{\circ})\geq 1-e^{-cN}/2$ such that the following hold.
\begin{enumerate}[label=(\alph*)]
    \item
    \label{it:langevin-approx-lipschitz-1}
    The restriction $\bx_T^{(K)}\big|_{\cM^{\circ}}:\cM^{\circ}\to\bbR^N$ is an $L$-Lipschitz function.
    \item
    \label{it:langevin-approx-lipschitz-2}
    For the coupling of \eqref{eq:proxy-coupling-init}, then
    $\|\bx_T^{(K)}-\bx_T\|/\sqrt{N}\leq \eps$ holds for all $(\bx_0,H_N,\bB_{[0,T]})\in\cM^{\circ}$.
\end{enumerate}
\end{proposition}

\begin{proof}
    We choose $K$ large depending on $(T,\eps)$ and $L$ large depending on $(K,T,\eps)$ and finally $c$ small depending on $(L,K,T,\eps)$.
    Note that $\bg\mapsto \bx_0^{(K)}$ is $2$-Lipschitz.
    By composition, \cite[Lemma 2.6]{ben2006cugliandolo} shows that $\bx_t^{(K)}$ is $L$-Lipschitz on a subset of $\cM$ with $\mu$-measure at least $1-e^{-cN}/4$.
    Noting that $\bx_0=\bx_0^{(K)}$ with probability $1-e^{-cN}$, \cite[Lemma 3.1]{sellke2023threshold} proves that
    \[
    \bbP[\|\bx_T^{(K)}-\bx_T\|/\sqrt{N}\leq \eps/2]\geq 1-e^{-cN}/4.
    \]
    Defining $\cM^{\circ}$ by the intersection of these two events completes the proof.
\end{proof}



Let $\ocM$ be the space of tuples $(\bg,\wt\bg,\bB_{[0,T]},\wt\bB_{[0,T]},H_N)$, endowed with the natural product measure $\omu$.
Fixing $p\in [0,1]$ and a choice of constants $(T,\eps,L,K,c)$ defining $\cM^{\circ}$, we let $\ocM_{p}^{\circ}(T,\eps,L,K,c)\subseteq\ocM$ consist of those tuples such that
\[
(\bg,\bB_{[0,T]},H_N),
(\bg_{p},\bB_{[0,T],p},H_N),
\in \cM^{\circ}(T,\eps,L,K,c).
\]
Since $(\bg_{p},\bB_{t,p},H_N)\stackrel{d}{=}(\bg,\bB_{[0,T]},H_N)$ for any $p$, we have $\omu(\ocM_{p}^{\circ})\geq 1-e^{-cN}$ when the relevant parameters are as in Proposition~\ref{prop:langevin-approx-lipschitz}.


% \begin{proposition}
% \label{prop:langevin-concentration}
% The following quantities concentrate exponentially, in the sense that for any $\eps$ they are within $\eps$ of their median value with probability at least $1-e^{-c(\eps)N}$.
% \begin{itemize}
%     \item $\la\bx_{T,p},\bx_{T,p'}\ra/N$.
%     \item $\la\bx_{T,p},\bx_{T,p'}'\ra/N$.
%     \item $H_N(\bx_{T,p,n})/N$.
%     \item
%     $\|\nabla H_N(\bx_{T,p})\|/\sqrt{N}$.
% \end{itemize}
% \end{proposition}

\begin{proposition}
\label{prop:langevin-concentration}
For any $T,\eps,K$, there exist $L,c$ such that for $N$ sufficiently large, uniformly in $(p,p')$, the following quantities are $L/\sqrt{N}$-Lipschitz functions of $(\bg, \wt\bg, \bB_{[0,T]},\wt\bB_{[0,T]},H_N)$ on $\ocM^\circ_{p}(T,\eps,L,K,c)$:
\begin{enumerate}[label=(\roman*)]
    \item
    \label{it:langevin-overlap-concentration}
    $\la\bx_{T}^{(K)},\bx_{T,p}^{(K)}\ra/N$.
    \item
    \label{it:langevin-gradient-concentration}
    $\|\nabla H_N(\bx_{T}^{(K)})\|/\sqrt{N}$.
\end{enumerate}
\end{proposition}


\begin{proof}
    We focus on \ref{it:langevin-overlap-concentration}, explaining the small changes for \ref{it:langevin-gradient-concentration} at the end.
    Note that the map $(\bx,\bx')\mapsto \la\bx,\bx'\ra/N$ is $O(1/\sqrt{N})$-Lipschitz on the set $\{(\bx,\bx'):\|\bx\|,\|\bx'\|\leq 2\sqrt{N}\}$.
    By Proposition~\ref{prop:langevin-approx-lipschitz}\ref{it:langevin-approx-lipschitz-2}, this condition holds for $(\bx_{T,p_1,1}^{(K)},\bx_{T,p_2,2}^{(K)})$ for data within the set $\ocM^{\circ}_{p_1,p_2}$.
    By composing with Proposition~\ref{prop:langevin-approx-lipschitz} and \eqref{eq:langevin-interpolation}, we find that
    \[
    (\bg, \wt\bg, \bB_{[0,T]},\wt\bB_{[0,T]},H_N) \mapsto
    \la\bx_{T,p_1,1}^{(K)},\bx_{T,p_2,2}^{(K)}\ra/N
    \]
    is $O(1/\sqrt{N})$ Lipschitz on $\ocM^\circ_{p}(T,\eps,L,K,c)$, proving \ref{it:langevin-overlap-concentration}.

    For case \ref{it:langevin-gradient-concentration}, the only change is that we may without loss of generality assume $\cM^{\circ}$ in Proposition~\ref{prop:langevin-approx-lipschitz} includes only those $H_N$ obeying Proposition~\ref{prop:gradients-bounded}.
    Then $\bx\mapsto \|\nabla H_N(\bx)\|/\sqrt{N}$ is $O(1/\sqrt{N})$-Lipschitz on $\|\bx\|\leq 2\sqrt{N}$.
    This implies a similar Lipschitz guarantee on $\ocM^{\circ}_{p}$, again by composition.
\end{proof}


We now deduce Lemma~\ref{lem:quantities-concentrate} from Proposition~\ref{prop:langevin-concentration}.


\begin{proof}[Proof of Lemma~\ref{lem:quantities-concentrate}]
    Since both quantities \ref{it:langevin-overlap-concentration}, \ref{it:langevin-gradient-concentration} in Proposition~\ref{prop:langevin-concentration} are scalar functions, by Kirszbraun's extension theorem they admit extensions to all of $\ocM$ with the same Lipschitz constant.
    Recalling Proposition~\ref{prop:gradients-bounded}, the estimate from Proposition~\ref{prop:langevin-approx-lipschitz} shows that \ref{it:langevin-overlap-concentration}, \ref{it:langevin-gradient-concentration} are respectively within $\delta$ of \ref{it:real-langevin-overlap-concentration}, \ref{it:real-langevin-gradient-concentration} with probability $1-e^{-cN}$.
    Since $(\ocM,\omu)$ obeys a logarithmic Sobolev inequality with constant $O(1)$ (see \cite{ben2006cugliandolo} for more discussion), applying concentration of measure for Lipschitz functions on $\ocM$ completes the proof.
\end{proof}



\subsection{Orthogonality of Independent Langevin Trajectories}
\label{subsec:orthogonal-langevin}


Here we prove Lemma~\ref{lem:langevin-orthogonal}.
The method uses a different auxiliary algorithm known as approximate message passing (AMP) to approximate the Langevin dynamics.
This technique was introduced by \cite{celentano2021high} to study noise-less continuous-time dynamics of a similar flavor (in fact it is suggested therein that the method should also suffice to analyze Langevin dynamics).
However we do not derive the equations governing the dynamics, but only verify the far simpler Lemma~\ref{lem:langevin-orthogonal}.
We note that AMP can be shown to have dimension-free Lipschitz constant in various parameters (see \cite[Section 6]{gamarnik2019overlap} 
), and thus should also suffice to imply Lemma~\ref{lem:quantities-concentrate}.
However we felt the proof in the previous subsection was more approachable.


Fixing $\eta>0$, the relevant AMP is initialized at $\bw_0^{\eta}\sim \cN(0,I_N)$ and defined for recursively determined ($N$-independent) constants $(A_{j,k}^{\eta})_{0\leq j\leq k}$ and $(B_{j,k}^{\eta})_{k\geq 0}$ by
\begin{equation}
\label{eq:discrete-time-AMP}
\begin{aligned}
\by^{\eta}_{k}
&=
\beta \eta\nabla H_N(\bx^{\eta}_k)
-
\ons^{\eta}_k;
\\
\bx^{\eta}_{k}
&=
\frac{\bw^{\eta}_{k}}{\sqrt{C^\eta_{k}}};
\\
\bw^{\eta}_{k}
&=
\bx_{k-1}^{\eta}
+
\beta \eta\nabla H_N(\bx^{\eta}_{k-1})
+
\sqrt{2\eta} \bg_{k-1}
\\
&=
\bx^{\eta}_{k-1}
+
\by^{\eta}_{k-1}
+
\ons^{\eta}_{k-1}
+
\sqrt{2\eta} \bg_{k-1}
\\
&=
\sum_{j=0}^{k-1}
\Big(
A_{j,k}^{\eta} \by^{\eta}_{j}
+
B_{j,k}^{\eta} \bg_j
\Big)
.
\end{aligned}
\end{equation}
Here
\[
C_{k}^{\eta}=\plim_{N\to\infty}\la \bw^{\eta}_{k},\bw^{\eta}_{k}\ra/N
\]
is determined by the state evolution recursion, and the Onsager terms $\ons^{\eta}_k$ are described below.
AMP algorithms of this type have been studied since \cite{bolthausen2014iterative,donoho2009message,bayati2011dynamics,javanmard2013state}; in these works, $H_N$ is quadratic and so $\nabla H_N(\cdot)$ is just multiplication by the corresponding random matrix.
The specific iteration above falls under the framework of \cite[Theorem 2]{huang2024optimization} which incorporates both random tensors and external Gaussian noise $\bg_k$.
Said state evolution result characterizes the iteration above in terms of an auxiliary centered Gaussian process $(Y^{\eta}_0,Y^{\eta}_1,\dots)$ with recursively defined covariance:
\begin{equation}
\label{eq:state-evolution}
    \bbE[Y^{\eta}_{k+1}Y^{\eta}_{j+1}]
    =
    \beta^2 \eta^2 \xi'\big(\bbE[X^{\eta}_{k}X^{\eta}_{j}]\big).
\end{equation}
Here the relevant random variables are defined as follows.
$G_0,G_1,\ldots \sim \cN(0,1)$ are IID standard Gaussians.
$W^{\eta}_k$ and $X^{\eta}_k$ are defined by:
\begin{align}
\notag
W_{k+1}^{\eta}
&=
X_k^{\eta}+Y_{k}^{\eta}+\ONS^{\eta}_k+\sqrt{2\eta} G_k,
\\
\label{eq:X-amp-def}
X_{k+1}^{\eta}
&=
\frac{W_{k+1}^{\eta}}{\sqrt{\bbE[(W_{k+1}^{\eta})^2]}},
\\
\label{eq:Onsager-formula}
\ONS_{k}^{\eta}
&=
\sum_{i=0}^{k-1}
\lt[
\xi''\Big(
\bbE[X_{k}^{\eta} X_i^{\eta}]
\Big)
\cdot
\lt(\frac{A_{i,k}^{\eta}}{\sqrt{C_{k}^{\eta}}}\rt)
\cdot
X_i^{\eta}
\rt]
% \bbE\lt[\frac{\partial f_k}{\partial Y_i^{\eta}}\rt]
\\
\label{eq:coefficients-determined}
&\equiv
\sum_{j=0}^k
\Big(
A_{j,k+1}^{\eta} Y^{\eta}_{j}
+
B_{j,k+1}^{\eta} G_j,
\Big)
.
\end{align}
Here the upper-case $\ONS$ random variables are defined on the same probability space as the $X,Y$ variables.
The formula \eqref{eq:Onsager-formula} is most easily read off from \cite[Equation (3.2)]{ams20} (which does not technically allow for the auxiliary randomness variables $G_i$), and can also be recovered from \cite[Theorem 2]{huang2024optimization}.
This uniquely determines the coefficients in \eqref{eq:coefficients-determined}.
One can easily check that the recursions \eqref{eq:state-evolution} and below close, thus uniquely defining a joint distribution on scalar random variables.
The state evolution result from \cite[Theorem 2]{huang2024optimization} then asserts that these recursively defined variables describe the behavior of the AMP iterates in a typical coordinate.




To model independent pairs of Langevin trajectories, let $\bx^{\eta}_i,\wt\bx^{\eta}_i$ be defined by the above AMP iteration, but with independent $\bx^{\eta}_0,\wt\bx^{\eta}_0$ and independent external Gaussian vectors $\bg_i,\wt\bg_i$.
The general formulation of \cite[Theorem 2]{huang2024optimization} encompasses this iteration as well\footnote{In the notation there, one can initialize $\bw_0^{\eta}=\be^0$ and $\wt\bw_0^{\eta}=\be^1$, and then e.g.\ alternate computations on the $\bw$ variables and $\wt\bw$ variables on even and odd steps. After initialization, the external randomness $\be^t$ play the role of the vectors $\bg_k$ in \eqref{eq:discrete-time-AMP}. The multiple species there are not needed in the present formulation, i.e.\ one can take $|\sS|=1$.}.
The resulting state evolution description of this pair of correlated AMP iterations is as follows.
Let $(G_1,\dots,G_k,\wt G_1,\dots,\wt G_k)$ be IID standard Gaussians, and define recursively the centered Gaussian process $(Y^{\eta}_i,\wt Y^{\eta}_i)_{i\geq 0}$ by the generalization of \eqref{eq:state-evolution}:
\begin{equation}
\label{eq:state-evolution-pair}
\begin{aligned}
    \bbE[Y^{\eta}_{k+1}Y^{\eta}_{j+1}]
    &=
    \beta^2 \eta^2 \xi'\big(\bbE[X^{\eta}_{k}X^{\eta}_{j}]\big),
    \\
    \bbE[Y^{\eta}_{k+1}\wt Y^{\eta}_{j+1}]
    &=
    \beta^2 \eta^2 \xi'\big(\bbE[X^{\eta}_{k}\wt X^{\eta}_{j}]\big),
    \\
    \bbE[\wt Y^{\eta}_{k+1}\wt Y^{\eta}_{j+1}]
    &=
    \beta^2 \eta^2 \xi'\big(\bbE[\wt X^{\eta}_{k}\wt X^{\eta}_{j}]\big)
    .
\end{aligned}
\end{equation}
Here $\wt X_j^{\eta}$ is described by the analogs of e.g.\ \eqref{eq:X-amp-def}.

\begin{proposition}[State Evolution]
For any fixed $\eta$ and Lipschitz $\psi:\bbR^{k+1}\to\bbR$, we have the $N\to\infty$ convergence in probability in the space $\bbW_2(\bbR^{4(k+1)})$:
\begin{equation}
\label{eq:w-W-convergence}
\begin{aligned}
&\frac{1}{N}
\sum_{i=1}^N
\delta_{(\by_0^{\eta})_i,\dots,(\by_k^{\eta})_i,(\bg_0)_i,\dots,(\bg_k)_i,(\wt\by_0^{\eta})_i,\dots,(\wt\by_k^{\eta})_i,(\wt\bg_0)_i,\dots,(\wt\bg_k)_i}
\\
&\to
\cL\big(Y^{\eta}_0,\dots,Y^{\eta}_k,G_1,\dots,G_k,\wt Y^{\eta}_0,\dots,\wt Y^{\eta}_k,\wt G_1,\dots,\wt G_k\big)
.
\end{aligned}
\end{equation}
Here $\delta_{(\cdot)}$ denotes a Dirac delta mass.
\end{proposition}




The next lemma is the desired orthogonality statement for the AMP iteration. It follows readily from the state evolution equations.


\begin{lemma}
\label{lem:AMP-orthogonal}
Then for any $\eta,K>0$ we have for all $0\leq j,k\leq K$:
\[
\plim_{N\to\infty}
\la \bx^{\eta}_j,\wt\bx^{\eta}_k\ra/N
=
\plim_{N\to\infty}
\la \by^{\eta}_j,\wt\by^{\eta}_k\ra/N
=
0.
\]
\end{lemma}

\begin{proof}
    We induct on $K$, with the base case being clear as $\plim_{N\to\infty} \la\bx_0,\wt\bx_0\ra/N=0$.
    For the inductive step, we consider $0\leq j\leq K$.
    Since $\xi'(0)=0$, the state evolution recursion \eqref{eq:state-evolution-pair} implies:
    \[
    \plim_{N\to\infty}
    \la\by^{\eta}_{j+1},\wt\by^{\eta}_{K+1}\ra/N
    =
    0.
    \]
    Given the expansion \eqref{eq:discrete-time-AMP}, we see that
    \begin{align*}
    \plim_{N\to\infty}
    \la\bw^{\eta}_{j+1},\wt\bw^{\eta}_{K+1}\ra/N
    &=
    0
    \\
    \implies
    \plim_{N\to\infty}
    \la\bx^{\eta}_{j+1},\wt\bx^{\eta}_{K+1}\ra/N
    &=
    0.
    \end{align*}
    In this implication, we use that
    \[
    \plim_{N\to\infty}
    \la\bg_{j+1},\wt\bg_{K+1}\ra/N
    =
    \plim_{N\to\infty}
    \la\bg_{j+1},\wt\bx^{\eta}_{K+1}\ra/N
    =
    \plim_{N\to\infty}
    \la\bx^{\eta}_{j+1},\wt\bg_{K+1}\ra/N
    =
    0.
    \]
    The first is clear while the latter two follow by independence, and because $\plim_{N\to\infty} \|\wt\bx^{\eta}_{k}\|/\sqrt{N}$ exists and is finite for each $k$ (again by state evolution).
    This closes the induction and completes the proof.
\end{proof}


We next define an intermediate approximation
\begin{equation}
\label{eq:discrete-time-Langevin}
\bx^{\eta,\aux}_{k+1}
=
\frac{\bx^{\eta,\aux}_k
+\beta \eta\nabla H_N(\bx^{\eta,\aux}_k)+\sqrt{2\eta} \bg_k}
{\|\bx^{\eta,\aux}_k
+\beta \eta\nabla H_N(\bx^{\eta,\aux}_k)+\sqrt{2\eta} \bg_k\|}\cdot \sqrt{N}.
\end{equation}


We couple this iteration with the AMP by using the same initialization $\bx_0^{\eta,\aux}=\bx_0^{\eta}$, and the same Gaussian vectors $\bg_k$.
We then couple with Langevin dynamics by setting
\begin{equation}
	\label{eq:langevin-coupling}
	\sqrt{\eta}\bg_k=\bB_{(k+1)\eta}-\bB_{k\eta}.
\end{equation}
Lemma~\ref{lem:langevin-orthogonal} follows directly from Lemma~\ref{lem:AMP-orthogonal} above and Lemmas~\ref{lem:AMP-approximates-discrete-langevin}, \ref{lem:discrete-langevin-approx-Langevin} below.
The latter two show that the auxiliary iteration \eqref{eq:discrete-time-Langevin} accurately approximates both AMP and the continuous-time spherical Langevin dynamics.


\begin{lemma}
\label{lem:AMP-approximates-discrete-langevin}
For any $T>0$ we have
\[
\plimsup_{N\to\infty}
\sup_{0\leq k\leq T/\eta}
\|\bx^{\eta,\aux}_k-\bx^{\eta}_k\|/\sqrt{N}
=
0.
\]
\end{lemma}

\begin{proof}
    This is easily shown by induction on $k$, the base case being trivial.
    In the inductive step, we assume the result for the $k$-th iterates and show it for the $k+1$ iterates.
    Using Proposition~\ref{prop:gradients-bounded}, we see that
    \[
    \plimsup_{N\to\infty}
    \sup_{0\leq k\leq T/\eta}
    \|\bx^{\eta,\aux}_k+\beta\eta \nabla H_N(\bx^{\eta,\aux}_k)
    -\bx^{\eta}_k-\beta\eta \nabla H_N(\bx^{\eta}_k)\|/\sqrt{N}=0.
    \]
    The independence of $\bg_k$ from both iterates implies it has overlap $o(1)$ with each in probability.
    Therefore
    \[
    \plimsup_{N\to\infty}
    \frac{\|\bx^{\eta,\aux}_{k+1}\|^2
    -
    \|\bx^{\eta}_{k+1}\|^2}{N}
    =
    0.
    \]
    Therefore the denominator in \eqref{eq:discrete-time-Langevin} satisfies
    \begin{align*}
    &\plim_{N\to\infty}
    \|\bx^{\eta,\aux}_k
    +\beta \eta\nabla H_N(\bx^{\eta,\aux}_k)+\sqrt{2\eta} \bg_k\|/\sqrt{N} \\
    &=\plim_{N\to\infty}
    \|\bx^{\eta}_k
    +\beta \eta\nabla H_N(\bx^{\eta}_k)+\sqrt{2\eta} \bg_k\|/\sqrt{N} \\
    &=\plim_{N\to\infty}
    = \|\bw_{k+1}^\eta\| / \sqrt{N}
    = \sqrt{C_{k+1}^\eta}
    \end{align*}
    in probability.
    This easily completes the inductive step and hence the proof.
\end{proof}

The following elementary estimate will be useful to prove Lemma~\ref{lem:discrete-langevin-approx-Langevin} (we will take $\bx_{k\eta}$ to be the disorder-dependent ``initialization'' when applying it).

\begin{proposition}[{\cite[Lemma 2.1]{sellke2023threshold}}]
\label{prop:langevin-continuity-bound}
    Suppose $H_N$ obeys Proposition~\ref{prop:gradients-bounded}.
    For fixed $\beta$ and small enough $\eta\in (0,\eta_0(\beta))$, for any (possibly $H_N$-dependent) initialization $\bx_0\in\cS_N$ of Langevin dynamics:
    \[
    \bbP[
    \sup_{0\leq t\leq \eta}
    \|\bx_t-\bx_0\|
    \leq
    C(\beta)\sqrt{\eta N}]
    \geq 1-e^{-cN}.
    \]
\end{proposition}

\begin{lemma}
\label{lem:discrete-langevin-approx-Langevin}
Let $T>0$ be fixed.
For $\bx^{\eta,\aux}$ as in \eqref{eq:discrete-time-Langevin} and $\bx_t$ the solution to the Langevin dynamics, coupled by \eqref{eq:langevin-coupling},
\[
\lim_{\eta\to 0}
\plimsup_{N\to\infty}
\sup_{0\leq k\leq T/\eta}
\|\bx^{\eta,\aux}_k-\bx_{k\eta}\|/\sqrt{N}
=
0.
\]
\end{lemma}

\begin{proof}
    Define the random variable
    $D_{k,\eta}= \|\bx^{\eta,\aux}_k-\bx_{k\eta}\|/\sqrt{N}$.
    We will show that with probability $1-o(1)$ as $N\to\infty$, the following recursion holds for all $0\le k\le T/\eta$:
    \begin{equation}
    \label{eq:discrete-time-gronwall}
    D_{k+1,\eta}
    \leq
    (1+O(\eta))
    D_{k+1,\eta}
    +
    O(\eta^{3/2})+o_N(1).
    \end{equation}
    We will prove this by induction on $k$, with the base case $k=0$ being trivial.
    Define
    \[
    \hat\bx^{\eta}_{k+1}
    =
    \frac{\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k}
    {\|\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\|}\cdot \sqrt{N}.
    \]
    We then have:
    \begin{equation}
    \label{eq:triangle-ineq-first-step-discrete-langevin}
    D_{k+1,\eta}
    \leq
    \|\bx^{\eta,\aux}_{k+1}-\hat\bx^{\eta}_{k+1}\|/\sqrt{N}
    +
    \|\hat\bx^{\eta}_{k+1}-\bx_{(k+1)\eta}\|/\sqrt{N}
    \end{equation}
    For the first term, on the event of Proposition~\ref{prop:gradients-bounded} we have
    \begin{equation}
    \label{eq:first-term-discrete-langevin-numerator}
    \big\|\big(\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})\big)
    -
    \big(\bx^{\eta,\aux}_k
    +\beta \eta\nabla H_N(\bx^{\eta,\aux}_k)
    \big)
    \big\|/\sqrt{N}
    \leq
    (1+O(\eta))
    D_{k,\eta}.
    \end{equation}
    We claim that
    \begin{equation}
    	\label{eq:first-term-discrete-langevin-denominator}
    	\fr{\|\bx_{k\eta}+\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\|}{\sqrt{N}},
    	\fr{\|\bx^{\eta}_k+\beta \eta\nabla H_N(\bx^{\eta}_k)+\sqrt{2\eta} \bg_k\|}{\sqrt{N}}
    	= 1 + O(\eta).
    \end{equation}
    This is because $\|\bx_{k\eta}\|, \|\bx^{\eta}_k\| = \sqrt{N}$, while $\|\nabla H_N(\bx_{k\eta})\|, \|\nabla H_N(\bx^{\eta}_k)\| = O(\sqrt{N})$ by Proposition~\ref{prop:gradients-bounded}, and $\bg_k$ is independent of and thus asymptotically orthogonal to everything else, with probability $1-e^{-cN}$.
    Combining \eqref{eq:first-term-discrete-langevin-numerator}, \eqref{eq:first-term-discrete-langevin-denominator} with Lemma~\ref{lem:normalize-almost-contraction} below (with $C = 1 + O(\eta)$) implies
    \[
    	\|\bx^{\eta,\aux}_{k+1}-\hat\bx^{\eta}_{k+1}\|/\sqrt{N} \le (1+O(\eta)) D_{k,\eta}.
    \]
    % \begin{align*}
    % &\lt|\frac{\|\bx_{k\eta}
    % +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\|
    % -
    % \|\bx^{\eta}_k
    % +\beta \eta\nabla H_N(\bx^{\eta}_k)+\sqrt{2\eta} \bg_k\|}{\sqrt{N}}
    % \rt|
    % \\
    % &\leq
    % \lt|\frac{\|\bx_{k\eta}
    % +\beta \eta\nabla H_N(\bx_{k\eta})\|
    % -
    % \|\bx^{\eta}_k
    % +\beta \eta\nabla H_N(\bx^{\eta}_k)\|}{\sqrt{N}}
    % \rt|
    % +
    % o_N(1)
    % \\
    % &\leq
    % (1+O(\eta))
    % D_{k,\eta}
    % +
    % o_N(1).
    % \end{align*}
    % \bhcomment{The commented out argument here bounds the difference between the two terms in \eqref{eq:first-term-discrete-langevin-denominator} by $(1+O(\eta)) D_{k,\eta}$. But we only know $D_{k,\eta} = O(\eta^{1/2})$ (see the last display of this proof) so it seems this only implies
    % \[\|\bx^{\eta,\aux}_{k+1}-\hat\bx^{\eta}_{k+1}\|/\sqrt{N} \le (1+O(\eta^{1/2})) D_{k,\eta}.\]
    % Unless I'm missing something.} \\
    It remains to estimate the second term in \eqref{eq:triangle-ineq-first-step-discrete-langevin}.
    To this end, for $\by\in\bbR^N$ we write
    $\by=\by^{\parallel}+\by^{\perp}$ for its decomposition into components parallel and orthogonal to $\bx_{k\eta}$.
    Since $\bx_{k\eta}\in\cS_N$, we have
    \begin{align}
    \notag
    \|\hat\bx^{\eta}_{k+1}-\bx_{(k+1)\eta}\|/\sqrt{N}
    &\leq
    \|(\hat\bx^{\eta}_{k+1})^{\perp}-(\bx_{(k+1)\eta})^{\perp}\|/\sqrt{N}
    +
    \|(\hat\bx^{\eta}_{k+1})^{\parallel}-(\bx_{(k+1)\eta})^{\parallel}\|/\sqrt{N}
    \\
    \notag
    &=
    \|(\hat\bx^{\eta}_{k+1})^{\perp}-(\bx_{(k+1)\eta})^{\perp}\|/\sqrt{N} \\
    \notag 
    &\qquad +
    \lt|
    \sqrt{1-\|(\hat\bx^{\eta}_{k+1})^{\perp}\|^2/N}
    -
    \sqrt{1-\|(\bx_{(k+1)\eta})^{\perp}\|^2/N}
    \rt|
    \\
    \label{eq:last-main-estimate-discrete-langevin}
    &\leq
    O(\|(\hat\bx^{\eta}_{k+1})^{\perp}-(\bx_{(k+1)\eta})^{\perp}\|/\sqrt{N})
    .
    \end{align}
    Here the last inequality holds so long as both $\|(\hat\bx^{\eta}_{k+1})^{\perp}\|$ and $\|(\bx_{(k+1)\eta})^{\perp}\|$ are at most $\sqrt{N/10}$, as the function $x \mapsto \sqrt{1-x^2}$ is $O(1)$-Lipschitz on $[0,1/\sqrt{10}]$.
    For small $\eta$, the bound $\|(\hat\bx^{\eta}_{k+1})^{\perp}\| \le \sqrt{N/10}$ follows from Proposition~\ref{prop:gradients-bounded}, while $\|(\bx_{(k+1)\eta})^{\perp}\| \le \sqrt{N/10}$ follows from Proposition~\ref{prop:langevin-continuity-bound} (and these propositions show both are $O(\sqrt{\eta N})$ with probability $1-e^{-cN}$).
    To estimate \eqref{eq:last-main-estimate-discrete-langevin}, we write
    \begin{align*}
    	\|(\hat\bx^{\eta}_{k+1})^{\perp}-(\bx_{(k+1)\eta})^{\perp}\|
    	&\le \big\|
    		(\bx_{(k+1)\eta})^{\perp}-
    		\big(\bx_{k\eta} +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\big)^{\perp}
    	\big\| \\
    	&+ \big\|
    		(\hat\bx^{\eta}_{k+1})^{\perp}-
    		\big(\bx_{k\eta} +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\big)^{\perp}
		\big\|.
    \end{align*}
    Then,
    \begin{align*}
    &(\bx_{(k+1)\eta})^{\perp}
    -
    % (\hat\bx^{\eta}_{k+1})^{\perp}
    \lt(\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\rt)^{\perp}
    \\
    &=
    \int_{k\eta}^{(k+1)\eta}
    \beta
    \Big(
    \big(\nabla_{\sph} H_N(\bx_t)\big)^{\perp}
    -
    \big(\nabla_{\sph} H_N(\bx_{k\eta})\big)^{\perp}
    \Big)
    +
    \frac{(N-1)\bx_t^{\perp}}{2N}
    \de t
    \\
    &\quad
    +
    \lt(
    \sqrt{2}
    \int_{k\eta}^{(k+1)\eta}(P^{\perp}_{\bx_t}-1)
    \de \bB_t
    \rt)^{\perp}.
    \end{align*}
    Proposition~\ref{prop:langevin-continuity-bound} ensures that $\|\bx_t-\bx_{k\eta}\|\leq O(\sqrt{\eta N})$ for all $t\in [k\eta,(k+1)\eta]$ with probability $1-e^{-cN}$.
    It easily follows that the integral of the first and second terms are both $O(\eta^{3/2}\sqrt{N})$, using Proposition~\ref{prop:gradients-bounded} in the former case.
    The last term is by definition
    \[
    -
    \sqrt{2}
    \lt(\int_{k\eta}^{(k+1)\eta}
    \frac{\bx_t \bx_t^{\top}}{N}\de \bB_t\rt)^{\perp}.
    \]
    The stochastic integrand has Frobenius norm $1$ almost surely for each $t$, so the resulting stochastic integral has average $L^2$ norm $\eta$, and thus vanishes in probability upon division by $\sqrt{N}$.
    Finally we claim that
    \[
    \|(\hat\bx^{\eta}_{k+1})^{\perp}
    -
    \lt(\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\rt)^{\perp}\|\leq O(\eta^{3/2}\sqrt{N}).
    \]
    % It is easy to see by approximate orthogonality of $\bg_k$ with any independent vector that
    Recall from \eqref{eq:first-term-discrete-langevin-denominator} that with probability $1-e^{-cN}$,
    \[
    \|\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\|^2/N
    =
    1+O(\eta).
    \]
    % with probability $1-e^{-cN}$.
    Therefore
    \begin{align*}
    \|(\hat\bx^{\eta}_{k+1})^{\perp}
    -
    \lt(\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\rt)^{\perp}\|
    &\leq
    O(\eta)
    \cdot \lt\|\lt(\bx_{k\eta}
    +\beta \eta\nabla H_N(\bx_{k\eta})+\sqrt{2\eta} \bg_k\rt)^{\perp}\rt\|
    \\
    &\leq
    O(\eta^{3/2}\sqrt{N})
    \end{align*}
    by Proposition~\ref{prop:langevin-continuity-bound}.
    Combining the above, we conclude that the left-hand side of \eqref{eq:last-main-estimate-discrete-langevin} is $O(\eta^{3/2}\sqrt{N})$.
    This yields \eqref{eq:discrete-time-gronwall}.
    Finally, iterating \eqref{eq:discrete-time-gronwall} gives that for all $0\le k\le T/\eta$,
    \begin{align*}
    	D_{k,\eta}
    	&\le \sum_{\ell=0}^{k-1} (1+O(\eta))^\ell O(\eta^{3/2}) + o_N(1) \\
    	&\le (1+O(\eta))^k O(\eta^{1/2}) + o_N(1)
    	\le O(\eta^{1/2}) + o_N(1),
    \end{align*}
    where the last inequality uses that $(1+O(\eta))^k \le e^{O(T)}$ is bounded by a constant.
\end{proof}

\begin{lemma}
	\label{lem:normalize-almost-contraction}
	Suppose $\bx,\by \in \bbR^N$ and $\|\bx\|, \|\by\| \ge \sqrt{N} / C$.
	Let $\widehat \bx = \sqrt{N} \cdot \bx / \|\bx\|$, $\widehat \by = \sqrt{N} \cdot \by / \|\by\|$.
	Then, $\|\widehat \bx - \widehat \by\| \le C \|\bx-\by\|$.
\end{lemma}
\begin{proof}
	We directly calculate
	\[
		\lt\|\widehat \bx - \widehat \by\rt\|^2
		= \fr{\|\bx-\by\|^2 - (\|\bx\|-\|\by\|)^2}{\|\bx\|\|\by\|} \cdot N
		\le \fr{\|\bx-\by\|^2}{\|\bx\|\|\by\|} \cdot N
		\le C^2 \|\bx-\by\|^2. \qedhere
	\]
\end{proof}









