\section{Introduction}\label{sec:intro}

\subsection{The main result in its simplest form}\label{sec:1.1}

\paragraph{The scattering problem and its finite-element approximation using a PML.}
We study computing approximations to the solution of sound-soft or sound-hard scattering problems using the finite-element method with non-uniform meshes. We consider scattering by an open obstacle $\Omega_-\Subset \mathbb{R}^d$ with smooth boundary and connected complement, $\Omega_+:=\mathbb{R}^d\setminus \overline{\Omega}_-$: given $f\in L^2_{\rm comp}(\overline{\Omega_+})$, find $u\in H^1_{\rm loc}(\overline{\Omega_+})$ such that
\begin{equation}
\label{e:edp}
-k^{-2}\operatorname{div}( A\nabla u)-n u=f\text{ in }\Omega_+,\qquad (Bu)|_{\partial\Omega_+}=0,\qquad (k^{-1}\partial_r-i)u=o_{r\to \infty}(r^{\frac{1-d}{2}}),
\end{equation}
where $A$ is a smooth, symmetric, positive-definite matrix with real coefficients, $n\in C^\infty(\overline{\Omega_+};\mathbb{R}_+)$, $\supp (A-I)\cup \supp (n-1)\Subset \overline{\Omega}_+$, and $Bu=u$ in the sound-soft case and $Bu=\partial_{\nu}u$, with $\nu$ the normal to $\partial\Omega_+$ in the sound-hard case.

We approximate the Sommerfeld radiation condition using a radial perfectly matched layer (PML):~let $\Omega_{\tr}\Subset \mathbb{R}^d$ be open and contain the closed convex hull of $\Omega_-\cup \supp (A-I)\cup \supp (n-1)$. We truncate the problem~\eqref{e:edp} to the computational domain $\Omega:=\Omega_+\cap \Omega_{\tr}$ and apply the finite-element method to the problem: given $f\in L^2(\Omega)$, find $u\in H^1(\Omega)$ such that
\begin{equation}
\label{e:PML1}
P_ku:=-k^{-2}\operatorname{div}(A_\theta\nabla u)+k^{-2} b_\theta\cdot\nabla u-n_\theta u=f\text{ in }\Omega,\qquad (Bu)|_{\partial\Omega_+}=0,\qquad u|_{\partial\Omega_{\tr}}=0,
\end{equation} 
where $A_\theta$, $b_\theta$, and $n_\theta$ are defined in \S\ref{sec:PML} (and $A_\theta$, $b_\theta$, and $n_\theta$ are respectively $A$, $0$, and $n$ in the non-PML region). 
 Let $a_k(\cdot,\cdot)$ be the sesquilinear form associated with~\eqref{e:PML1}.
\begin{definition}
Given  a subspace $V\subset H^1(\Omega)\cap H_0^1(\Omega_{+})$  (or $H_0^1(\Omega)$ in the sound-soft case), a \emph{finite-element/Galerkin solution of~\eqref{e:PML1}} is an element $u_h\in V$ such that 
\begin{equation}
\label{e:galerkinDef}
a_k( u_h,w_h) =\langle f,w_h\rangle\quad \tfa w_h\in V.
\end{equation}
\end{definition}

Let 
$$
\rho=\rho(k):=\sup\Big\{ \|u\|_{L^2(\Omega)}\,:\, u\text{ solves~\eqref{e:PML1} with }\, \|f\|_{L^2(\Omega)}=1\Big\}.
$$
Recall that, with the normalisation used in~\eqref{e:edp}, for all $k_0>0$ there exists $c>0$ such that  $\rho(k)\geq ck$ for $k>k_0$. By~\cite[Theorem 1.6]{GLS2}, for a radial PML (defined in \S\ref{sec:PML}), there exist $C, k_1>0$ such that for $k>k_1$ and $\chi\equiv 1$ on the convex hull of $\Omega$, 
$$
\rho\leq C\sup\Big\{ \|\chi u\|_{L^2(\Omega^+)}\,:\, u\text{ solves~\eqref{e:edp} with }\, \|\chi f\|_{L^2(\Omega^+)}=1\Big\};
$$
i.e. the PML solution operator is controlled by the scattering solution operator. 
\begin{assumption}
\label{a:polyBoundIntro}
The set $\mathcal{J}\subset\mathbb{R}_+$, $\Omega_-$, $A_\theta, b_\theta$, and $n_\theta$ are such that there are $C>0$, $N>0$ such that $\rho(k)\leq C k^N$ for $k\in \mathbb{R}_+\setminus \mathcal{J}$. 
\end{assumption}
By~\cite{LSW1} and~\cite[Theorem 1.6]{GLS2}, for any $\delta>0$, Assumption~\ref{a:polyBoundIntro} holds for a radial PML, any $(\Omega_-,A,n)$, and some $\mc{J}_\delta$ with $|\mc{J}_\delta|<\delta$.

\paragraph{State-of-the-art analysis of the $h$-FEM.}
The $h$-version of the finite-element method (FEM) considers the Galerkin solution to~\eqref{e:PML1} with $V$ given by the space of piecewise polynomials of a fixed degree, $p$, on a mesh with maximum width $h$.  The accuracy of the solution is then increased by decreasing $h$. 

Many authors have studied  $k$-explicit conditions on the meshwidth guaranteeing that the finite-element solution exists and has controlled error. The best existing result is the following: if $(hk)^{2p}\rho$ is sufficiently small, then for $m\in\{0,\dots, p-1\}$, 
\begin{equation}
\label{e:preasymptotic1}
\|u-u_h\|_{H_k^{1-m}(\Omega)}\leq C\Big((hk)^m+\rho (hk)^p\Big)
\inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1(\Omega)}.
\end{equation}
This estimate was proved for general Helmholtz problems  and general $p\in \mathbb{Z}^+$ in \cite{GS3} (with earlier work in \cite{FeWu:09, MeSa:10, FeWu:11, MeSa:11,Wu:14,DuWu:15,BaChGo:17,LiWu:19, ChNi:20, Pe:20,ChGaNiTo:22, LSW2}) and is empirically sharp when the mesh considered has uniform width $h$.
The bound~\eqref{e:preasymptotic1} implies that if $\rho (hk)^p$ is bounded then the FE solution is quasi-optimal (QO) in the sense that
$\|u-u_h\|_{H^1_k(\Omega)}$ is, up to a constant, the best-approximation error. Since $\rho\gtrsim k$, the requirement $\rho (hk)^p\lesssim 1$ implies that $hk\lesssim \rho^{1/p}\ll k^{-1/p}$-- this fact that $hk$ must decrease with $k$ is the \emph{pollution effect}~\cite{BaSa:00}.

% \cite[Theorem 6.1]{Wu:14},  \cite[Theorem 5.1]{DuWu:15}, \cite[Theorem 2]{BaChGo:17}, \cite[Theorem 4.1]{LSW2}, \cite[Theorem 4.4]{LiWu:19}, 
% \cite[Theorem 2.39]{Pe:20}, and 
% \cite[Theorem 7.2]{ChGaNiTo:22}


Using standard piecewise-polynomial approximation results in the right-hand side of \eqref{e:preasymptotic1}, one obtains 
%from~\eqref{e:preasymptotic1} 
that 
\begin{equation}
\label{e:preasymptotic2}
\|u-u_h\|_{H_k^{1-m}(\Omega)}\leq C\Big((hk)^m+\rho (hk)^p\Big)(hk)^p\|u\|_{H_k^{p+1}(\Omega)}.
\end{equation}
If the data is $k$-oscillatory, then so is the solution (by elliptic regularity; see \cite[Page 9]{GS3}), with $\|u\|_{H_k^{p+1}(\Omega)}\leq C\|u\|_{H^1_k(\Omega)}$. In this case,~\eqref{e:preasymptotic2} implies that the Galerkin solution has bounded relative error (BRE) if $(hk)^{2p} \rho$ is sufficiently small. We highlight that 
this threshold for BRE was famously identified for 1-d problems in the work of Ihlenburg and Babu\v{s}ka \cite{IhBa:95a, IhBa:97} (see \cite[Page 350, penultimate displayed equation]{IhBa:97}, \cite[Equation 4.7.41]{Ih:98}).  

To date, all $k$-explicit a priori analyses of the $h$-FEM consider uniform meshes.
The goal of this paper is to study non-uniform meshes, designed by considering the ray dynamics in $\Omega_+$, and give local -- as opposed to global -- criteria on the meshwidths. In particular, we show that there exist meshes that obtain QO/BRE while severely violating the mesh thresholds above, and thus involve many fewer degrees of freedom (see Table~\ref{tab:regimes} below).

\paragraph{Subsets of $\Omega$ defined by ray dynamics.}
We define billiard trajectories to be geodesics for the metric $g^{-1}=A/n$ in $\Omega_+$ continued by reflection with respect to $g$ at the boundary 
of $\Omega_+$\footnote{In fact, we use a somewhat more complicated notion, the \emph{generalised broken bicharacteristic}~\cite[Section 24.3]{Ho:85}.}-- when $A=I$ and $n=1$, these are straight line paths continued using the Snell--Descartes law at the boundary. Next, we define the \emph{cavity} $\cavity\subset \overline{\Omega}_+$ as the set of points $x\in \overline{\Omega}_+$ such that there is a billiard trajectory passing over $x$ that remains in a compact set for all positive and negative times. We also define the \emph{visible set} $\visible\subset \overline{\Omega}_+$ as those points $x\in \overline{\Omega}_+$ such that there is a billiard trajectory passing over $x$ that remains in a compact set for all positive times or all negative times. Finally, we define the \emph{invisible set} $\invisible:=\overline{\Omega}_+\setminus (\visible\cup \cavity)$ (the adjectives visible and invisible are relative to the cavity). Let $\Omega_{\pml}\subset \Omega$ be an open neighbourhood of $\partial\Omega_{\tr}$ that is strictly contained in the PML. Next, let $\Omega_\cavity$, $\Omega_\visible$ and $\Omega_\invisible$ be open neighbourhoods of the intersections with $\overline{\Omega}$ of, respectively, $\cavity$, $\visible\setminus (\cavity\cup\Omega_\pml)$, and $\invisible\setminus \Omega_\pml$ in the subspace topology of $\overline{\Omega}$ such that $\Omega_{\cavity}\cap \partial\Omega_{\tr}=\Omega_{\visible}\cap\partial \Omega_{\tr}=\Omega_{\invisible}\cap\partial\Omega_{\tr}=\emptyset.$


