\paragraph{Condition guaranteeing quasi-optimality away from trapping.}

We finally give the weakest condition under which Theorem \ref{t:simple} ensures that the quantities
\begin{equation}
	\label{eq:defQOaway}
	\frac{\norm{u-u_h}_{H^1_k(\Omega_\visible')}}{\displaystyle\min_{w_h \in V_{\mathcal{T}}^p}\norm{u - w_h}_{H^1_k(\Omega)}}, \quad \frac{\norm{u-u_h}_{H^1_k(\Omega_\invisible')}}{\displaystyle\min_{w_h\in V_{\mathcal{T}}^p}\norm{u - w_h }_{H^1_k(\Omega)}}
\end{equation}
remain $k$-uniformly bounded. We refer to these quantities as the quasi-optimality constants ``away from trapping". These quantities should not be confused with ``local quasi-optimality" constants (which would be defined with $\Omega_\visible$ and $\Omega_\invisible$ instead of $\Omega$ in the denominators of \eqref{eq:defQOaway}).

\begin{corollary}[Threshold for $k$-uniform ``quasi-optimality away from trapping"]
	\label{cor:QOaway}
		Under the same assumptions as Theorem~\ref{t:simple}, 
if $(\mathcal{T}_k)_{k>0}$ satisfies
	\begin{equation}
		\label{eq:cond_QOaway}
		(h_\cavity k)^p \sqrt{k\rho} + (h_\visible k)^p k + (h_\invisible k)^p k + (h_\pml k)^p < c,
	\end{equation}
then 
	\begin{equation}
		\label{eq:QOaway}
\mathscr{M}\leq 		C\begin{pmatrix}
			\sqrt{\frac{\rho}{k}} & \sqrt{\frac{\rho}{k}} & \frac{1}{k^2}\sqrt{\frac{\rho}{k}} &0\\
			1 & 1 & 1 &0\\
			\frac{1}{k} &1 & 1&0\\
			0&0&0&1
		\end{pmatrix} 
\quad\tand\quad
\mathscr{M}_\Omega
 \leq C \begin{pmatrix}
		\sqrt{\frac{\rho}{k}}\\
			1\\
			1\\
			1
	\end{pmatrix} .
	\end{equation}
\end{corollary}
\begin{remark}
	It is natural to look for the analogous weakest condition guaranteeing a controllably small $k$-uniform bound on the ``relative error away from trapping", defined by
	\begin{equation}
		\label{eq:defREaway}
		\frac{\norm{u-u_h}_{H^1_k(\Omega_\visible')}}{\norm{u}_{H^{p+1}_k(\Omega)}}, \quad \frac{\norm{u-u_h}_{H^1_k(\Omega_\invisible')}}{\norm{u}_{H^{p+1}_k(\Omega)}}
	\end{equation}
 	(again not to be confused with ``local relative errors" which would involve $\norm{u}_{H^1_k(\Omega_\visible \cap \Omega)}$ and $\norm{u}_{H^1_k(\Omega_\invisible \cap \Omega)}$ in the denominators). However, these quantities are already bounded under the weakest possible condition in Theorem \ref{t:simple}, see Corollary \ref{cor:REcoarse}.
\end{remark}



