\subsubsection{Sketch of the proof of Theorem~\ref{t:simple}}
\label{s:sketch}

For simplicity, we consider here the bound \eqref{e:simple} with $m=p$ and ignore improvements that are possible in the overlaps between subdomains, in the PML region, and by splitting the frequencies of the Galerkin error into those $\gg k$ and $\lesssim k$. 

The proofs of Theorem~\ref{t:simple} and Theorem~\ref{t:theRealDeal} are, at heart, localised versions of the elliptic projection-type argument introduced in~\cite{GS3}.
We first recap this argument %the argument in~\cite{GS3} 
and prove~\eqref{e:preasymptotic1} for $m=p$. The key insight in~\cite{GS3} is the existence of a self-adjoint smoothing operator $S_k$ so that $P_k^\sharp:= P_k+S_k$ is coercive (uniformly in $k$) and for all $N$ there exists $C>0$ such that for $k\geq k_0$ 
$$
\|S_k\|_{H_k^{-N}\to H_k^N}\leq C
$$
(see~\eqref{e:def_Sk} for the definition of the operator $S_k$).
Since $P_k^\sharp$ is coercive there is an \emph{elliptic projection} $\Pi_k^\sharp:H_k^1\to V_{\mc{T}_k}^p$ such that 
\beq\label{e:introPiSharp}
\big\langle P^\sharp_k w_h, (I- \Pi^\sharp_k)u\big\rangle =0 \quad\tfa w_h \in V_{\mc{T}_k}^p
\eeq
and there exists $C>0$ such that for all $k>k_0$
\beq\label{e:introPiSharpCea}
\|(\Id - \Pi_k^\sharp)v\|_{H^1_k} \leq C \inf_{w_h \in V_{\mc{T}_k}^p} \|v - w_h\|_{H^1_k}
\eeq
(i.e. $\Pi^\sharp_k$ is the adjoint Galerkin projection associated to $P^\sharp_k$). Moreover, by an Aubin--Nitsche-type duality argument
\beq
\label{e:lowNormPiSharp}
\|(\Id - \Pi_k^\sharp)v\|_{H^{-p+1}_k} \leq C(hk)^p\inf_{w_h \in V_{\mc{T}_k}^p} \|v - w_h\|_{H^1_k}.
\eeq

It follows from~\eqref{e:introPiSharp} and Galerkin orthogonality~\eqref{e:galerkinDef} that for all $w_h\in V_{\mc{T}_k}^p$, $v\in H_k^{p-1}$,
\begin{equation}
\label{e:basicEllipticProjection}
\begin{aligned}
\langle u-u_h,v\rangle 
&= \big\langle P_k(u-u_h) , R_k^*v \big\rangle\\
&= \big\langle P_k(u-u_h), (I-\Pi^\sharp_k)R_k^* v \big\rangle \\
&= \big\langle P^\sharp_k(u-u_h), (I-\Pi^\sharp_k) R_k^* v \big\rangle - 
\big\langle S(u-u_h), (I-\Pi^\sharp_k) R_k^* v \big\rangle \\
&= \big\langle P^\sharp_k(u-w_h), (I-\Pi^\sharp_k) R_k^*v\big\rangle - 
\big\langle S(u-u_h), (I-\Pi^\sharp_k) R_k^* v\big\rangle.
\end{aligned}
\end{equation}
By~\eqref{e:introPiSharpCea},~\eqref{e:lowNormPiSharp}, and the mapping properties $S_k:H_k^{-p+1}\to H_k^{p-1}$ and $P_k^\sharp:H_k^1\to H_k^{-1}$,
\begin{equation}
\label{e:preasymptoticSketch1}
\begin{gathered}
|\langle u-u_h,v\rangle|\leq C\eta_p\Big( \inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1}+(hk)^p\|u-u_h\|_{H_k^{-p+1}}\Big)\|v\|_{H_k^{p-1}},\\
\text{ where }\quad \eta_p:=\sup_{0\neq v\in H_{k}^{p-1}}\inf_{w_h\in V_{\mc{T}_k}^p}\frac{ \|R_k^*v-w_h\|_{H_k^1}}{\|v\|_{H_k^{p-1}}}.
\end{gathered}
\end{equation}
 By duality,~\eqref{e:preasymptoticSketch1} implies
% $$
% \|u-u_h\|_{H_k^{-p+1}}\leq C\eta_p \Big(\inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1}+(hk)^p\|u-u_h\|_{H_k^{-p+1}}\Big),
% $$
%so that
\beq \label{e:theFirstSystemSimple}
\begin{gathered}
 \|u-u_h\|_{H_k^{-p+1}}\leq C \Big( b\inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1}+\omega\|u-u_h\|_{H_k^{-p+1}}\Big),\\
 b:=\eta_p,\qquad \omega:=(hk)^{p}\eta_p.
 \end{gathered}
\eeq 
By a frequency splitting argument similar to that in Lemma~\ref{l:bound_eta_microlocal} below and the fact that $\rho\geq ck$,
 $$
 \eta_p \leq C(hk)^p\big(1+\|R_k\|_{L^2\to L^2}\big)= C(hk)^p(1+\rho)\leq C(hk)^p\rho.
 $$
% (proved using a frequency splitting argument similar to that in Lemma~\ref{l:bound_eta_microlocal} below and the fact that $\rho\geq ck$), implies
Thus, from \eqref{e:theFirstSystemSimple}, when $(hk)^{2p}\rho$ is sufficiently small, $(1-C\omega)^{-1}$ exists and is positive, and then
 \begin{equation}
 \label{e:martinIsHappy}
 \|u-u_h\|_{H_k^{-p+1}}\leq C(1-C\omega)^{-1}b\inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1}\leq C(hk)^p\rho\inf_{w_h\in V_{\mc{T}_k}^p}\|u-w_h\|_{H_k^1},
 \end{equation}
which is the preasymptotic estimate~\eqref{e:preasymptotic1} for $m=p$.

We now sketch the localised version of the above argument, which is used to prove Theorems~\ref{t:simple} and \ref{t:theRealDeal}. In this sketch, we treat $\Pi_k^\sharp$ and $S_k$ as though they are local; i.e., for $\chi,\psi\in C^\infty(\overline{\Omega})$ with $\supp \chi \cap \supp \psi=\emptyset$, we neglect the terms
$$
\chi\Pi_k^\sharp\psi \,\text{ and }\,\chi S_k\psi.
$$
In general these terms are nonzero, but Sections~\ref{sec:pseudolocS} to~\ref{sec:pseudoLocPi}, which contain the bulk of the technical work of this paper, show that they are $O(k^{-\infty})$ and smoothing. Using these properties, Section~\ref{sec:proof_realDeal} shows that these terms only contribute to the remainder term in Theorem~\ref{t:simple}.%Section~\ref{sec:proof_realDeal}.

To localise the elliptic-projection argument, we introduce an open cover of $\Omega$,  $\{\Omega_j\}_{j=1}^\domainnumber$ and $\{\phi_j\}_{j=1}^\domainnumber\subset C^\infty(\overline{\Omega})$ a partition of unity subordinate to this cover.
(In Theorem~\ref{t:simple}, $\domainnumber=4$ and $(\Omega_1,\Omega_2,\Omega_3,\Omega_4):=(\Omega_\cavity,\Omega_\visible,\Omega_\invisible,\Omega_\pml)$.)
Next, let $\chi_j\in C^\infty(\overline{\Omega})$, $j=1,\dots,\domainnumber$ such that 
$$
\supp \chi_j \subset \Omega_j\cup\partial\Omega,\qquad \chi_j\equiv 1\text{ in a neighbourhood of }\supp \phi_j.
$$
Arguing as in~\eqref{e:basicEllipticProjection}, for all $w_{h,j}\in V_k$, $j=1,\ldots,\domainnumber$, and $v\in H_k^{p-1}$, we obtain
\begin{align}\nonumber
&\langle \chi_i(u-u_h) ,v\rangle \\ 
\nonumber 
&= \big\langle P_k(u-u_h) , R_k^* \chi_i v \big\rangle\\ \nonumber
&= \big\langle P^\sharp_k(u-u_h), (I-\Pi^\sharp_k) R_k^* \chi_iv \big\rangle - 
\big\langle S_k(u-u_h), (I-\Pi^\sharp_k) R_k^* \chi_iv \big\rangle \\ 
&=\sum_{j=1}^{\domainnumber} \bigg(\big\langle P^\sharp_k(u-w_{h,j}), (I-\Pi^\sharp_k) \phi_j R_k^* \chi_iv\big\rangle - 
\big\langle S_k(u-u_h), (I-\Pi^\sharp_k) \phi_j R_k^* \chi_i v\big\rangle \bigg) \label{e:startDuality}
\\ 
&=\sum_{j=1}^{\domainnumber} \bigg(\big\langle P^\sharp_k\chi_j(u-w_{h,j}), \chi_j(I-\Pi^\sharp_k) \phi_j R_k^* \chi_iv\big\rangle - 
\big\langle S_k\chi_j(u-u_h), \chi_j(I-\Pi^\sharp_k) \phi_j R_k^* \chi_i v\big\rangle \bigg),\nonumber
\end{align}
where we have neglected the nonlocal parts of $\Pi_k^\sharp$, $P^\sharp_k$, and $S_k$ in the last line.
The local Aubin--Nitsche--type argument in Lemma~\ref{l:localSharp} shows that (modulo remainder terms)
\begin{equation}
\label{e:localLowNormPiSharp}
\|\chi_j (\Id - \Pi_k^\sharp)v\|_{H^{-p+1}_k} \leq C(h_jk)^p\inf_{w_h \in V_{\mc{T}_k}^p} \|v - w_h\|_{H^1_k},\quad \text{ where } h_j:=\max_{\substack{K\in\mc{T}\\K\cap \Omega_j\neq\emptyset}}h_K
\end{equation}
(compare to~\eqref{e:lowNormPiSharp}).
By~\eqref{e:introPiSharpCea},~\eqref{e:localLowNormPiSharp} and the mapping properties $S_k:H_k^{-p+1}\to H_k^{p-1}$ and $P_k^\sharp: H_k^1\to H_k^{-1}$,
\begin{equation}
\label{e:preasymptoticSketch2}
\begin{gathered}
\begin{aligned}
|\langle \chi_i(&u-u_h),v\rangle|\\
&\leq C\sum_j\eta_p(j\to i) \Big(\inf_{w_{h,j}\in V_{\mc{T}_k}^p}\|\chi_j(u-w_{h,j})\|_{H_k^1}+(h_jk)^p\|\chi_j(u-u_h)\|_{H_k^{-p+1}}\Big)\|v\|_{H_k^{p-1}},
\end{aligned}\\
\text{ where } \quad\eta_p(j\to i):=\sup_{0\neq v\in H_{k}^{p-1}}\inf_{w_h\in V_{\mc{T}_k}^p}\frac{ \|\chi_jR_k^*\chi_iv-w_h\|_{H_k^1}}{\|v\|_{H_k^{p-1}}}
\end{gathered}
\end{equation}
(compare to \eqref{e:preasymptoticSketch1}). 
 By duality,~\eqref{e:preasymptoticSketch2} implies
 $$
 \|\chi_i(u-u_h)\|_{H_k^{-p+1}}\leq \sum_j C\eta_p(j\to i)\Big(\inf_{w_{h,j}\in V_{\mc{T}_k}^p}\|\chi_j(u-w_{h,j})\|_{H_k^1}+(h_jk)^p\|\chi_j(u-u_h)\|_{H_k^{-p+1}}\Big).
 $$
 We then use a frequency splitting argument (see Lemma~\ref{l:bound_eta_microlocal}) to obtain (neglecting remainder terms)
 $$
 \eta_p(j\to i) \leq C(h_jk)^p\|\chi_jR_k^*\chi_i\|_{L^2\to L^2}+C1_{\{\Omega_i\cap \Omega_j\neq \emptyset\}}(h_{ij}k)^p,\quad \text{ where } h_{ij}:=\min (h_i,h_j).
 $$
% and hence
%  \begin{align*}
% \|\chi_i(u-u_h)\|_{H_k^{-p+1}}&\leq C\sum_j\big[(h_jk)^p\|\chi_jR_k^*\chi_i\|_{L^2\to L^2}+1_{\{\Omega_i\cap \Omega_j\neq \emptyset\}}(h_{ij}k)^p\big]\\
% &\qquad\qquad\big(\inf_{w_h\in V_{\mc{T}_k}^p}\|\chi_j(u-w_h)\|_{H_k^1}+(h_jk)^p\|\chi_j(u-u_h)\|_{H_k^{-p+1}}\big).
% \end{align*}
 In particular, this yields the system of inequalities
 \begin{equation}
 \label{e:theFirstSystem}
\big(\| \chi_i(u-u_h)\|_{H_k^{-p+1}}\big)_{i=1}^\domainnumber\leq CB \Big(\inf_{w_{h,j}\in V_{\mc{T}_k}^p}\|\chi_j(u-w_{h,j})\|_{H_k^1}\Big)_{j=1}^\domainnumber+C\oldT\big(\|\chi_j(u-u_h)\|_{H_k^{-p+1}}\big)_{j=1}^\domainnumber,
 \end{equation}
 where 
 \begin{align*}
 B_{ij}&:=\eta_p(j\to i)\leq C(h_jk)^p\|\chi_jR_k^*\chi_i\|_{L^2\to L^2}+C1_{\{\Omega_i\cap \Omega_j\neq \emptyset\}}(h_{ij}k)^p\\
 \oldT_{ij}&:=(h_jk)^p\eta_p(j\to i)\leq C(h_jk)^{2p}\|\chi_jR_k^*\chi_i\|_{L^2\to L^2}+C(h_jk)^p1_{\{\Omega_i\cap \Omega_j\neq \emptyset\}}(h_{ij}k)^p
% \big(\underline{v}\big)_i&:=\chi_iv.
 \end{align*}
 (compare to \eqref{e:theFirstSystemSimple}). 
 Under the condition that
\begin{equation}
\label{e:conditionW}
\sum_{n=0}^\infty (C W)^n<\infty,
 \end{equation}
 $(I-C\oldT)^{-1}$ exists and has non-negative entries. Hence~\eqref{e:theFirstSystem} implies that
 $$
\|  \underline{u-u_h}\|_{H_k^{-p+1}}\leq C(I-C\oldT)^{-1}B \|  \underline{u-w_h}\|_{H_k^1}.
 $$
 (compare to~\eqref{e:martinIsHappy}).

To understand when $\sum_n (CW)^n$ converges, consider $W$ as the weighted adjacency matrix of a directed graph with $\domainnumber$ nodes representing $\{\Omega\}_{j=1}^{\domainnumber}$. Observe that the entry in the $i^{\text{th}}$ row and $j^{\text{th}}$ column of $(CW)^{\ell}$ is given by $C^\ell$ times the sum of the weights over all paths of length $\ell$ from $j$ to $i$ in this graph. Hence, the sum converges if for any $i$ and $j$ the sum of the weights of all paths from $j$ to $i$ multiplied by $C^{\text{path length}}$ is finite. Using elementary graph analysis this condition can be reduced to the requirement that all the sum of such weights for all non-self intersecting loops is less than 1 (see Appendix~\ref{sec:loops}).

In the setting of Theorem~\ref{t:simple}, $\domainnumber=4$ and $(\Omega_1,\Omega_2,\Omega_3,\Omega_4):=(\Omega_\cavity,\Omega_\visible,\Omega_\invisible,\Omega_\pml)$. For $k\notin \mc{J}$, Section~\ref{sec:boundsCsol} obtains the bounds of Table~\ref{ta:resolve} on $\psi R_k^*\chi$ according to the support of $\psi$ and $\chi$.
