	& \lesssim k^{-2} ,	\\
	\frac{\|u_{\rm in} - u_h\|_{H^1_k(\Omega_\visible)}}{\|u_{\rm in}\|_{H^1_k(\Omega)}} &\lesssim \underbrace{(h_\cavity k)^p}_{k^{-2}} \frac{\|u_{\rm in}\|_{H^1_k(\Omega_\cavity)}}{\|u_{\rm in}\|_{H^1_k(\Omega)}} + \underbrace{(h_\visible k)^p}_{k^{-1}} \underbrace{\frac{\|u_{\rm in}\|_{H^1_k(\Omega_\visible)}}{\|u_{\rm in}\|_{H^1_k(\Omega)}}}_{k^{-0.5}} +  (h_\invisible k)^p\frac{\|u_{\rm in}\|_{H^1_k(\Omega_\invisible)}}{\|u_{\rm in}\|_{H^1_k(\Omega)}} 
	 \lesssim k^{-1.5} 	,
	 \end{split}\]\[
	 \begin{split}
	\frac{\|u_{\rm out} - u_h\|_{H^1_k(\Omega_\cavity)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} &\lesssim \underbrace{(h_\cavity k)^p}_{k^{-2}} \frac{\|u_{\rm out}\|_{H^1_k(\Omega_\cavity)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} + \underbrace{(h_\visible k)^p}_{k^{-\frac32}} \underbrace{\frac{\|u_{\rm out}\|_{H^1_k(\Omega_\visible)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}}}_{k^{-0.65}} +   (k\rho)^{-\frac12}(h_\invisible k)^p\frac{\|u_{\rm out}\|_{H^1_k(\Omega_\invisible)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} \\
	& \lesssim k^{-2} ,	\\
	\frac{\|u_{\rm out} - u_h\|_{H^1_k(\Omega_\visible)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} &\lesssim \underbrace{(h_\cavity k)^p}_{k^{-2}} \underbrace{\sqrt{\frac{k}{\rho}}}_{k^{-0.5}}\frac{\|u_{\rm out}\|_{H^1_k(\Omega_\cavity)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} + \underbrace{(h_\visible k)^p}_{k^{-\frac32}} \underbrace{\frac{\|u_{\rm out}\|_{H^1_k(\Omega_\visible)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}}}_{k^{-0.65}} + (h_\invisible k)^p\frac{\|u_{\rm out}\|_{H^1_k(\Omega_\invisible)}}{\|u_{\rm out}\|_{H^1_k(\Omega)}} \\
	& \lesssim k^{-2.15} 	.
\end{split}\]
Again, these rates are experimentally verified in Figure \ref{fig:QOerrors}.

