\end{remark}


\section{Assumptions and statement of the main result}
\label{sec:state_main_result}
We now gather some definitions and assumptions and state our main result, Theorem \ref{t:theRealDeal}. 


\subsection{The Helmholtz PML operators}\label{sec:3.1}


Throughout this paper, $\Omega_{-} \subset \R^d$ (the obstacle) denotes a bounded open set with $C^\infty$ boundary and connected complement. Let $\Omega_{\tr}\Subset \mathbb{R}^d$ (the truncation domain) be a bounded open set with $\Omega_-\Subset \Omega_{\tr}$ and define $\Omega:=\Omega_{\tr}\setminus\overline{\Omega}_-$ (the computational domain). Let $\Gamma_{\tr}=\partial\Omega_{\tr}$ so that $\partial\Omega=\partial\Omega_-\sqcup\Gamma_{\tr}$. For all $k > 0$ and $n\geq 0$, and given $U \subset \R^d$, let $H^n_k(U)$ (abbreviated $H^n_k$ when $U = \Omega$) be the completion of $C^\infty(U)$ with respect to the norm \eqref{e:weightedNorm},
%``semiclassical norm'' (where $k^{-1}$ is the semiclassical parameter)
%\[\|u\|^2_{H^n_k(U)} := \sum_{|\alpha|\leq n} k^{-2\abs{\alpha}} \|\partial^\alpha u\|^2_{L^2(U)},\]
and let $H_k^{-n}(U)$ be the normed dual of $H_k^n(U)$, with, as usual, $L^2(\Omega)$ identified through the $L^2$ pairing with a subspace of $H_k^{-n}$ for all $n \geq 0$. \footnote{We highlight that this is not the standard notation, as $H^{-n}$ usually denotes the dual of $H_0^n = \overline{C^\infty_c(\Omega)}^{H^n_k}$. } 

Let $a_k: H^1_k\times H^1_k \to \mathbb{C}$ be the sesquilinear form defined by 
\begin{equation}
\label{e:def_ak}
a_k(u,v) := \int_{\Omega} \Big(k^{-2}A_\theta(x) \nabla u(x) \cdot \overline{\nabla v(x)} 
+k^{-2}\langle b_\theta(x),\nabla u\rangle \overline{v(x)}
- n_\theta(x) u(x) \overline{v(x)}\Big)\,dx,
\end{equation}
where $A_\theta$, $b_\theta$, and $n_\theta$ are defined in \S \ref{sec:PML}.

To cover both Dirichlet (so-called ``sound-soft'') and Neumann (``sound-hard'') obstacles, we consider a subspace $\cZ_k \subset H^1_k$, which can be either given by $\cZ_k = \Zspaced{}$ or $\cZ_k = \Zspacen{}$, where
\begin{equation}
\label{e:defZk_concrete}
\Zspaced{}:=H_{0,k}^1(\Omega),\qquad\tand\qquad \Zspacen{}:=\overline{\{u\in C^\infty(\overline{\Omega})\,:\,\supp u\cap \Gamma_{\tr}=\emptyset\}}^{H_k^1},
\end{equation}
and let $\cZ_k^*$ be the normed dual of $\cZ_k$. The Helmholtz operator $P_k:\Zspace{} \to (\Zspace{})^*$ is then defined as the linear operator associated to $a_k$, i.e.
$$P_k : \cZ_k \to \cZ_k^*\,, \quad \langle P_k u,v\rangle := a_k(u,v) \quad \tfa u,v \in \cZ_k.$$
If $P_k$ is invertible, we denote by $R_k := (P_k)^{-1} : \cZ_k^* \to \cZ_k$ its inverse (also known as the resolvent), and let
\begin{equation*}
%\label{e:def_rho(k)}
\rho(k) := \|R_k\|_{L^2 \to L^2} = \sup_{f \in L^2(\Omega) \setminus \{0\}} \frac{\|P_k^{-1} f\|_{L^2(\Omega)}}{\|f\|_{L^2(\Omega)}}
\end{equation*}

Our main result holds for $k$ ranging in a subset $\R_+\setminus \mathcal{J}$ of the positive real numbers on which $\rho(k)$ is polynomially bounded; i.e., we make the following assumption on $\mathcal{J}$.
\begin{assumption}[Polynomial bound on the resolvent]
\label{a:polyBound}
There exist $C>0$, $N>0$ such that, for all $k \in \R_+ \setminus \mathcal{J}$, 
$$\rho(k)\leq C k^N.$$
\end{assumption}


In this paper, we are then interested in the error in the finite-element approximation solution (see next paragraph) of the variational problem, for $k \in \R_+ \setminus \mathcal{J}$:
\begin{equation}
\label{e:var_pb}
\text{find $u \in \cZ_k$ such that, for all $v \in \cZ_k$, $a_k(u,v) = F(v)$},
\end{equation}
where $F : \cZ_k \to \cZ_k^*$ is a continuous anti-linear form. 


\subsection{Finite-element approximation}

We consider a Galerkin approximation of the variational problem \eqref{e:var_pb}. Following the practice in the local FEM error analysis literature (see in particular \cite[Assumptions A.1--A.3]{NiSc:74}, and also \cite{Wa:91,DeGuSc:11,Br:20}), and following closely \cite{AvGaSp:24}, we describe $V_k$ through a set of standard assumptions as follows. Throughout, a fixed positive integer $p$,  modelling the polynomial degree of the finite-element subspace, is chosen independently of $k$; hence this setting models a ``$h$-version" of the FEM.

If $U \subset \Omega$ is an open set, define
%\[\Zspace{j}(U) := \big\{ u|_{U} \, \textup{ such that }\, u\in \Zspace{j} \big\}\]
\[C^{\infty}_<(U):= \big\{\chi \in C^\infty(\overline{\Omega}) \textup{ such that } \supp \chi \subset \overline{U} \tand \partial_<(\supp \chi,U) > 0\big\}\]
\[ \Zspace{1,<}(U) := \overline{\big\{ v \in \Zspace{} \, \textup{ s.t. }\, \supp v \subset \overline{U} \,\tand\, \partial_<(\supp v, U) > 0 \big\}},\]
where the closure is taken with respect to the $\Zspace{j}$ norm, and for any subsets $\Omega_0 \subset \Omega_1 \subset \Omega$,
\begin{equation}
\label{e:def_partial}
\partial_< (\Omega_0,\Omega_1) := \textup{dist}(\,\partial \Omega_0 \setminus \partial \Omega\,,\,\,\partial \Omega_1 \setminus \partial \Omega\,).
\end{equation}
A {\em triangulation} $\mathcal{T}$ of $\Omega$ is a set of pairwise disjoint open subsets $K \subset \Omega$ such that
\[\bigcup_{K \in \mathcal{T}} \overline{K} = \overline{\Omega}.\]
We denote by $h_K$ the diameter of $K \in \cT$. 
For $k > 0$, a {\em finite-element space} $V_k$ over a triangulation $\mathcal{T}$ of $\Omega$ is a finite-dimensional subspace $V_k \subset \cZ_k$ such that for every $u \in V_k$ and $K \in \mathcal{T}$, $u_{|K} \in C^\infty(\overline{K})$. If $V_k$ is a finite-element space and $U \subset \Omega$, define
\[V_k^<(U) := \Zspace{1,<}(U) \cap V_k.\] 
In what follows, for each $k > 0$, $\cT_k$ is a given triangulation and $V_k$ is a finite-element space over $\cT_k$. We denote 
$$h = h(k) :=\max_{K \in \cT_k} h_K$$
the global meshwidth, and make the following standard assumptions.

\begin{assumption}[Sub-wavelength grid]
	\label{ass:swlg}
	For all $k_0 > 0$, there exists a positive constant $\Cfem > 0$ such that for all $k \geq k_0$
	\[
h \leq \Cfem k^{-1}.
	\]
\end{assumption}
\begin{assumption}[Wavelength-scale quasi-uniformity]
	\label{ass:qu}
	For all $R > 0$ and all $k_0 > 0$, there exists $C > 0$ such that for all $k \geq k_0$ and any elements $K,K'$ of $\cT_k$ such that $\dist(K,K') \leq Rk^{-1}$, 
	\[\frac{1}{\Cfem} \leq \frac{h_K}{h_{K'}} \leq \Cfem.\] 
\end{assumption}

\begin{assumption}[Approximation property]
	\label{ass:ap}
	There exists $\kappa > 0$ such that for every $k_0 > 0$, there exists $\Cfem > 0$ such that for all $j \in \{1,\ldots,p+1\}$, all $m \in \{0,\ldots,j\}$, all $k \geq k_0$ and all $u \in \Zspace{1}\cap \Hspace{j}$, there exists $u_h \in V_k$ such that
	\[\sum_{K \in \mathcal{T}_k}(h_K k)^{2(m-j)} \|u - u_h\|_{H^m_k(K)}^{2} \leq \Cfem \|u\|^2_{H_k^j}.\]
	Furthermore, given subsets $U_0 \subset U_1 \subset \Omega$ such that 
	$$\partial_<(U_0,U_1) \geq \kappa \max \big\{h_K \,\,|\,\, K \in \mathcal{T}_k \,\,\textup{ s.t. }\,\, K \cap U_1 \neq \emptyset\big\},$$  
	if $\textup{supp}\,u \subset U_0 \cup \partial \Omega$, then $u_h$ can be chosen such that $\supp u_h \subset U_1 \cup \partial \Omega$.
\end{assumption}
\begin{assumption}[Super-approximation property]
	\label{ass:sap}
	There exists $\kappa > 0$ such that for all $k_0 > 0$ and $C_{\dagger} > 0$, there exists $\Cfem > 0$ such that for all $k \geq k_0$ and any subsets $U_0 \subset U_1 \subset \Omega$ such that
	\[d:= \partial_<(U_0,U_1) \geq \kappa  \max \big\{h_K \,\,|\,\, K \in \mathcal{T}_k \,\,\textup{ s.t. }\,\, K \cap U_1 \neq \emptyset\big\},\]
	if $\chi \in C^{\infty}_<(U_0)$ is such that,  
	\[\max_{|\alpha| = n} \|\partial^\alpha \chi \|_\infty \leq \frac{C_\dagger}{d^n}, \tfor n = 0,\ldots,p,\]
	then for any $u_h \in V_k$, there exists $v_h \in V_k^{<}(U_1)$ such that
	\[\|\chi^2 u_h - v_h\|_{H^1_k(K)} \leq \Cfem \frac{h_K}{d} \left[\left(1 + \frac{1}{kd}\right)\|u_h\|_{L^2(K)} + \|\chi u_h\|_{H^1_k(K)}\right]\,\quad \tfa K \in \cT_k.\]
\end{assumption}
\begin{assumption}[Inverse inequality on elements]
	\label{ass:ii}
	There exists $\Cfem$ such that for all $k > 0$, all $K \in \mathcal{T}_k$, all $u_h \in V_k$ and all $j \in \{0,1,\ldots,p\}$, 
	\begin{align*}
		\|u_h\|_{H^1_k(K)} \leq \frac{\Cfem}{h_K k}\|u_h\|_{L^2(K)}\quad\tand\quad
		\|u_h\|_{L^2(K)} \leq \frac{\Cfem}{(h_K k)^j} \|u_h\|_{H_k^{-j}(K)},
	\end{align*}
	where $\|u_h\|_{H_k^{-j}(K)} := \sup_{v \in C^\infty_c(K)} (\abs{\int_{K} u_h v\,dx}/\|v\|_{H^j_k(K)})$.
\end{assumption}

\begin{definition}[Well-behaved finite-element of order $p$]
\label{def:fem}
We say that $(V_k)_{k > 0}$ is a {\em well-behaved finite-element of order $p$} if it satisfies Assumptions \ref{ass:swlg}-\ref{ass:ii} above.
\end{definition}


\begin{remark}
	Since $\Omega$ has a $C^\infty$ boundary, under the assumptions of the present section, the elements $K$ must be curved, ruling out from our settings the standard simplicial Lagrange finite-element discretizations. However, 
	\begin{itemize}
		\item this type of assumptions is common in the high-frequency error analysis for the finite-element method for the Helmholtz equation, see e.g. \cite[Appendix B]{MeSa:10}, and
		\item the ``geometric error" incurred by using simplicial elements instead of curved elements is studied in \cite{ChSp:24}, and shown to be smaller than the pollution error. 
	\end{itemize}
%	We leave more in-depths discussion of this issue to future work.
\end{remark} 

For each $k \in \R_+ \setminus \mathcal{J}$, the Galerkin solution $u_h = u_h(k) \in V_k$ (where the subscript $h$ emphasizes the dependence of $u_h$ with respect to the meshwidth of the triangulation) is defined by 
\begin{equation*}
%\label{e:def_uh}
a_k(u-u_h,v_h) = 0 \quad \tfa v_h \in V_k,
\end{equation*}
and our main result, Theorem \ref{t:theRealDeal}, describes the (micro-)local behaviour of the error $u-u_h$.  


\subsection{Frequency splitting of the error}

We consider a splitting of the Galerkin error $u-u_h$ into ``low-frequencies'' and ``high-frequencies''. To define these notions, we introduce frequency cutoffs as follows.

The following G\aa rding inequality holds (see 
\S\ref{sec:verify} and \S\ref{sec:PML}): 
there exists $\omega\in \Rea$ (with $\omega=0$ for the most commonly-used PML) such that 
for all $k_0 > 0$ there are $\cGa, \CGa > 0$ such that for all $k \geq k_0$, 
\beq\label{e:Garding1}
\Re( \re^{\ri \omega} a_k(u,u)) \geq \cGa\|u\|^2_{\cZ_k} - \CGa \|u\|^2_{L^2}.
\eeq
We deduce from this (see \S \ref{sec:pseudolocS}) that $\sigma(\cP_k) \subset [-\CGa,+\infty)$, and thus, for each $k_0$, there exists a function $\psis$ such that 
\begin{equation}
\label{e:defpsis}
\psis(x) \geq \frac{-x + \CGa}{2} \quad \tfa x \in \sigma(\cP_k).
\end{equation}

Let $\cP_k : \Zspace{} \to (\Zspace{})^*$ be defined by 
$$\cP_k = \frac12 \Big(\re^{\ri \omega} P_k + \re^{-\ri \omega}P_k^{*}\Big).$$
We show in Section \ref{sec:assumptions} that $\cP_k$ is self-adjoint on $L^2(\Omega)$ with domain $\Zspace{2} = \Zspaced{2}$ in the Dirichlet case, and $\Zspace{2} = \Zspacen{2}$ in the Neumann case, where
\begin{equation}
\label{e:defZ2concrete}
\Zspaced{2}=H_0^1(\Omega)\cap H^2(\Omega),\qquad \Zspacen{2}=\{ u\in H^2(\Omega)\,:\,\partial_{\nu, A_\theta} u|_{\partial\Omega_-}=0,\,\, u|_{\Gamma_{\tr}}=0\}.
\end{equation}
Thus, if $f :\R \to \R$ is a bounded, continuous function, we may consider $f(\cP_k): L^2(\Omega) \to L^2(\Omega)$ defined by the functional calculus. 




Low-frequency cutoffs will then be defined as $\Psi = \psi(\cP_k)$ where $\psi \in C_c^\infty(\R)$ is such that $\psi \equiv 1$ on the support of $\psis$, and $1 - \Psi$ will correspond to high-frequency cutoffs.

\subsection{Spatial splitting of the error}


In addition to considering the Galerkin error locally in frequency space, we also localize it spatially. We fix a neighbourhood $U_{\Pml}$ of $\Gamma_{\tr}$ in which Theorem~\ref{thm:PML} holds (that is, sufficiently ``deep'' in the PML region so that the resolvent $R_k^*$ in this region behaves like a pseudolocal, uniformly bounded operator with respect to $k$).  Let 
\begin{equation*}
%\label{e:coverOmega}
\Omega = \bigcup_{j = 1}^M \Omega_j
\end{equation*}
be an open cover of $\Omega$ by $M = M_\Int + M_\Pml$ subdomains. We assume that the ``interior'' domains $\Omega_1,\ldots,\Omega_{M_\Int}$ do not intersect the truncation boundary, while the ``PML'' domains $\Omega_{M_{\Int}+1},\ldots,\Omega_{M_{\Int}+M_\Pml}$ all lie inside the deep PML region, i.e.
\begin{equation}
\label{e:domainConditions}
\bigcup_{j = 1}^{M_\Int} \Omega_j \cap \Gamma_{\rm tr} = \emptyset\,, \qquad \bigcup_{j = M_\Int + 1}^{M_\Int + M_\Pml} \Omega_j \subset U_{\Pml}.
\end{equation}
For $i,j \in \{1,\ldots,M\}$, define 
\beq\label{e:hij}
h_i := \max_{K \in \cT_k} \{\textup{diam}(K) \,\mid\, K \cap \Omega_i \neq \emptyset\} \quad \tand \quad h_{ij} := \min(h_i,h_j),
\eeq
the local mesh sizes on $\Omega_j$ and $\Omega_i \cap \Omega_j$.  


