\subsection{Simple-path matrix}
\label{sec:simple_path_mat}

To any square matrix $\oldT \in \mathbb{M}(N \times N)$, one can associate a matrix $V = V(\oldT)$ defined from the coefficients $\oldT$ in terms of simple paths on a graph. To define this, let $\mathcal{G} = \mathcal{G}(\oldT)$ be the (complete) directed graph, with node set $\mathcal{N} := \{1,\ldots,N\}$, and with edge set $\cE$ the set of ordered pairs $(i,j) \in \{1,\ldots,N\}^2$. A {\em path} $p$ in $\cG$ is a finite (and possibly empty) sequence of edges
$$p = (i_1,j_1) (i_2,j_2) \ldots (i_{\length - 1},j_{\length-1})(i_\length,j_\length)$$ 
satisfying the conditions $j_\ell = i_{\ell+1}$ for $1 \leq \ell  \leq \length-1$. Let $\mathbf{0}$ stand for the empty path. We 
write $\abs{p} := \length$ and denote by $p(\ell)$ the $\ell$-th node visited by $p$, i.e., $p(\ell):=i_\ell$ if $1\leq \ell \leq |p|$ and $p(|p|+1) :=j_\length$. Let $\mathbb{P}_{ij}$ be the set of paths from $i$ to $j$, i.e., such that $p(1) = i$ and $p(|p|+1) = j$.

A path $p$ is {\em non-intersecting} if the map $\ell \mapsto p(\ell)$ is injective. For $i,j \in \{1,\ldots,M\}$,
%i\neq j$, 
let $\mathbb{V}_{ij}$ be the set of non-intersecting paths from $i$ to $j$. %Otherwise,
Observe that $\mathbb{V}_{ii}:= \{\mathbf{0}\}$.

A non-empty path $p$ is a {\em loop} if it starts and ends at the same node, i.e., if $p(1) = p(|p|+1)$. It is a {\em simple loop} if it is a loop but otherwise does not intersect itself, i.e.,
\beqs
p(\ell) = p(m) \implies \big( \ell=m\,\text{ or }\,\{\ell,m\}= \{1,|p|+1\}\big).
\eeqs
We denote by $\mathbb{SL}$ the set of simple loops.  


To each edge $e = (i,j)$ of $\cG$, we associated the weight $\oldT_e := \oldT_{ij}$ (the $(i,j)$-th coefficient of the matrix $\oldT$). We also define the weight of the path $p$ as the product of the weights of its edges, i.e., $\oldT_{\mathbf{0}} := 1$ and
\begin{equation*}
%\label{e:path_weight_def}
\oldT_{e_1e_2\ldots e_L} := \oldT_{e_1} \oldT_{e_2} \ldots  \oldT_{e_L}.
\end{equation*}

\begin{definition}[Simple-path matrix]
\label{def:simple_path_mat}
The {\em simple-path matrix} $\transfer = \transfer(\oldT) \in \mathbb{M}(N \times N)$ of a matrix $\oldT \in \mathbb{M}(N\times N)$ is defined by
$$\transfer_{ij} := \sum_{p \in \mathbb{V}_{ij}} \oldT_{p} \,, \quad 1 \leq i,j\leq N.$$
Observe that the diagonal entries of $\transfer$ are $1$ since $\mathbb{V}_{ii} = \{\mathbf{0}\}$.
\end{definition}

\begin{remark}
We show in Theorem \ref{t:onlyTheSimpleOnes} that, provided the simple loops of of $\cG$ carry weights bounded by $c < 1$, then the $I - W$ is invertible and $(I- \oldT)^{-1} \leq \transfer$ coefficientwise. 
\end{remark}

\subsection{Statement of the main result}

\begin{theorem}[The main result]\label{t:theRealDeal}
	Let $a_k$ be defined by \eqref{e:def_ak} and let $\mathcal{J} \subset \R_+$ be such that Assumption \ref{a:polyBound} holds. Let $p$ be a positive integer and let $(V_k)_{k > 0}$ be a well-behaved Finite-Element of order $p$ in the sense of Definition \ref{def:fem}. Let $\{\Omega_i\}_{i = 1}^M$ be an open cover of $\Omega$ such that the conditions \eqref{e:domainConditions} hold. For every $i \in \{1,\ldots,M\}$, let $\chibigger_i \in C^\infty(\overline{\Omega})$ be such that
		\begin{equation}
		\label{e:crazyCover0}
\supp(\chibigger_i) \subset \Omega_i \cup \partial \Omega\quad \tand \quad
			\Omega=\bigcup_{i=1}^{\domainnumber} {\rm int}\, \big(\big\{ \chi_i \equiv 1\big\}\big),
		%		\big(\Omega\setminus\supp (1-\chi_i)\big).
		\end{equation}
	where the interior is taken in the subspace topology of $\Omega$. Let $k_0, N > 0$, let $\psis$ satisfy \eqref{e:defpsis} and let $\psi \in C^\infty_c(\R)$ be such that 
$\supp \psis \cap \supp(1-\psi)= \emptyset$.
%	$\psis\prec\psi$. 
%	(i.e., the interiors of the sets $\{\chi_i\equiv 1\}$ cover $\Omega$). 

Then, there exist constants $h_0,\specialC>0$ and, for any $0<c<1$, a constant $C>0$ such that the following holds. For any $k\in  (k_0,\infty)\setminus \mathcal{J}$, if $\mathcal{T}_k$ satisfies $h(k) \leq h_0$ and
	\begin{equation}
		\label{e:meshConditionsGeneral}
		%\sum_{\substack{q\in\mathbb{SL}\\|q|\geq 1}}\specialC^{|q|}
		\sum_{{L \in \mathbb{SL}}}
		C_\dagger^{|L|} \oldT_{L}\leq c,
	\end{equation}
	where $\oldT$ is defined by \eqref{e:matrixT}, then for all $u \in H^1_k$, there exists a unique solution $u_h \in V_k$ to the Galerkin problem
	\begin{equation}
	\label{e:Galerkin_ortho}
		a_k(u-u_h,v_h) = 0 \quad \tfa v_h \in V_k.
	\end{equation}
	Moreover, for any $w_{h,1},\ldots, w_{h,\domainnumber} \in V_k$, $m \in \{0,\ldots,p\}$, and $i \in \{1\,,\ldots\,,M_\Int\}$,
%	\begin{align}%\nonumber
%		&\| \chibigger_i\Psi(u-u_h)\|_{H_k^{1-m}}\leq 
