\section{Local bounds on the Helmholtz solution operator}
\label{sec:boundsCsol}

This section describes two results showing how the Helmholtz solution operator has improved $k$-dependence based on the data and measurement locations. The first result (Theorem \ref{thm:DV}) considers locations relative to the cavity or the ray dynamics, and the second (Theorem \ref{thm:PML}) considers locations relative to the PML.
Both results are proved in Appendix \ref{app:help} with the first result a special case of a more general result phrased in terms of semiclassical pseudodifferential operators.

%If either the data or measurement locations are away from the cavity, then the Helmholtz solution has improved $k$-dependence, as shown by the following theorem.

\begin{theorem}[Improved behaviour away from trapping]\label{thm:DV}
Let $k_0>0$ and let $\mathcal{J}$ be such that 
Assumption \ref{a:polyBoundIntro} holds. 

(i) For all $\chi \in C^\infty(\overline{\Omega})$ with $\supp \chi \cap \cavity=\emptyset$, there exists $C>0$ such that for all $k\in (k_0,\infty)\setminus\mathcal{J}$
\begin{gather}\label{eq:DV}
\|\chi R_k\|_{L^2\to L^2}+\|R_k\chi \|_{L^2\to L^2}\leq C\sqrt{k\rho },\qquad \|\chi R_k\chi\|_{L^2\to L^2}\leq Ck.
\end{gather}

(ii) For all $\chi,\psi \in C^\infty(\overline{\Omega})$ with $\supp \chi \subset \invisible$ and $\supp\psi\subset \cavity$, and all $N>0$, there exists $C>0$ such that for all $k\in (k_0,\infty)\setminus\mathcal{J}$
\begin{gather}\label{eq:negligible}
\|\chi R_k\psi\|_{L^2\to L^2}+\|\psi R_k\chi\|_{L^2\to L^2}\leq Ck^{-N}.
\end{gather}
\end{theorem}

%Theorem \ref{thm:DV} is a special case of Theorem \ref{thm:DV2} below, with the latter phrased in terms of semiclassical pseudodifferential operators. 
In the case of scattering without boundaries, the result analogous to \eqref{eq:DV} was proved in \cite{DaVa:12, DaVa:12a}.

\begin{theorem}[Improved behaviour in the PML]\label{thm:PML}
Let $k_0>0$ and let $\mathcal{J}$ be such that 
Assumption \ref{a:polyBoundIntro} holds. Then there is $U\subset \Omega$ a neighbourhood of $\Gamma_{\tr}$ such that for all $\chi \in C^\infty(\overline{\Omega})$ with $\supp \chi\subset U$, there exists $C>0$ such that,  for all $k\in (k_0,\infty)\setminus\mathcal{J}$,
\begin{equation}
\label{e:bounded_in_pml}
\|\chi R_k\|_{L^2\to L^2}+\|R_k\chi \|_{L^2\to L^2}\leq C.
\end{equation}
Moreover, if $\supp \chi \subset U$, and $\psi\in C^\infty(\overline{\Omega})$ with $\supp \chi \cap \supp \psi=\emptyset$, then for any $N$ there exists $C>0$ such that for all $k>k_0$, 
\begin{equation}
\label{e:pseudoloc_in_pml}
\|\chi R_k\psi\|_{L^2\to H_k^N}+\|\psi R_k\chi\|_{L^2\to H_k^N}\leq Ck^{-N}.
\end{equation}
\end{theorem}

Theorem \ref{thm:PML} is based on ellipticity in the PML region.

\section{Abstract pseudolocality results}
\label{sec:pseudolocS}

As described in \S\ref{s:sketch},
