In what follows, $(\cH,\|\cdot\|_{\cH})$ is a Hilbert space and for every $k \in \R_+$, $(\Hspace{n},\|\cdot\|_{\Hspace{n}})_{n \in \mathbb{N}}$ is a decreasing sequence of Hilbert spaces with continuous and dense inclusions $\Hspace{n} \subset \Hspace{m}$ for all $m \leq n$, with
$$\|u\|_{\cH_k^m} \leq \|u\|_{\cH_k^{n}} \quad \tfa u \in \cH_k^n$$ 
and such that $\Hspace{0} = \cH$ with equal norms.\footnote{Notice that the abstract setup is in many parts similar to \cite{GS3}, but here it is not assumed that the inclusions $\Hspace{n} \subset \Hspace{m}$ are compact for $n>m$.} For all $n \in \mathbb{N}$, $\Hspace{-n}$ denotes the {\em anti}-dual of $\Hspace{n}$, i.e., the set of continuous complex-valued {\em anti}-linear forms on $\Hspace{n}$. For any $u \in \cH$, one may define an element $L^n_u \in \Hspace{-n}$ by
$$L^n_u(v) := \langle u,v\rangle := (u,v)_{\cH} \qquad \tfa v \in \Hspace{n}.$$  
By density of the embeddings $\Hspace{n} \subset \Hspace{m} \subset \cH$ for $n \geq m$, the mapping $u \mapsto L_u^n$ is injective and $L^n_u$ coincides with $L^m_u$ on $\Hspace{m}$, so we may identify $u$ with $L_u$. Under this identification, the continuous embeddings $\Hspace{n} \subset \Hspace{m}$ for $n\geq m$ extend to all $m,n \in \Z$ and $\langle \cdot,\cdot\rangle$ extends to a continuous sesquilinear (linear on the left, anti-linear on the right) pairing $\cH_k^{-n} \times \cH_k^{n}$ for all $n$.
%Let $X\subset \cap_n\Hspace{n}$ be a topological vector space with dense inclusion in $\cH$. 

Let $(a_k)_{k \in \R_+}$ be a family of sesquilinear forms 
$$a_k : \Hspace{1} \times \Hspace{1}\to \mathbb{C}\quad\tfa k\geq 0,$$



\begin{assumption}[$k$-uniform Continuity] 
	\label{ass:cont}
	For every $k_0 \in \R$, there exists a positive constant $C_0(k_0)>0$  such that, for all $k \geq k_0$ and all $u,v \in \cH^1_k$, 
	\[ |a_k(u,v)| \leq C_0(k_0) \|u\|_{\cH^1_k} \|v\|_{\cH^1_k}.\]
\end{assumption}
\begin{assumption}[G\aa rding inequality] 
	\label{ass:Gar}
	For every $k_0 \in \R$, there exist positive constants $\cGa(k_0)$ and $\CGa(k_0) > 0$ such that, for all $k \geq k_0$, 
	\[\Re( a_k(u,u)) \geq \cGa(k_0)\|u\|_{\Hspace{1}}^2 - \CGa(k_0) \|u\|_{\cH}^2\qquad \tfa u \in \Hspace{1}. \]
\end{assumption}
Let $\Re a_k$ denote the Hermitian part of $a_k$, i.e.
$$(\Re  a_k)(u,v) := \frac{1}{2} \left(a_k(u,v) + \overline{a_k(v,u)}\right).$$
We fix a closed subspace $\cZ_k \subset \cH^1_k$ (possibly $\cH^1_k$ itself) which is dense in $\cH$ with respect to the $\cH$ norm, and make the following assumption:
\begin{assumption}[Domain symmetry]
	\label{ass:domComp}
	The spaces 
	$$\big\{u\in \cZ_k\,:\, \sup_{v \in \cZ_k, \|v\|_{\cH}=1} |a_k(u,v)| < +\infty \big\}\,, \qquad \big\{u\in \cZ_k\,:\, \sup_{v \in \cZ_k, \|v\|_{\cH}=1} |a_k(v,u)| < +\infty \big\}\,,$$
	$$ \tand \quad  \big\{u\in \cZ_k\,:\, \sup_{v \in \cZ_k, \|v\|_{\cH}=1} \big|\big(\Re a_k\big)(u,v)\big| < +\infty \big\}$$ 
	are equal and contained in $\Hspace{2}$. We denote  their common value by $\Zspace{2}$.
\end{assumption}
\begin{remark}[Boundary conditions]
In practice, the space $\Zspace{2}$ will be a subset of $H^2(\Omega)$ with Dirichlet/Neumann conditions on (parts of) $\partial \Omega$. Dirichlet conditions will be enforced ``essentially'' by the choice of $\cZ_k$, and Neumann conditions will appear ``naturally'' in $\Zspace{2}$ as a result of a lack of Dirichlet condition. 
\end{remark}
Due to the density of $\cZ_k$ in $\cH$ and the Riesz representation theorem, this allows to state the following definition
\begin{definition}[The operators $P_k$, $P_k^*$ and $\cP_k$]
For all $u \in \Zspace{2}$, define $P_k u$ and $P_k^* u$ as the unique elements of $\cH$ such that for all $v \in \cZ_k$ 
\beq\label{eq:crapatrunning1}
\langle P_k u,v\rangle = a_k(u,v) \tand  \langle P_k^* u,v\rangle = \overline{a_k(v,u)}.
\eeq
Furthermore, let
$$\cP_k u := \frac{1}{2}\left( P_k u +  P_k^*u\right).$$
\end{definition} 
\begin{proposition}
\label{prop:Pksa}
The space $\cZ_k^2$ is dense in $\cH$ and $\cZ_k$ for their respective norms, i.e.
$$\overline{\Zspace{2}}^{\|\cdot\|_\cH} = \cH \quad \tand \quad \overline{\Zspace{2}}^{\|\cdot\|_{\cZ_k}} = \cZ_k$$
Moreover, $\cP_k : \cZ_k^2 \to \cH$ is an unbounded self-adjoint operator. Its spectrum satisfies
$$\sigma(\cP_k) \subset [-\CGa(k_0),+\infty).$$
\end{proposition}
\begin{proof}
The continuity and G\aa rding inequality, and the fact that $\cZ_k$ is a closed subspace of $\cH^1_k$ that is dense in $\cH$ (for the $\|\cdot\|_{\cH}$ norm) imply that the restriction of $\Re a_k$ to $\cZ_k$ is a lower semi-bounded closed Hermitian form in the sense of \cite[Chap. 10]{schmudgen2012unbounded}, and $\cP_k$ is the operator associated to $\Re a_k$ in the sense of \cite[Definition 10.4]{schmudgen2012unbounded}. The density of $\cZ_k^2$ in $\cH$ and the self-adjointness of $\cP_k$ then follows from \cite[Theorem 10.7]{schmudgen2012unbounded}. The density of $\cZ_k^2$ in $\cZ_k$ is Proposition 10.5(iv) in the same reference. The lower bound on the spectrum is by Proposition 10.4 in the same reference. 
\end{proof}
\begin{proposition}
$\Zspace{2}$ is a Hilbert space under the norm 
\beq\label{e:zoomWorking1}
\|u\|_{\Zspace{2}} := \|\big(\cP_k + (\CGa(k_0) + 1) \Id\big)u\|_{\cH}.
\eeq
\end{proposition}
\begin{proof}
The operator $A := \big(\cP_k + (\CGa(k_0) + 1) \Id\big)u$ is self-adjoint, thus closed (since the adjoint operator is closed by, e.g., \cite[Prop.~1.6]{schmudgen2012unbounded}), so its graph norm makes $\Zspace{2}$ a Hilbert space. Furthermore, its spectrum is contained in $[1,+\infty)$, so that
$$(Au,u)_{\cH} \geq \|u\|^2_{\cH} \implies \|Au\|_{\cH} \geq \|u\|_{\cH}.$$
Thus, 
$$\|Au\|_{\cH} \leq \|Au\|_{\cH} + \|u\|_{\cH} \leq 2\|Au\|_{\cH},$$
concluding the proof. 
\end{proof}


We denote  the dual of $\Zspace{2}$ by $\Zspace{-2}$, and identify $\cH$ and $\cZ_k$ as subspaces of $\Zspace{-2}$ -- this identification is possible by the density of $\Zspace{2}$ in $\cH$. There are then unique linear continuous extensions of the operators $P_k$, $P_k^*$ and $\cP_k$ from $\cH$ to $\Zspace{-2}$ by 
$$\langle P_k u, v\rangle := \langle u,P_k^* v\rangle, \quad \langle P_k^* u, v\rangle := \langle u,P_k v\rangle\,, \quad \langle \cP_k u,v \rangle := \langle u,\cP_k v \rangle,$$
for all $u \in \cH$ and $v \in \Zspace{2}$. With these definitions, the operator $P_k^*$ is indeed the conjugate adjoint of $P_k$, as the notation 
\eqref{eq:crapatrunning1}
suggests. 

\begin{remark}[$P_k$ is not a differential operator]
\label{rem:Pknotdiff}
In the model settings of Table \ref{tab:model_settings}, $P_k$ is not a differential operator. For instance, in the case of the Neumann Laplacian, although
