\begin{proposition}
\label{prop:PkZk}
The operators $P_k$ and $P_k^*$ map  $\cZ_k$ to $\cZ_k^*$ continuously, and they satisfy
$$\langle P_k u,v\rangle = a_k(u,v), \quad \langle P_k^* u,v\rangle = \overline{a_k(v,u)} \quad \tfa u,v\in \cZ_k,$$
$$\max(\|P_k u\|_{\cZ_k^*}, \|P_k^* u\|_{\cZ_k^*})\leq C_0(k_0)\|u\|_{\cZ_k} \quad \tfa u \in \cZ_k.$$
\end{proposition}
\begin{proof}
We observe that for $u \in \cZ_k$ and $v \in \Zspace{2}$,
$$\langle P_k u,v\rangle=\langle  u,P_k^*v\rangle = (u,P_k^* v)_\cH = \overline{(P_k^* v,u )_{\cH}}= \overline{\langle P_k^* v,u \rangle} = \overline{\overline{a_k(u,v)}} = a_k(u,v)$$
and thus
$$|\langle P_k u,v\rangle| \leq C_0(k_0) \|u\|_{\cZ_k} \|v\|_{\cZ_k}.$$
The conclusion follows by density of $\Zspace{2}$ in $\cZ_k$ for the $\cZ_k$ norm. The reasoning for $P_k^*$ is similar.
\end{proof}
\begin{definition}[The resolvent norm $\rho(k)$]
Given $k \geq 0$, if $P_k : \cZ_k \to \cZ_k^*$ is invertible, we define 
\beq\label{e:rhoHtoH}
\rho(k) := \sup_{f \in \cH \setminus \{0\}} \frac{\|P_k^{-1}f\|_{\cH}}{\|f\|_{\cH}}.
\eeq
\end{definition}

\begin{proposition}
\label{prop:ResboundZkZk}
Suppose that $P_k : \cZ_k \to \cZ_k^*$ is invertible. Then $P_k^*:\cZ_k \to \cZ_k^*$ is also invertible and for all $k_0 > 0$, there exists $C > 0$ such that for all $k \geq k_0$, 
$$\|P_k^{-1}u\|_{\cZ_k} + \|(P_k^*)^{-1}u\|_{\cZ_k} \leq C\big(1+ \rho(k)\big) \|u\|_{\cZ_k^*}.$$
Moreover, for all $z \in \mathbb{C}\setminus \R$, $(\cP_k - z) : \cZ_k \to \cZ_k^{*}$ is invertible and
$$\|(\cP_k - z)^{-1} u\|_{\cZ_k} \leq C \frac{\langle z \rangle}{|\Im(z)|} \|u\|_{\cZ_k^*}$$
where $\langle z \rangle = (1 + |z|^2)^{1/2}$.
\end{proposition}
\begin{proof}
Let $k_0 > 0$ be fixed and denote by $C$ a generic constant depending only on $k_0$. For $u \in \Zspace{*}$, the G\aa rding inequality gives
\begin{align}\nonumber
\|P_k^{-1}u\|_{\cZ_k}^2 &\leq C\left(\textup{Re}(a_k(P_k^{-1}u,P_k^{-1}u)) + \|P_k^{-1}u\|^2_{\cH}\right) \\\label{e:moreclever}
& \leq C\left(\textup{Re}(\langle u,P_k^{-1}u\rangle) + \|P_k^{-1}u\|^2_{\cH}\right)
\end{align}
Now if, moreover, $u \in \cH$, then
$\|P_k^{-1}u\|_{\cZ_k}^2 \leq C\left(\|u\|_{\cH} \|P_k^{-1}u\|_{\cH} + \|P_k^{-1}u\|^2_{\cH}\right)$
Thus, 
$$\|P_k^{-1}u\|_{\cZ_k} \leq C (\|u\|^2_{\cH} + \|(P_k^{-1}u)\|^2_{\cH}),$$
which implies 
$$ \|P_k^{-1}\|_{\cH \to \cZ_k} \leq C \big(1 + \rho(k)\big).$$ 
By the same argument, using that $\rho(k) = \|P_k^{-1}\|_{\cH \to \cH} = \|(P_k^{*})^{-1}\|_{\cH \to \cH}$ (since $P_k^{-1}: \cH\subset \Zspace{*}\to \Zspace{}\subset \cH$),
$$\|(P_k^*)^{-1}\|_{\cH \to \cZ_k} \leq C\big(1 + \rho(k)\big).$$
Thus by duality, 
$$\|P_k^{-1}\|_{\cZ_k^* \to \cH} \leq C( 1+ \rho(k)).$$
Using this in the right-hand side of \eqref{e:moreclever} as well as the inequality 
\beq\label{e:peterPaul}
2ab\leq \e a^2+\e^{-1}b^2 \quad\tfa a,b,\e>0,
\eeq 
we obtain for all $\varepsilon \in (0,1)$ sufficiently small, 
$$\|P_k^{-1}u\|_{\cZ_k} \leq C \left(\varepsilon \|P_k^{-1}u\|^2_{\cZ_k} + (\varepsilon^{-1}+ \rho(k)) \|u\|^2_{\cZ_k^*}\right)$$
and thus 
$$\|P_k^{-1}\|_{\cZ_k^*\to \cZ_k} \leq C(1+ \rho(k)).$$
We obtain the analogous bound for $(P_k^*)^{-1}$ by duality. The proof of the bound $\|(\cP_k - z)^{-1}\|_{\cZ_k^* \to \cZ_k}$ is similar, first estimating $\|(\cP_k - z)^{-1}\|_{\cH \to \cZ_k}$, using that 
$$\|(\cP_k - z)^{-1}u\|_{\cH} \leq \frac{1}{|\Im(z)|} \|u\|_{\cH},$$
since $\cP_k$ is self-adjoint on $\cH$. 
\end{proof}
\begin{definition}[The spaces $\Zspace{n}$]\label{def:Zspaces}
Let
$$\Zspace{n} := \begin{cases}
\cH & \textup{if } n = 0\\
\cZ_k & \textup{if } n = 1\\
\Zspace{2} \cap \Hspace{n} & \textup{if } n \geq 2\\
\end{cases}$$
(recalling for $n=2$ that $\Zspace{2} \subset \Hspace{2}$ by Assumption \ref{ass:domComp}).
For $n \geq 2$, the norm
$$\|u\|^2_{\cZ_k^n} := \|u\|^2_{\Zspace{2}} + \|u\|^2_{\Hspace{n}},$$
makes $\Zspace{n}$ a Hilbert space. We denote the dual of $\Zspace{n}$ by $\Zspace{-n}$  for all $n \geq 0$. 
\end{definition}
\begin{assumption}[Continuity of $P_k$ and $P_k^*$]
\label{ass:contPk}
For all $n \in \mathbb{N}$, the operators $P_k$ and $P_k^*$ define continuous maps
$$P_k, P_k^* : \Zspace{n+2}\to \cH_k^{n}.$$
For all $k_0 > 0$ and $n \in \mathbb{N}$, there exists $C(k_0) > 0$ such that for all $k \geq k_0$,
$$\|P_k u\|_{\cH_k^n} + \|P_k^* u\|_{\cH_k^n} \leq C(k_0) \|u\|^2_{\cZ_k^{n+2}}.$$
\end{assumption}

\begin{remark}
The idea behind Assumption \ref{ass:contPk} is that $P_k$ and $P_k^*$ can only act on functions satisfying the chosen boundary condition, and they remove this boundary condition as well as decreasing the regularity index by $2$. Thus, given $a_k(\cdot,\cdot)$, $\Hspace{}, \Hspace{1}, \Hspace{2}$ and $\Zspace{}$, Assumption \ref{ass:contPk} can be considered as constraining the spaces $\Hspace{n}$ for $n\geq 3$.% (e.g., the only condition up to now on the spaces $\Hspace{n}$ for $n\geq 3$ is that the inclusion $\Hspace{n} \subset \Hspace{m}$ is dense for all $m \leq n$).
\end{remark}

Because of this, we can extend $P_k$ and $P_k^*$ uniquely into continuous linear maps from $\Hspace{-n}$ to $\Zspace{-n-2}$ for $n \geq 0$ by setting 
$$\begin{cases}
\langle P_k u,v \rangle := \langle u,P_k^*v\rangle,\\
\langle P_k^* u,v \rangle := \langle u,P_k v\rangle,
\end{cases} \quad \tfa v \in \Zspace{n+2}.$$
To state more conveniently the mapping properties of $P_k$ and $P_k^*$, we define the Hilbert spaces
\beq\label{e:capcupdefs}
\ZcapHspace{n} := \Zspace{n} \cap \Hspace{n}, \qquad \ZcupHspace{n} := \Zspace{n} + \Hspace{n}.
\eeq
By the inclusion $\Zspace{n} \subset \Hspace{n}$ for $n\geq 0$ and duality,  %(and thus $\ZcapHspace{n}= \Zspace{n}$ and $\ZcupHspace{n}= \Hspace{n}$), 
%while the opposite inclusion is true for $n \leq 0$.
%Therefore
\begin{equation}
\ZcapHspace{n} = \begin{cases}
\Zspace{n} & \textup{if } n \geq 0,\\
\Hspace{n} & \textup{if } n \leq 0,
\end{cases} \quad \tand \quad \ZcupHspace{n} = \begin{cases}
\Hspace{n} & \textup{if } n \geq 0,\\
\Zspace{n} & \textup{if } n \leq 0.
\end{cases}
\end{equation}
Thus, since $\Zspace{-n}= (\Zspace{n})^*$, 
\beqs%\label{e:dualNewSpaces}
\ZcupHspace{-n} = (\ZcapHspace{n})^*, \quad\tfa n\in \mathbb{Z}.
\eeqs


One may think of $\cW_k^n$ (respectively $\cY_k^n)$ as the space ``with'' (respectively ``without'') boundary conditions, and the application of $P_k$ ``removes'' the boundary conditions. 
\begin{proposition}[$P_k, P_k^*$ and $\cP_k$ map $\ZcapHspace{n+2}$ to $\ZcupHspace{n}$ continuously]
For all $n \in \mathbb{Z}$ and $k_0 > 0$, there exists $C > 0$ such that for all $k \geq k_0$ and all $u \in \ZcapHspace{n}$, 
$$\|P_k u\|_{\ZcupHspace{n}} + \|P_k^* u\|_{\ZcupHspace{n}} + \|\cP_k u\|_{\ZcupHspace{n}} \leq C \|u\|_{\ZcapHspace{n+2}}$$
\end{proposition}
\begin{proof}
This is Assumption \ref{ass:contPk} for $n \geq 0$ and follows from it by duality for $n \leq -2$. Finally, Proposition \ref{prop:PkZk} gives the result for $n = -1$ 
\end{proof}
\begin{assumption}[Elliptic regularity]
\label{ass:ell}
Let $Q$ equal either $P_k, P_k^*$ or $\cP_k$ and let $n \in \mathbb{N}$. If 
$$u \in \cH \quad \tand \quad Qu \in \Hspace{n},$$
then $u \in \Zspace{n+2}$, and for all $k_0 > 0$ and $n \in \mathbb{N}$, there exists $C_{\rm ell}(k_0,n) > 0$ such that for all $k \geq k_0$ and $u \in \Zspace{2}$, 
$$\|u\|_{\Zspace{n+2}}  \leq C_{\rm ell}(k_0,n) \Big(\norm{u}_{\cH} + \norm{Qu}_{\Hspace{n}}\Big).$$
\end{assumption}

