\begin{proposition}[Norms of $P_k^{-1}$ and $(P_k^*)^{-1}$ from $\ZcapHspace{n}$ to $\ZcupHspace{n+2}$]\label{prop:Rstar}
Suppose that $P_k : \cZ_k \to \cZ_k^*$ is invertible. Then for all $n \in \mathbb{Z}$,  $P_k^{-1} : \ZcupHspace{n} \to \ZcapHspace{n+2}$ and  $(P_k^*)^{-1} : \ZcupHspace{n} \to \ZcapHspace{n+2}$ are continuous and for all $k_0 > 0$, there exists $C > 0$ such that for all $k \geq k_0$, 
\begin{equation}
\label{e:map_PkPkstar}
\|P_k^{-1}u\|_{\ZcapHspace{n+2}} + \|(P_k^*)^{-1} u\|_{\ZcapHspace{n+2}} \leq C\big(1+\rho(k)\big) \|u\|_{\ZcupHspace{n}}
\end{equation}
where $\rho(k)$ is defined by \eqref{e:rhoHtoH}.
%$$\rho(k) = \sup_{f \in \cH \setminus \{0\}}\frac{\|P_k^{-1} f\|_{\cH}}{\|f\|_{\cH}}$$
\end{proposition}
\begin{proof}
The case $n = -1$ is Proposition \ref{prop:PkZk}. Hence it remains to prove \eqref{e:map_PkPkstar} for $n \geq 0$, since the case $n \leq -2$ follows by duality. We proceed by induction. First, for $n = 0$, let $u \in \cH$. Then $P_k^{-1}u \in \cH$ and thus by elliptic regularity, $u \in \Zspace{2}$ with
$$\|u\|_{\Zspace{2}} \leq C_{\rm ell}(k_0,0) (\|P_k^{-1}u\|_{\cH} + \|u\|_{\cH}) \leq C_{\rm ell}(k_0,0)(1+ \rho(k)) \|u\|_{\cH} \leq C \rho(k) \|u\|_{\cH}$$
by definition of $\rho(k)$, where $C$ depends only on $k_0$. Next, let $n \geq 0$ and suppose that there exists $C > 0$ such that
$$\|P_k^{-1}u\|_{\Zspace{n+2}} \leq C \rho(k) \|u\|_{\Hspace{n}}.$$
Let $u \in \Hspace{n+1}$. Then by elliptic regularity and using the continuous embeddings $\Zspace{n+2} \subset \cH$ and $\Hspace{n+1} \subset \Hspace{n}$, 
\begin{align*}
\|P_k^{-1}u\|_{\Zspace{n+3}} &\leq C_{\ell}(k_0,n+1) (\|P_k^{-1}u\|_{\cH} + \|u\|_{\Hspace{n+1}})\\
& \leq C_{\ell}(k_0,n+1) (\|P_k^{-1}u\|_{\Zspace{n+2}} + \|u\|_{\Hspace{n+1}}) \\
& \leq C_{\ell}(k_0,n+1) (C\rho(k)\|u\|_{\Hspace{n}} + \|u\|_{\Hspace{n+1}}) \\
& \leq C'\rho(k) \|u\|_{\Hspace{n+1}}
\end{align*}
where $C'$ depends only on $k_0$ and $n$. 
\end{proof}

\begin{proposition}[Resolvent norm from $\ZcupHspace{n-1}$ to $\ZcapHspace{n+1}$]\label{prop:rescuedfrombin}
Let $k_0 > 0$ and $n \in \mathbb{Z}$. There exists $C(k_0,n) > 0$ such that for all $k \geq k_0$ and all $z \in \mathbb{C} \setminus \R$, 
\begin{align*}%\label{e:ResBound3}
\|(\cP_k - z)^{-1} \|_{\ZcupHspace{n-1}\to \ZcapHspace{n+1}} &\leq C(k_0,n)\frac{\langle z \rangle^{1+\lfloor  |n|/2\rfloor}}{|\Im(z)|}.
\end{align*}
\end{proposition}


\begin{proof}
The result for $n = 0$ is Proposition \ref{prop:ResboundZkZk}. For $n = 1$, we use that 
$$\|(\cP_k - z)^{-1}u\|_{\cH} \leq \frac{\|u\|_{\cH}}{|\Im(z)|}\,.$$
and the elliptic regularity (Assumption \ref{ass:ell}) to write
\begin{align*}
	\|(\cP_k-z)^{-1}u\|_{\Zspace{2}}&\leq C(\| \cP_k(\cP_k-z)^{-1}u\|_{\cH} +\|(\cP_k-z)^{-1}u\|_{\cH})\\
	&\leq C\Big(\|u\|_{\cH}+|z| \cdot \| (\cP_k-z)^{-1}u\|_{\cH} +\|(\cP_k-z)^{-1}u\|_{\cH}\Big)\\
	&\leq C \frac{\langle z \rangle}{|\Im(z)|}\|u\|_{\cH}.
\end{align*}
Next let $n \geq 0$ and suppose that 
$$\|(\cP_k - z)^{-1}u\|_{\Zspace{n+1}} \leq C \frac{\langle z \rangle^{m}}{|\Im(z)|}\|u\|_{\Zspace{n-1}}$$
for all $u \in \Zspace{n-1}$. Then elliptic regularity gives
\begin{align*}
\|(\cP_k - z)^{-1}u\|_{\Zspace{n+3}} &\leq C \|(\cP_k - z)^{-1} u\|_{\cH} + \|\cP_k(\cP_k - z)^{-1}u\|_{\Zspace{n+1}}\\
& \leq C \Big(|\Im(z)|^{-1}\|u\|_{\cH} + \|u\|_{\Zspace{n+1}} + |z|\cdot \|(\cP_k - z)^{-1} u\|_{\Zspace{n+1}}\Big)\\
& \leq C \Big(|\Im(z)|^{-1}\|u\|_{\cH} + \|u\|_{\Zspace{n+1}} +  \frac{\langle z \rangle^{m+1}}{|\Im(z)|} \|u\|_{\Zspace{n-1}}\Big)\\
& \leq C \frac{\langle z \rangle^{m+1}}{|\Im(z)|} \|u\|_{\Zspace{n+1}}.
\end{align*}
Thus by induction, for all $n \geq 0$, 
$$
\|(\cP_k - z)^{-1}\|_{\ZcupHspace{n-1} \to \ZcapHspace{n+1}} \leq \frac{\langle z \rangle^{ 1+\lfloor |n|/2\rfloor}}{|\Im(z)|}.
$$
The result for $n \leq 0$ follows by duality. 
\end{proof}
