\subsection{The spaces $\Dspace{s}$}

Since $\lambda \mapsto (\lambda + \CGa(k_0) + 1)^{s/2}, s \geq 0,$ is finite for $\lambda\in \sigma(\cP_k)$, the functional calculus of unbounded self-adjoint operators (see, e.g., \cite[Section 5.3]{schmudgen2012unbounded}) allows us to define the self-adjoint operator 
\beq\label{e:zoomWorking3}
\cX_{k,s} := (\cP_k + (\CGa(k_0) + 1)\Id)^{s/2}
\eeq
with domain $$\Dspace{s} := \mathcal{D}(\cX_{k,s}) \subset \cH$$ 
where the inclusion is dense in the $\cH$ norm.
Since the functional calculus is an algebra homomorphism, $\cX_{k,s} = \cX_{k}^s$, where $\cX_k := \cX_{k,1}$. Since $\cX_k^s$ is self-adjoint, it is, in particular, a closed operator, so the space $\cD_k^s$ is a Hilbert space for the graph norm
\beqs%\label{e:graphNorm}
\|u\|^2_{\cX_k^s} := \|u\|^2_{\cH} + \|\cX_k^s u\|^2_{\cH}.
\eeqs
Moreover, 
%by the functional calculus, 
$\sigma(\cX_k^s) \subset [1,+\infty)$, hence 
$$\|u\|^2_{\cH} \leq (u,\cX_k^s u)_{\cH} \leq \|u\|_{\cH} \|\cX_k^s u\|_{\cH},$$
so the graph norm associated of $\cX_k^s$ is equivalent to the norm
\beq\label{e:zoomWorking2}
\|u\|^2_{\cD^s_k} := \|\cX_k^{s} u\|^2_{\cH}.
\eeq
This way, the operator $\cX_k^t$ induces an isometry from $\cD^s_k$ to $\cD_k^{s-t}$ for all $s \geq t \geq 0$. 
\begin{proposition}
\label{prop:Z2=D2}
$\Zspace{2} = \Dspace{2}$ with equal norms. Furthermore $\cZ_k = \mathcal{D}^{1}_k$ with equivalent norms; more precisely, for all $k_0 >0$, there exist constant $C(k_0) > 0$ such that for all $k \geq 0$ and for all $u \in \mathcal{D}^2$
$$\frac{1}{C(k_0)} \|u\|_{\cZ_k} \leq \norm{u}^2_{\cD_k^1} \leq C(k_0) \|u\|_{\cZ_k}.$$
\end{proposition}
\begin{proof}
The first statement follows from the fact that $\cX_k^2$ and $\cP_k$ differ by a multiple of identity, and by the definition of the norm of $\Zspace{2}$ (compare \eqref{e:zoomWorking1} with the combination of \eqref{e:zoomWorking3} and \eqref{e:zoomWorking2}). On the other hand, $\cX_k^2$ is the operator associated to the lower semi-bounded form $a_k^+ : \cZ_k \times \cZ_k \to \C$ defined by
$$a_k^+(u,v) := \Re a_k(u,v) + (\CGa(k_0) + 1) (u,v)_{\cH}$$
in the sense of \cite[Definition 10.4]{schmudgen2012unbounded}. In particular, by Theorem 10.7 and Proposition 10.5 in the latter reference, 
$$\cZ_k = \mathcal{D}(|\cX_k^2|^{1/2}) = \mathcal{D}(\cX_k) = \Dspace{1}.$$
The equivalence of the norms follows from the continuity of $\Re a_k$ and the G\aa rding inequality. 
\end{proof}
\begin{corollary}
\label{cor:DnsubZn}
For all $n \in \mathbb{N}$, $\Dspace{n} \subset \Zspace{n}$ and the embedding is continuous. 
\end{corollary}
\begin{proof}
The result is immediate if $n = 0$ and is Proposition \ref{prop:Z2=D2} above for $n = 1,2$. Finally, if $u \in \cD_k^{n+2}$, then 
$$\cP_k u = (\cX_k^2 - \CGa(k_0) + 1)u \in \cD_k^{n}$$
so the result follows by induction using elliptic regularity (Assumption \ref{ass:ell}).
\end{proof}

\

We also define $\cD_k^{-s} := (\cD_k^s)^*$. 
Since $\Dspace{s}$ is dense in $\Hspace{}$ for $s\geq 0$, $\cH$ can be identified as a subspace of $\Dspace{-s}$, so that 
$\cD_k^{t} \subset \cD_k^s$ for all real $s \leq t$. We can extend $\cX_k$ uniquely into a linear map from $\cD_k^s$ to $\cD_k^{s-1}$ for all $s \in [0,1]$ by putting
$$\langle\cX_k u,v\rangle := \langle \cX_k^{s}u,\cX_k^{1-s} v\rangle \quad \tfa (u,v) \in \cD_k^s \times \cD_k^{1-s}.$$ 
This way, $\cX_k : \cD_k^{s} \to \cD_k^{s-1}$ for all $s \in [0,+\infty)$ is an isometry and this is extended to $s \leq 0$ by duality. In turn, this allows us to view $\cP_k$ as a map $\cP_k: \cD_k^s \to \cD_k^{s-2}$ for all $s \in \R$ by $\cP_k := \cX_k^2 - (\CGa(k_0)+1)\Id$, with 
$$\|\cP_k u\|_{\cD_k^{s}} \leq (\CGa(k_0) + 1)\|u\|_{\cD_k^{s+2}}.$$

\begin{proposition}[Resolvent estimates in the $(\cD_k^s)$ scale]\label{prop:neverInBin}
Let $k_0 > 0$ and $s \in \mathbb{R}$. There exists $C > 0$ such that for all $k > 0$ and all $z \in \mathbb{C} \setminus \R$, 
$$\|(\cP_k - z)^{-1}\|_{\cD_k^s \to \cD_k^s} \leq  |\Im(z)|^{-1},$$
$$ \|(\cP_k - z)^{-1}\|_{\cD_k^s \to \cD_k^{s+2}} \leq  C\langle z \rangle|\Im(z)|^{-1},$$
where $\langle z \rangle := 1 + |z|$. 
\end{proposition}
\begin{proof}
Using the fact that $\cX_k^s : \cD_k^s \to \cH$ is an isometry, and functional calculus,
$$\|(\cP_k - z)^{-1}\|_{\cD_k^s \to \cD_k^s} \leq \|\cX_k^s (\cP_k - z)^{-1} \cX_k^{-s}\|_{\cH \to \cH} = \|(\cP_k - z)^{-1}\|_{\cH \to \cH} \leq |\Im(z)|^{-1}.$$
Similarly, 
$$\|(\cP_k - z)^{-1}\|_{\cD_k^{s} \to \cD_k^{s+2}} = \|\cX_k^{s+2} \big(\cX_k^2 - (\CGa + z)\big)^{-1} \cX_k^{-s} \|_{\cH \to \cH}  = \|g(\cX_k^2)\|_{\cH \to \cH} \leq \sup_{x \in \R} |g(x)|$$
where $g(x) := \frac{x}{x- (z + \CGa)}$. Since for all $z \in \C \setminus \R$, 
$$\sup_{x \in \R} \left|\frac{x}{x-z}\right| = \frac{|z|}{|\Im(z)|},$$
we conclude that 
$$\sup_{x \in \R}|g(x)| \leq (1 + \CGa) \langle z \rangle |\Im(z)|^{-1},$$
completing the proof. 
\end{proof}

\begin{proposition}[Functions of $\cP_k$]
\label{prop:f(Pk)}
Let $k_0 > 0$ and $s \geq 0$. There exists $C > 0$ such that, for all $k \geq k_0$ and for any function $f : \mathbb{R} \to \mathbb{C}$ satisfying 
$$\|f\|_{\infty,s} := \sup_{x \in \R} (1 + |x|^s)|f(x)| < \infty,$$
the operator $f(\cP_k) : \cH \to \cH$ defined by the functional calculus extends uniquely into a continuous map from $\cD_k^{-s}$ to $\cD_k^{s}$, with
$$\|f(\cP_k)\|_{\cD_k^{-s} \to \cD_k^{s}} \leq C \|f\|_{\infty,s}.$$
In particular (by Corollary \ref{cor:DnsubZn} and the definitions of $\ZcupHspace{n}$ and $\ZcapHspace{n}$ \eqref{e:capcupdefs}) for any $n\in \mathbb{N}$, $f(\cP_k) : \ZcupHspace{-n} \to \ZcapHspace{n}$ is continuous.
\end{proposition}
\begin{proof}
By functional calculus and using that $\cX_k^t = (\cP_k + \CGa(k_0) + 1)^{t/2} : \cD_k^t \to \cH$ is an isometry for all $t \in \R$, 
$$\|f(\cP_k)\|_{\cD_k^{-s} \to \cD_k^{s}} \leq \|(\cP_k + \CGa(k_0) + 1)^{s/2}f(\cP_k)(\cP_k + \CGa(k_0) + 1)^{s/2}\|_{\cH\to \cH} = \|g(\cP_k)\|_{\cH \to \cH}$$
where $g(x) = (\CGa + 1 + x)^{s} f(x)$ satisfies
$$|g(x)| \leq 2^{s}(\CGa + 1)^s (1 + |x|^s) |f(x)|$$
for all $x \in \sigma(\cP_k)$. Hence, $\|g(\cP_k)\|_{\cH \to \cH} \leq C \|f\|_{\infty,s}$ and the claim follows. 
\end{proof}


\subsection{Elliptic perturbation of $P_k$}
\label{sec:Pksharp}
By Proposition \ref{prop:Pksa}, for every $k_0 > 0$, there exists a real-valued, compactly supported function $\psis \in C^\infty_c(\R)$ such that
\begin{equation}
	\label{eq:conditionPsi}
	\psis(x) \geq \frac{-x + \CGa}{2}\quad\tfa x \in \sigma(\cP_k).
\end{equation}
Following \cite[Lemma 2.1]{GS3}, define 
\begin{equation}
\label{e:def_Sk}
S_k := \psis(\cP_k)
\end{equation}
by the functional calculus. Since $\psis$ has compact support, 
$$S_k : \cD_k^{-n} \to \cD_k^{n}$$ is continuous for all $n \in \mathbb{N}$ by Proposition \ref{prop:f(Pk)}. In what follows, the {\em elliptic perturbation} of $P_k$ is defined by 
\begin{equation}
\label{e:defPksharp}
P^{\sharp}_k := P_k + S_k.
\end{equation}
The associated sesquilinear form, denoted by $a_k^\sharp: \cZ_k \times \cZ_k \to \mathbb{C}$, is thus given by
\begin{equation}
	\label{def:aksharp}
	a_k^\sharp(u,v) := a_k(u,v) + (S_k u,v)_{\cH}.
\end{equation}
\newcommand{\Csharp}{C_{\sharp}}
\begin{proposition}[Properties of $P^\sharp_k$]
	\label{prop:ResPksharp}
	For every $k_0 > 0$ and any integer $n$, there exists a positive constant $\Csharp(k_0,n)$ such that, for all $k \geq k_0$, 
	\begin{equation}
		\label{eq:CoerciveAsharp}
		\Re (a_k^\sharp(u,u)) \geq \Csharp(k_0,1) \|u\|^2_{\cZ_k} \quad \tfa u \in \cZ_k,
	\end{equation}
	the operator $P_k^\sharp : \ZcapHspace{n+2} \to \ZcupHspace{n}$ is an isomorphism, and
	\[\|(P_k^\sharp)^{-1}u\|_{\ZcapHspace{n+2}} \leq \Csharp(k_0,n) \|u\|_{\ZcupHspace{n}} \quad \tfa u \in \ZcupHspace{n}. \]
\end{proposition}
\begin{proof} 
%	Let $a_k^\sharp(u,v):=a_k(u,v) + (S_k u,v)_{\cH}$ for $u,v \in \cZ_k$. This defines a continuous sesquilinear form on $\cZ_k \times \cZ_k$. 
	By \eqref{eq:conditionPsi},
	\beqs
	x + \psi^\sharp(x) \geq \frac{1}{2} (x+ \CGa) \quad \tfa x \in \sigma(\cP_k). 
	\eeqs
	Therefore, by the functional calculus, for all $u \in \Zspace{1}$,
	\[\Re(a_k^{\sharp}(u,u)) = \Re a_k(u,u) + (\psi^\sharp(\cP_k)u,u)_{\cH} =  \big(\cP_k + \psi^\sharp(\cP_k) u,u\big)_{\cH} \geq \frac{1}{2}\big((\cP_k + \CGa \Id) u,u\big)_\cH.\]
	%using the fact that $\cP_k + \psi(\cP_k) \geq \frac{1}{2}(\cP_k+ \CGa \Id)$. 
	Hence, by the G\aa rding inequality, 
	\[\Re(a_k^\sharp(u,u)) \geq \frac{\cGa}{2} \|u\|^2_{\cZ_k}
	\quad\tfa u\in \Zspace{2},\]
and the same inequality holds for all $u \in \cZ_k$ by the density of $\cZ^2_k$ in $\cZ_k$ and continuity of $a_k^\sharp$. Thus, $a_k^\sharp$ is coercive, and the Lax-Milgram lemma implies that $P^\sharp_k :\cZ_k \to (\cZ_k)^*$ is boundedly invertible; this is the required result for $n = 1$. With $n \geq 2$, let $u \in \Hspace{n-2}$ and suppose that $v \in \cZ_k$ satisfies $P^\sharp_k v = u$. Then $P_k v = u - S_k v \in \Hspace{n-2}$ (by the smoothing property of $S_k$ from Proposition \ref{prop:f(Pk)}), so that $v \in \Zspace{n}$ by elliptic regularity (Assumption \ref{ass:ell}). Moreover, since $\|v\|_{\cH} \leq \|v\|_{\cZ_k} \leq \|u\|_{\cZ_k^*}$ (again by the Lax-Milgram lemma), 
\begin{align*}
\|v\|_{\Zspace{n}} 
&\leq C\big(\|v\|_{\cH} + \|u - S_k v\|_{\Hspace{n-2}}\big)\leq C\big(\|u\|_{(\cZ_k)^*} + \|u\|_{\Hspace{n-2}}\big) 
\leq C\|u\|_{\Hspace{n-2}},
\end{align*}
which proves the result for $n \geq 2$. The same reasoning applied to $P_k^* + S_k^* = P_k^* + S_k$ followed by a duality argument (recalling that the dual of  $\ZcupHspace{n}$ is $\ZcapHspace{-n}$) gives the result for $n \leq 0$.
\end{proof}

\subsection{Order notation}\label{sec:order_notation}

\newcommand{\etak}{\eta}
Let
$$\ZcapHspace{\infty} := \bigcap_{n \in \Z} \ZcapHspace{n}\,, \quad \ZcapHspace{-\infty} := \bigcup_{n\in \Z} \ZcapHspace{n},$$
and define $\ZcupHspace{\pm\infty}$ and $\cD_k^{\pm\infty}$ similarly. 


\begin{definition}[Order notation]
\label{def:orderNotation}
Let $(\eta_k)_{k>0}$ be a family of real numbers.
Let $m,n \in \Z$ and let $L : \cW_k^\infty \to \cY_k^{\infty}$ be a linear operator. 
Then
$$L = O_{m}(\eta^{n};\ZcapHspace{} \to \ZcupHspace{})$$
if, for all $k_0 > 0$ and for all $j \in \mathbb{Z}$, there exists a real number $C(k_0,j) > 0$ such that for all $k \geq k_0$ and all $u \in \ZcapHspace{j}$, 
\beq\label{e:rocky1}
\|L u\|_{\ZcupHspace{j-m}} \leq C(k_0,j) \eta_k^{n} \|u\|_{\ZcapHspace{j}}.
\eeq
The notations $L = O_{m}(\eta^{n};\ZcupHspace{} \to \ZcupHspace{})$, $L = O_{m}(\eta^{n};\cD_k \to \cD_k)$ are defined similarly. 
\end{definition}

Observe that these order relations can then be combined multiplicatively; e.g., 
$$L_1 = O_{m}(\eta^{n};\ZcapHspace{} \to \ZcupHspace{})\,, \,\, L_2 = O_{m'}(\eta^{n'};\ZcupHspace{} \to \ZcapHspace{}) \implies L_1L_2 = O_{m + m'}(\eta^{n + n'}; \ZcupHspace{} \to \ZcupHspace{}).$$



