	An operator $t_N$ is called an {\em $(N,z)$-term} if it is of the form
	\[t_N =\sum_{j = 1}^J \sigma_j Y_z^{-1}a_{N,j}\] 
	where $J \in \mathbb{N}$, $\sigma_j$ are real coefficients and $a_{N,j}$ are $(N,z)$-atoms. For example, 
	$$t_5 = Y_z^{-1} (\ad_{X}^5 Y_z) Y_z^{-1}  - Y_z^{-1} (\ad_{X}^2 Y_z) Y_z^{-1} (\ad_{X}^{3} Y_z) Y_z^{-1}$$ 
	is a $(5,z)$-term. Notice that if $t_i$ and $t_j$ are $(i,z)$- and $(j,z)$-terms, then $t_i Y_z t_j$ is an $(i+j,z)$-term. 

	It follows immediately from assumptions (a) and (b), by induction on $N$, that if $t_N(z)$ is a $(N,z)$-term for all $z \in \Omega$, then
	\[t_N(z) =(1+C_1(z))^{N+1} (1+C_2(z))^{N} O_{- 2+N(m-1)}(\etak^{-N} \langle z\rangle^{M_n};\ZcupHspace{}\to \ZcapHspace{}).\]
	Thus it remains to show that for all $z \in \Omega$, $\ad_{X}^NY_z^{-1}:\cH\to \cH$ is an $(N,z)$-term. For this, it suffices to prove that, for all $N \in \mathbb{N}$, 
	\begin{equation}
		\label{eq:adRNterm}
		t_N \textup{ is an $(N,z)$-term } \quad \implies \quad \ad_X t_N \textup{ is an $(N+1,z)$-term}.
	\end{equation}
	By linearity, it is enough to prove \eqref{eq:adRNterm} in the case where $t_N = Y_z^{-1}a_N$ for some $(N,z)$-atom $a_N$. We consider separately the three cases (i), (ii), (iii) above in the definition of an $(N,z)$-atom.
%	\begin{itemize}
%		\item[Case (i):] 

		Case (i):~If $a_N = 1$, then %, since $X:\Dspace{2}\to \Dspace{2}$ and $X:\cH\to \cH$,
		\[\ad_{X}t_N = \ad_X Y_z^{-1} = XY_z^{-1}-Y_z^{-1}X=Y_{z}^{-1}Y_zXY_z^{-1}-Y_{z}^{-1}XY_zY_{z}^{-1}= -Y_z^{-1} (\ad_{X} Y_z) Y_z^{-1}\]
		which is a $(1,z)$-term acting on $u$. This shows the implication \eqref{eq:adRNterm} for $N = 0$, and in the following cases, we fix $N \geq 1$ and proceed by induction assuming that it holds for all $i \leq N-1$. 
%		\item[Case (ii):] 

		Case (ii):~If $a_N = (\ad_X^N Y_z) Y_z^{-1}$, then   
		\[\begin{split}
			\ad_X t_N = \quad & (\ad_X Y_z^{-1}) (\ad_X^N Y_z) Y_z^{-1}+ Y_z^{-1} (\ad_X^{N+1} Y_z) Y_z^{-1}
			+ Y_z^{-1} (\ad_{X}^N Y_z) (\ad_X Y_z^{-1}).
		\end{split}\] 
		The second term on the right-hand side is an $(N+1,z)$-term. The first term on the right-hand side can be rewritten as
		\[-Y_z^{-1} \underbrace{(\ad_ X Y_z)Y_z^{-1}}_{\textup{$(1,z)$-atom}} \underbrace{(\ad_X^N Y_z) Y_z^{-1}}_{\textup{$(N,z)$-atom}}.\]
		This is thus an $(N+1,z)$-term. Similarly, the third term is an $(N+1,z)$-term, and thus $\ad_X t_N$ is an $(N+1,z)$-term.
%		\item[Case (iii):] 	

		Case (iii):~If $a_N = a_i a_j$ then, since $a_j:\cH\to\cH$, 
		$$
		t_N =Y_z^{-1}a_ia_j=Y_{z}^{-1}a_iY_zY_z^{-1}a_j= t_i Y_z t_j
		$$
		 where $t_i := Y_z^{-1}a_i$ and $t_j := Y_z^{-1}a_j$ are $(i,z)$- and $(j,z)$-terms, respectively, with $i+j=n$.  Thus
		\[\ad_X t_N = (\ad_X t_i) Y_z t_j + t_i (\ad_X Y_z) t_j + t_i  Y_z (\ad_X t_j) .\]
		The first term is an $(N+1,z)$-term by the induction hypothesis. Similarly, the last term is an $(N+1,z)$-term. The middle term can be rewritten as
		\[t_i (\ad_X Y_z) t_j = \overbrace{t_i Y_z \underbrace{\underbrace{Y_z^{-1} (\ad_X Y_z) Y_z^{-1}}_{\textup{$(1,z)$-term}} Y_z t_j}_{\textup{$(j+1,z)$-term}}}^{\textup{$(i+(j+1),z)$-term}} \]
		which is an $(N+1,z)$-term. This concludes the proof.
%	\end{itemize}
\end{proof}

