We can now prove the estimate  \eqref{eq:adNR1}.
\begin{proposition}\label{prop:proofadNR1}
	For any $N \in \mathbb{N}$, $f \in \mathcal{S}(\R)$ and $R \in \Lcut^m$,
\beqs
	\ad_{R}^N f(\cP_k) = O_{-\infty}(\etak^{-N}; \ZcupHspace{} \to \ZcapHspace{}).%\cap O_{-\infty}(\etak^{-N}; \ZcapHspace{} \to \ZcapHspace{}).
\eeqs
\end{proposition}
\begin{proof}
By the Helffer--Sj\"ostrand formula, 
	\[\ad_{R}^N f(\cP_k) = \int_{\C} w(z) \ad_{R}^N  (\cP_k - z)^{-1}\,dm_{\C}(z).\]
	By Proposition \ref{prop:atoms} with $X = R$, $\Omega = \C \setminus \R$, $Y_z = (\cP_k - z)$, the first commutator property of spatial cutoffs, and the resolvent estimate 
of Proposition \ref{prop:rescuedfrombin},	
	\[\ad_R^{N} (\cP_k - z)^{-1} = \Big(1+\frac{\langle z \rangle}{\abs{\Im(z)}}\Big)^N O_{-2+N(m-1)}(\etak^{-N}\langle z\rangle^{M_n}; \ZcupHspace{} \to \ZcapHspace{}).\]
	Therefore, 
	\[\ad_R^N f(\cP_k)  = O_{-2+N(m-1)}\left(\etak^{-N}\int_{\C^N} w(z) \langle z\rangle^{M_n}\Big(1+\frac{\langle z \rangle}{\abs{\Im(z)}}\Big)^N dm_{\C}(z); \ZcupHspace{} \to \ZcapHspace{}\right).\]
	The bound \eqref{eq:condw} on $w$ implies that the integral is finite, and thus, for all $f \in \mathcal{S}(\R)$,
	\begin{equation}
		\label{eq:toupgrade}
		\ad_R^N f(\cP_k)  = O_{-2+N(m-1)}(\etak^{-N}; \ZcupHspace{} \to \ZcapHspace{}).
	\end{equation}
	We now upgrade the regularity index from $-2+N(m-1)$ to $-\infty$ by induction on $N$. For $N = 0$, 
	\begin{equation}
		\label{eq:startInduct}
		\ad_{R}^0 f(\cP_k) = f(\cP_k) = O_{-\infty}(1;\ZcupHspace{} \to \ZcapHspace{})
	\end{equation}
	by Proposition \ref{prop:f(Pk)}. Next fix an integer $N \geq 1$ and suppose that for all $i \leq N-1$ and all $g \in \mathcal{S}(\R)$, 
	\[\ad_{R}^i g(\cP_k) = O_{-\infty}(\etak^{-i};\ZcupHspace{} \to \ZcapHspace{}).\]
By, e.g., \cite[Theorem 3.2]{Vo:84}, 
given a Schwartz function $f$, there exist two Schwartz functions $f_1$ and $f_2$ such that $f = f_1f_2$. Thus $f(\cP_k)= f_1(\cP_k) f_2(\cP_k)$ with $f_1,f_2 \in \cS(\R)$. Furthermore, by the Leibniz identity
	\[\ad_{X}^N (YZ) = \sum_{i = 0}^N \binom{N}{i} (\ad_{X}^i Y) (\ad_{X}^{N-i}Z).\]
	Thus,
\begin{align*}&\ad_{R}^N (f_1(\cP_k) f_2(\cP_k)) \\
&\qquad= f_1(\cP_k) (\ad_{R}^N f_2(\cP_k)) + (\ad_R^{N} f_1(\cP_k)) f_2(\cP_k) + \sum_{i = 1}^{N-1} \binom{N}{i} \ad_R^{i} f_1(\cP_k) \ad_{R}^{N-i} f_2(\cP_k).
\end{align*}
Bounding the first two terms on the right-hand side by  \eqref{eq:startInduct} and \eqref{eq:toupgrade}, and bounding the third term by the induction hypothesis, we obtain that
%Now, by the induction hypothesis, 
%	\[\ad_{R}^N (f_1(\cP_k) f_2(\cP_k)) = f_1(\cP_k) (\ad_{R}^N f_2(\cP_k)) + (\ad_R^{N} f_1(\cP_k)) f_2(\cP_k) + \sum_{i = 1}^{N-1} O_{-\infty}(\etak^{-i}) O_{-\infty}(\etak^{-N+i}),\]
%	and, by \eqref{eq:startInduct} and \eqref{eq:toupgrade}, 
	\[\ad_{R}^N (f_1(\cP_k) f_2(\cP_k)) = O_{-\infty}(1)O_{-2+N(m-1)}(\etak^{-N}) +  \sum_{i = 1}^{N-1} O_{-\infty}(k^{-i}) O_{-\infty}(\etak^{-N+i}),\]
	where all the operators are $\ZcupHspace{} \to \ZcapHspace{}$. Since $\ZcapHspace{n}\subset \ZcupHspace{n}$ for all $n$, 
$\ad_{R}^N (f_1(\cP_k) f_2(\cP_k)) = O_{-\infty}(\etak^{-N};\ZcupHspace{} \to \ZcapHspace{})$, and the proof is complete.
\end{proof}

