We now record a variant of the previous result.
\begin{proposition}
\label{prop:variant_adNRf(Pk)}
Let $N \in \mathbb{N}$, $f \in \mathcal{S}(\R)$ and let $R = O_m(1;\Dspace{} \to \Dspace{})$ be such that 
$$\ad_R^N \cP_k = O_{m - N + 2}(\eta^{-N};\Dspace{} \to \Dspace{}).$$
Then 
$$\ad_R^N f(\cP_k) = O_{-\infty}(\eta^{-N};\Dspace{}\to\Dspace{})$$
\end{proposition}
The proof is the same as that of Proposition \ref{prop:proofadNR1},  using a variant of Proposition \ref{prop:atoms} in the scale $(\Dspace{s})_{s\in \mathbb{R}}$, and using the mapping properties of $(\cP_k - z), (\cP_k - z)^{-1}$ and $f(\cP_k)$ in this scale (with the latter two mapping properties coming from Propositions \ref{prop:neverInBin} and \ref{prop:f(Pk)}).

\begin{proposition}
	\label{prop:proofadNR2}
	For all $N \in \mathbb{N}$ and $R \in \Lcut^m$, 
	\[
	\ad_R^{N} (P_k^\sharp)^{-1} = O_{-2+N(m-1)}(\etak^{-N};\ZcupHspace{} \to \ZcapHspace{}).
	\]
\end{proposition}
\begin{proof}
	This follows from Proposition \ref{prop:atoms} applied with $X = R$, $\Omega = \{1\}$ and $Y_1 = P_k^\sharp$. Indeed, for assumption (a), the required estimate is given by Proposition \ref{prop:ResPksharp}, while for assumption (b), 
	\[\ad_{R}^N P_k^{\sharp} = \ad_{R}^N  P_k + \ad_R^N \psi(\cP_k) = O_{2+N(m-1)}(\etak^{-N}) + O_{-\infty}(\etak^{-N}) \]
	by the definition of spatial cutoffs 
	(i.e., Definition \ref{def:spatialCutoffs}) and by Proposition \ref{prop:proofadNR1}.
\end{proof}

