\begin{proposition}
	\label{prop:proofadNf1}
	Given $f \in \mathcal{S}(\R)$, $m\in\mathbb{R}$, and $X \in \Lf^m$,
	\[\ad_{f(\cP_k)}^N X = O_{-\infty}(\etak^{-N};\Dspace{} \to \Dspace{})\]
	(i.e., the bound \eqref{eq:adNf1} holds).
\end{proposition}
\begin{proof}
Using the Helffer-Sjöstrand formula, commutators with $f(\cP_k)$ can be expressed in terms of commutators with $(\cP_k-z)^{-1}$: for all $f_j \in \mathcal{S}(\R)$, $j=1,\ldots,N$, all $X \in \Lf^m$, and for every integer $N \in \mathbb{N}$, 
\begin{equation}
	\label{eq:adfN}
	\begin{split}
		&\ad_{f_N(\cP_k)} \ad_{f_{N-1}(\cP_k)} \ldots \ad_{f_1(\cP_k)} X \\
		&\qquad= \int_{\C^N} w_1(z_1) \ldots w_N(z_N) (\ad_{(\cP_k - z_N)^{-1}} \ldots \ad_{(\cP_k - z_1)^{-1}} X)\,dm_{\C^N}(z_1,\ldots,z_N),
	\end{split}
\end{equation}
where $w_i$ is as in Proposition \ref{prop:HS} with $f = f_i$. 
Using the identities 
$\ad_{(\cP_k-z)^{-1}} X= -(\cP_k-z)^{-1}\ad_{\cP_k}X(\cP_k-z)^{-1}$, 
$\ad_X(YZ)=(\ad_X Y)Z+Y(\ad_XZ)$,  
and the fact that $\ad_{(\cP_k - z)^{-1}} (\cP_k - z')^{-1} = 0$, one obtains the formula
\begin{equation*}
%	\label{eq:adResCommut}
	\ad_{(\cP_k-z_N)^{-1}} \ldots \ad_{(\cP_k - z_1)^{-1}} X = (-1)^N \prod_{i = 1}^{N}(\cP_k - z_i)^{-1} (\ad_{\cP_k}^N X)\prod_{i = 1}^{N}(\cP_k - z_i)^{-1}.
\end{equation*}
Therefore, by the resolvent estimate in 
Proposition \ref{prop:neverInBin} and the commutator assumption for frequency cutoffs (in Definition \ref{def:freqOp}),
\begin{align*}
	\ad_{(\cP_k-z_N)^{-1}} \ldots \ad_{(\cP_k - z_1)^{-1}} X 
= \prod_{j=1}^N\langle z_j\rangle^{2}|\Im( z_j)|^{-2}O_{-3N+m}(\eta^{-N};\Dspace{}\to \Dspace{}).
\end{align*}
Using this in \eqref{eq:adfN} and recalling 
	the decay properties of the $w_j$ \eqref{eq:condw}, we obtain that, for any $f_1,\ldots,f_N \in \cS(\R)$, 
	\[\ad_{f_N(\cP_k)} \ldots \ad_{f_1(\cP_k)} X= O_{-3N+m}(\etak^{-N};\Dspace{} \to \Dspace{}).\]
	In particular, if $f_j=f$, then $\ad^N_{f(\cP_k)} X= O_{-3N+m}(\etak^{-N};\Dspace{} \to \Dspace{})$. 

	To upgrade the regularity index from $-3N+m$ to $-\infty$, we use again that, given a Schwartz $f$, there exist two Schwartz functions $f_1$ and $f_2$ such that $f = f_1f_2$. By the functional calculus, $f(\cP_k)= f_1(\cP_k) f_2(\cP_k)$.  Furthermore, $\ad_{WY}Z = (\ad_W Z) Y + W (\ad_YZ)$. Thus,
	\[\begin{split}
		\ad_{f(\cP_k)}^N X  = \ad_{f_1(\cP_k) f_2(\cP_k)} \ad_{f(\cP_k)}^{N-1} X& =\underbrace{(\ad_{f_{1}(\cP_k)} \ad_{f(\cP_k)}^{N-1} X)}_{O_{-3N}(\etak^{-N})}  \underbrace{f_{2}(\cP_k)}_{O_{-\infty}(1)} + \underbrace{f_{1}(\cP_k)}_{O_{-\infty}(1)} \underbrace{(\ad_{f_{2}(\cP_k)} \ad_{f(\cP_k)}^{N-1} X)}_{O_{-3N}(\etak^{-N})}  \\
		 & =O_{-\infty}(\etak^{-N};\Dspace{} \to \Dspace{})
	\end{split}\] 
	which completes the proof. 
\end{proof}


\section{Pseudolocality results applied to the Helmholtz problem}\label{sec:assumptions}


In this section, we specialise the results of the previous section to the Helmholtz PML operator, that is, to the case where $\mathcal{H}_k^n = H_k^n$, $a_k$ is defined by \eqref{e:def_ak} and $\cZ_k$ is defined by \eqref{e:defZk_concrete}. With these definitions fixed, we keep the rest of the notation from Section \ref{sec:pseudolocS} (indeed, once we check that Assumptions \ref{ass:cont}, \ref{ass:Gar}, \ref{ass:domComp}, \ref{ass:contPk} and \ref{ass:ell} hold, all other objects appearing in this section are then defined in terms of $\cH_k^n$, $\cZ_k$ and $a_k$).  Observe that $\cZ_k$ is a subspace of $H^1_k$ with Dirichlet conditions on either $\partial \Omega$ (Dirichlet setting) or just $\Gamma_{\tr}$ (Neumann setting), and for all $j \geq 0$, $\ZcupHspace{j} = H_k^j$ and the inclusion $H_k^{-j} \subset \ZcupHspace{-j}$ is continuous. In particular, if $R = O_{-\infty}(\eta^n;\ZcupHspace{}\to\ZcupHspace{})$, then 
$$\|Ru\|_{H_k^N} \leq C \eta^{n}\|u\|_{H_k^{-N}} \quad \tfa N \in \mathbb{N}.$$


In this particular setting, we give sufficient conditions for smooth cut-off functions $\chi \in C^\infty(\overline{\Omega})$ to fulfil the conditions of Definition \ref{def:spatialCutoffs} or Definition \ref{def:freqOp}. We also identify some boundary-compatible operators in the sense of Definition \ref{def:freqOp} that are used for the proof of Theorem \ref{t:theRealDeal}.

In the remainder of this paper, we adopt the following notation.
\begin{definition}\label{def:cheeky1}
 Given two cutoff functions $\varphi,\widetilde{\varphi},\psi \in C^\infty(\overline{\Omega})$ and a real number $d > 0$, we write
$$\begin{array}{rcl}
\varphi \perp_d \psi &\iff& \dist(\supp \varphi,\supp \psi) > d\\[0.5em]
\varphi \prec_d \widetilde{\varphi} &\iff& \varphi \perp_d (1 - \widetilde{\varphi}).
\end{array}$$
We abbreviate $\perp_0$ and $\prec_0$ by $\perp$ and $\prec$.
\end{definition}



