The main result of this section is the following.

\begin{theorem}
\label{t:pseudoLocGeneral}
Suppose that $\chi_1,\chi_2\in C^\infty(\overline{\Omega})$ with $\supp \chi_1\cap \supp \chi_2=\emptyset$. Then, for all $f\in \mc{S}(\R)$,
\begin{gather*}
\chi_1f(\cP_k)\chi_2=O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{}),\qquad
\chi_1 R_{k}^\sharp\chi_2=O_{-2}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{}).
\end{gather*}
\end{theorem}

This result is proved by using Theorem~\ref{thm:pseudolocSpace} and showing, first, that if $\chi \in C^\infty(\overline{\Omega})$ and $\partial_\nu \chi|_{\partial\Omega_-}=0$ then $\chi \in \Lcut$ (see Lemma \ref{l:spatialCut} below) and, second, that 
given $\chi_1,\chi_2\in C^\infty(\overline{\Omega})$, there exist 
$\widetilde\chi_j\in C^\infty(\overline{\Omega})$ with $\partial_\nu \widetilde\chi_j|_{\partial\Omega_-}=0$, $j=1,2,$ such that
$\chi_j\prec \widetilde\chi_j$, and $\widetilde\chi_1 \perp \widetilde\chi_2$ (see Lemma \ref{l:goodCut}).  


\begin{lemma}
\label{l:spatialCut}
Given $\{C_N\}_{N > 0} \subset \R_+$, there exist $\{C'_{N,n}\}_{N,n} \subset \R_+$ such that the following is true. For all $\varepsilon > 0$, if $\chi \in C^\infty(\overline{\Omega})$ satisfies $\partial_\nu \chi|_{\partial\Omega_-}=0$ and
\begin{equation*}
%\label{e:goodCutDerivatives}
\begin{gathered}
\max_{|\alpha|\leq N} \varepsilon^{|\alpha|}|\partial^\alpha \chi|\leq C_N\quad \tfa N \in \mathbb{N},
\end{gathered}
\end{equation*}
then
\begin{equation}
	\label{e:adNRQ_goodCut}
	\begin{gathered}
		\|\ad_{\chi}^N Q\|_{\ZcapHspace{n} \to \ZcupHspace{n+2-N}} \leq C'_{N,n} (\varepsilon k)^{-N},
	\end{gathered}
\end{equation}
where $Q$ is any one of the operators $P_k$, $P_k^*$ or $\cP_k$. In particular $\chi \in \Lcut.$
\end{lemma}
\begin{proof}
We start by considering $\ad_{\chi}P_k$ acting in $\Zspace{1}$. Indeed, suppose that $u,v\in \Zspace{1}$. Then, $\chi u,\bar{\chi} v\in \Zspace{1}$ and hence
\begin{align}\nonumber
\langle \ad_\chi P_k u,v\rangle &=a_k(u,\bar{\chi} v)-a_k(\chi u,v)\\ \nonumber
&= k^{-2}\Big(\langle A_\theta \nabla u,\nabla (\bar{\chi} v)\rangle -\langle A_\theta (\nabla \chi u),\nabla v\rangle\Big)
+ k^{-2}\big\langle \chi b_\theta\cdot \nabla u  - b_\theta \cdot\nabla(\chi u), v \big\rangle
\\ \nonumber
&= k^{-2}\Big(\langle A_\theta \nabla u,v\nabla \bar{\chi} \rangle -\langle u A_\theta \nabla \chi ,\nabla v\rangle\Big)
-k^{-2} \langle (b_\theta \cdot \nabla \chi)u, v \rangle
\\ \label{e:helpTheFuture1}
&= k^{-2}\big\langle (A_\theta \nabla u) \cdot \nabla \chi+\nabla\cdot(uA_\theta \nabla \chi),v \big\rangle -k^{-2} \langle (b_\theta \cdot \nabla \chi)u, v \rangle,
\end{align}
where in the last line we use that  $\partial_{\nu}\chi|_{\partial\Omega_-}=0$ and $u|_{\Gamma_{\tr}}=0$. In particular, for $n\geq 1$, $\|\ad_\chi P_k u\|_{\Hspace{n-1}}\leq C(\varepsilon k)^{-1}\|u\|_{\Zspace{n}}$.
Next, since
\beqs
\langle \ad_\chi^2P_k u,v\rangle =\langle \ad_\chi P_k u,\overline{\chi} v\rangle -\langle \ad_\chi P_k (\chi u),v\rangle,
\eeqs
a short calculation using \eqref{e:helpTheFuture1} implies that, 
for $u,v\in \Zspace{1}$, 
\beq\label{e:helpTheFuture2}
\langle \ad_\chi^2P_k u,v\rangle = -k^{-2}\big\langle 2u (A_\theta \nabla \chi)\cdot \nabla \chi,v\big\rangle.
\eeq
Thus, for $n\geq 0$, $\|\ad_\chi^2P_k u\|_{\Hspace{n}}\leq C(\varepsilon k)^{-2}\|u\|_{\Zspace{n}}$.  
Since there are no derivatives of $u$ on the right-hand side of \eqref{e:helpTheFuture2}, a similar calculation shows that 
$u\in \Zspace{1}$, $(\ad_\chi^NP_k)u=0$ for $N\geq 3$. Thus 
\begin{equation}
\label{e:highn}
\|\ad_\chi^NP_k\|_{\Zspace{n}\to \Hspace{n-2+N}}
=\|\ad_\chi^NP_k\|_{\ZcapHspace{n}\to \ZcupHspace{n-2+N}}
\leq C(\varepsilon k)^{-N} \quad\tfor n\geq 0,
\end{equation}
and, by identical arguments,
\begin{equation}
\label{e:highn2}
\|\ad_\chi^NP_k^*\|_{\Zspace{n}\to \Hspace{n-2+N}}
=\|\ad_\chi^NP_k^*\|_{\ZcapHspace{n}\to \ZcupHspace{n-2+N}}
\leq C(\varepsilon k)^{-N}\quad\tfor n\geq 0.
\end{equation}
%The bounds for $n\in \mathbb{Z}$ then follow from
%\eqref{e:dualNewSpaces} and the fact that $(\ad_A^N B)^*= (-1)^N \ad_{A^*}^N B^*$ (which one can prove by induction).
Now, for $\ell \geq 0$, $u\in \Hspace{-\ell}$ and $v\in \Zspace{\ell+2}$, by 
the fact that $(\ad_A^N B)^*= (-1)^N \ad_{A^*}^N B^*$ (which one can prove by induction),
\begin{align*}
\big|\big\langle (\ad_\chi^N P_k)u,v\big\rangle\big|=\big|\big\langle u,(-1)^N(\ad_{\bar{\chi}}^NP_k^*)v\big\rangle \big|
&\leq \|u\|_{\Hspace{-\ell}}\| (\ad_{\bar{\chi}}^NP_k^*)v\|_{\Hspace{\ell}}
%\\
%&\leq Ck^{-N}\|u\|_{\Hspace{-\ell}}\|v\|_{\Zspace{\ell+2-N}}.
\end{align*}
If $N\geq 3$, then the right-hand side of the last inequality is zero. Otherwise, \eqref{e:highn2} with $n=\ell+2-N \geq 0$ implies that 
\beqs
\big|\big\langle (\ad_\chi^N P_k)u,v\big\rangle\big|\leq C(\varepsilon k)^{-N}\|u\|_{\Hspace{-\ell}}\|v\|_{\Zspace{\ell+2-N}}.
\eeqs
Since $\Zspace{\ell+2}$ is dense in $\Zspace{\ell+2-N}$, the previous inequality and 
%Hence, using that $\overline{\Zspace{\ell+2}}^{\Hspace{\ell+2-N}}\supset\Zspace{\ell+2-N}$, and 
similar arguments for $P_k^*$ imply that
\begin{equation}
\label{e:lowl}
\|\ad_{\chi}^NP^*_k\|_{\Hspace{-\ell}\to \Zspace{-\ell-2+N}}+\|\ad_{\chi}^NP_k\|_{\Hspace{-\ell}\to \Zspace{-\ell-2+N}}\leq C(\varepsilon k)^{-N},\qquad \ell\geq 0.
\end{equation}
The combination of \eqref{e:highn}, \eqref{e:highn2}, and~\eqref{e:lowl} are then \eqref{e:adNRQ_goodCut}.
\end{proof}

