\begin{lemma}[Partition of unity satisfying Neumann boundary conditions]
\label{l:goodPartition}
Let $\Omega_i\subset \Omega$, $i=1,\dots, N$ be open with $\Omega\subset \cup_i\Omega_i$. Then there exist $\varphi_i\in C^\infty(\overline{\Omega})$ satisfying
$$
\supp \varphi_i\subset \Omega_i\cup \partial\Omega,\quad \partial_\nu \varphi_i=0 \,\,\ton\partial\Omega,\quad \tand\quad\sum_{i=1}^N \varphi_i\equiv 1.
$$
\end{lemma}
\begin{proof}
Let $U_i\Subset \Omega_i$ be open sets such that $\Omega\subset \cup_i U_i$. Then, for $\e>0$ small enough, and $y\in \overline{U}_i$, $B(y,2\e)\subset \Omega_i$. In addition, since $\overline{U}_i$ is compact, there are $\{y_{ij}\}_{j=1}^{N_i}\subset \overline{U}_i$ such that $ U_i\subset \cup_{j=1}^{N_i} B(y_{ij},\e)$. 

 By Lemma~\ref{l:big} (applied with $\Omega_1= B(y_{ij},\e)$ and $\Omega_2= \Omega\setminus \overline{\Omega_i}$), for $\e>0$ small enough, there are $\widetilde{\varphi}_{ij}\in C^\infty(\overline{\Omega};[0,1])$ such that $\supp(1-\widetilde{\varphi}_{ij})\cap B(y_{ij},\e)=\emptyset$, $\supp \widetilde{\varphi}_{ij}\subset \Omega_i \cup \partial\Omega$,
 and $\partial_\nu \widetilde\varphi_{ij}=0$ on $\partial\Omega$.   
Noting that $\sum_{i=1}^N\sum_{j=1}^{N_i}\widetilde{\varphi}_{ij}\geq 1$, we define
$$
\varphi_i:=\frac{\sum_{j=1}^{N_i}\widetilde{\varphi}_{ij}}{\sum_{i=1}^N\sum_{j=1}^{N_i}\widetilde{\varphi}_{ij}},
$$
%It is then easy to see that $\varphi_i$ 
which has the required properties.
\end{proof}

