We now remove the assumption from Lemma \ref{l:big} that $\Omega_1$ is sufficiently small.

\begin{lemma}
\label{l:goodCut}
There exists $\e_0>0$ such that for all $N>0$, there exists $C_N>0$ such that for all $0<\e<\e_0$ and $\Omega_1,\Omega_2\subset \Omega$ and $d(\Omega_1,\Omega_2)>\e$, there exists $\chi \in C^\infty(\overline{\Omega})$ satisfying 
\begin{equation}
\label{e:cutEstimates2}
\begin{gathered}
\Omega_1\cap \supp (1-\chi)=\emptyset,\qquad  \supp \chi\cap \Omega_2=\emptyset, \\
|\partial^\alpha \chi|\leq C_N\e^{-|\alpha|},\qquad |\alpha|\leq N,\qquad \partial_\nu \chi|_{\partial\Omega}=0, 
\end{gathered}
\end{equation}
\end{lemma}
\begin{proof}
Let $\e_0$ be as in Lemma~\ref{l:big}. Since $\overline{\Omega}$ is compact, there exist $\{x_i\}_{i=1}^M$ such that $\overline{\Omega}\subset \cup_{i=1}^M B(x_i,\e_0)$. Then, by Lemma~\ref{l:goodPartition}, there exist $\{\varphi_i\}_{i=1}^M$ a partition of unity subordinate to $\{B(x_i,\e_0)\}_{i=1}^M$ satisfying $\partial_\nu \varphi_i=0$ on $\partial\Omega$. Then, let $\Omega_{1,i}:= \Omega_1\cap B(x_i,\epsilon_0)$. 
By Lemma~\ref{l:big}, there exists $\chi_i$ such that the conditions in \eqref{e:cutEstimates2} hold with $\Omega_1$ replaced by $\Omega_{1,i}$. Define $\chi:=\sum_{i=1}^M \chi_i\varphi_i$. The derivative estimates in~\eqref{e:cutEstimates2} then follow from the product rule and the fact that the derivatives of $\varphi_i$ are independent of $\epsilon$ (but depend on $\epsilon_0$).
The condition that $\partial_\nu \chi|_{\partial\Omega}=0$ follows since both $\partial_\nu \chi_i=0$ and $\partial_{\nu}\varphi_i=0$.
%  To check the rest of the conditions observe that, since $\partial_\nu \chi_i=0$, 
%$$
%\partial_\nu \chi=\sum_i \chi_i \partial_{\nu}\varphi_i=0.
%$$ 
Next, since $\supp\chi_i \cap \Omega_2=\emptyset$, $\supp \chi\cap \Omega_2 \subset \cup_i\supp (\chi_i\varphi_i)\cap \Omega_2=\emptyset$.
Finally, since $\chi_i\equiv 1$ on $\Omega_1\cap B(x_i,\epsilon_0)$ and $\supp \varphi_i \subset B(x_i,\epsilon_0)$, $(1-\chi_i)\varphi_i=0$ on $\Omega_1$, and thus 
$$
\supp (1-\chi)\cap \Omega_1 =\supp \Big(\sum_{i=1}^N (1-\chi_i)\varphi_i\Big)\cap \Omega_1=
%\cup_i \supp (1-\chi_i)\cap B(x_i,\epsilon_0)\cap \Omega_1=
\emptyset.
$$
\end{proof}

\begin{proof}[Proof of Theorem \ref{t:pseudoLocGeneral}]
Since $\supp \chi_1\cap \supp \chi_2=\emptyset$, there exist $\Omega_i$ neighbourhoods of $\supp \chi_i$ with $d(\Omega_1,\Omega_2)>0$. Therefore, by Lemma~\ref{l:goodCut} %(applied with $\Omega_j=U_j$) 
there are $\widetilde{\chi}_i$ with $\supp \chi_i\cap \supp (1-\widetilde{\chi}_i)=\emptyset$, $\supp \chi_i\cap \supp\widetilde{\chi}_j=\emptyset$, $i\neq j$, and $\partial_\nu \widetilde{\chi}_i=0$. Hence by Lemma~\ref{l:spatialCut}, $\widetilde{\chi}_i\in \Lcut$ and using Theorem~\ref{thm:pseudolocSpace}, we have
$$
\chi_1f(\cP_k)\chi_2=\chi_1\widetilde{\chi}_1f(\cP_k)\widetilde{\chi}_2\chi_2=\chi_1O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcapHspace{})\chi_2=O_{-\infty}(k^{-\infty}; \ZcupHspace{}\to \ZcupHspace{}),
$$
since $\chi_j = O_0(1;\ZcupHspace{}\to \ZcupHspace{})$. 
The proof for $R_{k}^\sharp$ is identical.
\end{proof}


