\begin{proof}[Proof of Lemma \ref{l:commuteP}]
We prove \eqref{eq:HRevil1}; the proof of \eqref{eq:HRevil2} is very similar. We write 
\beqs
\ad_{\varphi \cP_k\varphi}^N P_k= \psi_0 \ad_{\varphi \cP_k\varphi}^N P_k+(1-\psi_0) \ad_{\varphi \cP_k\varphi}^N P_k, 
\eeqs
where $\psi_0$ is supported in a region close to $\partial\Omega$ where $\varphi$ is constant.
More precisely, let $\psi_i\in C^\infty(\overline{\Omega})$, $i=-1,0,1$ with $\supp (1-\psi_i)\cap \partial\Omega_-=\emptyset$, $\supp\psi_i\cap \supp(c-\varphi)=\emptyset$, $\supp (1-\psi_i)\cap \supp \psi_{i-1}=\emptyset$, and $\psi_2 P_k=\psi_2 P_k^*$
 (note that such functions exist since $\supp \nabla \varphi\cap \partial\Omega_-=\emptyset$).

%We first consider $\psi_0\ad_{\varphi \cP_k\varphi}^N P_k.$ 
By locality of $\cP_k$ and $P_k$ and the fact that $\cP_k=P_k$ on $\supp \psi_2\supset \supp\psi_0$,
$$
\psi_0 \ad_{\varphi \cP_k\varphi}^N P_k =\psi_0\ad_{c P_kc}^N P_k=0.
%\psi_0\ad_{\varphi \cP_k\varphi}^NP_k=\psi_0c^{2N}\ad_{ \cP_k}^N P_k=0.
$$
Now, let $\tilde{\varphi}\in C^\infty(\overline{\Omega})$ with $\supp \tilde{\varphi}\cap \Gamma_{\tr}=\emptyset$ and $\supp \varphi\cap \supp (1-\tilde{\varphi})=\emptyset$. Then
$$
(1-\psi_0)\ad^N_{\varphi\cP_k\varphi}P_k=(1-\psi_0)\ad^N_{\varphi(1-\psi_{-1})\cP_k\varphi(1-\psi_{-1})}\big[(1-\psi_{-1})\tilde{\varphi}P_k(1-\psi_{-1})\tilde{\varphi}\big].
$$
Since $\supp \tilde{\varphi}\cap \supp (1-\psi_{-1})\cap \partial\Omega=\emptyset$, 
integration by parts (with all the boundary terms vanishing) shows that $\varphi(1-\psi_{-1})\cP_k\varphi(1-\psi_{-1})$ and $(1-\psi_{-1})\tilde{\varphi}P_k(1-\psi_{-1})\tilde{\varphi}$ coincide with differential operators on $C^\infty(\overline{\Omega})$. The result 
$$
\|\ad^N_{\varphi\cP_k\varphi}P_k\|_{\Dspace{n}\to \Dspace{n-N-2}}\leq Ck^{-N} 
$$
then follows by direct differentiation (using the product rule) and then density of $C^\infty(\overline{\Omega})$ in $\Dspace{n}$.
The proof of the analogous bound for $P_k^*$ is identical.
\end{proof}

