\begin{proof}[Proof of Lemma \ref{lem:huge_whiteboard1}]
We prove the statement for $P_k^\sharp$. The proof for $(P_k^{\sharp})^*$ is identical.
Let $\tilde{\varphi}\in C^\infty(\overline{\Omega})$ with $\supp \nabla\tilde{\varphi}\cap \partial\Omega=\emptyset$ and $\supp (1-\tilde{\varphi})\cap \supp \varphi=\emptyset$. Then, by locality of $\cP_k$,
\beq\label{e:mrcroc2}
\ad_{\cP_k}^N\varphi(P_k^\sharp)^{-1}\varphi= \ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N\varphi(P_k^\sharp)^{-1}\varphi,
\eeq
By Lemma \ref{l:doneWithAds}, 
$\ad_{\cP_k}^N\varphi =O_{N}(k^{-N};\Dspace{}\to\Dspace{})$,
so that, by repeated use of the identity $\ad_{AB} C = A(\ad_B C) + (\ad_A C)B$,
\beq\label{e:mrcroc1}
 \ad_{\tilde\varphi\cP_k\tilde\varphi}^N\varphi =O_{N}(k^{-N};\Dspace{}\to\Dspace{}).
%\qquad \ad_{\cP_k}\varphi= \tilde{\varphi}( \ad_{\cP_k}\varphi)\tilde{\varphi}
\eeq
Therefore, by the combination of \eqref{e:mrcroc1}, \eqref{e:mrcroc2}, and repeated use of the identity $\ad_{A} BC = (\ad_A B)C + B(\ad_A C)$, 
it is enough to show that 
\beq\label{e:bitLost1}
\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N(P_k^\sharp)^{-1}=O_{N-2}(k^{-N};\Dspace{}\to\Dspace{}).
\eeq
%$$
%\varphi (\ad_{\cP_k}^N(P_k^\sharp)^{-1})\varphi=O_{N-2}(k^{-N}).
%$$
