%\varphi (\ad_{\cP_k}^N(P_k^\sharp)^{-1})\varphi= \varphi (\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N(P_k^\sharp)^{-1})\varphi
%$$
To prove \eqref{e:bitLost1} we use Proposition~\ref{prop:atoms}. 
For this, observe that
$$
\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^NP_k^\sharp= \ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N(P_k+\psi(\cP_k)).
$$
By Lemma~\ref{l:commuteP},
$$
\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^NP_k=O_{2+N}(k^{-N};\Dspace{}\to \Dspace{}) \quad\tand\quad \ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^NP_k^*=O_{2+N}(k^{-N};\Dspace{}\to \Dspace{}).
$$
By induction, $\ad_A^N(B+C)= \ad_A^N B + \ad_A^N C$, and so
\beq\label{eq:HWB1}
 \ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N\cP_k=O_{2+N}(k^{-N};\Dspace{}\to \Dspace{}).
\eeq
Therefore, by Proposition \ref{prop:variant_adNRf(Pk)},
\begin{equation*}
\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N\psi(\cP_k)=O_{2+N}(k^{-N};\Dspace{}\to \Dspace{}).
