$$
\ad_{\tilde{\varphi}\cP_k\tilde{\varphi}}^N P^\sharp_k=O_{2+N}(k^{-N};\Dspace{}\to \Dspace{})
$$
and \eqref{e:bitLost1} -- and hence also the result -- then follows from Proposition~\ref{prop:atoms}.
\end{proof}


\section{Pseudolocality of the elliptic projection}
\label{sec:pseudoLocPi}

In Sections \ref{sec:boundsCsol}, \ref{sec:pseudolocS}, and \ref{sec:assumptions}, we studied pseudolocality 
properties at the continuous level. Another key tool required for the proof of Theorem \ref{t:theRealDeal} is of a discrete nature, namely, we need to establish the spatial pseudolocality of the Galerkin projection $\Pi_k^\sharp$ associated to (the adjoint of) the sesquilinear form $a_k^\sharp$ defined in Definition \ref{e:defPksharp}, see Theorem \ref{t:pseudoLocalPi} below. 

We keep the notation of Section \ref{sec:assumptions}. The operator $\Pi_k^\sharp$ is defined as follows.
\begin{definition}[Elliptic projection]
	\label{def:ellipticProjection}
	Given $k > 0$ and a linear subspace $V_k \subset \cZ_k$, the {\em elliptic projection} onto $V_k$ is the linear operator $\Pi_k^\sharp : \cZ_k \to V_k$ defined by
	\[a_k^\sharp(v,\Pi_k^\sharp u)  = a_k^\sharp(v,u) \qquad \tfa v \in V_k,\]
	where we recall that $\cZ_k$ is defined by \eqref{e:defZk_concrete}, $a_k^\sharp(u,v) = a_k(u,v) + (S_k u,v)_{\cH}$ and $S_k$ is defined by \eqref{e:def_Sk}. 
\end{definition}
The operator $\Pi_k^\sharp$ is well-defined for all $k > 0$ by the Lax-Milgram theorem, since $a_k^\sharp$ is coercive (by Proposition \ref{prop:ResPksharp}). 


\begin{theorem}[Pseudolocality of $\Id - \Pi_k^\sharp$]
	\label{t:pseudoLocalPi}
Let $(V_k)_{k > 0}$ be a well-behaved finite-element of order $p$ in the sense of Definition \ref{def:fem}, let $k_0>0$ and let $\mathfrak{c}>0$. There exists $h_0>0$ such that for all $N>0$, $\chi,\psi \in C^\infty(\overline{\Omega})$ satisfying $\chi \perp_{\mathfrak{c}} \psi,$ there exists $C>0$ such that for all $k\geq k_0$, $h\leq h_0$,  and $u\in\cZ_k$
	%	there exists $\mathfrak{c} > 0$ such that for every real number $k_0 > 0$, any integer $N > 0$ and any $\chi$, $\psi \in C^\infty(\overline{\Omega})$ satisfying
%	$$\dist(\supp \chi,\supp \psi) \geq \mathfrak{c} k_0^{-1} ,$$  
%
% 	there exists $\mathfrak{C}>0$ such that for all $k \geq k_0$ and all $u \in \cZ_k$
	\[
	\|\chi (\Id - \Pi_k^\sharp) \psi u\|_{H^1_k} \leq C k^{-N} \|(\Id - \Pi_k^\sharp) \psi u\|_{H_k^{-p}},
	\]
where $\Pi_k^\sharp$ is the elliptic projection onto $V_k$.
\end{theorem}

\begin{remark}
Through the constants $\mathfrak{c}$ and $h_0$, the assumptions of Theorem \ref{t:pseudoLocalPi} require a sufficient number of ``layers'' of elements separating the supports of $\chi$ and $\psi$. 
\end{remark}

Theorem~\ref{t:pseudoLocalPi} is an immediate consequence of the following two lemmas.

\begin{lemma}
	\label{l:iGainKBigRemainder}
Let $(V_k)_{k > 0}$ be a well-behaved finite-element of order $p$ in the sense of Definition \ref{def:fem}, and let $\mathfrak{c}>0$. Then, there exists $h_0>0$ such that the following holds. For any $k_0 > 0$, $N > 0$, and any $\chi_-,\chi_+,\psi \in C^\infty(\overline{\Omega})$ satisfying
	$$\chi_- \prec_\mathfrak{c} \chi_+ \quad\tand\quad\chi_+ \perp \psi,$$
	there exists $C > 0$ such that, for all $k \geq k_0$, $h\leq h_0$, and $u \in \cZ_k$,
	\[\|\chi_-(\Id -\Pi_k^\sharp) \psi u\|_{H^1_k} \leq Ck^{-N}\Big( \|\chi_+(\Id - \Pi_k^\sharp)\psi u\|_{L^2} + \|(\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}\Big).\] 
\end{lemma}
\ble
\label{l:iAmSoSmooth}
Let $(V_k)_{k > 0}$ be a well-behaved finite-element of order $p$ in the sense of Definition \ref{def:fem}, let $k_0>0$ and $\mathfrak{c}>0$. Then, there exists $h_0>0$ such that for all $N > 0$ and every $\chi$, $\psi \in C^\infty(\overline{\Omega})$ satisfying $\chi \perp_{\mathfrak{c}} \psi$, there exists $C > 0$ such that, for all $k \geq k_0$, $h\leq h_0$, and $u \in \cZ_k$,
\begin{equation}
	\label{e:iAmSoSmooth}\|\chi (\Id - \Pi_k^\sharp) \psi u\|_{L^2} \leq C\|(\Id - \Pi_k^\sharp) \psi u\|_{H_k^{-p}}.
\end{equation}
\ele

If $S_k$ is (formally) set to zero, then Lemmas \ref{l:iGainKBigRemainder} and \ref{l:iAmSoSmooth} are analogous to \cite[Lemmas 5.1 and 5.5]{AvGaSp:24}, respectively.

\

\begin{proof}[Proof of Lemma \ref{l:iGainKBigRemainder}]
Let $\mathfrak{c} > 0$ be given and let $h_0 >0$ be a sufficiently small constant depending only on $\mathfrak{c}$. Fix $k_0 > 0$, $N > 0$ and $\chi_-$, $\chi_+$ and $\psi$ as in the statement. 
In what follows, we denote by $C$ a generic constant depending only on the previous quantities. 

We first claim that, without loss of generality, we can assume that $\partial_\nu \chi_-=0$ and thus
\beq\label{e:reallyGoodSandwich1}
\ad_{\chi_-}P_k=O_1(k^{-1};\ZcapHspace{}\to\ZcupHspace{})
\eeq
by Lemma \ref{l:spatialCut} and Definition \ref{def:spatialCutoffs} and 
\beq\label{e:reallyGoodBaguette1}
	\ad_{\chi_-}S_k = O_{-\infty}(k^{-1}; \ZcupHspace{} \to \ZcapHspace{})
\eeq
by Proposition \ref{prop:proofadNR1}.
 Indeed, if $\partial_\nu \chi_-\neq 0$ we apply 
Lemma \ref{l:goodCut} with $\Omega_1= \supp \chi_-$ and $\Omega_2$ equal to $\supp(1-\chi_+)$ enlarged by distance $\mathfrak{c}/2$. We then relabel the resulting cut-off function $\chi_-$ and replace $\mathfrak{c}$ by $\mathfrak{c}/2$.

Let $k \geq k_0$, $u \in \cZ_k$ and suppose that $h \leq h_0$. It is sufficient to prove that
\begin{equation}
\label{e:localQOToShow}
\|\chi_-\Pi^\sharp_k \psi u\|_{H^{1}_k}\leq Ck^{-1/2}\|\chi_+\Pi_k^\sharp \psi u\|_{L^2} + Ck^{-N}\|(\Id - \Pi_k^\sharp )\psi u\|_{H_k^{-N}}
%C\sum_{j = 0}^{\infty} (2^jkd)^{-N}\|(1-\chi_+)\Pi^\sharp_k \psi u\|^2_{\Zspace{-N}(U_j)},
\end{equation}
since 
%the result then follows 
by iterating \eqref{e:localQOToShow} $2N$ times, (changing the cutoffs $\chi_-$ and $\chi_+$), one arrives at
\[\begin{split}
	\|\chi_-\Pi^\sharp_k \psi u\|_{H^1_k}&\leq Ck^{-N}\|\chi_+\Pi_k^\sharp \psi u\|_{L^2} + Ck^{-N}\|(\Id - \Pi_k^\sharp )\psi u\|_{H_k^{-N}}\\
	&= Ck^{-N}\|\chi_+(\Id - \Pi_k^\sharp) \psi u\|_{L^2} + Ck^{-N}\|(\Id - \Pi_k^\sharp )\psi u\|_{H_k^{-N}}
\end{split}\]
using the fact that $\chi_+ \psi = 0$. 

Let $\chi_0\in C^\infty(\overline{\Omega})$ be such that 
$\chi_- \prec_{\mathfrak{c}/4} \chi_0 \prec_{\mathfrak{c/4}} \chi_+$.
By the coercivity of $P_k^\sharp$ (cf. \eqref{eq:CoerciveAsharp}), the definition of $\Pi_k^\sharp$ (Definition \ref{def:ellipticProjection}), locality of $P_k$ and the fact that $\chi_- \psi = \chi_0 \psi = 0$, 
\begin{align*}
%\label{e:localQO3}
%\begin{aligned}
&\|\chi_-\Pi^\sharp_k \psi u\|_{H^1_k}^2 \leq C\abs{\big\langle  P_k^\sharp \chi_-\Pi^\sharp_k \psi u,\chi_- \Pi^\sharp_k \psi u\big\rangle}\\
&\quad = C\abs{\big\langle  P_k^\sharp \chi_-\Pi^\sharp_k \psi u,\chi_- {(\Id - \Pi^\sharp_k)}\psi u\big\rangle}\\
&\quad = C \Big(\abs{\langle P_k^\sharp \chi_-^2\Pi_k^\sharp \psi u, ({\Id - \Pi_k^\sharp}) \psi u\rangle} + \langle [P_k^\sharp,\chi_-] \chi_- \Pi_k^\sharp \psi u,{(\Id - \Pi_k^\sharp)} \psi u \rangle \Big)\\
&\quad = C \Big(\abs{\langle P_k^\sharp (\chi_-^2\Pi_k^\sharp \psi u - w_h),{(\Id - \Pi_k^\sharp)}\psi u\rangle} + \abs{\langle [P_k + S_k,\chi_-] \chi_- \Pi_k^\sharp\psi u ,{(\Id - \Pi_k^\sharp)} \psi u\rangle} \Big)\\
&\quad = C \big(\big|\big\langle P_k (\chi_-^2\Pi_k^\sharp \psi u - w_h),{(\Id - \Pi_k^\sharp)}\psi u\rangle\big|+ \big|\big\langle [P_k,\chi_-] \chi_- \Pi_k^\sharp\psi u ,\chi_0{(\Id - \Pi_k^\sharp)} \psi u\big\rangle\big|\big) + \Rrr,
\end{align*}
for all $w_h \in V_k$, where 
\begin{equation}
	\label{eq:nonLocalRemainder}
	\Rrr := \big|\big\langle S_k (\chi_-^2 \Pi_k^\sharp \psi u - w_h),(\Id - \Pi_k^\sharp) \psi u\big\rangle\big| + \big|\big \langle [S_k,\chi_-]\chi_- \Pi_k^\sharp \psi u,(\Id - \Pi_k^\sharp) \psi u \big\rangle\big|
\end{equation}
is the ``non-local" part. 
By \eqref{e:reallyGoodSandwich1} combined with the fact that $\chi_0 \psi = 0$,
\begin{align}\nonumber
\|\chi_-\Pi_k^\sharp \psi u\|_{H^1_k}^2&\leq 
C\big|\langle P_k (\chi_-^2\Pi^\sharp_k \psi u-w_h) ,{(\Id-\Pi_k^\sharp)}\psi u\rangle\big|
+Ck^{-1}\|\chi_-\Pi^\sharp_k \psi u\|_{H^1_k}\|\chi_0\Pi^\sharp_k \psi u\|_{L^2} + r
\label{eq:lunch1}
\end{align}
which implies 
\begin{equation}
	\label{eq:aux1}
	\|\chi_-\Pi_k^\sharp \psi u\|_{H^1_k}^2 \leq C\big|\langle P_k^\sharp (\chi_-^2\Pi^\sharp_k \psi u-w_h) ,{(\Id - \Pi^\sharp_k)} \psi u\rangle\big| +C k^{-2} \|\chi_0 \Pi_k^\sharp \psi u\|_{L^2}^2 + r.
\end{equation}%
Let $U_0$ be a neighbourhood of $\supp \chi_-$, and $U_1$ a set contained in $\{\chi_0 \equiv 1\}$. Since $\chi_- \prec_{\mathfrak{c}/4} \chi_0 \prec_{\mathfrak{c/4}} \chi_+$, we can arrange that 
\[d:=\partial_<(U_0,U_1) \geq \mathfrak{c}/8.\]
Hence, taking $h_0 < \frac{\mathfrak{c}}{8\kappa}$, where $\kappa$ is as in Assumption \ref{ass:sap}, we ensure that $d \geq \kappa h_0$. Thus, we can find a super-approximation $w_h$ to $\chi_-^2\Pi^\sharp_k \psi u$ with $\supp w_h \subset U_1$.
Now, for all $\epsilon<1$, 
\begin{align}\nonumber
&\big|\big\langle P_k(\chi_-^2\Pi^\sharp_k \psi u -w_h),{(\Id - \Pi_k^\sharp)} \psi u\big\rangle\big|
= { \big|\big\langle P_k(\chi_-^2\Pi^\sharp_k \psi u -w_h),\Pi_k^\sharp \psi u\big\rangle\big|} \qquad \textup{(by locality of $P_k$)}\\\nonumber
&\hspace{2cm}\leq \sum_{K\in\mc{T}_k: K\cap \supp \chi_0 \neq\emptyset}\| \chi_-^2\Pi^\sharp_k \psi u -w_h\|_{H^{1}_k(K)}\|\Pi_k^\sharp\psi u\|_{H^{1}_k(K)}\quad \textup{(by the definition of $a_k(\cdot,\cdot)$)}\\ \nonumber
&\hspace{2cm}\leq  \sum_{K\in\mc{T}_k: K\cap \supp \chi_0 \neq\emptyset}\|\Pi^\sharp_k\psi u\|_{H^{1}_k(K)}\frac{h_K}{d}\Big(\|\Pi^\sharp_k \psi u\|_{L^2(K)}+\|\chi_-\Pi^\sharp_k \psi u\|_{H^{1}_k(K)}\Big)\\ \nonumber
& \hspace{6cm}\qquad \textup{(by the super-approximation property, Assumption \ref{ass:sap})}\\ \nonumber
&\hspace{2cm}\leq  C\sum_{K\in\mc{T}: K\cap \supp \chi_0 \neq\emptyset}\|\Pi^\sharp_k\psi u\|_{L^2(K)}\frac{1}{kd}\Big(\|\Pi^\sharp_k \psi u\|_{L^2(K)}+\|\chi_-\Pi^\sharp_k \psi u\|_{H^1_k(K)}\Big) 
\\ \nonumber
& \hspace{7cm}\qquad \textup{(by the inverse inequality, Assumption \ref{ass:ii})}\\\nonumber
& \hspace{2cm}\leq  C \sum_{K\in \cT_k:K \cap \supp(\chi_0) \neq \emptyset} \frac{(1 + \epsilon^{-1})}{(kd)^2}\|\Pi^\sharp_k\psi u\|_{L^2(K)}^2 + \epsilon \|\chi_- \Pi_k^\sharp \psi u\|_{H^1_k(K)}^2\\ 
%&\hspace{2cm}\leq  C\|\chi_+\Pi^\sharp_k\psi u\|_{\mathcal{H}}\frac{1}{kd}\Big(\|\chi_+\Pi^\sharp_k \psi u\|_{\mathcal{H}}+\|\chi_-\Pi^\sharp_k \psi u\|_{\Zspace{1}}\Big)\qquad \textup{(Assumption \ref{ass:bn})}\\
&\hspace{2cm}\leq  \frac{C(1+\e^{-1})}{(kd)^{{2}}}\|\chi_+\Pi^\sharp_k \psi u\|_{L^2(\Omega)}^2+  \e\|\chi_-\Pi^\sharp_k\psi u\|^2_{\cZ_k}.
\label{e:localQO4}
\end{align}
Inputting \eqref{e:localQO4} into \eqref{eq:aux1} and recalling that $d \geq \mathfrak{c} /8$ and $k\geq k_0$, we find that
\begin{equation}
	\label{eq:PplShoutingTrain}
	\|\chi_- \Pi_k^\sharp \psi u\|^2_{\Zspace{}} \leq C k^{-2} \|\chi_+ \Pi_k^\sharp \psi u\|_{L^2(\Omega)}^2 + \Rrr,
\end{equation}
To estimate $\Rrr$, since 
$\textup{dist}(\supp (w_h,\supp (1 - \chi_0))) > 0$, 
pseudolocality of $S_k$ (Theorem \ref{t:pseudoLocGeneral}) implies that 
\begin{align*}
\big|\langle S_k(\chi_-^2\Pi_k^\sharp \psi u-w_h),(1-\chi_0){(\Id - \Pi_k^\sharp)} \psi u\rangle\big| \leq Ck^{-N}
\big\| \chi_-^2\Pi^\sharp_k \psi u -w_h\big\|_{\Zspace{}}
\big\|{(\Id - \Pi_k^\sharp)} \psi u\big\|_{H_k^{-N}}.
\end{align*}
Arguing as in \eqref{e:localQO4}, but now using Assumption \ref{ass:swlg} where before we used Assumption \ref{ass:ii}, and also recalling that $d \geq \mathfrak{c} /8$, we find that% and the fact that $V_k$ satisfies $\max_{K \in \cT_k} h_K \leq Ck^{-1}$,
\begin{equation*}
%	\label{e:saperror}
	\|\chi_-^2 \Pi_k^\sharp \psi u  - w_h\|^2_{\cZ_k} \leq \frac{C}{k^2}\Big(\|\chi_- \Pi_k^\sharp \psi u\|^2_{\cZ_k} + \|\chi_+ \Pi_k^\sharp \psi u\|^2_{L^2(\Omega)}\Big).
\end{equation*}
Therefore, for all $\epsilon < 1$, 
\begin{equation}
	\label{eq:lunch2}
	\begin{split}
		&\big|\langle S_k(\chi_-^2\Pi_k^\sharp \psi u-w_h),(1-\chi_0){(\Id - \Pi_k^\sharp)} \psi u\rangle\big| \\
		&\qquad\qquad = Ck^{-N}\Big(
		\epsilon\|\chi_-\Pi^\sharp_k\psi u\|_{\Zspace{}}^2+
		\e  \|\chi_+\Pi^\sharp_k \psi u\|_{L^2(\Omega)}^2+ \epsilon^{-1} \big\|{(\Id - \Pi_k^\sharp)}\psi u\big\|_{H_k^{-N}}^2
		\Big).
	\end{split}
\end{equation}
Reasoning similarly and using the mapping properties of $S_k$, we find that 
\begin{equation*}
%	\label{eq:lunch3}
	\begin{aligned}
	\big|\langle S_k(\chi_-^2\Pi_k^\sharp \psi u-w_h),\chi_0{(\Id - \Pi_k^\sharp)} \psi u\rangle\big|& \leq Ck^{-1}\Big(
	\epsilon \|\chi_-\Pi^\sharp_k\psi u\|_{\Zspace{}}^2+ \e 
	\|\chi_+\Pi^\sharp_k \psi u\|_{\mathcal{H}}^2+ \epsilon^{-1} \big\|\chi_0\Pi_k^\sharp \psi u\big\|_{H_k^{-N}}^2
	\Big)\\
	&\leq Ck^{-1}\Big(
	\epsilon \|\chi_-\Pi^\sharp_k\psi u\|_{\Zspace{}}^2+ (\e+\e^{-1}) 
	\|\chi_+\Pi^\sharp_k \psi u\|_{L^2(\Omega)}^2
	\Big).
	\end{aligned}
\end{equation*}
Arguing similarly, we obtain
\begin{equation}
\begin{aligned}
	&\big|\big \langle [S_k,\chi_-]\chi_- \Pi_k^\sharp \psi u,(\Id - \Pi_k^\sharp) \psi u \big\rangle\big|\\
	& \leq C \Big(\epsilon k^{-2} \|\chi_- \Pi_k^\sharp \psi u\|_{\Zspace{}}^2 +  k^{-2}(\e+\e^{-1}) \|\chi_+ \Pi_k^\sharp \psi u\|_{L^2(\Omega)}^2 + \epsilon^{-1}k^{-N}\|(\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}^2\Big);
	\end{aligned}
	\label{eq:lunch4}
\end{equation} 
indeed, $[\chi_-,S_k] = \chi_0[\chi_-,S_k] + (1 - \chi_0)[\chi_-,S_k]$
and 
\beqs
\chi_0[\chi_-,S_k] = O_{-\infty}(k^{-1};\ZcupHspace{} \to\ZcapHspace{})\,\,\tand\,\,(1 - \chi_0)[\chi_-,S_k] = - (1-\chi_0) S_k \chi_- = O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})
\eeqs
by, respectively, 
\eqref{e:reallyGoodBaguette1} and  Theorem \ref{t:pseudoLocGeneral}.

Combining~\eqref{eq:lunch2}-\eqref{eq:lunch4} thus leads to 
\[\Rrr\leq C\epsilon \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 + C(1+\e^{-1})k^{-1}\|\chi_+ \Pi_k^\sharp \psi u\|^2_{L^2(\Omega)} + C\epsilon^{-1}k^{-N} \|(\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}^2.\]
for all $\epsilon < 1$. Inserting this estimate in \eqref{eq:PplShoutingTrain} and taking $\epsilon$ sufficiently small, we obtain~\eqref{e:localQOToShow} and hence the result. 
\end{proof}

