In the proof of Lemma \ref{l:iAmSoSmooth}, we need a variant of Lemma \ref{l:iGainKBigRemainder} where, roughly speaking, the contributions at distance $k^{-1}2^n$ from $\supp \chi$ are multiplied by a weight decaying exponentially in $n$. The main tool is the following lemma:


\begin{lemma}[Dyadic decomposition for $S_k$]
\label{l:dyadicSk}
Let $\phi_0 \in C^\infty_c(\R^d)$ with $\phi_0(x) = 1$ for $|x| \leq \frac12$, $\phi_0(x) = 0$ for $|x|\geq 1$, and let $\phi_n(x) := \phi_0(x/2^{n}) - \phi_0(x/2^{n-1})$ for $n \geq 1$. Let $x_0 \in \overline{\Omega}$, and $R > 0$, and let $\varphi_{n,k} \in C^\infty(\overline{\Omega})$ be defined by
\beqs%\label{e:varphink}
\varphi_{n,k}(x) := \phi_n((x - x_0)/(Rk^{-1})).
\eeqs
Then, for any $k_0 > 0$ and $N \in\mathbb{N}$, there exists $C(N,k_0,R) > 0$ such that for all $k \geq k_0$ and $n \in \mathbb{N}$, 
$$\|\varphi_{n,k}S_k\varphi_{0,k}\|_{L^2 \to H_k^N} \leq C(N,k_0,R) 2^{-nN}.$$
\end{lemma}
\begin{proof}
We start by observing that $\supp \phi_0\subset B(0,1)$, while for $n \geq 1$,  
$$\supp (\phi_n) \subset B(0,2^{n}) \setminus B(0,2^{n-2}),$$
and in particular, $\phi_n \perp \phi_0$ for $n \geq 2$. Let $\chi_n$ be given by Lemma \ref{l:goodCut} applied with $\Omega_1 := \supp \varphi_{k,n}$ and $\Omega_2 := \supp \varphi_{k,0}$ and $\varepsilon = O(k^{-1}2^n)$. Then $\varphi_{n,k}$ and $\varphi_{0,k}$ are separated by $\chi_n$, and the result of the Lemma follows by the combination of Lemma \ref{l:spatialCut}, Theorem \ref{thm:pseudolocSpace} and Remark \ref{r:paradise}. 
\end{proof}


\begin{lemma}
	\label{l:iStayPutOnBalls}
	Let $(V_k)_{k > 0}$ be a well-behaved finite-element of order $k$, let $k_0 > 0$, $C_\dagger > 0$, let $\psi \in C^\infty(\overline{\Omega})$ and let $N > 0$.
Then there exists $C>0$ and $\mu >0$ such that the following is true. If  $k \geq k_0$, $x_0 \in \overline{\Omega}$, $R > 0$ and $\chi_-,\chi_+ \in C^\infty(\overline{\Omega})$ satisfy
	\begin{enumerate}
		\item $\supp \chi_- \subset \supp \chi_+ \subset B(x_0, Rk^{-1}/4)$\label{l:stayPutBallCond}
		\item $d:=\dist(\supp \chi_-,\supp(1 - \chi_+)) > \mu  k^{-1}$\label{l:stayPutDistCond}
		\item $\max_{|\alpha| = n} \|\partial^\alpha \chi_-\|_{L^\infty} \leq C_{\dagger} k^{n}$, \quad $n = 0,\ldots,p$, \label{l:stayPutCutoffCond}
		\item $\supp \chi_+ \cap \supp \psi = \emptyset$, \label{l:stayPutInterCond},
	\end{enumerate} 
	then for all $u \in \cZ_k$, 
	\[\|\chi_-\Pi_k^\sharp \psi u\|_{\cZ_k} \leq C \|\chi_+\Pi_k^\sharp \psi u\|_{L^2(\Omega)} + C\sum_{n = 0}^{\infty} 2^{-Nn} \|\varphi_{n,k}( \Id - \Pi_k^\sharp) \psi u\|_{H_k^{-N}}\]
	where 
	%$\varphi_{-1}(x) = \phi_0((x-x_0)/(Rk^{-1}))$ and for $n \geq 0$, $\varphi_{n,k}(x) := \varphi((x-x_0)/(2^{n} Rk^{-1}))$. 
	$\varphi_{n,k}$ is as in Lemma \ref{l:dyadicSk}.
\end{lemma} 

\begin{proof}[Proof of Lemma \ref{l:iStayPutOnBalls}]
	Let $k_0 > 0$ be given and let $\mu  := C \kappa$ where $C$ is as in Assumption \ref{ass:qu} and $\kappa$ is as in Assumption \ref{ass:sap}. Let $C_{\dagger} > 0$, $\psi \in C^\infty(\overline{\Omega})$, $N >0$ and denote by $C > 0$ any generic constant depending only on the previous quantities. Let $k \geq k_0$, suppose that $h \leq h_0$ and let $x_0$, $R$ and $\chi_-$, $\chi_+$ as in the statement. The choice of $r$ implies that
	\[d \geq \kappa h.\]
	Therefore, one can proceed as in the proof of Lemma \ref{l:iGainKBigRemainder} using the super-approximation property (Assumption \ref{ass:sap}), but taking into account that, now, $d$ scales as $k^{-1}$ instead of $1$, so that the analogue of \eqref{e:reallyGoodSandwich1} is 
\beqs
\|\ad_{\chi_-}P_k\|_{\ZcapHspace{n}\to\ZcupHspace{n-1}}\leq C.
\eeqs
This leads to
	\begin{equation}
		\label{eq:newComputer}
		\|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 \leq C \|\chi_+ \Pi_k^\sharp \psi u\|_{L^2(\Omega)}^2 + \Rrr,
	\end{equation}
	% where $\Rrr$ is defined as in
	where, as in
 	\eqref{eq:nonLocalRemainder}, 

	\newcommand{\Rrrrrrrr}{r}
	\begin{equation}
	\label{e:defRrrrrrrr}
\Rrrrrrrr := \big|\big\langle S_k (\chi_-^2 \Pi_k^\sharp \psi u - w_h),(\Id - \Pi_k^\sharp) \psi u\big\rangle\big| + \big|\big \langle [S_k,\chi_-]\chi_- \Pi_k^\sharp \psi u,(\Id - \Pi_k^\sharp) \psi u \big\rangle\big|.
	\end{equation}


	We now use the property that for all $x \in \mathbb{R}^d$, 
	\[\sum_{n \in \mathbb{N}} \varphi_{n,k}^2(x) \geq 1/2 \]
	(see e.g. \cite[Lemma 1.1.1]{AlGe:07}) to write, for any $f,g \in \cZ_k$, 
	\[\abs{\langle S_k f,g\rangle} \leq  2\sum_{n = 0}^{\infty} \abs{\langle \varphi_{n,k} S_k f, \varphi_{n,k} g\rangle}.\]	
 	Taking $f = \chi_-^2 \Pi_k^\sharp \psi u - w_h$ and $g = (\Id - \Pi_k^\sharp)\psi u$, and using the fact that $f = \varphi_{0,k}f$, the first term of \eqref{e:defRrrrrrrr} is estimated by
	\[\begin{split}
		&\abs{\big\langle S_k ( \chi_-^2 \Pi_k^\sharp \psi u - w_h),(\Id - \Pi_k^\sharp)\psi u\big\rangle}\\ 
		& \qquad \leq 2 \sum_{n = 0}^{\infty} \big|\big\langle \varphi_{n,k} S_k \varphi_{0,k}(\chi_-^2 \Pi_k^\sharp \psi u - w_h),\varphi_{n,k}(\Id - \Pi_k^\sharp)\psi u\big\rangle\big|\\
		&\qquad \leq C\|\chi_-^2 \Pi_k^\sharp \psi u - w_h\|_{\cZ_k} \sum_{n = 0}^{\infty} \|\varphi_{n,k} S_k \varphi_{0,k}\|_{\cZ_k \to H_k^{N}} \|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}} \\
		&\qquad\leq C(\|\chi_- \Pi_k^\sharp u\|_{\cZ_k} + \|\chi_+ \Pi_k^\sharp u\|_{L^2(\Omega)}) \sum_{n = 0}^{\infty} \|\varphi_{n,k} S_k \varphi_{0,k}\|_{\cZ_k \to H_k^{N}} \|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}},
	\end{split}\]
	where we have used that
	\[\|\chi_-^2 \Pi_k^\sharp \psi u - w_h\|_{\cZ_k} \leq C \frac{1}{(kd)^2} \|\chi_- \Pi_k^\sharp u\|_{\cZ_k} + \|\chi_+ \Pi_k^\sharp u\|_{L^2(\Omega)}\]
	(obtained by reasoning as in \eqref{e:localQO4}), and taken into account that $(kd)^{-1} \leq M^{-1} \leq C$. By Lemma \ref{l:dyadicSk}, 
	\[\|\varphi_{n,k} S_k \varphi_{0,k}\|_{\cZ_k \to H_k^{N}} \leq C 2^{-Nn} \quad \tfa n \in \mathbb{N}.\]
	Hence, for all $\epsilon < 1$, 
	\begin{align}\nonumber
		&\abs{\big\langle S_k ( \chi_-^2 \Pi_k^\sharp \psi u - w_h),(\Id - \Pi_k^\sharp)\psi u\big\rangle} \\
		%\nonumber
		&\qquad \leq C\epsilon \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 + C\epsilon \|\chi_+ \Pi_k^\sharp \psi u\|_{L^2(\Omega)}^2 + C\epsilon^{-1} \left(\sum_{n = 0}^{\infty} 2^{-Nn} \|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}\right)^2 
		%\nonumber
		\label{eq:Sestim1}
		%&\qquad \leq  C\epsilon \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 + C\epsilon \|\chi_+ \Pi_k^\sharp \psi u\|_{L^2(\Omega)}^2\\ 
		%\nonumber
		%&\hspace{5cm} + C\epsilon^{-1} \left(\sum_{n = 0}^{\infty} 2^{-2nN} \right) \left(\sum_{n = 0}^{\infty}2^{-2nN}\|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}^2\right)\\
		%&\qquad \leq  C\epsilon \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 + C\epsilon \|\chi_+ \Pi_k^\sharp \psi u\|_{\cH}^2+ C\epsilon^{-1}\sum_{n = 0}^{\infty}2^{-2nN}\|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}^2
	\end{align}
	Similarly, using that $\varphi_{n,k} \chi_-  =  0$ for $n \geq 1$, we deduce that for all $\varepsilon < 1$, 
	\begin{align}\nonumber
		&\abs{\big\langle [\chi_-,S_k] \chi_- \Pi_k^\sharp \psi u, (\Id - \Pi_k^\sharp) \psi u\big\rangle}\\\nonumber &\qquad\leq 2 \abs{\langle \varphi_{0,k} [S_k,\chi_-] \chi_- \Pi_k^\sharp \psi u, \varphi_{0,k} (\Id - \Pi_k^\sharp)\psi u\rangle} + \sum_{n = 1}^{\infty} \abs{\big\langle \varphi_{n,k} S_k\chi_-^2\Pi_k^\sharp \psi u, \varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\big\rangle} \\\nonumber
		&\qquad \leq C \big\|\chi_- \Pi_k^\sharp \psi u\big\|_{\cZ_k} \big\|\varphi_{0,k} [S_k,\chi_-]\big\|_{\cZ_k \to H_k^{N}} \big\|\varphi_{0,k}(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-N}}\\\nonumber
		&\qquad\qquad \qquad + C \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k} \sum_{n = 1}^{\infty} \|\varphi_{n,k} S_k \varphi_{0,k}\|_{\cZ_k \to H_k^{N}} \|\varphi_{n,k} (\Id - \Pi_k^\sharp) \psi u\|_{H_k^{-N}}\\
		& \qquad \leq C \varepsilon \|\chi_- \Pi_k^\sharp \psi u\|_{\cZ_k}^2 + C \varepsilon^{-1} \left( \sum_{n = 0}^{\infty} 2^{-Nn} \|\varphi_{n,k} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-N}}\right)^2.
		\label{eq:Sestim2}
	\end{align}
Adding \eqref{eq:Sestim1} and \eqref{eq:Sestim2}, inserting the result in \eqref{e:defRrrrrrrr} and then in \eqref{eq:newComputer}, %using that 
%$(\sum_{n} |a_n|)^2 \geq \sum_{n} |a_n|^2$ 
and letting $\varepsilon$ be small enough, we obtain the result.
\end{proof}

