\begin{proof}[Proof of Lemma \ref{l:iAmSoSmooth}]
We claim that, given $\mathfrak{c} > 0$, there exists $h_0 > 0$ such that for all $k_0 > 0$ and $\chi_-, \chi_+ ,\psi \in C^\infty(\overline{\Omega})$ satisfying 
\begin{equation}
	\label{e:sepChi-Chi+}
\chi_-\prec_{\mathfrak{c}} \chi_+ \quad \tand \quad \chi_- \perp \psi
\end{equation}
there exists 
% \mathfrak{C}
$C > 0$ such that for all $k \geq k_0$, $h\leq h_0$, $u \in \cZ_k$ and $0\leq j\leq p-1$,
\begin{equation}
	\label{e:iAmSoSmooth2}
	\|\chi_{-} \Pi^\sharp_k \psi u\|_{H_k^{-j}}\leq C\Big(\|\chi_+\Pi_k^\sharp \psi u\|_{H_k^{-(j+1)}} 
	+\big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-p}}
	\Big).
\end{equation}
If this is true, the lemma follows easily. Indeed, given $\mathfrak{c} > 0$, let $\mathfrak{c'} = \frac{\mathfrak{c}}{2p}$, and given $\chi, \psi$ as in the statement, let $\chi_1,\ldots, \chi_p$ be a sequence of nested cutoffs, i.e. such that
\begin{equation*}
\chi_i \prec_{\mathfrak{c'}}\chi_{i+1}
	\qquad \tfa i \in \{1,\ldots,p-1\}\quad\tand\quad \chi_p \perp \psi.
\end{equation*}
One then applies \eqref{e:iAmSoSmooth2} $p$ times with $\chi_- = \chi_i$ and $\chi_+= \chi_{i+1}$, using at the end that $\chi_p \Pi_k^\sharp \psi u = \chi_p (\Id - \Pi_k^\sharp) \psi u$ to obtain \eqref{e:iAmSoSmooth}.

It therefore remains to prove  \eqref{e:iAmSoSmooth2}. Let $\mathfrak{c} > 0$ be given and let $h_0 > 0$ be a sufficiently small constant. Let $k_0 > 0$, $\chi_-,\chi_+,\psi \in C^\infty(\overline{\Omega})$ such that \eqref{e:sepChi-Chi+} holds and let $C > 0$ denote a generic constant depending only on the previous quantities. Let $k \geq k_0$, suppose that $h\leq h_0$, let $u \in \cZ_k$ and let $0 \leq j \leq p-1$.

By arguing exactly as at the start of the proof of Lemma \ref{l:iGainKBigRemainder}, without loss of generality, we can assume that $\partial_\nu \chi_-=0$ 
and thus the commutator estimates \eqref{e:reallyGoodSandwich1} and \eqref{e:reallyGoodBaguette1} hold
(the first one by Lemma \ref{l:spatialCut} and Definition \ref{def:spatialCutoffs}, and the second one
by Proposition \ref{prop:proofadNR1}).

Let $\chi_0,\chi_1 \in C^\infty(\overline{\Omega})$ be such that 
\[
 \chi_- \prec_{(\mathfrak{c}/3)} \chi_0 \prec_{(\mathfrak{c}/3)} \chi_1 \prec_{(\mathfrak{c}/3)} \chi_+.
\]
To prove \eqref{e:iAmSoSmooth2}, it is sufficient to show that, for all $v \in H_k^{j}$, 
\begin{equation}
\label{e:regularShow}
\big|\big\langle v,\chi_- \Pi^\sharp_k \psi u\big\rangle\big|\leq C\Big(\|\chi_+\Pi^\sharp_k \psi u\|_{H_k^{-(j+1)}}+\big\|(\Id-\Pi_k^\sharp)\psi u\big\|_{H_k^{-p}}
\Big)\|v\|_{H_k^{j}}.
\end{equation}
By the relation $P_k^\sharp\RPd = \Id$, the definition of $\Pi_k^\sharp$ (Definition \ref{def:ellipticProjection}), and the fact that $\chi_-\psi = 0$, for all $w_h \in V_k$,
\begin{align}\nonumber
	\langle v,\chi_{-} \Pi_k^\sharp \psi u\rangle &=	\big\langle  P_k^\sharp R_{k}^\sharp v, \chi_{-}{(\Id - \Pi_k^\sharp) }\psi u\big\rangle  \\ \nonumber
	&=	\big\langle  \chi_{-} P_k^\sharp R_{k}^\sharp v, {(\Id - \Pi_k^\sharp)}\psi u\big\rangle  \\ \nonumber
		& = \big\langle  P_k^\sharp \chi_-R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)}\psi u\big\rangle + \big\langle  [\chi_-,P_k^\sharp] R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)}\psi u\big\rangle\\ 
				& = \big\langle  P_k^\sharp\big( \chi_-R_{k}^\sharp v -w_h\big), {(\Id - \Pi_k^\sharp)} \psi u\big\rangle +
				 \big\langle  [\chi_-,P_k^\sharp] R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)}\psi u\big\rangle.
%	&= a_k^\sharp(\Pi_k^\sharp \psi u, \chi_- (R_k^\sharp)^* v - w_h) + a_k(\psi u,w_h) + \big\langle [P_k^\sharp,\chi_-] \Pi_k^\sharp \psi u,(R_k^\sharp)^* v\big\rangle.
\label{e:EuanYawn1}
\end{align}
For the second term on the right-hand side of \eqref{e:EuanYawn1}, since $\chi_- = \chi_- \chi_+$, by locality of $P_k$, and by the mapping properties of $R_k^\sharp$ (Proposition \ref{prop:ResPksharp}), $[\chi_-,P_k]$ 
(from \eqref{e:reallyGoodSandwich1}), and  $[\chi_-,S_k]$ (from \eqref{e:reallyGoodBaguette1}),
%Assumption \ref{ass:spatialCutoffs}\eqref{ass:Spat:commProp1} and Proposition \ref{prop:proofadNR1} with $N = 1$),  
\begin{align}\nonumber
	\abs{\big\langle  [\chi_-,P_k^\sharp] R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)} \psi u\big\rangle} &\leq \abs{\big\langle  \chi_+ [\chi_-,{P_k}] R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)} \psi u\big\rangle}+ \abs{ \big\langle  [\chi_-,{S_k}] R_{k}^\sharp v,{(\Id - \Pi_k^\sharp)}  \psi u\big\rangle} \\\nonumber
	&\leq Ck^{-1} \|v\|_{H_k^{j}} \Big(\|\chi_+(\Id - \Pi_k^\sharp )\psi u\|_{H_k^{-j-1}} + \big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-p}} \Big).\nonumber
\end{align}
Furthermore, by the mapping properties of $S_k$ (Proposition \ref{prop:f(Pk)}),
\begin{align*}
\abs{\big\langle S_k (\chi_- R_k^\sharp v - w_h),(\Id - \Pi_k^\sharp)\psi u\big\rangle} 
%&\leq C \big\|\chi_- R_k^\sharp v - w_h\big\|_{\Zspace{1}} \big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{\Zspace{-p}}\\
&\leq C \big\|\chi_- R_k^\sharp v - w_h\big\|_{\Zspace{1}} \big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-p}}.
\end{align*}
Using the approximation property of $V_k$ (Assumption \ref{ass:ap}) with $m = 1$, and using that $j+2 \leq p+1$, we can choose $w_h$ supported in $\supp \chi_0$ such that
\beq\label{e:bankHoliday2}
\sum_{K \in \mathcal{T}_k}(h_K k)^{-2(j+1)} \|\chi_- R_k^\sharp v- w_h\|_{H^1_k(K)}^{2} \leq \Cfem \|\chi_- R_k^\sharp v\|^2_{H_k^{j+2}} \leq C \|v\|_{H_k^{j}}^2.
\eeq
In particular, 
\[\begin{split}
	\big\|\chi_- R_k^\sharp v - w_h\big\|_{\Zspace{1}}^2 = \sum_{K \in \cT_k} \|\chi_- R_k^\sharp v - w_h\|_{H^1_k(K)} 
	& \leq (hk)^{2j}  \sum_{K \in \cT_k} h_K^{-2j} \|\chi_- R_k^\sharp v - w_h\|_{H^1_k(K)} \\
	& \leq C(hk)^{2j} \N{v}_{H_k^{j}}^2,
\end{split}\]
where we recall that $h: = \max_{K \in \cT_k} h_K$. Hence, with this choice of $w_h$, since $V_k$ satisfies $hk \leq C$, 
\[\abs{\big\langle S_k (\chi_- R_k^\sharp v - w_h),(\Id - \Pi_k^\sharp)\psi u\big\rangle} \leq C \|v\|_{H_k^{j}} \big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-p}}.\]
%In particular, as $k \to \infty$, this is controlled by the right-hand side of \eqref{e:regularShow}.  
Therefore, to prove \eqref{e:regularShow}, it remains to prove that for this choice of $w_h\in V_k$,
\begin{equation}
	\label{e:EuanYawn3}
	\big|\big\langle  P_k\big( \chi_-R_{k}^\sharp v -w_h\big),{(\Id - \Pi_k^\sharp )}\psi u\big\rangle\big|\leq C \Big(\|\chi_+ \Pi_k^\sharp \psi u\|_{H_k^{-(j+1)}} + \big\|(\Id - \Pi_k^\sharp)\psi u\big\|_{H_k^{-p}}\Big)\|v\|_{H_k^{j}}.
\end{equation}
By (in this order) the locality of $P_k$ and  the fact that $\chi_0\equiv 1$ on the support of $\chi_- \RPd v - w_h$, 
continuity of $P_k$, and \eqref{e:bankHoliday2},
\begin{align}\nonumber
&|\langle P_k(\chi_- R_{k}^\sharp v-w_h),(\Id - \Pi_k^\sharp) \psi u\rangle|\\ \nonumber
&\qquad = |\langle P_k(\chi_- R_{k}^\sharp v-w_h),\chi_0(\Id - \Pi_k^\sharp) \psi u\rangle|\\\nonumber
&\qquad\leq \sum_{K\in \mc{T}_k}\|\chi_0 (\Id - \Pi_k^\sharp) \psi u\|_{H^1_k(K)}\|\chi_- R_{P^\sharp_k}v-w_h\|_{H^1_k(K)}
\\\nonumber
&\qquad\leq \Big(\sum_{K\in \mc{T}_k}(h_Kk)^{2(j+1)}\|\chi_0 \Pi^\sharp_k \psi u\|^2_{H^1_k(K)}\Big)^{\frac{1}{2}}\Big(\sum_{K\in \mc{T}_k}(h_K k)^{-2(j+1)}\|\chi_- R_{P^\sharp_k}v-w_h\|^2_{H^1_k(K)}\Big)^{\frac{1}{2}}\\
%&\qquad\leq  C\Big(\sum_{K\in \mc{T}}(h_Kk)^{2(j+1)}\|\chi_0\Pi^\sharp_k \psi u\|^2_{H^1_k(K)}\Big)^{\frac{1}{2}}\|\chi_- R_{P^\sharp_k}v\|_{\Zspace{j+2}}\\
%&\leq  C\Big(\sum_{K\in \mc{T}}(h_Kk)^{2(j+1)}\|\Pi^\sharp_k u\|^2_{\Zspace{1}}\Big)^{\frac{1}{2}}\|R_{P^\sharp_k}v\|^2_{\Zspace{j+2}}\\
&\qquad\leq C \Big(\sum_{K\in \mc{T}_k}(h_Kk)^{2(j+1)}\|\chi_0\Pi^\sharp_k\psi  u\|^2_{H^1_k(K)}\Big)^{\frac{1}{2}}\|v\|_{H_k^{j}}.
\label{e:dualityGivesRegularity}
\end{align}
To apply the arguments from \cite[Lemma 5.5]{AvGaSp:24}, and especially the wavelength-scale quasi-uniformity (Assumption \ref{ass:qu}), we now need to group the elements $K \in \cT_k$ into sets lying within balls of radius $\approx k^{-1}$. 

To this end, we choose a sufficiently large constant $\mu > 0$ depending only on $h_0$ and $k_0$ and let $\{x_\ell\}_{\ell=1}^{\cL}\subset\Omega$ be a ``maximal $\mu k^{-1}$ separated set", constructed inductively by choosing an initial point $x_1 \in \Omega$, and if $x_1,\ldots,x_\ell$ are constructed, choosing $x_{\ell + 1} \in \Omega \setminus \cup_{m = 1}^\ell B(x_\ell,\mu k^{-1})$ if this set is not empty, or finishing the construction with $\ell = \cL$ otherwise. By construction,
\begin{equation*}
%\label{e:covers}
\Omega\subset \bigcup_{\ell=1}^{\cL} B(x_\ell, \mu k^{-1}),
\end{equation*}
and one can check that for all $M>0$, there exists $\mathfrak{D}_M>0$ depending solely on $M$ and the space dimension $d$, and there exists a partition of $\{1,\ldots,\mathcal{L}\}$ into $\mathfrak{D}_M$ sets $\mathcal{J}_1^M, \mathcal{J}_2^M,\ldots,\mathcal{J}_{\mathfrak{D}_M}^M$, such that
\begin{equation*}
%\label{e:notTooManyOverlaps}
(\ell_1,\ell_2\in \mc{J}_m^M \,\,\tand \,\,\ell_1\neq \ell_2 )\,\Rightarrow\, B(x_{\ell_1},M\mu k^{-1})\cap B(x_{\ell_2},M\mu  k^{-1})=\emptyset,
\end{equation*}
i.e., the maximal number of overlaps between balls of radius $M\mu k^{-1}$ with centers in $\{x_{\ell}\}_{\ell = 1}^{\cL}$ is $\mathfrak{D}_M$.  
Define
$$
h_\ell:=\max\big\{ h_K\,:\, K\cap B(x_\ell,k^{-1}) \neq \emptyset\big\}\leq C_M\inf\big\{ h_K\,:\, K\cap B(x_\ell, M\mu k^{-1})\neq \emptyset\big\},
$$
where the second inequality follows from Assumption~\ref{ass:qu}. For all $1 \leq \ell \leq \cL$ and for $m \geq 1$, let  $\chi_{\ell,m} \in C^\infty(\overline{\Omega})$ be such that 
\begin{equation}
	\label{e:condChiEllM}
	\supp \chi_{\ell,m} \subset B(x_\ell,(m+1)\mu k^{-1}) \cap \overline{\Omega}, \quad \supp (1 - \chi_{\ell,m}) \cap B(x_{\ell},m\mu k^{-1}) \cap \overline{\Omega} = \emptyset.
\end{equation}
Using a construction via scaling, one can arrange that there exists a universal constant $C_\dagger$ such that
\begin{equation}
	\|\partial^\alpha \chi_{\ell,m}\|_{\infty} \leq C_\dagger  (\mu  k^{-1})^{-|\alpha|} \quad \tfa |\alpha|\leq p.
	\label{e:controlChiLM}
\end{equation} 
By choosing $\mu $ large enough, one ensures that $\mu  k^{-1} \geq 2h$, which implies that $K \cap B(x_\ell,\mu  k^{-1}) \neq \emptyset \implies K \subset B(x_\ell,2\mu  k^{-1})$. Therefore, 
\begin{align}\nonumber
\sum_{K\in \mc{T}_k}(h_Kk)^{2(j+1)}\|\chi_0\Pi^\sharp_k \psi u\|^2_{H^{1}_k(K)}&\leq C\sum_{\ell=1}^{\cL} (h_{\ell}k)^{2(j+1)}\sum_{K\cap B(x_\ell,\mu k^{-1})\neq \emptyset}\|\chi_0\Pi^\sharp_k \psi u\|^2_{H^1_k(K)}\\ \nonumber
&\leq C\sum_{\ell=1}^{\cL} (h_{\ell}k)^{2(j+1)}\sum_{K\subset B(x_\ell,2\mu k^{-1})}\|\chi_0\Pi^\sharp_k \psi u\|^2_{H^1_k(K)}\\
&\leq C\sum_{\ell = 1}^{\cL} (h_{\ell}k)^{2(j+1)}\|\chi_0\chi_{\ell,2}\Pi^\sharp_k \psi u\|^2_{\cZ_k}.
\label{e:regrouping}
\end{align}
Next we apply Lemma~\ref{l:iStayPutOnBalls} to estimate the norms $\|\chi_0\chi_{\ell,2} \Pi_k^\sharp \psi u\|_{\cZ_k}$. Choosing $R = 20\mu $, one gets that for every $\ell = 1,\ldots,\cL$, 
\[ \supp (\chi_0 \chi_{\ell,2}) \subset \supp (\chi_1 \chi_{\ell,4}) \subset B(x_\ell,Rk^{-1}/4),\]
so that assumption \eqref{l:stayPutBallCond} is satisfied.
Moreover, by definition of $\chi_{\ell,m}$ (see \eqref{e:condChiEllM}), 
\[d:=\dist (\supp(\chi_0 \chi_{\ell,2}), \supp (1- \chi_1 \chi_{\ell_4})) \geq \dist(B(x_\ell,3\mu k^{-1}),B(x_\ell,4 \mu k^{-1})^c) \geq \mu k^{-1},\]
showing that assumption \eqref{l:stayPutDistCond} is also satisfied by taking $\mu$ sufficiently large.
Assumption \eqref{l:stayPutCutoffCond} follows from this and the control on the derivatives of $\chi_{\ell,m}$ in \eqref{e:controlChiLM}. Finally, we have $\supp (\chi_1 \chi_{\ell,4})\subset \supp \chi_{1} \subset (\supp \psi)^c$ so that assumption \eqref{l:stayPutInterCond} holds. Therefore,  by Lemma~\ref{l:iStayPutOnBalls}, for $N\geq p$,
\begin{equation}
\label{e:crossfire1}
\| \chi_0 \chi_{\ell,2}\Pi^\sharp_k \psi u\|^2_{\cZ_k}\leq C\|\chi_{1} \chi_{\ell,4}\Pi^\sharp_k \psi  u\|^2_{L^2(\Omega)} + C\sum_{n= 0}^{\infty}2^{-Nn}\|\varphi_{n,\ell}(\Id - \Pi_k^\sharp) \psi u\|_{\Hspace{-p}}^2
\end{equation}
where 
\begin{equation}
\label{e:varphi}
\varphi_{n,\ell} = \phi_n\big((x - x_\ell)/( Rk^{-1})\big) \tfor n \geq 0,
\end{equation}
with $\phi_n$ as in Lemma \ref{l:dyadicSk}.
(note that here it is crucial that $\mathfrak{C}$ in Lemma \ref{l:iStayPutOnBalls} does not depend on $\chi_-$ and $\chi_+$). 

By \eqref{e:EuanYawn3}, \eqref{e:dualityGivesRegularity}, \eqref{e:regrouping}, and \eqref{e:crossfire1}, to prove \eqref{e:regularShow}, it is sufficient to prove that 
\beq\label{e:crossfire2}
	\sum_{\ell = 1}^\cL (h_\ell k)^{2(j+1)}\|\chi_{1}\chi_{\ell,4} \Pi^\sharp_k \psi  u\|^2_{L^2(\Omega)} \leq C \|\chi_+\Pi_k^\sharp \psi u\|_{H_k^{-(j+1)}}^2.
\eeq
and 
\beq
\sum_{\ell= 1}^{\cL} (h_\ell k)^{2(j+1)}\sum_{n = 0}^{\infty} 2^{-Nn} \|\varphi_{n,\ell} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-p}}^2 \leq C\|(\Id - \Pi_k^\sharp) \psi u\|_{H_k^{-p}}^2.
\label{e:crossfire3}
\eeq

By the wavelength-scale quasi-uniformity (Assumption \ref{ass:qu}) and  the inverse inequality (Assumption \ref{ass:ii}),
\[\begin{split}
	\sum_{\ell = 1}^\cL (h_\ell k)^{2j+2}\|\chi_{1}\chi_{\ell,4} \Pi^\sharp_k \psi  u\|^2_{L^2(\Omega)} &\leq C \sum_{\ell = 1}^{\cL} \sum_{K \cap \supp \chi_{1}\chi_{\ell,4} \neq \emptyset} (h_K k)^{2j+2} \|\Pi_k^\sharp \psi u\|^2_{L^2(K)} \\
	& \leq C \sum_{\ell = 1}^{\cL} \sum_{K \cap \supp \chi_{1}\chi_{\ell,4} \neq \emptyset}  \|\Pi_k^\sharp \psi u\|^2_{H^{-(j+1)}(K)}.
	\end{split}\]
Applying \cite[Lemma 5.2]{AvGaSp:24} (a simple bound on sums of negative Sobolev norms on elements by a global dual norm) and Lemma \ref{l:sumNegNorms} below, there exists $M > 0$ large enough such that 
\[
\sum_{l = 1}^{\cL}\sum_{K \cap \supp \chi_{1}\chi_{\ell,4} \neq \emptyset} \|\Pi_k^\sharp \psi u\|^2_{H^{-(j+1)}(K)} \leq C \sum_{l = 1}^{\cL} \big\|\chi_+ \chi_{\ell,M} \Pi_k^\sharp \psi u\big\|^2_{H_k^{-(j+1)}} \leq C \mathfrak{D}_M \|\chi_+\Pi_k^\sharp \psi u\|_{H_k^{-(j+1)}}^2,
\]
and the combination of these last two displayed equations is \eqref{e:crossfire2}.

On the other hand, 
by the definition of $\varphi_{n,\ell}$ \eqref{e:varphi}, there exists $C_{p,R}>0$ such that 
for every $x \in \R^d$, 
\beq\label{e:crossfire4}
	\sum_{\ell = 1}^{\cL}\sum_{n = 0}^{\infty} 2^{-Nn}
\Big(\max_{1\leq \alpha\leq p} k^{-|\alpha|}\abs{\varphi_{n,\ell}(x)}\Big)^2	
	 \leq C_{p,R}\sum_{n = 0}^{\infty} 2^{-Nn} \kappa_n(x)
\eeq
where
\[\kappa_n(x) = \textup{Card}\Big(\big\{ 1 \leq \ell \leq \cL \,:\, \dist(x,x_\ell) \leq 2^{n+1}Rk^{-1} \big\}\Big).\]
To estimate $\kappa_n(x)$, we write
\[ \kappa_n(x) = \sum_{m = 1}^{\mathfrak{D}_1} \textup{Card}(K_m(x)),\quad \textup{where}\quad K_m(x) := \big\{ \ell \in \mathcal{J}_m^1 \,:\, \dist(x,x_\ell) \leq 2^{n+1} Rk^{-1}\big\}\] 
and since the $\mu k^{-1}$ balls centered at $x_\ell$ for $\ell \in \mathcal{J}_m^1$ are pairwise disjoint, 
\[\sum_{\ell \in K_m(x)} \mu(B(x_\ell,k\mu^{-1})) \leq \mu (B(x,2^{n+1}Rk^{-1})) \quad \iff \quad \textup{Card}(K_m(x)) \leq 2^{d(n+1)}\frac{R^d}{\mu^d}.\]
This proves that $\kappa_n(x) \leq C 2^{nd}$. 
Inserting this bound into \eqref{e:crossfire4} and choosing $N$ large enough,  we find that 
\beqs%\label{e:crossfire4a}
	\sum_{\ell = 1}^{\cL}\sum_{n = 0}^{\infty} 2^{-Nn}
\Big(\max_{1\leq \alpha\leq p} k^{-|\alpha|}\abs{\varphi_{n,\ell}(x)}\Big)^2	
	 \leq C C_{p,R}.
\eeqs
We now use Lemma \ref{l:sumNegNorms} with $\{\chi_n\}_{n} = \{ 2^{-nN/2} \varphi_{n,\ell}, : \ell=1,\ldots, \cL , n=0,\ldots, \infty\}$ to obtain that
%
%Thus there exists $C_{\rm over}'>0$ such that, for all $N$ sufficiently large,
%\[
%\sum_{\ell = 1}^{\cL}\sum_{n = -1}^{\infty} 2^{-Nn} 1_{x\in \supp \varphi_{n,\ell}} < C_{\rm over}'.
%\]
%Therefore, by the definition of $\varphi_{n,\ell}$ \eqref{e:varphi}, given $N>0$, there exists $C_{\rm over}$ such that for all $x \in \R^d$ and all $k \geq k_0$, 
%\[\sum_{\ell = 1}^{\cL}\sum_{n = -1}^{\infty} 2^{-Nn} \Big(\max_{1\leq \alpha\leq N} k^{-|\alpha|}\abs{\varphi_{n,\ell}(x)}\Big)^2  < C_{\rm over}.\]
%Thus, by Lemma \ref{l:sumNegNorms}, 
\[\sum_{\ell= 1}^{\cL} \sum_{n = 0}^{\infty} 2^{-Nn} \|\varphi_{n,\ell} (\Id - \Pi_k^\sharp)\psi u\|_{H_k^{-p}}^2 \leq CC_{p,R} \|(\Id - \Pi_k^\sharp) \psi u\|_{H_k^{-p}}^2,\]
which is \eqref{e:crossfire3}, and the proof is complete.
\end{proof}

\

Finally, we prove the following technical lemma used in the proof of Lemma \ref{l:iAmSoSmooth}.

% Given a sequence $(\chi_n)_n$ of functions in $C^\infty(\R^d)$, suppose there exists $C_{\rm over}> 0$ such that for all $x \in \R^d$,
%		\[\sum_{n = 0}^{\infty} |\chi_n(x)|^2 \leq C_{\rm over}.\]
%		Then for any sequence $(u_n)_n$ of elements of $\Hspace{j}$, 
%		\[\Big\|\sum_{n = 0}^{\infty} \chi_n u_n\Big\|^2_{\Hspace{j}} \leq C C_{\rm over} \sum_{n = 0}^{\infty} \|\chi_n u_n\|^2_{\Hspace{j}}.\] 

\begin{lemma}
	\label{l:sumNegNorms}
Given $N>0$ there exists $C_N>0$ such that the following is true. Suppose that $(\chi_n)_n$ is such that
	there exists $C_{\rm over}> 0$ such that for all $x \in \R^d$,
		\[\sum_{n = 0}^{\infty} \Big(\max_{|\alpha|\leq N}k^{-|\alpha|}|\partial^\alpha \chi_n(x)|\Big)^2 \leq C_{\rm over}.\]
%		 for all $u_n \in \Hspace{N}$, 
%	\[\Big\|\sum_{n} \chi_n u_n\Big\|_{\Hspace{N}}^2 \leq C_{\rm over} \sum_{n} \|u_n\|_{\Hspace{N}}^2.\]
Then, for all $v \in H_k^{-N}$, 
	\begin{equation}
		\label{eq:sumNegNorms}
		\sum_{n} \|\chi_n v\|^2_{H_k^{-N}} \leq C_N C_{\rm over}\N{v}^2_{H_k^{-N}}.
	\end{equation}
\end{lemma}
\begin{proof}
	For every $n$, let $\theta_n := \|\chi_n v\|_{H_k^{-N}}$, let $\varphi_n \in H_k^{N}$ with unit norm, and let 
	\[\varphi := \sum_{n} \chi_n \theta_n \varphi_n.\]
	Then by assumption, 
	\[\N{\varphi}_{\Hspace{N}}^2 \leq C_N C_{\rm over} \sum_{n} \theta_n^2.\]
	Therefore, 
	\[\N{v}_{H_k^{-N}} \geq \frac{|(v,\varphi)|^2}{\|\varphi\|^2_{H_k^{N}}} \geq \frac{\big|\sum_{n} (v,\theta_n\chi_n \varphi_n)\big|^2}{C_N C_{\rm over}\sum_{n}\theta_n^2} = \frac{\big|\sum_{n} \theta_n(\chi_n v, \varphi_n)\big|^2}{C_N C_{\rm over}\sum_{n}\theta_n^2} .
	\]
	By taking the supremum over each $\varphi_n$,
	\[\N{v}_{H_k^{-N}}  \geq \frac{1}{C_N C_{\rm over}} \frac{\Big|\sum_{n} \theta_n^2\Big|^2}{\sum_{n} \theta_n^2} =  \frac{1}{C_N C_{\rm over}}\sum_{n} \theta_n^2,\]
and the result \eqref{eq:sumNegNorms} follows.
\end{proof}


\section{Proof of the main result (Theorem \ref{t:theRealDeal})}
\label{sec:proof_realDeal}

We fix $a_k : H^1_k \times H^1_k \to \R$, $\mathcal{J} \subset \R_+$, $p$, $(V_k)_{k > 0}$ as in the statement of Theorem \ref{t:theRealDeal}, and keep the definitions and notations from Sections \ref{sec:state_main_result}, \ref{sec:pseudolocS}, and \ref{sec:pseudoLocPi}. We denote by $h = h(k) := \max_{K \in \cT_k} h_K$. 

\subsection{Outline of the proof}

%Let $\{\varphi_j\}_{j = 1}^\domainnumber$ be a partition of unity on $\overline{\Omega}$ subordinate to the cover $\{\Omega_j\}_{j = 1}^\domainnumber$, and let $\{\chi_j\}_{j = 1}^\domainnumber$ be a set of compactly supported functions on $\R^d$ such that $\supp \chi_j\subset \overline{\Omega_j}$
%and $\varphi_j\prec \chi_j$.
%, $\supp (1 - \chi_j) \cap \supp \varphi_j = \emptyset$. 
Let $X^-(\ell), X^+(\ell) \in \R^{M_\Int}, X^\Pml \in \R^{M_\Pml}$ be the column vectors defined by
\[X^{-}_i(\ell) := \| \chi_i\Psi (u-u_h)\|_{H^\ell_k}, \quad X_i^{+}(\ell) := \|\chi_i(1-\Psi)  (u-u_h)\|_{H_k^\ell}, \quad 1 \leq i \leq M_\Int,\]
\[\tand\quad X^\Pml_i(\ell) := \|\chi_{i + M_\Int}(u-u_h)\|_{H_k^\ell} \quad 1 \leq i \leq M_\Pml
\] 
%(the case $\ell = 1$ corresponds to estimates in the energy norm, while $\ell \leq 0$ gives negative norm estimates), 
and let $Z \in \R^M$ be the column vector of local best approximation errors, i.e., 
$$Z_i = \|u - w_h\|_{H^1_k(\Omega_i)}$$
where $w_h$ is an arbitrary, fixed element of $V_k$. The heart of the proof of Theorem \ref{t:theRealDeal} consists of forming a matrix system of inequalities for the vector $X(\ell) = \begin{pmatrix}
	X^-(\ell) \\ X^{+}(\ell) \\ X^\Pml(\ell)
\end{pmatrix}$. We start by obtaining this system in the lowest possible norm, which is dictated by the polynomial order $p$, i.e., with $\ell = -p+1$. In Lemma \ref{l:lastDay}, we show that 
\begin{equation}
\label{e:systemOutline}
X(-p+1) \leq \specialC \oldT X(-p+1) + C B Z + R
\end{equation}
where $R$ is a superalgebraically small remainder term, where $\oldT$ and $B$ are the matrices defined in \eqref{e:matrixT} and \eqref{e:matrixB}, and where $C_\dagger, C$ are positive constants. 
Therefore, if $(I- \specialC \oldT)^{-1}$ exists, then 
\beqs
%\label{e:system_lowest_outline}
X(-p+1) \leq \mathfrak{C}(I - \specialC \oldT)^{-1} BZ + R\,.
\eeqs
Each line of the inequality \eqref{e:systemOutline} is obtained by applying a localised version of the elliptic-projection argument, Lemma \ref{l:localDualityArg}, and exploiting both the local behaviour of the mesh size and the microlocal behaviour of the solution operator of the continuous problem from \S\ref{sec:boundsCsol} (and in particular, its improved behaviour on high-frequencies or in the PML region, leading to Lemmas \ref{l:highFreqUpgrade} and \ref{l:PMLUpgrade}). 


We then use Theorem \ref{t:onlyTheSimpleOnes} to bound $(I- \specialC \oldT)^{-1}$ in terms of the simple-path matrix $\transfer$ of $\specialC \oldT$ (Definition \ref{def:simple_path_mat}), giving 
\begin{equation}
\label{e:system_lowest_outline2}
X(-p+1) \leq \mathfrak{C}\transfer BZ + R\,.
\end{equation}

Next, we upgrade \eqref{e:system_lowest_outline2} to higher norms, i.e., we estimate $X(\ell)$ for $1-p\leq \ell\leq 1$. For this, we notice that, on the one hand, since $\Psi$ is smoothing and pseudo-local,
\begin{equation}
\label{e:X-_upgrade_outline}
X^{-}(\ell) \leq C X^{-}(-p+1) + R
\end{equation}
for all $1-p\leq \ell\leq 1$. 
(In fact,  \eqref{e:X-_upgrade_outline} should actually have an $\widetilde{X}^-$ on the right-hand side involving $\widetilde{\chi}_i$ such that $\chi_i \prec \widetilde{\chi}_i$, but we have neglected this in this outline for brevity.)

On the other hand, by the ``improved'' local duality arguments of Lemmas \ref{l:highFreqUpgrade} and \ref{l:PMLUpgrade}, 
\begin{equation}
\label{e:X+_upgrade_outline}
X^{+}(\ell) \lesssim (\mathcal{H}k)^{\ell+1} Z +  (\mathcal{H}k)^{p+\ell + 1} X^{-}(-p+1) + (\Hmin(N) k^N) X^+(-p+1)+ R
\end{equation}
\begin{equation}
\label{e:Pml_upgrade_outline}
X^{\Pml}(\ell) \lesssim (\mathcal{H}k)^{\ell+1} Z + (\Hmin(N) k^N) \big(X^+(-p+1) +  X^-(-p+1)\big) + R
\end{equation}
for all $1-p\leq \ell\leq 0$. Combined with \eqref{e:system_lowest_outline2}, this gives the 
bounds in the second and third block rows of \eqref{e:mainResult}, 
up to the $L^2$ norm. Finally, to obtain \eqref{e:X+_upgrade_outline} and \eqref{e:Pml_upgrade_outline} in the $H^1_k$ norm, i.e., for $\ell=1$, we use Lemmas \ref{l:highReg} and \ref{l:PMLHighest} which give
\begin{equation}
\label{e:highReg_outline}
X^+(1) \lesssim Z + X^+(0) + (\Hdiag_{\Int,\Int}k)^pX^{-}(-p+1) + R,
\end{equation}
\begin{equation}
\label{e:PMLhighest_outlie}
X^\Pml(1) \lesssim Z + X^\Pml(0) + R.
\end{equation}
The estimates in the $H^1_k$ norm are then obtained by inserting \eqref{e:system_lowest_outline2}, \eqref{e:X+_upgrade_outline}, \eqref{e:Pml_upgrade_outline} into \eqref{e:highReg_outline} and \eqref{e:PMLhighest_outlie}. 


\subsection{Localised duality argument}

%In the remainder of \S \ref{sec:proof_realDeal}, we fix a well-behaved finite element $(V_k)_{k>0}$ or order $p$.  

%From now on (i.e., in the rest of \S\ref{sec:mainResult}), we assume that all the assumptions in \S\ref{sec:assumptions} hold, with any constants in these results depending on the constants in these assumptions, namely the constants in 
%Assumptions \ref{ass:cont}--\ref{ass:ell} and Assumptions \ref{ass:ln}--\ref{ass:bn}. 

%In the proof, we use $C$ as a constant, whose value may change from line to line, that depends on the predefined quantities in the order of quantifiers.


The next result %is a central argument of the proof of Theorem \ref{t:theRealDeal}. It 
relates the Galerkin error in some region $A$ of phase-space to (i) the set of local best-approximation errors in subdomains covering $\Omega$ and (ii) the set of local Galerkin errors in these subdomains, modulo a small global term. The subdomain contributions are weighted by ``transfer coefficients'' $\eta_{j \to A}$ that describe the corresponding local behavior of the Helmholtz solution operator. This result is applied several times later in the proof of Theorem \ref{t:theRealDeal}, for special choices of the partition of unity $\{\phi_j\}$ and operators $A$.

\begin{lemma}[Localised duality argument]
	\label{l:localDualityArg}
Given $\mathfrak{c}, \,k_0>0$, there exists $h_0$ such that the following holds. Let $N > 0$ and let
$\{\phi_j\}_{j = 1}^{J}$ and $\{\tilde{\phi}_j\}_{j = 1}^J$ be such that
	\beq\label{e:supportCondition1}
		\phi_j,\tilde{\phi}_j \in C^\infty_c(\R^d,[0,1]), \quad  \quad 
\phi_j \prec_{\mathfrak{c}} \widetilde{\phi}_j,
		\qquad j = 1,\ldots, J, 
\eeq	
and $\sum_{j = 1}^J \phi_j = 1$ on $\Omega$. For any $k > 0$, 
define
	\[h_j := \max \Big\{h_K \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp \tilde{\phi}_j \neq \emptyset\Big\}.\]  
Then there exists $C > 0$ such that for each $\ell\in \{0,\ldots, p-1\}$, for all $k \geq k_0$, $k \notin \mathcal{J}$, with $h\leq h_0$, for all $A : H_k^{-\ell} \to L^2(\Omega)$, for all $u-u_h$ satisfying \eqref{e:Galerkin_ortho}, and for all $w_{h,j} \in V_k, j=1,\ldots,J$,
	\[\begin{split}
		\|A(u-u_h)\|_{L^2} &\leq C\sum_{j = 1}^J \eta_{j \to A}(h_jk)^p  \Bigg((h_jk)^{-p}\|\tilde{\phi}_j(u - w_{h,j})\|_{H^1_k} +\|\tilde{\phi}_j (u - u_h)\|_{H_k^{-N}} \Bigg)\\
		&\qquad+ Ck^{-N}(hk)^{p+\ell + 1} \|A\|_{H_k^{-\ell} \to L^2}\left( \sum_{j=1}^J(hk)^{-p}\|u-w_{h,j}\|_{H^1_k} +\|u - u_h\|_{H_k^{-N}}\right)
	\end{split}\]
	%for all $w_h \in V_k$, 
	where for all $j \in \{1,\ldots,J\}$, 
\beq\label{eq:alphaj}
\eta_{j \to A} := (h_j k)^p \|\tilde{\phi}_j \RPs A^*\|_{L^2 \to L^2} + (h_j k)^{\ell+1} \|\tilde{\phi}_j (\RPd)^* A^*\|_{L^2 \to H_k^{\ell+2}}.
\eeq
\end{lemma}

To prove Lemma \ref{l:localDualityArg} we use the following two lemmas; the first is a localised version of the classic Aubin-Nitsche duality argument applied to the operator $P_k^\sharp$ defined in \eqref{def:aksharp}, and the second is a localised version of the bound on the adjoint-approximability constant from \cite[Theorem 1.7]{GS3} (with similar bounds appearing in \cite{MeSa:10, MeSa:11, ChNi:20, LSW3, LSW4, GLSW1, BeChMe:25}). Recall the definition of $\Pi_k^\sharp$ from Definition \ref{def:ellipticProjection}, and let 
$$\Pi_k : H^1_k \to V_k$$
be the $H^1_k$-orthogonal projection onto $V_k$. 

\begin{lemma}[Localised Aubin-Nitsche argument for $P_k^\sharp$]
	\label{l:localSharp}
	For any $\mathfrak{c} > 0$, there exists $h_0 > 0$ such that the following holds. Let $k_0 > 0$, $N > 0$, $\chi \in C^\infty(\overline{\Omega})$ and $U \subset \overline{\Omega}$ be such that 
	\[
	\supp \chi \subset U, \quad \partial_<(\supp \chi,U) \geq \mathfrak{c},
	\]
	where the notation $\partial_<$ is defined by \eqref{e:def_partial}.
	For any $k > 0$, let
	$$h_U := \max\big\{h_K \,:\, K \in \cT_k,\,\, K \cap U \neq \emptyset\,\big\}.$$
	Then, there exists 
	$C>0$ such that for all 
	$\ell =0\ldots,p-1$, $k \geq k_0$, $h\leq h_0$, and $u \in H^1_k$, 
	\[
	\|\chi  (\Id - \Pi_k^\sharp) u\|_{H_k^{-\ell}} \leq C \left((h_U k)^{\ell+1} + k^{-N} (hk)^{\ell + 1}\right) \|(\Id - \Pi_k)u\|_{H^1_k}.
	\]
\end{lemma}

\begin{proof}
Fix $\mathfrak{c} > 0$, and let $h_0$ be such that $\mathfrak{c} \geq 2\kappa h_0$ 
where $\kappa$ is as in Assumption \ref{ass:ap}. Let 
$N$, $\chi$ and $U$ as in the statement, and
let $C$ denote a generic constant depending only on the previous quantities. Let $\widetilde{\chi} \in C^\infty(\overline{\Omega})$ be such that $\chi \prec_{\mathfrak{c}/2} \widetilde{\chi}$, $\supp \widetilde{\chi} \subset U$, and 
$$\partial_<(\supp \widetilde{\chi},U) \geq \mathfrak{c}/2.$$
Let $\ell \in \{0,\dots,p-1\}$, and let $v \in H_k^{\ell}$ be such that $\|v\|_{H_k^{\ell}} = 1$.

By the Definition of $\Pi_k^\sharp$ (Definition \ref{def:ellipticProjection}), for all $w_{h,1},w_{h,2} \in V_k$, letting $w_h := w_{h,1} + w_{h,2}$, 
\begin{align}\nonumber
\big|\langle v, \chi (\Id - \Pi_k^\sharp)u\rangle\big| &= \big|\langle \chi v, (\Id - \Pi_k^\sharp) u\rangle\big|\\\nonumber
 &= \big|\langle P_k^\sharp (R_k^\sharp \chi v - w_h), (\Id - \Pi_k^\sharp) u\rangle\big|\\\nonumber
& \leq C\|R_k^\sharp \chi v - w_h\|_{H^1_k} \|(\Id - \Pi_k^\sharp) u\|_{H^1_k}\\
& \leq C \left(\|\widetilde{\chi} R_k^\sharp \chi v - w_{h,1}\|_{H^1_k} + \|(1 - \widetilde{\chi})R_k^\sharp \chi v - w_{h,2}\|_{H^1_k}\right) \inf_{w_h \in V_k} \|u - w_h\|_{H^1_k},\label{e:TGV}
\end{align}
where we used Céa's lemma for the coercive operator $P_k^\sharp$ in the last step. By the approximation property of $V_k$ (Assumption \ref{ass:ap}), $w_{h,1},w_{h,2} \in V_k$ can be chosen such that 
$$\sum_{K \in \cT_k} (h_K k)^{2 - 2(\ell + 2)} \|\widetilde{\chi} R_k^\sharp \chi v - w_{h,1}\|^2_{H^1_k(K)} \leq C \|\widetilde{\chi} R_k^\sharp \chi v\|_{H_k^{\ell+2}}^2\,,$$
$$\sum_{K \in \cT_k} (h_K k)^{2 - 2(\ell + 2)} \|(1-\widetilde{\chi}) R_k^\sharp \chi v - w_{h,2}\|^2_{H^1_k(K)} \leq C \|(1-\widetilde{\chi})R_k^\sharp \chi v\|_{H_k^{\ell+2}}^2\,,$$
with in addition $\supp w_{h,1} \subset U$. In this case, by the definition of $h_U$ and $h$,  
\begin{equation}
\label{e:loc_ba}
\|\widetilde{\chi} R_k^\sharp \chi v - w_{h,1}\|_{H_k^{1}} \leq C (h_U k)^{\ell + 1} \|\widetilde{\chi} R_k^\sharp \chi v\|_{H_k^{\ell+2}}, \quad \tand
\end{equation}
\begin{equation}
\label{e:glob_ba}
\|(1-\widetilde{\chi}) R_k^\sharp \chi v - w_{h,1}\|_{H_k^{1}} \leq C (hk)^{\ell+ 1}\|(1-\widetilde{\chi}) R_k^\sharp \chi v\|_{H_k^{\ell+2}}.
\end{equation}
Using \eqref{e:loc_ba} and \eqref{e:glob_ba} in \eqref{e:TGV} and the estimates 
$$\|\widetilde{\chi} R_k^\sharp \chi v\|_{H_k^{\ell+2}} \leq C\|R_k^\sharp v\|_{H_k^{\ell + 2}} \leq C \|v\|_{H_k^{\ell}}\,,$$
(by the mapping properties of $R_k^\sharp$, Proposition \ref{prop:ResPksharp}) and 
$$\|(1-\widetilde{\chi}) R_k^\sharp \chi v\|_{H_k^{\ell+2}} \leq C\|R_k^\sharp v\|_{H_k^{\ell + 2}} \leq C k^{-N}\|v\|_{H_k^{\ell}}\,,$$
(by pseudo-locality of $R_k^\sharp$, Theorem \ref{t:pseudoLocGeneral}), we obtain
$$\big|\langle v, \chi (\Id - \Pi_k^\sharp) u\rangle\big| \leq C \big( (h_Uk)^{\ell+1}+ k^{-N}(hk)^{\ell+1}\big) \inf_{w_h \in V_k}\|u - w_h\|_{H^1_k}$$
and the conclusion follows by taking the supremum over $v$.
