Lemma \ref{l:localSharp} has the following special case when $\chi \equiv 1$ on $\overline{\Omega}$:
\begin{corollary}
	\label{l:AubinNitsche}
Given $k_0>0$, there exists $C>0$ such that for all $\ell\in \{0,\ldots, p-1\}$, and for all $u \in H_k^{\ell} \cap \cZ_k$,
	\[\|(\Id - \Pi_k^\sharp) u\|_{H_k^{-\ell}} \leq C(hk)^{\ell-1}\|(\Id - \Pi_k)u\|_{H^1_k}.\]
\end{corollary}

\begin{definition}[Localised adjoint-approximability constant]
\label{def:eta_microlocal}
For $A: H_k^{-\ell} \to L^2$ and $\phi \in C^\infty(\overline{\Omega})$, define 
the {\em localised adjoint-approximability constant} associated to $\phi$ and $A$ as
$$\eta(\phi \to A) := \|(\Id-\Pi_k)\phi R_k^* A^*\|_{L^2 \to H^1_k}.$$
%$$\eta(\phi\to A) := \sup_{f \in L^2} \inf_{w_h \in V_k} \frac{\|(\phi R_k^* A^*) f - w_h\|_{H^1_k}}{\|f\|_{L^2}}$$
\end{definition}

\begin{lemma}[Bound on $\eta(\phi \to A)$]
\label{l:bound_eta_microlocal}
For all $k_0 > 0$ and $\mathfrak{c}> 0$, there exists $h_0 > 0$ such that, for all $N > 0$, $\phi,\widetilde{\phi} \in C^\infty(\overline{\Omega})$ with $\phi_j \prec_{\mathfrak{c}} \tilde{\phi}$, there exists $C > 0$ such that for all $h \leq h_0$, for all $k \geq k_0$, and for all $A : H_k^{-\ell}\to L^2$,
$$\eta(\phi \to A) \leq C \Big((h_{\tilde{\phi}} k)^{p}\|\tilde{\phi}R_k^* A^*\|_{L^2 \to L^2} + (h_{\tilde{\phi}} k)^{\ell + 1} \|\phi (R_k^\sharp)^* A^*\|_{L^2 \to H_k^{\ell + 2}} + (hk)^p k^{-N}\Big),$$
where $h_{\tilde{\phi}} :=\max \Big\{h_K \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp \tilde{\phi} \neq \emptyset\Big\}$.
\end{lemma}

\begin{proof}
Let $k_0, \mathfrak{c} > 0$ and let $h_0 > 0$ be such that $\mathfrak{c} \geq \kappa h_0$ where $\kappa$ is as in Assumption \ref{ass:ap}. Let $N > 0$, $\phi, \widetilde{\phi}$ be as in the statement. Let $\check{\phi} \in C^\infty(\overline{\Omega})$ be such that $\phi \prec \check{\phi} \prec \widetilde{\phi}$. Let $C$ denote a generic positive constant depending only on the previous quantities.
%Let $\Pi_k$ be the $H^1_k$-orthogonal projection onto $V_k$. Then
%$$\eta(\phi \to A) = \|(\Id-\Pi_k)\phi R_k^* A^*\|_{L^2 \to H^1_k}.$$
Since $(P_k^\sharp)^* =  P_k^* + S_k$, applying $(R_k^\sharp)^*$ to the left, and then $R_k^*$ to the right, we obtain that
\begin{equation}
	\label{e:EuanFavForm2}
	R_k^* =   (R_k^\sharp)^* + (R_k^\sharp)^* S_k R_k^*.
\end{equation}
Thus
\begin{align}\nonumber
\eta(\phi \to A) &\leq \|(\Id - \Pi_k) \phi (R_k^{\sharp})^* A^*\|_{L^2 \to H^1_k} + \|(\Id - \Pi_k)\phi (R_k^\sharp)^*S_k R_k^* A^*\|_{L^2 \to H^1_k}\\
& \leq C (h_{\tilde{\phi}} k)^{\ell +1}\|\phi (R_k^\sharp)^* A^*\|_{L^2 \to H_k^{\ell+2}} + C(h_{\tilde{\phi}} k)^p\|\phi (R_k^\sharp)^* S_k R_k^* A^*\|_{L^2 \to H_k^{p+1}}
\label{e:split_eta}
\end{align}
by the approximation property of $V_k$ (Assumption \ref{ass:ap}), which can be applied since $\phi R_k^\sharp$ maps $L^2$ into $\cZ_k$ (i.e., $\phi R_k^\sharp$ satisfies a 
zero Dirichlet boundary condition on $\Gamma_{\rm tr}$ and, if necessary, also on $\partial\Omega_-$). Finally, one can use pseudolocality of $(R_k^\sharp)^*$ and $S_k$ (Theorem \ref{t:pseudoLocGeneral}) to ``move $\phi$ to the right of $S_k$'' in the second term, as follows
\begin{align}\nonumber
\phi (R_k^\sharp)^* S_k &= \phi (R_k^\sharp )^* S_k\widetilde{\phi} + \phi (R_k^\sharp)^* S_k(1 - \widetilde{\phi})\\\nonumber
& = \phi (R_k^\sharp)^* S_k\widetilde{\phi} + \phi (R_k^\sharp)^* [\check{\phi} S_k(1 - \widetilde{\phi})]
+  \phi [(R_k^\sharp)^* (1 -\check{\phi})] S_k(1 - \widetilde{\phi}) \\ \nonumber
& = \phi (R_k^\sharp )^* S_k\widetilde{\phi} + \phi (R_k^\sharp)^* O_{-\infty}(k^{-\infty};\cY_k \to \cY_k) + O_{-\infty}(k^{-\infty};\cY_k \to \cY_k) S_k(1 - \widetilde{\phi})\\
& = \phi (R_k^\sharp )^* S_k\widetilde{\phi} + O_{-\infty}(k^{-\infty};\cY_k \to \cY_k),
\label{e:moved_to_the_right}
\end{align}
using the mapping properties of $S_k$ (Proposition \ref{prop:f(Pk)}) and of $R_k^\sharp$ (Proposition \ref{prop:ResPksharp}). Inserting \eqref{e:moved_to_the_right} into \eqref{e:split_eta} and using the continuity of $R_k^\sharp$ from $H_k^{p-1}$ to $H_k^{p+1}$ (Proposition \ref{prop:ResPksharp}) and of $S_k$ from $L^2 \to H_k^{p-1}$ (Proposition \ref{prop:f(Pk)}), the result follows.
\end{proof}

