\begin{proof}[Proof of Lemma \ref{l:localDualityArg}]
Let $\mathfrak{c},k_0 > 0$, and let $h_0 > 0$ be small enough to apply Theorem \ref{t:pseudoLocalPi}, Lemma \ref{l:localSharp} and Lemma \ref{l:bound_eta_microlocal}. Fix $\{\phi_j\}_{j = 1}^J$, $\{\tilde{\phi}_j\}_{j = 1}^J$ as in the statement, and let $N > 0$. Let $C$ denote a generic constant (whose value may change from line to line) depending only on the previous quantities. Let $k \geq k_0$ with $k \notin \mathcal{J}$. By Assumption \ref{a:polyBound}, there exists $N' > 0$ such that 
\begin{equation}
\label{e:defN'}
k^{-N'}\rho(k) \leq  Ck^{-N}.
\end{equation}
	Let $v \in L^2$ with $\|v\|_{L^2} = 1$. Arguing as in \eqref{e:startDuality}, we obtain that, 	for all $w_{h,j} \in V_k$, $j=1,\ldots,J$,
		\begin{equation}
		\label{eq:dismantled}
		\begin{split}
			%\|A(u-u_h)\|_{L^2}^2 
			\big\langle A(u-u_h),v\big\rangle& = \sum_{j = 1}^J \big\langle u-w_{h,j} , (P_k^\sharp)^*  (\Id - \Pi_k^\sharp) \phi_j \RPs A^* v \big\rangle - \sum_{j = 1}^J \big\langle u-u_h ,   S_k (\Id - \Pi_k^\sharp) \phi_j \RPs A^* v \big\rangle.\end{split}
	\end{equation}
 % recalling that $S_k = P_k^\sharp - P_k = \psis(\cP_k)$.
%	where $\widetilde{S}_k = \widetilde{\psi}(\cP_k)$, with $\widetilde{\psi} \in C^\infty_c(\R)$ such that $\supp(1 - \widetilde{\psi}) \cap \supp \psi = \emptyset$ (thus ensuring that $S_k = \widetilde{S}_k S_k$). 
The plan is to use the pseudo-locality properties of $(P_k^\sharp)$, $S_k$ and $(\Id - \Pi_k^\sharp)$ shown in Sections \ref{sec:pseudolocS}-\ref{sec:pseudoLocPi}, 
to show that, up to small remainders, 
$$P_k^\sharp (\Id - \Pi_k^\sharp)\phi_j \approx \widetilde{\phi}_j  P_k^\sharp \check\phi_j (\Id - \Pi_k^\sharp)\phi_j \quad \tand\quad S_k(\Id - \Pi_k^\sharp)\phi_j \approx \widetilde{\phi}_j S_k \check\phi_j (\Id - \Pi_k^\sharp)\phi_j\,,$$
where $\check\phi_{j} \in C^\infty_c(\R^2,[0,1])$ is such that
\[
\phi_j \prec_{\mathfrak{c}/4} \check\phi_j \prec_{\mathfrak{c}/4} \widetilde{\phi}_j \quad \tfa j \in \{1,\ldots,J\}.
\]
To achieve this, we rewrite the difference as
\begin{equation}
	\label{eq:idDoublePseudoLoc}
	X(\Id - \Pi_k^\sharp)\phi_j  -\widetilde{\phi}_j X \check\phi_j (\Id - \Pi_k^\sharp)\phi_jv  = X (1-\check\phi_j)(\Id - \Pi_k^\sharp) \phi_j + (1 - \widetilde{\phi}_j) X \check\phi_j (\Id - \Pi_k^\sharp) \phi_j,
\end{equation}
where $X$ is either $(P_k^\sharp)^*$
or $S_k$.
First, when $X = S_k$, \eqref{eq:idDoublePseudoLoc} gives,
for all $w \in H_k^{\ell+2} \cap \cZ_k$, 
	\begin{align}\nonumber
			&\|S_k(\Id - \Pi_k^\sharp) \phi_jw - \widetilde{\phi}_j S_k \check\phi_j (\Id - \Pi_k^\sharp)\phi_j w\|_{H_k^N} \\ \nonumber
			& \qquad \leq \|S_k\|_{H_k^{1}\to H_k^N} \|(1-\check\phi_j)(\Id - \Pi_k^\sharp) \phi_j w\|_{H_k^{1}} +  \|(1 -\widetilde{\phi}_j) S_k \check\phi_j \|_{H_k^{-p} \to H_k^N} \|(\Id - \Pi_k^\sharp)\phi_jw\|_{H_k^{-p}} \\ \nonumber
			& \qquad\leq Ck^{-N'}\|(\Id - \Pi_k^\sharp)\phi_jw\|_{H_k^{-p}} \qquad \text{ (by Theorem \ref{t:pseudoLocalPi} and \eqref{eq:pseudoloc1} of Theorem \ref{thm:pseudolocSpace})} \\ \nonumber
			& \qquad\leq C k^{-N'} \|(\Id - \Pi_k^\sharp)\phi_jw\|_{H_k^{-p+1}}\\
			& \qquad \leq Ck^{-N'} (hk)^{p+\ell+1} \| w\|_{H_k^{\ell+2}} \qquad\text{ (by Corollary \ref{l:AubinNitsche})},
					\label{eq:sicily1}
	\end{align}
	where the condition that $w \in \cZ_k$ is need to apply Corollary \ref{l:AubinNitsche}.
In particular, taking $w = R_k^* A^* v$, \eqref{eq:sicily1} gives
	\begin{align}\nonumber
		&\Big\|\Big(S_k(\Id - \Pi_k^\sharp) \phi_j - \widetilde{\phi}_j S_k \check\phi_j (\Id - \Pi_k^\sharp)\phi_j \Big) R_k^* A^*v\Big\|_{H_k^N}
		\\ \nonumber
		&\hspace{5cm} \leq Ck^{-N'}(hk)^{p+\ell+1}\big(1+\rho(k)\big)\|A^*\|_{L^2 \to H_k^\ell}\|v\|_{L^2}\\
		&\hspace{5cm}\leq Ck^{-N}(hk)^{p+\ell+1}\|A^*\|_{L^2 \to H_k^\ell}\label{eq:aloeVera1}
	\end{align}
using the mapping properties of $R_k^*$ from Proposition \ref{prop:Rstar} and the definition of $N'$ in \eqref{e:defN'}.

Similarly, when $X = P_k^\sharp$, \eqref{eq:idDoublePseudoLoc} gives
\begin{align}\nonumber
			&\|(P_k^\sharp)^*(\Id - \Pi_k^\sharp) \phi_jw - \widetilde{\phi}_j (P_k^\sharp)^* \check\phi_j (\Id - \Pi_k^\sharp)\phi_j w\|_{H_k^{-1}} \\ \nonumber
			&\qquad \leq \|P_k^{\sharp}\|_{H^1_k\to H^{-1}_k} \|(1 - \check\phi_j) (\Id - \Pi_k^\sharp) \phi_j w\|_{H^1_k} + \|(1 - \widetilde{\phi}_j) (P_k^\sharp)^* \check\phi_j\|_{H_k^1 \to H_k^{-1}} \|(\Id - \Pi_k^\sharp) \phi_j w\|_{H^1_k} \\ \nonumber
			& \qquad \leq C k^{-N'} \|(\Id - \Pi_k^\sharp) \phi_jw\|_{H_k^{-p}} + Ck^{-N} (hk)^{\ell + 1} \|w\|_{H_k^{\ell+2}}\\ \nonumber
			&\hspace{4cm}
			\text{ (by Theorem \ref{t:pseudoLocalPi},  \eqref{eq:pseudoloc1} of Theorem \ref{thm:pseudolocFreq}, and Assumption \ref{ass:ap})} 
			 \\
			& \qquad \leq Ck^{-N'} \big((hk)^{p+\ell+1}+(hk)^{\ell + 1}\big)\|w\|_{H_k^{\ell+2}},\qquad\text{ (by Corollary \ref{l:AubinNitsche}).}	\label{eq:sicily2}
	\end{align}
Choosing again $w = R_k^* A^* v$ in \eqref{eq:sicily2},
 	\begin{align}\nonumber
& 		\Big\|\Big((P_k^\sharp)^*(\Id - \Pi_k^\sharp) \phi_j - \widetilde{\phi}_j (P_k^\sharp)^* \check\phi_j (\Id - \Pi_k^\sharp)\phi_j \Big)
		 R_k^* A^* v
		\Big\|_{H_k^{-1}} \\
		&
		\hspace{5cm}\leq Ck^{-N}(hk)^{\ell + 1} \|A^*\|_{L^2 \to H_k^\ell} \|v\|_{L^2}.
		 		\label{eq:aloeVera2}
 	\end{align}
Therefore, by the combination of \eqref{eq:dismantled}, \eqref{eq:aloeVera1} and \eqref{eq:aloeVera2},  
\begin{align}
\nonumber
&%\|A(u-u_h)\|^2_{L^2} 
\Big|\big \langle A(u-u_h),v\big\rangle\Big|\\
\nonumber
&\leq C\Bigg(\sum_{j = 1}^{J} \abs{\big\langle u - w_{h,j} , \widetilde{\phi}_j (P_k^\sharp)^* \check\phi_j (\Id - \Pi_k^\sharp) \phi_j R_k^* A^* v\big\rangle} +  \sum_{j = 1}^{J} \abs{\big\langle u - u_h , \widetilde{\phi}_j S_k \check\phi_j (\Id - \Pi_k^\sharp) \phi_j R_k^* A^* v \big\rangle} +  R\Bigg),\\
&=C\Bigg(\sum_{j = 1}^{J} \abs{\big\langle P_k^\sharp \widetilde{\phi}_j(u - w_{h,j}) ,  \check\phi_j (\Id - \Pi_k^\sharp) \phi_j R_k^* A^* v\big\rangle} +  \sum_{j = 1}^{J} \abs{\big\langle S_k \widetilde{\phi}_j(u - u_h) , \check\phi_j (\Id - \Pi_k^\sharp)\phi_j R_k^* A^* v \big\rangle} +  R\Bigg),
\label{ready_to_go}
\end{align}
 	%where $w_j := \phi_j R_k^{*} A^* A(u-u_h)$,
 where
\begin{equation*}
	\begin{gathered}
%		\label{e:defR}
		R := k^{-N}(hk)^{\ell + 1}\|A^*\|_{L^2\to H_k^\ell} \Big(\sum_{j=1}^J\|u - w_{h,j}\|_{H^1_k} + (hk)^{p} \|u-u_h\|_{H_k^{-N}}\Big)
	\end{gathered}
\end{equation*}
(where we have used that $\|v\|_{L^2} = 1$).	
	Since $a_k^\sharp$ is coercive, Céa's lemma implies that %\eqref{e:PiSharpCea} holds. 
	$$\|(\Id - \Pi_k^\sharp)v\|_{H^1_k} \leq C \|(\Id - \Pi_k)v\|_{H^1_k}.$$
	Therefore, for each $j \in \{1,\ldots,J\}$, 
	\begin{equation}
	\label{eq:I-Piwj}
	\|(\Id - \Pi_k^\sharp)\phi_j R_k^* A^* v\|_{H^1_k} \leq C\eta(\phi_j\to A) \|v\|_{L^2} = C \eta(\phi_j \to A),
	\end{equation}
	where $\eta(\phi_j\to A)$ is the localised adjoint-approximability constant defined in Definition \ref{def:eta_microlocal}. Similarly, by Lemma \ref{l:localSharp} with $\ell = p-1$,  
	\begin{equation}
		\label{eq:I-Piwj_localSharped}
		\|\check{\phi}_j(\Id -\Pi_k^\sharp) \phi_j R_k^* A^* v\|_{H_k^{-p+1}} \leq C \big((h_jk)^p + k^{-N'}(hk)^p\big)\eta(\phi_j\to A) ,
	\end{equation}
By \eqref{eq:I-Piwj}, \eqref{eq:I-Piwj_localSharped} and the mapping properties of $S_k$ (Proposition \ref{prop:f(Pk)}) in \eqref{ready_to_go}, 
	\begin{align*}
		\Big|\big \langle A(u-u_h),v\big\rangle\Big| &\leq C \sum_{j = 1}^J \eta(\phi_j \to A)\Big(\|\widetilde{\phi}_j(u-w_{h,j})\|_{H^1_k}
		+(h_jk)^{p}\|\widetilde{\phi}_j(u-u_h)\|_{H^{-N}_k}\Big)+ C(R + R')
	\end{align*}
	where $R' = k^{-N}(hk)^{p} (\sum_{j=1}^J\|u-w_{h,j}\|_{H^1_k} + (hk)^{p}\|u-u_h\|_{H_k^{-N}})$, using the fact that $R_k^*$, and thus $\eta(\phi_j \to A)$, are polynomially bounded on $\R_+\setminus \mathcal{J}$, thanks to Assumption \ref{a:polyBound} and Proposition \ref{prop:Rstar} (while $R_k^\sharp$ is bounded by Proposition \ref{prop:ResPksharp}). The result then follows by using Lemma \ref{l:bound_eta_microlocal} to estimate the constants $\eta(\phi_j \to A)$, and taking the supremum over $v$.
\end{proof}

\subsection{Improvements at high frequency and in the PML region}

We now use the improved behavior of the resolvent on (i) high-frequency functions and (ii) functions localised in the PML region to improve Lemma \ref{l:localDualityArg}.

\ble[Improvement of $R_k^*$ on high-frequencies]\label{l:bigScreen}
%(i) 
Let $\psi\in C_c^\infty(\mathbb{R})$ satisfy $\psi^\sharp \prec \psi$ and let $\Psi := \psi(\cP_k)$ and let $\varphi\in C^\infty(\overline{\Omega})$ be such that 
$\supp \varphi \cap \Gamma_{\tr} = \emptyset$. Then 
$$
R_{k}^* (1 - \Psi) \varphi = (R_{k}^\sharp)^* (1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}).
$$
\ele

\bpf
We use again the resolvent identity \eqref{e:EuanFavForm2} 
to write
\beqs
R_k^* (1 - \Psi)  =  (R_{k}^\sharp)^* (1 - \Psi) +R_k^* S_k (R_{k}^\sharp)^*  (1 - \Psi).
\eeqs
The idea is to now use pseudolocality of $(R_{k}^\sharp)^*$ to move $(1 - \Psi)$ next to $S_k$, with this product then zero since $\psi^\sharp(1-\psi)=0$. 
The issue is that we have only shown that $(R_k^\sharp)^*$ is pseudolocal with respect to frequency cut-offs when sandwiched by appropriate spatial cut offs -- see 
Lemma \ref{lem:huge_whiteboard1} 
 and Theorem \ref{thm:pseudolocFreq}.

To this end, let $\varphi_{\Pml,1},\varphi_{\Pml,2} \in C^\infty(\overline{\Omega})$ be such that
$\varphi \prec \varphi_{\Pml,1} \prec \varphi_{\Pml,2}$, and 
\beq\label{e:cutoffPML}
\supp (\varphi_{\Pml,2})\cap \Gamma_{\tr}=\emptyset\quad \tand \quad \supp(1- \varphi_{\Pml,1}) \cap \partial \Omega_- =\emptyset.
\eeq
By Lemma~\ref{t:pseudoLocGeneral} applied to both $(1-\Psi)$ and $(R_{k}^\sharp)^*$,
\begin{align*}
	R_k^* S_k (R_{k}^\sharp)^*  (1 - \Psi)\varphi
	&=R_k^* S_k (R_{k}^\sharp)^* \varphi_{\Pml,1} (1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{})\\
	&=R_k^* S_k \varphi_{\Pml,2}(R_{k}^\sharp)^*  \varphi_{\Pml,1} (1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}),\\
	&=R_k^* S_k \varphi_{\Pml,2}(R_k^\sharp)^*\varphi_{\Pml,2}  \varphi_{\Pml,1} (1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}),\\
	&=R_k^* S_k \big(\varphi_{\Pml,2}(R_k^\sharp)^*\varphi_{\Pml,2} \big) (1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}).
\end{align*}
By Lemma \ref{lem:huge_whiteboard1}
(with $\varphi=\varphi_{\Pml,2}$) 
$\varphi_{\Pml,2}(R_k^\sharp)^*  \varphi_{\Pml,2}\in \cL^{\rm f}_{-2}$. Thus
by Theorem~\ref{thm:pseudolocFreq}, with $\psi^\sharp \prec \widetilde\psi\prec \psi$,  
		\begin{align*}
		R_k^* S (R_k^\sharp)^*  (1 - \Psi)\varphi
				&=R_k^* S \varphi_{\Pml,2}(R_k^\sharp)^*  \varphi_{\Pml,2}(1 - \Psi)\varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{})\\
				&=R_k^* S (1 - \widetilde\Psi)\varphi_{\Pml,2}(R_k^\sharp)^*  \varphi_{\Pml,2} (1 - \Psi) \varphi +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{})\\
		&=		O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}),
		\end{align*}
		where we have used that 
		\beqs%\label{e:weirdFormat1}
		O_{-\infty}(k^{-\infty};\Dspace{}\to\Dspace{})=O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}),
		\eeqs
		 since, for any $n\in \mathbb{Z}$, $\Dspace{|n|}\subset \ZcupHspace{n}\subset \Dspace{-|n|}$ with continuous inclusions (by Corollary \ref{cor:DnsubZn}).
\epf

\begin{lemma}[High-frequency upgrade]
\label{l:highFreqUpgrade}
For any $\mathfrak{c}, \,k_0$, there exists  $h_0$ such that the following is true.
Let $N > 0$, let $\psi\in C_c^\infty(\mathbb{R})$ satisfy $\psi^\sharp \prec \psi$ and let $\Psi := \psi(\cP_k)$. Let 
$\phi,\widetilde{\phi} \in C^\infty(\overline{\Omega})$ be such that $\phi \prec_\mathfrak{c} \tilde{\phi}$ and $\supp \widetilde{\phi} \cap \Gamma_{\rm tr} = \emptyset$. 
Then there exists $C > 0$ such that 
for all $\ell\in \{0,\ldots, p-1\}$, for 
%$1\leq m\leq p+1$, 
all $k \geq k_0$, $k \notin \mathcal{J}$, $h\leq h_0$ and $w_h \in V_k$,
\begin{align}\nonumber
&\|\phi(1-\Psi)(u-u_h)\|_{H_k^{-\ell}}\\ \nonumber
&\leq C(h_{\tilde\phi} k)^{p+\ell+1}\Big((h_{\tilde\phi} k)^{-p}\|\widetilde{\phi}(u-w_h)\|_{H_k^1}+\|\widetilde{\phi}\Psi(u-u_h)\|_{H_k^{-N}}+(h_{\tilde\phi}k)^N\|\widetilde{\phi}(1-\Psi)(u-u_h)\|_{H_k^{-N}}\Big)\\ \label{e:highFreqUpgrade}
&\qquad +Ck^{-N}(hk)^{p+\ell+1}\Big((hk)^{-p}\|u-w_h\|_{H_k^1}+\|u-u_h\|_{H_k^{-N}}\Big),
\end{align}
where $
	h_{\tilde\phi} := \max \big\{\diam(K) \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp \widetilde{\phi} \neq \emptyset\big\}.$
%	Then, for each $\ell\in \{0,\ldots, p-1\}$, for all $k \geq k_0$, $h\leq h_0$, all operators $A: H_k^{-\ell} \to L^2$ and 
\end{lemma}

We highlight that the advantage of \eqref{e:highFreqUpgrade} over the bound in Lemma \ref{l:localDualityArg} is the arbitrary power $N$ in the term $(h_{\tilde\phi}k)^N\|\widetilde{\phi}(1-\Psi)(u-u_h)\|_{H_k^{-N}}$.
%The bound \eqref{e:highFreqUpgrade} with $(h_{\tilde\varphi}k)^N$ replaced by $(h_{\tilde\varphi}k)^p$ follows immediately from Lemma \ref{l:localDualityArg}; the 

\

\begin{proof}[Proof of Lemma \ref{l:highFreqUpgrade}]
Let $\mathfrak{c} > 0$, $k_0 > 0$. Let $c \in (0,\mathfrak{c})$ be arbitrary and let $h_0$ be small enough to apply Lemma \ref{l:localDualityArg} with $\mathfrak{c} = c$. Let $N$, $\psi$, $\phi$ and $\widetilde{\phi}$ as in the statement, and let $\chi, \widetilde{\chi} \in C^\infty(\overline{\Omega})$ be any cutoff functions chosen such that $\chi \prec_c \widetilde{\chi}$ and $\supp \widetilde{\chi} \cap \Gamma_{\rm tr} = \emptyset$. Denote by $C$ any positive constant whose value depends only on the previous quantities. Then, given $k \geq k_0$, $k \notin \mathcal{J}$, $h \leq h_0$ and $w_h \in V_k$,
it is enough to show that %$\AtForty$ $\NoIroning$
%\beqs
%$\partial_<( \supp {\varphi},\supp (1 - \widetilde{\varphi}) \geq \mathfrak{c}$
\begin{align}\nonumber
&\|\chi(1-\Psi)(u-u_h)\|_{H_k^{-\ell}}\\\nonumber
&\leq C(h_{\tilde\chi} k)^{\ell+1}\Big(\|\widetilde{\chi}(u-w_h)\|_{H_k^1}+(h_{\tilde\chi}k)^p\|\widetilde\chi\Psi(u-u_h)\|_{H_k^{-N}}+(h_{\tilde\chi}k)^p\|\widetilde\chi(1-\Psi)(u-u_h)\|_{H_k^{-N}}\Big)\\
&\qquad +Ck^{-N}(hk)^{\ell+1}\Big(\|u-w_h\|_{H_k^1}+(hk)^p\|u-u_h\|_{H_k^{-N}}\Big).\label{eq:sufficientInduct1}
\end{align}
where $h_{\tilde{\chi}}$ is defined analogously to $h_{\tilde{\phi}}$. Indeed, one can then apply \eqref{eq:sufficientInduct1} iteratively with a sequence of cut-offs appropriately nested between $\phi$ and $\widetilde\phi$.

Let $\check\chi,\hat\chi$ be such that 
$\chi\prec_{c/4}\check\chi\prec_{c/4} \hat\chi\prec_{c/4}\widetilde\chi$. 
We apply Lemma~\ref{l:localDualityArg} with %$\ell=\newell-1$, 
$A=E_\ell\chi(1-\Psi)$, where $E_\ell:H_k^{-\ell}\to L^2$ an isomorphism, with 
$\{\phi_j\}_{j = 1}^{2} := \{ \hat{\chi},1-\hat{\chi}\}$ 
%$\phi_1=\hat{\chi}$, $\phi_2=(1-\hat\chi)$ 
(i.e., only two functions in the partition of unity)
and $\{\tilde\phi_j\}_{j = 1}^2=\{ \widetilde\chi,1- \check\chi\}$. 
%$\tilde{\phi}_1=\widetilde\chi$, and $\tilde{\phi}_2=(1-\chi))$. 
Then, by Lemma \ref{l:bigScreen} (since $\supp\chi\cap \Gamma_\tr=\emptyset$),
$$
\|\widetilde{\chi}R_k^*A^*\|_{L^2\to L^2} \leq \|\widetilde{\chi}(R^\sharp_k)^*A^*\|_{L^2\to L^2}+C k^{-N}
$$
and 
$$
\|(1-\check\chi)R_k^*A^*\|_{L^2\to L^2}\leq\|(1-\check\chi)(R^\sharp_k)^*A^*\|_{L^2\to L^2}+Ck^{-N}.
$$
Moreover, by Theorem~\ref{t:pseudoLocGeneral}, 
\beqs
\|(1-\check\chi)(R^\sharp_k)^*A^*\|_{L^2\to H_{k}^{\ell+2}} \leq Ck^{-N}
\eeqs
and by Proposition~\ref{prop:ResPksharp}
\beqs
\|\widetilde\chi(R^\sharp_k)^*A^*\|_{L^2\to H_{k}^{\ell+2}}\leq C.
\eeqs
Therefore, with $\eta_{j \to A}$ defined by \eqref{eq:alphaj},
\beqs
\eta_{1\to A} \leq C \Big( 
(h_{\tilde\chi}k)^p\|\widetilde\chi R_k^*A^*\|_{L^2\to L^2}+(h_{\tilde\chi}k)^{\ell+1}\|\widetilde\chi(R^\sharp_k)^*A^*\|_{L^2\to H_{k}^{\ell+2}}\Big)\leq C(h_{\tilde\chi}k)^{\ell+1},
\eeqs
and $\eta_{2\to A}\leq C k^{-N}(hk)^{\ell+1}$.
Lemma \ref{l:localDualityArg} thus gives 
\begin{align*}
\|\chi(1-\Psi)(u-u_h)\|_{H_k^{-\ell}}&\leq (h_{\tilde{\chi}} k)^{\ell+1}C\Big(\|\widetilde{\chi}(u-w_h)\|_{H_k^1}+(h_{\tilde{\chi}}k)^p\|\widetilde{\chi}(u-u_h)\|_{H_k^{-N}}\Big)\\
&\qquad\qquad+ Ck^{-N}(hk)^{\ell+1}\Big(\|u-w_h\|_{H_k^1}+(hk)^{p}\|u-u_h\|_{H_k^{-N}}\Big),
\end{align*}
and \eqref{eq:sufficientInduct1} follows using $\|\widetilde{\chi}(u-u_h)\|_{H_k^{-N}} \leq  \| \widetilde{\chi}\Psi(u-u_h)\|_{H_k^{-N}} + \|\widetilde{\chi}(1 - \Psi)(u-u_h)\|_{H_k^{-N}}$.
\end{proof}

Recall from \S\ref{sec:state_main_result} that $U_{\Pml}$ is a neighbourhood of $\Gamma_{\tr}$ such that Theorem~\ref{thm:PML} holds on $U_{\Pml}$.

\begin{lemma}[PML upgrade]
\label{l:PMLUpgrade}
For any $\mathfrak{c}, \,k_0$, there exists $h_0 > 0$ such that the following is true. Let $N > 0$, let $\psi \in C^\infty_c(\R)$, let $\Psi := \psi(\cP_k)$, and let $\phi,\widetilde{\phi}\in C^\infty(\overline{\Omega})$ be such that 
$\phi \prec_{\mathfrak{c}} \widetilde{\phi}$ and $\supp \widetilde\phi \subset U_{\Pml}$. Then there exists $C > 0$ such that, for all $\ell\in \{0,\ldots, p-1\}$, 
$k \geq k_0$, $k \notin \mathcal{J}$, $h\leq h_0$ and $w_h \in V_k$,
\begin{align*}
&\|\phi\Psi (u-u_h)\|_{H_k^{-\ell}} + \|\phi(1 - \Psi) (u-u_h)\|_{H_k^{-\ell}}\\
&\hspace{2cm} \leq C(h_{\tilde\phi} k)^{p+\ell+1}\Big((h_{\tilde{\phi}}k)^{-p}\|\widetilde{\phi}(u-w_h)\|_{H_k^1}+(h_{\tilde\phi}k)^N\|\widetilde{\phi}(u-u_h)\|_{H_k^{-N}}\Big)\\
&\hspace{5cm}+Ck^{-N}(hk)^{p+\ell+1}\Big((hk)^{-p}\|u-w_h\|_{H_k^1}+\|u-u_h\|_{H_k^{-N}}\Big),
\end{align*}
where $h_{\tilde\phi} := \max \Big\{\diam(K) \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp \widetilde{\phi} \neq \emptyset\Big\}$.
\end{lemma}

\begin{proof}
We proceed as in the proof of Lemma \ref{l:highFreqUpgrade}, with $A=E_\ell \chi \Psi$ or $A = E_\ell \chi (1 - \Psi)$, but this time, the 
terms $\eta_{j \to A}$ in Lemma \ref{l:localDualityArg} are bounded by first using pseudolocality of $\Psi$ (or $1 - \Psi$) to write
$$R_k^*\Psi \chi  = R_k^* \underline{\chi} \Psi \chi + O_{-\infty}(k^{-\infty};\cY_k \to \cY_k),$$
where $\chi \prec \underline{\chi} \prec \check{\chi}$. The conclusion is then obtained from
$$
\|(1-\check\chi) R_k^* \underline{\chi}\|_{L^2\to L^2} \leq Ck^{-N} \quad\tand\quad \|\widetilde\chi R_k^* \underline{\chi}\|_{L^2\to L^2}\leq C,
$$
with these bounds following from Theorem~\ref{thm:PML}, since $1 - \check{\chi} \perp \underline{\chi}$ and $\supp \widetilde{\chi}\subset U_{\Pml}$. 
\end{proof}


\bre
The iteration in the proofs  of Lemmas \ref{l:highFreqUpgrade} and  \ref{l:PMLUpgrade} is possible because the $\eta_{j \to A}$ are small, precisely because of the ``good" behaviour of the solution operator on high frequencies/in the PML, respectively. 
\ere



