which gives the first block row  of \eqref{e:system} (where here, and in the rest of the proof, we use the convention that a vector plus a scalar is the vector obtained by adding the scalar to every entry). 
To do this, we estimate $X^-$ (defined by \eqref{e:defX})
$$X^- \leq X^{\circ,-} + X^{\x,-}$$
where $X^{-,\circ} := \|\chi_i^\circ \Psi(u-u_h)\|_{H_k^{-p+1}}$ and $X^{-,\x} := \|\chi_i^\x \Psi(u-u_h)\|_{H_k^{-p+1}}$.\footnote{Without this splitting, one only gets $\Hmin_{\Int,\Pml}(2p) k^{2p}$ instead $\Hmin_{\Int,\Pml}(N) k^{N}$ in the third block of the first matrix in the right-hand side of \eqref{e:mainBoundX-}.} We estimate $X^{-,\circ}$ and $X^{-,\x}$ separately. 

{\em Bound on $X^{\circ,-}$.} The main work is to bound $X^{\circ,-}$.  
%\begin{equation*}
%\begin{array}{rcl}
%X^{\circ,-} &\leq& 
%C
%\begin{pmatrix}
%\mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & \mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & 0
%\end{pmatrix} X 
%+ C
%\begin{pmatrix}
%\mathcal{C} (\Hdiag_{\Int,\Int} k)^{p} & 0
%\end{pmatrix} Z+ R\\
%X^{\x,-} &\leq &
%C
%\begin{pmatrix}
%\mathcal{C} \Hmin_{\Int,\Int}(N) k^{N} &\Hmin_{\Int,\Int}(N) k^{N} & \Hmin_{\Int,\Pml}(N) k^{N}
%\end{pmatrix} X 
%+ C
%\begin{pmatrix}
%\mathcal{C} (\Hdiag_{\Int,\Int} k)^{p} & 0
%\end{pmatrix} Z+ R
%\end{array}
%\end{equation*}
To this end, we fix $i \in \{1,\ldots,M_\Int\}$ and apply Lemma \ref{l:localDualityArg} with $A = A_i := \chi_i^\circ \Psi$ (observe that the smoothing property of $\Psi$, Proposition \ref{prop:f(Pk)}, implies that $A_i: H_k^{-p+1} \to L^2$) and the functions $\{\phi_j\}_{1 \leq j \leq 2\widehat{\domainnumber}}$, $\{\widetilde{\phi}_j\}_{1 \leq j \leq 2\widehat{\domainnumber}}$ defined by
\[
\phi_j := 
\begin{cases}
 \varphi_{i,3}^\circ\varphi_{j,0}, & j=1,\ldots,\widehat{\domainnumber},\\
 (1 -\varphi_{i,3}^\circ)\varphi_{j-\widehat{\domainnumber},0}, & j=\widehat{\domainnumber}+1,\ldots, 2\widehat{\domainnumber},
\end{cases}
\]
and
\[
\widetilde{\phi}_j := 
\begin{cases}
 \varphi_{i,4}^\circ\varphi_{j,1}, & j=1,\ldots,\widehat{\domainnumber},\\
 (1 -\varphi_{i,2}^\circ)\varphi_{j-\widehat{\domainnumber},1}, & j=\widehat{\domainnumber}+1,\ldots, 2\widehat{\domainnumber}.
\end{cases}
\]
With these definitions, $\big\{\phi_j\big\}_{1\leq j \leq 2\widehat{\domainnumber}}$ is indeed a partition of unity on $\Omega$ and $\big\{\widetilde{\phi}_j\big\}_{1\leq j \leq 2\widehat{\domainnumber}}$ satisfies the condition 
\eqref{e:supportCondition1} by the definition of $\varphi_{j,\nu}$. Therefore, choosing $h_0$ small enough, Lemma \ref{l:localDualityArg} ensures that
\begin{equation}
\label{eq:alphaji-alphaprimeji}
X_i^{\circ,-} \leq C\sum_{j = 1}^{\widehat{\domainnumber}}  \big[(\widehat{h}_{ij}k)^{2p} \alpha_{j \to i} + (\widehat{h}_{j}k)^{2p} \alpha'_{j \to i}\big] \widehat{X}_j + \big[(\widehat{h}_{ij}k)^{p} \alpha_{j \to i} + (\widehat{h}_{j}k)^{p} \alpha'_{j \to i}\big] \widehat{Z}_j+CR,
\end{equation}
where $R = k^{-N}\left((hk)^{2p}  \|u-u_h\|_{H^{-N}_k} + (hk)^p \sum_{j=1}^\domainnumber\|u - w_{h,j}\|_{H^1_k}\right)$, 
\begin{equation}
\label{e:defXjZjtilde}
\widehat{X}_j := \|\varphi_{j,1} (u-u_h)\|_{H^{-N}_k}\,, \quad \widehat{Z}_j := \|\varphi_{j,1} (u-w_{h,j})\|_{H^1_k},\quad j=1,\ldots,\widehat{\domainnumber},
\end{equation}
and 
$$\alpha_{j \to i} := \|\varphi_{i,4}^\circ \varphi_{j,1} R_k^* \Psi \chi_i^{\circ}\|_{L^2 \to L^2} + \|\varphi_{i,4}^\circ \varphi_{j,1} (R_k^\sharp)^* \Psi \chi_i^{\circ}\|_{L^2 \to H^{p+1}_k},$$
$$\alpha'_{j \to i} := \|(1-\varphi_{i,2}^\circ) \varphi_{j,1} R_k^* \Psi \chi_i^{\circ}\|_{L^2 \to L^2} + \|(1-\varphi_{i,2}^\circ) \varphi_{j,1} (R_k^\sharp)^* \Psi \chi_i^{\circ}\|_{L^2 \to H^{p+1}_k}.$$
Since $N \geq p-1$, by \eqref{e:defXjZjtilde}, \eqref{e:newCutOff}, and \eqref{e:defX},
\begin{align}\label{e:pinkBunny1}
\widehat{X}_j &\leq \|\varphi^\circ_{j,1} \Psi (u-u_h)\|_{H^{-p+1}_k} + \|\varphi^\circ_{j,1} (1 - \Psi) (u-u_h)\|_{H^{-p+1}_k} \leq X_j^- + X_j^+\,, \qquad 1 \leq j \leq M_{\Int},\\
\widehat{X}_{j + M_\Int} &\leq \|\varphi^\x_{j,1} \Psi (u-u_h)\|_{H^{-p+1}_k} + \|\varphi^\x_{j,1} (1 - \Psi) (u-u_h)\|_{H^{-p+1}_k}\leq X_j^- + X_j^+,\qquad 1 \leq j \leq M_{\Int},\\
\widehat{X}_{j + 2M_\Int} &\leq \|\varphi^\Pml_{j,1} (u-u_h)\|_{H^{-p+1}_k} = X_j^\Pml, \qquad 1 \leq j \leq M_{\Pml},
\end{align}
and similarly, 
\beq\label{e:pinkBunny2}
\widehat{Z}_j \leq \begin{cases}
Z_j & 1 \leq j \leq M_{\Int},\\
Z_{j - M_\Int} & M_{\Int}+1 \leq j \leq 2M_{\Int},\\
Z_{j - M_\Int} & 2M_{\Int} + 1 \leq j \leq \widehat{\domainnumber}.%M_{\Pml}.
\end{cases}
\eeq
Let
$$\omega_{j \to i} := (\widehat{h}_{ij}k)^{2p} \alpha_{j \to i} + (\widehat{h}_{j}k)^{2p} \alpha'_{j \to i}\,, \quad \beta_{j \to i} := (\widehat{h}_{ij}k)^{p} \alpha_{j \to i} + (\widehat{h}_{j}k)^{p} \alpha'_{j \to i}$$
and
$$\omega_{j \to i}^\circ := \omega_{j \to i}\,, \quad \omega_{j \to i}^\x := \omega_{j+M_\Int\to i},\quad j=1,\ldots, \domainnumber_\Int,$$ 
$$\omega_{j \to i}^{\Pml} := \omega_{j + 2M_\Int \to i},\quad j=1,\ldots, \domainnumber_\Pml,$$
and define $\beta^{\circ}_{j \to i},\beta^{\x}_{j \to i}$ and $\beta^{\Pml}_{j \to i}$ analogously. Then \eqref{eq:alphaji-alphaprimeji} can be written as 
\begin{equation}
\label{e:X0-_1}
X^{\circ,-} \leq C \begin{pmatrix}
\mathscr{A} & \mathscr{B}   & \mathscr{C} 
\end{pmatrix} X + 
\begin{pmatrix}
\mathscr{D}  & \mathscr{E} 
\end{pmatrix}Z + R
\end{equation}
where, for $1 \leq i \leq M_\Int$, 
\beq\label{e:heroic1}
\mathscr{A}_{ij} = \mathscr{B}_{ij} = \omega^\circ_{j\to i} + \omega^\x_{j\to i}\,, \quad 1 \leq j \leq M_\Int, \qquad \mathscr{C}_{ij} = \omega_{j \to i}^{\Pml}\,, \quad 1 \leq j\leq M_\Pml,
\eeq
and
\beq\label{e:heroic2}
\mathscr{D}_{ij} = \beta^\circ_{j\to i} + \beta^\x_{j\to i}\,, \quad 1 \leq j \leq M_\Int, \qquad \mathscr{E}_{ij} = \beta_{j \to i}^{\Pml}\,, \quad 1 \leq j\leq M_\Pml.
\eeq
To proceed, we now bound the following four terms appearing in the definitions of $\alpha_{j\to i}$ and $\alpha'_{j \to i}$:
\begin{equation*}
\|\varphi_{i,4} \varphi_{j,1}R_k^*\Psi \varphi_{i,1}^\circ\|_{L^2\to L^2}, 
\quad \| \varphi_{i,4} \varphi_{j,1} (R_{k}^\sharp)^* \Psi \varphi_{i,1}^\circ\|_{ L^2
			\to H_k^{p+1}},\quad 
\end{equation*}
\begin{equation*}
\|(1 -\varphi_{i,2})\varphi_{j,1}R_k^*\Psi \varphi_{i,1}^\circ\|_{L^2\to L^2},
\quad \tand\quad 
\| (1 -\varphi_{i,2})\varphi_{j,1} (R_{k}^\sharp)^* \Psi \varphi_{i,1}^\circ\|_{ L^2
			\to H_k^{p+1}},
\end{equation*}
where we have used that $\chi_i^\circ=\varphi_{i,1}=\varphi_{i,1}^\circ$ for $i=1,\ldots,\domainnumber_\Int$ by \eqref{e:MartinLovesNotation1}.

First, by pseudolocality of $\Psi$ (Lemma~\ref{t:pseudoLocGeneral}), polynomial boundedness of $R_k^*$ (Assumption \ref{a:polyBound}) and boundedness of $R_k^*$ in $U_{\Pml}$ (estimate \eqref{e:bounded_in_pml} in Theorem \ref{thm:PML}), %and boundedness of $\Psi:H_k^{-s}\to L^2$, %the estimate
	\begin{align}
%\nonumber
		\|\varphi_{i,4} \varphi_{j,1}R_k^*\Psi\varphi_{i,1}^\circ \|_{L^2\to L^2}
%		&\leq C \|1_{\Omega_j}R_k^* 1_{\Omega_i}\|_{L^2\to L^2}+Ck^{-N},\\ %O(k^{-\infty}).
\leq C1_{\{\widehat{\Omega}_j\cap \Omega_i^\circ\neq \emptyset\}} \begin{cases}
	  k^{-N} + \|1_{\Omega_j^\circ}R_k^* 1_{\Omega_i^\circ}\|_{L^2\to L^2}, &1\leq j\leq \domainnumber_\Int \\
	 1, &\domainnumber_\Int +1\leq j\leq 2M_{\Int}\\
	 0, & 2M_\Int + 1 \leq j \leq \widehat{\domainnumber},
		\end{cases}
		\label{e:box1_bis}
\end{align}
since by definition, for $j \in \{M_\Int + 1,\ldots,2M_\Int\}$, $\widehat{\Omega}_j \subset U_{\Pml}$, and for $j \in \{2M_\Int + 1,\ldots,\widehat{\domainnumber}\}$, $\widehat{\Omega}_j \subset \Omega_{\Pml}$, while $\Omega_j^\circ \cap \Omega_\Pml = \emptyset$.  

Second, by the mapping properties of $R_k^\sharp$  (Proposition \ref{prop:ResPksharp}), %and pseudolocality of $\Psi$ (Lemma~\ref{t:pseudoLocGeneral}),  
boundedness of $\Psi:L^2\to H_k^{p-1}$ (Proposition \ref{prop:f(Pk)}), and similar arguments,
\begin{equation*}
%\label{e:box2_bis}
		\|\varphi_{i,4} \varphi_{j,1}(R_k^\sharp)^*\Psi\varphi_{i,1}^\circ \|_{L^2\to L^2}
\leq C1_{\{\widehat{\Omega}_j\cap \Omega_i^\circ\neq \emptyset\}} \begin{cases}
	  1, &1\leq j\leq \domainnumber_\Int \\
	 1, &\domainnumber_\Int +1\leq j\leq 2M_{\Int}\\
	 0, & 2M_\Int + 1 \leq j \leq \widehat{\domainnumber}.
		\end{cases}
\end{equation*}

Third, by pseudolocality of $\Psi$ again, and of $R_k$ in $U_{\Pml}$ (estimate \eqref{e:pseudoloc_in_pml} of Theorem \ref{thm:PML}), and since $\varphi_{i,2}^\circ \prec \varphi_{i,3}$, 
\begin{align*}
\|(1-\varphi_{i,2}^\circ)\varphi_{j,1}R_k^*\Psi\varphi^\circ_{i,1}\|_{L^2\to L^2}
\leq Ck^{-N}+ C\begin{cases}
	 \|1_{\Omega_j^\circ} R_k^* 1_{\Omega_i^\circ}\|_{L^2\to L^2}, &1\leq j\leq \domainnumber_\Int \\
	 0,&\domainnumber_\Int +1\leq j\leq \widehat{\domainnumber}.
		\end{cases}
		\label{e:box3_bis}
\end{align*}

Finally, by pseudolocality of $(R_k^\sharp)^*$ 
and $\Psi$ (Lemma~\ref{t:pseudoLocGeneral}), since $\varphi_{i,2}^\circ \prec_c\varphi_{i,3}^\circ$, 
\begin{equation}
	\label{e:box4_bis}
	\begin{aligned}
	\| (1 - \varphi_{i,2}^\circ) \varphi_{j,1}(R_k^\sharp)^*\Psi \varphi_{i,1}^\circ\|_{ L^2 \to H_k^{p+1}} &\leq 
	%\| (1 - \varphi_{i,1})\varphi_{i,2} \varphi_{j,1}R_{P^\sharp_k}^* \varphi_{i,2}\|_{ L^2 \to L^2}+
	Ck^{-N}.\\
%		&\leq C\| 1_{\Omega_i \cap \Omega_j}R_{P^\sharp_k}^* 1_{\Omega_i}\|_{ L^2
%			\to L^2}+Ck^{-N}.
		\end{aligned}
\end{equation}
From the estimates \eqref{e:box1_bis}-\eqref{e:box4_bis}, we deduce that 
$$\omega_{j\to i}^\circ \leq C\Big((\widehat{h}_{ij}k)^{2p} 1_{\{\widehat{\Omega}_j\cap \Omega_i^\circ\neq \emptyset\}} + (\widehat{h}_j k)^{2p}\Big)\Big(k^{-N} +\|1_{\Omega^\circ_j} R_k^* 1_{\Omega_i^\circ}\|_{L^2\to L^2}\Big)  \leq C(h_jk)^{2p} \mathcal{C}_{ij} + C(hk)^{2p}k^{-N},$$
using the inclusions $\Omega_j^\circ \subset \Omega_j$, the fact that if $A' \subset A$, $B' \subset B$, then 
$$\|1_{A'}R_k^* 1_{B'}\| =\|1_{A'}1_AR_k^*1_B 1_{B'}\| \leq \|1_{A'}\| \|1_A R_k^*1_B\|\|1_{B'}\|  \leq  \|1_A R_k^*1_B\|,$$
and the fact that $1 \leq \mathcal{C}_{ij}$ when $\Omega_i^\circ \cap \Omega_j^\circ \neq \emptyset$. Similarly, 
$$\omega_{j \to i}^\x \leq 1_{\{\Omega_j^\x \cap \Omega_i^\circ \neq \emptyset\}} (\widehat{h}_{ij}k)^{2p} + C(\widehat{h}_j k)^{2p}k^{-N}\leq C (\Hmin(2p))_{ij}k^{2p} + C(hk)^{2p}k^{-N}.$$
Therefore, by \eqref{e:heroic1}, the following inequalities hold componentwise
$$\mathscr{A} \leq C \mathcal{C} (\Hdiag k)^{2p} + C(hk)^{2p}k^{-N}\,, \quad \mathscr{B} \leq C \mathcal{C} (\Hdiag k)^{2p} + C(hk)^{2p}k^{-N}.$$
One can check in a similar way that, by \eqref{e:heroic2},
$$\mathscr{D} \leq C \mathcal{C} (\Hdiag k)^{p} + C(hk)^pk^{-N}.$$
Finally, the estimates \eqref{e:box1_bis}-\eqref{e:box4_bis} also imply that, for $j \in \{1,\ldots,M_{\Pml}\}$, 
$$\omega_{j \to i}^{\Pml} \leq  C(hk)^{2p} k^{-N}\,, \qquad \beta_{j \to i}^{\Pml} \leq C(hk)^{p} k^{-N},$$
and thus, componentwise, by \eqref{e:heroic1} and \eqref{e:heroic2},
$$\mathscr{C} \leq C(hk)^{2p} k^{-N}\,, \quad \mathscr{E} \leq C(hk)^p k^{-N}.$$
Taking into account the definition of $R$, \eqref{e:X0-_1} thus yields
\begin{align}
X^{\circ,-} &\leq C \begin{pmatrix}
\mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & \mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & 0
\end{pmatrix} X+ C\begin{pmatrix}
\mathcal{C} (\Hdiag_{\Int,\Int} k)^{p} &0 
\end{pmatrix} Z + CR
%&\leq C \begin{pmatrix}\mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & \mathcal{C} (\Hdiag_{\Int,\Int} k)^{2p} & 0\end{pmatrix} \Bigg(X+ \begin{pmatrix} (\Hdiag_{\Int,\Int} k)^{-p} &0\\0&0\\0&0 \end{pmatrix} Z\Bigg) + CR.
\label{e:mainBoundXo-}
\end{align}
{\em Bound on $X^{\x,-}$.} To bound $X_i^{\x,-}$ for $i \in \{1,\ldots,M_{\Int}\}$, we write
\begin{align*}
X_i^{\x,-} &= \|\varphi_{i,1}^\times \Psi (u-u_h)\|_{H_k^{-p+1}} \leq \sum_{j = 1}^{\widehat{\domainnumber}}\|\varphi_{i,1}^\times \varphi_{j,0}\Psi (u-u_h)\|_{H_k^{-p+1}}
\end{align*}
since $\{\varphi_{j,0}\}_{1 \leq j \leq \widehat{\domainnumber}}$ is a partition of unity. Applying Lemma \ref{l:PMLUpgrade} with $\ell = p-1$ to each term with $\varphi = \varphi_{i,1}^\x \varphi_{j,0}$, $\tilde{\varphi} = \varphi_{i,2}^\x \varphi_{j,1}$, we deduce that
%
\beq\label{e:purpleCheeky}
X_i^{\x,-} \leq C \sum_{j = 1}^{\widehat{\domainnumber}} 1_{\{\Omega_{i}^\x \cap \widehat{\Omega}_j \neq \emptyset\}} \Big((\widehat{h}_{ij}k)^N \widehat{X}_j + (\widehat{h}_{ij}k)^p \min(\widehat{Z}_j ,Z_i)\Big) + CR,
\eeq
%
with $\widehat{Z}_j$ and $\widehat{X}_j$ given by \eqref{e:defXjZjtilde} and $Z_i$ given by \eqref{e:defX}. Estimating $\{\widehat{X}_j\}_{1 \leq j \leq \widehat{\domainnumber}}$ and $\{\widehat{Z}_j\}_{1 \leq j \leq \widehat{\domainnumber}}$ in terms of $\{Z_j\}_{1 \leq j \leq M}$ and $\{X_j^\pm\}_{1 \leq j \leq M}$ as in \eqref{e:pinkBunny1}-\eqref{e:pinkBunny2}, we obtain
%
\begin{align}
\nonumber
X^{\x,-} &\leq 
C
\begin{pmatrix}
\Hmin_{\Int,\Int}(N)k^N & \Hmin_{\Int,\Int}(N)k^N  & \Hmin_{\Int,\Pml}(N)k^N 
\end{pmatrix}
X \\
&\hspace{5cm}+ 
C
\begin{pmatrix}
(\Hdiag_{\Int,\Int}k)^p & 0
\end{pmatrix}
Z
+CR,
\label{e:mainBoundXx-}
\end{align}
where, in the minimum in \eqref{e:purpleCheeky}, we always choose the $Z_i$. 
Summing the estimates \eqref{e:mainBoundXo-} and \eqref{e:mainBoundXx-} gives the claimed estimate \eqref{e:mainBoundX-} for $X^-$. 


\paragraph{Bound on $X^+$.} 
We now show that 
\begin{align}
\nonumber
X^+ &\leq C \begin{pmatrix}
(\Hmin_{\Int,\Int}(2p) k^{2p} & \Hmin_{\Int,\Int}(N) k^{N} & \Hmin_{\Int,\Pml}(N) k^N 
\end{pmatrix} X \\
& \hspace{5cm} + C\begin{pmatrix}
(\Hdiag_{\Int,\Int}k)^p& 0%\Hmin_{\Int,\Pml}(p) k^{p} 
\end{pmatrix} Z + CR
\label{e:mainBoundX+}
\end{align}
which gives the second block row of \eqref{e:system}.
As before, we write 
$$X^+ \leq X^{\circ,+} + X^{\x,+}$$
where $X^{\circ,+} := \|\chi_i^\circ(1 - \Psi)(u-u_h)\|_{H_k^{-p+1}}$ and $X^{\x,+} := \|\chi_i^\x(1 - \Psi)(u-u_h)\|_{H_k^{-p+1}}$. 
Using exactly the same method as above for the bound on $X^{\x,-}$, we obtain
\begin{align}
\nonumber
X^{\x,+} &\leq 
C
\begin{pmatrix}
\Hmin_{\Int,\Int}(N)k^N & \Hmin_{\Int,\Int}(N)k^N  & \Hmin_{\Int,\Pml}(N)k^N 
\end{pmatrix}
X \\
&\hspace{5cm}
+C
\begin{pmatrix}
(\Hdiag_{\Int,\Int}k)^p & 0%\Hmin_{\Int,\Int}(p)k^p
\end{pmatrix}
Z
+CR.
\label{e:mainBoundXx+}
\end{align}
Using the same arguments, 
but applying Lemma \ref{l:highFreqUpgrade} instead of Lemma \ref{l:PMLUpgrade}, we obtain 
\begin{align}
\nonumber
X^{\circ,+} &\leq 
C
\begin{pmatrix}
\Hmin_{\Int,\Int}(2p)k^{2p} & \Hmin_{\Int,\Int}(N)k^N  & 0
\end{pmatrix}
X \\
&\hspace{5cm}+ 
C
\begin{pmatrix}
(\Hdiag_{\Int,\Int}k)^p & 0
\end{pmatrix}
Z
+CR.
\label{e:mainBoundXo+}
\end{align}
The bound \eqref{e:mainBoundX+} then follows by adding \eqref{e:mainBoundXx+} and \eqref{e:mainBoundXo+}. 


\paragraph{Bound on $X^\Pml$.} Following the same method as for $X^{\x,-}$, we obtain
\begin{align}
\nonumber
X^{\Pml} &\leq 
C
\begin{pmatrix}
\Hmin_{\Pml,\Int}(N)k^{N} & \Hmin_{\Pml,\Int}(N)k^N  & \Hmin_{\Pml,\Pml}(N)k^N 
\end{pmatrix}
X \\
&\hspace{5cm}+ 
C
\begin{pmatrix}
0%\Hmin_{\Int,\Int}(p)k^p 
& (\cH_{\Pml,\Pml}k)^p
\end{pmatrix}
Z
+CR.
\label{e:mainBoundXpml}
\end{align}

Gathering the estimates \eqref{e:mainBoundX-}, \eqref{e:mainBoundX+} and \eqref{e:mainBoundXpml} and taking into account the definitions of $B$ and $W$ in \eqref{e:matrixB} and \eqref{e:matrixT}, we obtain \eqref{e:system}, which concludes the proof of the lemma.
\end{proof}

\subsection{A bound on $(I-\specialC \oldT)^{-1}$ via graph arguments}\label{s:graph}

We now state the result that allows to bound the matrix $(I - \specialC \oldT)^{-1}$ coefficientwise by the simple-path matrix (see Definition \ref{def:simple_path_mat}) of $\specialC \oldT$ in Corollary \ref{c:Eurostar}. The proof is deferred to Appendix \ref{sec:loops}. Recall the graph notation from \S \ref{sec:simple_path_mat}.

\begin{theorem}[A bound on $(I-\oldT)^{-1}$ by the simple-path matrix]
	\label{t:onlyTheSimpleOnes}
Let $M \in \mathbb{N}$, let $\oldT \in \mathbb{M}(M\times M)$ be a matrix with non-negative coefficients. % and let $c := \sum_{L \in \mathbb{SL}} W_L$. Then 
\beq\label{e:loop_condition}
\text{If } \quad c  := \sum_{L \in \mathbb{SL}} W_L< 1, \quad\text{ then } \quad
\sum_{n = 0}^{\infty}W^n < \infty,
\eeq
and
\beq\label{e:transfer}
\transfer\leq \sum_{n = 0}^{\infty} W^n \leq \frac{1}{1-c} \transfer
\eeq
in the componentwise sense, where $\transfer$ is the simple-path matrix of $W$.
\end{theorem}	

\subsection{Estimates in higher norms and completion of the proof of Theorem \ref{t:theRealDeal}}\label{s:proofRegularity}

In this section, we complete the proof of Theorem \ref{t:theRealDeal}. In view of Corollary \ref{c:Eurostar} and Theorem \ref{t:onlyTheSimpleOnes}, the main task is to obtain higher norm estimates for the Galerkin error.

We now fix $\{\chi\}_{i = 1}^M$, $k_0$, $N$ and $\psi$ as in the statement of Theorem \ref{t:theRealDeal}. For $i = 1,\ldots,M$, let $\chi_{i,\nu} \in C^\infty(\overline{\Omega})$, $\nu = 0,1,2,3$, be such that 
$$\chi_{i,0} \prec \chi_{i,1} \prec \chi_{i,2} \prec \chi_{i,3}$$
with $\chi_{i,0} = \chi_i$ and $\supp(\chi_{i,\nu}) \subset \Omega_i \cap \partial\Omega$. 
Let 
 $\specialC > 0$ be as in Corollary \ref{c:Eurostar} applied with $\{\chi_{i,2}\}_{i = 1}^M$. 
Let $h_0$ be sufficiently small, depending on $k_0$ and the cutoff functions (this restriction that $h_0$ is sufficiently small comes from the applications below of 
Corollary \ref{c:Eurostar} and Lemmas \ref{l:highFreqUpgrade}, \ref{l:PMLUpgrade},  \ref{l:inaugural1}, \ref{l:highReg}, and \ref{l:PMLHighest}).
 Let $c \in (0,1)$ and suppose that the simple loop condition \eqref{e:meshConditionsGeneral} holds. 
Let $C$ denote any positive constant whose value only depends on the previous quantities. Let $k \geq k_0$, $k \notin \mathcal{J}$, $u \in H^1_k$ and $w_h \in V_k$. To show that there exists a unique $u_h \in V_k$ such that \eqref{e:Galerkin_ortho} holds, by linearity and the fact that $V_k$ is finite-dimensional, it suffices to show that when $u = 0$, the unique solution to \eqref{e:Galerkin_ortho} is $u_h = 0$. But since the latter is a consequence of \eqref{e:onlyH1}, without loss of generality, we may assume that there exists $u_h \in V_k$ satisfying \eqref{e:Galerkin_ortho} and it remains to prove the bound \eqref{e:mainResult}.


By Theorem \ref{t:onlyTheSimpleOnes}, 
$$\sum_{n =0}^{\infty} (\specialC \oldT)^n \leq \frac{1}{1-c} \transfer,$$
where $\transfer$ is the simple-path matrix of $\specialC W$. Since $\rho(k)$ is polynomially bounded on $\R_+\setminus \mathcal{J}$, $\transfer\leq C k^{M}$ coefficient-wise (since by definition, the coefficients of $\transfer$ are finite linear combination of finite products of coefficients of $\specialC \oldT$). Thus, we can apply Corollary \ref{c:Eurostar} to deduce that 
for $i=1,\dots, \domainnumber_\Int $,
\begin{align}
\label{e:low_freq_check}
\|\chi_{i,2}\Psi(u-u_h)\|_{H^{-p+1}_k}&\leq 
C \sum_{j=1}^\domainnumber \left[\piminus 
\transfer
 \matrixB\right]_{i,j}
\|u-w_{h,j}\|_{H_k^1(\Omega_j)}
+CR,
\\
\label{e:high_freq_check}
\|\chi_{i,2}(1-\Psi)(u-u_h)\|_{H_k^{-p+1}}&\leq 
C\sum_{j=1}^\domainnumber \left[\piplus
\transfer
%\sum_{n=0}^\infty \big(\specialC\matrixT\big)^n
 \matrixB\right]_{i,j}
\|u-w_{h,j}\|_{H_k^1(\Omega_j)} + CR
\end{align}
and for $1\leq i \leq \domainnumber_\Pml$,
\begin{align}
\label{e:pml_check}
&\|\chi_{\domainnumber_\Int+i,2}(u-u_h)\|_{H_k^{-p+1}}\leq 
C\sum_{j=1}^\domainnumber \left[\pi_{\Pml}
\transfer
%\sum_{n=0}^\infty \big(\specialC\matrixT\big)^n
 \matrixB\right]_{i,j}
\|u-w_{h,j}\|_{H_k^1(\Omega_j)}+ CR,
\end{align}
with $R = k^{-N}(hk)^p\sum_{j=1}^\domainnumber\|u - w_{h,j}\|_{H^1_k}$. 

\subsubsection*{Low-frequency bound in arbitrary norms}%bounds for $1\leq m\leq p$.}


The first block row of  \eqref{e:mainResult}, i.e., the low-frequency bound, follows from \eqref{e:low_freq_check} by applying Lemma \ref{l:lfshift} below for each $i = 1,\ldots,M_\Int$, with $\phi=\chi_{i,0} = \chi_i$, $\tilde{\phi} := \chi_{i,2}$, $v = u-u_h$ and $N = N'$ large enough, and then using Lemma \ref{l:inaugural1} 
(with $w_h = (\sum_{j=1}^J w_{h,j})/J$) 
to estimate $k^{-N'}\|u-u_h\|_{H_k^{-N'}}$ by $R$.

\begin{lemma}[Low-frequency shift]
\label{l:lfshift}
Let $\phi, \tilde{\phi}, \in C^\infty(\overline{\Omega})$ be such that $\phi \prec \tilde{\phi}$ and $\supp \tilde{\phi} \cap \Gamma_{\tr} = \emptyset$. Let $\psi \in  C^\infty_c(\R)$ and let $\Psi := \psi(\cP_k)$. Then, for all $k_0 > 0$ and $N \in \mathbb{N}$, there exists $C > 0$ such that
$$\|\phi \Psi v\|_{H^N_k} \leq C \|\tilde{\phi} \Psi v\|_{H^{-N}_k} + Ck^{-N} \|v\|_{H_k^{-N}} \quad \tfa k \geq k_0 \tand  v \in H^{-N}_k.$$ 
\end{lemma}
\begin{proof}
As in the proof of Lemma \ref{l:bigScreen}, the assumptions let us define $\varphi_{\Pml} \in C^\infty(\overline{\Omega})$ such that (i) $\varphi_\Pml \equiv 1$ near $\partial \Omega_-$, (ii) $\varphi_\Pml \equiv 0$ near $\Gamma_{\tr}$ and (iii) $\tilde{\phi} \prec \varphi_{\Pml}$. By Lemma \ref{l:doneWithAds}, $\varphi_\Pml$ is a boundary compatible operator in the sense of Definition \ref{def:freqOp}, and thus by Theorem \ref{thm:pseudolocFreq},
$$\phi\Psi = \phi \varphi_{\Pml} \Psi = \phi \widetilde{\Psi} \varphi_{\Pml} \Psi + \phi O_{-\infty}(k^{-\infty};\cD_k \to \cD_k) = \phi \widetilde{\Psi} \varphi_{\Pml} \Psi + O_{-\infty}(k^{-\infty};\cY_k \to \cY_k)$$
where $\widetilde{\psi} \in \mathcal{S}(\R)$ is such that $\psi \prec \widetilde{\psi}$ and $\widetilde{\Psi}:=\widetilde{\psi}(\cP_k)$, and 
where the last step uses the fact that for $n \geq 0$, $\ZcupHspace{-n} \subset \Dspace{-n}$, $\Dspace{n} \subset \ZcupHspace{n}$ are continuous inclusions and $\phi \in O_0(1,\cY_k \to \cY_k)$. Hence, since $\phi \widetilde{\Psi} = \phi \widetilde{\Psi} \tilde{\phi} + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{})$ by Theorem \ref{t:pseudoLocGeneral},
$$\phi \Psi  = \phi \widetilde{\Psi} \tilde{\phi} \Psi + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}),$$
using that $\varphi_{\Pml} \tilde{\phi} = \tilde{\phi}$. Thus, 
$$\|\phi \Psi u\|_{H_k^N} \leq \|\phi\|_{H_k^N  \to H_k^{N}} \|\widetilde{\Psi}\|_{H_k^{-N} \to H_k^{N}} \|\tilde{\phi} \Psi u\|_{H_k^{-N}} + Ck^{-N} \|u\|_{H_k^{-N}}$$
and the conclusion follows using the mapping properties of $\widetilde{\Psi}$ from Proposition \ref{prop:f(Pk)}.
\end{proof}

\subsubsection*{High-frequency and PML bounds up to the $L^2$ norm.}
The second and third block rows of \eqref{e:mainResult} 
when $m \in \{1,\ldots,p\}$ (i.e., up to the $L^2$ norm) are obtained by using Lemma \ref{l:highFreqUpgrade} and  \ref{l:PMLUpgrade}, and then using Lemma \ref{l:inaugural1} 
(again with $w_h = (\sum_{j=1}^J w_{h,j})/J$) to estimate $\|u-u_h\|_{H_k^{-N}}$ in the remainder term.

Indeed, to prove the second block row of \eqref{e:mainResult} for $m \in \{1,\ldots,p\}$, observe that from Lemma~\ref{l:highFreqUpgrade} (with $\ell=m-1$) combined with Lemma \ref{l:inaugural1} (with $w_h=w_{h,i}$), with $1\leq i\leq \domainnumber_\Int$,
\begin{align}\nonumber
\|\chi_{i,1}(1-\Psi)(u-u_h)\|_{H_k^{1-m}}&\leq C(h_i k)^m\Big(\|u-w_{h,i}\|_{H_k^1(\Omega_i)}+(h_ik)^p\|\chi_{i,2}\Psi(u-u_h)\|_{H_k^{-p+1}}\\
&\hspace{1cm}+(h_ik)^N\|\chi_{i,2}(1-\Psi)(u-u_h)\|_{H_k^{-p+1}}\Big) +Ck^{-N}(hk)^m\|u-w_{h,i}\|_{H_k^1};
\label{e:quickSand1}
\end{align}
the second block row of \eqref{e:mainResult} then follows from \eqref{e:quickSand1} and \eqref{e:high_freq_check}, using that $\chi_{i,0}\prec \chi_{i,1}$ (this extra ``layer" is used in the proof for $m=0$ below). 

The third block row of \eqref{e:mainResult}, i.e., the bound on the PML error, is proved in a similar way to the high-frequency bound, using Lemma~\ref{l:PMLUpgrade}  instead of Lemma~\ref{l:highFreqUpgrade}. Indeed, Lemma~\ref{l:PMLUpgrade} (with $\ell=m-1$ and $N$ sufficiently large) combined with 
Lemma \ref{l:inaugural1} (with $w_h=w_{h,i}$) implies that, with $\domainnumber_\Int +1\leq i\leq \domainnumber$, %$\tilde{i}:=\domainnumber_\Int +i$,
\begin{align}\nonumber
\|\chi_{i,1}(u-u_h)\|_{H_k^{1-m}}&\leq C(h_{i} k)^m\Big(\|u-w_{h,i}\|_{H_k^1(\Omega_{i})}+(h_ik)^N\|\chi_{i,2}(u-u_h)\|_{H_k^{-p+1}}\Big) \\
&\hspace{5cm}+Ck^{-N}(hk)^m\|u-w_{h,i}\|_{H_k^1}.
\label{e:quickSand2}
\end{align}
The third block row of \eqref{e:mainResult} then follows from \eqref{e:quickSand2} and \eqref{e:pml_check}, using again that $\chi_{i,0}\prec \chi_{i,1}$.


\subsubsection*{High-frequency and PML bound in the energy norm.}
%\paragraph{Proof of the bounds for $m=0$.}

The second block row of \eqref{e:mainResult}
 for $m = 0$ (i.e., in the $H^1_k$ norm) follows from \eqref{e:high_freq_check}, \eqref{e:quickSand1} with $m = 1$, and the following lemma applied with $\phi = \chi_{i,0}$, $\widetilde{\phi} := \chi_{i,1}$, $N := N'$ large enough and using Lemma \ref{l:inaugural1} 
(with $w_h=w_{h,i}$)  
to estimate $k^{-N'}\|u-u_h\|_{H_k^{-N'}}$ by $R$.



\begin{lemma}
\label{l:highReg}
For any $k_0 > 0$ and $\mathfrak{c} > 0$, there exists $h_0 > 0$ such that the following holds. Let $\phi,\widetilde{\phi} \in C^\infty(\overline{\Omega})$ be such that
$$\phi \prec_{\mathfrak{c}} \widetilde{\phi} \quad \tand \quad \supp(\widetilde{\phi}) \cap \Gamma_{\tr} = \emptyset.$$
Furthermore, let $\psi,\psi_0 \in C^\infty_c(\R)$ be such that $\psi_0 \prec \psi$, let $\Psi := \psi(\cP_k)$, $\Psi_0:= \psi_0(\cP_k)$ and
$$A:= \phi(1 - \Psi) \quad \tand \quad \widetilde{A} := \widetilde{\phi}(1 - \Psi_0).$$
Then, for all $N > 0$, there exists $C > 0$ such that for all $k \geq k_0$, $h \leq h_0$, $u-u_h$ satisfying \eqref{e:Galerkin_ortho} and for all $w_h \in V_k$,  
\begin{align*}
\|A(u-u_h)\|_{H^1_k} &\leq C \left( \|\widetilde{\phi} (u-w_h)\|_{H^1_k} + \|\widetilde{A}(u-u_h)\|_{L^2} + (h_{\tilde{\phi}}k)^p \|\widetilde{\phi}(u-u_h)\|_{H_k^{-N}}\right)\\
& \hspace{5.5cm} + Ck^{-N}(\|u -w_h\|_{H_k^1} + \|u - u_h\|_{H_k^{-N}}).
\end{align*}
where $h_{\tilde{\phi}} :=\max \big\{h_K \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp (\widetilde{\phi}) \neq \emptyset\big\}$.
\end{lemma}

The heart of the proof of Lemma \ref{l:highReg} is that, by the G\aa rding inequality, Galerkin orthogonality, and the definition of $\Pi^\sharp_k$, 
\begin{equation}
\label{e:luigi2_prepare}
 \begin{aligned}
&\|A(u-u_h)\|_{H_k^1}^2 \leq \Re \big\langle  P_k A(u-u_h), A(u-u_h)\big\rangle + C \| A(u-u_h)\|^2_{L^2}\\
&\leq \big| \big\langle P_k(u-u_h), (I-\Pi^\sharp_k)A^*A(u-u_h)\big\rangle\big| +\big|\big\langle [P_k,A](u-u_h),A(u-u_h)\big\rangle\big|+C\|A(u-u_h)\|^2_{L^2}.
\end{aligned}
\end{equation}
The first term on the right-hand side of \eqref{e:luigi2_prepare} is dealt with in a similar way to the proof of Lemma \ref{l:localDualityArg} (compare the first term on the right-hand side of \eqref{e:luigi2_prepare} to the right-hand side of \eqref{eq:dismantled}). The following lemma deals with the second term on the right-hand side of \eqref{e:luigi2_prepare} (i.e., the commutator term).


\begin{lemma}\label{l:commutator}
Let $\phi, \widetilde{\phi}\in C^\infty(\overline{\Omega})$ be such that $\partial_\nu \phi |_{\partial\Omega_-}=0$, $\phi \prec \widetilde{\phi}$ and $\supp (\widetilde{\phi})\cap \Gamma_{\tr}=\emptyset$, let 
$\psi,\psi_{0}\in C^\infty_c(\mathbb{R})$ be such that $\psi_0 \prec \psi$, let $\Psi:= \psi(\cP_k)$ and $\Psi_0:= \psi_0(\cP_k)$ and let $$A:= \phi (1-\Psi) \quad \tand \quad \widetilde{A}:= \widetilde{\phi} (1-\Psi_0)$$ 
Then
\beqs%\label{e:commutator0}
A = A\widetilde{A}+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})
\eeqs
\beq\label{e:commutator1}
[P_k,A] = [P_k,A] \widetilde{A}+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})
\eeq
and for all $k_0 > 0$, there exists $C > 0$ such that for all $k \geq k_0$,
\beq\label{e:commutator2}
\|[P_k,A]\|_{L^2\to (\cZ_k)^*}\leq  Ck^{-1}.
\eeq
\end{lemma}

\bpf 
Similar to in the proof of Lemma \ref{l:bigScreen}, let $\varphi_{\Pml} \in C^\infty(\overline{\Omega})$, 
be such that $\widetilde{\phi}\prec\varphi_{\Pml}$ and that
$$\supp (\varphi_{\Pml})\cap \Gamma_{\tr}=\emptyset\quad \tand \quad \supp(1- \varphi_{\Pml}) \cap \partial \Omega_- =\emptyset$$
(compare to \eqref{e:cutoffPML}). We claim that
\begin{align}
[P_k,A] &= [\varphi_{\Pml} P_k \varphi_{\Pml}, A]+ O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}) \label{e:PkAtosandwichA}\\
A &= A\widetilde{A} + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}),
\label{e:AtoAAtilde}\\
A(\varphi_{\Pml} P_k \varphi_{\Pml}) &= A(\varphi_{\Pml} P_k \varphi_{\Pml})\widetilde{A} + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}).\label{e:AsandwitchtoAsandwichAtilde}
\end{align}
Once these three properties are shown, we obtain \eqref{e:commutator1} and \eqref{e:commutator2} as follows. First,
\begin{align*}
[P_k,A] &= [\varphi_{\Pml} P_k \varphi_{\Pml},A] + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{})\qquad \text{(by \eqref{e:PkAtosandwichA})}\\
& = [\varphi_{\Pml} P_k \varphi_{\Pml},A]\widetilde{A} + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}) \qquad 
\text{(by \eqref{e:AtoAAtilde} and \eqref{e:AsandwitchtoAsandwichAtilde})}\\
& = [P_k,A]\widetilde{A} + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}) \qquad 
\text{(by \eqref{e:PkAtosandwichA})}
\end{align*}
which is \eqref{e:commutator1}. Second,
\begin{align}\nonumber
[P_k,A] &= [\varphi_{\Pml} P_k \varphi_{\Pml},A] + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}) \qquad \text{(by \eqref{e:PkAtosandwichA}}\\\nonumber
&= [\varphi_{\Pml} P_k \varphi_{\Pml},\phi](1 - \Psi) + \phi [\varphi_{\Pml} P_k \varphi_{\Pml},(1 - \Psi)] + O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{}) \\\nonumber
& \hspace{8cm} \textup{(by definition of $A$)} \\
& = \varphi_{\Pml}[P_k,\phi]\varphi_{\Pml} (1 - \Psi) + \phi [\varphi_{\Pml} P_k \varphi_{\Pml},(1 - \Psi)] \qquad \textup{(since $[\varphi_{\Pml},\phi] = 0$)}\label{e:twoComm}
\end{align}
By Lemma \ref{l:spatialCut}, $\phi \in \Lcut$, and by Lemma \ref{l:commuteP}, $\varphi_{\Pml} P_k \varphi_{\Pml} \in \Lf$. Thus, by the Definition of these spaces (Definitions \ref{def:spatialCutoffs} and \ref{def:freqOp}), \eqref{e:twoComm} gives \eqref{e:commutator2}.

We now prove \eqref{e:PkAtosandwichA}-\eqref{e:AsandwitchtoAsandwichAtilde}. First, by locality of $P_k$, 
\begin{equation}
\label{e:PkAsandwichA}
P_k A = P_k \phi (1 - \Psi) = \varphi_{\Pml} P_k \varphi_{\Pml} \phi (1 - \Psi) = \varphi_{\Pml} P_k \varphi_{\Pml} A.
\end{equation}
Moreover, by Theorem \ref{t:pseudoLocGeneral}, the locality of $P_k$, the fact that $\widetilde\phi= \widetilde\phi \varphi_{\Pml}$, and then Theorem \ref{t:pseudoLocGeneral} again,
\begin{align}\nonumber
A P_k = \phi (1-\Psi) P_k &= \phi(1-\Psi)\widetilde\phi P_k + O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})\\\nonumber
&=\phi(1-\Psi)\widetilde{\phi}P_k \varphi_{\Pml}
+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})\\\nonumber
&=\phi(1-\Psi)\widetilde{\phi}\varphi_{\Pml}P_k \varphi_{\Pml}
+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})\\\nonumber
&=\phi(1-\Psi)\varphi_{\Pml}P_k \varphi_{\Pml}
+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{}),\\
& = A \varphi_{\Pml} P_k \varphi_{\Pml}+O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{})
\label{e:APkAsandwitch}.
\end{align}
Combining \eqref{e:PkAsandwichA} and \eqref{e:APkAsandwitch} gives \eqref{e:PkAtosandwichA}. Second, by the fact that  $(1-\psi)= (1-\psi)(1-\psi_0)$ and by Theorem \ref{t:pseudoLocGeneral},
\begin{align*}
A = \phi(1- \Psi) = \phi(1-\Psi) (1-{\Psi}_0) &= \phi(1-\Psi) \widetilde\phi(1-{\Psi}_0) +O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{}),\\
&=A\widetilde{A} + O_{-\infty}(k^{-\infty};\ZcupHspace{}\to \ZcupHspace{}).
\end{align*}
which is \eqref{e:AtoAAtilde}. Finally, using again that $\varphi_{\Pml} P_k \varphi_{\Pml} \in \Lf$, we obtain
$$(1 - {\Psi})(\varphi_{\Pml} P_k \varphi_{\Pml}) = (1 - {\Psi})(\varphi_{\Pml} P_k \varphi_{\Pml}) (1 -{\Psi}_0) + O_{-\infty}(k^{-\infty},\ZcupHspace{} \to \ZcupHspace{})$$
by Theorem \ref{thm:pseudolocFreq}. Left-multiplying by $\phi$ thus gives
\begin{align*}
A(\varphi_{\Pml} P_k \varphi_{\Pml}) &= \phi(1 - {\Psi})(\varphi_{\Pml} P_k \varphi_{\Pml}) (1 -\Psi_0) + O_{-\infty}(k^{-\infty},\ZcupHspace{} \to \ZcupHspace{}) \\
& = \phi(1 - {\Psi})(\varphi_{\Pml} P_k \varphi_{\Pml}) \widetilde{\phi}(1 -\Psi_0) \\
&\qquad + 
\phi (1 - \Psi) (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi})(1 -\Psi_0)
+ O_{-\infty}(k^{-\infty},\ZcupHspace{} \to \ZcupHspace{}) \\
& = A(\varphi_{\Pml} P_k \varphi_{\Pml})\widetilde{A} \\
& \qquad + \phi (1 - \Psi) (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi})(1 -\Psi_0)
+ O_{-\infty}(k^{-\infty},\ZcupHspace{} \to \ZcupHspace{}),
\end{align*}
and \eqref{e:AsandwitchtoAsandwichAtilde} then follows from locality of $\varphi_{\Pml} P_k \varphi_{\Pml}$ and pseudolocality of $\Psi$ (Theorem \ref{t:pseudoLocGeneral}), since
\begin{align*}
&\phi (1 - \Psi) (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi}) \\
&\qquad = [\phi (1 - \Psi) (1 -\check{\phi})] (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi})+\phi (1 - \Psi) [\check{\phi} (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi})] \\
&\qquad = O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{}) (\varphi_{\Pml} P_k \varphi_{\Pml})(1 - \widetilde{\phi}) + 0\\
&\qquad = O_{-\infty}(k^{-\infty};\ZcupHspace{} \to \ZcupHspace{})
\end{align*}
where $\check{\phi} \in C^\infty(\overline{\Omega})$ is such that $\phi \prec \check{\phi} \prec \widetilde{\phi}$. 
\epf 


