\begin{proof}[Proof of Lemma \ref{l:highReg}]
Let $k_0 > 0$ and $\mathfrak{c} > 0$, and let $h_0$ be small enough to apply Theorem \ref{t:pseudoLocalPi} and Lemma \ref{l:localSharp}. Let $\phi$, $\widetilde{\phi}$, $\psi$, $\psi_0$ and $N$ be as in the statement, and denote by $C$ any positive constant depending only on the previous quantities. Let $k \geq k_0$, suppose that $h \leq h_0$ let $u-u_h$ be such that \eqref{e:Galerkin_ortho} holds.
Let $\phi_{1},\phi_2,\phi_3\in C^\infty(\overline{\Omega})$ be such that 
\beqs
\phi \prec_{\mathfrak{c}/4} \phi_{1} \prec_{\mathfrak{c}/4} \phi_2 \prec_{\mathfrak{c}/4} \phi_3 \prec_{\mathfrak{c}/4} \widetilde{\phi}
\eeqs
with, additionally, $\partial_{\nu} (\phi_1)|_{\partial\Omega_-}=0$; such a $\phi_1$ exists by Lemma \ref{l:goodCut}. 
Since
$$
\|\phi(1-\Psi)u\|_{H_k^{1}}\leq \|\phi_1(1-\Psi)u\|_{H_k^{1}},
$$
it is enough to estimate the latter.
Let $A= \check{\phi} (1 - \Psi)$. 
By the G\aa rding inequality and Galerkin orthogonality \eqref{e:Galerkin_ortho},
\begin{equation}
\label{e:luigi2}
 \begin{aligned}
\|A(u-u_h)\|_{H_k^1}^2 &\leq \Re \big\langle  P_k A(u-u_h), A(u-u_h)\big\rangle + C \| A(u-u_h)\|^2_{L^2}\\
&\leq \big| \big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle\big| \\
& \hspace{3cm} +\big|\big\langle  [P_k,A](u-u_h),A(u-u_h)\big\rangle\big|+C\|A(u-u_h)\|^2_{L^2}.
\end{aligned}
\end{equation}
With $\widetilde{A}$ as in the statement, Lemma \ref{l:commutator} gives 
\begin{align}\nonumber
&\big|\big\langle  [P_k,A](u-u_h),A(u-u_h)\big\rangle\big|
\\\nonumber
&\qquad  \leq \big|\big\langle  [P_k,A]\widetilde{A}(u-u_h),A(u-u_h)\big\rangle\big| + Ck^{-N} \|u-u_h\|_{H_k^{-N}} \|A(u-u_h)\|_{H^1_k}\\
& \qquad \leq C\left(k^{-1}\|\widetilde{A}(u-u_h)\|_{L^2} + Ck^{-N} \|u-u_h\|_{H_k^{-N}}\right) \|A(u-u_h)\|_{H^1_k},
\label{e:bound_commutator}
\end{align}
and
\begin{align}
\nonumber
\|A(u-u_h)\|_{L^2}^2 & \leq \|A(u-u_h)\|_{L^2} \|A(u-u_h)\|_{H^1_k}\\ 
&\leq C \left(\|\widetilde{A}(u-u_h)\|_{L^2} + Ck^{-N} \|u-u_h\|_{H_k^{-N}}\right) \|A(u-u_h)\|_{H^1_k}.
\label{e:bound_L2term}
\end{align}
Combining \eqref{e:luigi2}, \eqref{e:bound_commutator} and \eqref{e:bound_L2term}, we deduce that 
$$\|A(u-u_h)\|^{2}_{H^1_k} \leq  \big| \big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle\big| +C \|\widetilde{A}(u-u_h)\|^2_{L^2} + Ck^{-2N} \|u-u_h\|^2_{H_k^{-N}},$$
and to conclude the proof, it remains to show that 
\begin{align}\nonumber
&\big| \big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle\big|\\
& \hspace{3cm} \leq (\|\widetilde{\phi}(u-w_h)\|_{H^1_k} + (h_{\tilde{\phi}}k)^p \|\widetilde{\phi}(u - u_h)\|_{H_k^{-N}} + C R)\|A(u-u_h)\|_{H^1_k}
\label{e:main_term_Garding}
\end{align}
where $R := k^{-N} (\|u-u_h\|_{H_k^{-N}} + \|u-w_h\|_{H^1_k}).$

To establish \eqref{e:main_term_Garding}, we use the identity
\begin{align*}
&\big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle \\
&\qquad =   \big\langle u-w_h,(P_k^\sharp)^*(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle - \langle  u-u_h, S_k(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle
\end{align*}
(shown in the same manner as \eqref{eq:dismantled} in the proof of the localised duality argument, Lemma \ref{l:localDualityArg}). Next, by pseudo-locality of $1 - \Psi$, $A^* = \phi_2 A^* + O_{-\infty}(k^{-\infty};\ZcupHspace{}\to\ZcupHspace{})$, so that
\begin{align*}
&\abs{\big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle} \\
&\qquad \leq \abs{ \big\langle u-w_h,(P_k^\sharp)^*(\Id - \Pi_k^\sharp) \phi_2 A^*A(u-u_h)\big\rangle} +\abs{ \langle  (u-u_h), S_k(\Id - \Pi_k^\sharp) \phi_2A^*A(u-u_h)\big\rangle} \\
& \qquad \qquad + CR\|A(u-u_h)\|_{H^1_k}.
\end{align*}
Now, adapting the arguments in the proof of Lemma \ref{l:localDualityArg} (from \eqref{eq:dismantled} to \eqref{ready_to_go}), we obtain
\begin{align}
\nonumber
&\abs{\big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle}\\
& \quad \leq \abs{\big\langle P_k^\sharp \widetilde{\phi}(u-w_h),\phi_3(\Id - \Pi_k^\sharp) w\big\rangle} + \abs{\big\langle S_k \widetilde{\phi}(u-u_h),\widetilde{S}_k \phi_3(\Id - \Pi_k^\sharp) w\big\rangle} + CR\|A(u-u_h)\|_{H^1_k},
\label{e:almost_there}
\end{align}
where $w = \phi_2 A^* A (u-u_h)$ and $\widetilde{S}_k := \widetilde{\psi}(\cP_k)$ where $\widetilde{\psi} \in C^\infty_c(\R)$ is such that $\psi \prec \widetilde{\psi}$. Namely, we follow exactly the same steps as in \eqref{eq:sicily1} and \eqref{eq:sicily2} but with $\ell = -1$, and in \eqref{eq:aloeVera1} and \eqref{eq:aloeVera2}, choosing $v = A^* A (u-u_h)$, we use the estimate $\|v\|_{H^1_k} \leq \|A^*\|_{H^1_k \to H^1_k} \|A(u-u_h)\|_{H^1}$, and the fact that $\|A^*\|_{H^1_k\to H^1_k} \leq C$. Finally, by the quasi-optimality of $\Pi_k^\sharp$ and the previous bound on $\|A^*\|_{H^1_k \to H^1_k}$, 
$$\|(\Id - \Pi_k^\sharp) w\|_{H^1_k} \leq C \|A(u-u_h)\|_{H^1_k},$$
and in turn, by Lemma \ref{l:localSharp}, 
$$\|\widetilde{S}_k \phi_3 (\Id - \Pi_k^\sharp) w\|_{L^2} \leq C\Big((h_{\tilde{\phi}}k)^p + k^{-N}(hk)^p\Big)\|A(u-u_h)\|_{H^1_k}.$$
Using these bounds in \eqref{e:almost_there}, 
\begin{align*}
&\abs{\big\langle P_k(u-u_h),(\Id - \Pi_k^\sharp) A^*A(u-u_h)\big\rangle}\\
&\qquad \leq C\left(\|\widetilde{\phi}(u-w_h)\|_{H^1_k} + \big((\widetilde{h}_{\phi}k)^p + k^{-N}(hk)^p\big)\|S_k \widetilde{\phi} (u-u_h)\|_{L^2} + CR\right)\|A(u-u_h)\|_{H^1_k}
\end{align*}
and \eqref{e:main_term_Garding} follows by using the mapping properties of $S_k$. 
\end{proof}

