The proof of the third block row of \eqref{e:mainResult} in the $H^1_k$ norm (i.e., $m = 0$), is similar to that of the second block row, using Lemma \ref{l:PMLHighest} below instead of Lemma \ref{l:highReg}.

\begin{lemma}\label{l:PMLHighest}
For any $k_0 > 0$ and $\mathfrak{c} > 0$, there exists $h_0 > 0$ such that the following holds. Let $\phi,\widetilde{\phi} \in C^\infty(\overline{\Omega})$ be such that $\phi \prec_{\mathfrak{c}} \widetilde{\phi}$.
Then, for all $N > 0$, there exists $C > 0$ such that for all $k \geq k_0$, $h \leq h_0$, $u-u_h$ satisfying \eqref{e:Galerkin_ortho} and for all $w_h \in V_k$,  
\begin{align*}
\|\phi(u-u_h)\|_{H^1_k} &\leq C \left( \|\widetilde{\phi} (u-w_h)\|_{H^1_k} + \|\widetilde{\phi}(u-u_h)\|_{L^2}\right)\\
& \hspace{3.5cm} + Ck^{-N}\big(\|u -w_h\|_{H_k^1} + \|u - u_h\|_{H_k^{-N}}\big).
\end{align*}
where $h_{\tilde{\phi}} :=\max \Big\{h_K \, :\, K \in \cT_k \,\,\textup{ s.t. }\, K \cap \supp (\widetilde{\phi}) \neq \emptyset\Big\}$.
\end{lemma}
\begin{proof}
Let $\phi_{1},\phi_2 \in C^\infty(\overline{\Omega})$ be such that 
$$\phi \prec \phi_1 \prec \phi_2 \prec \widetilde{\phi},$$
with in addition, $\partial_\nu (\phi_1)|_{\partial\Omega_-}=0$. Then, observe that 
$$
\|\phi (u-u_h)\|_{H_k^1}\leq C\|\phi_1(u-u_h)\|_{H_k^1}. 
$$
The proof is now identical to that of Lemma~\ref{l:highReg}, with the following replacement for Lemma \ref{l:commutator}: (i) $[P_k,\phi_1]=[P_k,\phi_1]\phi_2$, which follows from locality of $P_k$ and (ii), $\|[P_k,\phi_1]\|_{L^2 \to \cZ_k^*} \leq Ck^{-1}$ is continuous, which follows from Lemma~\ref{l:spatialCut} and Definition \ref{def:spatialCutoffs}.
\end{proof}


