By Lemma \ref{l:what_is_t}, it suffices to show that for all $\specialC > 0$, there exists $\specialC' > 0$ and $C > 0$ such that 
\begin{equation}
\label{e:matrix_estimate2}
\begin{pmatrix}
\Id & 0 & 0 \\
0 & 0 & \Id 
\end{pmatrix}  (\specialC W)^n B \leq C \specialC'^n\mathscr{W}^n\mathscr{B}.
\end{equation}
To prove this, we first observe that, with $\ell = p$ or $2p$, 
$$\Hmin_{\Int,\Int}(\ell) k^{\ell} \leq \mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^{\ell}.$$
Indeed, $(\mathcal{C}_{\Int,\Int})_{ij} \geq 1$ for all $i,j$ such that $(\mathcal{H}^{\min}_\Int(\ell))_{ij} \neq 0$ (since when the domains overlap, the norm of the solution operator is $\geq 1$). Since $\Hdiag$ is diagonal, it follows that for such pairs $i,j$ and all $\ell \geq 0$, 
\[(\cH_{\Int,\Int}^{\min}(\ell))_{ij} = \min(h_i,h_j)^\ell \leq (\mathcal{C}_{\Int,\Int})_{ij} h_j^{\ell} = (\mathcal{C}_{\Int,\Int} (\Hdiag)^{\ell})_{ij}.\]

Therefore, the matrix $\oldT$ associated to the full graph (Figure \ref{f:twitch}) and the matrix $B$ can be estimated by blocks as
$$\oldT \leq C\begin{pmatrix}
\mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^{2p}& \mathcal{C}_{\Int,\Int}(\Hdiag_{\Int,\Int} k)^{2p} &h_{\min}(N) k^{N}\\
\mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^{2p}& \mathcal{C}_{\Int,\Int}(\Hdiag_{\Int,\Int} k)^{2p} &h_{\min}(N) k^{N}\\
h_{\min}^T(N) k^{N} & h_{\min}^T(N) k^{N}& (h_\pml k)^N\\
\end{pmatrix} = C\begin{pmatrix}
\textup{diag}(A(2p)) J & Kb(N)\\[0.2em]
b(N)^T K^T & (h_\pml k)^N
\end{pmatrix}$$ 
$$B \leq C\begin{pmatrix}
\mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^p& 0\\
\mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^{p}& 0\\
0
& (h_\pml k)^p\\
\end{pmatrix} = C\begin{pmatrix}
\textup{diag}({A(p)})K & 0%Kb(p)
\\
0%b(p)
 & (h_\pml k)^p
\end{pmatrix}$$ 
where
$$A(\ell) = \mathcal{C}_{\Int,\Int} (\Hdiag_{\Int,\Int} k)^\ell\,, \quad \textup{diag}(A) := \begin{pmatrix}
A & 0 \\
0 & A
\end{pmatrix}\,, \quad b(\ell) = h_{\min}(\ell) k^{\ell}\,, \quad J = \begin{pmatrix}
I_3 & I_3\\
I_3 & I_3
\end{pmatrix} \quad K = \begin{pmatrix}
I_3 \\
I_3
\end{pmatrix}$$ 
with $I_3$ denoting the $3\times3$ identity matrix. With these definitions, observe that
$$\mathscr{W} = \begin{pmatrix}
A(2p) &b(N)\\
b(N)^T & (h_\pml k)^N
\end{pmatrix}\,, \quad \mathscr{B} = \begin{pmatrix}
A(p) & 0%b(p)
\\
0%b(p)^T 
& (h_\pml k)^p
\end{pmatrix};$$
thus the estimate \eqref{e:matrix_estimate2} immediately follows from the next lemma.
\begin{lemma}
Let $A,B$ be $M \times M$ matrices with positive coefficients, $b,b' \in \mathbb{R}_+^M$, $c \in \R_+$. Then, for all $n$,
$$\begin{pmatrix}
\Id_M & 0 & 0\\
0 & 0 & \Id_M
\end{pmatrix}\begin{pmatrix}
\end{pmatrix}\begin{pmatrix}
\textup{diag}(A) J & Kb\\
b^TK^T & c
\end{pmatrix}^n \begin{pmatrix}
\textup{diag}(A')K & 0\\
0 & c'
\end{pmatrix}\leq 2^{n+1}\begin{pmatrix}
A & b\\
b^T & c
\end{pmatrix}^n \begin{pmatrix}
A' & 0\\
0 & c'
\end{pmatrix}.$$
\end{lemma}
\begin{proof}
Let
$$\begin{pmatrix}
A_n & b_n\\
b_n^T & c_n
\end{pmatrix} := \begin{pmatrix}
A & b \\
b^T & c
\end{pmatrix}^n.$$
Using that
$J^2 = 2J$, $JK = 2K$ and $K^T K = 2$, one can check by an easy induction that
$$
\begin{pmatrix}
\textup{diag}(A) J & Kb\\
b^TK^T & c
\end{pmatrix}^n \leq 2^n\begin{pmatrix}
\textup{diag}(A_n) J & Kb_n\\
b_n^TK^T & c_n.\end{pmatrix}$$
The result then follows using that
\begin{align*}
\begin{pmatrix}
\Id_M & 0 & 0\\
0 & 0 & \Id_M
\end{pmatrix}\begin{pmatrix}
\textup{diag}(A_n) J & Kb_n\\
b_n^TK^T & c_n
\end{pmatrix}\begin{pmatrix}
\textup{diag}(A')K & Kb'\\
b'^T & c'
\end{pmatrix} &= \begin{pmatrix}
A_n & A_n & b\\
b & b & c
\end{pmatrix}\begin{pmatrix}
A' & 0\\
A' & 0\\
0 & c'
\end{pmatrix}\\
& \leq 2 \begin{pmatrix}
A_n & b_n\\
b_n^T & c_n
\end{pmatrix}\begin{pmatrix}
A' & 0\\
0 & c'
\end{pmatrix}. 
\end{align*}
\end{proof}


