\section{Definition of radial perfectly matched layers}
\label{sec:PML}

Let $R_{\rm scat}$ be such that
\beq\label{e:Rscat}
\supp(A-I) \cup \supp(n-1) \cup \Omega\Subset B_{R_{\rm scat}}.
\eeq
Let $\RPMLo>R_{\rm scat}$ be such that $B_{\RPMLo }\Subset \Omega_{\tr}$.

As in \S\ref{sec:1.1} and \S\ref{sec:3.1}, let $\Omega:=\Omega_{+}\cap \Omega_{\tr}$ and $\Gamma_{\tr}:=\partial\Omega_{\tr}$.
For $0\leq \theta<\pi/2$, let the PML scaling function $f_\theta\in C^{\infty}([0,\infty);\mathbb{R})$ be defined by $f_\theta(r):=f(r)\tan\theta$ for some $f$ satisfying
\begin{equation}
\label{e:fProp}
\begin{gathered}
\big\{f(r)=0\big\}=\big\{f'(r)=0\big\}=\big\{r\leq \RPMLo\big\},\quad f'(r)\geq 0;
\end{gathered}
\end{equation}
i.e., the scaling ``turns on'' at $r=\RPMLo$. 
Given $f_\theta(r)$,  let 
\beqs
\alpha(r) := 1 + \ri f_\theta'(r) \quad \tand\quad \beta(r) := 1 + \ri f_\theta(r)/r.
\eeqs
We now define two possible PML problems \eqref{e:PML1}; both are formed by first replacing $\Delta$ in \eqref{e:edp} by 
\begin{align*}
\Delta_\theta&= \Big(\frac{1}{1+\ri f_\theta'(r)}\pdiff{}{r}\Big)^2+\frac{d-1}{(r+\ri f_\theta(r))(1+\ri f'_\theta(r))}\pdiff{}{r} +\frac{1}{(r+\ri f_\theta(r))^2}\Delta_\omega,\\
&= \frac{1}{(1+\ri f_\theta'(r))(r+\ri f_\theta(r))^{d-1}}\frac{\partial}{\partial r}
\left( \frac{ (r+\ri f_\theta(r))^{d-1}}{1+\ri f_\theta'(r)}\frac{\partial}{\partial r}
\right)+\frac{1}{(r+\ri f_\theta(r))^2}\Delta_\omega
\end{align*}
(with $\Delta_\omega$ the surface Laplacian on $S^{d-1}$) and then either multiplying by $ \alpha \beta^{d-1}$ or not -- the coefficients $A_\theta,b_\theta$, and $n_\theta$ for both options are defined below.

\paragraph{Comparison of the two different formulations.}

The multiplication by $\alpha \beta^{d-1}$ has the advantage that the resulting operator is in divergence form; however, for $P_k$ to satisfy~\eqref{e:Garding1}, one requires additional assumptions. In particular,~\cite[Lemma 2.3]{GLSW1} shows that~\eqref{e:Garding1} holds for any $f_\theta(r)$ satisfying the above assumptions in $d=2$ and holds in $d=3$ when $f_\theta(r)/r$ is, in addition, non-decreasing and~\cite[Remark 2.1]{GLSW1} shows that such an additional assumption is needed.


If one instead integrates by parts the complex-scaled PDE directly (i.e., avoids the above multiplication), 
then the resulting sesquilinear form satisfies the G\aa rding inequality after multiplication by $\re^{\ri \omega}$, for some suitable constant $\omega$~\cite[Lemma A.6]{GLS1}. %The results of this paper hold equally for both these sesquilinear forms.
%\bre\label{rem:emptySet}
%When the complex-scaled PDE is integrated by parts directly (without multiplication by $\alpha \beta^{d-1}$), Theorem \ref{t:theRealDeal} is applicable to the sesquilinear form $\re^{\ri \omega} a_k(\cdot,\cdot)$. Since 
%\beqs
%a_k(u-u_h, v_h) = 0 \quad \text{ if and only if }\quad \re^{\ri \omega} a_k(u-u_h, v_h) = 0,
%\eeqs
%this multiplication does not change the Galerkin solution \eqref{e:Galerkin_ortho}.
%\ere
%

We highlight that, in other papers on PMLs, the scaled variable, which in our case is $r+\ri f_\theta(r)$, is often written as $r(1+ \ri \widetilde{\sigma}(r))$ with $\widetilde{\sigma}(r)= \sigma_0$ for $r$ sufficiently large; see, e.g., \cite[\S4]{HoScZs:03}, \cite[\S2]{BrPa:07}. Therefore, to convert from our notation, set $\widetilde{\sigma}(r)= f_\theta(r)/r$ and $\sigma_0= \tan\theta$.
In this alternative notation, the assumption that $f_\theta(r)/r$ is nondecreasing is therefore that $\widetilde{\sigma}$ is nondecreasing -- see \cite[\S2]{BrPa:07}.


\paragraph{The sesquilinear form after multiplication by $\alpha \beta^{d-1}$.}
Define $b_\theta:=0$,
\beq\label{e:firstPML}
A_\theta := 
\begin{cases}
A
\hspace{-1ex}
& \tin \Omega,\\
HDH^T 
\hspace{-1ex}
&\tin (B_{\RPMLo})^c
\end{cases}
\quad\tand\quad
n_\theta := 
\begin{cases}
 n &\tin \Omega \cap B_{\RPMLo},\\
\alpha(r) \beta(r)^{d-1} 
\hspace{-1ex}
&\tin (B_{\RPMLo})^c,
\end{cases}
\eeq
where, in polar coordinates $(r,\varphi)$,
\beqs
D =
\left(
\begin{array}{cc}
\beta(r)\alpha(r)^{-1} &0 \\
0 & \alpha(r) \beta(r)^{-1}
\end{array}
\right) 
\quad\tand\quad
H =
\left(
\begin{array}{cc}
\cos \varphi & - \sin\varphi \\
\sin \varphi & \cos\varphi
\end{array}
\right) 
\tfor d=2,
