0 & 0 &\alpha(r)
\end{array}
\right) 
\tand
H =
\left(
\begin{array}{ccc}
\sin \varphi \cos\phi & \cos \varphi \cos\phi & - \sin \phi \\
\sin \varphi \sin\phi & \cos \varphi \sin\phi & \cos \phi \\
\cos \varphi & - \sin \varphi & 0 
\end{array}
\right) 
\eeqs
for $d=3$.
(observe that then $A=I$ and $n=1$ when $r=\RPMLo$ and thus $A_\theta$ and $n_\theta$ are continuous at $r=\RPMLo$).

\ble[{\cite[Lemma 2.3]{GLSW1}}]
Let $f_\theta$ satisfy \eqref{e:fProp} 
and the additional assumption when $d=3$ that $f_\theta(r)/r$ is nondecreasing,
