\section{Loop decompositions in directed graphs (Theorem \ref{t:onlyTheSimpleOnes})}

\label{sec:loops}

Fix a matrix $\oldT \in \mathbb{M}(M\times M)$, let $\mathcal{G}$ be the graph associated to $\oldT$ as defined in \S \ref{sec:simple_path_mat} and $\transfer$ the simple-path matrix of $\oldT$. Denote by $\mathbb{P}_{ij}$ the set of paths from $i$ to $j$. Recalling the classical identity 
$$(\oldT^n)_{ij} = \sum_{p \in \mathbb{P}_{ij} \textup{ s.t. } |p|=n}\oldT_p$$
and summing over $n$, one obtains that
$$\left[\sum_{n \in \mathbb{N}} W^n\right]_{ij} = \sum_{p \in \mathbb{P}_{ij}} \oldT_p,$$
provided that the right-hand side converges.
The first inequality in \eqref{e:transfer} then follows immediately. 

To prove the implication in \eqref{e:loop_condition} and the second inequality in \eqref{e:transfer}, it is sufficient to show that 
\begin{equation}
\label{e:transfer_bound}
\sum_{p \in \mathbb{P}_{ij}} \oldT_p \leq\frac{1}{1-c} \transfer_{ij} 
\end{equation}

\subsection{Outline}

We show 
% Lemma \ref{t:onlyTheSimpleOnes}
\eqref{e:transfer_bound} by constructing an injective map
\[\mathcal{D}ec: \mathbb{\mathbb{P}}_{ij} \to
%\begin{cases}
 \mathbb{V}_{ij} \times \mathbb{SL}^{(\mathbb{N})} %, & i\neq j,\\
% \bigcup_{Q = 0}^{+ \infty} (\mathbb{SL})^{Q}, & i=j.
%\end{cases} 
  \]
 where for any set $A$, $A^{(\mathbb{N})}$ denotes the set of finite ordered sequences of elements of $A$ (possibly of size $0$). The map $\mathcal{D}ec$ is defined in Definition \ref{def:loopDec} below, and its properties are stated in Lemma \ref{l:decIsInj}. It corresponds to a decomposition of every path $p \in \mathbb{P}_{ij}$ into a non-intersecting segment 
$v \in \mathbb{V}_{ij}$ and a tuple of simple loops $(L_1,\ldots,L_Q) \in \mathbb{SL}^{(\mathbb{N})}$. The idea is that one obtains the decomposition by recursively removing loops from $p$ until the remainder is non-intersecting.
If one defines 
\begin{equation}
\label{e:extT}
\oldT_{(v,(L_1,\ldots,L_Q))} := \oldT_{v} \oldT_{L_1}\ldots \oldT_{L_Q},	
\end{equation}
then it will be seen that $\oldT_p = \oldT_{\mathcal{D}ec(p)}$ for all $p \in \mathbb{P}_{ij}$. The proof of Lemma \ref{t:onlyTheSimpleOnes} is then obtained as follows:
\[\sum_{p \in \mathbb{P}_{ij}} \oldT_{p} = \sum_{p \in \mathbb{P}_{ij}} \oldT_{\mathcal{D}ec(p)} = \sum_{q \in \mathcal{D}ec(\mathbb{P}_{ij})} \oldT_q \leq \sum_{q \in \mathbb{V}_{ij} \times \mathbb{SL}^{(\mathbb{N})}} \oldT_q\]
since $\mathcal{D}ec$ is injective. The last term can be rewritten as 
\begin{align*}
	 \sum_{q \in \mathbb{V}_{ij} \times \mathbb{SL}^{(\mathbb{N})}} \oldT_q& = \sum_{v \in \mathbb{V}_{ij}} \sum_{Q = 0}^{\infty} \sum_{L_1,\ldots,L_Q \in \mathbb{SL}}\oldT_{v} \oldT_{L_1}\ldots \oldT_{L_Q} = \sum_{v \in \mathbb{V}_{ij}} \oldT_v \sum_{Q = 0}^\infty\left(\sum_{L \in \mathbb{SL}} \oldT_L\right)^Q.
\end{align*}
Therefore if $\left(\sum_{L \in \mathbb{SL}} \oldT_L \right)\leq c < 1$, then
\[\sum_{p \in \mathbb{P}_{ij}} \oldT_{p} \leq \frac{1}{1-c} \sum_{v \in \mathbb{V}_{ij}} \oldT_v = \transfer_{ij}.\]

\subsection{Construction of the map $\operatorname{\cD ec}$}

For $1 \leq \ell \leq m \leq \abs{p}+1$, the {\em splice} of $p$ between $\ell$ and $m$, denoted by $p{[\ell,m)}$, is the path obtained from $p$ by only keeping the edges from $\ell$ to $m-1$, that is 
\[p{[\ell,m)} := e_{\ell} e_{\ell+1}\ldots e_{m-1},\]
with the convention that $p{[\ell,\ell)} = \mathbf{0}$. Given two paths $p = e_1 e_2\ldots e_{\abs{p}}$ and $q = f_{1}f_{2}\ldots f_{\abs{q}}$ such that $p(\abs{p}+1) = q(1)$, the {\em concatenation} of $p$ and $q$ is defined by
\[p\cdot q = e_1e_2\ldots e_{\abs{p}} f_{1} f_2\ldots f_{\abs{q}},\]
with the convention that for all paths $p$,
$p \cdot \mathbf{0} = \mathbf{0} \cdot p = p.$
In particular, for all $p,q \in \mathbb{P}$, $$|p\cdot q| = |p| + |q|.$$ 
Furthermore, when $m>\ell$, $p{[\ell,m)}$ is a path from $p(\ell)$ to $p(m)$, and for all $1 \leq \ell \leq |p|+1$, 
$$p = p[1,\ell) \cdot p[\ell,|p|+1).$$
If $p(\ell) = i_0$ and $L_{i_0}$ is either $\mathbf{0}$ or a loop through $i_0$, one can then define the {\em insertion of $L_{i_0}$ in $p$ at index $\ell$} by
\begin{equation*}
	p\overset{{\ell}}{\leftharpoonup}L_{i_0} := p{[1,\ell)}\cdot L_{i_0}\cdot p{[\ell,\abs{p}+1)}.
\end{equation*}

To extract the first loop of a self-intersecting path, one can ``follow" the path until some vertex $i_\times$ occurs for the second time. One then backtracks to the first occurence of that vertex, and the splice in between those two occurences defines a simple loop that can be extracted from $p$. More precisely, let
\[\ell_\times(p) := \inf \Big\{\ell \in \{1,\ldots,|p|+1\} \,: p(\ell) \in \{p(1),\ldots,p(\ell-1)\}\Big\},\]
the {\em index of first crossing}. Note that $\ell_\times(p) = \infty$ if, and only if, $p$ is non-intersecting. If $\ell_\times(p) < \infty$,  define $i_\times(p):= p(\ell_\times(p))$ the {\em first crossing point} of $p$, and  
\[\ell_0(p) := 
	\inf\Big\{\ell \in \{0,\ldots,\abs{p}+1\} \,: p(\ell) = i_\times(p)\Big\}\]
the first index at which $p$ visits $i_\times(p)$. These definitions are illustrated in Figure \ref{f:defIcross}. Define the maps $L: \mathbb{P}\to \mathbb{P}$ and $E:\mathbb{P} \to \mathbb{P}$ by\\
\begin{minipage}{0.65\textwidth}
	\begin{itemize}
		\item $L(p) := \begin{cases}
			p[\ell_0(p),\ell_\times(p)) & \textup{if } \ell_\times(p) < \infty,\\[1em]
			\mathbf{0} & \textup{if } \ell_\times(p) = \infty.
		\end{cases} 
		$\\[1em]
		the {\em first loop} in $p$, and\\[1em]
		\item $	E(p) := \begin{cases}
			p[1,\ell_0(p))\cdot p[\ell_\times(p),\abs{p}+1) & \textup{if } \ell_\times(p) < \infty,\\[1em]
			p & \textup{if } \ell_\times(p) = \infty,
		\end{cases}$\\[1em]
		the remainder after extracting the loop $L(p)$.
	\end{itemize}
\end{minipage}
\hfill
\begin{minipage}{0.3\textwidth}
	\begin{figure}[H]
		\centering
		\includegraphics[width=\textwidth]{Asymptote/graphExample.pdf}
		\caption{Example of a self-intersecting path. Here, $\ell_0(p) = 5$ and $\ell_\times(p) = 8$. The vertices of $L(p)$ are highlighted in red.}
		\label{f:defIcross}
	\end{figure}
\end{minipage}\\[1em]
The properties of $L$ and $E$ are summarized in the following lemma.  
The proof is immediate from the definitions.
\begin{lemma}
	\label{l:recreate2}
	For all paths $p$, 
	\[p = E(p)\overset{{\ell_0(p)}}{\leftharpoonup}L(p),\]
	\[\abs{p} = \abs{E(p)} + \abs{L(p)} \quad \tand \quad \oldT_p = \oldT_{L(p)} \oldT_{E(p)}.\]
	%If $\abs{p} > 0$, then $L(p) \in \mathbb{SL}$, $\abs{L(p)} \geq 1$ and $\abs{E(p)} \leq \abs{p}-1$.
	The path $p$ is non-intersecting if, and only if, $L(p) = \mathbf{0}$, in which case, $p = E(p)$. Otherwise, $L(p) \in \mathbb{SL}$, $|L(p)|\geq 1$ and
	\[\ell_0(p) = \inf\Big\{\ell \in \{0,\ldots,\abs{E(p)}+1\}\,: \big(E(p)\big)(\ell) =\big(L(p)\big)(1)\Big\}.\]
	If $p \in \mathbb{P}_{ij}$, then either 
	\begin{enumerate}
		\item $E(p) \in \mathbb{P}_{ij}$, or
		\item $E(p) = \mathbf{0}$, and this can only occur if $i = j$. 
	\end{enumerate}
\end{lemma}
Define $E^n(p) := E(E^{n-1}(p))$, with $E^0(p) := p$. 
\begin{corollary}
	\label{c:numberLoops}
	Let $p \in \mathbb{P}$. Then there exists a unique number $n_0 \in \mathbb{N}$, the {\em number of loops in $p$}, such that the following properties hold:
	\begin{itemize}
		\item  either $n_0 = 0$ or $E^{n_0 - 1}(p) \neq E^{n_0}(p)$,
		\item for all $n \geq n_0$, $E^n(p) = E^{n_0}(p)$.
	\end{itemize}  
\end{corollary}
\begin{proof}
	If $E^{n+1}(p) \neq E^n(p)$, then by Lemma \ref{l:recreate2}, $|E^{n+1}(p)| \leq |E^n(p)| - 1$. Since infinite sequences of natural numbers cannot be strictly decreasing, the sequence $(E^n(p))_n$ must eventually stagnate. 
\end{proof}
\begin{corollary}
	\label{c:recreate2}
	The map 
	\[\begin{array}{llll}
		\textup{Dec}:&\mathbb{P}\times \mathbb{P}^{(\mathbb{N})} &\to& \mathbb{P}\times \mathbb{P}^{(\mathbb{N})}\\
		&p,(L_1,\ldots,L_Q) & \mapsto & E(p), (L_1,\ldots,L_Q,L(p))
	\end{array}\]
	is injective. If $X \in \mathbb{P} \times \mathbb{P}^{(\mathbb{N})}$ and if $\oldT_X$ is defined as in \eqref{e:extT}, then 
	\begin{equation}
		\label{e:conserv}
		\oldT_{\operatorname{Dec}(X)} = \oldT_{X}.
	\end{equation}
\end{corollary}
\begin{proof}
	Suppose that
	\[(E(p),(L_1,\ldots,L_Q,L(p))) = (E(p'),(L_1',\ldots,L_Q',L(p')))\]
	and let $E = E(p) = E(p')$ and $L = L(p) = L(p')$. To conclude, it suffices to show that $p = p'$ (since it is obvious that $L_i = L'_i$ for $1 \leq i \leq Q$). There are two cases: either $|L| = 0$ or $|L|\geq 1$. By Lemma \ref{l:recreate2}, in the first case, $E = p = p'$. In the second case, since $E(p)=E(p')$ and $L(p)=L(p')$, 
	\[\ell_0(p) = \ell_0(p') = \inf\Big\{\ell \in \{0,\ldots,\abs{E}+1\}\,: E(\ell) =L(1)\Big\} =:\ell_0 \]
	and $p = p' = E\overset{{\ell_0}}{\leftharpoonup}L$. Thus in both cases, $p = p'$. 
	The proof of \eqref{e:conserv} is immediate.
\end{proof}\
\begin{definition}[Loop decomposition of a path]
	\label{def:loopDec}
	Given $p \in \mathbb{P}$, the {\em loop-decomposition} of $p$, denoted by $\operatorname{\mathcal{D}ec}(p) \in \mathbb{P} \times \mathbb{P}^{(\mathbb{N})}$, is defined by
	\[\operatorname{\mathcal{D}ec}(p) := \operatorname{Dec}^{n_0}(p,\varnothing)\]
	where $\varnothing$ is the empty sequence of paths, and $n_0$ is the number of loops in $p$. 
\end{definition}
\begin{lemma}
	\label{l:decIsInj}
	For all $p \in \mathbb{P}_{ij}$, $\operatorname{\cD ec}(p) \in \mathbb{V}_{ij} \times \mathbb{SL}^{(\mathbb{N})}$, and 
	\begin{equation}
		\label{e:conserv2}
		\oldT_{\operatorname{\cD ec}(p)} = \oldT_p.
	\end{equation} 
	Furthermore, the map 
	$\operatorname{\cD ec} : \mathbb{P} \to \mathbb{V} \times \mathbb{SL}^{(\mathbb{N})}$
	is injective. 
\end{lemma}
\begin{proof}
	Write $\operatorname{Dec}^{n_0}(p,\varnothing) = (v,(L_1,\ldots,L_{n_0}))$, and observe that $v = E^{n_0}(p)$. If $v$ were self-intersecting, then it would follow that $E^{n_0+1}(p) \neq E^{n_0}(p)$, contradicting Corollary \ref{c:numberLoops}. Thus, $v \in \mathbb{V}$. If $p \in \mathbb{P}_{ij}$ then either $i \neq j$, in which case it follows by \ref{l:recreate2} that $v \in \mathbb{V}_{ij}$, or $i = j$ in which case $v = \mathbf{0}$ (otherwise we would have an non-intersecting path in $\mathbb{P}_{ii}$, which is impossible). On the other hand, one can check easily by induction that 
	\[L_1 = L(p),\quad L_2 = L(E(p)), \quad \ldots\quad L_{n_0} = L(E^{n_0-1}(p)),\]
	and thus, by Lemma \ref{l:recreate2}, for $1 \leq i \leq n_0$, $L_i$ is either $\mathbf{0}$ or a simple loop. But $L_i$ cannot be $\mathbf{0}$, since this would imply that $E^{i-1}(p) = E^i(p)$, contradicting again Corollary \ref{c:numberLoops}. Thus $L_1,\ldots,L_{n_0} \in \mathbb{SL}$. 

The relation \eqref{e:conserv2} follows immediately from \eqref{e:conserv}. 

	Finally, suppose that $\operatorname{\mathcal{D}ec}(p) = \operatorname{\cD ec}(p')$. Then $p$ and $p'$ have the same number of loops $n_0$ (otherwise, the list of loops in their loop-decomposition could not be the same) and thus 
	$\operatorname{\cD ec}(p) = \operatorname{Dec}^{n_0}(p,\varnothing)$, $\operatorname{\cD ec}(p') = \operatorname{Dec}^{n_0}(p',\varnothing)$ and therefore
	\[\operatorname{Dec}^{n_0}(p,\varnothing) = \operatorname{Dec}^{n_0}(p',\varnothing)\]
	But since $\operatorname{Dec}$ is injective (by Corollary \ref{c:recreate2}), $\operatorname{Dec}^{n_0}$ is injective, and thus it must be that $p = p'$. 
	\end{proof}

\section{Proofs of the local bounds on the solution operator (Theorems \ref{thm:DV} and \ref{thm:PML})}\label{app:help}

In this section we prove Theorems \ref{thm:DV} and \ref{thm:PML}. In fact, we prove a stronger 
analogue of Theorem \ref{thm:DV} phrased using semiclassical pseudodifferential operators -- i.e., pseudodifferential operators in a calculus where each derivative is weighted by $k^{-1}$. Furthermore, because we work on a bounded domain, we need a special class of pseudodifferential operators adapted to the boundary. 

\subsection{Pseudodifferential operators and $b$-pseudodifferential operators}

\subsubsection{Semiclassical pseudodifferential operators.}
Semiclassical pseudodifferential operators are generalisations of Fourier multipliers acting as
$$
\Op(a)u(x):=\frac{1}{(2\pi h)^d}\int e^{\frac{i}{h}\langle x-y,\xi\rangle}a(x,\xi)u(y)dyd\xi,
$$
where, for some $m\in \mathbb{R}$, $a$ satisfies
$$
|\partial_x^\alpha \partial_\xi^\beta a(x,\xi)|\leq C_{\alpha \beta}\langle \xi\rangle^{m-|\alpha|}.
$$ 
In this case we write $a\in S^m(T^*\mathbb{R}^d)$ and $\Op(a)\in \Psi^m(\mathbb{R}^d)$. When $m=0$ we write $S(T^*\mathbb{R}^d)$ and $\Psi(\mathbb{R}^d)$ respectively. This class of pseudodifferential operators is the natural class of operators generalising quantization of $b(x)(hD)^\alpha$ for some $b\in C^\infty(\mathbb{R}^d)$ and $\alpha\in\mathbb{N}^d$. For more details and information about the calculus of such operators see e.g.~\cite[Appendix E]{DyZw:19} and~\cite{Zw:12}.


The class of $b$-pseudodifferential operators that we work with is, instead, the natural class of operators quantizing differential operators that are tangential to the boundary of $\Omega_+$. Away from $\partial\Omega_+$ they are pseudodifferential operators in the sense above, but near $\partial\Omega_+$ they have a different form. In particular, in coordinates $(x_1,x')$ with $\partial\Omega_+=\{x_1=0\}$, their symbols are functions on the $b$-cotangent bundle, ${}^bT^*\Omega_+$, whose sections are of the form
$$
\sigma \frac{d x_1}{x_1}+\xi' dx'.
$$
Notice that ${}^bT^*\Omega_+$ is the dual to sections of $T^*\Omega_+$ that are tangent to $\partial\Omega_+$. We also write ${}^b\overline{T^*\Omega_+}$ for the fiber radially compactified $b$-contangent bundle; i.e., ${}^bT^*\Omega_+$ with the sphere at infinity in $(\sigma, \xi')$ attached.



%There is a natural inclusion $\pi^b:T^*\Omega_+\to {}^bT^*\Omega_+$ which, in coordinates, is given by $(x,\xi)\mapsto (x,x_1\xi_1,\xi')$ and whose image is denoted by ${}^b\dot{T}^*\Omega_+$. 
In coordinates, $b$-pseudodifferential operators are of the form
$$
\Op_{b}(a)(u)(x)=\frac{1}{(2\pi h)^d}\int e^{\frac{i}{h}((x_1-y_1)\xi_1+(x'-y'),\xi')}\phi(x_1/y_1)a(x_1,x',x_1\xi_1,\xi')u(y)dyd\xi,
$$
where $\phi\in C_c^\infty(1/2,2)$ with $\phi\equiv 1$ near $1$  and for some $m$
$$
|D_{x}^\alpha D_\sigma^j D_{\xi'}^\beta a(x_1,x',\sigma,\xi')|\leq C_{j\alpha\beta}\langle (\sigma,\xi')\rangle^{m-j-|\beta|}.
$$
In this case, we write $\Op_{b}(a)\in \Psi_b^m(\Omega_+)$ and $a\in S^m({}^bT^*\Omega_+)$. When $m=0$ we write $S({}^bT^*\Omega_+)$ and $\Psi_b(\Omega_+)$ respectively. We also write $\Psi_b^{-\infty}=\cap_m \Psi_b^m$. 

 The class comes equipped with principal symbol map ${}^b\sigma: {}^b\Psi^m(\Omega_+)\to S^m({}^bT^*\Omega_+)/ h {}^bS^{m-1}(T^*\Omega_+)$ such that if $A\in\Psi_b(\Omega_+)$ and $\sigma(A)=0$ then $A\in h\Psi_b^{m-1}(\Omega_+)$. We now introduce two important sets for $b$-pseudodifferential operators. For $A\in \Psi_b^m(\Omega_+)$ and $q\in {}^b\overline{T^*\Omega_+}$, we say $q\in {}^b\Ell(A)$ if there is a neighbourhood, $U$ of $q$ such that
$$
|\sigma(A)(q')|\langle (\sigma,\xi')\rangle^{-m}>c>0,\qquad q'\in U\cap {}^bT^*\Omega_+.
$$ 
Next, we say $q\notin {}^b\WF(A)$ if there is $E\in {}^b\Psi(\Omega_+)$ with $q\in {}^b\Ell(E)$ such that 
$$
EA\in h^\infty \Psi_b^{-\infty}.
$$ 
For a more complete treatment of these operators, we refer the reader to~\cite[Appendix A]{HiVa:18} and the references therein.

\subsubsection{The generalised bicharacteristic flow on ${}^bT^*\Omega_+$.}

Let $p_\theta\in S^2(T^*\Omega)$ denote the semiclassical principal symbol of $P_k$ and observe that on $B(0,R_{\operatorname{scat}})$, $p_\theta = \sum_{ij}g^{ij}(x)\xi_i\xi_j-1$, where $g^{-1}(x)=A(x)/n(x)$. 
We then let $\varphi_t:\pi^b\{\Re p_\theta=0\}\to \pi^b\{\Re p_\theta=0\}$ be the generalised bicharacteristic flow for $\Re p_\theta$ in the sense of~\cite[Definition 1.1]{Va:08}. 

We are now in a position to define the \emph{forward and backward trapped sets} $\Gamma_-$ and $\Gamma_+$, respectively,
$$
\Gamma_{\pm}:=\Big\{ q\in \pi^b(\{ \Re p_\theta=0\})\,: \sup \{t>0\,:\, \varphi_{\mp t}(q)\in {}^bT^*\Omega\}=\infty\Big\},
$$
as well as the trapped set,
$$
K:=\Gamma_+\cap \Gamma_-.
$$
One can show that $\Gamma_{\pm}$ and hence $K$ are closed (see e.g.~\cite[Proposition 6.3]{DyZw:19}).

\bre 
For this flow to exist, we assume that $\partial\Omega$ has no infinite order tangency with the Hamiltonian bicharacteristics of $\Re p_\theta$.  By~\cite[Theorem 24.3.9]{Ho:85} this suffices for the flow to be unique and by~\cite[Example 24.3.11]{Ho:85} uniqueness may fail in the opposite case.

We highlight that the definitions of $K$ and $\Gamma_\pm$, and the statements of Theorems \ref{thm:negligible2} and \ref{thm:negligible3}
below can all be rewritten without the need for uniqueness of the flow (with the results of the theorems
still true); however, for simplicity we do not do this.
\ere

