\subsection{Estimates away from the scatterer}

We start by proving an estimate `deep' in the PML region; i.e. near the truncation boundary. 
\begin{lemma}
\label{l:nearPMLBoundary}
There exists $U\subset \Omega$ such that $\overline{U}$ is a neighbourhood of $\Gamma_{\tr}$ and for all $k_0>0$, $\psi,\widetilde{\psi}\in C^\infty(\Omega)$ with $\supp \psi,\supp\widetilde\psi\subset U$, $\psi\prec \widetilde\psi$, and $\supp (1-\psi)\cap \partial\Omega=\emptyset$, there exists $C>0$ such that for $k>k_0$,
\begin{equation}
\label{e:nearPMLByAway}
\|\psi u\|_{H_k^1}\leq C\Big(\| \widetilde\psi P_k u\|_{L^2}+Ck^{-N}\| u\|_{H_k^{-N}}\Big).
\end{equation}
\end{lemma}
\begin{proof}
By~\cite[Lemma 4.4]{GLS2}, there is $U$ with $\overline{U}$ a neighbourhood of $\partial \Omega_{\tr}$ such that for $v\in H_k^1(\Omega)$ with $v|_{\Gamma_{\tr}}=0$ and $\supp v\subset U$,
\begin{equation}
\label{e:PMLImport}
\|v\|_{H_k^1}\leq C\|P_k v\|_{L^2}.
\end{equation}
%The by boundary elliptic regularity, for any $m\geq 2$, 
%\begin{equation}
%%\label{e:PMLImport}
%\|v\|_{H_k^{m}}\leq C\|Pv\|_{H_k^{m-2}}.
%\end{equation}
Let $\psi_j\in C^\infty_c(U)$ be such that $\psi_1\prec\psi_2\prec\widetilde\psi$ and $\supp(1-\psi_1)\cap \supp \partial \psi=\emptyset$.
Applying \eqref{e:PMLImport} with $v= \psi u$, we obtain 
\beq\label{e:actualLastDay1}
\|\psi u\|_{H_k^1}\leq C\|P_k\psi u\|_{L^2}\leq C\big(\|\psi P_ku\|_{L^2}+\big\| [P_k, \psi] u\big\|_{L^2}\big)
\leq C\big(\|\psi P_ku\|_{L^2}+ Ck^{-1}\| \psi_1 u\|_{H_k^1}\big)
\eeq
Now, shrinking $U$ if necessary so that 
$$
\{x\in U\,:\, \text{ there exists }\xi \text{ such that }p_\theta(x,\xi) = 0 \} =\emptyset,
$$
the elliptic parametrix construction~\cite[Proposition E.32]{DyZw:19} implies that
\beq\label{e:actualLastDay2}
\|\psi_1 u\|_{H^1_k}\leq C\|\psi_2P_ku\|_{L^2}+Ck^{-N}\|u\|_{H_k^{-N}},
\eeq
and the result follows by combining \eqref{e:actualLastDay1} and \eqref{e:actualLastDay2}.
\end{proof}

\

We now prove Theorem \ref{thm:PML}.

\

\bpf[Proof of Theorem \ref{thm:PML}]
The bound $\|\chi R_k\|_{L^2\to L^2}\leq C$ follows immediately from \eqref{e:nearPMLByAway}, with the bound $\|R_k\chi \|_{L^2\to L^2}\leq C$ then following by applying the previous bound with $P_k$ replaced by $P_k^*$. 

The bound $\|\chi R_k\psi\|_{L^2\to H^1_k}\leq Ck^{-N}$ also follows immediately from \eqref{e:nearPMLByAway}, with then the bound $\|\chi R_k\psi\|_{L^2\to H^N_k}\leq Ck^{-N}$ following by elliptic regularity up to the boundary. 

Finally, the bound $\|\psi R_k\chi\|_{L^2\to L^2}\leq Ck^{-N}$ follows by applying the  bound 
$\|\chi R_k\psi\|_{L^2\to L^2}\leq Ck^{-N}$
with $P_k$ replaced by $P_k^*$, and then the bound $\|\psi R_k\chi\|_{L^2\to H^N_k}\leq Ck^{-N}$ follows by elliptic regularity up to the boundary. 
\epf

\

Next, we prove an estimate near incoming points away from the truncation boundary.

\begin{lemma}
\label{l:outgoing}
Let $m\geq 2$, $\chi\in C_c^\infty(\Omega\setminus \overline{B(0,R_{\operatorname{scat}}}))$ (where $R_{\rm scat}$ is defined by \eqref{e:Rscat}). Then there is $\epsilon>0$ such that for $A,B\in \Psi^0$ with 
$$
\WF(A)\cap \Big\{ \big\langle \tfrac{x}{|x|},\xi\big\rangle\geq \e,\,p_\theta(x,\xi)=0\Big\}=\emptyset,
$$
$$
\WF(A)\cup \bigcap_{t\geq 0}\big\{(x-t\xi,\xi)\,:\, (x,\xi)\in \WF(A)\cap \{p_\theta=0\}\big\}\cap\{p_\theta=0\}\subset\operatorname{Ell}(B)
$$
and $N>0$, given $k_0>0$ there exists $C>0$ such that for all $k\geq k_0$
$$
\|A\chi u\|_{H_k^m}\leq Ck\|BP_ku\|_{H_k^{m-2}}+Ck^{-N}\|u\|_{H_k^{-N}}.
$$
\end{lemma}
\begin{proof}Since 
$$
\WF(A)\cap \Big\{ \langle \tfrac{x}{|x|},\xi\rangle\geq \e,\,p_\theta(x,\xi)=0\Big\},
$$ 
there is a neighbourhood, $V$ of $\{p_\theta=0\}$ such that 
$$
\WF(A\chi )\cap V\subset\{ \langle \tfrac{x}{|x|},\xi\rangle< 2\e\}.
$$
In particular, for $(x,\xi)\in \WF(A\chi)\cap V$, and $t\geq 0$,
$$
|x-t\xi|^2=|x|^2-2t|x|\langle \tfrac{x}{|x|},\xi\rangle +t|\xi|^2\geq |x|^2-4t|x|\e+t^2\geq |x|^2(1-2\e)+t^2(1-2\e).
$$
Therefore, there is $T>0$ such that for all $(x,\xi)\in\WF(A\chi)\cap V$, there is $0\leq t\leq T$ such that $(x-t\xi,\xi)\notin \{p_\theta=0\}$. Using a microlocal partition of unity on $\WF(A\chi)\cap V$, $\{X_j\}_{j=1}^N$, there are $0<T_j\leq T$ and $E_j\in \Psi^{\comp}$ with $\WF(E_j)\subset \{p_\theta\neq 0\}\cap \Omega_{\tr}\cap \operatorname{Ell}(B)$ such that
$$
\{ (x-t\xi,\xi)\,:\, (x,\xi)\in \WF(AX_j\chi)\cap V,\, 0\leq t\leq T_j\}\subset \operatorname{Ell}(B)
$$
and 
$$
 \{ (x-T_j\xi,\xi)\,:\, (x,\xi)\in \WF(AX_j\chi)\cap V\}\subset \operatorname{Ell}(E_j).
$$


%Letting $U$, $\psi$, and $\psi_1$ as in Lemma~\ref{l:nearPMLBoundary} such that $\supp \psi_1\subset \Omega\setminus \overline{B(0,R_{PML_-})}$, there is $T>0$ such that for all $(x,\xi)\in \WF(A\chi)\cap V$, there is $0\leq t\leq T$ such that $x-t\xi\in \{\psi\equiv 1\}$. 

Now, let $X\in \Psi^{\comp}$ with $\WF(X)\subset V$ and $\WF(I-X)\cap \{p_\theta=0\}=\emptyset$. Then, by the elliptic parametrix construction~\cite[Proposition E.32]{DyZw:19}
\begin{equation}
\label{e:high}
\|(I-X)A\chi u\|_{H_k^m}\leq C\|BP_ku\|_{H_k^{m-2}}+Ck^{-N}\|u\|_{H_k^{-N}}.
\end{equation}
On the other hand, using that $X\in \Psi^{\comp}$ and then that $\Im p_\theta \leq 0$ near $p_\theta=0$, by~\cite[Theorem E.47]{DyZw:19} we have
\begin{equation}
\label{e:low}
\|XAX_j\chi u\|_{H_k^m}\leq C\|XAX_j\chi u\|_{H_k^{-N}}+Ck^{-N}\|u\|_{H_k^{-N}}\leq Ck\|BP_ku\|_{L^2}+\|E_j u\|_{L^2}+Ck^{-N}\|u\|_{H_k^{-N}}.
\end{equation}
Finally, since $\WF(E_j)\subset \{p_\theta\neq 0\}\cap \operatorname{Ell}(B)$, we have
\begin{equation}
\label{e:low2}
\|E_j u\|_{L^2}\leq C\|BP_ku\|_{L^2}+Ck^{-N}\|u\|_{H_k^{-N}}.
\end{equation}
Combining~\eqref{e:high},~\eqref{e:low}, and~\eqref{e:low2}, and summing in $j$,
$$
\|A\chi u\|_{H_k^m}\leq Ck\|BP_ku\|_{H_k^{m-2}}+Ck^{-N}\|u\|_{H_k^{-N}}.
$$


\end{proof}

We now prove the key propagation lemma that allows us to improve resolvent estimates away from trapping. In particular, we estimate $u$ in an annulus away from $\Omega_-$ but inside $B(0,R_{\operatorname{PML}_-})$ 
\begin{lemma}
\label{l:DV}
Let $R_{\operatorname{PML}_+}>R_{\operatorname{PML}_-}$ with $B(0,R_{\operatorname{PML}_+})\Subset \Omega_{\tr}$, $a\in C_c^\infty((R_{\operatorname{scat}},R_{\operatorname{PML}_-}))$ and $b\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_+})$ with 
$$
b\equiv 1 \text{ on } \{ x\in (R_{\operatorname{scat}}, R_{\operatorname{PML}_-})\,:\, x\geq \inf \supp a\}.
$$ 
and define $A=a(|x|)$, $B=B(|x|)$. Then, for $X\in {}^b\Psi^0$ with ${}^b\WF(I-X)\cap {}^b\WF(P_ku)=\emptyset$, given $k_0>0$ there exists $C>0$ such that for all $k\geq k_0$
$$
\|A u\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\|X u\|_{L^2}+Ck^2\|BP_ku\|_{L^2}^2+C_Nk^{-N}\|u\|^2_{L^2}.
$$
\end{lemma}
\begin{proof}
Let  $a,b_1\in C_c^\infty((R_{\operatorname{scat}},R_{\operatorname{PML}_-}))$ with 
$a\prec b_1$,
$\supp b_1\cap \{b<\tfrac{1}{2}\} =\emptyset$. Let $b_2\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_+})$ with $\supp b_2\cap \{b<\frac{1}{2}\}=\emptyset$ and 
$$
b_2\equiv 1 \text{ on } \big\{ x\in (R_{\operatorname{scat}}, R_{\operatorname{PML}_-})\,:\, x\geq \inf \supp b_1\big\}.
$$ 
Let $A=a(|x|)$ and $B_j=b_j(|x|)$, $j=1,2$.  We claim that 
\begin{equation}
\label{e:step1DV}
c\|Au\|_{H_k^s}^2\leq Ck\|P_ku\|_{L^2}\| Xu\|_{L^2}+k^2\|B_2P_ku\|_{L^2}^2+Ck^{-1}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{L^2}^2.
\end{equation}
To establish \eqref{e:step1DV}, first let $g\in C_c^\infty(\mathbb{R})$ with $\supp g\subset  [0, R_{\operatorname{PML}_-})$, $g\geq 0$, $g'\leq 0$, $\supp g'\subset (R_{\operatorname{scat}},R_{\operatorname{PML}_-})$ 
$g'\leq -1$ on $\supp a$, and $\supp(1-b_1)\cap \supp g'=\emptyset$. Next, let $E\in \Psi^{0}$ with $0\leq \sigma(E)\leq 1$, and
\begin{gather*}
\WF(E)\subset \Big\{(x,\xi)\,: \, \langle \tfrac{x}{|x|},\xi\rangle<2 \e\langle\xi\rangle\Big\},\qquad \WF(I-E)\cap \Big\{ (x,\xi)\,:\,\langle \tfrac{x}{|x|},\xi\rangle<\e\langle\xi\rangle\Big\}=\emptyset.
\end{gather*}
Finally, let $b_0\in C_c^\infty ((R_{\operatorname{scat}},R_{\operatorname{PML}_-})$ with 
$g' \prec b_0\prec b_1$.

Put $G= g(|x|)$, $B_0=b_0(|x|)$ and consider 
$$
k\Im \big\langle P_ku,G^2 u\big\rangle = \frac{k}{2i}\big\langle [P_k,G^2]u,u\big\rangle=\frac{k}{2i}\big\langle B_0[P_k,G^2]B_0B_1u,B_1u\big\rangle. $$
Now, define $Z:=\frac{k}{2i}B_0[P_k,G^2]B_0\in \Psi^1$ and observe that
\begin{align*}
\sigma(Z)=b_0^2g(|x|)\langle \xi,\partial_xg(|x|)\rangle &= b_0^2g(|x|)\langle \xi,\tfrac{x}{|x|}\rangle g'(|x|)\\
&=b_0^2\Big(g(|x|)\langle \xi,\tfrac{x}{|x|}\rangle g'(|x|)(1-\sigma(E^2))+g(|x|)\langle \xi,\tfrac{x}{|x|}\rangle g'(|x|)\sigma(E^2)\Big)\\
&\leq b_0^2\Big(-c\e a^2\langle\xi\rangle(1-\sigma(E^2))+g(|x|)\langle \xi,\tfrac{x}{|x|}\rangle g'(|x|)\sigma(E^2)\Big)\\
&\leq b_0^2\Big(-c\e a^2\langle\xi\rangle+C\sigma(E^2)|\xi|\Big)\\
&\leq b_0^2\Big(-c\e a^2\langle \xi\rangle+C\sigma(E^2)\langle \xi\rangle + Cp_\theta^2\Big)
\end{align*}
Therefore, by the microlocal G\aa rding inequality~\cite[Proposition E.34]{DyZw:19}, 
$$
\frac{k}{2i}\langle [P_k,G^2]B_1u,B_1u\rangle \leq -c_\e\|B_0AB_1u\|_{H^1_k}^2+C\|B_0EB_1u\|_{H^1_k}^2 +C\|B_0P_kB_1u\|_{L^2}^2 +Ck^{-1}\|B_1u\|_{L^2}^2
$$
Thus, since $a\prec b_0\prec b_1$ and ${}^b\WF(I-X)\cap {}^b\WF(P_ku)=\emptyset$,
$$
c_\e\|A u\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\| G  X u\|_{L^2}+C\|EB_1u\|_{H^1_k}^2+C\|B_1P_ku\|_{L^2}^2+Ck^{-1}\|B_1u\|_{L^2}^2 +Ck^{-N}\|u\|_{H_k^{-N}}^2
$$
Then, by Lemma~\ref{l:outgoing}, 
$$
c_\e\|Au\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+ Ck^2\| B_2P_ku\|_{L^2}^2+Ck^{-1}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2
$$
as claimed in \eqref{e:step1DV}.

Now, suppose by induction that for  $a,b_1\in C_c^\infty((R_{\operatorname{scat}},R_{\operatorname{PML}_-}))$ with $a\prec b_1$ and $b_2\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_+})$ with $\supp b_2\cap \{b<\frac{1}{2}\}=\emptyset$ and 
$$
b_2\equiv 1 \text{ on } \Big\{ x\in (R_{\operatorname{scat}}, R_{\operatorname{PML}_-})\,:\, x\geq \inf \supp b_1\Big\},
$$ we have, with $A=a(|x|)$ and $B_1=b_1(|x|)$, $B_2=b_2(|x|)$, 
\begin{equation}
\label{e:step2DV}
c\|Au\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+Ck^2\|B_2 P_ku\|_{L^2}^2+Ck^{-L}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2.
\end{equation}

Now, fix $a,b_1\in C_c^\infty((R_{\operatorname{scat}},R_{\operatorname{PML}_-}))$ with $a\prec b_1$, and $b_2\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_+})$ with $\supp b_2\cap \{b<\frac{1}{2}\}=\emptyset$ and 
$$
b_2\equiv 1 \text{ on } \big\{ x\in (R_{\operatorname{scat}}, R_{\operatorname{PML}_-})\,:\, x\geq \inf \supp b_1\big\}.
$$


Then, by~\eqref{e:step2DV}, letting $\widetilde{b}_1\in C_c^\infty((R_{\operatorname{scat}},R_{\operatorname{PML}_-})) $ with 
$a\prec \widetilde{b}_1 \prec b_1$
%$\supp (1-\widetilde{b}_1)\cap \supp a=\emptyset$, $\supp (1-b_1)\cap \supp \widetilde{b}_1=\emptyset$, 
and $\widetilde{b}_2\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_+})$ with $\supp \widetilde{b}_2\cap \{b_2<\frac{1}{2}\}=\emptyset$ and 
$$
\widetilde{b}_2\equiv 1 \text{ on } \{ x\in (R_{\operatorname{scat}}, R_{\operatorname{PML}_-})\,:\, x\geq \inf \supp \widetilde{b}_1\},
$$
by~\eqref{e:step2DV} with $A=a(|x|)$ and $\widetilde{B}_1=b_1(|x|)$, $\widetilde{B}_2=b_2(|x|)$, 
\begin{equation*}
c\|Au\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+Ck^2\|\widetilde{B}_2P_ku\|_{L^2}^2+Ck^{-L}\|\widetilde{B}_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2.
\end{equation*}
Now, by~\eqref{e:step1DV} with $A$ replaced by $\widetilde{B}_1$, 
\begin{equation*}
c\|\widetilde{B}_1u\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+Ck^{-1}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2.
\end{equation*}
Hence,
\begin{equation*}
\begin{aligned}c\|Au\|_{L^2}^2&\leq Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+Ck^2\|\widetilde{B}_2P_ku\|_{L^2}^2+Ck^{-L-1}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2\\
&\leq  Ck\|P_ku\|_{L^2}\| X u\|_{L^2}+Ck^2\|B_2P_ku\|_{L^2}^2+Ck^{-L-1}\|B_1u\|_{L^2}^2+Ck^{-N}\|u\|_{H_k^{-N}}^2;
\end{aligned}
\end{equation*}
we have therefore obtained \eqref{e:step2DV} with $L$ replaced by $L+1$, and the result then follows by induction.
\end{proof}


\subsection{Estimates near the scatterer and away from trapping}


Before proceeding, we record the following consequences of~\cite[Proposition 4.6, Theorems 8.1 and 8.5]{Va:08}.
\begin{theorem}\label{l:ellipticVasy}
Let $A,E\in {}^b\Psi(\Omega)$ with ${}^b\WF(A)\cup{}^b\WF(E)\subset \Omega_{\tr}$ with ${}^b\WF(A)\subset {}^b\Ell(E)$ and ${}^b\WF(A)\cap {}^b\pi(\{p_\theta=0\})=\emptyset$. Then, for all $k_0>0$ there exists $C>0$ such that 
$$
\|Au\|_{L^2}\leq C\|EP_ku\|_{L^2}+C_Nk^{-N}\|u\|_{L^2}
$$
\end{theorem}
\begin{proof}
The estimate follows from~\cite[Proposition 4.6]{Va:08} when ${}^b\WF(A)\subset B(0,R_{\operatorname{scat}})$ and from the standard elliptic parametrix construction~\cite[Proposition E.32]{DyZw:19}, when ${}^b\WF(A)\cap T^*\partial \Omega_-=\emptyset$. 
\end{proof}

\begin{theorem}\label{l:propagateVasy}
Let $A,B,E\in {}^b\Psi(\Omega)$ such that 
\begin{gather*}
{}^b\WF(A)\cup\bigcup_{t=0}^T \varphi_{-t}({}^b\WF(A)\cap\pi^b(\{ \Re p_\theta=0\})\subset {}^b\Ell(E),\\
\text{ and for all }  q\in {}^b\WF(A)\cap\pi^b(\{ \Re p_\theta=0\}),\qquad \bigcup_{t=0}^T\varphi_{-t}(q)\cap {}^b\Ell(B)\neq \emptyset.
\end{gather*}
 Then, for all $k_0>0$ there exists $C>0$ such that 
$$
\|Au\|_{L^2}\leq Ck\|EP_ku\|_{L^2}+\|Bu\|_{L^2}+C_Nk^{-N}\|u\|_{L^2}
$$
\end{theorem}
\begin{proof}
The estimates follow from the combination of the propagation results in~\cite[Theorem 8.1]{Va:08} (for Dirichlet boundary conditions on $\partial\Omega_-$) and \cite[Theorem 8.5]{Va:08} (for Neumann boundary conditions on $\partial\Omega_-$) applied near the $\partial\Omega$ and~\cite[Theorem E.47]{DyZw:19} applied away from $\partial\Omega_-$. 
\end{proof}

\

Our next lemma shows that, to measure $u$ away from trapping, we need only have an estimate for $u$ in an annulus.
\begin{lemma}
\label{l:propagate}
Suppose that $A\in {}^b\Psi(\Omega)$ and ${}^b\WF(A)\cap K=\emptyset$. Then, for any $R_{\operatorname{scat}}<R_1<R_{\operatorname{PML}_-}$ and $B\in C_c^\infty(\Omega)$ with $\supp (1-B)\cap \{|x|=R_1\}=\emptyset$, given $k_0>0$ there exists $C>0$ such that for all $k\geq k_0$
\beq\label{e:savingSpace}
\|Au\|_{L^2}\leq Ck\|P_ku\|_{L^2}+\|Bu\|_{L^2}+C_Nk^{-N}\|u\|_{L^2}^2.
\eeq
\end{lemma}
\begin{proof}
First, by Lemma~\ref{l:nearPMLBoundary} %and~\ref{l:outgoing} and 
we may assume that 
$$
{}^b\WF(A)\subset \Omega_{\tr}.%\qquad {}^b\WF(A)\cap \{|x|>R_{\operatorname{scat}}\}\subset \{ \langle \tfrac{x}{|x|},\xi\rangle \geq \e\}.
$$
Next observe that if ${}^b\WF(A)\cap {}^b\pi(\{p_\theta=0\})=\emptyset$, then by the ellipticity results in Theorem~\ref{l:ellipticVasy}
$$
\|Au\|_{L^2}\leq C\|P_ku\|_{L^2}+C_Nk^{-N}\|u\|_{L^2}.
$$
Therefore, we may assume that ${}^b\WF(A)$ is contained in a small neighbourhood of ${}^b\pi(\{p_\theta=0\})$. 

If ${}^b\WF(A)\subset \{B\equiv 1\}$ then, by the elliptic parametrix \cite[Proposition E.32]{DyZw:19},
$$
\|Au\|_{L^2}\leq C\|Bu\|_{L^2}+Ck^{-N}\|u\|_{L^2}.
$$ 
Therefore, using a partition of unity, we need only consider two cases: ${}^b\WF(A)\subset \{|x|>R_1\}$ and ${}^b\WF(A)\subset \{|x|<R_1\}$. 

First, suppose that ${}^b\WF(A)\subset \{|x|>R_1\}$. Let $U$ be as in Lemma~\ref{l:nearPMLBoundary}. Then, there exists $T>0$ such that for all $(x,\xi)\in {}^b\WF(A)$, there is $t\in[0,T]$ such that 
$$
\varphi_{-t}(x,\xi)\in \{B\equiv 1\}\cup \{(x,\xi)\,:x\in U\}
$$
(i.e., flowing backwards, one either hits $B\equiv 1$ or the PML).
In particular, by the propagation results~\cite[Theorem E.47]{DyZw:19}
 there is $\psi \in C^\infty(U)$ with $\psi\equiv 1$ near $\Gamma_{\tr}$ such that 
$$
\|Au\|_{L^2}\leq Ck\|P_ku\|_{L^2}+\|Bu\|_{L^2}+\|\psi u\|_{L^2}+Ck^{-N}\|u\|_{L^2}.
$$
By Lemma~\ref{l:nearPMLBoundary}, we then obtain
$$
\|Au\|_{L^2}\leq Ck\|P_ku\|_{L^2}+\|Bu\|_{L^2}+Ck^{-N}\|u\|_{L^2}
$$
as required.

Next, suppose ${}^b\WF(A)\subset\{|x|<R_1\}$. Then, since ${}^b\WF(A)\cap K=\emptyset$, applying a partition of unity again, we may assume there exists $T>0$ such that for all $(x,\xi)\in {}^b\WF(A)$, either there is $t\in[0,T]$ such that 
$$
\varphi_t(x,\xi)\in \Big\{(x,\xi)\,:\, B(x)>\tfrac{1}{2}\Big\},\qquad \bigcup_{s\in[0,t]}\varphi_s(x,\xi)\in B(0,R_{\operatorname{PML}_-}),
$$
(informally, one flows forwards from $A$, staying away from the PML region, and reaches where $B>1/2$ at time $t$)
or there is $t\in[0,T]$ such that 
$$
\varphi_{-t}(x,\xi)\in \Big\{(x,\xi)\,:\, B(x)>\tfrac{1}{2}\Big\},\qquad \bigcup_{s\in[-t,0]}\varphi_s(x,\xi)\in B(0,R_{\operatorname{PML}_-}).
$$
(informally, one flows backwards from $A$, staying away from the PML region, and reaches where $B>1/2$ at time $t$).
The result \eqref{e:savingSpace} then follows by the propagation results of Theorem \ref{l:propagateVasy}.
\end{proof}

\

Finally, we combine the above lemmas to show that we may estimate $u$ away from trapping by $u$ near the wavefront set of $P_ku$. In particular, this will improve the resolvent estimate when the measurement is away from trapping.
\begin{lemma}
\label{l:halfAway}
Suppose that $A\in {}^b\Psi(\Omega)$ and ${}^b\WF(A)\cap K=\emptyset$. Then, for any $X\in {}^b\Psi^0$ with ${}^b\WF(I-X)\cap {}^b\WF(P_ku)=\emptyset$, given $k_0>0$ there exists $C>0$ such that for all $k\geq k_0$
$$
\|Au\|^2_{L^2}\leq Ck\|P_ku\|_{L^2}\|Xu\|_{L^2}+Ck^2\|P_ku\|_{L^2}^2+C_Nk^{-N}\|u\|_{L^2}^2.
$$
\end{lemma}
\begin{proof}
Let $R_{\operatorname{scat}}<R_1<R_{\operatorname{PML}_-}$ and $b\in C_c^\infty(R_{\operatorname{scat}},R_{\operatorname{PML}_-})$ with $\supp (1-b)\cap \{|x|=R_1\}=\emptyset. $ Then, by Lemma~\ref{l:propagate}
$$
\|Au\|^2_{L^2}\leq Ck^2\|P_ku\|_{L^2}^2+C\|Bu\|_{L^2}^2+C_Nk^{-N}\|u\|_{L^2}^2,
$$
and, by Lemma~\ref{l:DV},
$$
\|Bu\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\|X u\|_{L^2}+Ck^2\|P_ku\|_{L^2}^2+C_Nk^{-N}\|u\|_{L^2}^2,
$$
which completes the proof.
\end{proof}

\

When the both the data and measurement are away from trapping, we can use the previous lemma to improve our estimates further-- all the way to a non-trapping type bound.
\begin{lemma}
\label{l:fullAway}
Suppose that ${}^b\WF(P_ku)\cap K=\emptyset$, then for any $A\in {}^b\Psi(\Omega)$ with ${}^b\WF(A)\cap K=\emptyset$ given $k_0>0$ there exists $C>0$ such that for all $k\geq k_0$
$$
\|Au\|_{L^2}\leq Ck\|P_ku\|_{L^2}+Ck^{-N}\|u\|_{L^2}.
$$
\end{lemma}
\begin{proof}
Let $\tilde{A},X\in {}^b\Psi(\Omega)$ with ${}^b\WF(I-X)\cap {}^b\WF(P_ku)=\emptyset$, ${}^b\WF(\tilde{A})\cap K=\emptyset$, and ${}^b\WF(I-\tilde{A})\cap( {}^b\WF(A)\cup{}^b\WF(X))=\emptyset$. 
By Lemma~\ref{l:halfAway},
$$
\|\tilde{A}u\|_{L^2}^2\leq Ck\|P_ku\|_{L^2}\|Xu\|_{L^2}+Ck^2\|P_ku\|_{L^2}^2+Ck^{-N}\|u\|_{L^2}.
$$
Then, by the elliptic parametrix construction in the b-calculus~\cite[Equation 3.11]{GaWu:23} (see also \cite[Appendix A]{HiVa:18}),
$$
\|Xu\|_{L^2}\leq 
C\|\tilde{A}u\|_{L^2}+Ck^{-N}\|u\|_{L^2}
$$
Combining the last two inequalities and using the inequality \eqref{e:peterPaul}, we obtain that
$$
\|\tilde{A}u\|_{L^2}^2\leq Ck^2\|P_ku\|_{L^2}^2+Ck^{-N}\|u\|_{L^2}^2.
$$
Finally, since $\tilde{A}$ is elliptic on $\WF(A)$,
$$
\|Au\|_{L^2}\leq  C\|\tilde{A}u\|_{L^2}+Ck^{-N}\|u\|_{L^2},
$$
which completes the proof
\end{proof}

