\section{A new variational formulation for the Willmore flow in 3D} 
In this section, we present a new variational formulation for the Willmore flow base on two geometric identities for the normal velocity vector $V\n$ and the temporal evolution of the mean curvature $\cur$. The energy dissipation is established within the variational formulation by using a new transport theorem.   

\subsection{Basic notations and identities}
In this paper, we always assume that $\Gamma(t) \subset \bR^3$ is a sufficiently smooth, orientable and compact evolving surface with outward unit normal vector field $\n$, parameterized by a global parameterization $\X(\cdot,t)$ as
$$
\X(\cdot, t): \Gamma(0) \rightarrow \bR^3, \quad (\boldsymbol{\rho}, t)\mapsto \left(x_1(\boldsymbol{\rho},t),\ x_2(\boldsymbol{\rho},t),\ x_3(\boldsymbol{\rho},t) \right)^T,
$$
where $\Gamma(0)$ is the initial surface parameterized by the identity map $\X(\cdot, 0)$.

For a scalar function $f\in C^2(\Gamma)$ on surface $\Gamma$, the surface gradient operator is defined via \cite{Barrett2020}
\be
\ds f \coloneqq\left(I_3- \n\n^T\right) \nabla f = \left(\ud_1 f, \ud_2 f,\ud_3 f\right)^T,
\ee
where $\ud_i$ ($i=1,2,3$) represent the tangential derivative operators intrinsic to the surface $\Gamma$ \cite{deckelnick2005computation}, $I_3$ the $3\times 3$ identity matrix, and the surface Laplacian operator (also called Laplace-Beltrami operator) is given by
\be
\lap f \coloneqq \ds\cdot \ds f = \ud_1^2 f + \ud_2^2 f + \ud_3^2 f.
\ee
In the case of a vector valued function $\boldsymbol{f} = \left(f_1, f_2, f_3\right)^T\in [C^2(\Gamma)]^3$, we define the surface Jacobian, surface divergence, and surface Laplacian as follows:
\begin{subequations}
    \label{def surface differential operators}
    \begin{align}
        &\ds \boldsymbol{f} \coloneqq \left(\ds f_1, \ds f_2, \ds f_3 \right)^T = \begin{pmatrix}
            \ud_1 f_1 & \ud_2 f_1 & \ud_3 f_1 \\
            \ud_1 f_2 & \ud_2 f_2 & \ud_3 f_2 \\
            \ud_1 f_3 & \ud_2 f_3 & \ud_3 f_3
        \end{pmatrix}, \\
        &\ds \cdot \boldsymbol{f} \coloneqq \text{Tr}(\ds \boldsymbol{f}) = \ud_1 f_1 + \ud_2 f_2 + \ud_3 f_3, \\
        &\lap \boldsymbol{f} \coloneqq \left(\lap f_1, \lap f_2, \lap f_3\right)^T.
    \end{align}
\end{subequations}
For a matrix-valued function $\boldsymbol{F} = (F_{ij})_{i,j=1}^3 \in [C^1(\Gamma)]^{3\times 3} $, its surface divergence is defined as 
\begin{equation}\label{matrix surface divergence}
    \ds \cdot \boldsymbol{F}= \begin{pmatrix}
        \ud_1 F_{11} + \ud_2 F_{12} + \ud_3 F_{13} \\
        \ud_1 F_{21} + \ud_2 F_{22} + \ud_3 F_{23} \\
        \ud_1 F_{31} + \ud_2 F_{32} + \ud_3 F_{33}
    \end{pmatrix}.
\end{equation}
%where $\left\{\boldsymbol{e}_1, \boldsymbol{e}_2, \boldsymbol{e}_3\right\}$ are three orthogonal directions in the Cartesian coordinate.  

Here we gather the product rule for surface differential operators on $f\in C^1(\Gamma)$, 
$\boldsymbol{f}, \boldsymbol{g}\in [C^1(\Gamma)]^3$ and 
$\boldsymbol{F},\boldsymbol{G}\in [C^1(\Gamma)]^{3\times 3} $, the proof can be found in \cite[Lemma 7]{Barrett2020}:
\begin{subequations}
\begin{align}
    &\ds\cdot (f\boldsymbol{g}) = \boldsymbol{g}\cdot \ds f + f\ds \cdot \boldsymbol{g},\label{divergence multi}\\
    &\ds (\boldsymbol{f}\cdot \boldsymbol{g}) = (\ds\boldsymbol{f})^T \boldsymbol{g} + (\ds \boldsymbol{g})^T \boldsymbol{f},\label{gradient multi vector}\\
    &\ds (f\boldsymbol{g}) = \boldsymbol{g}(\ds f)^T + f\ds \boldsymbol{g},\label{gradient multi scalar}\\
    & \ds \cdot (\boldsymbol{f} \boldsymbol{g}^T) = (\ds \cdot \boldsymbol{g})\boldsymbol{f} + (\ds \boldsymbol{f}) \boldsymbol{g}, \label{divergence vector vector} \\
    & \ds \cdot (f \boldsymbol{G}) = f \ds \cdot \boldsymbol{G} + \boldsymbol{G} \ds f, \label{divergence scalar matrix}\\
    & \ds \cdot (\boldsymbol{F} \boldsymbol{g}) = (\ds \cdot \boldsymbol{F}^T) \cdot \boldsymbol{g} + \text{Tr}(\boldsymbol{F} \nabla_\Gamma \boldsymbol{g}). \label{divergence matrix vector}
\end{align}
\end{subequations}

We define the function space $L^2(\Gamma(t))$ by
\begin{equation}
    L^2(\Gamma(t)) \coloneqq \left\{f:\, \Gamma(t) \rightarrow \bR\, \Big|\, \int_{\Gamma(t)} f^2\, \dd A < +\infty \right\},
\end{equation}
equipped with the $L^2$ inner product $(\cdot, \cdot )_{\Gamma(t)}$ which is formulated by 
\begin{equation}
    (u, v)_{\Gamma(t)} \coloneqq \int_{\Gamma(t)} uv \, \dd A,\quad \forall u, v\,\in L^2(\Gamma(t)).
\end{equation}
The definition of $L^2(\Gamma(t))$ can easily be extended to vector-valued function space $[L^2(\Gamma(t)]^3$ and the matrix-valued function space $[L^2(\Gamma(t))]^{3\times 3}$. Specially, the inner product for two matrix-valued functions is emphasized by
\begin{equation}\label{inner product matrix}
    \langle\boldsymbol{U}, \boldsymbol{V}\rangle_{\Gamma(t)} \coloneqq \int_{\Gamma(t)} \boldsymbol{U}:\boldsymbol{V}\, \dd A, \quad \forall\, \boldsymbol{U}, \boldsymbol{V}\, \in [L^2(\Gamma(t))]^{3\times 3},
\end{equation}
where $\boldsymbol{U}:\boldsymbol{V} \coloneqq \text{Tr}\,(\boldsymbol{U}^T\boldsymbol{V})$ denotes the Hilbert-Schmidt inner product. And the Sobolev space $H^1(\Gamma(t))$ can be straightforwardly defined:
\begin{equation}
    H^1(\Gamma(t)) \coloneqq \left\{f\in L^2(\Gamma(t))\, \text{and}\, \ \ud_i f \in L^2(\Gamma(t)),\quad i = 1,2,3\right\},
\end{equation}  
which can also be easily extended to vector-valued function space $[H^1(\Gamma(t))]^3$ and matrix-valued function space  $[H^1(\Gamma(t))]^{3\times 3}$. 

Next, we consider the geometric quantities on surface $\Gamma$. The mean curvature is defined as the trace of the second fundamental form of the surface
\begin{equation}\label{def cur}
    \cur \coloneqq\ds\cdot \n = \text{Tr}(\mathbf{A}),
\end{equation}
where $\mathbf{A} := \ds \n$ is also called as the Weingarten map, which satisfies $\mathbf{A} = \mathbf{A}^T$. The mean curvature $\cur$ satisfies the following mean curvature vector identity \cite{Barrett2020}, which is frequently used in the BGN schemes:
\begin{equation}\label{BGN curvature}
    \cur \n = - \lap \X.
\end{equation}
The Willmore energy is therefore given by
\begin{equation}
    \label{continuous energy}
    W(t) \coloneqq W(\Gamma(t)) = \frac{1}{2}\int_{\Gamma(t)} \cur^2 \, \dd A = \frac{1}{2}\left(\cur, \cur \right)_{\Gamma(t)}.
\end{equation}

Using the above notation, we are able to write the Willmore flow in 3D as the following coupled fourth-order nonlinear parabolic geometric partial differential equations (PDEs): % ref{BGN}:
\begin{subequations}
    \label{original Willmore formulation}
    \begin{align}
        &\dt \X =V\n, \label{original Willmore formulation X}\\
        &V = \lap\cur+ |\mathbf{A}|^2 \cur -\frac{1}{2} \cur^3,\label{original Willmore formulation V}\\
        & \cur \n = - \lap \X,\label{original Willmore formulation H}
    \end{align}
\end{subequations}
where $|\mathbf{A}|^2\coloneqq \text{Tr}(\mathbf{A}^T\mathbf{A})$, with the initial condition $\X(\cdot,0)=\X_0(\cdot)$.  


