\subsection{New geometric identities}
In this subsection, we focus on establishing two geometric identities that are crucial for constructing the ES-PFEM for the Willmore flow in 3D. The first identity characterizes the normal velocity vector of the Willmore flow, while the second one provides a novel expression for the mean curvature evolution that holds for all geometric flows. In contrast to our previous work on the planar Willmore flow \cite{bao2025energy}, both identities are formulated in the variational 
(or weak) forms.

\begin{lemma}\label{lemma V}
    For a solution $\X$ of the parameterized Willmore flow \eqref{original Willmore formulation} with the scalar normal velocity $V$, it holds that 
    \begin{align}
        \label{new identity for V}
        &\int_{\Gamma(t)} V\n\cdot \w \, \dd A \nonumber \\
        & = \int_{\Gamma(t)} \left(\cur \mathbf{A}  -\n (\ds \cur)^T - \frac{1}{2}\cur^2\ds \X\right): \ds \w \, \dd A, \quad \forall\, \w \in [H^1(\Gamma(t))]^3.
    \end{align}
\end{lemma}
\begin{proof}
    By utilizing \eqref{divergence vector vector} with $\boldsymbol{f} = \n$ and $\boldsymbol{g} = \ds \cur$, \eqref{divergence scalar matrix} with $f = \cur$ and $\boldsymbol{G} = \mathbf{A}$, and \eqref{divergence scalar matrix} with $f = \cur^2$ and $\boldsymbol{G} = \ds \X$,  we can derive
    \begin{subequations}
        \begin{align}
            &\ds \cdot(\n (\ds \cur)^T) = \ds\n \ds\cur + \lap \cur \n = \mathbf{A} \ds \cur + \lap \cur \n,  \label{pf1 eq1}\\
            &\ds \cdot (\cur \ds \n) = \ds\n \ds\cur+ \cur \lap \n = \mathbf{A} \ds \cur + \cur \lap \n,  \label{pf1 eq2} \\
            & \ds \cdot (\cur^2 \ds \X) = 2\cur \ds \X \ds \cur + \cur^2 \lap \X = 2\cur  \ds \cur - \cur^3 \n.   \label{pf1 eq3}
        \end{align}
    \end{subequations}
 The last equality makes use of \eqref{BGN curvature}, $\n \cdot \ds \cur = 0$, and $\ds \X = I_3 - \n \n^T$ from \cite[(1)]{Barrett2020}. 
 Using \eqref{gradient multi scalar}, \eqref{pf1 eq1}, and \eqref{pf1 eq2}, there holds
 \begin{align}\label{pf1 eq4}
     \lap (\cur \n) = \ds\cdot \left( \n(\ds \cur)^T + \cur \ds \n\right) %\nonumber\\
     %&= \ds\cdot (\ds\cur \n^T)+ \ds\cdot (\cur \ds\n)\nonumber\\
     =\,  2\mathbf{A} \ds\cur+ \cur \lap \n +  \lap\cur \n.
 \end{align}
Moreover, the expression for the surface gradient related to the mean curvature is given as follows (see Lemma 16 of \cite{Barrett2020}):
\begin{align}\label{pf1 eq5}
    \ds \cur = \lap \n + |\mathbf{A}|^2 \n.
\end{align}
Recalling $V = \lap\cur + |\mathbf{A}|^2\cur - \frac{1}{2}\cur^3$, combining \eqref{pf1 eq2}, \eqref{pf1 eq3}, \eqref{pf1 eq4} and \eqref{pf1 eq5}, we deduce
\begin{align}
    &\lap(\cur\n)- \ds\cdot \left(2\cur \mathbf{A} - \frac{1}{2}\cur^2 \ds\X\right)\nonumber\\
    &\ = \left(2\mathbf{A} \ds\cur+ \cur \lap \n +  \lap\cur \n\right) -2(\mathbf{A} \ds\cur + \cur \lap \n) + \left(\cur \ds\cur -\frac{1}{2}\cur^3 \n\right)\nonumber\\
    &\ =- \cur \lap \n + \lap\cur \n +\cur \ds\cur -\frac{1}{2}\cur^3 \n \nonumber\\
    &\ =  \left( \lap \cur + |\mathbf{A}|^2 \cur  - \frac{1}{2}\cur^3  \right)\n \nonumber\\
    &\ =V\n.
\end{align}
Finally, multiplying both sides of the above equation by $\w$,  then integrating over $\Gamma(t)$, and applying the product rule \eqref{divergence matrix vector}, \eqref{gradient multi scalar}, and the divergence theorem given in \cite[Theorem 21]{Barrett2020} with $\boldsymbol{f} = \left(2\cur \mathbf{A} - \frac{1}{2}\cur^2 \ds\X\right)^T \boldsymbol{\omega} = \left(2\cur \mathbf{A} - \frac{1}{2}\cur^2 \ds\X\right) \boldsymbol{\omega}$, we have
\begin{align}
    \int_{\Gamma(t)}V\n \cdot \w\, \dd A=& \int_{\Gamma(t)}\left( \lap(\cur\n)- \ds\cdot \left(2\cur \mathbf{A} - \frac{1}{2}\cur^2 \ds\X\right) \right)\cdot \w\,\dd A\nonumber\\
    =&\int_{\Gamma(t)} \left(-\ds(\cur\n)+ \left(2\cur \mathbf{A}- \frac{1}{2}\cur^2 \ds\X\right)\right):\ds\w\,\dd A\nonumber\\
    & \qquad -\int_{\Gamma(t)} \cur\n^T(2\cur \mathbf{A}- \frac{1}{2}\cur^2 \ds\X) \w\,\dd A\nonumber\\
    =&\int_{\Gamma(t)} \left(-\n(\ds\cur)^T-\cur \mathbf{A} + \left(2\cur \mathbf{A} - \frac{1}{2}\cur^2 \ds\X\right)\right):\ds\w\,\dd A\nonumber\\
    =&\int_{\Gamma(t)} \left(\cur\mathbf{A} -\n (\ds\cur)^T- \frac{1}{2}\cur^2\ds\X\right):\ds\w\,\dd A,
\end{align}
which yields the result \eqref{new identity for V}.\qed
\end{proof}

In addition, the integral geometric identity related to the temporal evolution of the mean curvature is given by the following lemma. For notational convenience, we always use $\partial_t$ to represent the material derivative in \cite{Barrett2020}.
\begin{lemma}\label{lemma H}
    For the mean curvature $\cur$ of the evolving surface $\Gamma(t)$ parameterized by $\X(\cdot, t)$, there holds
    \begin{equation}
        \label{new identity for H}
        \int_{\Gamma(t)} \dt \cur  \varphi \,\dd A = \int_{\Gamma(t)}\ds (\dt\X): \left(\n(\ds\varphi)^T- \varphi \mathbf{A}\right)\,\dd A, \quad \forall \varphi \in H^1(\Gamma(t)).
    \end{equation}

\end{lemma}
\begin{proof}
From the Huisken's evolution equation for the mean curvature \cite{huisken1984flow}, we know that 
\begin{equation}
    \label{pf2 eq1}
    \dt \cur = -\lap V - |\mathbf{A}|^2 V.
\end{equation}
In our parameterization, $\dt \X =V\n$, thus \eqref{gradient multi scalar} yields
\begin{equation}
    \label{pf2 eq2}
    \ds(\dt\X) = \ds(V\n) = \n (\ds V)^T + V \mathbf{A}.
\end{equation}
Furthermore, noting $\mathbf{A}^T\n = \boldsymbol{0}$, by left-multiplying both sides of \eqref{pf2 eq2} with $\n^T$, it turns out
\begin{equation}
    \label{pf2 eq3}
    (\ds V)^T = \n^T \ds (\dt \X). 
\end{equation}
By multiplying both sides of \eqref{pf2 eq1} with $\varphi$, then integrating over $\Gamma(t)$, and applying the above equation, we can proceed directly to the computations:
\begin{align}
    \int_{\Gamma(t)} \dt \cur \varphi \, \dd A &= \int_{\Gamma(t)} (-\lap V -|\mathbf{A}|^2V)\, \varphi \dd A\nonumber\\
    & = \int_{\Gamma(t)} \ds V \cdot \ds \varphi  \dd A - \int_{\Gamma(t)} \text{Tr}\left(\mathbf{A}^TV \mathbf{A}\right)\varphi\, \dd A\nonumber\\
    & = \int_{\Gamma(t)} (\ds V)^T \ds \varphi  \dd A - \int_{\Gamma(t)} \text{Tr}\left(\mathbf{A}^T(V \mathbf{A} + \n (\ds V)^T)\right)\varphi\, \dd A\nonumber\\
    & = \int_{\Gamma(t)} \n^T\ds(\dt\X)\ds \varphi  \dd A - \int_{\Gamma(t)} \text{Tr}(\mathbf{A}^T\ds(\dt \X))\varphi\, \dd A\nonumber\\
    & = \int_{\Gamma(t)}\ds (\dt\X): (\n(\ds\varphi)^T- \varphi \mathbf{A})\,\dd A,
\end{align}
which validates \eqref{new identity for H}.\qed
\end{proof}
\subsection{A variational formulation and its properties}
Let $(\mathbf{X}(\cdot,t), V(\cdot, t), \cur(\cdot,t)) \in [H^1(\Gamma(t))]^3 \times H^1(\Gamma(t)) \times H^1(\Gamma(t))$ be a solution to the Willmore flow \eqref{original Willmore formulation} under our parameterization. We reformulate the governing equation \eqref{original Willmore formulation X} as $\n \cdot \dt \X = V$. Then we multiply by test functions $\phi \in L^2(\Gamma(t))$ and integrate over the surface $\Gamma(t)$ to get its variational form. Furthermore, the variational forms of the normal velocity $V(\cdot, t)$ and the mean curvature $\cur(\cdot, t)$ are given by Lemma \ref{lemma V} and Lemma \ref{lemma H}, respectively. Consequently, this derivation yields a consistent variational formulation for the Willmore flow given by
\begin{subequations}\label{new weak form}
\begin{align}
    &\left(\n \cdot \dt \X, \phi\right)_{\Gamma(t)} = \left(V, \phi\right)_{\Gamma(t)}, \quad \forall \phi\in H^1(\Gamma(t)),\label{new weak form X}\\
    &\left(V\n, \w\right)_{\Gamma(t)} = \Big\langle\cur \mathbf{A} - \n\left(\ds\cur\right)^T- \frac{1}{2}\cur^2\ds \X, \ds\w\Big\rangle_{\Gamma(t)}, \forall \w\in [H^1(\Gamma(t))]^3,\label{new weak form V}\\
    &\left(\dt\cur, \varphi\right)_{\Gamma(t)} = \big\langle\ds(\dt \X), \n (\ds \varphi)^T- \varphi \mathbf{A} \big\rangle_{\Gamma(t)}, \quad \forall \varphi \in H^1(\Gamma(t));\label{new weak form H}
\end{align}
with the initial data $\X(\cdot,0):=\X_0(\cdot)$ and $\cur(\cdot,0):=-\n\cdot\lap \X_0(\cdot)$.
\end{subequations}

\begin{remark}
    The new variational formulation above is in fact a natural generalization of Bao and Li's work in the two-dimensional case \cite{bao2025energy}. By replacing the surface gradient operator $\ds$ by the arc length derivative $\partial_s$ and utilizing the identity $\partial_s \n = \kappa\partial_s \X$ with $\kappa$ denoting the mean curvature in 2D, we can recover the variational formulation in the two-dimensional case presented in \cite{bao2025energy}. 
\end{remark}

\begin{lemma}[A new transport theorem]\label{transport thoerem}
    Let a scalar-valued function $f$ be defined on the evolving surface $\Gamma(t)$ and $f$ is differentiable with respect to $t$. Then it holds
    \begin{equation}
        \label{eqn:transport thm}
        \frac{\dd}{\dd t} \int_{\Gamma(t)} f \,\dd A = \int_{\Gamma(t)} \dt f \, \dd A + \int_{\Gamma(t)} f \ds\X :\ds(\dt\X)\, \dd A.
    \end{equation}
\end{lemma}
\begin{proof}
    From (v) in \cite[Remark 6]{Barrett2020} and the fact that $\ds \X = (I_3 - \n \n^T)$, we know that
    \begin{align}\label{pf3 eq2}
        \ds\cdot (\dt\X) = \text{Tr}(\ds(\dt\X))=  \text{Tr}(\ds(\dt\X)(\ds\X)^T)= \ds \X :\ds (\dt\X).
    \end{align}
    Therefore, using the transport theorem \cite[Theorem 32]{Barrett2020}, we can derive that 
    \begin{align}
        \frac{\dd}{\dd t} \int_{\Gamma(t)}f \, \dd A &= \int_{\Gamma(t)} \dt f \, \dd A + \int_{\Gamma(t)} f \ds \cdot \left(\dt (V \n)\right) \, \dd A\nonumber\\
        &= \int_{\Gamma(t)} \dt f \, \dd A + \int_{\Gamma(t)} f \ds \cdot \left(\dt \X\right) \, \dd A\nonumber\\
        & = \int_{\Gamma(t)} \dt f \, \dd A + \int_{\Gamma(t)} f \ds \X :\ds(\dt\X)\, \dd A,
    \end{align}
    which implies \eqref{eqn:transport thm}.
    \qed
\end{proof}
\begin{remark}
    The new transport theorem reveals that energy dissipation decomposes into two components: energy change (represented by $\int_{\Gamma(t)} \dt f \, \dd A$) and domain change (represented by $\int_{\Gamma(t)} f \ds\X :\ds(\dt\X)\, \dd A$). Instead of $\ds \cdot \dt (V \n)$, our new formulation adopts $\ds\X:\ds(\dt\X)$ to represent the domain change term, which is inspired by the fundamental inequality from the BGN scheme in the discrete setting as \cite{barrett2007variational}:
    \begin{equation*}
    \int_{\Gamma^m} \ds \X^{m+1} :\ds ( \X^{m+1} - \X^m) \, \dd A \geq |\Gamma^{m+1}| - |\Gamma^m|, \qquad m\ge0.
    \end{equation*}
    This reformulation is crucial for enabling energy stability in the full-discretization.
\end{remark}

Now we can turn back to prove the energy dissipative property of the new variational formulation \eqref{new weak form}.
\begin{theorem}[Energy dissipation]\label{thm:continuous energy dissipation }
Let $\left(\X(\cdot,t), V(\cdot, t), \cur(\cdot,t)\right)$ be a solution of the new variational formulation \eqref{new weak form} with the initial data $\X(\cdot,0):=\X_0(\cdot)$ and $\cur(\cdot,0)=-\n\cdot\lap \X_0(\cdot):=\cur_0(\cdot)$. Then the Willmore energy $\Gamma(t)$ defined in \eqref{continuous energy} is decreasing over time, i.e.
\begin{equation}
\label{eqn: continuous energy dissipation}
    W(t) \leq W(t')\leq W(0) = \frac{1}{2}\left(\cur_0,\cur_0\right)_{\Gamma(0)}, \quad \forall t \geq t'\geq 0.
\end{equation}
\end{theorem}
\begin{proof}
We employ Lemma \ref{transport thoerem} for $f = \frac{1}{2}\cur^2$ and derive that
\begin{align}\label{pf4 eq1}
    \frac{\dd}{\dd t} W(t) &= \frac{\dd}{\dd t}\int_{\Gamma(t)}\frac{\cur^2}{2}\, \dd A \nonumber\\
    &= \int_{\Gamma(t)} \cur \dt \cur\, \dd A + \frac{1}{2}\int_{\Gamma(t)} \cur^2 \ds\X :\ds(\dt\X)\, \dd A,\nonumber\\
    & = \left(\dt \cur, \cur \right)_{\Gamma(t)}+ \Big\langle\frac{\cur^2}{2}\ds\X, \ds(\dt \X)\Big\rangle_{\Gamma(t)}, \qquad t\ge0.
\end{align}  
In the meanwhile, by taking test functions $\phi = -V \in L^2(\Gamma(t))$ in \eqref{new weak form X}, $\w = \dt \X \in [H^1(\Gamma(t))]^3$ in \eqref{new weak form V} and  $\varphi = \cur \in H^1(\Gamma(t))$ in \eqref{new weak form H}, we obtain
\begin{subequations}
    \begin{align}
        &-\left(\n \cdot \dt \X, V\right)_{\Gamma(t)} = -\left(V, V\right)_{\Gamma(t)}, \label{continuous, test function X}\\
        &\left(V\n, \dt \X\right)_{\Gamma(t)} = \Big\langle\cur \mathbf{A} - \n\left(\ds\cur\right)^T- \frac{1}{2}\cur^2\ds \X, \ds (\dt \X)\Big\rangle_{\Gamma(t)}, \label{continuous, test function V}\\
        &\left(\dt\cur, \cur\right)_{\Gamma(t)} = \big\langle\ds(\dt \X), \n (\ds \cur)^T- \cur \mathbf{A} \big\rangle_{\Gamma(t)}, \qquad t\ge0. \label{continuous, test function H}
    \end{align}
\end{subequations}
Summing up the above three equations, we get
\begin{equation}\label{pf4 eq2}
    \begin{aligned}
    \left(\dt\cur, \cur\right)_{\Gamma(t)} & = - \left(V, V\right)_{\Gamma(t)}-\Big\langle\frac{\cur^2}{2}\ds\X, \ds(\dt \X)\Big\rangle_{\Gamma(t)},\qquad t\ge0.
    \end{aligned}
\end{equation}
Utilizing \eqref{pf4 eq1} and \eqref{pf4 eq2}, it can be deduced that
\begin{equation}
    \frac{\dd}{\dd t} W(t) = -\left(V, V\right)_{\Gamma(t)} \leq 0, \qquad t\ge0,
\end{equation}
which yields the energy dissipative property \eqref{eqn: continuous energy dissipation}.
\qed
\end{proof}



\begin{remark}
    In the above proof of the energy dissipation, by employing \eqref{new weak form H} along with the new transport theorem Lemma \ref{transport thoerem}, we circumvent the treatment of the high-order term $\lap V$ as in \eqref{pf2 eq1}, and the Weingarten map $\mathbf{A}$ cancels out between \eqref{continuous, test function V} and \eqref{continuous, test function H}. This will help us develop the energy-stable numerical scheme under piecewise linear finite elements in the following section.
\end{remark}

\section{An energy-stable parametric finite element method}
In this section, by utilizing the parametric finite element method in spatial discretization and the backward Euler method in temporal discretization, we present an ES-PFEM for the Willmore flow in 3D by building upon the new variational formulation \eqref{new weak form}. We also prove rigorously the unconditional energy stability of the proposed ES-PFEM.

\subsection{A full-discretization}
To derive an appropriate fully discrete scheme, we introduce the following parametric finite element approximation. Let $\tau > 0$ be the uniform time step size and denote the discrete time levels as $t_m = m\tau$ for $m = 0,1,2,\cdots$. At every time step $t_m$, we approximate the evolving surface $\Gamma(t_m)$ by the polygonal surface denoted by $\Gamma^m$, which is composed of a collection of mesh vertices $\{ \q_k^m\}_{k = 1}^K$, or equivalently, a collection of nonoverlapping and nondegenerate triangles $\{ \sigma_{j}^m\}_{j = 1}^J$. The polygonal surface can be written as 
$$
\Gamma^m \coloneqq \bigcup_{j = 1}^J \overline{\sigma_{j}^m},\quad  m = 0,1,2,\cdots. 
$$
For $1\leq j \leq J$, the triangle surface element $\sigma_j^m = \{\q_{j_1}^m, \q_{j_2}^m, \q_{j_3}^m\}$ is determined by its three vertices $\q_{j_1}^m, \q_{j_2}^m, \q_{j_3}^m$ in counter-clockwise order on the outer surface of $\Gamma^m$ in 3D. 

We use the continuous piecewise linear elements in space to approximate the space $L^2(\Gamma(t_m))$, which is given as 
\begin{equation}
    \mathbb{K}^m \coloneqq \left\{ u \in C(\Gamma^m)\, \Big|\, \,  u |_{\sigma_j^m}\in \mathcal{P}^1(\sigma_j^m), \quad \forall 1\leq j \leq J \right\},
\end{equation}
where $\mathcal{P}^1(\sigma_j^m)$ denotes the function space of all polynomials with degree at most $1$ on $\sigma_{j}^m$. Let $\n^m$ be the outward unit normal vector on polygonal surface $\Gamma^m$, then it is a piecewise constant vector-valued function which can be defined via
\begin{align} \label{discrete normal vector}
    \n^m|_{\sigma_j^m}\coloneqq \n^m_j = \frac{\mathcal{J}\{\sigma_j^m\}}{|\mathcal{J}\{\sigma_j^m\}|},
\end{align}
where $\mathcal{J}\{\sigma_j^m\}$ is the direction vector given by the three vertices denoted by 
\begin{equation}
    \mathcal{J}\{ \sigma_j^m\} =  \left(\q_{j_2}^m- \q_{j_1}^m\right)\times  \left(\q_{j_3}^m- \q_{j_1}^m\right),
\end{equation}
on each $\sigma_j^m = \{\q_{j_1}^m, \q_{j_2}^m, \q_{j_3}^m\}$. 


Suppose the scalar/vector-valued functions $u^h, v^h \in \mathbb{K}^m/[\mathbb{K}^m]^3$, the $L^2$ inner product $(\cdot,\cdot )_{\Gamma(t_m)}$ is approximated by the mass-lumped inner product $(\cdot, \cdot)_{\Gamma^m}^h$  as follows:
\begin{equation}
    \left(u^h, v^h\right)_{\Gamma^m}^h\coloneqq \frac{1}{3}\sum_{j = 1}^J \sum_{k = 1}^3|\sigma_j^m|\, u^h\left( (\q_{j_k}^m)^{-}\right)\cdot v^h\left( (\q_{j_k}^m)^{-}\right),
\end{equation}
where $|\sigma_j^m| = \frac{1}{2}|\mathcal{J}\{\sigma_j^m\}|$ is the area of $\sigma_j^m$, and  $f((\q_{j_k}^m)^{-}) = \lim\limits_{\boldsymbol{x} \rightarrow \q_{j_k}^m, \boldsymbol{x}\in \sigma_j^m} f(\boldsymbol{x})$. For matrix-valued functions $\boldsymbol{U}^h, \boldsymbol{V}^h \in [\mathbb{K}]^{3\times 3}$, we approximate the inner product \eqref{inner product matrix} by $\left< \boldsymbol{U}^h, \boldsymbol{V}^h\right>_{\Gamma^m}^h$ defined as
\begin{equation}
    \left<\boldsymbol{U}^h, \boldsymbol{V}^h\right>_{\Gamma^m}^h \coloneqq\frac{1}{3} \sum_{j = 1}^J \sum_{k =1}^3 |\sigma_j^m|\, \boldsymbol{U}^h\left(  (\q_{j_k}^m)^{-}\right):\boldsymbol{V}^h\left(  (\q_{j_k}^m)^{-}\right).
\end{equation}
Finally, the discretized surface gradient operator $\ds$ defined on $\Gamma$ is formulated in the following:  we can calculate $\ds f$ on a triangle surface element $\sigma = \{\q_{1}, \q_{2}, \q_{3}\}$ for any $f\in \mathbb{K}^m$ as
\begin{equation}\label{discretized surface gradient}
    (\ds f)\big|_{\sigma} \coloneqq  f(\q_1)\frac{(\q_2-\q_3)\times \n}{|\mathcal{J}\{\sigma\}|}+f(\q_2)\frac{(\q_3-\q_1)\times \n}{|\mathcal{J}\{\sigma\}|}+f(\q_3)\frac{(\q_1-\q_2)\times \n}{|\mathcal{J}\{\sigma\}|},
\end{equation}
where $\n$ is the normal vector of $\sigma$ given by \eqref{discrete normal vector}.

Based on the finite element space $\mathbb{K}^m$ defined above, we can define a
 parameterization over $\Gamma^m$ for $\Gamma^{m+1}$ as $\X^{m+1}(\cdot) \in [\mathbb{K}^m]^3$, where $[\mathbb{K}^m]^3$ can be viewed as a finite element approximation of the function space $[H^1(\Gamma(t_m))]^3$. In particular, $\X^m(\cdot)$ represents the identity function in $[\mathbb{K}^m]^3$. Moreover, let $\cur^{m+1}, V^{m+1}\in \mathbb{K}^m$ denote the numerical approximations of the mean curvature and scalar normal velocity of $\Gamma^{m+1}$, respectively.

Then an unconditionally energy-stable PFEM based on the implicit backward Euler scheme is proposed as follows: Given the initial data of an polygonal surface $\Gamma^0$: \quad $\X^0 (\cdot) \in [\mathbb{K}^0]^3$ and $\cur^0(\cdot)\in \mathbb{K}^0$, find the solution $\left(\X^{m+1},V^{m+1},\cur^{m+1}\right) \in [\mathbb{K}^m]^3 \times \mathbb{K}^m\times \mathbb{K}^m$ such that
\begin{subequations}
\label{eqn:full wm}
\begin{align}
\label{eqn:full1 wm}
&\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h= \left(V^{m+1},\,  \phi^h\right)_{\Gamma^m}^h,\qquad \qquad \quad  \forall \phi^h\in \mathbb{K}^m,\\[0.5em]
\label{eqn:full2 wm}
&\left(V^{m+1}\n^m,\w^h\right)_{\Gamma^m}^h=\Big\langle\cur^{m+1} \mathbf{A}^{m}-\n^m(\ds \cur^{m+1})^T-\frac{1}{2}(\cur^{m+1})^2 \ds \X^{m+1},\, \ds \w^h\Big\rangle_{\Gamma^m}^h,\nonumber\\
& \qquad \qquad \qquad \qquad\qquad \qquad \qquad\qquad\qquad \qquad\qquad\qquad \forall \w^h  \in [\mathbb{K}^m]^3, \\[0.5em]
\label{eqn:full3 wm}
&\left(\cur^{m+1}-\cur^m, \,\varphi^h\right)_{\Gamma^m}^h = \Big\langle \ds(\X^{m+1}-\X^m), \n^m (\ds\varphi^h)^T -\varphi^h \mathbf{A}^{m} \Big\rangle_{\Gamma^m}^h,\quad \forall \varphi^h \in \mathbb{K}^m,
\end{align}
\end{subequations}
where $\n^m$ is given in \eqref{discrete normal vector} and $\mathbf{A}^{m}$ is a numerical approximation of the Weingarten map $\ds\n$ at $t=t_m$. 
Since $\n^m$ is piecewise constant in $[\mathbb{K}^h]^3$, the Weingarten map $\ds\n^m$ vanishes under discretized surface gradient \eqref{discretized surface gradient}, necessitating a refined approximation. Here we employ vertex unit normals $\boldsymbol{w}^m$ (see \cite{barrett2008parametric2}) to make normals non-constant over each surface element $\sigma_{j}^m$, enabling a direct computation of the discrete Weingarten map as
\begin{align}\label{eqn:A^m}
    \mathbf{A}^{m} = \ds \boldsymbol{w}^m, \qquad m\ge0.
\end{align}



\subsection{Energy stability}
For the polygonal surface $\Gamma^m$, we define the discretized Willmore energy as 
\begin{equation}
    \label{discretized Willmore energy}
    W^m \coloneqq  \frac{1}{2}\left(\cur^m, \cur^m\right)_{\Gamma^m}^h = \frac{1}{6}\sum_{j = 1}^J\sum_{k = 1}^3|\sigma_{j}^m| \cur^2\left((\q_{j_k}^m)^{-}\right), \qquad m\ge0.
\end{equation}
Then, we have the following energy stability for the proposed ES-PFEM \eqref{eqn:full wm}.
\begin{theorem}[Unconditional energy dissipation of \eqref{eqn:full wm}]
Let $\left(\X^{m+1}, V^{m+1} ,\cur^{m+1}\right)$ be a solution of the ES-PFEM \eqref{eqn:full wm} with the initial data $\X^0$ and $\cur^0$. Then it holds that the discretized Willmore energy \eqref{discretized Willmore energy} decreases, i.e.
\begin{equation}\label{fulld stability}
    W^{m+1}\leq W^m \leq W^0 =  \frac{1}{2}\left(\cur^0, \cur^0\right)_{\Gamma^0}^h, \qquad m\ge0.
\end{equation}
\end{theorem}
\begin{proof}
Choose $\phi^h=-\tau V^{m+1} \in \mathbb{K}^m$ in \eqref{eqn:full1 wm}, $\w=\X^{m+1}-\X^m \in [\mathbb{K}^m]^3$ in \eqref{eqn:full2 wm}, and $\varphi^h = \cur^{m+1} \in \mathbb{K}^m$  in \eqref{eqn:full3 wm}, we obtain
\begin{align}
\label{test func 1}
-\left((\X^{m+1}-\X^m)\cdot \n^m, V^{m+1}\right)_{\Gamma^m}^h=-\tau\left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h,
\end{align}
\begin{align}
\label{test func 2}
\left(V^{m+1}\n^m,\X^{m+1}-\X^m\right)_{\Gamma^m}^h=&\Big\langle\cur^{m+1} \mathbf{A}^m-\n^m(\ds \cur^{m+1})^T,\, \ds (\X^{m+1}-\X^m)\Big\rangle_{\Gamma^m}^h\nonumber\\
 &-\Big\langle\frac{1}{2}(\cur^{m+1})^2 \ds \X^{m+1},\, \ds (\X^{m+1}-\X^m)\Big\rangle_{\Gamma^m}^h,
\end{align}
\begin{align}
\label{test func 3}
 &\left(\cur^{m+1}-\cur^m, \,\cur^{m+1}\right)_{\Gamma^m}^h = \Big\langle \ds(\X^{m+1}-\X^m), \n^m (\ds \cur^{m+1})^T -\cur^{m+1} \mathbf{A}^m \Big\rangle_{\Gamma^m}^h.
\end{align}
Summing \eqref{test func 1}, \eqref{test func 2} and \eqref{test func 3}, we derive that
\begin{align}\label{aeq 0}
	&\left(\cur^{m+1}-\cur^m, \,\cur^{m+1}\right)_{\Gamma^m}^h + \Big\langle\frac{1}{2}(\cur^{m+1})^2\ds \X^{m+1},\, \ds\X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h \nonumber\\
    &=-\tau\left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h \leq 0, \qquad m\ge0.
\end{align}  
By applying the inequality $a(a-b)\geq \frac{1}{2}a^2- \frac{1}{2}b^2$, we know that 
\begin{align}\label{aeq 1}
    \left(\cur^{m+1}-\cur^m, \cur^{m+1}\right)_{\Gamma^m}^h&\geq \frac{1}{2}\left(\cur^{m+1}, \cur^{m+1}\right)_{\Gamma^m}^h -\frac{1}{2}\left(\cur^{m},\cur^{m}\right)_{\Gamma^m}^h\nonumber\\[0.5em]
&= \frac{1}{2}\left(\cur^{m+1}, \cur^{m+1}\right)_{\Gamma^m}^h-W^m.
\end{align}
Similarly for any $\boldsymbol{M} = (m_{ij})$ and $\boldsymbol{N} = (n_{ij})$ in $\bR^{3\times 3 }$, we have
\begin{align}
\boldsymbol{M}:(\boldsymbol{M}-\boldsymbol{N}) &= \sum_{i = 1}^3\sum_{j = 1}^3m_{ij}(m_{ij} -n_{ij})\geq \frac{1}{2}\sum_{i = 1}^3\sum_{j = 1}^3(m_{ij})^2-\frac{1}{2}\sum_{i = 1}^3\sum_{j = 1}^3(n_{ij})^2\nonumber\\
&=\frac{1}{2}\boldsymbol{M}:\boldsymbol{M}-\frac{1}{2}\boldsymbol{N}:\boldsymbol{N}.
\end{align}
 Thus, it can be derived that
\begin{align}\label{aeq 2}
&\Big\langle\frac{1}{2}(\cur^{m+1})^2\ds \X^{m+1},\, \ds \X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h\nonumber\\[0.5em]
&\geq \frac{1}{4}\Big\langle(\cur^{m+1})^2\ds \X^{m+1},\, \ds \X^{m+1}\Big\rangle_{\Gamma^m}^h- \frac{1}{4}\Big\langle(\cur^{m+1})^2\ds \X^{m},\, \ds \X^{m}\Big\rangle_{\Gamma^m}^h\nonumber\\[0.5em]
&=\frac{1}{4}\sum_{j = 1}^J|\sigma_j^m|\left(\ds \X^{m+1}\Big|_{\sigma_j^m}: \ds \X^{m+1}\Big|_{\sigma_j^m}\right) \sum_{k = 1}^3\frac{(\cur_{j_k}^{m+1})^2}{3}\nonumber\\
&\ -\frac{1}{4}\sum_{j = 1}^J|\sigma_j^m|\left(\ds \X^m\Big|_{\sigma_j^m}: \ds \X^m\Big|_{\sigma_j^m}\right) \sum_{k = 1}^3\frac{(\cur_{j_k}^{m+1})^2}{3}\nonumber\\[0.5em]
&\geq \frac{1}{2} \sum_{j=1}^J\sum_{k=1}^3\frac{(\cur_{j_k}^{m+1})^2}{3}(|\sigma_j^{m+1}|-|\sigma_j^m|),
\end{align}
where the last inequality is due to
\begin{align}\label{aeq 3}
    &\frac{1}{2}|\sigma_j^m|\left(\ds \X^{m+1}\Big|_{\sigma_j^m}: \ds \X^{m+1}\Big|_{\sigma_j^m}\right) \geq |\sigma_j^{m+1}|,\\[0.5em]
    &\frac{1}{2}|\sigma_j^m|\left(\ds \X^{m}\Big|_{\sigma_j^m}: \ds \X^{m}\Big|_{\sigma_j^m}\right) = |\sigma_j^{m}|,
\end{align}
which are directly derived from the Lemma 2.1 in \cite{barrett2008parametric1}. 
Moreover, we have the following identity of $W^{m+1}$:
\begin{align}
    \label{aeq 4}
    W^{m+1}& = \frac{1}{2}\sum_{j = 1}^J\sum_{k = 1}^3 \frac{(\cur^{m+1}_{j_k})^2}{3} |\sigma_j^{m+1}| \nonumber\\
    & = \frac{1}{2}\sum_{j = 1}^J \sum_{k = 1}^3 \frac{(\cur^{m+1}_{j_k})^2}{3}|\sigma_j^m| +\frac{1}{2}\sum_{j = 1}^J  \sum_{k = 1}^3 \frac{(\cur^{m+1}_{j_k})^2}{3}(|\sigma_j^{m+1}|-|\sigma_j^m|)\nonumber\\
    &=  \frac{1}{2} (\cur^{m+1}, \cur^{m+1})_{\Gamma^m}^h + \frac{1}{2}\sum_{j = 1}^J \sum_{k = 1}^3 \frac{(\cur^{m+1}_{j_k})^2}{3}(|\sigma_j^{m+1}|-|\sigma_j^m|) .
\end{align}
This, together with \eqref{aeq 0}, \eqref{aeq 1} and \eqref{aeq 2}, yields that
\begin{align}\label{aeq 5}
    W^{m+1}-W^m  = &\frac{1}{2} (\cur^{m+1}, \cur^{m+1})_{\Gamma^m}^h - W^m+ \frac{1}{2}\sum_{j = 1}^J  \sum_{k = 1}^3 \frac{(\cur^m_{j_k})^2}{3}(|\sigma_j^{m+1}|-|\sigma_j^m|)\nonumber\\
    \leq &  \left(\cur^{m+1}-\cur^m, \cur^{m+1}\right)_{\Gamma^m}^h +\Big\langle\frac{1}{2}(\cur^{m+1})^2\ds \X^{m+1},\, \ds \X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h\nonumber\\[0.5em]
    \leq & -\tau (V^{m+1}, V^{m+1})_{\Gamma^m}^h \leq 0,
\end{align}
which is the desired energy stability \eqref{fulld stability}.\qed
\end{proof}


\section{Extension to the curvature-dependent geometric gradient flows}

This section is to extend the ES-PFEM \eqref{eqn:full wm} to the curvature-dependent geometric gradient flows, where the functional $W(\Gamma)$ is generalized to be
\begin{equation}\label{eqn:continuous energy, curvature-dependent geometric gradient flow}
    W(\Gamma) = \int_{\Gamma} f(\cur) \, \dd A,
\end{equation}
where $f(\cur)$ is an arbitrary weakly convex function of the mean curvature $\cur$. The corresponding geometric gradient flow is given by the normal velocity $V$ as \cite{duan2021high}
\begin{equation}\label{eq: curvature-dependent geometric gradient flow}
    V = \lap (f'(\cur)) + |\mathbf{A}|^2f'(\cur) - \cur f(\cur) .
\end{equation}
Specifically, by setting $f(\cur) = \frac{1}{2}\cur^2$, we recover the Willmore energy and the Willmore flow \eqref{eq: Willmore flow}. Furthermore, by setting $f(\cur) \equiv 1$, we have $f'(\cur) \equiv 0$ and $V = -\cur$, which is the mean curvature flow; and by setting $f(\cur) = \cur$, we have $f'(\cur) = 1$ and $V = -2\mathcal{K}$, which is the Gauss curvature flow with $\mathcal{K} = \det(\mathbf{A})$ being the Gaussian curvature.

\subsection{A variational formulation}
Similar to the Willmore flow, in order to derive the variational formulation for the curvature-dependent geometric gradient flow \eqref{eq: curvature-dependent geometric gradient flow}, we need to find a proper weak formulation for $V \n$.  The evolution equation for $\cur$ follows directly from the Willmore flow.

\begin{lemma}\label{lemma: curvature-dependent geometric gradient flow V}
    For a solution $\X$ of the curvature-dependent geometric gradient flow \eqref{eq: curvature-dependent geometric gradient flow} with the scalar normal velocity $V$, it holds that
    \begin{align}
        \label{new identity for V, curvature-dependent geometric gradient flow}
        \int_{\Gamma(t)} V\n\cdot \w \, \dd A&= \int_{\Gamma(t)} \left(f'(\cur) \mathbf{A}  -\n (\ds f'(\cur))^T - f(\cur)\ds \X\right): \ds \w \, \dd A, \nonumber \\
        &\qquad \qquad \quad \forall\, \w \in [H^1(\Gamma(t))]^3.
    \end{align}
\end{lemma}
\begin{proof}
    By utilizing \eqref{divergence vector vector} with $\boldsymbol{f} = \n$ and $\boldsymbol{g} = \ds f'(\cur)$, \eqref{divergence scalar matrix} with $f = f'(\cur)$ and $\boldsymbol{G} = \mathbf{A}$, and \eqref{divergence scalar matrix} with $f = f(\cur)$ and $\boldsymbol{G} = \ds \X$,  we can derive
    \begin{subequations}
        \begin{align}
            \ds \cdot(\n (\ds f'(\cur))^T) &= \ds\n \ds f'(\cur) + \left(\lap f'(\cur)\right) \n \nonumber\\
            &= \mathbf{A} \ds f'(\cur) + \left(\lap f'(\cur)\right) \n,  \label{pf1 eq1, curvature-dependent}\\
            \ds \cdot (f'(\cur) \ds \n) &= \ds\n \ds f'(\cur)+ f'(\cur) \lap \n \nonumber\\
            &= \mathbf{A} \ds f'(\cur) + f'(\cur) \lap \n,  \label{pf1 eq2, curvature-dependent} \\
            \ds \cdot (f(\cur) \ds \X) &= f'(\cur) \ds \X \ds \cur + f(\cur) \lap \X \nonumber\\
            &= f'(\cur)  \ds \cur - \cur f(\cur) \n.   \label{pf1 eq3, curvature-dependent}
        \end{align}
    \end{subequations}
    Next, we consider the linear combination \eqref{pf1 eq1, curvature-dependent} $-$ \eqref{pf1 eq2, curvature-dependent} $+$ \eqref{pf1 eq3, curvature-dependent}, and invoke relation \eqref{gradient multi scalar} and \eqref{pf1 eq5}, we can get the following strong formulation of $V\n$:

    \begin{align}
        &\lap \left(f'(\cur)\n\right) - \ds \cdot \left(2\left(f'(\cur) \ds \n\right) - \left(f(\cur) \ds \X\right) \right) \nonumber\\
         &\ =  \ds \cdot \left(\left(\n (\ds f'(\cur))^T\right) - \left(f'(\cur) \ds \n\right) + \left(f(\cur) \ds \X\right) \right) \nonumber\\
         &\ = \left(\mathbf{A} \ds f'(\cur) + \left(\lap f'(\cur)\right) \n\right) + \left(f'(\cur)  \ds \cur - \cur f(\cur) \n\right)   \nonumber\\
        & \qquad - \left(\mathbf{A} \ds f'(\cur) + f'(\cur) \left(\ds \cur - |\mathbf{A}|^2 \n\right)\right) \nonumber\\
         &\ = \left(\lap f'(\cur)  + |\mathbf{A}|^2 f'(\cur) - \cur f(\cur) \right) \n \nonumber\\
        &\ = V\n.
    \end{align}
Finally, multiplying both sides of the above equation by $\w$, then integrating over $\Gamma(t)$, and 
applying the product rule \eqref{divergence matrix vector}, \eqref{gradient multi scalar}, and the divergence theorem  with $\boldsymbol{f} = \left(2\left(f'(\cur) \ds \n\right) - \left(f(\cur) \ds \X\right)\right)^T \boldsymbol{\omega}$, we have
\begin{align}
    \int_{\Gamma(t)}V\n \cdot \w\, \dd A=& \int_{\Gamma(t)}\left( \lap \left(f'(\cur)\n\right)- \ds\cdot \left(2\left(f'(\cur) \ds \n\right) - \left(f(\cur) \ds \X\right)\right) \right)\cdot \w\,\dd A\nonumber\\
    =&\int_{\Gamma(t)} \left(-\ds(f'(\cur)\n)+ \left(2 f'(\cur) \mathbf{A}- f(\cur) \ds\X\right)\right):\ds\w\,\dd A\nonumber\\
    & \qquad -\int_{\Gamma(t)} \cur\n^T(2f'(\cur) \mathbf{A}- f(\cur) \ds\X) \w\,\dd A.
\end{align}
\begin{align}
    \int_{\Gamma(t)}V\n \cdot \w\, \dd A=&\int_{\Gamma(t)} \left(-\n(\ds f'(\cur))^T-f'(\cur) \mathbf{A} \right):\ds\w\,\dd A\nonumber\\
    & \qquad + \int_{\Gamma(t)} \left(2 f'(\cur) \mathbf{A}- f(\cur) \ds\X\right): \ds \w\,\dd A \nonumber\\
    =&\int_{\Gamma(t)} \left(f'(\cur) \mathbf{A}  -\n (\ds f'(\cur))^T - f(\cur)\ds \X\right):\ds\w\,\dd A,
\end{align}
which yields the result \eqref{new identity for V, curvature-dependent geometric gradient flow}.\qed
\end{proof}

Next, we adopt the temporal evolution of $\cur$ derived in Lemma \ref{lemma H}, thereby deriving the following variational formulation for \eqref{eq: curvature-dependent geometric gradient flow}: Given the initial data $\X(\cdot, 0):= \X_0(\cdot)$ and $\cur(\cdot, 0):= -\n \cdot \lap \X_0(\cdot)$, find the solution $\X(\cdot,t)\in [H^1(\Gamma(t))]^3$, $V(\cdot,t)\in H^1(\Gamma(t))$, and $\cur(\cdot,t)\in H^1(\Gamma(t))$, such that
\begin{subequations}\label{new weak form, curvature-dependent geometric gradient flow}
\begin{align}
    &\left(\n \cdot \dt \X, \phi\right)_{\Gamma(t)} = \left(V, \phi\right)_{\Gamma(t)}, \quad \phi \in H^1(\Gamma(t)),    
    \label{new weak form X, curvature-dependent geometric gradient flow}\\
    &\left(V\n, \w\right)_{\Gamma(t)} = \Big\langle f'(\cur) \mathbf{A} - \n(\ds f'(\cur))^T- f(\cur)\ds \X, \ds\w\Big\rangle_{\Gamma(t)},\nonumber \\
    & \qquad\qquad \hspace{3cm} \w \in [H^1(\Gamma(t))]^3, \label{new weak form V, curvature-dependent geometric gradient flow}\\
    &\left(\dt\cur, \varphi\right)_{\Gamma(t)} = \big\langle\ds(\dt \X), \n (\ds \varphi)^T- \varphi  \mathbf{A} \big\rangle_{\Gamma(t)}, \quad  \varphi\in H^1(\Gamma(t)).\label{new weak form H, curvature-dependent geometric gradient flow}
\end{align}
\end{subequations}
If we take $f(\cur) = \frac{1}{2}\cur^2$, we observe that $f'(\cur) = \cur$, and this weak formulation \eqref{new weak form, curvature-dependent geometric gradient flow} goes to the weak formulation \eqref{new weak form} for the Willmore flow. %Here, the left-hand side is $\left(\dt\cur, \cur \varphi\right)_{\Gamma(t)}$, whereas in the Willmore flow, it is $\left(\dt\cur, \varphi\right)_{\Gamma(t)} $. 

For this weak formulation, we establish the following energy stability result:

\begin{theorem}[Energy dissipation]\label{thm:continuous energy dissipation, curvature-dependent geometric gradient flow}
    Let $\left(\X(\cdot,t), V(\cdot, t), \cur(\cdot,t)\right)$ be a solution of the new variational formulation \eqref{new weak form, curvature-dependent geometric gradient flow} with the initial data 
   $\X(\cdot,0):=\X_0(\cdot)$ and $\cur(\cdot,0):=-\n\cdot\lap \X_0(\cdot)$. 
   Then the curvature-dependent energy $W(\Gamma(t))$ defined in \eqref{eqn:continuous energy, curvature-dependent geometric gradient flow} is decreasing over time,
    \begin{equation}
    \label{eqn: continuous energy dissipation, curvature-dependent geometric gradient flow}
        W(t) \leq W(t')\leq W(0) = \int_{\Gamma_0} f(\cur_0) \,\dd A, \quad \forall t \geq t'\geq 0.
    \end{equation}
\end{theorem}

The proof follows completely analogous to that of the Willmore flow, with the only difference being that in the third equation we choose the test function $\varphi = f'(\cur)$. We therefore omit the detailed proof here for brevity.


\subsection{An energy-stable full discretization}
We then propose the following unconditionally energy-stable full discretization for the new variational formulation \eqref{new weak form, curvature-dependent geometric gradient flow}: Given the initial data of polygonal surface $\Gamma^0$: $\X^0 (\cdot) \in [\mathbb{K}^0]^3$  and $\cur^0(\cdot)\in \mathbb{K}^0$, for any $m\geq 0$, find the solution $\left(\X^{m+1},V^{m+1},\cur^{m+1}\right) \in [\mathbb{K}^m]^3 \times \mathbb{K}^m\times \mathbb{K}^m$, such that
\begin{subequations}
    \label{eqn:full curvature-dependent geometric gradient flow}
    \begin{align}
    \label{eqn:full1 curvature-dependent geometric gradient flow}
    &\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h = \left(V^{m+1}, \phi^h\right)_{\Gamma^m}^h, 
    \quad \forall \phi^h\in \mathbb{K}^m,\\
    \label{eqn:full2 curvature-dependent geometric gradient flow}
    &\left(V^{m+1}\n^m,\w^h\right)_{\Gamma^m}^h = \left\langle f'(\cur^{m+1})) 
    \mathbf{A}^{m}-\n^m(\ds f'(\cur^{m+1})))^T, \ds \w^h\right\rangle_{\Gamma^m}^h \nonumber\\
    &\qquad\qquad\qquad\qquad \qquad - \left\langle f(\cur^{m+1}) \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h,
    \quad \forall \w^h \in [\mathbb{K}^m]^3,\\
    \label{eqn:full3 curvature-dependent geometric gradient flow}
    &\left(\cur^{m+1}-\cur^m, \varphi^h\right)_{\Gamma^m}^h = \left\langle \ds(\X^{m+1}-\X^m), \n^m (\ds \varphi^h)^T \right\rangle_{\Gamma^m}^h \nonumber\\
    &\qquad\qquad\qquad \qquad \qquad - \left\langle \ds(\X^{m+1}-\X^m), \varphi^h \mathbf{A}^{m} \right\rangle_{\Gamma^m}^h,
    \, \forall \varphi^h \in \mathbb{K}^m;
    \end{align}
    \end{subequations}
where $ \mathbf{A}^{m}$ is the numerical approximation of Weingarten map $\ds\n$ given by \eqref{eqn:A^m}.

Define the discretized energy as
\begin{equation}
    \label{discretized curvature-dependent energy}
    W^m \coloneqq \left(f(\cur^m), 1\right)_{\Gamma^m}^h = \frac{1}{3}\sum_{j = 1}^J\sum_{k = 1}^3|\sigma_{j}^m| f\left(\cur\left((\q_{j_k}^m)^{-}\right)\right), \qquad m\ge0.
\end{equation}
Then, we have the following energy stability for the proposed ES-PFEM \eqref{eqn:full curvature-dependent geometric gradient flow}.
\begin{theorem}[Unconditional energy dissipation of \eqref{eqn:full curvature-dependent geometric gradient flow}]
Let $\left(\X^{m+1}, V^{m+1} ,\cur^{m+1}\right)$ be a solution of the ES-PFEM \eqref{eqn:full curvature-dependent geometric gradient flow} with the initial data $\left(\X^0, \cur^0\right)$. Then it holds that the discretized curvature-dependent energy \eqref{discretized curvature-dependent energy} decreases for any $\tau>0$:
\begin{equation}\label{fulld stability, curvature-dependent geometric gradient flow}
    W^{m+1}\leq W^m \leq W^0 =  \left(f(\cur^0), 1\right)_{\Gamma^0}^h, \qquad m\ge0.
\end{equation}
\end{theorem}
\begin{proof}
Let $I_h$ be  the standard interpolation operator defined in \cite[Definition 43(i)]{Barrett2020}. For any scalar functions $f$ and $g$, by utilizing the mass-lumped inner product,  we know that 
\begin{equation}\label{equiv1}
    (f,g)_{\Gamma^m}^h = (f, I_h(g))_{\Gamma^m}^h,
\end{equation}
and by the definition of discretized surface gradient
\begin{equation}\label{equiv2}
    \ds f\Big|_{\sigma_j^m} = \ds I_h(f)\Big|_{\sigma_j^m}.
\end{equation}

    We follow the same proof strategy as in the Willmore flow. Let $\phi^h=-\tau V^{m+1} \in \mathbb{K}^m$ in \eqref{eqn:full1 curvature-dependent geometric gradient flow}, $\w=\X^{m+1}-\X^m \in [\mathbb{K}^m]^3$ in \eqref{eqn:full2 curvature-dependent geometric gradient flow}, and $\varphi^h = I_h(f'(\cur^{m+1})) \in \mathbb{K}^m$ in \eqref{eqn:full3 curvature-dependent geometric gradient flow}, we obtain
    \begin{subequations}
        \begin{align}
        \label{test func 1, curvature-dependent geometric gradient flow}
        &-\left((\X^{m+1}-\X^m)\cdot \n^m, V^{m+1}\right)_{\Gamma^m}^h = -\tau\left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h,\\[0.5em]
        %
        \label{test func 2, curvature-dependent geometric gradient flow}
        &\left(V^{m+1}\n^m,\X^{m+1}-\X^m\right)_{\Gamma^m}^h = \Big\langle f'(\cur^{m+1})) \mathbf{A}^{m},\, \ds (\X^{m+1}-\X^m)\Big\rangle_{\Gamma^m}^h\nonumber\\
        &  \qquad\qquad\qquad\qquad\qquad\quad\quad-\Big\langle \n^m(\ds f'(\cur^{m+1}))^T,\, \ds (\X^{m+1}-\X^m)\Big\rangle_{\Gamma^m}^h\nonumber \\
        &\qquad\qquad\qquad\qquad\qquad\quad\quad-\Big\langle f(\cur^{m+1}) \ds \X^{m+1},\, \ds (\X^{m+1}-\X^m)\Big\rangle_{\Gamma^m}^h,\\[0.5em]
        %
        \label{test func 3, curvature-dependent geometric gradient flow}
        &\left(\cur^{m+1}-\cur^m, I_h(f'(\cur^{m+1}))\right)_{\Gamma^m}^h = \Big\langle \ds(\X^{m+1}-\X^m), \n^m (\ds I_h(f'(\cur^{m+1})))^T  \Big\rangle_{\Gamma^m}^h \nonumber \\
        &\qquad\qquad\qquad\qquad\qquad\qquad\quad - \Big\langle \ds(\X^{m+1}-\X^m), I_h(f'(\cur^{m+1}))) \mathbf{A}^{m} \Big\rangle_{\Gamma^m}^h.
        \end{align}
        \end{subequations}
    By \eqref{equiv1} and \eqref{equiv2},  the \eqref{test func 3, curvature-dependent geometric gradient flow} is equivalent to 
    \begin{align}\label{equiv, test func 3, curvature-dependent gradient flow}
    & \left(\cur^{m+1}-\cur^m, f'(\cur^{m+1})\right)_{\Gamma^m}^h = \Big\langle \ds(\X^{m+1}-\X^m), \n^m (\ds f'(\cur^{m+1}))^T  \Big\rangle_{\Gamma^m}^h \nonumber \\
    &\qquad\qquad\qquad\qquad\qquad\qquad\quad - \Big\langle \ds(\X^{m+1}-\X^m), f'(\cur^{m+1}) \mathbf{A}^{m} \Big\rangle_{\Gamma^m}^h.
    \end{align}
    Summing \eqref{test func 1, curvature-dependent geometric gradient flow}, \eqref{test func 2, curvature-dependent geometric gradient flow} and \eqref{equiv, test func 3, curvature-dependent gradient flow}, we derive that
    \begin{align}\label{aeq 0, curvature-dependent geometric gradient flow}
        &\left(\cur^{m+1}-\cur^m, \,f'(\cur^{m+1})\right)_{\Gamma^m}^h + \Big\langle f(\cur^{m+1})\ds \X^{m+1},\, \ds\X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h \nonumber\\
        &=-\tau\left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h \leq 0.
    \end{align}  
    By the convexity of $f$, we know that $f(\cur^{m})\geq f(\cur^{m+1}) + f'(\cur^{m+1})(\cur^{m}-\cur^{m+1})$. Therefore, we have
    \begin{align}\label{aeq 1, curvature-dependent geometric gradient flow}
    \left(\cur^{m+1}-\cur^m, f'(\cur^{m+1})\right)_{\Gamma^m}^h&\geq \left(f(\cur^{m+1}) - f(\cur^m), 1\right)_{\Gamma^m}^h\nonumber\\[0.5em]
    &= \left(f(\cur^{m+1}) , 1\right)_{\Gamma^m}^h-W^m, \qquad m\ge0.
\end{align}
    Using the same argument as in the Willmore flow, we can derive that
    \begin{align}\label{aeq 2, curvature-dependent geometric gradient flow}
        \Big\langle f(\cur^{m+1})\ds \X^{m+1},\, \ds\X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h \geq W^{m+1} - \left(f(\cur^{m+1}) , 1\right)_{\Gamma^m}^h.
    \end{align}
    All together, we have
    \begin{align}\label{aeq 3, curvature-dependent geometric gradient flow}
        W^{m+1} - W^m \leq -\tau \left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h \leq 0, \qquad m\ge0,
    \end{align}
    which implies the energy dissipation we desired.\qed
\end{proof}


\subsection{Application to the Gauss curvature flow}
We now apply the ES-PFEM \eqref{eqn:full curvature-dependent geometric gradient flow} to the special case of the Gauss curvature flow, i.e., $f(\cur) = \cur$. The Gauss curvature flow is of particular interest for two reasons. First, the linear density function $f(\cur) = \cur$ results in a weakly nonlinear numerical scheme. Second, despite its importance in geometric evolution, there is no prior PFEM proposed for the Gauss curvature flow for surfaces.

For the Gauss curvature flow with $f(\cur) = \cur$, we have $f'(\cur) = 1$, $\nabla_\Gamma f'(\cur) = 0$, and the general scheme \eqref{eqn:full curvature-dependent geometric gradient flow} simplifies to: Given the initial data $\X^0 (\cdot) \in [\mathbb{K}^0]^3$ and $\cur^0(\cdot)\in \mathbb{K}^0$, for any $m\geq 0$, find $\left(\X^{m+1},V^{m+1},\cur^{m+1}\right) \in [\mathbb{K}^m]^3 \times \mathbb{K}^m\times \mathbb{K}^m$ such that
\begin{subequations}
    \label{eqn:full Gauss curvature flow}
    \begin{align}
    \label{eqn:full1 Gauss curvature flow}
    &\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h = \left(V^{m+1}, \phi^h\right)_{\Gamma^m}^h, 
    \quad \forall \phi^h\in \mathbb{K}^m,\\
    \label{eqn:full2 Gauss curvature flow}
    &\left(V^{m+1}\n^m,\w^h\right)_{\Gamma^m}^h = \left\langle \mathbf{A}^{m}, \ds \w^h\right\rangle_{\Gamma^m}^h 
    - \left\langle \cur^{m+1} \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h,
    \quad \forall \w^h \in [\mathbb{K}^m]^3,\\
    \label{eqn:full3 Gauss curvature flow}
    &\left(\cur^{m+1}-\cur^m, \varphi^h\right)_{\Gamma^m}^h = \left\langle \ds(\X^{m+1}-\X^m), \n^m (\ds \varphi^h)^T \right\rangle_{\Gamma^m}^h \nonumber\\
    &\qquad\qquad\qquad\qquad\qquad\qquad - \left\langle \ds(\X^{m+1}-\X^m), \varphi^h \mathbf{A}^{m} \right\rangle_{\Gamma^m}^h,
    \, \forall \varphi^h \in \mathbb{K}^m.
    \end{align}
    \end{subequations}
Notably, the weak nonlinearity appears in only one term $\left\langle \cur^{m+1} \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h$, which in general comes from \eqref{eqn:full2 curvature-dependent geometric gradient flow}: 
\begin{equation*}
    \left\langle f(\cur^{m+1}) \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h.
\end{equation*}
This nonlinearity stems naturally from the energy density $f(\cur)$ itself. Moreover, it is essential in the energy stability proofs for analyzing energy differences between surfaces, i.e.,
\begin{equation*}
    \Big\langle f(\cur^{m+1})\ds \X^{m+1},\, \ds(\X^{m+1}- \X^m)\Big\rangle_{\Gamma^m}^h \geq \left( f(\cur^{m+1}) , 1\right)_{\Gamma^{m+1}}^h - \left( f(\cur^{m+1}) , 1\right)_{\Gamma^m}^h.
\end{equation*}

% the third equation \eqref{eqn:full3 Gauss curvature flow} becomes linear in $\cur^{m+1}$ since $f'(\cur^{m+1}) = 1$ is constant.  %Moreover, the curvature evolution equation \eqref{eqn:full3 Gauss curvature flow} is the same as the one in the Willmore flow \eqref{eqn:full3 wm}.
\begin{remark}
    If we take $f(\cur) \equiv 1$, then $f'(\cur) \equiv 0$, and the weak formulation \eqref{new weak form, curvature-dependent geometric gradient flow} reduces to the following:
    \begin{subequations}\label{new weak form, MCF}
        \begin{align}
            &\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h = \left(V^{m+1}, \phi^h\right)_{\Gamma^m}^h, 
            \quad \forall \phi^h\in \mathbb{K}^m,\label{new weak form X, MCF}\\
            &\left(V^{m+1}\n^m,\w^h\right)_{\Gamma^m}^h = 
            - \left\langle \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h,
            \quad \forall \w^h \in [\mathbb{K}^m]^3,\label{new weak form V, MCF}\\
            &\left(\cur^{m+1}-\cur^m, \varphi^h\right)_{\Gamma^m}^h = \left\langle \ds(\X^{m+1}-\X^m), \n^m (\ds \varphi^h)^T \right\rangle_{\Gamma^m}^h \nonumber\\
    &\qquad\qquad\qquad\qquad\qquad\qquad - \left\langle \ds(\X^{m+1}-\X^m), \varphi^h \mathbf{A}^{m} \right\rangle_{\Gamma^m}^h,
    \, \forall \varphi^h \in \mathbb{K}^m.
        \end{align}
    \end{subequations}
    Note that the evolution equation \eqref{new weak form H, curvature-dependent geometric gradient flow} becomes redundant since the first two equations \eqref{new weak form X, MCF}-\eqref{new weak form V, MCF} do not involve the mean curvature $\cur$. Therefore, the curvature evolution equation \eqref{new weak form H, curvature-dependent geometric gradient flow} is no longer needed, and the system reduces to the first two equations. Remarkably, the first two equations \eqref{new weak form, MCF} coincides exactly with the BGN weak formulation for the mean curvature flow \cite{barrett2008parametric1}:
    \begin{subequations}
        \begin{align*}
            &\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h = -\left(\cur^{m+1}, \phi^h\right)_{\Gamma^m}^h, 
            \quad \forall \phi^h\in \mathbb{K}^m, \\
            &\left(\cur^{m+1}\n^m,\w^h\right)_{\Gamma^m}^h = 
            \left\langle \ds \X^{m+1}, \ds \w^h\right\rangle_{\Gamma^m}^h,
            \quad \forall \w^h \in [\mathbb{K}^m]^3,
        \end{align*}
    \end{subequations}
    with $V^{m+1}$ replaced by $-\cur^{m+1}$. This reveals an interesting connection: despite that our formulation \eqref{new weak form, curvature-dependent geometric gradient flow} comprises three equations while the BGN formulation contains only two, our formulation can still be viewed as a generalization of the BGN formulation.
\end{remark}

\begin{remark}
    By slightly modifying the evolution equation for $\cur$, we can obtain another energy-stable scheme, which can directly reduced to the BGN formulation in \cite{barrett2008parametric1}. Instead of evolving $\cur$, we consider the evolution equation for $f(\cur)$:
    \begin{equation*}
        \label{new identity for H, curvature-dependent geometric gradient flow}
        \int_{\Gamma(t)} \dt \cur (f'(\cur) \varphi) \,\dd A = \int_{\Gamma(t)}\ds (\dt\X): \left(\n(\ds(f'(\cur) \varphi))^T- f'(\cur) \varphi \mathbf{A}\right)\,\dd A.
    \end{equation*}
    Then we derive the following weak formulation
    \begin{subequations}\label{new weak form, curvature-dependent geometric gradient flow, 2}
        \begin{align}
            &\left(\n \cdot \dt \X, \phi\right)_{\Gamma(t)} = \left(V, \phi\right)_{\Gamma(t)}, \quad \phi \in H^1(\Gamma(t)),    
            \label{new weak form X, curvature-dependent geometric gradient flow, 2}\\
            &\left(V\n, \w\right)_{\Gamma(t)} = \Big\langle f'(\cur) \mathbf{A} - \n(\ds f'(\cur))^T- f(\cur)\ds \X, \ds\w\Big\rangle_{\Gamma(t)},\nonumber \\
            & \qquad\qquad \hspace{4cm} \w \in [H^1(\Gamma(t))]^3, \label{new weak form V, curvature-dependent geometric gradient flow, 2}\\
            &\left(\dt\cur, f'(\cur) \varphi\right)_{\Gamma(t)} = \big\langle\ds(\dt \X), \n (\ds(f'(\cur) \varphi))^T- \varphi f'(\cur) \mathbf{A} \big\rangle_{\Gamma(t)},\nonumber \\
            & \qquad \qquad \hspace{4cm}\varphi \in H^1(\Gamma(t)).\label{new weak form H, curvature-dependent geometric gradient flow, 2}
        \end{align}
    \end{subequations}
    When $f(\cur) = 1$, the evolution equation \eqref{new weak form H, curvature-dependent geometric gradient flow, 2} vanishes since it becomes the trivial identity $0 = 0$. This reveals an interesting connection: despite that our formulation \eqref{new weak form, curvature-dependent geometric gradient flow, 2} comprises three equations while the BGN formulation contains only two, our formulation can still be viewed as a generalization of the BGN formulation.
\end{remark}



\section{Mesh improvement and Newton iterations}
In the end of the previous section, we build upon the energy-stable PFEM \eqref{new weak form, curvature-dependent geometric gradient flow, 2}, which reduces to the BGN scheme when $f(\cur)\equiv 1$. This reduction suggests that our formulation may inherit the good mesh quality of the BGN scheme. But in practice, we have observed that the ES-PFEM \eqref{eqn:full wm} in Section 2 often does not exhibit favorable mesh quality.

In fact, the BGN scheme's mesh quality is improved by the mean curvature vector identity  $\cur\n=-\lap\X$, which simultaneously provides the computational formula for $\cur$. In contrast, for the general energy density $f(\cur)$, the computation of mean curvature $\cur$ and mesh quality are governed by distinct equations: the evolution equation for $\cur$ in \eqref{new weak form H, curvature-dependent geometric gradient flow} and the normal velocity equation for $V\n$ in \eqref{new weak form V, curvature-dependent geometric gradient flow}, respectively. This decoupling allows us to enhance mesh quality by adopting the tangential velocity control methodology from \cite{barrett2008parametric2} to modify the $V\n$ equation, while preserving the $\cur$ computation to maintain energy stability. Using the ES-PFEM \eqref{eqn:full wm} as a representative example, we develop an ES-PFEM for the Willmore flow with improved mesh quality, and propose Newton iterative solvers for the resulting nonlinear system.



\subsection{An improved ES-PFEM with controlled tangential motion}
Even though we entirely employ purely normal motion in the derivation of the continuous variational formulation \eqref{new weak form} and the BGN scheme is implicitly included in \eqref{eqn:full curvature-dependent geometric gradient flow}, our fully discretized scheme still improperly introduces significant implicit tangential motion which leads to bad mesh quality. The mesh points under the ES-PFEM \eqref{eqn:full wm} will easily cluster or disperse within a short period, resulting in extremely low robustness of the algorithm.

To control the tangential motion during evolution and therefore improve the mesh quality, the crucial idea is to represent the tangential part of velocity explicitly and then control this part by a given parameter \cite{barrett2008parametric2}.  In the continuous level, reformulate the variational formulation \eqref{new weak form} as follows
\begin{subequations}\label{new weak form reduced}
\begin{align}
    &\left(\n \cdot \dt \X, \phi\right)_{\Gamma(t)} = \left(V, \phi\right)_{\Gamma(t)}, \quad \forall \phi\in L^2(\Gamma(t)),\label{new weak form X reduced}\\
    &\left(\Tau_i \cdot \dt \X, \psi_i\right)_{\Gamma(t)} = \left(\beta_i, \psi_i\right)_{\Gamma(t)}, \quad i = 1,2, \quad \forall \psi_1, \psi_2\in L^2(\Gamma(t)),\label{new weak form b reduced}\\
    &\left(V\n + \alpha \sum_{i = 1,2} \beta_i\Tau_i, \w\right)_{\Gamma(t)} = \Big \langle\cur \mathbf{A}- \n\left(\ds\cur\right)^T- \frac{1}{2}\cur^2\ds \X, \ds\w\Big\rangle_{\Gamma(t)},\nonumber\\
    &\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \qquad\qquad\quad \forall \w\in [H^1(\Gamma(t))]^3,\label{new weak form V reduced}\\
    &\left(\dt\cur, \varphi\right)_{\Gamma(t)} = \Big\langle\ds(\dt \X), \n (\ds \varphi)^T- \varphi \mathbf{A} \Big\rangle_{\Gamma(t)}, \quad \forall \varphi \in H^1(\Gamma(t)),\label{new weak form H reduced}
\end{align}
\end{subequations}
where $\Tau_1, \Tau_2$ are two mutually non-parallel tangent vector fields and $\text{span}\{\n, \Tau_1, \Tau_2\} = \bR^3$, $\alpha >0$ is a hyperparameter which will be detailed in the forthcoming discretization scheme and $\beta_i$ can be viewed as the tangential velocity. In fact,
\begin{equation*}
    \dt \X= V\n \quad \Longleftrightarrow\quad  \beta_i = \Tau_i \cdot \dt \X =0,
\end{equation*}
which implies that \eqref{new weak form V reduced} directly reduces to \eqref{new weak form V}. Thus, it should be mentioned that \eqref{new weak form reduced} and \eqref{new weak form} are equivalent to each other but exhibit significant differences after full discretization.

Since our approach prioritizes purely normal motion, in the fully discrete numerical scheme, we utilize
\begin{equation}
    \left(\Tau_i \cdot \dt \X, \psi_i\right)_{\Gamma(t)} = 0, \quad i = 1,2, \quad \forall \psi_1, \psi_2\in L^2(\Gamma(t)),
\end{equation}
 instead of \eqref{new weak form b reduced} out of $\beta_i =0$. Thus, the fully discretized scheme based on the improved formulation \eqref{new weak form reduced} is given as follows: Given the initial data of polygonal surface $\Gamma^0$: $\X^0 (\cdot) \in [\mathbb{K}^m]^3$  and $\cur^0(\cdot)\in \mathbb{K}^m$ , for any $m\geq 0$, find the solution $\left(\X^{m+1},V^{m+1},\beta^{m+1}_1, \beta^{m+1}_2, \cur^{m+1}\right) \in [\mathbb{K}^m]^3 \times \mathbb{K}^m\times\mathbb{K}^m\times\mathbb{K}^m\times \mathbb{K}^m$, such that
\begin{subequations}
\label{eqn:full wm reduced}
\begin{align}
\label{eqn:full1 wm reduced}
&\left(\frac{\X^{m+1}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h= \left(V^{m+1},\,  \phi^h\right)_{\Gamma^m}^h,\qquad \qquad \quad  \forall \phi^h\in \mathbb{K}^m,\\[0.5em]
\label{eqn:full2 wm reduced}
&\left((\X^{m+1}-\X^m)\cdot \Tau^m_i, \psi^h_i\right)_{\Gamma^m}^h= 0,\qquad \qquad \qquad i = 1,2, \quad\forall \psi^h_1, \psi^h_2\in \mathbb{K}^m,\\[0.5em]
\label{eqn:full3 wm reduced}
&\left(V^{m+1}\n^m+ \alpha^m\sum_{i = 1,2} \beta^{m+1}_i \Tau_i^m ,\w^h\right)_{\Gamma^m}^h=\Big\langle\cur^{m+1} \mathbf{A}^m-\n^m(\ds \cur^{m+1})^T,\, \ds \w^h\Big\rangle_{\Gamma^m}^h\nonumber\\
& \qquad \qquad  \qquad\qquad-\Big\langle\frac{1}{2}(\cur^{m+1})^2 \ds \X^{m+1},\, \ds \w^h\Big\rangle_{\Gamma^m}^h,\quad \forall \w^h  \in [\mathbb{K}^m]^3, \\[0.5em]
\label{eqn:full4 wm reduced}
&\left(\cur^{m+1}-\cur^m, \,\varphi^h\right)_{\Gamma^m}^h = \Big\langle \ds(\X^{m+1}-\X^m), \n^m (\ds\varphi^h)^T -\varphi^h \mathbf{A}^m \Big\rangle_{\Gamma^m}^h,\quad  \forall \varphi^h \in \mathbb{K}^m;
\end{align}
\end{subequations}
where $\alpha^m$ is a hyperparameter. Here the two non-parallel unit tangential vectors $\Tau_1^m$ and $\Tau_2^m$ of the polynomial surface are defined as follows: on each surface element $\sigma_j^m = \{\q_{j_1}^m, \q_{j_2}^m, \q_{j_3}^m\}$
\begin{equation}
\boldsymbol{\tau}^m_1\big|_{\sigma_j^m}\coloneqq  \frac{\q_{j_2}^m- \q_{j_1}^m}{|\q_{j_2}^m- \q_{j_1}^m|}, \quad \boldsymbol{\tau}^m_2\big|_{\sigma_j^m}\coloneqq  \frac{\q_{j_3}^m- \q_{j_1}^m}{|\q_{j_3}^m- \q_{j_1}^m|}. 
\end{equation}
And since $\sigma_j^m$ is nondegenerate, $\Tau_1^m|_{\sigma_j^m}$ and $\Tau_2^m|_{\sigma_j^m}$ are not parallel.
We now clarify the role of the hyperparameter $\alpha^m$.  As indicated by equation (\ref{eqn:full2 wm reduced}), $\beta^{m+1}$ can still be roughly interpreted as an indicator of tangential velocity in full discretization. Observing (\ref{eqn:full3 wm reduced}), the right-hand side term after discretization introduces a component along the tangential directions $\boldsymbol{\tau}_i^m$. Notably, this tangential component is independent of $\alpha^m$. When $\alpha^m$ is sufficiently large ($\alpha^m>1$), this leads to a reduction in $\beta^{m+1}$, effectively suppressing the tangential velocity. And when $\alpha^m = 0$, \eqref{eqn:full wm reduced} reduces to the original ES-PFEM \eqref{eqn:full wm}.

Notably, the ES-PFEM \eqref{eqn:full wm reduced} preserves energy dissipation.
\begin{theorem}[Unconditional energy dissipation of \eqref{eqn:full wm reduced}]\label{thm: energy2}
    Let $\left(\X^{m+1}, V^{m+1} ,\cur^{m+1}\right)$ be a solution of our ES-PFEM \eqref{eqn:full wm reduced} with initial data $\left(\X^0,\cur^0\right)$. Then the discretized Willmore energy \eqref{discretized Willmore energy} decreases with respect to $m$ unconditionally when the hyperparameter $\alpha^m\geq 0$.
\end{theorem}
\begin{proof}
    Taking $\phi^h = -\tau V^{m+1}\in \mathbb{K}^m$ in \eqref{eqn:full1 wm reduced}, $\psi^h_i = -\alpha^m\beta^{m+1}_i\in \mathbb{K}^m$ in \eqref{eqn:full2 wm reduced} for $i = 1,2$, $\w^h = \X^{m+1}-\X^m\in [\mathbb{K}^m]^3$ in \eqref{eqn:full3 wm reduced} and $\varphi^h = \cur^{m+1} \in \mathbb{K}^m$ in \eqref{eqn:full4 wm reduced}, and summing them together, we derive that
    \begin{align}\label{pf6 eq1}
        &\left(\cur^{m+1}-\cur^m, \,\cur^{m+1}\right)_{\Gamma^m}^h + \Big\langle\frac{1}{2}(\cur^{m+1})^2\ds \X^{m+1},\, \ds\X^{m+1}-\ds \X^m\Big\rangle_{\Gamma^m}^h \nonumber\\
        &=-\tau\left(V^{m+1},\, V^{m+1}\right)_{\Gamma^m}^h \leq 0,
    \end{align}
which is the same as the equation \eqref{aeq 0}. Therefore, the subsequent proof follows identically to \eqref{aeq 5}, which implies the energy dissipation we desired.\qed
\end{proof}

\subsection{Newton iterative solver}
To solve the fully implicit numerical scheme \eqref{eqn:full wm reduced}, we employ the Newton-Rhapson iterations.

Given $\left(\X^m, \cur^m\right)\in [\mathbb{K}^m]^3 \times \mathbb{K}^m$, at time step $t_{m+1}$, set $\X^{m+1,0}=\X^m$ and $\cur^{m+1,0}=\cur^m$ as the initial guess of the nonlinear problem \eqref{eqn:full wm reduced}, where $V^{m+1,0}$ and $\beta_i^{m+1,0}$ are chosen arbitrarily because we do not need their values at $t = t_m$ in the scheme \eqref{eqn:full wm reduced}. And in the $l$-th iteration, given $\left(\boldsymbol{X}^{m+1, l}, V^{m+1,l}, \beta^{m+1,l}_1, \beta^{m+1,l}_2, \cur^{m+1,l}\right) \in [\mathbb{K}^m]^3 \times \mathbb{K}^m\times \mathbb{K}^m\times \mathbb{K}^m\times \mathbb{K}^m $ , the Newton direction $\left(\boldsymbol{X}^{\delta}, V^{\delta}, \beta^{\delta}_1, \beta^{\delta}_2, \cur^{\delta}\right)$  can be obtained by solving
\begin{subequations}
    \label{iteration}
    \begin{align}
        &\left(\frac{1}{\tau}\X^{\delta}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h -\left(V^{\delta}, \phi^h\right)_{\Gamma^m}^h= -\left(\frac{\X^{m+1,l}-\X^m}{\tau}\cdot \n^m, \phi^h\right)_{\Gamma^m}^h
        +\left(V^{m+1,l},\phi^h\right)_{\Gamma^m}^h,\\[0.5em]
         &\left(\X^{\delta}\cdot \Tau_i^m, \psi^h_i\right)_{\Gamma^m}^h= -\left((\X^{m+1,l}-\X^m)\cdot \Tau_i^m, \psi^h_i\right)_{\Gamma^m}^h,\quad \quad i = 1,2,\\[0.5em]
         &\Big\langle\frac{1}{2}(\cur^{m+1,l})^2\ds\X^{\delta}, \ds\w^h\Big \rangle_{\Gamma^m}^h + \left(V^{\delta}\n^m + \alpha^m \sum_{i = 1,2}\beta_i^{\delta}\Tau_i^m, \w^h\right)_{\Gamma^m}^h\nonumber\\ 
         & \qquad -\Big\langle\cur^{\delta}\mathbf{A}^m- \n^m(\ds\cur^{\delta})^T, \ds\w^h\Big\rangle_{\Gamma^m}^h+\Big\langle\cur^{m+1,l}\cur^{\delta}\ds\X^{m+1,l}, \ds\w^h\Big \rangle_{\Gamma^m}^h\nonumber\\
        & \quad = -\left(V^{m+1,l}\n^m + \alpha^m \sum_{i= 1,2}\beta_i^{m+1,l}\Tau_i^m ,\w^h\right)_{\Gamma^m}^h-\Big\langle\frac{1}{2}(\cur^{m+1,l})^2 \ds\X^{m+1,l}, \ds\w^h\Big\rangle_{\Gamma^m}^h\nonumber\\
         & \qquad +\Big\langle\cur^{m+1,l}\mathbf{A}^m-\n^m (\ds\cur^{m+1,l})^T, \ds \w^h\Big\rangle_{\Gamma^m}^h, \\[0.5em]
         &- \Big\langle\ds\X^{\delta}, \n^m(\ds\varphi^h)^T- \varphi^h\mathbf{A}^m\Big \rangle_{\Gamma^m}^h+\left(\cur^{\delta},\varphi^h\right)_{\Gamma^m}^h = -\left(\cur^{m+1,l}-\cur^{m},\varphi^h\right)_{\Gamma^m}^h\nonumber\\
         &  \qquad \qquad \qquad \qquad\qquad  +\Big\langle\ds(\X^{m+1,l}-\X^m), \n^m(\ds\varphi^h)^T- \varphi^h\mathbf{A}^m\Big \rangle_{\Gamma^m}^h;
    \end{align}
\end{subequations}
for all $\phi^h \in \mathbb{K}^m$, $\psi^h_1\in \mathbb{K}^m$, $\psi_2^h \in \mathbb{K}^m$, $\boldsymbol{\omega}^h \in [\mathbb{K}^m]^3$ and $\varphi^h \in \mathbb{K}^m$. And for each $m\geq 0$, update the solution by 
$$\X^{m+1,l+1} = \X^{m+1, l} +\X^{\delta},\quad V^{m+1, l+1} = V^{m+1,l}+ V^{\delta},$$
$$\beta_i^{m+1,l+1} = \beta^{m+1,l}_i + \beta_i^{\delta},\quad \cur^{m+1,l+1} = \cur^{m+1,l}+ \cur^{\delta}.$$
 The iteration terminates when
$$
\max\left\{ \Vert \boldsymbol{X}^{\delta}\Vert_{L^{\infty}}, \Vert V^{\delta}\Vert_{L^{\infty}}, \Vert \beta_i^{\delta}\Vert_{L^{\infty}}, \Vert \cur^{\delta}\Vert_{L^{\infty}}\right\}\leq \text{tol},
$$
where $\Vert\cdot \Vert_{L^{\infty}}$ is defined as 
\begin{equation}
    \Vert f^h\Vert_{L^{\infty}} = \max_{1\leq k\leq K}|f^h(\q_k^m)|, \quad f^h \in \mathbb{K}^m, % / [\mathbb{K}^m]^3,
\end{equation}
and tol is the chosen tolerance to ensure that the iteration achieves a certain level of accuracy when the conditions are met.  The numerical solution of (\ref{eqn:full wm reduced}) is given by
$$
\boldsymbol{X}^{m+1} =\boldsymbol{X}^{m+1,l+1}, \quad V^{m+1} = V^{m+1,l+1},\quad \beta_i^{m+1} = \beta_i^{m+1,l+1} ,\quad \cur^{m+1} = \cur^{m+1,l+1}. 
$$


After the Newton iterations, the hyperparameter $\alpha^m$ is adjusted to $\alpha^{m+1}$ by the following algorithm according to $\beta_i^{m+1}$. When the $\beta_1^m$ and $\beta_2^m$ are too large/small, we increase/decrease the value of the hyperparameter by a factor $C$.
\begin{algorithm}\label{alg:1}
\caption{Adaptive $\alpha^m$}
\begin{algorithmic}[1]
\Require $\alpha^{m}$: hyperparameter at $t_m$; \  $\beta_i^{m+1}$: results from the Newton iterations;\  $C$: a constant $C>1$

\If{$\beta_i^{m+1} \geq 10^{-4}$}
    \State $\alpha^{m+1}= C\alpha^m$;
\ElsIf{$\beta_i^{m+1} \leq 10^{-6}$}
    \State $\alpha^{m+1}= \alpha^m/C$;
\EndIf

\end{algorithmic}
\end{algorithm}

To initialize the iterative solver, we also need the initial data $\cur^0$ and initial hyperparameter $\alpha^0$. The curvature $\cur^0$ is approximated via the definition of $\cur$ \cite{barrett2008parametric2},
\begin{equation}
    \left(\cur^0, \chi^h\right)_{\Gamma^0}^h = \left(\text{Tr}(\mathbf{A}^0),\chi^h\right)_{\Gamma^0}^h, \quad \forall \chi^h \in \mathbb{K}^0.
\end{equation}
And $\alpha^0$ is subjectively determined in our following numerical tests.

\begin{remark}
    We must emphasize that the method employed in this section inherently aims to suppress tangential motion. While theoretically, this suppression could be achieved through discretizing purely normal motion, but our actual code implementation revealed that the numerical scheme derived from purely normal motion  still leads to rapid mesh collapse.
\end{remark}

\begin{remark}
    The above mesh improvement approach and Newton iteration can be similarly applied to  curvature-dependent geometric gradient flows.
\end{remark}

\section{Numerical results}

In this section, numerical experiments are carried out to validate the performance of our proposed ES-PFEM \eqref{eqn:full wm reduced}, which includes the investigation of convergence order, the validation of the energy dissipation and morphological evolutions of closed surfaces.

Here are the initial surfaces we consider in our tests:
\begin{itemize}
\item Unit sphere: $x^2 +y^2 + z^2 = 1$.
\item Ellipsoid: $\frac{x^2}{a} + \frac{y^2}{b} + z^2 = 1$.
\item Torus: $(R- \sqrt{x^2+y^2})^2 + z^2 = r^2$.
\end{itemize}
And among all of our numerical tests, tol in the Newton iterations is chosen as $10^{-10}$. For adaptive $\alpha^m$,  the initial hyperparameter  $\alpha^0 = 10^{6}$ and constant $C = 5$ in Algorithm 1. 

\subsection{Numerical tests for the Willmore flow}

The sphere and Clifford torus (torus with $R:r = \sqrt{2}:1$)  are critical points of the Willmore energy and thus are the steady-state solutions of the Willmore flow. Specifically, spheres globally minimize the Willmore energy among all closed surfaces with a value of $8\pi$\cite{willmore1993riemannian}. And among all closed surfaces with positive genus, the minimal Willmore energy is proved to be $4\pi^2$ achieved by the Clifford torus \cite{marques2014min,marques2014willmore}. 

