\section{Differential calculus}
First, let us introduce several basic multiplication rules for surface differential operators. For the scalar-valued function $f\in C^1(\Gamma)$ and vector-valued function $\boldsymbol{f}, \, \boldsymbol{g} \in [C^1(\Gamma)]^3$, there holds that

Under our parameterization $\X$, by definition of surface gradient,
\begin{equation}\label{ds X}
     \ds \X = \boldsymbol{I}-\n\n^T.
\end{equation}
Thus, $\ds\X$ is symmetric. Moreover,
\begin{align} 
    &\ds \X \ds f = \ds f,\label{ds X multi f}\\
    &\ds \boldsymbol{f} (\ds \X)^T = \ds \boldsymbol{f} \ds \X = \ds \boldsymbol{f} \label{ds X multi vecor f}.
\end{align}
\section{Proof of Lemma 2.1}
Now we prove the Lemma 2.1. From the Theorem 22 in \cite{Barrett2020}, 
\begin{equation}
    \int_{\Gamma}\ds \cdot \boldsymbol{f} \, \dd A =\int_{\Gamma}\cur \boldsymbol{f}\cdot \n \, \dd A.
\end{equation}
Replacing $\boldsymbol{f}$ with $g\boldsymbol{f}$ in the above equation, where $g\in  C^1(\Gamma)$, we derive that 
\begin{equation}
    \int_{\Gamma}g\ds\cdot \boldsymbol{f}\,\dd A = \int_{\Gamma} g \cur \boldsymbol{f}\cdot \n\,\dd A - \int_{\Gamma} \boldsymbol{f}\cdot \ds g \, \dd A.
\end{equation}
For the matrix-valued function $\boldsymbol{F}\in [C^1(\Gamma)]^3$,
    \begin{align}
        \int_{\Gamma} (\ds\cdot\boldsymbol{F})\cdot \boldsymbol{g} \, \dd A& = \int_{\Gamma}\sum_{j = 1}^3 g_j \ds\cdot (\boldsymbol{F}\boldsymbol{e}_j)\, \dd A\nonumber\\
        &=\sum_{j = 1}^3  \int_{\Gamma} g_j \cur (\boldsymbol{F}\boldsymbol{e}_j)\cdot \n\,\dd A - \sum_{j = 1}^3 \int_{\Gamma} (\boldsymbol{F}\boldsymbol{e}_j)\cdot \ds g_j \, \dd A.\nonumber\\
        &= \int_{\Gamma} \cur\n^T\boldsymbol{F}\boldsymbol{g}\, \dd A-\int_{\Gamma} \boldsymbol{F}^T: \ds \boldsymbol{g}\,\dd A.
    \end{align}
