\section{Omitted Proofs From Section \ref{sec: decision problem}}\label{apx: ommited proofs decision}
\PPSZthreeSAT*
\begin{proof}
Recall that $R_k(r)$ is the smallest nonnegative solution $R$ to $\Big(r+(1-r)R\Big)^{k-1} = R$.
Now we focus on the case that $k=3$ and solve for $R_3(r)$, 
\begin{align*}
    R_3(r)&=\begin{cases}
        \left(\frac{r}{1-r}\right)^2 & 0\le r\le \frac{1}{2}\\
        1 & \frac{1}{2}\le r\le1
    \end{cases}.
\end{align*}
Then we evaluate $\epsilon_3$,
\begin{align*}
    \epsilon_3&=\epsilon -  \int_{0}^{\epsilon}{R_3(r)dr}\\
    &=\epsilon - \left(\frac{1}{1-\epsilon}+2\ln{(1-\epsilon)}-1+\epsilon \right)\\
    &=-\frac{1}{1-\epsilon}-2\ln{(1-\epsilon)}+1.
\end{align*}

Now we apply Theorem \ref{thm: subset PPSZ kSAT}. Recall that without advice $R_3 = 2- 2\ln{2}$ and $c_3 =2^{ 2\ln{2} - 1 +o(1)}$, therefore
\begin{align*}
    c_3' &= c_3 \cdot 2^{- \epsilon_3}\\
         &= 2^{2\ln{2} - 1 +o(1)- \epsilon_3}\\
         &=2^{\left(\frac{\epsilon}{1-\epsilon}+2\ln{(2-2\epsilon)}-1+o(1)\right)}.
\end{align*}
\end{proof}

\thmHardnessSat*
\begin{proof}
Let $\epsilon_0<\delta$, where $\delta$ is the constant in the ETH. Suppose there is a polynomial time algorithm that solves \threesat given subset advice with parameter $\epsilon\le\epsilon_0$. Fix a subset of size $\epsilon n$, we can simulate a subset advice by enumerating all possible assignments then run the algorithm, thereby solving \threesat in time $O(2^{\epsilon n}\mathrm{poly}(n))\le O(2^{\delta n})$, contradicting ETH.
\end{proof}

\section{Omitted Proofs From Section \ref{sec: optimization problem}}\label{apx: ommited proofs optimization}
\thmHardnessMaxSat*
\begin{proof}
Let $\epsilon_0<\delta$ in the ETH. Suppose there is a polynomial time algorithm that given a fully satisfiable instance of \maxthreesat and subset advice with parameter $\epsilon\le\epsilon_0$, returns a solution satisfying at least a $(1-\gamma)$-fraction of the clauses. Given input $\phi$, we fix a subset of size $\epsilon n$ and simulate a subset advice by enumerating all possible assignments, then run the algorithm. If $\phi$ is fully satisfiable, eventually we will get a solution satisfying at least a $(1-\gamma)$-fraction of the clauses; on the other hand, if $\mathrm{sat}(\phi)<1-\gamma$, no solution can satisfy a $(1-\gamma)$-fraction, thereby we can distinguish between the two cases in time $O(2^{\epsilon n}\mathrm{poly}(n))\le O(2^{\delta n})$, contradicting Gap-ETH.
\end{proof}

\thmMaxTwoSatLabel*
\begin{proof} 
The proof follows from a chain of inequalities in expectation over the randomness the advice.
\begin{enumerate}
    \item $f(\hat{y}) \le f(y)$, where $y$ is the QP solution, and $\hat{y}$ is the rounding of $y$. This follows from the same argument as in \cite{ghoshal2024constraint}.
    \item $f(y)\le F(y,\tilde{y})$, where $F(y,\tilde{y})$ is the minimum value of the QP attained at solution $y$. This step follows from Lemma \ref{lemma: f(y) to F(y)}, which is an extension of Claim 3.2 from \cite{ghoshal2024constraint}.
    \item $F(y,\tilde{y}) \le F(y^*,\tilde{y})$, where $y^*$ is the vector corresponding to the ground-truth optimal solution $x^*$. This step directly follows from the optimality of the QP solution $y$, and the fact that $y^*$ is feasible to the QP.
    \item $ F(y^*,\tilde{y}) \le f(y^*) + m\cdot O(\frac{1}{\epsilon \sqrt{\Delta}})$. This step follows from Lemma \ref{lemma: F(y*) to f(y*)}, which is an extension of Lemma 3.3 from \cite{ghoshal2024constraint}.
\end{enumerate}
Putting these together, and we may assume $\OPT \ge \frac{3}{4}m$,
\begin{align*}
    f(\hat{y})&\le f(y^*) + m\cdot O\left(\frac{1}{\epsilon \sqrt{\Delta}}\right), \\
    \numSAT(\hat{y})&= \frac{3}{4}m - \frac{1}{8}f(\hat{y}) \\
    &\ge \frac{3}{4}m - \frac{1}{8}f(y^*) -  m\cdot O\left(\frac{1}{\epsilon \sqrt{\Delta}}\right)\\
    &\ge \OPT - \OPT\cdot  O\left(\frac{1}{\epsilon \sqrt{\Delta}}\right)\\
    &\ge \OPT \cdot \left(1-O\left(\frac{1}{\epsilon \sqrt{\Delta}}\right)\right) .
\end{align*}
\end{proof}

\begin{restatable}[]{lemma}{lemmafToF}\label{lemma: f(y) to F(y)}
    For $y \in [-1,1]^{2n+1}$, $f(y)\le F(y,\tilde{y})$.
\end{restatable}
% \lemmafToF*
\begin{proof}This Lemma is a modified version of Claim 3.2 \cite{ghoshal2024constraint}, we include a full proof for completeness.
    \begin{align*}
        f(y) &= 2\underset{i\in[2n]}{\sum}y_0y_id_i +\langle{y,Ay}\rangle \\
        &= 2\underset{i\in[2n]}{\sum}y_0y_id_i +\langle{y,A\tilde{y}/\epsilon}\rangle + \langle{y,A(y-\tilde{y}/\epsilon)}\rangle \\
        &\le 2\underset{i\in[2n]}{\sum}y_0y_id_i +\langle{y,A\tilde{y}/\epsilon}\rangle + \inftynorm{y}\cdot \onenorm{A (y - \tilde{y}/\epsilon)}\\
        & = 2\underset{i\in[2n]}{\sum}y_0y_id_i +\langle{y,A\tilde{y}/\epsilon}\rangle +\onenorm{A (y - \tilde{y}/\epsilon)}\\
        & = F(y,\tilde{y}),
    \end{align*}
where the inequality follows from Hölder's inequality.
\end{proof}


\begin{restatable}[]{lemma}{lemmaFtof}\label{lemma: F(y*) to f(y*)}
    $\expect{\tilde{y}}{F(y^*,\tilde{y})} \le f(y^*) + \frac{2}{\epsilon}\sqrt{mn}$. 
    \\Note that $\frac{2}{\epsilon}\sqrt{mn} = m\cdot O(\frac{1}{\epsilon \sqrt{\Delta}})$, following the definition of $\Delta = \frac{m}{n}$.
\end{restatable}
% \lemmaFtof*
\begin{proof}   
Let $z =  y^* - \tilde{y}/\epsilon$. First we calculate the mean and variance of $\tilde{y_i}$ and $z_i$. 
\begin{align*}
    &\expect{}{\tilde{y_i}} = \frac{1+\epsilon}{2} y_i^* + \frac{1-\epsilon}{2}(-y_i^*) =  \epsilon y_i^*,\\
    &\expect{}{z_i} = 0,\\
    &\expect{}{z_i^2} = \frac{1+\epsilon}{2}(y_i^* - y_i^*/\epsilon )^2 + \frac{1-\epsilon}{2}( y_i^* + y_i^*/\epsilon)^2 =\frac{1-\epsilon^2}{\epsilon^2}.
\end{align*}
Consider
\begin{align*}
    \expect{\tilde{y}}{F(y^*,\tilde{y})} &= 2\underset{i\in[2n]}{\sum}y^*_0y^*_id_i +\expect{\tilde{y}}{\langle y^*,A \tilde{y}/\epsilon\rangle} +  \expect{\tilde{y}}{\onenorm{Az}}\\
    &=2\underset{i\in[2n]}{\sum}y^*_0y^*_id_i +\langle{y^*,A\expect{\tilde{y}}{\tilde{y}/\epsilon}}\rangle+  \expect{\tilde{y}}{\onenorm{Az}}\\
    &=2\underset{i\in[2n]}{\sum}y^*_0y_i^*d_i +\langle{y^*,Ay^*}\rangle+  \expect{\tilde{y}}{\onenorm{Az}}\\
    &=f(y^*) +  \expect{\tilde{y}}{\onenorm{Az}}
\end{align*}

According to the proof of Lemma 3.3 \cite{ghoshal2024constraint}, the expectation term
\begin{align*}
    \expect{\tilde{y}}{\onenorm{Az}} 
    &\le \sqrt{2n} \ \expect{\tilde{y}}{\twonorm{Az}}\\
    &\le \sqrt{2n} \sqrt{\expect{}{z_i^2}\cdot \fnorm{A}^2 } \\
    &\le \sqrt{2n}\sqrt{\frac{1-\epsilon^2}{\epsilon^2}}\fnorm{A}\\
    &\le \frac{2}{\epsilon}\sqrt{mn},
\end{align*}
since $\fnorm{A}^2 = 2m$.
\end{proof}

\propLinToSat*
\begin{proof}
Recall the reduction:
given a MAX-$2$-LIN instance on $n$ variables and $m$ constraints, we can reduce it to \maxtwosat on $n$ variables and $M=2m$ clauses in the following way:
\begin{itemize}
    \item For MAX-$2$-LIN constraint $x_i\cdot x_j = +1$, add $2$ clauses in \maxtwosat: $(x_i \lor \bar{x_j}) \land (\bar{x_i} \lor x_j)$;
    \item For MAX-$2$-LIN constraint $x_i\cdot x_j = -1$, add $2$ clauses in \maxtwosat: $(x_i \lor x_j) \land (\bar{x_i} \lor \bar{x_j})$.
\end{itemize}
Given a solution $x$ to the \maxtwosat problem, we can translate it to a solution $z$ to the MAX-$2$-LIN problem by setting $z_i = 1$ if $x_i=1$, and $z_i= -1$ if $x_i=0$.

Notice that for each of the constraint and its $2$ corresponding clauses, the constraint is satisfied if and only if both clauses are true, and the constraint is not satisfied if and only if exactly one of the clauses is true. Therefore, $\numLIN = \numSAT - m$. 
Denote the value of an optimal solution to MAX-$2$-LIN as $m^*$, and the value of an optimal solution to \maxtwosat as $M^*$, and notice that $m^* = M^* - m$.
Given an assignment $x$ that satisfies $\left(1-O(\delta)\right)\cdot M^*$ clauses in \maxtwosat, the number of constraints in MAX-$2$-LIN satisfied by corresponding $y$ is
\begin{align*}
    \numLIN &= \numSAT - m\\
    &=\left(1-O(\delta)\right)\cdot M^* - m\\
    &=\left(1-O(\delta)\right)\cdot(m^*+m) - m\\
    &=\left(1-O(\delta)\right) \cdot m^* - O(\delta)\cdot m\\
    &=\left(1-O(\delta)\right) \cdot m^*, \text{ since we may assume } m^* = \Theta(m).
\end{align*}

Given label advice, our Theorem \ref{thm: label max2sat} is a generalization of Theorem 1.4 from \cite{ghoshal2024constraint}. By mapping $\{-1,1\}$ to $\{0,1 \}$, an advice to the MAX-$2$-LIN instance can be translated as an advice to the \maxtwosat instance with the same $\epsilon$. Furthermore, the degree of the MAX-$2$-LIN instance is $\Delta = \frac{2m}{n}$ which is equal to the degree of the \maxtwosat instance $\frac{M}{n}$, so the same average degree assumption applies to both problems as well. Therefore we recover the solution to MAX-$2$-LIN and generalize the previous results from the ``symmetric" constraint satisfaction problems to ``non-symmetric" SAT problems.
\end{proof} 


