	GA([7 0 0])
	toc
	Elapsed time is 1.108590 seconds.
	tic
	a = MV.rand([7,0,0]);
	b = a^-1;
	toc
	Elapsed time is 0.005595 seconds.

	tic
	GA([8 0 0])
	toc
	Elapsed time is 4.122144 seconds.
	tic
	a = MV.rand([8,0,0]);
	b = a^-1;
	toc
	Elapsed time is 0.004904 seconds.

	tic
	GA([9 0 0])
	toc
	Elapsed time is 18.076994 seconds.
	tic
	a = MV.rand([9,0,0]);
	b = a^-1;
	toc
	Elapsed time is 0.012538 seconds.

	tic
	GA([9 1 0])
	toc
	Elapsed time is 95.988849 seconds.
	tic
	a = MV.rand([9,1,0]);
	b = a^-1;
	toc
	Elapsed time is 0.180647 seconds.
\end{colorverbatim}
\begin{rem}
	The computation of symbolic multivector inverses in geometric algebras satisfying $p+q+r>5$ with $\mathtt{SUGAR}$ can be employed to derive closed-form formulas for computing such inverses. Existing formulas found in the literature only extend up to $p+q+r=5$ \cite{Hitzer_inv}. The authors are currently preparing an article further exploring this idea.
\end{rem}
\subsection{Functions of multivectors}
Basic Matlab functions have been overloaded to allow operating with numeric or symbolic multivectors. Some of these functions include $\sin$, $\mathrm{asin}$, $\sinh$, $\mathrm{asinh}$, $\cos$, $\mathrm{acos}$, $\cosh$, $\mathrm{acosh}$,  $\tan$, $\mathrm{atan}$, $\tanh$, $\mathrm{atanh}$, $\cot$, $\mathrm{acot}$, $\coth$, $\mathrm{acoth}$, $\csc$, $\mathrm{acsc}$, $\mathrm{csch}$, $\mathrm{acsch}$, $\sec$, $\mathrm{asec}$, $\mathrm{sech}$, $\mathrm{asech}$, $\log$, and $\exp$. In the following code, the exponential of a randomly generated multivector $A$ is computed first, and then the logarithm of the previous result is computed, leading again to $A$:
\begin{colorverbatim}
	>> A=MV.rand([2 0 0])
	A = 
	(0.81472)*e0+(0.90579)*e1+(0.12699)*e2+(0.91338)*e12
	>> exp(A)
	ans = 
	(2.2612)*e0+(2.0466)*e1+(0.28692)*e2+(2.0637)*e12
	>> log(ans)
	ans = 
	(0.81472)*e0+(0.90579)*e1+(0.12699)*e2+(0.91338)*e12
\end{colorverbatim}
\noindent Analogously, the exponential of a symbolic multivector is computed as follows:
\begin{colorverbatim}
	>> syms a [1 4] 
	>> A=MV(a,[2 0 0])
	A = 
	(a1)*e0+(a2)*e1+(a3)*e2+(a4)*e12
	>> exp(A)
	ans = 
	(exp(a1+(a2^2+a3^2-a4^2)^(1/2))/2+exp(a1-(a2^2+a3^2-a4^2)^(1/2))/2)*e0...
	+((a2*exp(a1+(a2^2+a3^2-a4^2)^(1/2))- ...
	a2*exp(a1-(a2^2+a3^2-a4^2)^(1/2)))/(2*(a2^2+a3^2-a4^2)^(1/2)))*e1...
	+((a3*exp(a1+(a2^2+a3^2-a4^2)^(1/2))- ...
	a3*exp(a1-(a2^2+a3^2-a4^2)^(1/2)))/(2*(a2^2+a3^2-a4^2)^(1/2)))*e2...
	+((a4*exp(a1+(a2^2+a3^2-a4^2)^(1/2))- ...
	a4*exp(a1-(a2^2+a3^2-a4^2)^(1/2)))/(2*(a2^2+a3^2-a4^2)^(1/2)))*e12
\end{colorverbatim}
\begin{rem}
	To date, there are no closed-form formulas for the exponential of general multivectors in geometric algebras with either $p+q+r\leq5$ or $p+q+r>5$. In particular, closed-form formulas have been developed for certain algebras with $p+q+r\leq5$ or for particular blades in algebras with $p+q+r\leq5$ \cite{exponentials}. As in the case of multivector inverses, the symbolic power of $\mathtt{SUGAR}$ can be used to compute closed-form formulas for the exponential of general multivectors in geometric algebras of any signature.
\end{rem}

\subsubsection{Matrices of multivectors}
By exploiting the Matlab-based array-inspired computations, $\mathtt{SUGAR}$ allows the creation of matrices where the components are multivectors of the same GA as well as performing operations with them, as demonstrated in the following example:

\begin{colorverbatim}
	>> GA([1,1,0])
	>> M=[e1 e1+e2; e2 e2-e1]
	M = 
	(1)*e1    (1)*e1+(1)*e2    
	(1)*e2    (-1)*e1+(1)*e2  
	>> M*M^-1
	ans = 
	(1)*e0    0     
	0     (1)*e0 
\end{colorverbatim}
\noindent Multivectors matrix operations can be done numerically or symbolically in the same way as with non-multivector matrices.

\subsection{Multivector methods}
This section presents Table~\ref{t:fun} which lists the main functions/methods/operations available for multivectors (and often for matrices of multivectors). They are not described in detail, but an intuitive description is provided. The following example illustrates the use of some of the functions listed in Table~\ref{t:fun}:

