\noindent This causes two issues in using $\widehat{K}$ (or data-driven approximations thereof) to model the flow of $f$: 
\begin{enumerate}
    \item The first is that it is unclear how to recover the state values underlying the propagated observables.
        Specifically, if $\widehat{K}\Psi(x) \notin \mathbb{M}$, 
        then by definition there is no value $x \in \mathbb{X} \subset \mathbb{R}^d$ satisfying $\Psi (x) = \widehat{K} \Psi(x)$.
    \item The second issue is that the learning process --~based on the regression problem~\eqref{eq:fitting}~-- only uses measurements of the form $z = \Psi(x)$, i.e., only points contained in the set~$\mathbb{M}$ are taken into account.
Hence, one cannot expect $\widehat{K} z$ to be meaningful if $z \notin \mathbb{M}$, which may render a repeated application of~$\widehat{K}$ questionable. 

\end{enumerate}
Both of these issues can be mitigated by \emph{projecting} the dynamics $z^+ = \widehat{K}z$, $z = \Psi(x)$, \emph{back} to the set~$\mathbb{M}$ after each application of the Koopman operator, see, e.g., \cite{MaurGonc16} and the follow-up work~\cite{MaurGonc19}.
In this paper, we propose a framework for optimal choices of such reprojection maps including an extension to parameter-dependent systems.
In particular, we discuss the following two choices: the widely used \emph{coordinate projection} and our newly proposed \emph{geometric projection}.
Such a projection step is particularly crucial for future applications in Koopman-based (predictive) control using \mbox{EDMDc}~\cite{KordMezi18b} or a bilinear surrogate model~\cite{WillHema2016,BoldGrun23}, where the construction of Koopman-invariant subspaces is a highly-nontrivial issue, see, e.g., \cite{GoswPale21}.

In the conference paper \cite{vanGMaho23}, we formulated first steps towards reprojections for parameter-independent systems. Therein, we considered closest-point projections in weighted norms of the following type.
\begin{definition}\label{def:repr}
    For a positive-definite matrix $W \in \R^{M\times M}$, the \emph{weighted reprojection} $\pi_W : \R^{M} \to \mathbb{M}$ satisfies 
    \begin{align}\label{eq:reprojection_function}
        \pi_W(z) \in \operatorname{arg}\min_{q \in \mathbb{M}} \vert q - z \vert_W^2
    \end{align}
    with the weighted norm $|z|_W^2 := z^\top W z$. %
    That is, for a point $z \in \R^{M}$, $\pi_W(z)$ provides the closest points in $\mathbb{M}$ with respect to the norm induced by $W$. %
\end{definition}
Hence, after pursuing one or several steps along the data-driven model, we may reproject to the manifold $\mathbb{M}$ by means of such a reprojection. In this work, we provide a thorough analysis of this idea addressing the following points:
\begin{enumerate}
    \item Tailored application to parameter- or control-affine systems extending the results of~\cite{vanGMaho23} for autonomous systems.
    \item Sophisticated data-driven choice of the weight matrix~$W$ by means of covariance matrices, allowing for a maximum likelihood interpretation of the projection~$\pi_W$.
    \item Efficient evaluation of~\eqref{eq:reprojection_function} using Riemannian Newton methods leveraging the structure of the manifold~$\mathbb{M}$.
\end{enumerate}
This reprojection is optimal for recovering the state of the system in the sense that, if we take the model %
$\hat K \Psi(x)$ to be correct, then the most likely admissible state of the system is given by the reprojection $\pi_W(\hat K \Psi(x))$ upon a suitable choice of the weighting matrix $W$.
\begin{proposition}\label{prop:maxlikely}
    Let $x \in \mathbb{X}$ and $z = \Psi(x) + \mu \subset \R^M$, where $\mu \sim N(0, \Sigma)$ for a positive definite covariance $\Sigma$.
    Then the maximum likelihood estimate $\hat{z} \in \mathbb{M}$ of $\Psi(x)$ given a measurement~$z$ satisfies
    \begin{align*}
        \hat{z} \in \pi_{\Sigma^{-1}}(z),
    \end{align*}
    i.e., it is a weighted reprojection~\eqref{eq:reprojection_function} with weighting matrix $W = \Sigma$.
\end{proposition}
\begin{proof}
    Up to a constant offset, the negative log-likelihood of $\hat{z} = \Psi(x)$ given $z$ is
    \begin{align*}
        l(\hat{z} = \Psi(x) \;|\; z) = \frac{1}{2} \vert z - \hat{z} \vert^2_{\Sigma^{-1}}.
    \end{align*}
    An optimal solution for $\hat{z}$ therefore satisfies $\hat{z} = \pi_{\Sigma^{-1}}(z)$.
\end{proof}
A widely-used and extremely simple form is the coordinate projection that was introduced, to the best of our knowledge, in~\cite{MaurGonc16}.
\begin{remark}\label{rem:coord}
Assume that the first $d$ entries of the dictionary are the coordinate functions, i.e., $\Psi_{i}(x) = x_i$ for $i\in [1:d]$. Then the weight function %
    \begin{align*}
        W_c = \begin{pmatrix}
        I_d & 0\\
        0&0
        \end{pmatrix}\in \R^{M\times M}
    \end{align*}
    induces a coordinate reprojection, that is,
    \begin{align*}
        \Psi(z_{[1:d]}) =\pi_{W_c}(z) \in \operatorname{arg}\min_{q \in \mathbb{M}} \vert q - z \vert_{W_c}^2 ,
    \end{align*}
    where $z_{[1:d]} \in \R^d$ corresponds to the first $d$ entries of $z\in \R^M$. For more details, i.e., a proof that $W_c$ indeed induces a Riemannian metric on $\mathbb{M}$, we refer the reader to \cite[Proposition 5.2]{vanGMaho23}.
\end{remark}





\section{Reprojections for Parameter-Affine Systems}
\label{sec:parameter-affine}

\noindent We consider parameter-affine systems of the form
\begin{align}\label{eq:system_dfn}
    \dot{x} = f(x) + \sum_{i=1}^m p_i g_i(x),
\end{align}
where $f, g_1,...,g_m : \mathbb{X} \to \R^d$ are locally Lipschitz continuous vector fields and $p \in \mathbb{R}^m$, $m\in \mathbb{N}$, represents a constant parameter. An extension to parameter-varying problems (e.g.~control systems) is straightforward such that in this work, we stick to the constant setting for ease of notation. In the following, for $p\in \R^m$ and $t\geq 0$, we denote by $\mathcal{K}_{f + \sum_{i=1}^m p_i g_i}^t$ the Koopman operator induced by $\eqref{eq:system_dfn}$, that is, for $x\in \mathbb{X}$ and $\varphi:\mathbb{X}\to \R$,
\begin{align*}
    (\mathcal{K}_{f + \sum_{i=1}^m p_i g_i}^t\varphi)(x) = \varphi(\Flow_{f + \sum_{i=1}^m p_i g_i}^t(x)),
\end{align*}
again tacitly assuming that $\mathbb{X}$ is invariant under $ \Flow^t_{f + \sum_{i=1}^m p_i g_i}$ for simplicity. Since one typically restricts parameter ranges to relatively small intervals, see, e.g., the examples below in Subsections~\ref{subsec:duffing} and \ref{subsec:lorenz}, this is a reasonably mild assumption for dynamical systems.

\subsection{The Koopman operator for parameter-affine systems}
\label{subsec:parameter-affine}

While the parameter-affine structure is directly inherited by the Koopman generator~\cite{PeitOtto20,Sura16,WillHema2016}, see also \cite{guo2025modularized} where this was leveraged for efficient learning on graphs, the Koopman operator is only approximately parameter-affine, as may be seen with a Taylor-series argument: For an observable $\varphi \in C^2(\mathbb{X}, \R)$ and any $x \in \mathbb{X}$, one has
\begin{align*}
    (\mathcal{K}_{f + \sum_{i=1}^m p_i g_i}^t \varphi) (x) & = \varphi (\Flow_{f + \sum_{i=m}^l p_i g_i}^t (x)) \\
    & = \varphi(x) + t \underbrace{\tD \varphi (x)(f + \sum_{i=1}^m p_i g_i)(x)}_{= \tD \varphi (x)f(x) + \sum_{i=1}^m p_i \tD \varphi (x) g_i(x)} +\ \mathcal{O}(t^2) \\
    & = \Big[ \varphi(x) + t \tD \varphi (x)f(x) \Big] + \sum_{i=1}^m p_i \Big[ t \tD \varphi (x) g_i(x) \pm \varphi(x) \Big] + \mathcal{O}(t^2) \\
    &= \varphi(\Flow_f^t(x)) + \sum_{i=1}^m p_i  \Big[ \varphi(\Flow_{g_i}^t (x)) -\varphi(x) \Big] + \mathcal{O}(t^2)\\
    &= \mathcal{K}^t_f\varphi(\hat x) + \sum_{i=1}^m p_i \left( \mathcal{K}^t_{g_i} \varphi - \varphi\right)(x) + \mathcal{O}(t^2)
\end{align*}
Motivated by the above calculation and denoting by $\otimes$ the usual Kronecker product we obtain the (infinite-dimensional) approximation for $\Psi$ as defined in \eqref{eq:Psi} 
\begin{align}\label{eq:firstapprox}
    (\mathcal{K}_{f + \sum_{i=1}^m p_i g_i}^t \Psi)(x)
    &= \widebar{\mathcal{K}}^t (\bar{p} \otimes\Psi)(x) + \mathcal{O}(t^2),
\end{align}
with the augmented parameter vector $\bar{p}:=\left(\begin{smallmatrix}1\\p\end{smallmatrix}\right)\in \R^{m+1}$  %
and the column block operator
\begin{align}\label{eq:bilinear1}
    \widebar{\mathcal{K}}^t := \begin{pmatrix}
        \mathcal{K}_f^t &
        \mathcal{K}_{g_1}^t - \mathcal{I} & \cdots &
        \mathcal{K}_{g_m}^t - \mathcal{I}
    \end{pmatrix},
\end{align}
where $\mathcal{K}^t_h$,  $h\in \{f,g_1,\ldots,g_m\}$ is the Koopman operator corresponding to the flow $\Flow^t_h$ defined by~\eqref{eq:Koopman}.

This bilinear representation motivates the following (finite-dimensional) approximation
\begin{align}\label{eq:parameter_koopman}
    \widehat{K} &:=
    \operatorname{argmin}_{K \in \mathbb{R}^{M \times M(m+1)} \hspace*{0.4cm}}\hspace*{-0.2cm} \int_{\mathbb{L} \otimes \mathbb{X}} \|\Psi(\Flow_{f + \sum_{i=1}^m p_i g_i}^t(x)) - {K}(\bar{p} \otimes \Psi(x))\|^2_2 \,\mathrm{d}(p \otimes x),
\end{align}
where $\mathbb{L}\subset \R^m$ is a compact set (with potentially only finitely-many elements) containing all possible parameters~$p$.
%
Solving the problem~\eqref{eq:parameter_koopman} yields an $M \times M(m+1)$ matrix that can be partitioned into 
\begin{align}\label{eq:blockcols}
    \widehat{K} = \begin{pmatrix}
        \widehat{K}_0 &
        \widehat{K}_1 & \cdots &
        \widehat{K}_{m}
    \end{pmatrix}
\end{align}
with $\widehat{K}_i \in \R^{M \times M}$ for $i \in [0:m]$, from which the individual approximations of the block-columns of $\widebar{\mathcal{K}}^t$ in~\eqref{eq:bilinear1} can be defined. This leads to the approximation of the parametric Koopman operator
\begin{align}\label{eq:parameter_kooopman_model}
    \left( \mathcal{K}^t_{f+\sum_{i=1}^m p_i g_i} \Psi \right)(x) = \Psi(\Flow^t_{f + \sum_{i=1}^m p_i g_i}(x))
    \approx \widehat{K}_0 \Psi(x) + \sum_{i=1}^m p_i \widehat{K}_i \Psi(x).
\end{align}
We stress that the structure of the right-hand side of \eqref{eq:bilinear1} mainly serves as a motivation to formulate the regression problem \eqref{eq:parameter_koopman} that may be leveraged in an error analysis. %

As in the parameter-independent case \eqref{eq:Koopman_manifold}, the parametric Koopman operator on the left-hand side of \eqref{eq:parameter_kooopman_model} preserves the set $\mathbb{M} = \Psi(\mathbb{X})$.
However, as in the parameter-independent case, this does, in general, not hold for the approximation on the right-hand side of~\eqref{eq:parameter_kooopman_model}. %
Thus, the state of the approximating system must be reprojected to~$\mathbb{M}$ to recover a state of the original system in $\mathbb{X}$. Before presenting a suitable reprojection in Section~\ref{subsec:reprojections}, we briefly comment on data-driven surrogates of \eqref{eq:parameter_koopman} via EDMD and provide a relation to existing parameter-affine approximations of the Koopman operator.
\begin{remark}\hfill
	\begin{itemize}
		\item[(i)] 
			In the spirit of EDMD and analogously to Remark~\ref{rem:finite_data} we may perform a Monte-Carlo-like approximation of \eqref{eq:parameter_koopman} by replacing the integral by a sum over data points, e.g., chosen i.i.d.\ with respect to the Lebesgue measure on $\mathbb{L}\otimes \mathbb{X}$. 
		\item[(ii)] 	Following \cite[Section 5]{PhilScha23}, again using a Taylor-series argument, we have 
		%
		%
		%
		%
		%
		%
		\begin{align*}
		\left( \mathcal{K}^t_{g_i} \varphi - \varphi \right)(x) %
		& = t\nabla \varphi \cdot (f + g_i - f)(x) %
		+ \mathcal{O}(t^2)\\
		& = \left(\mathcal{K}^t_{f+g_i} \varphi - \varphi\right)(x) - \left(\mathcal{K}^t_f \varphi - \varphi\right)(x) + \mathcal{O}(t^2)\\
		& = \left( \mathcal{K}^t_{f+g_i} \varphi \right)(x) - \left( \mathcal{K}^t_f\varphi \right)(x) + \mathcal{O}(t^2),
		\end{align*}
		which shows the equation
		\begin{align*}
		\mathcal{K}^t_f\varphi (\hat x) + \sum_{i=1}^m p_i \left( \mathcal{K}^t_{g_i} \varphi - \varphi\right) (\hat x) = \mathcal{K}^t_f\varphi(\hat x) + \sum_{i=1}^m p_i \left( \mathcal{K}^t_{f + g_i} \varphi - \mathcal{K}^t_f\varphi\right) (\hat x) + \mathcal{O}(t^2).
		\end{align*}
		The presented line of reasoning allows us to replace the definition ~\eqref{eq:bilinear1} by %
		\begin{align}\label{eq:bilinear2}
		\bar{\mathcal{K}}^t := \begin{pmatrix}
		\mathcal{K}_f^t & \mathcal{K}_{g_1+f}^t - \mathcal{K}_f^t & \cdots & \mathcal{K}_{g_m+f}^t - \mathcal{K}_f^t
		\end{pmatrix},
		\end{align}
		which nicely links the presented parameter-affine approximation of the Koopman operator to existing ones~\cite{PeitOtto20,NuskPeit23}. 
	\end{itemize}
\end{remark}



\subsection{Maximum likelihood reprojections via covariance estimators}\label{subsec:reprojections}

\noindent Consider the parameter-affine system \eqref{eq:system_dfn} and let $\mathbb{V}$ be a $M$-dimensional dictionary.
Let $\Psi \in L^2(\mathbb{X}, \R)^M$ denote the vector of observables spanning~$\mathbb{V}$ and $\widehat{K}$ be the approximation of the Koopman operator defined in~\eqref{eq:parameter_koopman}.
Then, as discussed in Section~\ref{sec:problem_formulation}, it is generally not guaranteed that the set {$\mathbb{M} = \Psi(\mathbb{X})$} is preserved under the Koopman operator, {compare~\eqref{eq:Koopman_manifold}}. %
To measure the approximation error, %
the \emph{residual operator} for a vector field $f$ is defined on $\mathbb{V}$ by
\begin{align*}
    (\mathcal{R}_{f}^t \Psi)(x) := (\mathcal{K}_{f}^t \Psi)(x) - {\widehat{K}} \Psi(x),
\end{align*}
where by $\widehat{K}_f$ we denote the solution of \eqref{eq:fitting}.

%
Then, by virtue of the definition of $\widehat{K}$ through the regression problem \eqref{eq:fitting}, the first and second moments of $\mathcal{R}^t_f \Psi$ satisfy
\begin{align*}
    \mathbb{E}(\mathcal{R}^t_f \Psi) & = \int_{\mathbb{X}} \mathcal{R}^t_f \Psi(x) \mathrm{d} x = \int_{\mathbb{X}} \Psi(\Flow_f^t(x)) - \widehat{K} \Psi(x)\, \mathrm{d} x = 0, \\
    \mathrm{Cov}(\mathcal{R}^t_f \Psi)
    &= \mathbb{E} \left((\mathcal{R}^t_f \Psi(x) - \mathbb{E}(\mathcal{R}^t_f \Psi))(\mathcal{R}^t_f \Psi(x) - \mathbb{E}(\mathcal{R}^t_f \Psi))^\top\right) \\
    &= \int_{\mathbb{X}} \mathcal{R}^t_f \Psi(x)(\mathcal{R}^t_f \Psi(x))^\top \mathrm{d} x \\
    &= \int_{\mathbb{X}} (\Psi(\Flow_f^t(x)) - \widehat{K} \Psi(x))(\Psi(\Flow_f^t(x)) - \widehat{K} \Psi(x))^\top \mathrm{d} x.
\end{align*}
Here, we propose a model for the approximated Koopman dynamics as a linear system corrupted by a zero-mean Gaussian noise process, that is, %
\begin{align*}
    \Psi(\Flow_f^t(x)) &= \widehat{K}_f^t \Psi(x) + \mathcal{R}_f^t \Psi(x)
    \approx \widehat{K} \Psi(x) + \mu, &
    \mu &\sim N(0, \mathrm{Cov}(\mathcal{R}^t_f \Psi)).
\end{align*}
While this is also an approximation, it captures the effects of the finite-dictionary Koopman fitting up to second-order.
%
Moreover, it provides a stochastic approximation of the Koopman dynamics %
including a model of the error introduced by projection.
In Proposition \ref{prop:cov}, we demonstrate how the covariance used to model the error can be computed from the same data used to construct $\widehat{K}$ in the first place.

For parameter-dependent systems, we define the residual operator analogously, that is,
\begin{align}\label{eq:residual_operator}
    \mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi (x) :=
        (\mathcal{K}^t_{f + \sum_{i=1}^m p_i g_i} \Psi)(x) -  \left(\widehat{K}_0 + \sum_{i=1}^m p_i \widehat{K}_i\right) \Psi(x),
\end{align}
for all initial states $x \in \mathbb{X}$ and parameters $p \in \mathbb{L}$. Here, we recall that $\widehat{K}_i\in \mathbb{R}^{M\times M}$, $i\in [0:m]$, are defined as the block columns of $\widehat{K}$, see \eqref{eq:blockcols}, solving the augmented regression problem~\eqref{eq:parameter_koopman}. 
For parameter-dependent systems~\eqref{eq:system_dfn}, the covariance may depend on the parameter $p$ %
in a non-trivial fashion. However, in the following, we will show that it can be approximated as a quadratic function of the parameters for short integration times. To this end, define the matrix-valued bilinear form $Q : \R^{m+1} \times \R^{m+1} \to \R^{M \times M}$ as the symmetric solution to the regression problem
\begin{align}\label{eq:solQ}
    \min_Q \int_{\mathbb{L}} \left\| 
        \operatorname{Cov}(\mathcal{R}^t_{f + \sum_{i=1}^l u_i g_i} \Psi) - Q(\bar{p}, \bar{p})
    \right\|_F^2 \mathrm{d}p,
\end{align}
where $\bar{p} = \left(\begin{smallmatrix}1\\p\end{smallmatrix}\right)\in \R^{m+1}$ again denotes the augmented %
parameter vector.
The solution $Q$ may be determined analytically, that is, denoting by $\operatorname{vec}$ the column-wise vectorization of a matrix, $Q$ solves~\eqref{eq:solQ} if
\begin{align}\label{eq:covariance_map_Q}
    \operatorname{vec} (Q(\bar{p}, \bar{p})) &= Y X^\dag (\bar{p} \otimes \bar{p}), \\
    \mathrm{where\ }Y &:= \int_{\mathbb{L}} \int_{\mathbb{X}} (\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi(x) \bar{p}^\top ) \otimes (\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi(x) \bar{p}^\top ) 
    \; \mathrm{d}x \; \mathrm{d}p, \notag\\
    X &:= \int_{\mathbb{L}} \bar{p} \bar{p}^\top \otimes \bar{p} \bar{p}^\top \mathrm{d}p. \notag
\end{align}
%
Hereby we note that $X$ may be computed analytically, where $Y$ depends on the Koopman operator and thus has to be approximated by means of data in applications, see Remark~\ref{rem:edmdcov}.

The following result shows that the bilinear form $Q$ yields a second-order approximation of the true covariance.

\begin{proposition}\label{prop:cov}
    For any $p \in \mathbb{L}$, the covariance of the residual operator \eqref{eq:residual_operator} satisfies
    \begin{align}\label{eq:koopman_system_noise}
        \operatorname{Cov}\left(
            \mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi
        \right)
        &= Q(\bar{p},\bar{p}) + \mathcal{O}(t^2),
    \end{align}
    where $Q$ is defined as in \eqref{eq:covariance_map_Q}.
\end{proposition}

\begin{proof}
For the expected value, we have that %
%
\begin{align*}
    \mathbb{E}(\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi)
    &= \mathbb{E}(\mathcal{R}^t_{f}\Psi + \sum_{i=1}^m p_i \mathcal{R}^t_{g_i} \Psi) + \mathcal{O}(t^2) \\
    &= \mathbb{E}(\mathcal{R}^t_{f}\Psi) + \sum_{i=1}^m p_i \mathbb{E}(\mathcal{R}^t_{g_i} \Psi)  + \mathcal{O}(t^2) \\
    &= \mathcal{O}(t^2)
\end{align*}
as $\mathbb{E}(\mathcal{R}^t_{f}\Psi) = \mathbb{E}(\mathcal{R}^t_{g_1}) = \ldots = \mathbb{E}(\mathcal{R}^t_{g_m}) = \mathcal{O}(t^2)$. 
%
%
For convenience of notation, %
let $g_0 := f$, so that
\begin{align*}
    f + \sum_{i=1}^m p_i g_i = \sum_{i=0}^m \bar{p}_i g_i.
\end{align*}
Then, using the parameter-affine structure, the covariance satisfies %
\begin{align}
    &\mathrm{Cov}(\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi)\nonumber
    \\&= \mathrm{Cov}(\mathcal{R}^t_{\sum_{i=0}^m \bar{p}_i g_i} \Psi) \nonumber\\
    &= \mathrm{Cov}\left(\sum_{i=0}^m \bar{p}_i \mathcal{R}^t_{g_i} \Psi\right) + \mathcal{O}(t^2)\nonumber \\
    &= \mathbb{E} \left( \left(\sum_{i=0}^m \bar{p}_i \mathcal{R}^t_{g_i} \Psi - \underbrace{\mathbb{E}\left(\sum_{i=0}^m \bar{p}_i \mathcal{R}^t_{g_i} \Psi\right)}_{=\mathcal{O}(t^2)}\right) \left(\sum_{i=0}^m \bar{p}_i \mathcal{R}^t_{g_i} \Psi - \underbrace{\mathbb{E}\left(\sum_{i=0}^m \bar{p}_i \mathcal{R}^t_{g_i} \Psi\right)}_{=\mathcal{O}(t^2)}\right)^\top\right) + \mathcal{O}(t^2)\nonumber\\
    &= \sum_{i,j=0}^m \bar{p}_i \bar{p}_j \mathbb{E} \left( (\mathcal{R}^t_{g_i} \Psi)( \mathcal{R}^t_{g_j} \Psi)^\top \right)  + \mathcal{O}(t^2).\label{eq:almostdone}
\end{align}
We now show that $Q$ defined by \eqref{eq:covariance_map_Q} provides an approximation of the first term in \eqref{eq:almostdone} up to second order in $t$. %
To see this, we compute
\begin{align*}
    Y &= \int_{\mathbb{L}} \int_{\mathbb{X}}
        (\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi(x) \bar{p}^\top )
        \otimes (\mathcal{R}^t_{f + \sum_{i=1}^m p_i g_i} \Psi(x) \bar{p}^\top ) 
    \; \mathrm{d}x \; \mathrm{d}p \\
    &= \int_{\mathbb{L}} \int_{\mathbb{X}}
        (\mathcal{R}^t_{\sum_{i=0}^m \bar{p}_i g_i} \Psi(x) \bar{p}^\top )
        \otimes (\mathcal{R}^t_{\sum_{i=0}^m \bar{p}_i g_i} \Psi(x) \bar{p}^\top )
    \; \mathrm{d}x \; \mathrm{d}p \\
    &= \int_{\mathbb{L}} \int_{\mathbb{X}}
        \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \bar{p} \bar{p}^\top\right)
        \otimes \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \bar{p} \bar{p}^\top\right)
    \; \mathrm{d}x \; \mathrm{d}p
     + \mathcal{O}(t^2) \\
    &= \int_{\mathbb{L}} \int_{\mathbb{X}}
        \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) 
        \otimes \left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \right)
        (\bar{p} \bar{p}^\top \otimes
        \bar{p} \bar{p}^\top)
    \; \mathrm{d}x \; \mathrm{d}p
    + \mathcal{O}(t^2) \\
    &= \int_{\mathbb{X}}
        \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) 
        \otimes \left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \right)
    \; \mathrm{d}x 
    \int_{\mathbb{L}} 
    (\bar{p} \bar{p}^\top \otimes \bar{p} \bar{p}^\top)
    \; \mathrm{d}p
    + \mathcal{O}(t^2).
\end{align*}
Substituting this into the definition of $Q$, i.e., \eqref{eq:covariance_map_Q}, we get %
\begin{align*}
    \operatorname{vec} (Q(\bar{p}, \bar{p})) &= Y X^\dag (\bar{p} \otimes \bar{p}) \\
    &= \int_{\mathbb{X}}
        \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) 
        \otimes \left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \right)
    \; \mathrm{d}x (\bar{p} \otimes \bar{p}) + \mathcal{O}(t^2) \\
    &= \int_{\mathbb{X}}
        \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \bar{p} \right)
        \otimes \left(\left(\begin{smallmatrix}
            \mathcal{R}^t_{g_0}\Psi(x) & \cdots & \mathcal{R}^t_{g_m}\Psi(x)
        \end{smallmatrix}\right) \bar{p}\right)
    \; \mathrm{d}x + \mathcal{O}(t^2) \\
    &=  \int_{\mathbb{X}}{\scriptstyle
        \left( \mathcal{R}^t_{g_0}\Psi(x) p_0 + \cdots + \mathcal{R}^t_{g_m}\Psi(x) p_m \right)}
        \otimes {\scriptstyle \left( \mathcal{R}^t_{g_0}\Psi(x) p_0 + \cdots + \mathcal{R}^t_{g_m}\Psi(x) p_m \right)}
    \; \mathrm{d}x + \mathcal{O}(t^2)
    %
\end{align*}
such that
\begin{align*}
        Q(\bar{p}, \bar{p})
    &= \int_{\mathbb{X}} 
        {\scriptstyle \left( \mathcal{R}^t_{g_0}\Psi(x) p_0 + \cdots + \mathcal{R}^t_{g_m}\Psi(x) p_m \right) \left( \mathcal{R}^t_{g_0}\Psi(x) p_0 + \cdots + \mathcal{R}^t_{g_m}\Psi(x) p_m \right)^\top}
    \; \mathrm{d}x + \mathcal{O}(t^2) \\
    &= \sum_{i,j=0}^m \bar{p}_i \bar{p}_j \mathbb{E} \left( (\mathcal{R}^t_{g_i} \Psi)( \mathcal{R}^t_{g_j} \Psi)^\top \right)  + \mathcal{O}(t^2).
\end{align*}
This completes the proof.
\end{proof}

%
%



Combining Proposition~\ref{prop:maxlikely} and Proposition~\ref{prop:cov}, we directly obtain the following result for the parameter-dependent prediction model.
\begin{corollary}
    Let $x \in \mathbb{X}$ and $z = \Psi(x) \in \mathbb{M} \subset \R^M$. Let
    \begin{align*}
        z^+ := \left(\widehat{K}_0 + \sum_{i=1}^m p_i \widehat{K}_i\right) z
        = \Psi(\Flow_{f + \sum_{i=1}^m p_i g_i}^t(x))
        + \mu, &&
        \mu \sim N\left(0, \sum_{i,j=0}^m Q_{ij} p_i p_j\right).
    \end{align*}
    Then, a maximum likelihood estimate $\hat{z}^+ \in \mathbb{M}$ of $\Psi(\Flow_{f + \sum_{i=1}^l p_i g_i}^t(x))$ is given by
    \begin{align*}
        \hat{z}^+ \in \pi_{\Sigma^{-1}}(z^+) \qquad\text{with}\qquad
        \Sigma := \sum_{i,j=0}^m Q_{ij} p_i p_j.
    \end{align*}
\end{corollary}
We conclude this section commenting on data-driven approximations of the covariance surrogate $Q$.
\begin{remark}[Data-driven approximation by EDMD]\label{rem:edmdcov}
    To compute the matrix representation of $Q$ serving as an approximation of the covariance matrix~\eqref{eq:koopman_system_noise} similar to EDMD applied to the Koopman operator, we perform a Monte-Carlo approximation of the integrals appearing in \eqref{eq:covariance_map_Q} by a sum over finitely many data points. 
\end{remark}


\subsection{Numerical results}\label{subsec:numres}
%
%
%

%
In this part, we present various numerical examples to illustrate the proposed parametric Koopman scheme and the corresponding reprojections. We discuss a scalar example in the subsequent Subsection~\ref{subsec:pitchfork}, a two-dimensional Duffing oscillator in Subsection~\ref{subsec:duffing} and the three-dimensional Lorenz dynamics in Subsection~\ref{subsec:lorenz}. In all these examples, we discretize the ODE by means of a fourth-order Runge-Kutta method of fourth order with adaptive step-size control. For the evaluation, we distinguish three different cases of EDMD-based predictions:
\begin{itemize}
    \item[(i)] Standard prediction without reprojection. %
    \item[(ii)] Prediction with coordinate reprojection as described in Remark~\ref{rem:coord}; applicable if the lifting map is injective.
    \item[(iii)] Maximum likelihood-based closest-point reprojection as proposed and outlined in Subsection~\ref{subsec:reprojections}.
\end{itemize}
In all numerical examples, if not stated otherwise, we approximate the Koopman operator  using a polynomial dictionary up to order five with a sampling time step of $t = 0.1$. %
%



\subsubsection{Supercritical pitchfork bifurcation}\label{subsec:pitchfork}

First, we consider the scalar system 
\begin{align*}
\frac{\mathrm{d}}{\mathrm{d}t} x(t) = px(t) - x(t)^3
\end{align*}
with parameter $p\in \mathbb{R}$.
This system corresponds to a supercritical pitchfork bifurcation, as with the parameter becoming positive, two stable equilibria arise. More precisely, we have the following two cases:
\begin{itemize}
	\item[(i)] $p\leq 0$: The only equilibrium is the origin which is asymptotically stable.
	\item[(ii)] $p > 0$: The equilibria are given by $\{0,-\sqrt{p},\sqrt{p}\}$, where the origin is unstable, and $\sqrt{p}$ resp.\ $-\sqrt{p}$ are asymptotically stable for positive resp.\ negative initial values.
\end{itemize}
As a parameter and state domain, we choose $\mathbb{L}=\mathbb{X} = [-2,2]$. %

In Figure~\ref{fig:pitchfork}, we depict the scalar state (left) and the error over time (right). For $p=-1$, as depicted in the top row, we observe that the globally asymptotically stable nature of the origin renders all three Koopman-based predictions robust, that is, the error is relatively stable over the horizon. 
%
When transitioning to $p=1$, however, we clearly see that a standard prediction fails after a short time period. In particular, while the formed equilibrium at $x=\sqrt{p}=1$ is correctly identified using reprojections, this is not the case for the standard prediction.
