\subsection{Efficient Reprojection via Riemannian Newton Method}\label{subsec:newton}

In general, it is not straightforward to implement the proposed reprojection function~\eqref{eq:reprojection_function}. 
To use %
{derivative-based} methods for solving the corresponding \emph{manifold-constrained nonlinear optimization problem}, we suppose %
that the image of~$\Psi$ defined in \eqref{eq:M} has the structure of an embedded manifold.
%

\begin{definition}[Embedded Submanifold~{\cite[Chapter 4,5]{Lee12}}]
    An \emph{embedding} of a manifold $\mathbb{M}$ into $\R^M$ is a smooth immersion $F : \mathbb{M} \to \R^M$ that is also a topological embedding.
    That is, $F$ is smooth, the derivative $\tD F(x)$ has full rank for all $x \in M$, and $F$ is a homeomorphism onto its image $F(M) \subseteq \R^M$.
    A manifold $\mathbb{M}$ is called an \emph{embedded submanifold (of $\R^M$)} if it is a subset $\mathbb{M} \subseteq \R^M$ and the inclusion map is an embedding.
\end{definition}

\begin{assumption}
    The map $\Psi : \mathbb{X} \to \R^M$ is an embedding; equivalently, $
\mathbb{M}= \Psi(\mathbb{X}) \subset \R^M$ is an embedded submanifold.
\end{assumption}

To apply optimization methods on the manifold $
\mathbb{M}$, both a Riemannian metric on $\mathbb{M}$ and a retraction from the tangent bundle $\mathrm{T} 
\mathbb{M}$ are required.
We recall the definitions as they are needed.

\begin{definition}[Riemannian Metric~{\cite[Chapter 13]{Lee12}}]
    For a manifold $\mathbb{M}$, a \emph{Riemannian metric on $\mathbb{M}$} is a 2-
    tensor field $g$ that is positive definite at each point.
    That is, for each $p \in \mathbb{M}$, the metric defines a positive definite bilinear map $g_p : \tT_p \mathbb{M} \times \tT_p \mathbb{M} \to \R$.
\end{definition}

The Riemannian metric may be simply inherited from the ambient Euclidean space; that is, for any $p\in \mathbb{M}$ and $\eta_1, \eta_2 \in \tT_p \mathbb{M}$, the Riemannian metric at $p$ is defined by
\begin{align}\label{eq:riemannian_metric}
    g_p(\eta_1, \eta_2)  := \langle \eta_1, \eta_2 \rangle,
\end{align}
where the right-hand side is the ordinary inner product in $\R^M$ applied by the inclusion of $\tT_p \mathbb{M}$ as a subspace of $\R^M$.

\begin{definition}[Retraction~{\cite[Definition 4.1.1]{AbsiMaho09}}]
    A \emph{retraction} on a manifold $\mathbb{M}$ is a smooth map $R: \tT \mathbb{M} \to \mathbb{M}$ satisfying the following two properties, where $R_p : \tT_p \mathbb{M} \to \mathbb{M}$ is the restriction of $R$ to $\tT_p \mathbb{M}$:
    \begin{enumerate}
        \item $R_p(0_p) = p$, where $0_p \in \tT_p \mathbb{M}$ is the zero vector in the tangent space at $p$.
        \item Through the canonical identification $\tT_{0_p} \tT_p \mathbb{M} \simeq \tT_p \mathbb{M}$, the differential of $R_p$ satisfies
        \begin{align*}
            \tD R_p(0_p) = \mathrm{id}_{\tT_p \mathbb{M}},
        \end{align*}
        where $\mathrm{id}_{\tT_p \mathbb{M}} : \tT_p \mathbb{M} \to \tT_p \mathbb{M}$ denotes the identity map.
    \end{enumerate}
\end{definition}

The definition of $\mathbb{M}$ as the image of an embedding $\Psi$ lends itself to defining a retraction.
\begin{lemma}\label{lem:retraction}
    Consider the manifold $\mathbb{M} = \Psi(\mathbb{X}) \subset \R^M$.
    Define the map $R : \tT \mathbb{M} \to \mathbb{M}$ by
    \begin{align*}
        R_p(\eta) = \Psi(\Psi^{-1}(p) + \tD \Psi(\Psi^{-1}(p))^{-1} \eta),
    \end{align*}
    for all $p \in \mathbb{M}$ and $\eta \in \tT_p \mathbb{M}$.
    Then $R$ is a retraction.
\end{lemma}

\begin{proof}
    Smoothness of $R$ is immediate as it is a composition of smooth maps.
    Let $p \in \mathbb{M}$ be arbitrary and denote the zero element of the tangent space as $0_p \in \tT_p \mathbb{M}$.
    Then the retraction of the zero element satisfies
    \begin{align*}
        R_p(0_p) = \Psi(\Psi^{-1}(p) + \tD \Psi(\Psi^{-1}(p))^{-1} 0_p)
        = \Psi(\Psi^{-1}(p) + 0) = p.
    \end{align*}
    Finally, for any $\eta \in \tT_{0_p} \tT_p \mathbb{M} \simeq \tT_p \mathbb{M}$,
    \begin{align*}
        \tD R_p(0_p)[\eta]
        &= \at{\ddt}{t=0} R_p(0_p + t \eta) \\
        &= \at{\ddt}{t=0} \Psi(\Psi^{-1}(p) + \tD \Psi(\Psi^{-1}(p))^{-1} (0_p + t \eta)) \\
        &= \at{\ddt}{t=0} \Psi(\Psi^{-1}(p) + t \tD \Psi(\Psi^{-1}(p))^{-1} \eta) \\
        &= \tD \Psi(\Psi^{-1}(p))\tD \Psi(\Psi^{-1}(p))^{-1} \eta \\
        &= \eta.
    \end{align*}
    Thus $\tD R_p(0_p)$ is exactly the identity map on $\tT_p \mathbb{M}$ for all $p$.
    This shows that $R$ is indeed a retraction.
\end{proof}

%
Let $R : \tT \mathbb{M} \to \mathbb{M}$ be the retraction defined in Lemma \ref{lem:retraction}.
Then we may apply a Riemannian Newton method \cite[Algorithm 5]{AbsiMaho09} to find a local solution to the reprojection map $\pi_W$.
Specifically, given a point $z \in \R^M$, define
\begin{align*}
    l_z : \mathbb{M} \to \R, && l(p) := \frac{1}{2} \vert p - z \vert_W^2.
\end{align*}
Then the Newton equation is
\begin{align}\label{eq:newton_equation}
    \Hess l_z(p) \eta = - \grad l_z(p).
\end{align}
The gradient and Hessian of $l_z$ are easily computed to be
\begin{align*}
    \grad l_z(p) &= W(p-z) &
    \Hess l_z(p) &= W,
\end{align*}
using the embedded representation of $\tT_p \mathbb{M}$.
The Newton equation \eqref{eq:newton_equation} thus appears trivial to solve by $\eta = (p-z)$.
However, this neglects the fact that the Hessian and gradient of $l_z$ are restricted to the tangent space of $\mathbb{M}$ at $p$.
This issue can be addressed by finding a minimal basis of the tangent space at $p$.

Let $x = \Psi^{-1}(p)$.
Then the tangent space $\tT_p \mathbb{M}$ is exactly the image of the differential $\tD \Psi(x) : \R^d \to \R^M$, and this map is injective.
Therefore any $\eta \in \tT_p \mathbb{M}$ may be written as $\tD \Psi(x) v$ for a unique $v \in \R^d$, and the standard basis vectors $e_1,\ldots,e_d$ of $\R^d$ induce a basis $\tD \Psi(x) e_1, \ldots \tD \Psi(x) e_d \in \R^M$ for $\tT_p \mathbb{M}$.
In this basis, the gradient and Hessian may be written as
\begin{align*}
    \grad l_z(p) &= \tD \Psi(x)^\top W(p-z) &
    \Hess l_z(p) &= \tD \Psi(x)^\top W \tD \Psi(x).
\end{align*}
Let $v \in \R^d$ denote the unique vector in $\R^d$ such that $\eta = \tD \Psi(x) v$. 
Then the Newton equation \eqref{eq:newton_equation} simplifies to
\begin{align}\label{eq:simplified_newton_equation}
    \tD \Psi(x)^\top W \tD \Psi(x) v &= - \tD \Psi(x)^\top W(p-z), \\
    v &= - (\tD \Psi(x)^\top W \tD \Psi(x))^\dag \tD \Psi(x)^\top W(p-z).
\end{align}
The retraction of $\eta$ can also then be simplified to
\begin{align*}
    R_p(\eta)
    &= \Psi(\Psi^{-1}(p) + \tD \Psi(\Psi^{-1}(p))^{-1} \eta), \\
    &= \Psi(\Psi^{-1}(p) + \tD \Psi(\Psi^{-1}(p))^{-1} \tD\Psi(x) v), \\
    &= \Psi(\Psi^{-1}(p) + v).
\end{align*}
Finally, this leads to Algorithm \ref{alg:newton_method} for obtaining $\pi_W(z)$.

\begin{algorithm}
    \caption{Riemannian Newton method for reprojection \eqref{eq:reprojection_function}}
    \label{alg:newton_method}
    \begin{algorithmic}[1]
        \Require $W \in \R^{M\times M}$ positive semidefinite; $z \in \R^M$ the target point.
        \Goal Find $p \in \mathbb{M}$ to minimize $\vert p - z \vert^2_W$.
        \Input An initial guess $p_0 \in \mathbb{M}$.
        \Output An estimate $\hat{p}$ of $\pi_W(z)$.
        \State Set $x_0 = \Psi^{-1}(p_0) \in \mathbb{X}$.
        \For{$k=0,1,2,...,k_{\max}$}
            \State Solve the simplified Newton equation \eqref{eq:simplified_newton_equation},
            \begin{align*}
                v_k &= - (\tD \Psi(x_k)^\top W \tD \Psi(x_k))^\dag \tD \Psi(x_k)^\top W(p-z).
            \end{align*}
            \State Set
            \begin{align*}
                x_{k+1} &= x_k + v_k, \\
                \hat{p} &= \Psi(x_{k+1}).
            \end{align*}
            \If{$\vert v_k \vert \leq \text{threshold}$}
                \State \textbf{break}
            \EndIf
        \EndFor
    \end{algorithmic}
\end{algorithm}

Algorithm \ref{alg:newton_method} features guaranteed local convergence.
Specifically, if $x_* = \Psi^{-1}(p_*)$ is a critical point of $\vert p - z \vert^2_W$, then there is a neighbourhood $\mathcal{U}_{x_*}$ of $x_*$ such that, if $x_0 \in \mathcal{U}_{x_*}$ then the sequence $x_k$ generated by the algorithm converges at least quadratically to $x_*$ \cite[Theorem 6.3.2]{AbsiMaho09}.

The proposed algorithm requires an initial guess $x_0$, which can be obtained through two simple approaches in practice.
The first is to use a naive projection method such as coordinate projection.
That is, if the coordinate functions are included in the dictionary $\mathbb{V}$, so that $\Psi(x) = (x, \bar{\Psi}(x))$, where $\bar{\Psi} : \mathbb{X} \to \R^{M-d}$, then the initial guess can be chosen as the first $d$ coordinates of $p$, $x_0 := p_{1:d}$.
Another possibility, which does not rely on a particular structure of the dictionary, is to use the previous value of $x^*(t_k)$ to initialise the guess for the new value $x_0(t_{k+1}) = x^*(t_k)$.
%

%
In Figure~\ref{fig:newton}, we illustrate the superlinear convergence of the Riemannian Newton method for the projection. We observe that the tolerance of $10^{-8}$ is met already after a few time steps when using the solution of the previous time step as an initial guess.
\begin{figure}[htb]
    \centering
\includegraphics[width=0.49\linewidth]{figures/newton/newton_duffing.png}
    \includegraphics[width=0.49\linewidth]{figures/newton/newton_lorenz.png}
    \caption{Error of Newton iteration for every 20th prediction step with time step $t=0.1$ for the Duffing oscillator (left) and the Lorenz example (right).}
    \label{fig:newton}
\end{figure}
We conclude this section by means of a remark considering globalization.
\begin{remark}
    The Newton method proposed in Algorithm \ref{alg:newton_method} can be extended to a trust region method such as \cite[Algorithm 10]{AbsiMaho09} to provide global convergence under some mild assumptions.
\end{remark}

\section{Conclusion}
\noindent In this paper, we proposed a reprojection method for Koopman-based predictions of nonlinear parameter-affine systems. Considering closest-point projections parametrized by weighting matrices mapping onto the consistent manifold of the compression, we have analyzed two particular choices corresponding to coordinate and maximum-likelihood projections and provided details for efficient implementation using an adaptive multistep scheme or a Riemannian Newton method. In various numerical examples, we have showcased the performance and increased robustness of Koopman-based predictions using these reprojections. 


