\section{SPARQL queries used to extract the papers of a given proceedings and their corresponding authors from the DBLP KG.}\label{app:query_ex}
\lstset{
    language=Python,
    basicstyle=\small,
    numbers=left,
    numberstyle=\tiny,
    numbersep=5pt,
    frame=single,
    breaklines=true,
    breakatwhitespace=true,
    tabsize=4,
    showstringspaces=false
}
% \begin{lstlisting}

\begin{figure}[h]
%\footnotesize
\begin{lstlisting}[frame=single,breaklines]{sparql}

# get the list of papers in a given proceeding 
#identifier <__proceedings_uri__>

PREFIX dblp: <https://dblp.org/rdf/schema#> 

SELECT ?paper ?title ?doi ?pages ?year WHERE {
    ?paper a dblp:Publication, dblp:Inproceedings;
        dblp:title ?title;
        dblp:doi ?doi;
        dblp:pagination ?pages;
        dblp:yearOfPublication ?year;
        dblp:publishedAsPartOf <__proceedings_uri__> .
    FILTER (STRSTARTS(str(?doi), "https://doi.org/"))
}

# get the list of authors associated in papers of a given
# proceeding identifier <__proceedings_uri__>

PREFIX dblp: <https://dblp.org/rdf/schema#> 

SELECT ?paper ?title ?name ?ordinal ?orcid ?wikidata ?scholar {
    ?paper a dblp:Publication, dblp:Inproceedings;
        dblp:title ?title;
        dblp:hasSignature ?sign;
        dblp:publishedAsPartOf <__proceedings_uri__> .

    ?sign dblp:signatureDblpName ?name;
        dblp:signatureCreator ?dblp_person;
        dblp:signatureOrdinal ?ordinal .

    OPTIONAL { ?dblp_person dblp:orcid ?orcid }
    OPTIONAL { ?dblp_person dblp:wikidata ?wikidata }
    OPTIONAL { ?dblp_person dblp:webpage ?scholar . 
    FILTER (STRSTARTS(str(?scholar),''https://scholar.google.com/")) }
}
\end{lstlisting}
\label{lst:ex3}
\end{figure}

