\title{Reed-Muller Codes for Quantum Pauli and\\ Multiple Access Channels} 

\author{%
  \IEEEauthorblockN{Dina Abdelhadi\IEEEauthorrefmark{2}\IEEEauthorrefmark{3}, Colin Sandon\IEEEauthorrefmark{1}\IEEEauthorrefmark{3},  Emmanuel Abbe\IEEEauthorrefmark{1}\IEEEauthorrefmark{2}, Ruediger Urbanke\IEEEauthorrefmark{2} }

