\section{Problem Setup}
Consider $N$ discrete linear time-invariant (LTI) processes with $N$ sensors (Fig.~\ref{fig:framework}). The $i$-th system is observed by the $i$-th sensor, i.e.,
\begin{equation*}
x^{(i)}_{k+1} 	= A_ix^{(i)}_k + w^{(i)}_k,\quad y^{(i)}_k		=C_ix^{(i)}_k + v^{(i)}_k,
\end{equation*}
where $k$ is the discrete time index, $x_k^{(i)}\in\mathbb{R}^{n_i}$ is the system state,  $y^{(i)}_k\in\mathbb{R}^{m_i}$ is the sensor measurement vector, $w_k^{(i)}$ and $v_k^{(i)}$ are mutually uncorrected Gaussian white noise with covariances $W_i\succeq 0$ and $V_i\succ0$, respectively. The initial state $x_0^{(i)}$ is assumed to be zero-mean Gaussian with covariance $P_0^{(i)}\succeq 0$, and uncorrelated with $w_k^{(i)}$ and $v_k^{(i)}$ for all $k$. We assume $(A_i,C_i)$ is detectable and $(A_i,\sqrt{W_i})$ is stabilizable. Additionally, we assume $||A_i||\geq 1$ (This is discussed later in Remark~\ref{rmk:stable}). The same assumption has been adopted in prior studies~\cite{peng2017optimal,zhang2020false}.
%
\begin{figure}[!tbp]
	\centering
	\includegraphics[width=0.9\linewidth]{framework.pdf}
	\caption{System diagram.}
	\label{fig:framework}
\end{figure}
%
\subsection{Sensor Local State Estimation}
As shown in Fig.~\ref{fig:framework}, each sensor is assumed to be ``smart'' and capable of running a Kalman filter locally to estimate the system state based on its accumulated measurements, i.e.,
\begin{align*}
\tilde{x}_k^{(i)} 			&\triangleq \mathbb{E}\left[x_k^{(i)}|y_0^{(i)},\dots,y_k^{(i)}\right],\\
\tilde{P}_k^{(i)} 			&\triangleq \mathbb{E}\left[(x_k^{(i)}-\tilde{x}_k^{(i)})(x_k^{(i)}-\tilde{x}_k^{(i)})^T|y_0^{(i)},\dots,y_k^{(i)}\right],
\end{align*}
where $\tilde{x}_k^{(i)}$ and $\tilde{P}_k^{(i)}$ are the local estimate and the corresponding estimation error covariance, respectively.


For notational simplicity, define the following functions:
\begin{align*}
\tilde{g}_i(X)	&\triangleq X-XC_i^T[C_iXC_i^T+V_i]^{-1}C_iX,\\
h_i(X)		&\triangleq A_iXA_i^T+W_i,\qquad g_i(X)		\triangleq \tilde{g}_i\circ h_i(X).
\end{align*}

It is well-established that $\tilde{P}_k^{(i)}$ converges exponentially to a steady-state $\bar{P}_{i}$, which can be uniquely computed by solving the equation $g_i(X)=X$~\cite{anderson2012optimal}. As we herein focus on the asymptotic performance over an infinite time horizon, we assume without loss of generality that the Kalman filter at the sensors have reached the steady state at $k=0$, i.e., $\tilde{P}_k^{(i)}=\bar{P}_{i}$.

\subsection{Remote State Estimation}
After obtaining the local estimate, the sensors transmit their data to a remote state estimator via wireless communication channels. Due to the unreliability of wireless communications, the packet transmission suffers from dropouts. Let $\gamma_k^{(i)}\in\{0,1\}$ denote the binary variable indicating whether the remote estimator receives the sensor's local estimate at time $k$, i.e., $\gamma_k^{(i)}=1$ if the estimator receives $\tilde{x}_k^{(i)}$, and $\gamma_k^{(i)}=0$ otherwise.

Define $\tau_k^{(i)}$ as the duration between $k$ and the most recent reception of the sensor's estimate, i.e.,
\begin{equation*}
\tau_k^{(i)}\triangleq\min\{t\geq 0:\gamma^{(i)}_{k-t}=1\}.
\end{equation*}
Since we are interested in the asymptotic behavior of the system, we assume $\gamma_0^{(i)}=1$ without loss of generality.

Depending on $\gamma_k^{(i)}$ and $\tau_k^{(i)}$, the minimum mean square error (MMSE) estimate and the relative error covariance at the remote estimator obey the stochastic recursions~\cite{shi2010kalman}: $\hat{x}^{(i)}_k=\tilde{x}^{(i)}_k$ and $P^{(i)}_k=\bar{P}_{i}$ if $\gamma^{(i)}_k=1$; $\hat{x}^{(i)}_k=A_i\hat{x}_{k-1}^{(i)}$ and $P^{(i)}_k=h_i(P^{(i)}_{k-1})=h_i^{\tau_k^{(i)}}(\bar{P}_{i})$ otherwise.
%%
\subsection{Self-Sustainable Attack}
Equipped with energy harvesters, the attacker can launch jamming attacks, thus reducing the estimation accuracy of the remote estimator by utilizing the harvested energy. 

Let $b_k$ represent the battery level of the attacker at time $k$, and let $b_{\max}$ denote the maximum battery capacity. At each time $k$, the attacker determines the amount of jamming attack power $p_k^{(i)}\geq 0$ to inject into the $i$-th sensor-estimator communication link. The power $p_k^{(i)}$ is determined to maximize the estimation error covariance at the remote estimator, which will be introduced later.

\begin{figure}[!tbp]
	\centering
	\includegraphics[width=\linewidth]{battery.pdf}
	\caption{Battery dynamics of the attacker.}
	\label{fig:battery}
\end{figure}

Since the jamming power is limited by the available energy in the battery and the attacker's transmission capacity, we have the following constraints on $p_k^{(i)}$:
\begin{equation}\label{eq:p_con}
p_k^{(i)}\leq p_{\max},\qquad \sum_{i=1}^N p_k^{(i)}\leq b_k,
\end{equation}
where $p_{\max}$ represents the maximum power the attacker can allocate to each channel.

On the other hand, let $E_k$ denote the amount of energy harvested by the attacker during the interval between time $k$ and $k+1$. The battery dynamics (Fig.~\ref{fig:battery}) are given by~\cite{ho2012optimal,leong2018optimal}
\begin{equation}\label{eq:bat_model}
b_{k+1} = \min\{b_k-\sum_{i=1}^N p_k^{(i)}+\lfloor E_{k}\rfloor,b_{\max}\},
\end{equation}
where $\lfloor\cdot\rfloor$ is the floor function that returns the greatest integer less than or equal to the given input.



Generally speaking, $E_k$ is time-varying and may exhibit temporal correlation. For instance, the amount of solar energy can vary significantly depending on the time of day or weather conditions. In this paper, we assume that $E_k$ is represented by a finite-state Markov model, where the set of possible states is denoted by $\mathcal{E}=\{e_1,\dots,e_\ell\}$. The transition probability can be expressed by~\cite{ho2012optimal}
\begin{equation}\label{eq:e_trans}
\mathbb{P}(E_{k+1}=e_q|E_{k}=e_{p})=t^e_{e_p,e_q}.
\end{equation}

\subsection{Wireless Communication}
Let $\lambda_k^{(i)}\triangleq\mathbb{P}(\gamma_k^{(i)}=1)$ represent the packet arrival rate for the wireless transmission. It is influenced by two factors: i) the attackers' jamming power $p_k^{(i)}$; ii) the channel gains of both the sensor-estimator and attacker-estimator links.

Denote $H^{(i)}_k$ and $G_k^{(i)}$ as the channel gains of the sensor-estimator and attacker-estimator links at time $k$, respectively.  Assume the gains are Markovian with states $\mathcal{S}=\{s_1,\dots,s_l\}$. The transition probabilities are given by
%
\begin{equation}\label{eq:transition}
\begin{aligned}
\mathbb{P}	&(H^{(i)}_{k+1}=s_q|H^{(i)}_{k}=s_{p})\\
			&\qquad\qquad=\mathbb{P}(G^{(i)}_{k+1}=s_q|G^{(i)}_{k}=s_{p})=t^s_{s_p,s_q}.
\end{aligned}
\end{equation}

\begin{rmk}{\rm
The finite-state Markov model can be regarded as an extension of the well-known Gilbert-Elliott model with higher model accuracy~\cite{wang1995finite}.
}\end{rmk}
%
\begin{rmk}{\rm
While the transition probability is not necessary to be identical across different systems and communication links as shown in~\eqref{eq:transition}, for better presentation of the main results, we assume it is identical without loss of generality.
}\end{rmk}
%
%%
Consider a unit time slot and assume normalized power transmission of the sensors. Under the jamming attack, the SINR for the $i$-th sensor at time $k$ is given by
\begin{equation}\label{eq:sinr}
{\rm SINR}_k^{(i)}\triangleq\frac{H_k^{(i)}}{G_k^{(i)}p_k^{(i)}+\sigma_i^2},~  p_k^{(i)}\leq p_{\max}, ~ \sum_{i=1}^N p_k^{(i)}\leq b_k,
\end{equation}
where $\sigma_i^2$ represents the power of additive white Gaussian noise in the $i$-th channel.

%%

Using error-detection mechanisms such as cyclic redundancy checks, the packet arrival rate is determined by the associated SINR~\cite{alma991002544119703412}, i.e.,
\begin{equation*}
\lambda_k^{(i)}=f({\rm SINR}_k^{(i)}),
\end{equation*}
where $f(\cdot):\mathbb{R}\mapsto[0,1]$ is a non-decreasing function specified by the modulation mode used by the sensors and the estimator.
%%
\begin{example}\label{exam:qam}{\rm
Considering a quadrature amplitude modulation (QAM) scheme, we have $f({\rm SINR}_k^{(i)})=1-Q(\sqrt{b {\rm SINR}_k^{(i)}})$, where $b>0$ is a channel parameter and $Q(x)\triangleq\frac{1}{\sqrt{2\pi}}\int_{x}^{\infty}\exp(-\delta^2/2)d\delta$.
}\end{example}
%
\subsection{Problem of Interest}
Assume the attacker knows its battery level $b_k$, the harvested energy $E_k$ and its transition probability~\eqref{eq:e_trans}. Additionally, the attacker knows the system dynamics, i.e., $A_i$, $C_i$, $Q_i$, and $R_i$, and can obtain $\tau^{(i)}_{k-1}$ by eavesdropping on the feedback channels from the estimator to the sensors.\footnote{The same assumption has been adopted in prior studies on related topics~\cite{peng2017optimal,ren2018attack}.} Regarding the channel information, two scenarios are considered:
\begin{enumerate}
\item \underline{\it Perfect channel information}: the attacker has access to the values of $H^{(i)}_k$, and $G^{(i)}_k$ via channel estimation and knows the transition probability~\eqref{eq:transition} perfectly.
\item \underline{\it Unknow channel model}: the attacker knows the values of $H^{(i)}_k$, and $G^{(i)}_k$ but not the transition probability.\footnote{This assumption is also commonly found in numerous works within the literature~\cite{lyu2020irs,zhang2017wireless}.}
\end{enumerate}

%
\begin{rmk}{\rm
The above assumptions imply a strong attacker. This follows Kerckhoffs's principle, which states that the security of a system should not rely on its secrecy~\cite{van2014encyclopedia}. Studying the ``worst-case" attack helps us better understand the security level of the system. Alternatively, one could also assume that the attacker does not have the full information. In such cases, the provided MDP formulation (Section~\ref{chap:results}) should be extended to the partially observable Markov decision process (POMDP) model~\cite{krishnamurthy2016partially}. 
}\end{rmk}
%
The attacker aims to smartly utilize the harvested energy to disturb the estimation process of the remote estimator. More specifically, the objective function is
\begin{equation}\label{eq:cost}
J(p)=\liminf_{T\to\infty}\frac{1}{T+1}\sum_{k=0}^{T}\sum_{i=1}^{N}\tr\left\{\mathbb{E}\left[P_k^{(i)}\right]\right\},
\end{equation}
where $p=\{p_0^{(1)},\dots,p_0^{(N)},\dots,p_k^{(1)},\dots,p_k^{(N)},\dots\}$ is the jamming power subject to the energy constraint~\eqref{eq:p_con}.

The problem addressed in this paper can be summarized as an optimization problem as follows:
\begin{align}
\max_{p} 	&\quad J(p)\label{eq:problem}\\
{\rm s.t.}		&\quad 0\leq p_k^{(i)}\leq p_{\max},~ i = 1,\dots,N,~\forall k\in\mathbb{N},\notag\\
			&\quad \sum_i p_k^{(i)}\leq b_k,~\forall k\in\mathbb{N},\notag\\
			&\quad b_{k+1} = \min\{b_k-\sum_{i} p_k^{(i)}+\lfloor E_{k}\rfloor,b_{\max}\}, ~\forall k\in\mathbb{N}.\notag
\end{align}
%%%%
\section{MDP Formulation and Structural Results}\label{chap:results}
In this section, we solve the problem enunciated in the preceding section with an MDP model and prove the existence of an optimal stationary policy under mild assumptions. Additionally, we establish some structural properties of the optimal policy, which enables efficient computation in both scenarios of perfect and unknown channel information.
%
\subsection{MDP Design}
Since in practice, the transmitter is typically programmed to operate with a finite number of transmission power levels only~\cite{fu2012practical}, we herein assume the attacker chooses $p_k^{(i)}$ discretely, i.e., $p_k^{(i)}\in\mathcal{P}=\{0,1,\dots, \lfloor p_{\max}\rfloor\}$.

The MDP formulation requires the following definitions.


%%
\noindent 1) \emph{State:} The attacker's state encapsulates its information for decision-making. Since the power allocation strategy depends on the channel state $H_k^{(i)}$, $G_k^{(i)}$, the estimation error covariance of the remote estimator $P_k^{(i)}$, the battery level $b_k$ and the harvested energy $E_k$, the state at the beginning of time $k$, i.e., $\phi_k$, is defined as follows:
%
\begin{equation*}
\begin{aligned}
\phi_k=(b_k, E_k, \Lambda_k^{(1)},\dots,\Lambda_k^{(N)}),\quad \Lambda_k^{(i)}=(H_k^{(i)},G_k^{(i)},\tau_{k-1}^{(i)}).
\end{aligned}
\end{equation*}
%
We note that the state space $\mathbb{S}$ is countably infinite:
\begin{equation*}
\mathbb{S}=\mathcal{B}\times\mathcal{E}\times\prod_{i=1}^N\left\{H^{(i)},G^{(i)},\tau^{(i)})\right\},
\end{equation*}
where $\mathcal{B}=\{0,1,\dots,b_{\max}\}$, $H^{(i)},G^{(i)}\in\mathcal{S}$ and $\tau^{(i)} \in\mathbb{N}$.

\noindent 2) \emph{Action:} The action $a_k$ of the attacker is its jamming power at time $k$, i.e.,
%
\begin{equation*}
a_k				=(a_k^{(1)},\dots,a_k^{(N)}),\quad a_k^{(i)}=p_k^{(i)}\in\mathcal{P}.
\end{equation*}
%
The available action for state $\phi_k$ is
\begin{equation*}
\begin{aligned}
\mathbb{A}_{\phi_k}=\{(a^{(1)}_k,\dots,a^{(N)}_k)|	&\sum_{i}a^{(i)}_k\leq b_k, \\
							&\qquad a^{(i)}\in\mathcal{P}, ~i=1,\dots,N\}.
\end{aligned}
\end{equation*}
Then the action space $\mathbb{A}$ is
\begin{equation*}
\begin{aligned}
\mathbb{A}=\cup_{k=1}^\infty\mathbb{A}_{\phi_k}&=
\{(a^{(1)},\dots,a^{(N)})|	\sum_{i}a^{(i)}\leq b_{\max}, \\
							&\quad\qquad a^{(i)}\in\mathcal{P}, ~i=1,\dots,N\}.
\end{aligned}
\end{equation*}

\begin{rmk}{\rm
Since the state $\phi_k$ is defined at the beginning of time $k$, $\tau_{k}^{(i)}$ is unavailable to the attacker for decision-making.
}\end{rmk}
%
\noindent 3) \emph{Transition Probability:} Define $\mathbb{T}:\mathbb{S}\times\mathbb{A}\times\mathbb{S}\mapsto[0,1]$ as the transition function. Using the model~\eqref{eq:bat_model}-\eqref{eq:transition}, it can be computed as follows:
%
\begin{equation*}
\begin{aligned}
&\mathbb{P}(\phi_{k+1}|\phi_k,a_k)\\
&\quad=\mathbb{P}(b_{k+1},E_{k+1}|b_k,E_k,a_k)\prod_{i=1}^N\mathbb{P}(\Lambda^{(i)}_{k+1}|\Lambda^{(i)}_k,a^{(i)}_k),	
\end{aligned}
\end{equation*}
where
\begin{equation*}
\mathbb{P}(b_{k+1},E_{k+1}|b_k,E_k,a_k)=
\begin{cases}
t^e_{E_k,E_{k+1}}, 	& \text{if~\eqref{eq:bat_model} holds};\\
0, 				&\text{otherwise},
\end{cases}
\end{equation*}
%
and
\begin{equation*}
\begin{aligned}
\mathbb{P}(\Lambda^{(i)}_{k+1}|\Lambda^{(i)}_k,a^{(i)}_k)&=t^s_{H^{(i)}_k,H^{(i)}_{k+1}}t^s_{G^{(i)}_k,G^{(i)}_{k+1}}\\
&\quad\times
\begin{cases}
	\lambda_k^{(i)},  		&{\rm if~}\tau^{(i)}_{k}=0;\\
	1-\lambda_k^{(i)},		&{\rm if~}\tau^{(i)}_{k}=\tau^{(i)}_{k-1}+1;\\
	0, 		&{\rm otherwise}.
\end{cases}
\end{aligned}
\end{equation*}
%%%

\noindent 4) \emph{One-Stage Reward Function:} Considering the reward function defined in~\eqref{eq:cost}, the one-stage reward function for state $\phi_k$ and action $a_k$ becomes
%
\begin{equation}\label{eq:reward}
\begin{aligned}
&r(\phi_k,a_k)	=\sum_{i=1}^N \tr\left\{\mathbb{E}\left[P_k^{(i)}|\phi_k,a_k\right]\right\}\\
			=&\sum_{i=1}^N\left\{\lambda_k^{(i)}\tr[\bar{P}_{i}]+(1-\lambda_k^{(i)})\tr[h_i^{\tau^{(i)}_{k-1}+1}(\bar{P}_{i})]\right\}.
\end{aligned}
\end{equation}
The objective function in~\eqref{eq:cost} is then given by the average expected sum of one-stage rewards, i.e.,
%
\begin{equation*}
J(p)=\liminf_{T\to\infty}\frac{1}{T+1}\sum_{k=0}^{T}r(\phi_k,a_k).
\end{equation*}

Since neither the transition probability nor the reward function depend on $k$, the problem is time invariant. To simplify notation, we shall ignore the variable $k$ for simplicity.

Denote $J^*$ as the optimal value of the objective, i.e., $J^*=\sup_{p}J(p)$. Then $J^*$ satisfies the following average-cost Bellman equation:
%
\begin{equation}\label{eq:bellman}
J^*+V(\phi)=\max_{a\in\mathbb{A}_\phi}\{r(\phi,a)+\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)V(\phi')\},
\end{equation}
where $V(\cdot):\mathbb{S}\mapsto\mathbb{R}$ is the relative value function.
%%

However, the Bellman equation may fail to have a solution~\cite{bertsekas2011dynamic}, for instance, when  $J^*$ is infinite. Let $\theta(\cdot)$ be a deterministic policy that maps states to actions, i.e., $\mathbb{S}\mapsto\mathbb{A}$, and let $\Theta$ denote the set of all feasible policies. In the following, we will establish the existence of an optimal deterministic stationary policy that indeed solves the Bellman equation.
%
\begin{assumption}\label{assumption:stable}{\rm
Assume for the $i$-th sensor, $i=1,\dots,N$, there exisits $\kappa_i\in[0,1)$ such that
\begin{equation*}
\inf_{\Xi_{k-1}^{(i)}}\sum_{\Xi_k^{(i)}}\left[f({\rm SINR}^{(i)}_{k,\min})t_{H_{k-1}^{(i)},H_{k}^{(i)}}t_{G_{k-1}^{(i)},G_{k}^{(i)}}\right]\geq1-\frac{\kappa_i}{||A_i||^2},
\end{equation*}
where the quantities are defined in~\eqref{eq:transition}-\eqref{eq:sinr} and as follows:
\begin{equation*}
\Xi_k^{(i)}=(H_k^{(i)},G_k^{(i)}),\quad {\rm SINR}^{(i)}_{k,\min}={H^{(i)}_k}/[b_{\max} G_k^{(i)}+\sigma_i^2].
\end{equation*}
}\end{assumption}
%
\begin{lemma}\label{lemma:bound}{\rm
If Assumption~\ref{assumption:stable} holds, then $\mathbb{E}[P_k^{(i)}]$ is exponentially bounded for any attack allocations, i.e.,
\begin{equation*}
\mathbb{E}[\tr(P_k^{(i)})]\leq c_i\kappa_i^k+d_i, ~i=1,\dots,N, ~k\in\mathbb{N},
\end{equation*}
for some finite constants $c_i$ and $d_i$.
}\end{lemma}
%
\begin{proof}
The proof follows directly from~\cite[Theorem 1]{quevedo2012state}, thus omitted here.
\end{proof}
%
\begin{rmk}{\rm
Intuitively, Assumption~\ref{lemma:bound} guarantees that starting from any channel conditions $\Xi_{k-1}^{(i)}$, the expected packet arrival rate will not be unreasonably low even under the worst attack. This assumption ensures that $\mathbb{E}[P_k^{(i)}]$ remains bounded as $k\to\infty$, thereby avoiding trivial scenarios where the system is excessively susceptible to malicious attacks.
}\end{rmk}
%
\begin{thm}\label{thm:stationary}{\rm
Assume Assumption~\ref{assumption:stable} holds. There exists a deterministic stationary policy $\theta^*$, a constant $J^*$, and a function $V(\phi)$ which solve the Bellman equation~\eqref{eq:bellman}. The optimal policy $\alpha^*(\phi)=\theta^*(\phi)$ is determined by
\begin{equation*}
\alpha^*(\phi)=\arg\max_{\alpha\in\mathbb{A}_\phi}\{r(\phi,\alpha)+\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,\alpha)V(\phi')\}.
\end{equation*}
}\end{thm}
\begin{proof}
See Appendix~\ref{apx:stationary}.
\end{proof}
%
\begin{rmk}\label{rmk:stable}{\rm
Constructing a measurable function $\Psi(\cdot)$ that simultaneously satisfies the intricate conditions (I)(II), as indicated in Appendix~\ref{apx:stationary}, poses a fundamental challenge. When $||A_i||<1$, the condition $\Psi(\cdot)\geq1$ for the constructed measureable function no longer holds. As a result, we make the assumption that $||A_i||\geq1$ herein and defer the study of the case $||A_i||<1$ to our future work.
}\end{rmk}
%%

\subsection{Structural Results}\label{sec:structure}
In this part, we demonstrate that the optimal policy exhibits monotonic structures, which allows for a significant reduction in the computational complexity of the algorithms introduced in subsequent sections.

Following ideas in~\cite[Section 8.11]{puterman2014markov}, we denote the $Q$-factor of a state-action pair as
\begin{equation}\label{eq:q factor}
Q(\phi,a)\triangleq r(\phi,a)+\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)V(\phi')-J^*.
\end{equation}
Combining $V(\phi)=\max_{a\in\mathbb{A}}Q(\phi,a)$ with~\eqref{eq:bellman}, we obtain
\begin{equation}\label{eq:q update}
J^*+Q(\phi,a)=r(\phi,a)+\sum_{\phi'\in\mathbb{S}}\max_{a'\in\mathbb{A}_{\phi'}}Q(\phi',a')\mathbb{P}(\phi'|\phi,a).
\end{equation}

To introduce ordering, with a slight abuse of notation, we denote $\phi_+=(b,E,\Lambda_+^{(1)},\dots,\Lambda_+^{(N)})$ and $\phi_-=(b,E,\Lambda_-^{(1)},\dots,\Lambda_-^{(N)})$ where each component $\Lambda_+^{(i)}$ and $\Lambda_-^{(i)}$ is given by
\begin{align*}
\Lambda^{(i)}_+=(H^{(i)},G^{(i)},\tau^{(i)}_+),\qquad \Lambda^{(i)}_-=(H^{(i)},G^{(i)},\tau^{(i)}_-).
\end{align*}
Here $b$, $E$, $H^{(i)}$ and $G^{(i)}$ represent arbitrary but fixed elements. We say $\phi_-\preceq_{\tau}\phi_+$ if $\tau_-^{(i)}\leq\tau_+^{(i)}$ for all $i$. Note that $\preceq_{\tau}$ is a partial order defined on $\mathbb{S}$.

Now we are ready to present the monotonicity properties of $V(\phi)$ and $Q(\phi,a)$, respectively.

%
\begin{lemma}[Monotonicity]\label{lemma:monototic}{\rm
The function $V(\phi)$ is monotonically increasing in $\tau^{(i)}$ for all $i$. In other words, for all pairs $(\phi_-,\phi_+)$ such that $\phi_-\preceq_{\tau}\phi_+$, we have $V(\phi_-)\leq V(\phi_+)$.
}\end{lemma}
\begin{proof}
See Appendix~\ref{apx:monototic}.
\end{proof}

%
\begin{lemma}[Monotonicity]\label{lemma:monototic q}{\rm
The $Q$-factor $Q(\phi,a)$ is monotonically increasing in $\tau^{(i)}$ for all $i$. In other words, for all pairs $(\phi_-,\phi_+)$ such that $\phi_-\preceq_{\tau}\phi_+$ and $\forall a\in\mathbb{A}_{\phi_+}\cap\mathbb{A}_{\phi_-}$, we have 
\begin{equation}\label{eq:monototic q}
Q (\phi_-,a)\leq Q (\phi_+,a).
\end{equation}
}\end{lemma}
\begin{proof}
The proof follows directly from Lemma~\ref{lemma:monototic} and~\eqref{eq:q factor}, thus omitted here.
\end{proof}
%
Fixing the other components of the state $\phi$ except $\tau^{(i)}$, with a bit of abuse of notations, we denote the $Q$-factor in~\eqref{eq:q factor} as $Q(\tau^{(i)},a)$. Additionally, denote $a_{-,i}=(a_{-,i}^{(1)},\dots,a_{-,i}^{(N)})$ and $a_{+,i}=(a_{+,i}^{(1)},\dots,a_{+,i}^{(N)})$, where the inequality $a_{-,i}^{(i)}\leq a_{+,i}^{(i)}$ holds for the specific index $i$. Then we are prepared to present the superadditivity property of $Q(\tau,a)$.
%
\begin{lemma}[Superadditivity]\label{lemma:super}{\rm
The $Q$-factor $Q(\tau^{(i)}, a)$ is superadditive in $(\tau^{(i)}, a^{(i)})$. In other words, for all $\tau^{(i)}_-\leq  \tau^{(i)}_+$ and for all $ a_{-,i},a_{+,i}$ satisfying $a_{-,i}^{(i)}\leq a_{+,i}^{(i)}$, the following inequality holds:
\begin{equation}\label{eq:super}
 Q (\tau^{(i)}_+,a_{+,i})- Q (\tau^{(i)}_+,a_{-,i})\geq Q (\tau^{(i)}_-,a_{+,i})- Q (\tau^{(i)}_-,a_{-,i}).
\end{equation}
}\end{lemma}
\begin{proof}
See Appendix~\ref{apx:additive}.
\end{proof}
%
\begin{thm}\label{thm:structure}{\rm
The optimal allocated power for the $i$-th sensor, i.e., $\alpha^{(i)*}(\phi)$, is non-decreasing in $\tau^{(i)}$, where $i=1,\dots,N$. In other words, $\forall\phi_-\preceq_{\tau}\phi_+$, we have $\alpha^{(i)*}(\phi_-)\leq\alpha^{(i)*}(\phi_+)$.
}\end{thm}
%
\begin{proof}
See Appendix~\ref{apx:structure}.
\end{proof}
%
The structural results developed above can be leveraged to enhance the efficiency of our algorithms. In Section~\ref{sec:perfect} and Section~\ref{sec:unknown}, we will provide a detailed discussion on how to utilize these findings.


\section{Perfect Channel Information}\label{sec:perfect}
%
By virtue of Theorem~\ref{thm:stationary}, if the attacker has perfect channel information, we can solve~\eqref{eq:bellman} by the relative value iteration algorithm~\cite{bertsekas2011dynamic}. The iterative recursion is expressed as:
\begin{equation}\label{eq:iteration}
\begin{aligned}
D_t(\phi)	&=\max_{a\in\mathbb{A}_\phi}\{r(\phi,a)+\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)D_{t-1}(\phi')\}\\
		&-\max_{a\in\mathbb{A}_{\phi_f}}\{r(\phi_f,a)+\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi_f,a)D_{t-1}(\phi')\},
\end{aligned}
\end{equation}
where $t$ denotes the iteration number of the algorithm, $\phi_f\in\mathbb{S}$ is some fixed reference state that can be arbitrarily chosen.
%
\begin{rmk}{\rm
For average-cost problems, the commonly used value iteration algorithm may produce a value that diverges to infinity~\cite{bertsekas2011dynamic}. To address this issue, we instead adopt the relative value iteration algorithm introduced above.
}\end{rmk}
%
\begin{proposition}\label{prop}{\rm
As $t\to\infty$, $D_t(\phi_f)$ and $D_t(\phi)$ in~\eqref{eq:iteration} converge to the optimal solution $J^*$ and $V(\phi)$ of the infinite-time horizon Bellman equation~\eqref{eq:bellman}, respectively.
}\end{proposition}
%
\begin{proof}
By utilizing~\cite[Proposition 4.3.2]{bertsekas2011dynamic} and selecting a state $z=(b,E,\Lambda^{(1)},\dots,\Lambda^{(N)})$, where $\Lambda^{(i)}=(H^{(i)},G^{(i)},0)$, the proof is straightforward and is thus omitted here.
\end{proof}

Proposition~\ref{prop} indicates that using relative value iteration, we are able to find the optimal policy. However, this procedure can be computationally expensive when the state space is large. The monotonic property in Theorem~\ref{thm:structure} indicates that the optimal power allocations switch between certain thresholds. While the analytical form of these thresholds may not be available, gradient-estimate-based algorithms~\cite{nourian2014optimal} can be employed to search for them. This significantly enhances the computational efficiency of determining the optimal policy~\cite{puterman2014markov}.

Additionally, it is important to note that the countably infinite nature of the state space makes it impractical to solve the Bellman equation directly. To address this issue, the set of $\tau^{(i)}$ is typically truncated to a finite subset by imposing an upper limit, denoted as $L$, and treating any $\tau^{(i)}$ greater than $L$ as $L$. Given the monotonic nature of the optimal policy, the solution to the truncated problem coincides with the true optimal solution when $L$ is sufficiently large.

%
\section{Unknown Channel Model}\label{sec:unknown}
When the transition probabilities are unknown to the attacker, solving the Bellman equation via relative value iteration becomes inapplicable. However, as an alternative approach, we can employ a stochastic approximation algorithm that does not require prior knowledge of the transition probabilities. In the remainder of this section, we first outline the standard stochastic approximation with standard updates. Building on this foundation, we propose a novel structural update mechanism that accelerates convergence by leveraging the structural results developed in Section~\ref{sec:structure}.

\subsection{Standard Update}
At each time $k$ and state $\phi$, the action $a$ is selelcted according to an $\epsilon$-greedy strategy based on the $k$-th iteration of the $Q$-factor\footnote{Herein the time index $k$ and the algorithm iteration number $t$ can be regarded as identical.}, i.e.,
\begin{equation*}
a=
\begin{cases}
\arg\max_{a'\in\mathbb{A}_\phi}Q_k(\phi,a'),			&\text{with probability $1-\epsilon$};\\
\text{any action in $\mathbb{A}_\phi$},	&\text{with probability $\epsilon$}.
\end{cases}
\end{equation*}
With the new observation of the next state $\phi'$, $Q_k(\phi,a)$ is updated to
\begin{equation}\label{eq:q learning}
\begin{aligned}
Q_{k+1}(\phi,a)=Q_{k}(\phi,a)&+\xi_{k}[r(\phi,a)+\max_{a'\in\mathbb{A}_{\phi'}}Q_{k}(\phi',a')\\
&-Q_{k}(\phi,a)-Q_k(\phi_f,a_f)],
\end{aligned}
\end{equation}
where $(\phi_f,a_f)\in\mathbb{S}\times\mathbb{A}_{\phi_f}$ is an arbitrary but fixed state-action pair, and $\xi_k$ is the step size.

Under mild assumptions on the step size\footnote{Common choices include $1/k$, ${1}/[k\log (k)]$, and ${\log (k)}/{k}$ for $k\geq 2$.}, the scheme \eqref{eq:q learning} is guaranteed to converge~\cite{abounadi2001learning}. However, the convergence rate may be slow since only one state-action pair $(\phi,a)$ is updated per observation.
To address this limitation, we propose leveraging the structural results established in Lemmas~\ref{lemma:monototic q} and~\ref{lemma:super}. These properties enable simultaneous updates of multiple state-action pairs during each iteration while preserving convergence guarantees, thereby accelerating the process.
%
%
\subsection{Structural Update}
The key insight is that Lemmas~\ref{lemma:monototic q} and~\ref{lemma:super} establish relationships between the $Q$-factors. Such ``extra'' information enables the simultaneous update of multiple state-action pairs. The following example illustrates this idea intuitively.
%
\begin{example}{\rm
Suppose a new observation $(\phi_-,a)$ arrives at time $k$ and updating $Q(\phi_-,a)$ via~\eqref{eq:q learning} results in $Q(\phi_-,a)>Q(\phi_+,a)$, where $\phi_-\preceq_{\tau}\phi_+$. Then by Lemmas~\ref{lemma:monototic q}, this necessitates an increase in $Q (\phi_+,a)$ as well, which effectively allows for two updates from a single observation $(\phi_-,a)$.
}\end{example}

In the following, we formally introduce this approach in three steps, as illustrated in Fig.~\ref{fig:relation}. For clarity, we consider a simplified scenario with $N=2$, $l=1$, and $L=1$, and assume there are only two power levels, i.e., $\{0,1\}$. Note that the subsequent analysis can be easily extended to a general case. For notation simplicity, we denote the $Q$-factor as $Q(^{\tau^{(1)}}_{\tau^{(2)}}~^{a^{(1)}}_{a^{(2)}})$, and stack them as a vector, i.e.,
\begin{figure}[!tbp]
	\centering
	\includegraphics[width=0.95\linewidth]{relation.pdf}
	\caption{The relationship between the standard update and our proposed structural update.}
	\label{fig:relation}
\end{figure}
%
\begin{equation*}
\bm{Q}=\left[Q(^0_0~^0_0),Q(^0_0~^0_1),Q(^0_0~^1_0),Q(^0_0~^1_1), Q(^0_1~^0_0),\dots,Q(^1_1~^1_1)\right].
\end{equation*}
%
\subsubsection{Objective Transformation}
The update scheme~\eqref{eq:q learning} can be viewed as the gradient descent algorithm for an unconstrained optimization problem. To formalize this connection, we consider the following optimization problem:
\begin{equation}\label{eq:gradient}
\begin{aligned}
\min_{\bm Q} 	\quad -\mathcal{G}(\bm{Q}),
\end{aligned}
\end{equation}
where $\mathcal{G}(\bm{Q})$ is a differentiable function of $\bm Q$. The corresponding gradient descent update is $Q_{k+1}(\phi,a)=Q_{k}(\phi,a)+\zeta_k\nabla_{\bm{Q}}\mathcal{G}_{\phi,a}$, where $\nabla_{\bm{Q}}\mathcal{G}_{\phi,a}$ is the $(\phi,a)$-th component gradient. Remarkably, if the gradient fulfills
\begin{equation*}
\nabla_{\bm{Q}}\mathcal{G}_{\phi,a}=r(\phi,a)+\max_{a'\in\mathbb{A}_{\phi'}}{Q}(\phi',a')-{Q}(\phi,a)-{Q}(\phi_f,a_f),
\end{equation*}
then the scheme~\eqref{eq:q learning} is indeed the gradient descent method for solving problem~\eqref{eq:gradient}.
%
%
\subsubsection{Constraint Adding}
Lemma~\ref{lemma:monototic q} and~\ref{lemma:super} can expressed as constraints on $\bm Q$, i.e., $\bm{T}_m\bm{Q}\geq 0$ and $\bm{T}_s\bm{Q}\geq 0$, where
%
\begin{equation*}
\begin{aligned}
\bm{T}_m&=\begin{bmatrix}\bar{\bm{T}}^T_{m,1}&\bar{\bm{T}}^T_{m,2}&\bar{\bm{T}}^T_{m,3}&\bar{\bm{T}}^T_{m,4}\end{bmatrix}^T,\\
\bar{\bm{T}}_{m,1}&=\begin{bmatrix}\bar{\bm T}_m&\bm{0}_{4\times 3}\end{bmatrix},
\quad \bar{\bm{T}}_{m,2}=\begin{bmatrix}\bm{0}_{4\times 1}&\bar{\bm T}_m&\bm{0}_{4\times 2}\end{bmatrix},\\
\bar{\bm{T}}_{m,4}&=\begin{bmatrix}\bm{0}_{4\times 3}&\bar{\bm T}_m\end{bmatrix},
\quad \bar{\bm{T}}_{m,3}=\begin{bmatrix}\bm{0}_{4\times 2}&\bar{\bm T}_m&\bm{0}_{4\times 1}\end{bmatrix},
\end{aligned}
\end{equation*}
with $\bar{\bm{T}}_m$ and $\bm{T}_s$ defined in \eqref{eq:tm} and \eqref{eq:ts}, respectively.
%%%
\begin{figure*}[!htbp]
%
