%

This formulation allows us to interpret the learning scheme incorporating both lemmas as constrained optimization:
\begin{equation}\label{eq:gradient new}
\min_{\bm Q} 	\quad -\mathcal{G}(\bm{Q}),\qquad\qquad{\rm s.t.}		\quad \bm{T}\bm{Q}\geq0,
\end{equation}
where $\bm{T}=[\bm{T}_m;\bm{T}_s]$. 
%
\subsubsection{Primal-Dual Algorithm}
Now our task becomes solving the problem~\eqref{eq:gradient}. Since $\nabla^2(-\mathcal{G}(\bm Q))\succeq0$ and the constraint is linear, \eqref{eq:gradient} is convex. Consequently, the following primal-dual algorithm can be applied to solve the problem:
%
\begin{align}
{Q}_{k+1}(\phi,a)	&={Q}_k(\phi,a)+\zeta_k\{\nabla_{\bm {Q}_k}\mathcal{G}_{\phi,a}+[\bm{T}^T\bm{\nu}_k]_{\phi,a}\},\label{eq:primal}\\
\bm{\nu}_{k+1}		&=\bm{\nu}_k-\zeta_k\bm{T}\bm{Q}_k.\label{eq:dual}
\end{align}
%%%%
%
The algorithm is guaranteed to converge to the solution of the Bellman equation, as formalized in the following theorem.
\begin{thm}\label{thm:converge}{\rm
The structural update rules~\eqref{eq:primal}-\eqref{eq:dual} converge to a solution to~\eqref{eq:q update} almost surely.
}\end{thm}
\begin{proof}
See Appendix~\ref{apx:converge}.
\end{proof}
\begin{rmk}{\rm
Compared to the unconstrained optimization problem~\eqref{eq:gradient}, the problem \eqref{eq:gradient new} is now constrained. Intuitively, this means that the feasible domain is reduced at each time, making the corresponding learning scheme~\eqref{eq:primal}-\eqref{eq:dual} more efficient than~\eqref{eq:q learning}. A visual illustration of the relationship between the standard update~\eqref{eq:q learning} and our proposed structural update~\eqref{eq:primal}-\eqref{eq:dual} is provided in Fig.~\ref{fig:relation}.
}\end{rmk}
