\section{Proof of Theorem~\ref{thm:stationary}}\label{apx:stationary}
%\noindent\emph{Proof of Theorem~\ref{thm:stationary}.}
Considering a policy $a_k=\theta(\phi_k)$, we can express its discounted reward as follows:
\begin{equation}\label{eq:discounted cost}
V_{\delta}(\theta,\phi)\triangleq\sum_{k=0}^{\infty}\delta^k\mathbb{E}[r(\phi_k,\theta(\phi_k))|\phi_0=\phi],
\end{equation}
where $\delta\in(0,1)$ is the discount factor. Denote $V_{\delta}(\phi)\triangleq\sup_{\theta\in{\Theta}}V_{\delta}(\theta,\phi)$.


According to to~\cite[Theorem 4.1, Remark 3.2, Remark 4.1(b)]{guo2006average}, only the following items need to be verified:
\begin{enumerate}[(I)]
\item There exist positive constants $\zeta$ and $\mu<1$ and a measurable function $\Psi(\cdot)\geq1$ on $\mathbb{S}$ such that for all $(\phi,a)\in\mathbb{S}\times\mathbb{A}$, we have $\sum_{\phi'\in\mathbb{S}}\Psi(\phi')\mathbb{P}(\phi'|\phi,a)\leq\mu \Psi(\phi)+\zeta$.
\item For all $(\phi,a)\in\mathbb{S}\times\mathbb{A}$, there exists a constant $M\geq0$ such that $|r(\phi,a)|\leq M\Psi(\phi)$.
\item The action space $\mathbb{A}$ is finite.
\item The state space $\mathbb{S}$ is countably infinite.
\item There exists a state $\phi_f\in\mathbb{S}$ and two functions $l(\cdot)$ and $u(\cdot)$ on $\mathbb{B}_{\Psi}(\mathbb{S})$ such that $-l(\phi)\leq V_{\delta}(\phi)-V_{\delta}(\phi_f)\leq u(\phi)$, for all $\phi\in\mathbb{S}$ and $\delta\in(0,1)$, where $\mathbb{B}_{\Psi}(\cdot)$ is the Banach space given $\Psi(\cdot)$.
\end{enumerate}
%
We choose 
\begin{equation}\label{eq:measure}
\Psi(\phi)		=\sum_{i=1}^N\Psi(\tau^{(i)}), \quad \Psi(\tau^{(i)})	=||A_i||^{2\tau^{(i)}}.
\end{equation}
Since $||A_i||\geq1$, $\Psi(\phi)\geq1$ for any $\phi\in\mathbb{S}$. Then when the state $\phi$ transitions to $\phi'$, the function $\Psi(\phi'^{(i)})$ is updated according to the following rule: $\Psi(\tau'^{(i)})=1$ if $\tau'^{(i)}=0$ and $\Psi(\tau'^{(i)})=||A_i||^2\Psi(\tau^{(i)})$ if $\tau'^{(i)}=\tau^{(i)}+1$.

For ease of exposition, we focus on the case with $N=2$ sensors without loss of generality. We calculate the value of $\sum_{\phi'\in\mathbb{S}}\Psi(\phi')\mathbb{P}(\phi'|\phi,a)$ by fixing $\Lambda_{2}$ while varying $\Lambda_{1}$. Through some manipulations and relaxations (Fig.~\ref{fig:derivation} and Fig.~\ref{fig:proof}), the calculation is reduced to the scenario where only the $2$-nd sensor is present. This process can be repeated for each sensor in the general case of $N$ sensors, resulting in
