Let $\mu=\max_i{\kappa_i}<1$ and $\zeta=N$, (I) is proved.

Let $\varphi$ be a constant such that $\bar{P}_i\preceq\varphi I$ and $W_i\preceq\varphi I$. Define a function $\bar{h}_i(X)\triangleq A_iXA_i^T+\varphi I$. It is easy to verify that $h^{\tau^{(i)}}_i(\bar{P}_i)\preceq \bar{h}^{\tau^{(i)}}_i(\varphi I)\preceq\varphi\sum_{j=0}^{\tau^{(i)}}A_i^j(A_i^T)^j$.
%
Therefore,
\begin{equation*}
\begin{aligned}
\frac{\tr[h^{\tau^{(i)}+1}_i(\bar{P}_i)]}{\varphi}	&\leq n_i+n_i||A_i||^2+\cdots+n_i||A_i||^{2\tau^{(i)}+2}\\
						&=n_i\frac{||A_i||^{2\tau^{(i)}+4}-1}{||A_i||^2-1}\leq\frac{n_i||A_i||^4}{||A_i||^2-1}\Psi(\tau^{(i)}).
\end{aligned}
\end{equation*}
Therefore, we obtain ${\tr[h^{\tau^{(i)}+1}_i(\bar{P}_i)]}\leq M\Psi(\tau^{(i)})$, where $M=\varphi\max_i\frac{ n_i||A_i||^4}{||A_i||^2-1}$.
Then, (II) is proved since:
\begin{equation*}
\begin{aligned}
0&\leq r(\phi,a)	=\sum_{i=1}^N\left\{\lambda^{(i)}\tr[\bar{P}_{i}]+(1-\lambda^{(i)})\tr[h_i^{\tau^{(i)}+1}(\bar{P}_{i})]\right\}\\
			&\leq\sum_{i=1}^N\tr[h_i^{\tau^{(i)}+1}(\bar{P}_{i})]\leq\sum_{i=1}^N M\Psi(\tau^{(i)})=M\Psi(\phi).
\end{aligned}
\end{equation*}
According to~\cite[Lemma 3.2]{guo2006average}, for any $\delta\in(0,1)$ and state $\phi\in\mathbb{S}$, the following holds:
\begin{equation*}
V_{\delta}(\phi)\leq \frac{M\Psi(\phi)}{1-\delta}+\frac{M\zeta}{(1-\mu)(1-\delta)}.
\end{equation*}
%
Let $\phi_f=(b, E, \Lambda_f^{(1)},\dots,\Lambda_f^{(N)})$, where $\Lambda_f^{(i)}=(H^{(i)},G^{(i)},0)$. Since $V_{\delta}(\phi)\geq0$, we obtain
{\small
\begin{equation*}
\begin{aligned}
V_{\delta}(\phi)-V_{\delta}(\phi_f)	&\geq0-V_{\delta}(\phi_f)	\geq  -\frac{M\Psi(\phi_f)}{1-\delta}-\frac{M\zeta}{(1-\mu)(1-\delta)}\\
										&=-\frac{(N-\mu N+\zeta)M}{(1-\mu)(1-\zeta)}.
\end{aligned}
\end{equation*}}
On the other hand, let $\underline{k}=\inf_{k\geq0}\{k|\phi_k=\phi_f,\phi_0=\phi\}$. Then
{\small
\begin{equation*}
\begin{aligned}
V_{\delta}(\phi)	&=\mathbb{E}\left[\sum_{k=0}^{\underline{k}}\delta^kr(\phi_k,\theta^*(\phi_k))|\phi_0=\phi\right]\\
				&\quad+\mathbb{E}\left[\sum_{k=\underline{k}}^{\infty}\delta^{k}r(\phi_k,\theta^*(\phi_k))|\phi_0=\phi,\phi_{\underline{k}}=\phi_f\right]\\
				&=\mathbb{E}\left[\sum_{k=0}^{\underline{k}}\delta^kr(\phi_k,\theta^*(\phi_k))|\phi_0=\phi\right]+\mathbb{E}[\delta^{\underline{k}}|\phi_0=\phi]V_{\delta}(\phi_f)\\
				&\leq\mathbb{E}\left[\sum_{k=0}^{\underline{k}}\delta^kr(\phi_k,\theta^*(\phi_k))|\phi_0=\phi\right]+V_{\delta}(\phi_f).
\end{aligned}
\end{equation*}}
By Lemma~\ref{lemma:bound}, $\mathbb{E}[\sum_{k=0}^{\underline{k}}\delta^kr(\phi_k,\theta^*(\phi_k))|\phi_0=\phi]$ is bounded. Therefore, by letting $l(\phi)=(N-\mu N+\zeta)M/[(1-\mu)(1-\zeta)]$ and $u(\phi)=\mathbb{E}[\sum_{k=0}^{\underline{k}}\delta^kr(\phi_k,\theta^*(\phi_k))|\phi_0=\phi]$, we complete the proof of (V), and thus the proof of Theorem~\ref{thm:stationary}.
