\section{Proof of Lemma~\ref{lemma:monototic}}\label{apx:monototic}
%\noindent\emph{Proof of Lemma~\ref{lemma:monototic}.}
Recall the discounted reward $V_{\delta}(\phi)$ defined in~\eqref{eq:discounted cost}. Similar to the average-cost problem, the optimal policy for the discounted cost problem satisfies the Bellman equation:
\begin{equation}\label{eq:bellman discount}
V_{\delta}(\phi)=\max_{a\in\mathbb{A}_\phi}\{r(\phi,a)+\delta\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)V_{\delta}(\phi')\}.
\end{equation}
Define the mapping $\mathcal{T}_{\delta}(\cdot)$ as the Bellman operator on $\hat{V}_{\delta}(\phi)$, $\phi\in\mathbb{S}$ as
\begin{equation}\label{eq:map}
\mathcal{T}_{\delta}\hat{V}_{\delta}(\phi)=\max_{a\in\mathbb{A}_\phi}\{r(\phi,a)+\delta\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)\hat{V}_{\delta}(\phi')\}.
\end{equation}
%
In what follows, we first demonstrate that $\mathcal{T}_{\delta}(\cdot)$ is a contraction mapping. We then apply the induction-based method to prove that $V_{\delta}(\phi)$ is monotonic, and subsequently show that $V(\phi)$ is also monotonic.
%
\begin{definition}[Weighted supremum norm]{\rm
Let $\Psi(\cdot)$ be an arbitrary positive real-valued function on $\mathbb{S}$. The weighted supremum norm $||\cdot||_\Psi$ for real-valued functions $V(\cdot)$ on $\mathbb{S}$, is defined as $||V||_\Psi=\sup_{\phi\in\mathbb{S}}|V(\phi)|/\Psi(\phi)$.
}\end{definition}

\begin{definition}[Contraction mapping]{\rm
The mapping $\mathcal{T}_{\delta}(\cdot)$ is said to be a contraction mapping on $\mathbb{B}_\Psi(\mathbb{S})$ with repsect to $\Psi(\cdot)$, if for all $\hat{V}_{\delta}, \hat{V}_{\delta}'\in\mathbb{B}_\Psi(\mathbb{S})$, the inequality $||\mathcal{T}_{\delta}\hat{V}_{\delta}-\mathcal{T}_{\delta}\hat{V}_{\delta}'||_\Psi\leq\vartheta ||\hat{V}_{\delta}-\hat{V}_{\delta}'||_\Psi$ holds, where $0\leq\vartheta<1$.
}\end{definition}
\begin{lemma}{\rm
If Assumption~\ref{assumption:stable} holds, then the Bellman operator $\mathcal{T}_{\delta}(\cdot)$ in~\eqref{eq:map} is a contraction mapping with respect to the function $\Psi(\cdot)$ as defined in~\eqref{eq:measure}.
}\end{lemma}
\begin{proof}
By~\cite[Proposition 8.3.9]{hernandez2012further}, it suffices to verify that a set of assumptions, i.e., \cite[Assumptions 8.3.1, 8.3.2, and 8.3.3]{hernandez2012further}, are satisfied. Assumptions 8.3.1 and 8.3.3 impose conditions on the compactness of the action space and the continuity of the reward functions in actions, both of which hold naturally in our setup. Furthermore, by \cite[Remark 8.3.5]{hernandez2012further}, Assumption 8.3.2 can be replaced by conditions (I)–(II) provided in Appendix~\ref{apx:stationary}, which have already been verified. Hence, $\mathcal{T}_{\delta}(\cdot)$ is a contraction mapping.
\end{proof}
%
On the other hand, with (I)-(III) in Appendix~\ref{apx:stationary}, a stationary policy satisfying~\eqref{eq:bellman discount} exists~\cite[Lemma 3.2]{guo2006average}. Thus, we are able to prove the monotonicity of $V_{\delta}(\phi)$ by induction.

Consider a function $\hat{V}_{\delta}(\cdot)$. Assume Lemma~\ref{lemma:monototic} holds for $\hat{V}_{\delta}(\cdot)$, i.e., $\hat{V}_{\delta}(\phi_+)\geq\hat{V}_{\delta}(\phi_-)$ for all $\phi_+$ and $\phi_-$. Let $a^*_-$ denote the action that maximizes the right-hand side of~\eqref{eq:map} for $\phi_-$, i.e., $a_-^*=\arg\max_{a\in\mathbb{A}_{\phi_-}}\{r(\phi_-,a)+\delta\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi_-'|\phi_-,a)\hat{V}_{\delta}(\phi_-')\}$. Then, by assumption, we have 
\begin{equation*}
\sum_{\phi'_+\in\mathbb{S}}\mathbb{P}(\phi'_+|\phi_+,a_-^*)\hat{V}_{\delta}(\phi_+')\geq \sum_{\phi'_-\in\mathbb{S}}\mathbb{P}(\phi'_-|\phi_-,a_-^*)\hat{V}_{\delta}(\phi_-').
\end{equation*}
%
Additionally, since $r(\phi_+,a^*_-)\geq  r(\phi_-,a^*_-)$, we obtain
\begin{equation*}
\begin{aligned}
\mathcal{T}_{\delta}\hat{V}_{\delta}(\phi_+)	&\geq r(\phi_+,a^*_-)+\delta\sum_{\phi'_+\in\mathbb{S}}\mathbb{P}(\phi'_+|\phi_+,a_-^*)\hat{V}_{\delta}(\phi_+')\\
				&\geq r(\phi_-,a^*_-)+\delta\sum_{\phi'_-\in\mathbb{S}}\mathbb{P}(\phi'_-|\phi_-,a_-^*)\hat{V}_{\delta}(\phi_-')\\
				&=\mathcal{T}_{\delta}\hat{V}_{\delta}(\phi_-).
\end{aligned}
\end{equation*}
Therefore, Lemma~\ref{lemma:monototic} still holds after the Bellman operator $\mathcal{T}_{\delta}(\cdot)$. By Banach fixed-point theorem, since the mapping is contractive, it has a unique fixed point. By induction, the fixed point $V_{\delta}(\cdot)$ satisfies $V_{\delta}(\phi_+)\geq V_{\delta}(\phi_-)$ for all $\phi_+$ and $\phi_-$.

We note that the sequence $\{V_{\delta(n)}(\phi)-V_{\delta(n)}(\phi_f)\}$ is equicontinuous, where $\{\delta(n)\}$ is any sequence of increasing discount factors such that $\delta(n)\to1$ as $n\to\infty$. Furthermore, since conditions (I)-(V) in Appendix~\ref{apx:stationary} are satisfied, it follows from~\cite[Remark 4.1(b)]{guo2006average} that, $V(\phi)=\lim_{n\to\infty}\{V_{\delta(n)}(\phi)-V_{\delta(n)}(\phi_f)\}$. As a result, $V(\phi)$ is also monotonically increasing in $\tau^{(i)}$. This completes the proof.

\section{Proof of Lemma~\ref{lemma:super}}\label{apx:additive}
For notation simplicity, we denote the packet arrival rate of the $i$-th sensor under action $a$ as
\begin{equation*}
f_a^{(i)}\triangleq\lambda^{(i)}=f\left(\frac{H^{(i)}}{a^{(i)}G^{(i)}+\sigma_i^2}\right).
\end{equation*}

We let $\hat{\phi}_+=(b,E,\hat{\Lambda}_+^{(1)},\dots,\hat{\Lambda}_+^{(N)})$ and $\hat{\phi}_-=(b,E,\hat{\Lambda}_-^{(1)},\dots,\hat{\Lambda}_-^{(N)})$, where for $j=1,\dots,N$,
\begin{equation*}
\hat{\phi}^{(j)}_+	=(H^{(j)},G^{(j)},\tau^{(j)}_+),\quad\hat{\phi}^{(j)}_-		=(H^{(j)},G^{(j)},\tau^{(j)}_-).
\end{equation*}
Here, $b$, $E$, $H^{(j)}$ and $G^{(j)}$ are some arbitrary values. Additionally, for the specific index $i$, $\tau^{(i)}_-\leq  \tau^{(i)}_+$, and for $j\neq i$, $\tau^{(j)}_-=  \tau^{(j)}_+=\tau^{(j)}$. 

Then for the $i$-th system, since
\begin{equation*}
\begin{aligned}
f_{a_{-,i}}^{(i)}	&\geq f_{a_{+,i}}^{(i)},\\
0\leq \tr[h^{\tau^{(i)}_-+1}(\bar{P}_{i})]&\leq \tr[h^{\tau^{(i)}_++1}(\bar{P}_{i})],
\end{aligned}
\end{equation*}
we have:
\begin{equation}\label{eq:1}
(f_{a_{-,i}}^{(i)}- f_{a_{+,i}}^{(i)})\tr[h^{\tau^{(i)}_++1}(\bar{P}_{i})]\geq(f_{a_{-,i}}^{(i)}- f_{a_{+,i}}^{(i)})\tr[h^{\tau^{(i)}_-+1}(\bar{P}_{i})].
\end{equation}
%

Otherwise, for $j\neq i$,
\begin{equation}\label{eq:2}
\begin{aligned}
&~(f_{a_{-,i}}^{(j)}- f_{a_{+,i}}^{(j)})\tr[h^{\tau^{(j)}_++1}(\bar{P}_{j})]\\	
=&~(f_{a_{-,i}}^{(j)}- f_{a_{+,i}}^{(j)})\tr[h^{\tau^{(j)}_-+1}(\bar{P}_{j})]\\
		=&~(f_{a_{-,i}}^{(j)}- f_{a_{+,i}}^{(j)})\tr[h^{\tau^{(j)}+1}(\bar{P}_{j})].
\end{aligned}
\end{equation}

On the other hand, applying Lemme~\ref{lemma:monototic} and following a similar trend as in~\eqref{eq:1}-\eqref{eq:2}, we have
\begin{equation}\label{eq:3}
\begin{aligned}
&~\mathbb{E}[V(\phi')|\hat{\phi}_+,a_+]-\mathbb{E}[V({\phi}')|\hat{\phi}_+,a_-]\\
\geq&~\mathbb{E}[V(\phi')|\hat{\phi}_-,a_+]-\mathbb{E}[V(\phi')|\hat{\phi}_-,a_-],
\end{aligned}
\end{equation}
where $\mathbb{E}[V(\phi')|\phi,a]=\sum_{\phi'\in\mathbb{S}}\mathbb{P}(\phi'|\phi,a)V(\phi')$.

Combining~\eqref{eq:1}-\eqref{eq:3}, we obtain
\begin{equation*}
\begin{aligned}
	&~ Q (\tau^{(i)}_+,a_{+,i})- Q (\tau^{(i)}_+,a_{-,i})\\
=	&~ \sum_{j=1}^N (f_{a_{+,i}}^{(j)}-f_{a_{-,i}}^{(j)})\tr[\bar{P}_{j}]+(f_{a_{-,i}}^{(j)}- f_{a_{+,i}}^{(j)})\tr[h^{\tau^{(j)}_++1}(\bar{P}_{j})]\\
	&~\quad+	\mathbb{E}[V(\phi')|\hat{\phi}_+,a_+]-\mathbb{E}[V(\phi')|\hat{\phi}_+,a_-]\\
\geq	&~\sum_{j=1}^N (f_{a_{+,i}}^{(j)}-f_{a_{-,i}}^{(j)})\tr[\bar{P}_{j}]+(f_{a_{-,i}}^{(j)}- f_{a_{+,i}}^{(j)})\tr[h^{\tau^{(j)}_-+1}(\bar{P}_{j})]\\
	&~\quad+\mathbb{E}[V(\phi')|\hat{\phi}_-,a_+]-\mathbb{E}[V(\phi')|\hat{\phi}_-,a_-]\\
=	&~ Q (\tau^{(i)}_-,a_{+,i})- Q (\tau^{(i)}_-,a_{-,i}),
\end{aligned}
\end{equation*}
which completes the proof.%\hfill$\Box$

