Let $(P,Q,R,E)$ be an instance of \dmatchingshort such that each  element of $P\uplus Q \uplus R$ belongs to at most three sets in $E$. %Let $P=\{p_1,\ldots,p_n\}, Q=\{q_1,\ldots,q_n\}$, and $R=\{r_1,\ldots,r_n\}$. 
We construct an instance of \mefe as follows. For each $r \in R$, we create three courses $r^{1},r^{2},r^{3}$. Intuitively, three copies of $r$ denote the sets containing $r$. 
For each $p\in P$, we add a TA $p$ and for each $q\in Q$, we add a TA $q$. We call these TAs as ``original'' and denote this set as $O$.  Next, we add some ``dummy'' TAs. For each $r \in R$, we add four dummy TAs $r^{d_1}$ , $r^{d_2}$ , $r^{d'_1}$ and $r^{d'_2}$. Let $D=\{r^{d_i}\colon r\in R, i\in [2]\}$ and $D'=\{r^{d'_i}\colon r\in R, i\in [2]\}$. Let $X$ be the set of all courses, i.e., $X=\{r^j \colon r\in R, j\in [3]\}$, and $T$ be the set of all the TAs, i.e., $T=O \uplus D \uplus D'$. Next, we define the utility function of every course. Suppose that $(p,q,r), (p',q',r)$, and $(p'',q'',r)$ be three triplets in $E$. Then, $v_{r^1}(p)=v_{r^1}(q)=2$, $v_{r^2}(p')=v_{r^2}(q')=2$, and $v_{r^3}(p'')=v_{r^3}(q'')=2$. Furthermore, for all $i\in [3]$, $v_{r^i}(r^{d_1})=v_{r^i}(r^{d_2})=3$, and $v_{r^i}(r^{d'_1})=v_{r^i}(r^{d'_2})=1$. That is, first copy of $r$ gives valuations $2$ to the TAs corresponding to the elements in the first set with $r$, second copy gives valuations $2$ to the TAs corresponding to the elements in the second set with $r$, and so on. All the copies gives valuation $3$ to the corresponding TAs in the set $D$ and $1$ to the corresponding elements in the set $D'$. The valuation for all the other TAs is $0$.  





For every TA $t$ and course $x$, the utility function is as follows: $u_t(x)=1$, i.e., all the TAs value all the courses equally (the value does not matter in our reduction). 

Next, we define a grade function for each TA as follows.
For each TA $t$ corresponding to elements in $P\uplus Q$, $g_t(r_i^j)=1$, if $t$ and $r$ belong to a triplet in $E$. If $t$ is a dummy TA such that $t\in \{r^{d_1},r^{d_2},r^{d'_1},r^{d'_2}\}$, then, $g_t(r_i^j)=2$, where $i\in [n], j\in [3]$, and $0$ for all the other courses. 




We set $k=2$ and the capacity for each course is $2$.

Next, we prove the correctness. In particular, we prove the following. 

\begin{restatable}{lemma}{lem:correctnees-nph-3DPM}
${\cal I}=(P,Q,R,E)$ is a yes-instance of \dmatchingshort if and only if ${\cal I}=(X,T,\{v_i\}_{i\in X}, \{u_i\}_{i\in T}, \{g_i\}_{i\in T}, \{c_i\}_{i\in X},k\}$ is a yes-instance of \mefe. 
\label{lem:correctnees-nph-3DPM}\end{restatable}

\begin{proof}
    In the forward direction, let $M$ be a solution to ${\cal I}$. We construct a solution to ${\cal I}$ as follows. If $(r,p,q)\in M$, then $\mu(p)=\mu(q)=r^1$. Furthermore, $\mu(r^{d_1})=\mu(r^{d'_1})=r^2$ and $\mu(r^{d_2})=\mu(r^{d'_2})=r^2$. We first show that $\mu$ is a feasible matching.
    \begin{restatable}{claim}{clm:matching-feasibility}
            $\mu$ is a feasible matching.
   \label{clm:matching-feasibility}\end{restatable}
    \begin{proof}
        Since $M$ is a perfect matching, for every $r\in R$, its first copy $r^1$ is matched to two TAs. By the construction, all the other courses are matched to two dummy TAs. Thus, $\mu$ is a feasible matching.
    \end{proof}
    Next, we argue that $\mu$ meets satisfaction criteria of each course.
    \begin{restatable}{claim}{clm:satisfaction}
               For each course $r^j\in X$, where $r\in R$, ${\sf AvgUtil}(r^j)\geq 2$.
\label{clm:satisfaction}\end{restatable}
    \begin{proof}
        Recall that every $r\in R$ is in a triplet in $M$. Suppose $(p,q,r)\in M$. Then, $\mu^{-1}(r^1)=\{p,q\}$. Since the utility of $r^1$ for $p$ and $q$ is $2$, ${\sf AvgUtil}(r^1)=2$. Since $r^2$ is matched with $r^{d_1}$ and $r^{d'_1}$, and its utility for $r^{d_1}$ is $3$ and $r^{d'_1}$ is $1$, ${\sf AvgUtil}(r^2)=2$. Similarly, since $r^3$ is matched with $r^{d_2}$ and $r^{d'_2}$, ${\sf AvgUtil}(r^3)=2$.
    \end{proof}
    Next, we prove merit-based envy-freeness between TAs. Note that since every TA values all the courses equally, if he is matched to a course, then there is no envy. Since $M$ is a perfect matching, every element in $P\uplus Q$ is in a triplet in $M$. Thus, every TA corresponding to elements in $P\uplus Q$ is matched to a course. TAs $r^{d_1} \in D, r^{d'_1} \in D'$ are matched to $r^2$, and $r^{d_2} \in D, r^{d'_2} \in D'$ are matched to $r^3$. Thus, all the TAs are matched to a course. This completes the proof in the forward direction.


In the reverse direction, let $\mu$ be a solution to ${\cal I}$. We begin with the following observations about the solution $\mu$. 

\begin{restatable}{observation}{obs1:rev-proof}
   Every course $x$ is matched to two TAs for whom the utility is non-zero. 
\label{obs1:rev-proof}\end{restatable}

\begin{proof}
    Since the capacity of every course is two, every course is matched to two TAs. Recall that $k=2$ and maximum utility of a course for any TA is $3$. Thus, $x$ is matched to TAs with non-zero utility. 
\end{proof}

\begin{restatable}{observation}{obs2:rev-proof}
    Every TA $t\in D\uplus D'$ is matched to a course in $\mu$. 
\label{obs2:rev-proof}\end{restatable}

\begin{proof}
    Suppose that a TA $t\in D\uplus D'$ is unsaturated in $\mu$. Recall that grade of $t$ is $2$ in every course, and no other TA has higher grade. Since $t$ is unsaturated, $t$ envies all the TAs by the definition of merit-based envy-freeness. 
\end{proof}

\begin{restatable}{observation}{obs3:rev-proof}
     If a TA $t \in D'$ matched to a course $x$, then $x$ is also matched to a TA in $D$.  
\label{obs3:rev-proof}\end{restatable}

\begin{proof}
    Recall that the capacity of every course is $2$ and $k=2$. Thus, course $x$ is matched to two TAs. Since the utility of a course for TAs in $D'$ is $1$, $x$ is matched with a TA in $D$ as the utility for TAs in $O$ is $2$ and for TAs in $D$ is $3$. 
\end{proof}
Due to Observations~\ref{obs2:rev-proof} and \ref{obs3:rev-proof}, without loss of generality, let $r^{d_1}, r^{d'_1}$ are matched to $r^{j}$ and $r^{d_2}, r^{d'_2}$ are matched to $r^{j'}$, where $r\in R, j,j' \in [3], j\neq j'$. Thus, $r^i$, where $i\in [3]\setminus \{j,j'\}$, is matched to two TAs in $O$, say $p,q$. Due to Observation~\ref{obs1:rev-proof} and the fact that $r^i$ has non-zero utility to $p,q \in O$, if $(p,q,r)\in E$, we know that if a course $x$ is matched to two TAs in $O$, then $r$ and $\mu^{-1}(r)$ forms a triplet in $T$.  

We construct a set $M\subseteq T$ as follows: $M=\{(r,p,q)\in T \colon \mu^{-1}(r^i)=\{p,q\}, \text{ where } i\in [3]\}$. Next, we argue that $M$ is a matching. Note that $p$ and $q$ are only matched to one course in $\mu$. Since the capacity of every course is also $2$, a course is matched to only two TAs. Thus, $M$ is a matching. Next, we argue that $M$ is a perfect matching. Recall that $k=2$ and the capacity of every course is also $2$, due to Observation~\ref{obs3:rev-proof}, only two courses corresponding to $r\in R$ can be matched to TAs in $D\uplus D'$. Morevover, since capacity of each course is two, one copy is matched to two TAs in $O$. Hence, every $r\in R$ belongs to a triplet in $M$. Since $|P|=|Q|=|R|$ and $M$ is a matching, every element of $P\uplus Q$ also belong to a triplet in $M$. 
\end{proof}
This completes the proof.
\end{proof}
}

