$T_\mu=N(x_1)\setminus \{t_{\ell}\}$, 
\State $\mu$={\texttt{Extended Matching}}($G',\mu,T_\mu,X_\mu$) \label{stp:cycle-c1}
\If{$\mu$ is a solution to ${\cal I}$}
\Return $\mu$
\EndIf
%    \State $T_{\mu}=\emptyset$, $X_{\mu}=\emptyset$
