\begin{algorithm}
\caption{Tile Traversal in Agglomerative Gate Fusion}
% \caption{Tile Traversal in Gate Fusion}
\fontsize{8.5}{9.0}\selectfont
\label{alg:1}
\begin{algorithmic}[1]
\Function{Traverse}{$\textrm{CircuitTile $T$, unsigned $k$}$}
    \State{$\delta \gets \textbf{false}$}
    \For{$r \in [0 .. N_\mathrm{rows}-1]$}
        \For {$q \in  [0 .. N_\mathrm{qubits}-1]$}
            \State $b_{\top} \leftarrow T_{r,q}$
            \If {$b_{\top} \neq \varnothing$}
                \State $b_{\bot} \leftarrow T_{r+1,q}$
                \If {$b_{\bot} \neq \varnothing$}
                    \State \Call{MoveBlock}{$b_{\top}, b_{\bot}$}
                \EndIf
                \If {\Call{Fusible}{$b_{\top}, b_{\bot}, k$}}
                    \State \Call{Fuse}{$b_{\top}$, $b_{\bot}$} \Comment{Consecutive Fusion}
                    \State $\delta \gets \textbf{true}$ 
                \EndIf
            \EndIf
        \EndFor
        \For {$q \in  [1 .. N_\mathrm{qubits}-1]$}
            \State $b_{\top} \leftarrow T_{r,q-1}$
            \State $b_{\bot} \leftarrow T_{r,q}$
            \If {\Call{Fusible}{$b_{\top}, b_{\bot}, k$}}
                \State \Call{Fuse}{$b_{\top}$, $b_{\bot}$} \Comment{Commuting Fusion}
                \State $\delta \gets \textbf{true}$ 
            \EndIf
        \EndFor
    \EndFor
    \State \Return{$\delta$}
\EndFunction
\end{algorithmic}
\end{algorithm}


% \textbf{Tile Traversal}\quad{}
% In certain cases, fuse-able gates may not lie in consecutive rows. To resolve this, we dynamically move some blocks during the fusion process via the \code{MoveDown} call.


The algorithm actively relocates blocks to create fusion opportunities. Specifically, when the traversal reaches a gate block in the \(i\)-th row and the space below it in the \((i+1)\)-th row is unoccupied, the algorithm moves the gate block down to the \((i+1)\)-th row to fill the space. This relocation allows the block to potentially fuse with a block in the \((i+2)\)-th row. For example, \figref{fig:537} gives an illustration of such a case. In the compact tile above, blocks 1 and 3 are not in consecutive rows. Since the position immediately below block 1 is empty (line 8 in Algorithm \ref{alg:1}), block 1 can be moved down. Block 1 will then fuse with block 3 when we traverse to the new position of block 1.


%During traversals of the tile, when two blocks are fused together, a new row has to be created to hold the fused block. This may leave some vacant spaces and break the compactness of the tile (\figref{fig:543}). Compressing tile takes a relatively long time because it may move many gate blocks, so we only compress the tile after each tile traversal. For a complete fusion, multiple tile traverses might be needed. In practice, we find the MoveDown scheme will eliminate most vacancies in the middle, and only a small number of fuse-able blocks will be left in the bottom after a single traversal.

% After two gate blocks $b_{\top}$ and $b_{\bot}$ in consecutive rows $r$ and $(r+1)$ are fused, the $\Call{Fuse}{}$ procedure needs to place the fused block in a proper location. Specifically,
To place fused blocks back into the tile,
the $\Call{Fuse}{}$ procedure first removes $b_{\top}$ and $b_{\bot}$. If the removal creates enough space in rows $r$ or $(r+1)$ to accommodate the fused block, the fused gate block occupies the corresponding space (prioritize on row $(r+1)$). Otherwise, the $\Call{Fuse}{}$ procedure inserts a new row between the two rows and places the fused block in the new row. Note that the creation of the new row can leave empty spaces (\figref{fig:543}). To maintain the compactness of the \code{CircuitTile}, we compress it at the end of each tile traversal.


