%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\section{Formulation} 
\label{s:formulation}

In this section we derive the form of the wave equation we will be solving numerically.
In section \ref{s:metric} we foliate Minkowski spacetime into hyperboloidal slices of constant mean curvature and apply a conformal transformation to the metric. 
We work out the wave equation in terms of the conformally rescaled quantities in section \ref{s:waveeq} and write it in first-order in time, second-order in space form.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Hyperboloidal foliation of Minkowski spacetime}
\label{s:metric}

We start with the $(n+1)$-dimensional Minkowski metric in spherical polar coordinates,
\begin{equation}
  \eta = -\rmd t^2 + \rmd r^2 + r^2 \sigma^{(n-1)},
  \quad t\in\R, \quad r\in(0,\infty).
\end{equation}
Here $\sigma^{(n-1)}$ is the standard round metric on $S^{n-1}$, the $(n-1)$-dimensional unit sphere. 
Explicitly, we have 
\begin{eqnarray}
  \sigma^{(1)} = \rmd \varphi^2, \\
  \sigma^{(2)} = \rmd \theta^2 + \sin^2\theta \, \rmd\varphi^2 , 
\end{eqnarray}   
where $\theta \in [0,\pi]$ and $\varphi \in [0,2\pi)$.
More generally for $n>3$,
\begin{equation} 
  \sigma^{(n-1)} = \rmd \theta_1^2 + \sin^2\theta_1 \left( \rmd \theta_2^2 + \sin^2\theta_2 (\ldots (\rmd \theta_{n-2}^2 + \sin^2 \theta_{n-2} \rmd\varphi^2 ) )\right)
\end{equation}
with $\theta_1, \ldots, \theta_{n-2} \in [0,\pi]$ and $\varphi \in [0,2\pi)$.

We introduce a new time coordinate 
\begin{equation}
  \label{e:hyperboloid}
  \tilde t = t - \sqrt{a^2 + r^2}
\end{equation}
with a constant $a = n/C > 0$. 
The hypersurfaces $\tilde t=\const$ are hyperboloids and $C$ is their constant mean curvature (up to a sign as discussed further below).
In the new coordinates the Minkowski metric reads
\begin{equation}
  \eta = -\rmd \tilde t^2 - \frac{2r}{\sqrt{a^2 + r^2}} \, \rmd \tilde t \, \rmd r + \frac{a^2}{a^2 + r^2} \, \rmd r^2 + r^2 \sigma^{(n-1)}. 
\end{equation}
Let us also introduce a new radial coordinate $\tr$ depending on $r$ only.
We can arrange for the spatial metric to be conformally flat if we demand 
\begin{equation} \label{rdiff}
  \frac{a^2}{a^2 + r^2} \rmd r^2 = \frac{r^2}{\tr^2} \rmd \tr^2 \; \Leftrightarrow \; \frac{\rmd r}{\rmd \tr} = \frac{r \sqrt{a^2 + r^2}}{\tr a}.
\end{equation}
This ordinary differential equation can be solved explicitly.
If we impose the boundary condition $\tr \to 1$ as $r\to \infty$, we obtain 
\begin{equation}
  \label{e:rofr_}
  r = \frac{2a\tr}{1-\tr^2} = \frac{2n\tr}{C(1-\tr^2)}.
\end{equation}
From \eref{e:hyperboloid} we observe that on a slice $\tilde t=\const$, as the conformal boundary $\tr\to 1$ is approached, we have  
\begin{equation}
  t, r \to \infty, \quad t - r \to \tilde t = \const,
\end{equation}
so the slice becomes asymptotically characteristic and $\tr=1$ corresponds to \Scri.

The metric now takes the form 
\begin{eqnarray}
  \eta &=& -\rmd \tilde t^2 - \frac{2 r^2}{\tr a} \rmd \tilde t \, \rmd \tr + \frac{r^2}{\tr^2} \left( \rmd \tr^2 + \tr^2 \sigma^{(n-1)} \right)\nonumber\\
  &=& \Omega^{-2} \left[ - \tilde \alpha^2 \rmd \tilde t^2 + (\rmd \tr + \tilde \beta^{\tr} \rmd \tilde t)^2 + \tr^2 \sigma^{(n-1)} \right] =: \Omega^{-2} \tilde \eta. 
\end{eqnarray}
Here we have introduced the conformal factor 
\begin{equation} \label{e:Omega}
  \Omega = \frac{\tr}{r} = \frac{C}{2n} (1-\tr^2),
\end{equation}
the conformal shift vector $\tilde \beta$, which only has a radial component 
\begin{equation} \label{e:shift}
  \tilde \beta^{\tr} = -\frac{\tr}{a} = -\frac{C}{n}\tr,
\end{equation}
and the conformal lapse function 
\begin{equation} \label{e:lapse}
  \tilde \alpha = \frac{C}{2n} (1+\tr^2)
\end{equation}
so that $\tilde \alpha^2 - (\tilde \beta^{\tr})^2 = \Omega^2$. 

From now on we will work entirely with the conformal metric $\tilde \eta$.
Its induced metric $\tilde \gamma$ on the $\tilde t=\const$ slices is flat,
\begin{equation}
  \tilde \gamma = \rmd \tr^2 + \tr^2 \sigma^{(n-1)}.
\end{equation}
The conformal extrinsic curvature of the $\tilde t=\const$ slices is\footnote{
  We use the sign convention $\Lie_{\tilde \nu} \tilde \gamma_{ab} = -2 \tilde K_{ab}$.
  For the $\tilde t=\const$ slices to intersect \Scri we need the constant $C>0$ so that the shift \eref{e:shift} is negative at $\tr=1$.
  Spacetime indices $a,b$ are raised and lowered using the conformal metric $\tilde \eta$, and repeated indices are summed over.
} 
\begin{equation} \label{e:confKab}
  \tilde K_{ab} = \frac{\tilde K}{n} \tilde \gamma_{ab}
\end{equation}
with the conformal mean curvature given by
\begin{equation}
  \tilde K = -\tilde \alpha^{-1} C = -\frac{2n}{\tr^2+1}. 
\end{equation}
Its Lie derivative along the conformal future-directed timelike unit normal $\tilde \nu$ to the $\tilde t=\const$ slices is 
\begin{equation}
  \Lie_{\tilde \nu} \tilde K = -\tilde \alpha^{-1} \tilde \beta^{\tr} \partial_{\tr} \tilde K = \frac{8n \tr^2}{(\tr^2+1)^3}.
\end{equation}

Combining the contracted Gauss and Ricci equations, we can relate the Ricci scalar $\tilde R$ of $\tilde \eta$ to the Ricci scalar $\tilde R_{\tilde \gamma}$ of $\tilde \gamma$:
\begin{equation} \label{e:gaussricci}
  \tilde R = \tilde R_{\tilde \gamma}- 2 \tilde \alpha^{-1} \tilde \Delta \tilde \alpha - 2 \Lie_{\tilde \nu} \tilde K + \tilde K^2 + \tilde K_{ab} \tilde K^{ab}.
\end{equation}
Here 
\begin{equation}
  \tilde \Delta = \partial_{\tr}^2 + (n-1) {\tr}^{-1} \partial_{\tr} + \tr^{-2} \mathring{\Delta}^{(n-1)}
\end{equation}
is the standard flat Laplacian of the flat conformal metric $\gamma$ and
$\mathring{\Delta}^{(n-1)}$ is the Laplace-Beltrami operator on the sphere $S^{n-1}$.
Explicitly, we have
\begin{eqnarray}
  \mathring{\Delta}^{(1)} = \partial_\varphi^2, \\
  \mathring{\Delta}^{(2)} = \partial_\theta^2 + \cot\theta \, \partial_\theta + \frac{1}{\sin^2\theta}\partial_\varphi^2.
\end{eqnarray}

In our numerical implementation for higher dimensions $n>3$, we shall impose an SO$(n-1)$ symmetry so that all but one of the angular coordinates are suppressed.
The angular Laplacian then reduces to
\begin{equation}
  \mathring{\Delta}^{(n-1)} = \partial_\theta^2 + (n-2)\cot\theta \, \partial_\theta.
\end{equation}

Using the fact that $\tilde R_{\tilde \gamma} = 0$ and the form of the conformal extrinsic curvature \eref{e:confKab}, we obtain from \eref{e:gaussricci}
\begin{equation}
  \tilde R = -2 \tilde \alpha^{-1} \tilde \Delta \tilde \alpha - 2 \Lie_{\tilde \nu} \tilde K + \frac{n+1}{n} \tilde K^2 =
  \frac{4n[-\tr^4 + (n-5)\tr^2 + n]}{(\tr^2+1)^3}.
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Wave equation}
\label{s:waveeq}

The scalar field $\Phi$ is supposed to obey the NLW 
\begin{equation} \label{e:nlw2}
  \Box \Phi = \mu |\Phi|^{p-1} \Phi,
\end{equation}
where $\Box$ is the d'Alembertian of the Minkowski metric $\eta$.

Defining a conformally rescaled scalar field 
\begin{equation}  \label{e:Phitildedef}
  \tilde \Phi = \Omega^{(1-n)/2} \Phi
\end{equation}
and using the conformal transformation properties of the d'Alembertian and the Ricci scalar, we have
\begin{equation} \label{e:confNLW}
  \fl \tilde \Box \tilde \Phi - \frac{n-1}{4n} \tilde R \tilde \Phi  = \Omega^{-(n+3)/2} \left( \Box\Phi - \frac{n-1}{4n} R \Phi \right) = \mu \Omega^{[p(n-1)-n-3]/2} |\tilde \Phi|^{p-1} \tilde \Phi,
\end{equation}
where on the right-hand side we have used \eref{e:nlw2} and the fact that $\eta$ is flat, $R = 0$.
This equation is regular at \Scri, where $\Omega=0$, iff $n \geqslant 2$ and
\begin{equation}
  p(n-1)-n-3\geqslant 0 \; \Leftrightarrow \; p \geqslant \frac{n+3}{n-1}
  =: p_\mathrm{conf}.
\end{equation}
For any $n\geqslant 3$ we have $p_\mathrm{conf} < p_\mathrm{crit} $,
where $p_\mathrm{crit}$ was defined in \eref{e:pcrit}, cf. table \ref{t:critexps}.
Thus the conformal approach is capable of treating both energy-subcritical and supercritical NLWs.

\begin{table} 
  \[
  \begin{array}{c||c|c|c|c|c|c|c}
    n & 2 & 3 & 4 & 5 & 6 & 7 & \cdots\\\hhline{=||=|=|=|=|=|=|=}
    p_\mathrm{conf} & 5 & 3 & 7/3 & 2 & 9/5 & 10/6 & \cdots\\\hline
    p_\mathrm{crit} & \infty & 5 & 3 & 7/3 & 2 & 9/5 & \cdots
  \end{array}
\]
  \caption{\label{t:critexps}
    The smallest allowed exponent $p_\mathrm{conf}$ of the nonlinearity for the conformal approach to be applicable, as compared with the energy-critical exponent $p_\mathrm{crit}$, depending on the number of space dimensions $n$.
  For $n=2$ the NLW is energy-subcritical for any $p>1$.}
\end{table}

Performing an $(n+1)$-decomposition of the conformal d'Alembertian, \eref{e:confNLW} becomes
\begin{equation} \label{e:wave2ndorder}
  \fl -\Lie_{\tilde \nu}^2 \tilde \Phi + \tilde \Delta \tilde \Phi + \tilde K \Lie_{\tilde \nu} \tilde \Phi + \tilde \alpha^{-1} \tilde \alpha^{,i} \tilde \Phi_{,i} - \frac{n-1}{4n} \tilde R \tilde \Phi = \mu \Omega^{[p(n-1)-n-3]/2} |\tilde \Phi|^{p-1} \tilde \Phi,
\end{equation} 
where spatial indices $i$ are raised and lowered using the flat conformal metric $\tilde \gamma$.
We can write this equation in first-order in time form by introducing an auxiliary field $\tilde \Pi$,
\begin{eqnarray}
  \fl \Lie_{\tilde \nu} \tilde \Phi &=:& \tilde \Pi,\\
  \fl \Lie_{\tilde \nu} \tilde \Pi &=& \tilde \Delta \tilde \Phi + \tilde K \tilde \Pi + \tilde \alpha^{-1} \tilde \alpha^{,i} \tilde \Phi_{,i} 
  - \frac{n-1}{4n} \tilde R \tilde \Phi - \mu \Omega^{[p(n-1)-n-3]/2} |\tilde \Phi|^{p-1} \tilde \Phi.
\end{eqnarray}
Writing out the Lie derivative $\Lie_{\tilde \nu} = \tilde \alpha^{-1} (\partial_{\tilde t} - \Lie_{\tilde \beta})$, we arrive at
\begin{eqnarray}
  \label{e:scalarwave1}
  \fl \tilde \Phi_{,\tilde t} = \tilde \beta^{\tr} \tilde \Phi_{,\tr} + \tilde \alpha \tilde \Pi, \\
  \fl \tilde \Pi_{,\tilde t} = \tr^{1-n}\left[ \tr^{n-1} \left(\tilde \beta^{\tr} \tilde \Pi + \tilde \alpha \tilde \Phi_{,\tr} \right) \right]_{,\tr} +\tilde \alpha \tr^{-2} \mathring{\Delta}^{(n-2)} \tilde \Phi 
  - \frac{n-1}{4n} \tilde \alpha \tilde R \tilde \Phi \nonumber\\ \fl \qquad 
  - \mu \tilde \alpha \Omega^{[p(n-1)-n-3]/2} |\tilde \Phi|^{p-1} \tilde \Phi.
  \label{e:scalarwave2}
\end{eqnarray} 

We have double-checked using computer algebra that \eref{e:scalarwave1}--\eref{e:scalarwave2} are equivalent to \eref{e:nlw2} if the coordinate transformation given by \eref{e:hyperboloid} and \eref{e:rofr_} is applied directly.

Equations \eref{e:scalarwave1}--\eref{e:scalarwave2} are perfectly regular at future null infinity $\tr=1$, where $\Omega=0$, provided that $p\geqslant p_\mathrm{conf}$ (or $\mu=0$).
No boundary conditions are needed there because all characteristics point towards the exterior of the domain.

It should be noted that we have written the radial principal part of \eref{e:scalarwave2} in conservative form. 
The finite differencing (section \ref{s:spatialdiscr}) will be applied in precisely this order.
This was found to be essential for the numerical evolutions to be stable.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\section{Numerical methods} 
\label{s:nummeth}

In this section we describe the numerical methods we use in order to solve the NLW \eref{e:scalarwave1}--\eref{e:scalarwave2}.
We begin with the spatial discretisation in section \ref{s:spatialdiscr}.
Next we explain how the equation is integrated forward in time in section \ref{s:timestepping}, and we address how to eliminate high-frequency instabilities.
Finally we provide details on how spatial integrals needed for various diagnostics are computed in section \ref{s:integrals}.
The code has been written in Python using libraries such as \texttt{NumPy} \cite{NumPy} and \texttt{SciPy} \cite{SciPy}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Spatial discretisation}
\label{s:spatialdiscr}

We use a hybrid method for the spatial discretisation, which combines a finite-difference method in the radial direction with a pseudo-spectral method in the angular directions.
The latter has the advantage that it is easier to build in parity conditions by an appropriate choice of expansion functions, as will be explained below.
Furthermore, if we introduce a logically rectangular grid with equidistant grid points in the standard spherical coordinates $\theta$ and $\varphi$ on the two-sphere, the distance between neighbouring $\varphi$-grid points becomes very small near the poles. 
This leads to a severe restriction on the time step due to the Courant-Friedrichs-Lewy (CFL) condition if a finite-difference method is used.
With a pseudo-spectral method, it is straightforward to remove an increasing number of higher (more oscillatory) $\varphi$-modes as the axis is approached (section \ref{s:timestepping}), thus allowing for larger time steps.

We take the spatial dimension to be $n=3$ without symmetries first. 
Higher dimensions with $\mathrm{SO}(n-1)$ symmetry will be treated as a special case.

We introduce equidistant grid points in each dimension,
\begin{eqnarray}
  \tr_i = (i + \half) \htr, \quad\; 
  i=0,1,\ldots, \Ntr - 1, \quad 
  h_{\tr} = 1/(\Ntr - \half),\\
  \theta_j = (j + \half) h_\theta, \quad 
  j=0,1,\ldots, N_\theta - 1, \quad 
  h_\theta = \pi/N_\theta,\\
  \varphi_k = k h_\varphi, \qquad\;\; 
  k = 0, 1, \ldots, N_\varphi - 1, \quad 
  h_\varphi = 2\pi/N_\varphi.
\end{eqnarray}
The radial grid is staggered at the origin, whereas the outermost grid point coincides with \Scri ($\tr=1)$.
The grid in the elevation $\theta$ is staggered about the axis.
The reason for this choice is that there are terms in the wave equation that are formally singular at the origin ($\tr=0$) and on the axis ($\sin\theta=0$), which would be difficult to evaluate if there were grid points at the origin and on the axis.

Fourth-order finite differences are used in order to approximate the radial derivatives. 
In the interior a centred stencil is used.
Setting $u_i := u(\tr_i)$ for a smooth function $u$ and leaving out its angular dependence for simplicity, 
\begin{eqnarray}
  u'_i \approx (u_{i-2} - 8 u_{i-1} + 8 u_{i+1} - u_{i+2})/(12 \htr),\\
  u''_i \approx (-u_{i-2} + 16 u_{i-1} - 30 u_i + 16 u_{i+1} - u_{i+2})/(12 \htr^2)
\end{eqnarray}
for $i=0,1,\ldots,\Ntr-3$, where $\approx$ stands for equality up to a truncation error of the 
order $O(\htr^4)$.
Evaluating the above stencils at $i=0$ and $i=1$ requires values of $u$ at the ghost points 
$\tr_{-1}=-h_{\tr}/2$ and $\tr_{-2}=-3h_{\tr}/2$, which we copy from interior points according to 
\begin{equation}
  \label{e:symmetryorigin}
  u(-\tr, \theta, \varphi) = u(\tr, \pi-\theta, \pi+\varphi),
\end{equation}
satisfied by any smooth function $u$.
We require $N_\varphi$ to be even, which ensures that if there is a grid point at $\varphi$, there is also a grid point at $\pi+\varphi$.

Near the outer boundary at $\tr=1$, one-sided differences are used,
\begin{eqnarray}
  \fl u'_{\Ntr-2} \approx (-u_{\Ntr-5} + 6 u_{\Ntr-4} - 18 u_{\Ntr-3} + 10 u_{\Ntr-2} + 3 u_{\Ntr-1})/(12 \htr),\\
  \fl u'_{\Ntr-1} \approx (3 u_{\Ntr-5} - 16 u_{\Ntr-4} + 36 u_{\Ntr-3} - 48 u_{\Ntr-2} + 25 u_{\Ntr-1} )/(12 \htr),\\
  \fl u''_{\Ntr-2} \approx (u_{\Ntr-6} - 6 u_{\Ntr-5} + 14 u_{\Ntr-4} - 4 u_{\Ntr-3} - 15 u_{\Ntr-2} + 10 u_{\Ntr-1})/(12 \htr^2),\\
  \fl u''_{\Ntr-1} \approx (-10 u_{\Ntr-6} + 61 u_{\Ntr-5} - 156 u_{\Ntr-4} + 214 u_{\Ntr-3} - 154 u_{\Ntr-2} + 45 u_{\Ntr-1})\nonumber\\
  \fl \qquad\qquad /(12 \htr^2),
\end{eqnarray}
the truncation error again being $O(\htr^4)$.

Our pseudo-spectral method is based on Fourier expansions in both $\theta$ and $\varphi$. 
This allows us to employ fast Fourier transform (FFT) techniques \cite{Boyd1978}, which would not be available if we expanded the fields in spherical harmonics.

Leaving out its radial dependence for simplicity, a smooth function $u$ is expanded as
\begin{equation} \label{e:spectralexpansion}
  \fl u(\theta,\varphi) \approx \sum_{l=0}^{N_\theta-1} \left( \cos(l\theta) \sum_{m=0\atop{m\,\mathrm{even}}}^{N_\varphi/2-1} a_{lm} \, \rme^{\rmi m \varphi} +  \sin(l\theta) \sum_{m=1\atop{m\,\mathrm{odd}}}^{N_\varphi/2-1} a_{lm} \, \rme^{\rmi m \varphi} \right).
\end{equation}
Any smooth function $u$ on the two-sphere must obey 
\begin{equation}
  u(-\theta, \varphi) = u(\theta, \pi + \varphi), \qquad
  u(\pi + \theta, \varphi) = u(\pi - \theta, \pi + \varphi),
\end{equation}
and the way we expand the even and odd $m$-modes separately in \eref{e:spectralexpansion} enforces this.
For $u$ to be real, the coefficients $a_{lm}$ in \eref{e:spectralexpansion} must be complex, and we may use 
\begin{equation}
  \Re(a_{lm} \rme^{\rmi m \varphi}) = \Re \, a_{lm} \cos(m\varphi) - \Im \, a_{lm} \sin(m\varphi).
\end{equation}

In order to compute the expansion coefficients $a_{lm}$ from the point values $u_{jk} := u(\theta_j, \varphi_k)$, we first perform a real FFT w.r.t. $\varphi$ using \texttt{scipy.fft.rfft}.
Next, we perform a discrete cosine transform w.r.t. $\theta$ for the even-$m$ modes (\texttt{scipy.fft.dct}) and a discrete sine transform for the odd-$m$ modes (\texttt{scipy.fft.dst}).
The (default) Type II versions of the discrete cosine and sine transforms implemented in \texttt{scipy} are appropriate for our staggered $\theta$ grid.

Derivatives of the expansion can now be computed analytically by simply differentiating the basis functions $\cos(l\theta)$, $\sin(l\theta)$ and $\rme^{\rmi m \varphi}$.
Finally in order to obtain the values of the derivatives at the grid points $(\theta_j, \varphi_k)$, we apply the inverse discrete cosine and sine transforms w.r.t. $\theta$, followed by an inverse real FFT w.r.t. $\varphi$.

In the code the main object is the array of values of the unknowns $\tilde \Phi$ and $\tilde \Pi$ at the grid points $(\tr_i, \theta_j, \varphi_k)$. 
Terms in the evolution equations, especially nonlinear terms, are evaluated and added pointwise.

We remark that a purely spectral (rather than pseudo-spectral collocation) method such as the one used in \cite{Racz2011} cannot be employed in our case because of the nonlinear term in the wave equation we consider.

\paragraph{$n$ dimensions with $\mathrm{SO}(n-1)$ symmetry.}
In this case there is no $\varphi$-dependence and the expansion \eref{e:spectralexpansion} is replaced with
\begin{equation} \label{e:spectralexpansionreduced}
  u(\theta) \approx \sum_{l=0}^{N_\theta-1} a_l \cos(l\theta) 
\end{equation}
with real coefficients $a_l$.
This satisfies the symmetry conditions 
\begin{equation}
  u(-\theta) = u(\theta), \qquad
  u(\pi + \theta) = u(\pi - \theta).
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Time stepping and filtering}
\label{s:timestepping}

We employ the method of lines, whereby the evolution equations \eref{e:scalarwave1}--\eref{e:scalarwave2} are first discretised in space as described in the previous subsection, leading to a system of ordinary differential equations (ODEs), one for each grid point.
These ODEs are then integrated forward in time using the standard fourth-order Runge-Kutta method.

In order to obtain a stable finite-difference method, fifth-order Kreiss-Oliger dissipation \cite{Kreiss1973} is applied in the radial direction, whereby the term 
\begin{eqnarray}
  \fl (Q u)_i = \frac{\varepsilon}{64 \htr} (u_{i-3} - 6 u_{i-2} + 15 u_{i-1} - 20 u_i + 15 u_{i+1} - 6 u_{i+2} + u_{i+3}) \nonumber \\ 
  \fl \qquad \; = \frac{\varepsilon}{64} \htr^5 \left(\frac{\rmd^6 u}{\rmd\tilde r^6}\right)_i + \Or(\htr^7) \label{e:diss} 
\end{eqnarray}
for $i=0,1,\ldots,\Ntr-4$ is added to the right-hand side of the discretised evolution equations for both $\tilde\Phi$ and $\tilde\Pi$.
Ghost points near the origin are filled according to \eref{e:symmetryorigin}.
No dissipation is added at the outermost three radial grid points.
We typically take the parameter $\varepsilon = 0.2$.
It should be noted that the artificial dissipation term \eref{e:diss} is of higher order in $h_{\tr}$ than the truncation error of the finite-difference method.

In a pseudo-spectral method, nonlinear terms such as the one in our wave equation can cause high frequencies to be represented incorrectly due to aliasing \cite{Boyd2000}.
We address this by applying spectral filtering according to the 2/3 rule, whereby the top third of all $\theta$-modes are removed at each substep of the Runge-Kutta algorithm.

In order to combat the clustering of grid points near the poles of the two-sphere, we filter out an increasing number of the highest Fourier modes w.r.t. $\varphi$ as $\theta$ approaches $0$ or $\pi$.
Specifically, we remove the proportion $1 - \sin\theta$ of all $\varphi$-Fourier modes (beginning at the highest frequencies) \cite{Fornberg1998}.

The time step is restricted by the smallest distance between neighbouring grid points, and this occurs between neighbouring $\theta$-grid points at the smallest radius:
$\Delta x_{\min} = \tr_0 h_\theta$, where $\tr_0 = \htr/2$.
The time step is then taken to be $\Delta \tilde t = \lambda \Delta x_{\min}$,
where $0<\lambda<1$ according to the CFL condition.
We typically choose $\lambda = 0.8$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Spatial integration}
\label{s:integrals}

For expressions such as the energy and flux (section \ref{s:energy}) we will need to compute integrals on a $\tilde t=\const$ slice and on its spherical boundary.
The radial integration is performed using Simpson's rule (taking $\Ntr$ to be even), 
\begin{eqnarray}
  \fl \int_{0}^1 u(\tr) \rmd \tr \approx \frac{\htr}{3} \left(\frac{27}{8} u_0 + \frac{17}{8} u_1 + 4 u_2 + 2 u_3 + 4 u_4 + 2 u_5 + \ldots 
  \right. \nonumber\\ \left. + 4 u_{\Ntr-4} + 2 u_{\Ntr-3} + 4 u_{\Ntr-2} + u_{\Ntr-1}\right),
\end{eqnarray}
where the error is of the same order as the truncation error of the finite-difference scheme, $\Or(\htr^4)$.
The modified coefficients of $u_0$ and $u_1$ are due to the fact that the grid is staggered at the origin, with a first grid point at $\tr_0 = \htr/2$, and $u$ is assumed to be an even function of $\tr$ here.

The spectral expansion on the right-hand side of \eref{e:spectralexpansion} can easily be integrated exactly:
\begin{equation}
   \int_{S^{2}} u \, dS^{(2)} =
   \int_0^{2\pi} \int_0^\pi u(\theta,\varphi) \, \sin\theta \, \rmd \theta \, \rmd \varphi \approx 2\pi \sum_{l=0\atop{l\,\mathrm{even}}}^{N_\theta - 1}\frac{2a_{l0}}{1-l^2}.
\end{equation} 

\paragraph{$n$ dimensions with $\mathrm{SO}(n-1)$ symmetry.}
In this case \eref{e:spectralexpansionreduced} integrates to
\begin{equation} \fl
  \int_{S^{n-1}} u \, dS^{(n-1)} = \int_{S^{n-2}} \int_0^\pi u(\theta) \sin^{n-2}\theta \, \rmd\theta \, dS^{(n-2)} \approx A^{(n-2)} \sum_{l=0}^{N_\theta-1} a_l \, I_{n-2, l},
\end{equation} 
where 
\begin{equation} \label{e:areaS}
  A^{(n-2)} = \frac{2\pi^{(n-1)/2}}{\Gamma(\tfrac{n-1}{2})}
\end{equation}
is the area of $S^{n-2}$, and the integrals 
\begin{equation}
  I_{n-2, l} := \int_0^\pi \sin^{n-2} \theta \, \cos(l \theta) \, \rmd\theta
\end{equation}
are computed numerically to high precision using \texttt{scipy.integrate.quad} in the initialisation phase of the code.

