\appendix

\section{Exact solutions, initial data}
\label{s:exact}

Here we work out exact solutions to the linear wave equation, which are used to test the convergence of the code in section \ref{s:convtest}.
We first assume dimension $n=3$ without symmetries in \ref{s:exactn3}; higher dimensions will be treated in \ref{s:exactn5}.
The solutions are constructed in standard spherical polar coordinates first;
finally in \ref{s:exacttrafo} they are transformed to hyperboloidal coordinates.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{$n=3$ without symmetries} \label{s:exactn3}

The solution to the linear wave equation 
\begin{equation} 
  \Box \Phi = 0
\end{equation}
in standard spherical polar coordinates can be decomposed into spherical harmonics,
\begin{equation} \label{e:spherharmexpansion}
  \Phi = \sum_{l=0}^\infty \sum_{m=-l}^l\Phi_{lm} (t, r) \, Y_{l m}(\theta, \varphi).
\end{equation}
The spherical harmonics are eigenfunctions of the Laplace-Beltrami operator on $S^2$,
\begin{equation}
  \mathring{\Delta}^{(2)} \, Y_{l m}(\theta, \varphi) = -l(l+1) Y_{l m}(\theta, \varphi).
\end{equation}
They have the form
\begin{equation}
  Y_{l m}(\theta,\varphi) = N_{lm} P_{l m} (\theta) \, \rme^{\rmi m \varphi},
\end{equation}
where $P_{l m} (\theta)$ are the associated Legendre functions and $N_{lm}$ are normalisation constants chosen such that 
\begin{equation}
  \fl \int_{S^{2}} Y_{lm} Y_{l'm'} dS^{(2)} = 
  \int_0^{2\pi} \int_0^\pi Y_{lm}(\theta,\varphi) Y_{l'm'}^*(\theta,\varphi) \sin\theta \,\rmd\theta \, \rmd\varphi = \delta_{ll'} \delta_{mm'}.
\end{equation}
The (complex) spherical harmonics are implemented in 
\texttt{scipy.special.sph\_harm\_y}.
A suitable real basis of spherical harmonics is obtained by taking 
\begin{equation}
  \left\{
  \begin{array}{ll}
    \sqrt{2} (-1)^m \Im Y_{l|m|}, & m < 0, \smallskip\\
    Y_{l0}, & m=0, \smallskip\\ 
    \sqrt{2} (-1)^m \Re Y_{lm}, & m > 0.
  \end{array}
  \right.
\end{equation}

The wave equation implies that the radial functions $\Phi_{lm}(t,r)$ in \eref {e:spherharmexpansion} obey an equation of Euler-Poisson-Darboux type,
\begin{equation}  \label{e:epd3}
  -\Phi_{lm,tt} + \Phi_{lm,rr} + \frac{2}{r} \Phi_{lm,r} - \frac{l(l+1)}{r^2} \Phi_{lm} = 0.
\end{equation}
Since this equation does not depend on $m$ explicitly, we leave out the index $m$ on $\Phi_{lm}$ in the following.
Solutions have the form
\begin{equation}
  \Phi_l^\pm(t, r) = \sum_{k=0}^l c_k \, r^{-k-1} F^{(l-k)}(r \pm t),
\end{equation}
where $F$ is an arbitrary mode function, and $-$ refers to an outgoing and $+$ to an ingoing solution.
The coefficients $c_k$ can be determined by recursion.
We provide explicit solutions for $l=0,1,2$:
\begin{eqnarray}
  \label{e:Phi_rad0_n3}
  \Phi_0^\pm(t,r) &=& r^{-1} F(r\pm t), \\
  \Phi_1^\pm(t,r) &=& r^{-1} F'(r\pm t) - r^{-2} F(r\pm t),\\
  \Phi_2^\pm(t,r) &=& r^{-1} F''(r\pm t) - 3 r^{-2} F'(r\pm t) + 3 r^{-3} F(r\pm t).
  \label{e:Phi_rad2_n3}
\end{eqnarray}
We observe that $\Phi_l^- = \Or(r^{-1})$ as \Scri is approached ($r\to\infty$, $r-t$ finite).

If we take the mode function $F$ to be odd and form the linear combination $\Phi_l^+ + \Phi_l^-$, the result turns out to be regular at the origin $r = 0$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{$n\geqslant 3$ with $\mathrm{SO}(n-1)$ symmetry}
\label{s:exactn5}

In this case we expand
\begin{equation}
  \Phi = \sum_{l=0}^\infty \Phi_{l} (t, r) \, Y_l(\theta),
\end{equation}
where the real spherical harmonics $Y_l(\theta)$ are eigenfunctions of the Laplace-Beltrami operator on $S^{(n-1)}$,
\begin{equation}
  \mathring{\Delta}^{(n-1)} \, Y_l(\theta) = l(2-n-l) Y_l(\theta).
\end{equation}
We normalise them such that
\begin{equation}
  \int_{S^{n-1}} Y_l Y_{l'} dS^{(n-1)} = 
  A^{(n-2)} \int_0^\pi Y_l(\theta) Y_{l'}(\theta) \sin^{n-2}\theta \,\rmd\theta = \delta_{ll'},
\end{equation}
where the area $A^{(n-2)}$ of $S^{n-2}$ is given in \eref{e:areaS}.
The mode equation now reads
\begin{equation}
  -\Phi_{l,tt} + \Phi_{l,rr} + \frac{n-1}{r} \Phi_{l,r} + \frac{l(2-n-l)}{r^2} \Phi_l = 0.
\end{equation}
Note that for $n=3$ we recover \eref{e:epd3}.

In the following we state explicit solutions for $n=5$.
The first three spherical harmonics are
\begin{equation} \fl
  Y_0(\theta) = \frac{\sqrt{3}}{2\sqrt{2}\pi}, \quad
  Y_1(\theta) = \frac{\sqrt{15}}{2\sqrt{2}\pi} \cos\theta, \quad 
  Y_2(\theta) = \frac{\sqrt{21}}{8\pi} (5\cos^2\theta - 1)
\end{equation}
and the corresponding radial solutions are 
\begin{eqnarray}
  \label{e:Phi_rad0_n5}
  \fl \Phi_0^\pm( t, r) &=& r^{-2} F'(r\pm  t) - r^{-3} F(r\pm  t),  \\
  \fl \Phi_1^\pm( t, r) &=& r^{-2} F''(r\pm  t) - 3 r^{-3} F'(r\pm  t) + 3 r^{-4} F(r\pm  t), \\
  \label{e:Phi_rad2_n5}
  \fl \Phi_2^\pm( t, r) &=& r^{-2} F'''(r\pm  t) - 6 r^{-3} F''(r\pm  t) + 15 r^{-4} F'(r\pm  t) -15 r^{-5} F(r\pm  t).
\end{eqnarray}
We observe that now $\Phi_l^- = \Or(r^{-2})$ as \Scri is approached.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Transformation to hyperboloidal coordinates}
\label{s:exacttrafo}

From the conformal coordinates $\tilde t, \tr$ used in the code, we first compute the physical coordinates  
\begin{equation}
  r = \frac{2n\tr}{C(1-\tr^2)}, \quad t = \tilde t + \sqrt{\frac{n^2}{C^2} + r^2}
\end{equation}
so we can compute $\Phi(t,r)$ as constructed above.
We then form 
\begin{equation} \label{e:PhifromPhi_}
  \tilde \Phi = \Omega^{(1-n)/2} \Phi,
\end{equation}
where the conformal factor is given by \ref{e:Omega}.

The multiplication by a negative power of $\Omega$ in \eref{e:PhifromPhi_} may seem problematic at \Scri ($r=1$), where $\Omega=0$. 
However, from the explicit solutions given in \ref{s:exactn3} and \ref{s:exactn5}, we see that $\Phi = \Or(r^{(1-n)/2})$,
and $\Omega = \tr/r = \Or(r^{-1})$, so 
$\tilde \Phi$ in \eref{e:PhifromPhi_} is in fact regular at \Scri.

For the initial data we also need to compute the field $\tilde \Pi$.
By its definition, we have 
\begin{equation}
  \fl \tilde \Pi = \tilde \alpha^{-1} (\tilde \Phi_{,\tilde t} - \tilde \beta^{\tr}\Phi_{,\tr})
    = \tilde \alpha^{-1} \Omega^{(1-n)/2} \left[\Phi_{,\tilde t} - \tilde \beta^{\tr} \left(\Phi_{,\tr} + \frac{1-n}{2} (\ln\Omega)_{,\tr} \Phi \right)\right]
\end{equation}
with $\Omega$, $\tilde \beta^r$ and $\tilde \alpha$ given in \eref{e:Omega}--\eref{e:lapse}.
Finally we need to express the derivatives of $\Phi$ in terms of derivatives w.r.t. $r$ and $t$:
\begin{equation}
  \Phi_{,\tr} = \frac{\rmd r}{\rmd \tr} \Phi_{,r} + \frac{\partial t}{\partial \tr} \Phi_{,t}, \qquad \Phi_{,\tilde t} = \Phi_{,t},
\end{equation}
where
\begin{equation}
   \frac{\rmd r}{\rmd \tr} = \frac{2n(1+\tr^2)}{C(1-\tr^2)^2}, \qquad
   \frac{\partial t}{\partial \tr} = \frac{4n\tr}{C(1-\tr^2)^2}.
\end{equation}
The quantities $\Phi_{,r}$ and $\Phi_{,t}$ can be computed directly from the radial solutions \eref{e:Phi_rad0_n3}--\eref{e:Phi_rad2_n3} or \eref{e:Phi_rad0_n5}--\eref{e:Phi_rad2_n5}.

