    \setlength{\abovecaptionskip}{-0.1cm}  
    \setlength{\belowcaptionskip}{-0.1cm}   
\centerline{\includegraphics[width=0.9\columnwidth]{fig_convex_hull.pdf}}
    \caption{Illustration of Convex Hull Approximation for the LDES Model.}    \label{fig:convex_hull}
\end{figure}




