\subsection{Proof of Equivalence between Long-Term Trajectory Tracking and Explicit Time-Coupling Constraints} \label{appendix1}

On one hand, since the reference $\hat{h}_{t}$ satisfies the time-coupling constraints~\eqref{E-power-H-1}, enforcing a quadratic tracking term with a sufficiently large penalty $\theta$ implicitly ensures compliance with these constraints. On the other hand, through partial Lagrangian relaxation of constraint~\eqref{E-balance-H}, an additional penalty term emerges in the objective. In online dispatch, we can substitute SoC reference into the future decisions, which yields:
\begin{align}
\varphi(h_T-{H}_{T})^2&=\varphi(h_{t-1}+\sum_{\tau=t}^{T}\sum_{m\in\mathcal{M}}(\hat{\lambda}_{m\text{,}\tau}^{-}H_{m}^{-}-\hat{\lambda}_{m\text{,}\tau}^{+}H_{m}^{+})-{H}_{T})^2\notag\\
&=\varphi(h_t-\hat{h}_t)^2
\end{align}
where $\varphi$ is the Lagrange multiplier. Hence, we finish the proof.


\subsection{Proof of Theorem 1} \label{appendix2}

The dynamic regret is defined as the cumulative objective difference between the decisions obtained from the proposed method and the oracle optimal decisions, as illustrated in~\eqref{regret_def}. To rigorously analyze the regret, we decompose it into four components in~\eqref{regret_decomposition}: (1) convex hull approximation error, (2) OCO regret, (3) tracking penalty error, and (4) optimality gap.
\begin{subequations}
\begin{align}
&   \text{Regret}= \sum\nolimits_{t=1}^T[\hat{f}_t(x_t\text{,}y_t)-\hat{f}_t(x_t^{\star}\text{,}y_t^{\star})]\label{regret_def}  \\
& \text{Regret}=\underbrace{\sum\nolimits_{t=1}^T[\hat{f}_t(x_t\text{,}y_t)-\tilde{f}_t(x_t\text{,}y_t)+\tilde{f}_t(x_t^{\star}\text{,}y_t^{\star})-\hat{f}_t(x_t^{\star}\text{,}y_t^{\star})]}_{\text{Convex Hull Approximation Error}}\notag\\
&+\underbrace{\sum\nolimits_{t=1}^T[f(x_t\text{,}y_t)-f(x_t^\dagger\text{,}y_t^\dagger)]}_{\text{OCO Regret}}+\underbrace{\sum\nolimits_{t=1}^T\theta[\|h_t^\dagger-\hat{h}_t\|^2-\|h_t-\hat{h}_t\|^2]}_{\text{Tracking Penalty Error}}\notag\\
&+\underbrace{\sum\nolimits_{t=1}^T[\tilde{f}_t(x_t^\dagger\text{,}y_t^\dagger)-\tilde{f}_t(x_t^{\star}\text{,}y_t^{\star})]}_{\text{Optimality Gap}}\label{regret_decomposition}
\end{align}    
\end{subequations}
where $\hat{f}_t$ and $\tilde{f}_t$ denote the objective function of OED~\eqref{eq:OED} and convex reformulation~\eqref{eq:reformulation}, respectively. $(x_t^\star,y_t^\star)$ and $(x_t^\dagger,y_t^\dagger)$ denote the optimal solution to OED~\eqref{eq:OED} and TED~\eqref{eq:TED}, respectively. $h_t^\dagger$ denotes the optimal LDES SoC of TED.



\textbf{(1) Convex Hull Approximation Error.} Given a twice differentiable nonconvex power-hydrogen function with second derivative bounded by Z, from the convergence property of the Hausdorff distance between the nonconvex set and its convex hull approximation~\cite{chen2018convex}, we have:
\begin{align}
\text{Regret}^{\text{Approx}}\leq \dfrac{2c^\text{h}Z(\overline{P}-\underline{P})^2T}{(M-1)^2}=\mathcal{O}(\dfrac{T}{M^2}) 
\end{align}

\textbf{(2) OCO Regret.} From $f_{t}$ is convex and~\eqref{condition}, we have:
\begin{align}\label{reg1}
&f_t(\boldsymbol{x}_{i,t}) - f_t(\boldsymbol{x}_t^{\dagger}) \leq \left\langle \partial f_t(\boldsymbol{x}_{i,t}),\ \boldsymbol{x}_{i,t} - \boldsymbol{x}_t^{\dagger} \right\rangle \\
&\leq J \parallel \boldsymbol{x}_{i,t} - \boldsymbol{x}_{i,t+1} \parallel + \left\langle \partial f_t(\boldsymbol{x}_{i,t}),\ \boldsymbol{x}_{i,t+1} - \boldsymbol{x}_t^{\dagger} \right\rangle\notag \\
&\leq \frac{J^{2} \alpha_{i,t}}{2} + \frac{1}{2 \alpha_{i,t}} \parallel \boldsymbol{x}_{i,t} - \boldsymbol{x}_{i,t+1} \parallel^{2} + \left\langle \partial f_t(\boldsymbol{x}_{i,t}),\ \boldsymbol{x}_{i,t+1} - \boldsymbol{x}_t^{\dagger} \right\rangle\notag
\end{align}

For the rightmost term of~\eqref{reg1}, we have:
\begin{align}\label{reg2}
&\left\langle\partial f_t(\boldsymbol{x}_{i,t}),\ \boldsymbol{x}_{i,t+1}-\boldsymbol{x}_t^{\dagger} \right\rangle 
\\&=\left\langle\beta_{i,t+1}(\partial[g_t(\boldsymbol{x}_{i,t+1})]_{+})^{T}Q_{i,t},\ \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t+1}\right\rangle \notag
\\&+\left\langle\partial f_t(\boldsymbol{x}_{i,t})+\beta_{i,t+1}(\partial[g_t(\boldsymbol{x}_{i,t+1})]_{+})^{T}Q_{i,t},\ \boldsymbol{x}_{i,t+1}-\boldsymbol{x}_t^{\dagger} \right\rangle\notag
\end{align}

Since $g_{t}$ is a convex function, it is trivial to show that $[g_t]_+$ is also convex; hence the first term of~\eqref{reg2} can be relaxed:
\begin{align}\label{reg3}
&\left\langle\beta_{t+1}(\partial[g_t(\boldsymbol{x}_{i,t+1})]_{+})^{T}Q_{i,t},\ \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t+1}\right\rangle\\
&\leq\beta_{t+1}\left\langle Q_{i,t},\ [g_t(\boldsymbol{x}_t^{\dagger} )]_+\right\rangle-\beta_{i,t+1}\left\langle Q_i(t),\ [g_t(\boldsymbol{x}_{i,t+1})]_+\right\rangle\notag
\end{align}

From Lemma 1 in~\cite{yi2020distributed}, we have:
\begin{align}\label{reg4}
&\left\langle\partial f_t(\boldsymbol{x}_{i,t})+\beta_{i,t+1}(\partial[g_t(\boldsymbol{x}_{i,t+1})]_{+})^{T}Q_{i,t},\ \boldsymbol{x}_{i,t+1}-\boldsymbol{x}_t^{\dagger} \right\rangle\\
&\leq\frac1{\alpha_{i,t}}(\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t}\parallel^2-\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t+1}\parallel^2-\parallel \boldsymbol{x}_{i,t+1}-\boldsymbol{x}_{i,t}\parallel^2)\notag
\end{align}

Combining~\eqref{eq:final_decision},~\eqref{reg1}-\eqref{reg4}, we have:
\begin{align}\label{reg5}
&\ell_t(\boldsymbol{x}_{i,t}) - \ell_t(\boldsymbol{x}_t^{\dagger} ) \leq{J^2\alpha_{i,t}}/2+\beta_{t+1}\left\langle Q_i(t),\ [g_t(\boldsymbol{x}_t^{\dagger} )]_+\right\rangle
\\&(\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t}\parallel^2-\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t+1}\parallel^2)/\alpha_{i,t}\notag
\end{align}


Since the second term of~\eqref{reg5} is non-negative, we have:
\begin{align}\label{reg6}
&\sum\nolimits_{t=1}^{T} (\ell_t(\boldsymbol{x}_{i,t}) - \ell_t(\boldsymbol{x}_t^{\dagger} ))\leq\sum\nolimits_{t=1}^T{J^2\alpha_{i,t}}/2\\
&+\sum\nolimits_{t=1}^T(\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t}\parallel^2-\parallel \boldsymbol{x}_t^{\dagger} -\boldsymbol{x}_{i,t+1}\parallel^2)/{\alpha_{i,t}}\notag
\end{align}

For the first term of~\eqref{reg6}, we have:
\begin{equation}\label{reg7}
\begin{aligned}
\sum_{t=1}^T\frac{J^2\alpha_{i,t}}2\leq\frac{2^{i-1}J^2}2\sum_{t=1}^T\frac1{t^{c}}\leq\frac{2^{i-1}J^2}{2(1-c)}T^{1-c}
\end{aligned}
\end{equation}

By leveraging~\eqref{condition} and parameter setting~\eqref{parameter}, we have:
\begin{align}\label{reg8}
&\sum_{t=1}^{T} \frac{t^c}{\alpha_0 2^{i-1}} \left( \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t}\|^2 - \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t+1}\|^2 \right) \\
&= \frac{1}{\alpha_0 2^{i-1}}\sum_{t=1}^{T} \big( t^c \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t}\|^2 - (t + 1)^c \|\boldsymbol{x}_{t+1}^{\dagger} - \boldsymbol{x}_{i,t+1}\|^2 \notag\\
&+  (t + 1)^c \|\boldsymbol{x}_{t+1}^{\dagger} - \boldsymbol{x}_{i,t+1}\|^2 - t^c \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t+1}\|^2\notag  \\
&+ t^c \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t+1}\|^2 - t^c \|\boldsymbol{x}_t^{\dagger}  - \boldsymbol{x}_{i,t}\|^2 \big)\notag\\
&\le \frac{1}{\alpha_0 2^{i-1}} \|\boldsymbol{x}_{1}^{\dagger} - \boldsymbol{x}_{i,1}\|^2 + \frac{1}{\alpha_0 2^{i-1}} \sum_{t=1}^{T} \left( (t + 1)^c - t^c \right) (d(\mathcal{X}))^2 \notag\\
&+ \frac{2}{\alpha_0 2^{i-1}} \sum_{t=1}^{T} t^c d(\mathcal{X}) \|\boldsymbol{x}_{t+1}^{\dagger} - \boldsymbol{x}_t^{\dagger} \|\notag \\
&\le \frac{1}{\alpha_0 2^{i-1}} \left( 1 + (T + 1)^c - 1 \right) (d(\mathcal{X}))^2 + \frac{2T^c d(\mathcal{X}) P_x}{\alpha_0 2^{i-1}}\notag \\
&\le \frac{2}{\alpha_0 2^{i-1}} (d(\mathcal{X}))^2 T^c \left( 1 + {P_x}/{d(\mathcal{X})} \right)\notag
\end{align}
where $d(\mathcal{X})$ denotes the diameter of the feasible set.

Let $i_0=\left[\frac12\log_2(1+{P_x}/{d(\mathcal{X})})\right]+1\in[N]$, we have:
\begin{equation}\label{reg9}
2^{i_0-1}\leq\sqrt{1+{P_x}/{d(\mathcal{X})}}\leq2^{i_0}
\end{equation}

Combining~\eqref{reg7}-\eqref{reg9} yields:
\begin{align}\label{reg10}
&\sum_{t=1}^{T} (\ell_t(\boldsymbol{x}_{i_0, t}) - \ell_t(\boldsymbol{x}_t^{\dagger} )) \leq \frac{4}{\alpha_0} (d(\mathcal{X}))^2 T^c \left( 1 + \frac{P_x}{d(\mathcal{X})} \right)^{1-\kappa}\notag\\
&+ \frac{J^2 \alpha_0}{2 (1 - c)} T^{1-c} \left( 1 + \frac{P_x}{d(\mathcal{X})} \right)^{\kappa}
\end{align}
Applying Lemma 1 in reference~\cite{zhang2018adaptive} to~\eqref{eq:final_decision} yields:
\begin{equation}\label{reg11}
\begin{aligned}
\sum_{t=1}^T\ell_t(\boldsymbol{x}_{t})-\min_{i\in[N]}\{\sum_{t=1}^T\ell_t(\boldsymbol{x}_{i,t})+\frac1\gamma\ln\frac1{\rho_{i,1}}\}\leq\frac{\gamma(Jd(\mathcal{X}))^2T}2
\end{aligned}
\end{equation}
\begin{equation}\label{reg12}
\begin{aligned}
\sum_{t=1}^T(\ell_t(\boldsymbol{x}_{t})-\ell_t(\boldsymbol{x}_{i_0,t}))\leq\frac{\gamma_0 (J d(\mathcal{X}))^2 T^{1 - c}}{2} + \frac{1}{\gamma_0} T^c \ln \frac{1}{\rho_{i_0, 1}}
\end{aligned}
\end{equation}
From $\rho_{i,1}=(N+1)/[i(i+1)N]$, we have:
\begin{equation}\label{reg13}
\begin{aligned}
\ln\frac1{\rho_{i_0,1}}\leq\ln(i_0(i_0+1))\leq2\ln(i_0+1)\leq2\ln(\left\lfloor\kappa\log_2(1+\frac{P_x}{d(\mathcal{X})})\right\rfloor)
\end{aligned}
\end{equation}
From~\eqref{eq:final_decision} and that $f_{t}$ is convex, we have
\begin{equation}\label{reg14}
\begin{aligned}
f_t(\boldsymbol{x}_{t})-f_t(\boldsymbol{x}_t^{\dagger} )\leq \ell_t(\boldsymbol{x}_{t})-\ell_t(\boldsymbol{x}_t^{\dagger} )
\end{aligned}
\end{equation}
Combining~\eqref{reg10}-\eqref{reg14} yields:
\begin{equation}\label{reg15}
\begin{aligned}
&\text{Regret}\leq \frac{4}{\alpha_0} (d(\mathcal{X}))^2 T^c \left( 1 + \frac{P_x}{d(\mathcal{X})} \right)^{1 - \kappa}+\frac{\gamma_0 (J d(\mathcal{X}))^2 T^{1 - c}}{2}\\
 &+\frac{J^2 \alpha_0}{2(1 - c)} T^{1 - c} \left( 1 + \frac{P_x}{d(\mathcal{X})} \right)^{\kappa}+\frac{2}{\gamma_0} T^c \ln ([\kappa \log_2 \left( 1 + \frac{P_x}{d(\mathcal{X})} \right)])\\
\end{aligned}
\end{equation}

Hence, we have the regret bound of OCO in~\eqref{OCObound}.
\begin{align}\label{OCObound}
\text{Regret}^{\text{OCO}}=\mathcal{O}(T^c (1 + P_x)^{1 - \kappa} + T^{1 - c} (1 + P_x)^{\kappa})    
\end{align}



\textbf{(3) Tracking Penalty Error.} From the KKT condition of TED, we have~\eqref{KKT}, where $\varphi^\dagger$ denotes the Lagrange multiplier of TED. Since the second term of tracking penalty error is non-positive, we have~\eqref{penalty_error}. 
\begin{subequations}
\begin{align}
&\nabla_{h_t}\tilde{f}_t(x_t\text{,}y_t)+2\theta(h_t^\dagger-\hat{h}_t)+\varphi^\dagger=0\label{KKT}\\
&\text{Regret}^{\text{Penalty}}\leq\sum\nolimits_{t=1}^T\theta\|h_t^\dagger-\hat{h}_t\|^2=\mathcal{O}(\theta\dfrac{T}{{\theta^2}})=\mathcal{O}(\dfrac{T}{{\theta}})\label{penalty_error}
\end{align}    
\end{subequations}

\textbf{(4) Optimality Gap.} Due to the Lipschitz continuity of $\tilde{f}_t$, we have~\eqref{L_f}. From the power balance constraints~\eqref{powerbalance-1} and SoC dynamics~\eqref{E-power-H-1}, the relationship between \(h_t\) and \((x_t\text{,} y_t)\) is affine. Thus, we have~\eqref{L_H}. Then, by applying the triangle inequality, we have~\eqref{triangle_inequality}.
\begin{subequations}
\begin{align}
&\tilde{f}_t(x_t^\dagger\text{,}y_t^\dagger)-\tilde{f}_t(x_t^{\star}\text{,}y_t^{\star})\leq\Lambda_f\|(x_t^\dagger\text{,}y_t^\dagger)-(x_t^{\star}\text{,}y_t^{\star})\|\label{L_f}\\
& \|(x_t^\dagger,y_t^\dagger)-(x_t^\star,y_t^\star)\| \leq \Lambda_h \|h_t^\dagger - {h}_t^\star\|\label{L_H}\\
&\|h_t^\dagger - {h}_t^\star\|\leq\|h_t^\dagger - \hat{h}_t\|+\|\hat{h}_t - \tilde{h}_t\|+\|\tilde{h}_t - {h}_t^\star\| \label{triangle_inequality}
\end{align}
\end{subequations}
where $\Lambda_f$ and $\Lambda_h$ denote the Lipschitz constants of $\tilde{f}_t$ and the affine mapping from decision variables to LDES SoC.

From~\eqref{eq:mse_kernel}, we have the best bandwidth: $\sigma^\star=\mathcal{O}({S}^{-1/(4+\iota)})$. By substituting it into~\eqref{eq:mse_kernel}, we can obtain the optimal MSE in~\eqref{optimal_MSE}. Thus, we have the tracking optimality gap in~\eqref{optimality_gap}.
\begin{subequations}
\begin{align}
& \text{MSE}^\star=\mathbb{E}\|h_t^\dagger-\hat{h}_t\|^2=\mathcal{O}({S}^{-4/(4+\iota)})\label{optimal_MSE} \\
&\text{Regret}^{\text{Opt}}=\mathcal{O}({T}/{{S}^{2/(4+\iota)}})+\mathcal{O}({T}/{\theta})+\mathcal{O}({T}/{M^2}) \label{optimality_gap}
\end{align}    
\end{subequations}

By substituting the parameter settings in~\eqref{parameter} into the overall regret expression given by~\eqref{overall_regret}, we have finished the proof.
\begin{align}\label{overall_regret}
\text{Regret}&=\mathcal{O}(T^c (1 + P_x)^{1 - \kappa} + T^{1 - c} (1 + P_x)^{\kappa})\\&+\mathcal{O}({T}/{{S}^{2/(4+\iota)}})+\mathcal{O}({T}/{\theta})+\mathcal{O}({T}/{M^2})  \notag 
\end{align}

