\subsection{Proof of Correctness}
\noindent We first note a few key lemmas which are useful in proving Theorem~\ref{theorem:Newinstance}. 
For any iteration $\ite\geq 1$ and $j\in\{0,1,2\}$, 
let $E_j(k):=\{e\in E:\labk(e)=j\}$.
Recall that $\labk(e)$ denotes the label of $e$ at the start of iteration $\ite$;
where we initially define $\labone(e)=1$ if $e\in\fout$, and $\labone(e)=0$ if $e\in E\setminus E(\fout)$.

\begin{lemma}\label{propositionCycle2}
The following holds for each iteration $\ite\geq 1$ and $g\in D$.
\begin{enumerate}[label=(\alph*),topsep=0.2ex]
\item $E_1(k)$ is either the edge-set of a simple cycle $C^{(k)}$ in $G$, or the empty set.\label{pr1}
\item Consider the induced graph $G[C^{(k)}]$ on the vertex-set of $C^{(k)}$. Then $E_0(k)$ are precisely the edges of $G[C^{(k)}]$ that do not lie on the cycle $C^{(k)}$, and $E_2(k)$ are precisely the edges of $G$ that are not contained in $G[C^{(k)}]$.\label{pr2}
\item The demand edges in $\W_g^{(k)}$ form a walk between the end-points of $g$. Furthermore, there is at most one bad demand edge $h\in \W_g^{(k)}$.
If such $h$ exists, then both of its end-points lie on the cycle $C^{(k)}$.\label{pr3}
\end{enumerate}
\end{lemma}
\begin{proof}
The proof is by induction on $k$. 
The result clearly holds when $k=1$.
Suppose that $k\geq 2$. By the induction hypothesis, the result holds for $k-1$. We consider three cases.\\

\noindent \textbf{Case 1:} $E_1(k-1)=\emptyset$. 

By \ref{pr2}, it follows that $\labkminus(e)=2$ for each $e\in E$; thus, the algorithm reaches its termination-condition at the start of iteration $(k-1)$ (in particular there is no iteration $\ite$).\\
%thus, no face of $G$ satisfies the conditions of the while-loop after iteration $k-1$, and the algorithm terminates after iteration $(k-1)$.\\  

\noindent \textbf{Case 2:} $E_1(k-1)\neq\emptyset$ and $G[C^{(k-1)}]=C^{(k-1)}$. 

Then the cycle $C^{(k-1)}$ is a face of $G$. By \ref{pr2}, it follows that $\labkminus(e)=2$ for all edges $e\in E\setminus E_1(k-1)$.
%Thus $C^{(k-1)}$ is the face processed in iteration $k$. 
Thus $C^{(k-1)}$ is the (unbounded) face $f$ of $G$ processed in iteration $k-1$.
%Since $\labkminus(e)=1$ for each $e\in C^{(k-1)}$, then $\labk(e)=2$ for each $e\in C^{(k-1)}$, and hence $\labk(e)=2$ for each $e\in E$. 
Since $\labk =\labkminus +\bon_f$ (see \eqref{updateflowcapacityandlabel}), it follows that $\labk(e)=2$ for each $e\in E$.
This proves \ref{pr1} and \ref{pr2}. 
We now show \ref{pr3}. 
By the induction hypothesis, (i) there is at most one bad demand edge $h\in\Wkminus_g$; and
(ii) $\Wkminus_g$ is the edge-set of a walk between the endpoints of $g$.
%If such an edge does not exist, then $\W_g^{(k-1)}=\W_g^{(k)}$ since $\Dp_1$ and $\Dp_2$ (defined on lines \ref{definingDP1} and \ref{definingDP2} of \ref{algorithmFaceAug}) only contain edges whose endpoints are not adjacent in $G$, and \ref{pr3} is trivially satisfied in this case. 
If such a bad demand edge $h$ does not exist, then $\W_g^{(k-1)}=\W_g^{(k)}$ (see \eqref{updateWg}), and therefore \ref{pr3} is trivially satisfied in this case.
Suppose on the other hand that there is a bad demand edge $h\in\Wkminus_g$.
By \ref{pr3}, 
both end-points $s,t$ of $h$ lie on $C^{(k-1)}$; 
therefore $h \in \Dpminus_2$.
%\david{(should we place the definition of $\Dp_1$ and $\Dp_2$ on an equation on the previous section?)}
At the end of iteration $k-1$, 
edge $h$ is replaced by a sequence of demand edges $\Dpminus_h$ which form a simple $s-t$ path along the edges of $C^{(k-1)}$ (see \eqref{2ndD2option} and \eqref{1stD2option}).
Thus, (i) $\Wk_g=(\Wkminus_g-h)\cup \Dpminus_h$ only contains \emph{good} demand edges; and (ii) $\Wk_g$ is the edge-set of a walk between the end-points of $g$.
This proves \ref{pr3}.\\

\noindent \textbf{Case 3:} $E_1(k-1)\neq\emptyset$ and $G[C^{(k-1)}]\neq C^{(k-1)}$. 

Then $C^{(k-1)}$ is not a bounded face\footnote{Recall that all the faces of $G$ except $\fout$ are bounded} of $G$. Also, $G[C^{(k-1)}]$ is a (2-vertex connected) outerplanar graph and each bounded face of $G[C^{(k-1)}]$ is also a bounded face of $G$. 
By Fact \ref{fact:weakdualtree}, the weak dual $G^*[C^{(k-1)}]$ of $G[C^{(k-1)}]$ is a tree. 
By \ref{pr2}, the edge-set $E_0(k-1)$ is precisely the edge-set of $G^*[C^{(k-1)}]$;  
%therefore, the faces of $G$ satisfying the conditions of the while-loop on iteration $k$ are precisely the faces representing the leaf nodes of $G^*[C^{(k-1)}]$.
therefore, the faces of $G$ that can be processed on iteration $k-1$ are precisely the faces representing the leaf nodes of $G^*[C^{(k-1)}]$. 
%Recall that the face $f$ that is processed during an iteration of the algorithm is one for which the 
Let $f=i_1i_2\hdots i_\ell i_1$ be the face that is processed on iteration $\ite-1$. 
Then $\labkminus(\{i_j,i_{j+1}\})=1$ for each $1\leq j\leq \ell-1$ and $\labkminus(\{i_\ell,i_{1}\})=0$. 
Let $\omega_1\omega_2\hdots \omega_p i_1i_2\hdots i_\ell \omega_1$ denote the node-sequence of the simple cycle $C^{(k-1)}$, 
where $p\geq 1$. 
%Since $\lab(k)=\lab(k-1)+\bon_f$,
Since $\labk=\labkminus+\bon_f$,
the edge-set $E_1(k)$ induces the simple cycle $C^{(k)}$ given by the node-sequence $\omega_1\omega_2\hdots \omega_p i_1i_\ell \omega_1$. 
This proves \ref{pr1}. 
By the above, the only edge $e\in E$ such that $\labkminus(e)=0$ and $\labk(e)=1$ is $e=\{i_\ell,i_1\}$ i.e.,~$E_0(k)=E_0(k-1)-\{i_\ell,i_1\}$.
Therefore, $E_0(k)$ consists precisely of the edges $e$ of $G$ whose two endpoints lie on $C^{(k)}$ and $e\notin C^{(k)}$. 
This proves \ref{pr2}. 
    % Observe that $E_1(k-1)$ induce the simple cycle $C(k-1)$ given by a node-sequence $\omega_1\omega_2\hdots \omega_p i_1i_2\hdots i_\ell \omega_1$, where $p\geq 1$ since $C(k-1)$ is not a face of $G$; 
    % therefore, $E_1(k)$ induce the simple cycle $C(k)$ given by the node-sequence $\omega_1\omega_2\hdots \omega_p i_1i_\ell \omega_1$. This proves \ref{pr1}.     
    % By $(i)$ and $(ii)$, the edge-set $E_0(k)$ are precisely the edges of $G^*[C(k-1)]-f$,
    % which is precisely the weak dual graph of $G[C(k)]$; and therefore, $E_0(k)$ is precisely the set of edges of $G[C(k)]$ that do not lie in $C(k)$. This proves \ref{pr2}. 
If $\W_g^{(k-1)}$ does not contain a bad demand edge,
then $\W_g^{(k-1)}=\W_g^{(k)}$, as observed before. 
Otherwise, $\W_g^{(k-1)}$ contains precisely one bad demand edge $h$.
By \ref{pr3}, both end-points $s,t$ of $h$ lie on $C^{(k-1)}$. 
If neither $s$ nor $t$ are contained in $\{i_2,i_3,\hdots,i_\ell\}$, 
then $h$ is not contained in $\Dp_1\cup\Dp_2$ during iteration $k-1$;
in which case $\Wk_g=\Wkminus_g$ and $s,t\in G[C^{(k)}]$.
Otherwise, $h\in \Dp_1\cup\Dp_2$. 
If $h\in \Dp_2$, then, by the same argument as in Case 2,
(i) $\Wk_g=(\Wkminus_g-h)\cup \Dpminus_h$ only contains \emph{good} demand edges; and (ii) $\Wk_g$ is the edge-set of a walk between the end-points of $g$.
%$\W_g^{(k)}$ consists of edges whose endpoints are adjacent in $G$. 
Thus assume that $h\in \Dp_1$, $s\in \{i_2,i_3,\hdots,i_{\ell-1}\}$, and $t\in \{\omega_1,\omega_2,\hdots,\omega_p\}$. 
If $\Wk_g$ contains a bad demand edge,
then this edge is either $\{i_1,t\}$ or $\{i_\ell,t\}$;
both of these possible demands edges have their two end-points in $C^{(k)}$. 
Finally, since (a) $\Wkminus_g$ is the edge-set of a walk between the end-points of $g$, and (b) $h$ gets replaced in $\Wkminus_g$ with the edge-set $\Dpminus_h$ of an $s-t$ path (containing at most one bad demand edge),
then $\Wk_g$ is the edge-set of a walk between the end-points of $G$. This proves \ref{pr3}.
\end{proof}
