\begin{lemma}\label{lemma:instancesSatisfyCutCond}
Let $x$ be a feasible flow for $\I\left(G,\cp,\Dp,\dpr\right)$, then the following hold:
\noindent
\begin{enumerate}[label=(\alph*),topsep=0.2ex]
\item The ring-loading instance $\RL\left([n],\crl,\Dp_1\cup\Dp_2,\dpr\right)$ defined at \cref{ringLoadfeasible} satisfies the cut-condition.\label{condition2}
\item The instance $\mathcal{I}\left(G,x^*+\alpha \cdot \Dmax\cdot\bon_f,D_f,d^{(k+1)}\right)$ defined at \cref{cutconditionEndofIteration} satisfies the cut-condition.\label{condition3}
\end{enumerate}
\end{lemma}
\begin{proof}
Observe that at the start of iteration $k$, $x^*$ is a feasible flow of $\I(G,x^*,\Dp_1\cup\Dp_2,\dpr)$, and hence $\I(G,x^*,\Dp_1\cup\Dp_2,\dpr)$ satisfies the cut-condition, i.e.,
%(for all central cuts):
\begin{equation}\label{eq:cutconditionD1D2}
\dpr\left(\delta_{\Dp_1\cup\Dp_2}\left(\,\closedleft i,j\closedright\,\right)\right)\leq x^*\big(\delta_{G}\left(\,\closedleft i,j\closedright\,\right)\big) \text{ for each }i,j\in[n].
\end{equation}
Let $i,j\in[n]$ with $i\neq j+1$, and $f_1$ and $f_2$ be the unique faces in $\F-\fout$ that contain $\{i-1,i\}$ and $\{j,j+1\}$ respectively. Then,
\begin{align*}
\dpr\left(\delta_{\Dp_1\cup\Dp_2}\left(\,\closedleft i,j\closedright\,\right)\right)
&\leq  x^*\big(\delta_{G}\left(\,\closedleft i,j\closedright\,\right)\big)
\leq x^*(G^*_{f_1,f})+x^*(G^*_{f,f_2})+x^*(\{i-1,i\})+x^*(\{j,j+1\})\\
&=\crl\big(\,\{i-1,i\}\,\big)+\crl\big(\,\{j,j+1\}\,\big)=\crl\big(\,\delta_{[n]}(\,\closedleft i,j\closedright\,)\,\big).
\end{align*}
The first inequality follows from \eqref{eq:cutconditionD1D2}. The second inequality follows from Lemma~\ref{lemma:usefullemmafor[i,j]}. The first equality follows from the definition of $\crl$. 
%on line  \ref{definingEdgecapacitiesforRL}.
    %The last equation follows since the cut edges of $\closedleft i,j\closedright)$ are precisely $\{i-1,i\},\{j,j+1\}$. 
 It follows from Lemma~\ref{central} that $\RL([n],\crl,\Dp_1\cup\Dp_2,\dpr)$ satisfies the cut-condition. This proves \cref{condition2}. 
 Hence, Algorithm $\Alg$ computes a $\alpha$-feasible unsplittable flow $z$ for $\RL\left([n],\crl,\Dp_1\cup\Dp_2,\dpr\right)$. 
 We now prove \ref{condition3}. 
 By Lemma~\ref{central}, it suffices to show that,
% \david{Should we use some annoying notation like in here
    % https://arxiv.org/pdf/1606.07927 since there are parallel edges?}
\begin{equation}\label{eq:cutconditionendofalgorithm}
d^{(k+1)}\big(\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)\big)\leq (x^*+\alpha \cdot \Dmax\cdot\bon_f)(\delta_{G}\left(\,\closedleft i,j\closedright\,\right)\big) ~\text{for}~i,j\in[n], i\neq j+1.
\end{equation}
We consider three cases.

\noindent \textbf{Case 1: $i,j \in \openleft i_\ell,i_{1} \openright$}. 

It suffices to show that, 
$$\dpr\left(\delta_{\Dp_1\cup\Dp_2}\left(\,\closedleft i,j\closedright\,\right)\right)=d^{(k+1)}\big(\,\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)\big),$$
since inequality \eqref{eq:cutconditionendofalgorithm} would then immediately follow from \eqref{eq:cutconditionD1D2} in this case. Observe that: (i) all the edges in $\Dp_h$, for $h\in\Dp_2$, are only incident to nodes of $f$; and (ii) if $h\in \Dp_1$, then $t\in V(h)$ is the unique endpoint of $h$ contained in $\openleft i_\ell,i_1\openright$, and there is precisely one demand edge of $\Dp_h$ with exactly one endpoint in $\openleft i_\ell,i_1\openright$, and this endpoint is $t$. Then $\delta_{\Dp_2}\left(\,\closedleft i,j\closedright\,\right)=\emptyset$ and $\delta_{\Dp_h}\left(\,\closedleft i,j\closedright\,\right)=\emptyset$ for each $ h\in (\Dp_1\cup\Dp_2)\setminus\delta_{\Dp_1}\left(\,\closedleft i,j\closedright\,\right)$. This implies that:
\begin{align*}
\dpr\big(\delta_{\Dp_1\cup\Dp_2}(\closedleft i,j\closedright)\big)&=\sum_{h\in \delta_{\Dp_1}(\closedleft i,j\closedright)}\dpr(h);\\
\dpr\big(\delta_{D_f}(\closedleft i,j\closedright)\big)&=\sum_{h\in \delta_{\Dp_1}(\closedleft i,j\closedright)}\sum_{r\in \delta_{\Dp_h}(\closedleft i,j\closedright)}\dpr(r).
\end{align*}
Let $h\in \delta_{\Dp_1}(\closedleft i,j\closedright)$. By observation (ii) above, $|\delta_{\Dp_h}\left(\,\closedleft i,j\closedright\,\right)|=1$. Thus, since $\dpr(r)=\dpr(h)$ for each $r\in \Dp_h$, $\dpr(h)=\sum_{r\in \delta_{\Dp_h}(\closedleft i,j\closedright)}\dpr(r)$.
It follows that $\dpr\big(\delta_{\Dp_1\cup\Dp_2}\left(\,\closedleft i,j\closedright\,\right)\big)=\dpr\big(\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)\big)$, as desired.     

\noindent\textbf{Case 2:} $i,j \in \openleft i_q,i_{q+1} \openright$ for some $1\leq q\leq \ell-1$. 

Then either $\closedleft i,j\closedright\subseteq \openleft i_q,i_{q+1} \openright$ or $[n]\setminus\closedleft i,j\closedright\subseteq \openleft i_{q},i_{q+1} \openright$.
% %If $\closedleft i,j\closedright\subseteq \openleft i_q,i_{q+1} \openright$ ,
    % %then $\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)=\emptyset$ 
    Since for each $h\in \Dp_1\cup\Dp_2$, the demand edges in $\Dp_h$ 
    %reated on the for-loops on lines \ref{FirstForstarts} and \ref{SecondForStarts} 
    are incident only to nodes contained in either $f$ or $\openleft i_\ell,i_1 \openright$, 
    then either $[i,j]$ or $[n]\setminus[i,j]$ does not contain any node incident to edges of $D_f$.
    Hence $\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)=\emptyset$,
     and inequality \eqref{eq:cutconditionendofalgorithm} follows trivially.

\noindent\textbf{Case 3:} $\{i,j\} \nsubseteq \openleft i_q,i_{q+1} \openright$ for every $1\leq q\leq \ell$, where $i_{\ell+1}:=i_1$.

Then both $\closedleft i,j\closedright$ and $[n]\setminus [i,j]$ contain at least one node from $f$. Let $f_1$ and $f_2$ denote the unique faces in $\F-\fout$ that contain $\{i-1,i\}$ and $\{j,j+1\}$, respectively.
Since $z$ is an $\alpha$-feasible unsplittable flow for $\RL\left([n],\crl,\Dp_1\cup\Dp_2,\dpr\right)$,
and by construction of $D_f$,
the ring-loading instance $\RL\left([n],\crl+\alpha \cdot \Dmax,D_f,d^{(k+1)}\right)$ is feasible.
Therefore $\RL\left([n],\crl+\alpha \cdot \Dmax,D_f,d^{(k+1)}\right)$ satisfies the cut-condition. 
%Let $\big(\delta_{[n]}\left(\,\closedleft i,j\closedright\,\right)\big)$ denote the total capacity of edges going across the set $[i,j]$ in the ring-loading instance $\mathcal{RL}([n],\crl+\alpha \cdot \Dmax,D_f,\dpr)$. 
It follows that,
\begin{align*}
         d^{(k+1)}\big(\delta_{D_f}\left(\,\closedleft i,j\closedright\,\right)\big)
        &\leq  \left(\crl+\alpha \cdot \Dmax\right)\big(\delta_{[n]}\left(\,\closedleft i,j\closedright\,\right)\big)\\
         &= \crl\big(\,\{i-1,i\}\,\big)+\crl\big(\,\{j,j+1\}\,\big)+2 \cdot \alpha \cdot \Dmax\\
        &=x^*\left(G^*_{f,f_1}\right)+x^*\big(\,\{i-1,i\}\,\big)+x^*\left(G^*_{f,f_2}\right)+x^*\big(\,\{j,j+1\}\,\big)+2 \cdot \alpha \cdot \Dmax\\
        &=x^*\left(G^*_{f_1,f_2}\right)+x^*\big(\,\{i-1,i\}\,\big)+x^*\big(\,\{j,j+1\}\,\big)+2 \cdot \alpha \cdot \Dmax\\
        &=\left(x^*+\alpha \cdot \Dmax \cdot \bon_f\right)\big(\delta_{G}\left(\,\closedleft i,j\closedright\,\right)\big).
\end{align*}
 The second equality follows from the definition of $\crl$.
The third equality follows from Lemma~\ref{lemma:usefullemmafor[i,j]}.
The last equality follows from part (c) of Lemma~\ref{lemma:usefullemmafor[i,j]}, and the fact that there are precisely two edges of $f$ in $\delta_{G}\left(\,\closedleft i,j\closedright\,\right)$. This proves \cref{condition3}.
\end{proof} 
