\begin{proof}
Suppose that $f\in\F-\fout$ is the face being considered in iteration $k$. Since $x^{(k)}$ is a feasible flow for instance $\I\left(G,\cp,\Dp,\dpr\right)$, it follows that 
%and $x^\prime=x-x^*$, where $x^*=\sum_{h\in \Dp_1\cup\Dp_2}x_h$, then
$x^{(k)}-x^*$ is a feasible flow for instance 
$\I\left(G,\cp-x^*,\Dp\setminus \left(\Dp_1\cup\Dp_2\right),\dpr\right)$.
By Lemma~\ref{lemma:instancesSatisfyCutCond}, $\mathcal{I}\left(G,x^*+\alpha \cdot \Dmax\cdot\bon_f,D_f,d^{(k+1)}\right)$ (defined at \cref{cutconditionEndofIteration}) satisfies the cut-condition. Therefore, by Theorem~\ref{OS} a feasible flow $y$ of $\mathcal{I}\left(G,x^*+\alpha \cdot \Dmax\cdot\bon_f,D_f,d^{(k+1)}\right)$ can be computed (in polynomial time). It then follows that $x^{(k)}-x^*+y$ is a feasible flow for $\I\left(G,\cp+\alpha \cdot \Dmax\cdot\bon_f,\left(\Dp\setminus \left(\Dp_1\cup\Dp_2\right)\right)\cup D_f,d^{(k+1)}\right)$
The proof of the lemma follows from the fact that $x^{(k+1)}= x^{(k)}-x^*+y$, and $$\I(G, c^{(k+1)}, D^{(k+1)}, 
 d^{(k+1)})=\I\left(G,\cp+\alpha \cdot \Dmax\cdot\bon_f,\left(\Dp\setminus \left(\Dp_1\cup\Dp_2\right)\right)\cup D_f,d^{(k+1)}\right).$$
\end{proof}


We are now ready to give a proof of Theorem~\ref{theorem:Newinstance}, which we restate.
\theoremnew*
\begin{proof}By Lemma~\ref{lemma:every_ite_feasible}, the cut-condition is satisfied for each $\I(G,\cp,\Dp,\dpr)$, and hence the cut-condition is also satisfied for the final output $\I(G,c',D',d')$. Note that the capacity of an edge $e$ is increased by $\alpha \cdot d_{\max}$ only when its label is also increased by 1. Initially, the label of all the edges on the unbounded face $\fout$ is 1 while the label of the remaining edges is 0. At the end of the algorithm, the label of every edge is 2. This implies that the capacity of edges on $\fout$ increases by $\alpha \cdot \Dmax$ and the capacity of the remaining edges increases by $2 \cdot \alpha \cdot \Dmax$.
By \cref{pr3} of Lemma~\ref{propositionCycle2}, it follows that the edges in $W_g$ form a walk between the end points of $g$. Furthermore, if there are bad edges in $W_g$, then both its end-points are incident on the cycle formed by label 1 edges. At the end of the algorithm, there are no label 1 edges and hence there are no bad edges in $W_g$. Whenever we insert a new demand edge in $\W_g^{(k)}$, we set its value to $d(g)$. Hence all the demand edges in $W_g$ have value $d(g)$, and this completes the proof.
%of Theorem~\ref{theorem:Newinstance}.
\end{proof}
\subsection{Handling Parallel Edges in $G$}\label{parallele}
Suppose that $G=(V,E)$ has parallel edges. We describe how to proceed in this case.
For every $u,v\in V$, let $E(u,v)$ denote the edges incident to both $u$ and $v$.
We can create a new graph $G_0=(V,E_0)$ by replacing each $E(u,v)\neq\emptyset$ with an edge $uv$ of capacity $c_0(uv)=\sum_{e\in E(u,v)}c(e)$.
Then $\I(G,c,D,d)$ is feasible if and only if $\I(G_0,c_0,D,d)$ is feasible. 
We can apply the algorithm in this section to $\I(G_0,c_0,D,d)$ in order to obtain an instance $\I(G_0,c_0^\prime,D^\prime,d^\prime)$ satisfying the properties in Theorem~\ref{theorem:Newinstance}.
For each $uv\in E_0$, if $c_0^\prime(uv)=c_0(uv)+\delta$, then pick an edge $e\in E(u,v)$ and define $c^\prime(e)=c(e)+\delta$ and $c^\prime(e^\prime)=c(e^\prime)$ for all $e^\prime\in E(u,v)-e$.
Then , the instance $\I(G,c^\prime,D^\prime,d^\prime)$ satisfies the properties of Theorem~\ref{theorem:Newinstance}  with respect to $\I(G,c,D,d)$.

\section{Proof of Theorem~\ref{theorem:G+Hplanar}}\label{section:good}
In this section, we give a proof of Theorem~\ref{theorem:G+Hplanar}, which we restate for convenience.
\theoremgood*
As discussed in Section 2, we may assume without loss of generality that $G=(V,E)$ is 2-vertex connected. 
%We assume that $G$ can have parallel edges. Since $G$ is outerplanar and the cut-condition is satisfied, there exists a feasible flow $x$ for $\I(G,c,H,d)$ by Theorem~\ref{OS}.
For any pair $u\neq v\in V$ of nodes, we use $E(u,v):=\{e\in E:V(e)=\{u,v\}\}$ and $D(u,v):=\{g\in D:V(g)=\{u,v\}\}$ to denote the set of edges of $E$ and $D$, respectively, incident to both $u$ and $v$.
We say that an unbounded face $f=i_1i_2\hdots i_\ell i_1$ of $G$ is an \emph{ear incident to $\{i_\ell, i_1\}$}, 
if $\ell\geq 3$ and if for every $j\in[\ell-1]$, there exists an edge $e\in E(i_\ell,i_{j+1})$ incident to the unbounded face of $G$.
\footnote{Observe that if we create a graph $G_0$ by replacing each $E(u,v)\neq\emptyset$ in $G$ with a single edge $uv$, then an ear of $G$ corresponds to a leaf of the weak dual of $G_0$.} 

We first give a brief description of the algorithm.
Our algorithm works in iterations; one per each unbounded face of $G$ incident to at least $3$ vertices.
At the start of iteration $k$ we consider a feasible instance $\I(G^{(k)},c^{(k)},D^{(k)},d^{(k)})$ where all demand edges are good and where $G^{(k)}$ is 2-vertex connected .
Initially, $\I(G^{(1)},c^{(1)},D^{(1)},d^{(1)})=\I(G,c,D,d)$.
We consider an ear $f$ of $G^{(k)}$ incident to some $\{i_\ell,i_1\}$. 
%All demands in $\cup_{j=1}^{\ell-1}D^{(k)}(i_j,i_{j+1})$ are either fully or partially routed on iteration $k$, using only edges in $\cup_{j=1}^{\ell-1}E^{(k)}(i_j,i_{j+1})$. 
For each $j\in[\ell-1]$, each demand $g\in D^{(k)}(i_j,i_{j+1})$ is either routed along a single edge of $E^{(k)}(i_j,i_{j+1})$, or $g$ is replaced with a demand of value $d^{(k)}(g)$ incident to $i_1,i_\ell$ after routing a flow of value $d^{(k)}(g)$ both from $i_j$ to $i_1$, and from $i_{j+1}$ to $i_\ell$, across two paths with node sequence $i_j\hdots i_1$ and $i_{j+1}\hdots i_\ell$, respectively.
We do this so that the capacity of any edge is not exceeded by more than $\Dmax$.
After this procedure, there are no demands incident to $i_2,\hdots,i_{\ell-1}$.
If there is one $j\in[\ell-1]$, 
such that all edges $e$ in $E^{(k)}(i_j,i_{j+1})$ have exceeded their original capacity $c^{(k)}(e)$, we remove $\{i_2,\hdots,i_{\ell-1}\}$ from $G^{(k)}$; otherwise, we replace $\{i_2,\hdots,i_{\ell-1}\}$ and their incident edges with a single edge $e_0=\{i_1,i_\ell\}$ with a suitable capacity.
We then continue to iteration $k+1$, and in there we consider any ear from the graph of the resulting instance.
%The resulting instance is then passed to iteration $k+1$.
%Note that the number of unbounded faces in the graph with more than two vertices decreases by one.
After the last iteration, the resulting (feasible) instance has a supply graph with only two vertices, which is straightforward to solve, for instance, by using Claim \ref{claim:pathgood} below. 

\noindent Iteration $k$ proceeds differently, depending on which of the following two cases hold:
\begin{align}\label{gooddemands:cases}
\textbf{Case 1:}& \sum_{g\in D^{(k)}(i_j,i_{j+1})}d^{(k)}(g)\leq \Dmax+\sum_{e\in E^{(k)}(i_j,i_{j+1})}c^{(k)}(e) \text{ for each }j\in [\ell-1].\nonumber\\
\textbf{Case 2:}& \sum_{g\in D^{(k)}(i_j,i_{j+1})}d^{(k)}(g)> \Dmax+\sum_{e\in E^{(k)}(i_j,i_{j+1})}c^{(k)}(e) \text{ for precisely one }j\in [\ell-1].
\end{align}
Observe that if $\I(G^{(k)},c^{(k)},D^{(k)},d^{(k)})$ satisfies the cut-condition, then it cannot be the case that there are $1\leq j< j^{\prime}\leq \ell-1$ with  $\sum_{g\in D^{(k)}(i_j,i_{j+1})}d^{(k)}(g)> \Dmax+\sum_{e\in E^{(k)}(i_j,i_{j+1})}c^{(k)}(e)$ and  $\sum_{g\in D^{(k)}(i_{j^\prime},i_{{j^\prime}+1})}d^{(k)}(g)>\Dmax+\sum_{e\in E^{(k)}(i_{j^\prime},i_{j^\prime+1})}c^{(k)}(e)$.
This holds because,
\begin{align*}
\sum_{e\in E(i_j,i_{j+1})}c^{(k)}(e)+\sum_{e\in E(i_{j^\prime},i_{j^\prime+1})}c^{(k)}(e)&=c^{(k)}(\{i_{j+1},i_{j+2},\hdots,i_{j^\prime}\})\geq d^{(k)}(\{i_{j+1},i_{j+2},\hdots,i_{j^\prime}\})\\
&=\sum_{g\in D^{(k)}(i_j,i_{j+1})}d^{(k)}(g)+\sum_{g\in D^{(k)}(i_{j^\prime},i_{j^\prime+1})}d^{(k)}(g),
\end{align*}
where the equalities follow from the fact that $f=i_1i_2\hdots i_\ell i_1$ is an ear of $G^{(k)}$.
%incident to $\{i_\ell,i_1\}$).

In order to prove Theorem~\ref{theorem:G+Hplanar}, we make repeated use of the following straightforward claims.
\begin{claim}\label{claim:pathgood}
Consider an instance $\mathcal{I}(G,c,D,d)$.
Let $v_1,v_2\hdots,v_r\in V$ be a set of distinct vertices, and let $D^*\subseteq D$ be a set of demand edges such that $V(g)=\{v_1,v_r\}$ for all $g\in D^*$.
If 
\begin{equation*}
\sum_{g\in D^*}d(g)\leq\Dmax+\sum_{e\in E(v_j,v_{j+1})}c(e),\;\forall j\in[r-1],
\end{equation*}
then one can efficiently compute a set of paths $\{p_g\}_{g\in D^*}$ in $G$ such that the node sequence of each $p_g$ is precisely $v_1v_2\hdots v_r$, and such that 
\begin{equation*}
\sum_{g\in D^*:e\in p_g}d(g)\leq c(e)+\Dmax,\;\forall e\in \{E(v_j,v_{j+1})\}_{j\in[r-1]}.
\end{equation*}
\end{claim}
\begin{proof}
%By the Max Flow-Min Cut Theorem,
Let $j\in[r-1]$.
Suppose that $E(i_j,i_{j+1})=\{e_1,\hdots,e_a\}$ and $D(i_j,i_{j+1})=\{g_1,\hdots,g_b\}$. 
%We prove by induction on $|E(i_j,i_{j+1})|$
It suffices to prove that we can compute an assignment $\sigma_j:D^*\rightarrow E(i_j,i_{j+1})$, such that $\sum_{g\in D^*:\sigma_j(g)=e}d(g)\leq c(e)+\Dmax$ for each $e\in E(v_j,v_{j+1})$. 
The proof of the theorem would then follow by taking $p_g=\{\sigma_j(g)\}_{j\in[\ell-1]}$.
We prove the above by induction on $|E(i_j,i_{j+1})|$.
Clearly, the above holds if $|E(i_j,i_{j+1})|=1$. 
Thus, suppose that $|E(i_j,i_{j+1})|>1$.
Take any edge $e^\prime\in E(v_j,v_{j+1})$, and let $Q\subseteq D^*$ be a maximal inclusion-wise subset of demands with $\sum_{g\in Q}d(g)\leq c(e^\prime)+\Dmax$.
Let $\sigma_j(g)=e^\prime$ for all $g\in Q$.
If $Q=D^*$, we are done. 
If $Q\neq D^*$, then $c(e^\prime)<\sum_{g\in Q}d(g)$.
Therefore, $\sum_{g\in D^*\setminus Q}d(g)\leq \Dmax+\sum_{e\in E(v_j,v_{j+1})-e^\prime}c(e)$. By the induction hypothesis, we can assign each $g\in D^*\setminus Q$ to some edge in $E(v_j,v_{j+1})-e^\prime$, so that $\sum_{g\in D^*\setminus Q:\sigma_j(g)=e}d(g)\leq c(e)+\Dmax$ for each $e\in E(v_j,v_{j+1})-e^\prime$. 
\end{proof}
\begin{claim}\label{claim:residual}
Suppose that an instance $\mathcal{I}(G,c,D,d)$ satisfies the cut-condition.
Let $g\in D$ be a good demand with $V(g)=\{u,v\}$. 
Suppose that one routes $g$ through some $e^\prime\in E(u,v)$, 
by possibly exceeding the capacity of $e^\prime$. 
Then the residual instance $\mathcal{I}(G,c^\prime,D-g,d)$ satisfies the cut-condition, where $c^\prime(e^\prime)=\max\{0,c(e^\prime)-d(g)\}$ and $c^\prime(e)=c(e)$ for each $e\in E-e^\prime$.
\end{claim}
\begin{proof}
Let $S\subseteq V$. 
Clearly, the cut-condition holds if $u,v\in S$ or $u,v\in V\setminus S$.
If suffices to consider the case in which, without loss of generality, $u\in S$ and $v\notin S$.
Observe that,
$$c^{\prime}(\delta_G(S))=c(\delta_G(S))-c(e^\prime)+c^\prime(e^\prime)\geq d(\delta_D(S))-c(e^\prime)+c^\prime(e^\prime)\geq d(\delta_D(S))-d(g).$$
\end{proof}
For each case in \eqref{gooddemands:cases}, we show how to construct the feasible instance $\I(G^{(k+1},c^{(k+1)},D^{(k+1)},d^{(k+1)})$, and show how to convert a 1-feasible unsplittable flow in $\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ into a 1-feasible unsplittable flow in $\I(G^{(k)},c^{(k)},D^{(k)},d^{(k)})$.

\subsection{Description of an Iteration in Case 1}
Suppose that $\sum_{g\in D^{(k)}(i_j,i_{j+1})}d^{(k)}(g)\leq \Dmax+\sum_{e\in E^{(k)}(i_1,i_{j+1})}c^{(k)}(e)$ for all $j\in[\ell-1]$.
By Claim~\ref{claim:pathgood}, we can assign each $g\in D^{(k)}(i_j,i_{j+1})$ to an edge $e_g\in E^{(k)}(i_j,i_{j+1})$, so that $d_e\leq c(e)+\Dmax$ for each $e\in E^{(k)}(i_j,i_{j+1})$,
where
$d_e:=\sum_{g\in D^{(k)}(i_j,i_{j+1}):e_g=e}d^{(k)}(g)$.
%For each $e\in E^{(k)}(i_j,i_{j+1})$,
%let $d_e=\sum_{g\in D^{(k)}(i_j,i_{j+1}):e_g=e}d^{(k)}(g)$.
After this operation, define $E_j=\{e\in E^{(k)}(i_j,i_{j+1}):d_e\leq c^{(k)}(e)\}$ as the set of edges whose capacity was not exceeded during the above procedure.
Create a new edge $e_0$ incident to $i_1$ and $i_\ell$, and define 
\begin{align*}
V^{(k+1)}&:=V^{(k)}\setminus\{i_2,\hdots,i_{\ell-1}\},\\
E^{(k+1)}&:=\left(E^{(k)}\setminus \cup_{j\in [\ell-1]}E^{(k)}(i_j,i_{j+1})\right)+e_0,\\
c^{(k+1)}(e)&:=\begin{cases}
c^{(k)}(e),&\:\text{if }~e\in E^{(k)}\setminus \cup_{j\in [\ell-1]}E^{(k)}(i_j,i_{j+1})\\
\min_{j\in[\ell-1]}\sum_{e\in E_j}(c^{(k)}(e)-d_e),&\:\text{if }~e=e_0,
\end{cases}\\
D^{(k+1)}&:=D^{(k)}\setminus \cup_{j\in [\ell-1]}D^{(k)}(i_j,i_{j+1}),\\
d^{(k+1)}(g)&:=d^{(k)}(g).
\end{align*}
\begin{claim}
$\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ is feasible.
\end{claim}
\begin{proof}
By Claim~\ref{claim:residual}, 
the residual instance $\I_{res}$ obtained from $\I(G^{(k)},c^{(k)},D^{(k)},d^{(k)})$ after routing the demands in $\{D^{(k)}(i_j,i_{j+1})\}_{j\in[\ell-1]}$,
replacing $\{E^{(k)}(i_j,i_{j+1})\}_{j\in[\ell-1]}$ with $\{E_j\}_{j\in[\ell-1]}$, and decreasing $c^{(k)}(e)$ by $d_e$, is feasible.
The claim follows from the Max Flow-Min Cut Theorem, by
observing that $\I_{res}$ does not have demands incident to any node in $\{i_2,\hdots,i_{\ell-1}\}$, and that $\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ is obtained from $\I_{res}$ by replacing $\{E_j\}_{j\in[\ell-1]}$ with $e_0$.
\end{proof}
\begin{claim}\label{flowk:case1}
A 1-feasible unsplittable flow $y$ in $\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ can be efficiently converted into a 1-feasible unsplittable flow $z$ in $\I(G^{k},c^{(k)},D^{(k)},d^{(k)})$.
\end{claim}
\begin{proof}
Let $y(g)$ be the edge set of the path on which $y$ routes $g\in D^{(k+1)}$.
For each $g\in \cup_{j\in[\ell-1]} D^{(k)}(i_j,i_{j+1})$, let $z(g)=\{e_g\}$.
For the remaining demands of $D^{(k)}$ i.e., the demands in $D^{(k+1)}$, we consider two cases.
For each $g\in D^{(k+1)}$ with $e_0\notin y(g)$, let $z(g)=y(g)$.
Let $D_0\subseteq D^{(k+1)}$ be the set of demands $g$ with $e_0\in y(g)$.
Let $y(e_0)$ be the flow that traverses $e_0$.
Then,
\begin{equation*}
y(e_0)\leq \Dmax+ c^{(k+1)}(e_0)=\Dmax+\min_{j\in[\ell-1]} \sum_{e\in E_j}(c^{(k)}(e)-d_e).
\end{equation*}
It follows from Claim~\ref{claim:pathgood} that we can compute a set of paths $\{p_g\}_{g\in D_0}$ in $\cup_{j\in[\ell-1]}E_j$, each of which has the node sequence $i_1i_2\hdots i_\ell$, such that for each $e\in \cup_{j\in[\ell-1]}E_j$,
\begin{equation*}
\sum_{g\in D_0:e\in p_g}d^{(k)}(g)\leq c^{(k)}(e)-d_e+\Dmax.
\end{equation*}
For each $g\in D_0$, we set $z(g)=(y(g)-e_0)\cup p_g$.
Therefore, for each $e\in \cup_{j\in[\ell-1]} E_j$,
\begin{align*}
z(e)&=\sum_{g\in D^{k}(i_j,i_{j+1}):z(g)=e}d^{(k)}(g)+\sum_{g\in D_0:e\in p_g}d^{(k)}(g)\\
%\sum_{g\in D^{(k)}:e\in z(g)}d^{(k)}(g)&=\sum_{g\in D^{k}(i_j,i_{j+1}):z(g)=e}d^{(k)}(g)+\sum_{g\in D_0:e\in p_g}d^{(k)}(g)\\
&\leq d_e+c^{(k)}(e)-d_e+\Dmax\leq c^{(k)}(e)+\Dmax.
\end{align*}
%Finally, note that none of the edges outside $\cup_{j\in[\ell-1]}E_j$ is used to route the demands in $D_0$.
Finally, note that $z(e)=d_e\leq c^{(k)}(e)+\Dmax$ for each $e\in \cup_{j\in[\ell-1]}\left(E^{(k)}(i_j,i_{j+1})\setminus E_j\right)$, 
and that $z(e)=y(e)\leq c^{(k+1)}(e)+\Dmax=c^{(k)}(e)+\Dmax$ for each $e\in E^{(k)}\setminus\cup_{j\in[\ell-1]}E^{(k)}(i_j,i_{j+1})$.
\begin{comment}
$e\in E^{(k)}\setminus\cup_{j\in[\ell-1]}E^{(k)}(i_j,i_{j+1})$, 
$z(e)=y(e)\leq c^{(k+1)}(e)+\Dmax=c^{(k)}(e)+\Dmax,$
$$\sum_{g\in D^{(k)}:e\in z(g)}d^{(k)}(g)=y(e)\leq c^{(k+1)}(e)+\Dmax=c^{(k)}(e)+\Dmax,$$
and for each $e\in \cup_{j\in[\ell-1]}\left(E^{(k)}(i_j,i_{j+1})\setminus E_j\right)$, $$\sum_{g\in D^{(k)}:e\in z(g)}d^{(k)}(g)=d_e\leq c^{(k)}(e)+\Dmax.$$
\end{comment}
\end{proof}

\subsection{Description of an Iteration in Case 2}
Let $j^\prime$ be the unique index in $[\ell-1]$ for which $\sum_{g\in D^{(k)}(i_{j^\prime},i_{j^\prime+1})}d^{(k)}(g)> \Dmax+\sum_{e\in E^{(k)}(i_{j^\prime},i_{j^\prime+1})}c^{(k)}(e)$.
As in Case 1, for each $j^\prime\neq j\in[\ell-1]$,
we can assign each $g\in D^{(k)}(i_j,i_{j+1})$ to an edge $e_g\in E^{(k)}(i_j,i_{j+1})$, 
so that $d_e\leq c(e)+\Dmax$ for each $e\in E^{(k)}(i_j,i_{j+1})$, 
where $d_e=\sum_{g\in D^{(k)}(i_j,i_{j+1}):e_g=e}d^{(k)}(g)$.
Take an inclusion-wise maximal subset $D^*_{j^\prime}\subseteq D^{(k)}(i_{j^\prime},i_{j^\prime+1})$, 
such that each $g\in D^*$ can be mapped to an edge $e_g\in E^{(k)}(i_{j^\prime},i_{j^\prime+1})$, so that $\sum_{g\in D^*_{j^\prime}:e_g=e}d^{(k)}(g)\leq c(e)+\Dmax$ for each $e\in E^{(k)}(i_{j^\prime},i_{j^\prime+1})$.
If $D^*_{j^\prime}= D^{(k)}(i_{j^\prime},i_{j^\prime+1})$, we can proceed in the exact same way as in Case 1 and define $\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ as there.
Thus, assume that $D^*_{j^\prime}\neq D^{(k)}(i_{j^\prime},i_{j^\prime+1})$.
%By Claim~\ref{claim:residual}, the residual instance 
Let $D^\#_{j^\prime}=D^{(k)}(i_{j^\prime},i_{j^\prime+1})\setminus D^*_{j^\prime}$.
