\begin{align*}
 V^{(k+1)}&:=V^{(k)}\setminus \{i_2,\hdots,i_{\ell-1}\},\\ E^{(k+1)}&:=E^{(k)}\setminus \{E(i_j,i_{j+1})\}_{j\in [\ell-1]},\\
 c^{(k+1)}(e)&:=c^{(k)}(e), \\
D^{(k+1)}&:=\left( D^{(k)}\setminus \cup_{j\in[\ell-1]}D^{(k)}(i_j,i_{j+1})\right)\cup\{g^\#\}_{g\in D_{j^\prime}^\#}. \\
d^{(k+1)}(g)&:=\begin{cases}
d^{(k)}(g),&\:\text{if }~g\in D^{(k)}\setminus \cup_{j\in [\ell-1]}D^{(k)}(i_j,i_{j+1})\\
d^{(k)}(h),&\:\text{if }~g=h^\#.
\end{cases}   
\end{align*}
%We define $V^{(k+1)}=V^{(k)}\setminus \{i_2,\hdots,i_{\ell-1}\}$, $E^{(k+1)}=E^{(k)}\setminus \{E(i_j,i_{j+1})\}_{j\in [\ell-1]}$, 
%$D^{(k+1)}=\left( D^{(k)}\setminus \{D^{(k)}(i_j,i_{j+1})\}_{j\in[\ell-1]}\right)\cup\{g^\#\}_{g\in D_{j^\prime}^\#}$. 
