\end{proof}
\begin{claim}\label{flowk:case2}
A 1-feasible unsplittable flow $y$ in $\I(G^{(k+1)},c^{(k+1)},D^{(k+1)},d^{(k+1)})$ can be efficiently converted into a 1-feasible unsplittable flow $z$ in $\I(G^{k},c^{(k)},D^{(k)},d^{(k)})$.
\end{claim}
\begin{proof}
Let $z(g)=y(g)$ for each $g\in D^{(k)}\setminus\cup_{j\in[\ell-1]}D^{(k)}(i_j,i_{j+1})$, and let $z(g)=e_g$ for each $g\in \left(\cup_{j\in[\ell-1]}D^{(k)}(i_j,i_{j+1})\right)\setminus D^\#_{j^\prime}$. Let $\I_a$ and $\I_b$ be as in the proof of Claim \ref{claim:iaib}.
By Claim \ref{claim:pathgood}, we can compute two $1$-feasible unsplittable flows $z_a$, $z_b$ for $\I_a$ and $\I_b$, respectively.
For each $g\in D^\#_{j^\prime}$, we set $z(g)=z_a(g_a)\cup y(g^\#)\cup z_b(g_b)$.
Observe that $z(e)= d_e\leq c^{(k)}(e)+\Dmax$ for each $e\in \cup_{j\in[\ell-1]}\left (E^{(k)}(i_j,i_{j+1})\setminus E_j\right)$, and $z(e)=y(e)\leq c^{(k+1)}(e)+\Dmax=c^{(k)}(e)+\Dmax$ for each $e\in E^{(k)}\setminus \cup_{j\in[\ell-1]}E^{(k)}(i_j,i_{j+1})$. Finally, let $c\in\{a,b\}$ and $e\in E_c$. Then, $$z(e)=d_e+z_c(e)\leq d_e+c^\prime(e)+\Dmax=d_e+c^{(k)}(e)-d_e+\Dmax=c^{(k)}(e)+\Dmax.$$
\end{proof}
\subsection{Proof of Theorem~\ref{theorem:G+Hplanar}}
Let $\I(G,c,D,d)$ be a feasible instance and let $F$ be the number of unbounded faces of $G$ with at least 3 vertices.
For each iteration $k\in[F+1]$, we compute the feasible instances $\I(G^{(k)},c^{(k)},D^{(k)},d^{(k)})$ as described above. 
Observe that each instance only contains good demands, and that each $G^{(k)}$ is a 2-vertex connected planar graph. 
In the end, $\I(G^{(F+1)},c^{(F+1)},D^{(F+1)},d^{(F+1)})$ has no unbounded faces with at least 3 vertices. 
Thus, $G^{(F+1)}$ contains only 2 vertices.
By Claim~\ref{claim:pathgood}, we can compute a 1-feasible unsplittable flow in $\I(G^{(F+1)},c^{(F+1)},D^{(F+1)},d^{(F+1)})$.
By Claims~\ref{flowk:case1} and \ref{flowk:case2}, we can backtrack starting from $k=F$ in order to compute a 1-feasible unsplittable flow in $\I(G^{(1)},c^{(1)},D^{(1)},d^{(1)})=\I(G,c,D,d)$.
This concludes the proof.



\section{Conclusion}
We proved that if $G$ is an outerplanar graph and the cut-condition is satisfied, then there exists a $\mathcal{O}(1)$-feasible unsplittable flow. It is an interesting open problem to generalize this result to other settings where the cut-condition is also sufficient for a feasible routing of all the demands, for example when all the source-sink pairs are incident on the unbounded face of a planar graph. It would also be interesting to see if a similar result holds for a more general class of graphs, where the cut-condition is not sufficient for a feasible routing, such as series-parallel graphs.

