	\frac{x}{y}	\cdot \frac{u}{v}		&=  \frac{x \cdot u}{y \cdot v}\\
	\label{fracDivSum}		
	\frac{x}{y} + \frac{u}{v}	&= \frac{(x\cdot v) + (y \cdot u)}{y \cdot v}\\
	%\label{fracDivDiv}
	%\frac{x}{( \frac{u}{v})}		&=  x \cdot \frac{v \cdot v}{u \cdot v}\\
	\frac{x}{y +( 0 \cdot z)} &= \frac{x + (0 \cdot z)}{y}\\
	\bot				&= \frac{1}{0}
\end{align}
\hrule
\medskip
\caption{$E_{\mathsf{ftc-cm}}$: Equational axioms for fracterm calculus for common meadows}
\label{FTCcm}
\end{table}


\begin{definition}
A model of $E_{\mathsf{ftc-cm}}$ we will call a {\em generalised common meadow}. We denote the class of such algebras $\mathsf{GCM} =\mathsf{Alg}(\Sigma_{r,\div, \bot}, E_{\mathsf{ftc-cm}})$.
\end{definition}

Because the generalised common meadows constitute a variety, the conditional equational theory -- and indeed the first order theory -- of the class of generalised common meadows is finitely axiomatized by $E_{\mathsf{ftc-cm}}$. 

