\makecommand{\vrpile}{{\hat\pile}}
\makecommand{\vrPileType}{{\hat\pileType}}
\makecommand{\vrPileTypeFn}{{\hat\pileTypeFn}}
%\makecommand{\vrPileTypeFn}{{\bar\pileTypeFn}}

\makecommand{\designpile}{{\tilde\pile}}
