\section{An algebra for virtual piles types}
\label{sec:algebra}

The ``virtual shuffle'' interpretation
just presented
proves fundamental to the analysis of multi-round pile shuffle.
However,
the characterizing equation~\eqref{eq:type-indicator-recurrence} is convoluted and generally unintuitive.
%
In this section we present a small symbolic algebra
which concisely and intuitively captures its effects.
In addition to providing useful insight
about the formation of virtual piles
corresponding to the concatenation of multiple rounds of shuffle,
the algebra and its notation will be relied upon heavily
in the sequel.

%
\begin{defn}
\label{defn:factored-schedules}
Given a type schedule
$\typeSchedules = \left( \pileType_1, \pileType_2, \ldots, \pileType_\numphase \right)$,
we will denote by
$\pileType_1 \backslash \pileType_2 \backslash \ldots \backslash \pileType_\numphase$
the virtual pile type assignments $\vrPileType_1$ 
corresponding to $\typeSchedules$ in the sense of Lemma~\ref{prop:hetero-multi-sort}.
\end{defn}

%
The definition
introduces a new backslash ($\backslash$) operator with several noteworthy properties
that can be verified with~\eqref{eq:type-indicator-recurrence}.
We omit the proofs, which are purely technical.
%
\begin{defn}[Inverse]
\makecommand{\word}{\pileType}
\makecommand{\pt}{x}

We will denote by $\invert \word$ the \emph{inverse} of a type sequence $\word = \pt_1 \ldots \pt_m$, 
defined by
$\invert \qsym = \ssym$, $\invert \ssym = \qsym$,
and
$\invert \word = \invert \pt_1 \ldots \invert \pt_m$;
that is,
each pile switches to the opposite type.
For example, if $\word = \qsym\qsym\ssym$, then $\invert \word = \ssym\ssym\qsym$.
\end{defn}
%
\begin{defn}[Dual]
\makecommand{\word}{\pileType}
\makecommand{\pt}{x}

We will denote by $\word^\dual$ the \emph{dual} of $\word$, which is the combination of inversion and sequence reversal,
$\word^\dual = \invert \pt_m \ldots \invert \pt_1$.
%
For example, if $\word = \qsym\qsym\ssym$, then $\word^\dual = \qsym\ssym\ssym$.
(Pure sequence reversal can be captured by $\invert \word^\dual = \ssym\qsym\qsym$.)
\end{defn}
%
The inverse and dual are both self-inverting, in the sense that
${\invert {\invert \pileType}} = \pileType$ and $(\pileType^\dual)^\dual = \pileType$.




\makecommand{\word}{\pileType}

\begin{lemma}[Singleton compositions]
\label{label:singleton-compose-lemma}

\vphantom{new-line}

\begin{enumerate}
\item $\word \backslash \qsym = \qsym \backslash \word = \word$,
\item $\word \backslash \ssym = \word^\dual$, and
\item $\ssym \backslash \word = \invert\word$.
\end{enumerate}

\end{lemma}
%
%For the compositions with a single queue specifically, \ie,
%$\word \backslash \qsym = \qsym \backslash \word = \word$,
%we appeal to the intuition that
%a round of shuffle with a single queue does not change its input.

%
\begin{lemma}%[Composition distributes concatenation]
\label{lemma:concat-lemma}

\makecommand{\pt}{x}

Composition distributes concatenation, \ie,
\[
\pileType \backslash ( \pt_1 \ldots \pt_m )
=
(\pileType \backslash \pt_1) \ldots ( \pileType \backslash \pt_m )
,
\]
for any $\pileType \in \arbpile^*$, $\pt_1 \ldots \pt_m \in \arbpile^*$.
\end{lemma}
%
For example,
$\qsym\qsym\ssym \backslash \qsym\ssym
= (\qsym\qsym\ssym \backslash \qsym)(\qsym\qsym\ssym \backslash \ssym)
= (\qsym\qsym\ssym)(\qsym\ssym\ssym)
= \qsym\qsym\ssym \qsym\ssym\ssym
$.

%
%We observe that
Given Lemmas~\ref{label:singleton-compose-lemma} and~\ref{lemma:concat-lemma},
any composition
$\pileType_1 \backslash \pileType_2 \backslash \ldots \backslash \pileType_\numphase$
can be systematically reduced by pairs to compute~\eqref{eq:type-indicator-recurrence},
by using the lemmas alternatingly starting from the right.
%
For example, 
\begin{align*}
\qsym \qsym \ssym \backslash \qsym\ssym\ssym \backslash \ssym
&= \qsym \qsym \ssym \backslash (\qsym\ssym\ssym \backslash \ssym)
\\
&= \qsym \qsym \ssym \backslash \qsym\qsym\ssym
\\
&= (\qsym \qsym \ssym \backslash \qsym) (\qsym \qsym \ssym \backslash \qsym) (\qsym \qsym \ssym \backslash \ssym) 
%.
= (\qsym \qsym \ssym) (\qsym \qsym \ssym) (\qsym \ssym \ssym)
\\
&= \qsym \qsym \ssym \qsym \qsym \ssym \qsym \ssym \ssym
.
\end{align*}
%
In fact,
the composition operator is associative.
Any contiguous sub-recurrence
of~\eqref{eq:multi-round-defn}
%, \eg,
%on
%%$(\perm_i, \ldots, \perm_j)$
%$\left(
%%(\pileType_\phase)_{\phase=i}^j,
%(\pileType_i, \ldots, \pileType_j), \,
%(\pile_i, \ldots, \pile_j)
%\right)$,
%%$\left(
%%(\pileType_\phase, \pile_\phase)_i^j
%%\right)$,
defines a multi-round sub-shuffle,
equally subject to Lemma~\ref{prop:hetero-multi-sort}.
Therefore we obtain the same result if we reduce from the left instead,
or indeed by any other sequence of adjacent pairs.
%in general.






