\section{Type schedules as finite automata}
\label{sec:chains}

\makecommand{\profile}{\delta}
\makecommand{\profileAlphabet}{\Delta}
\makecommand{\profileFn}{\profileAlphabet}
\makecommand{\step}{b} % "bima" (roughly) is Greek for "step"

\makecommand{\endState}{{\it end}}

\makecommand{\dfaVar}{\pi}
\makecommand{\dfaSet}{\Pi}
\makecommand{\dfaFn}{\dfaSet}

The main objective of the paper is
to prove Theorem~\ref{thm:variable-round-hard},
asserting that
variable-round Dealer's choice pile shuffle sort
(Prob.~\ref{prob:variable-round})
is \NPHard/.
%
We will accomplish that by reducing $\SAT$ to each of a sequence of problems,
ultimately leading to Prob.~\ref{prob:variable-round}.
%
In order to do so
we exploit a 
%fundamental
useful
correspondence between type schedules---%
the certificates of sort feasibility---%
and a class of finite automata
introduced in this section.

%
Let us examine again
the recurrence equation~\eqref{eq:min-piles-mixed}
obtaining pile assignments $\pile^*$
of a minimal sort
of a permutation $\perm \in [n]!$
on pile types given by $\pileType$.
%%
The right-hand side of the recurrence is determined strictly
by the direction of change at each place in the permutation, \ie
whether it is 
increasing or decreasing.
%an ascent or a descent.
Therefore we introduce the concept of a \emph{change profile}:
%
\begin{defn}
The \emph{change profile}
$\profileFn(\perm) =: \profile$
of a permutation $\perm \in [n]!$
is the sequence
on the alphabet 
$$\profileAlphabet \dfneq \{a[scent], d[escent]\}$$
defined for all $s \in [n - 1]$ by
\[
%\text{$\profile(s) = a$ if $\perm(s+1) > \perm(s)$ or else $\profile(s) = d$.}
\profile(s) = \begin{cases}
a,	& \perm(s+1) > \perm(s),	\\
d,	&
%\text{otherwise.}
\perm(s+1) < \perm(s)
.
\end{cases}
\]
\end{defn}
%
For example,
the change profile
of $\perm = 4 8 7 5 3 1 2 6$
is $\profile = addddaa$.

%
If $\profile$ is the change profile of a permutation $\perm$, then
the recurrence of~\eqref{eq:min-piles-mixed} can be written as
%
\begin{align}
\label{eq:trajectory-regular}
\pile^*(s+1) =
\pile^*(s)
+ \left[
	\pileType(\pile^*(s)) = \qsym, \,
	\profile(s) = d
\right]
+ \left[
	\pileType(\pile^*(s)) = \ssym, \,
	\profile(s) = a
\right]
.
\end{align}
%
\eqref{eq:trajectory-regular} has a useful interpretation
as the state update equation governing
a deterministic finite automaton (DFA) over the alphabet $\profileAlphabet$, where
$s$ represents discrete time, and
$\pile^*$ represents the trajectory of the state under input $\profile$.
%
\eqref{eq:trajectory-regular} describes the dynamics of a DFA
defined entirely by $\pileType$:
It is made of a chain of states, %\ie
one of a corresponding type for each type assignment of $\pileType$.
%
For example, $\pileType = \qsym\qsym\ssym\qsym$ defines a chain of five ($5$) nodes, shown in Fig.~\ref{fig:dfa-example-1}.

%
\begin{figure}[h!]
\centering
\begin{tikzpicture}

	\tikzset{
		->, %makes the edges directed
		>=stealth', %makesthearrowheadsbold
		node distance=1.5cm, %specifiestheminimumdistancebetweentwonodes.Changeifnecessary. 
		every state/.style={thick,fill=gray!10}, %setsthepropertiesforeach’state’node 
		initial text=$ $, %setsthetextthatappearsonthestartarrow 
	}

	\makecommand{\qnode}[1]{
	\node[state, accepting, right of ]
	}

	\node[state,initial,accepting] (q1) [label=below:$\qsym$] {$1$};
	\node[state,accepting,right of=q1] (q2) [label=below:$\qsym$] {$2$};
	\node[state,accepting,right of=q2] (q3) [label=below:$\ssym$] {$3$};
	\node[state,accepting,right of=q3] (q4) [label=below:$\qsym$] {$4$};
	\node[state,right of=q4] (end)
	%[label=below:$\endState$]
	{$5$};

	\draw 
		(q1) edge[loop above] node{$a$} (q1) 
		(q1) edge[above] node{$d$} (q2)
		(q2) edge[loop above] node{$a$} (q2) 
		(q2) edge[above] node{$d$} (q3)
		(q3) edge[loop above] node{$d$} (q3) 
		(q3) edge[above] node{$a$} (q4)
		(q4) edge[loop above] node{$a$} (q4) 
		(q4) edge[above] node{$d$} (end)
		(end) edge[loop right] node{$a$, $d$} (end)
;

\end{tikzpicture}
\caption{The deterministic automata (chain), $\dfaFn(\qsym\qsym\ssym\qsym)$.}
\label{fig:dfa-example-1}
\end{figure}

%
Queue states (piles) consume arbitrarily long ascending ``runs'' of a permutation,
but no descents, while stack states consume descending runs but no ascents:
%
Accordingly, in Fig.~\ref{fig:dfa-example-1},
the $\qsym$ nodes have $a$ as a self loop while $d$ transitions to the next node in the chain;
conversely,
the $\ssym$ node has $d$ as a self-loop and 
$a$ transitions to the next node.
A final terminal node, appended to the end of the chain, returns to itself on either $a$ or $d$.

We have seen that sort is feasible on $\pileType$
if and only if~\eqref{eq:min-piles-mixed} has a solution.
The trajectory of the change profile $\profileFn(\perm)$
starting from the beginning of the chain ($\pile^*(1) = 1$)
is a solution to~\eqref{eq:min-piles-mixed} as long as it
ends in one of the pile states (any but the terminal node).
%Otherwise, \ie, 
If the terminal state is reached, however, then
\eqref{eq:min-piles-mixed} has no solution;
$\pileType$ is too short to sort $\perm$.
%
Accordingly,
we mark only the pile states as \emph{accepting} states (double outline in Fig.~\ref{fig:dfa-example-1}),
but not the terminal state.
%
Then we obtain the following key results:
%
\begin{prop}
\label{prop:sort-by-automata}
A permutation $\perm$ can be sorted
by a single-round shuffle with the pile type assignments $\pileType$ if and only if
its change profile $\profileFn(\perm)$ is accepted 
by the corresponding automaton, which we denote $\dfaFn(\pileType)$.
%($\profile$ is therefore a member of an associated regular language.)
%(The equivalence between regular languages and finite automata is well known.)
\end{prop}
%
\begin{corollary}
A permutation $\perm$
can be sorted by a multi-round shuffle with the type schedule $\typeSchedules$ if and only if
$\profileFn(\perm)$ is accepted by $\dfaFn(\typeSchedules) \dfneq \dfaFn(\vrPileType_1)$
($\vrPileType_1$ of Lemma~\ref{prop:hetero-multi-sort}).
\end{corollary}
%
The proof of the corollary is a trivial application of Lemma~\ref{prop:hetero-multi-sort} to Prop.~\ref{prop:sort-by-automata}.

%
\makecommand{\dynamicsFn}{f}
\makecommand{\localStateVar}{\pile^*}
%\makecommand{\localStateVar}{\pile}

For completeness, we give a formal definition of $\dfaFn$:
%
\begin{defn}[Sort certificate chain]
The ``chain'' automaton $\dfaFn(\pileType)$ of a types assignment $\pileType$
on $\numpile$ piles
is defined over the alphabet $\profileAlphabet$ as follows:
%
It is on states $[\numpile + 1]$,
starting from $\pile^*(1) = 1$, and accepting the states $[\numpile]$.
It is governed by 
$\pile^*(s + 1) = \dynamicsFn_{\dfaFn(\pileType)}(\pile^*(s), \profile(s))$,
where
\[
	\dynamicsFn_{\dfaFn(\pileType)}(\localStateVar, \profile) = \begin{cases}
		\localStateVar + \left[
			\pileType(\localStateVar) = \qsym, \,
			\profile = d
		\right]
		+ \left[
			\pileType(\localStateVar) = \ssym, \,
			\profile = a
		\right]
		& \localStateVar \leq \numpile
		\\
		\numpile + 1 & \localStateVar = \numpile + 1
		.
	\end{cases}
\]
%
\end{defn}


\subsection{Objective reformulation}



\makecommand{\questionCons}{{\mathcal Q}}
\makecommand{\allowedSched}{\sortScenario}

\makecommand{\paramVar}{\theta}
\makecommand{\paramSet}{\Theta}

\makecommand{\word}{W}
