\gtNeg &\dfneq daddddadaaadad, \\
\gtDk &\dfneq adadddadaaadad, \\

\lastLitSeg_i(\clause_j) &\dfneq \begin{cases}
\gtLastPos	& x_i \in \clause_j,
\\
\gtLastNeg	& \neg x_i \in \clause_j,
\\
\gtLastDk	& \textrm{otherwise},
\end{cases}
\\

\gtLastPos &\dfneq aaddddaddddaaaaddaaaadddda, \\

\gtLastNeg &\dfneq daddddaddddadaaadaaaadaaaadddda,	\\

\gtLastDk &\dfneq daaddddaddddaaaaddaaaadddda.

\end{array}
