a start state becomes a clause not activated state;

\item
$\theWord \in \, \geq \bChainDisq \backslash k \to \, \geq \bClauseDisq \backslash k$, \ie,
chain disqualification becomes clause disqualification.
\end{itemize}

\end{lemma}
