At last we have the tools needed for the proof of Lemma~\ref{lemma:clause-gadget}.
%
\begin{proof}[Proof of Lemma~\ref{lemma:clause-gadget}]
We start with trajectories from $\bChainDisq \backslash k_1$:
According to Lemma~\ref{lemma:start-clause},
after $\gtStart$ the state will be $\tilde k_0 \geq \bClauseDisq \backslash k_1$.
%
Then, according to Lemma~\ref{lemma:lit-gadget},
for each $i \in [n-1]$,
the application of $\litSeg_i(\clause_j)$ will transit from state $\tilde k_{i-1}$ to $\tilde k_{i}$, where
$\tilde k_i \geq \bClauseDisq \backslash (k_1 + i)$.
%
Finally, according to Lemma~\ref{lemma:endlit-gadget},
$\lastLitSeg_{n}(\clause_j)$ transits
from $\tilde k_{n-1} \geq \bClauseDisq \backslash (k_1 + n - 1)$
to $\tilde k_n
\geq \bChainDisq \backslash (k_1 + n + 1)$.

Next we consider trajectories from $\bStart \backslash k_1$
when $A_1 = \assignEmbed(\assignvec) \qsym$ for some $\assignvec \in SAT(\clause_j)$.
%
In this case
$\gtStart$ takes us to $\tilde k_0 = \bNActd \backslash k_1$.
%
Since ${\mathbf x} \in SAT(\clause_j)$, then in at least one place
either
$x_i = \top$ where $x_i \in \clause_j$, or
$x_i = \bot$ where $\neg x_i \in \clause_j$.
Then, respectively, either
$\assignEmbed(x_i) = \qsym$ and $\litSeg_i(\clause_j) = \gtPos$ or
$\assignEmbed(x_i) = \ssym$ and $\litSeg_i(\clause_j) = \gtNeg$.
%and .
We consider the first such $i$.
%
For each $i'=1 \ldots i-1$,
$\litSeg_{i'}(\clause_j)$ moves
from $\tilde k_{i'-1} = \bNActd \backslash (k_1 + i' - 1)$
to $\tilde k_{i'} = \bNActd \backslash (k_1 + i')$.
%
Then activation occurs:
%
If $i < n$, then
$\litSeg_i(\clause_j)$ moves
from $\tilde k_{i-1} = \bNActd \backslash (k_1 + i - 1)$
to $\tilde k_{i} = \bActd \backslash (k_1 + i)$.
Then for each $i' \in (i+1) \ldots n-1$,
$\litSeg_{i'}(\clause_j)$ moves
from $\tilde k_{i'-1} = \bActd \backslash (k_1 + i' - 1)$
to $\tilde k_{i'} = \bActd \backslash (k_1 + i')$.
%
Finally $\lastLitSeg_n(\clause_j)$ moves
from $\tilde k_{n-1} = \bActd \backslash (k_1 + n - 1)$
to $\bEnd \backslash (k_1 + n)$.
%
If $i = n$, then 
$\lastLitSeg_n(\clause_j)$ simply moves
from $\tilde k_{n-1} = \bNActd \backslash (k_1 + n - 1)$
to $\tilde k_{n} = \bEnd \backslash (k_1 + n)$.

Finally, we consider trajectories from
$\bStart \backslash k_1$
when $A_1$ is \emph{not} of the form $\assignEmbed(\assignvec) \qsym$
for some $\assignvec \in SAT(\clause_j)$.
Then either 
$A_1 = \assignEmbed(\assignvec) \qsym$ for ${\mathbf x} \notin SAT(\clause_j)$,
or else
$A_1 = \assignEmbed(\assignvec) \ssym$, \ie, it ends on a stack.
%
In the former case there is never any activation, and so
$\tilde k_{n-1} = \bNActd \backslash (k_1 + n-1)$, and
$\lastLitSeg_n(\clause_j)$ moves
to $\tilde k_n \geq \bChainDisq \backslash (k_1 + n + 1)$.
%
If $A_1$ ends on a stack, then regardless of whether activation occurred,
since $\tilde k_{n-1} \geq \bActd \backslash (k_1 + n-1)$
then $\lastLitSeg_n(\clause_j)$ moves
to $\tilde k_n \geq \bChainDisq \backslash (k_1 + n + 1)$.
\end{proof}








