\section{Sort on $\theInstances$ is \NPHard/}
\label{sec:Q1}

Now we complete our first reduction of SAT to an accepting-chain problem,
specifically $\probAlias{1}'$,
and
thereby to the associated sort feasibility problem $\probAlias{1}$.
As shown in Table~\ref{table:all-problems},
their permissible sets are of the form $\theInstances$.

We begin by introducing a problem-specific embedding of formulae
as change profiles,
including a new trivial low-level gadget:

\begin{defn}
Given a CNF
formula $\clause$ of $m \geq 1$ clauses, we define
$$\formSeg_{\Rom{1}} (\clause)
\dfneq
\mainClause(\clause_1) \,
\gtNext \, \mainClause(\clause_2)
\ldots
\gtNext \, \mainClause(\clause_m)
,
$$
where
$\gtNext \dfneq a$.
\end{defn}

\begin{lemma}
\label{lemma:next-clause}
For every chain
$\designAlign \backslash x_0 \ldots x_n 
\in \designAlign \backslash \arbpile^{n+1}$,
$n \geq 1$,
for each measure $k \in [n]-1$,
if $x_k = \qsym$, then
$\gtNext \in \bEnd \backslash k \to \bStart \backslash (k+1)$.
\end{lemma}

\begin{proof}
The proof is again exhaustive and can be verified (easily)
with the trajectory plots for $\gtNext = a$ in Fig.~\ref{fig:next-proof}.
\end{proof}

%
\begin{figure}[h!]
	\centering
	\includegraphics[width=.75\linewidth]{fig/gadgets/next-clause-5.pdf}
\caption{
Trajectories of $\gtNext$
on chain automata
of the form $\designAlign \backslash x_0 \ldots x_n$
(only $x_k = \qsym$)
starting from $\bEnd \backslash k$.
}
\label{fig:next-proof}
\end{figure}

%
The figure demonstrates the function of the word $\gtNext$,
which is to move from the end of one measure to the start of the next one.
It provides us a key adaptation of Lemma~\ref{lemma:clause-gadget}.

\begin{lemma}
\label{lemma:clause-plus-next}
Given a CNF clause $\clause_j$ on $n \geq 1$ variables,
the following statements hold
for every
$k_1 \geq 0$, $k_2 \geq 1$,
and for every chain
$\designAlign \backslash A_0 A_1 A_2 \in \designAlign \backslash \arbpile^{k_1} \arbpile^{n+1} \arbpile^{k_2}$:
%
\begin{itemize}

\item
if $A_1 = \assignEmbed(\assignvec) \qsym$ for some $\assignvec \in SAT(\clause_j)$, then
$\mainClause(\clause_j) \, \gtNext
\in \bStart \backslash k_1 \to \bStart \backslash (k_1 + n + 1)$%
;

\item
otherwise, it is in
$\bStart \backslash k_1 \to \, \geq \bChainDisq \backslash (k_1 + n + 1)$;

\item
$\mainClause(\clause_j) \, \gtNext
\in \bChainDisq \backslash k_1 \to \, \geq \bChainDisq \backslash (k_1 + n + 1)$.
%, unconditionally.

\end{itemize}
\end{lemma}

\begin{proof}
The proof is a fairly straightforward combination of Lemmas~\ref{lemma:clause-gadget} and~\ref{lemma:next-clause}.
\end{proof}
%
We omit the graph of the lemma's claims, which would be nearly identical to that of Fig.~\ref{fig:traj-clause},
only with $\bStart \backslash (k_1 + n + 1)$ as the top-right corner.
(Which makes it chainable.)

Now we may consider trajectories of the formula gadget as a whole.
%
\begin{lemma}
\label{lemma:formula-gadget}
Given a formula $\clause$
of $m$ CNF clauses $\{ \clause_j \}_{j=1}^m$ on $n \geq 1$ variables,
%
the following statements hold
on all
$\designAlign \backslash A_1 \ldots A_{m} x \in \designAlign \backslash \left( \arbpile^{n+1} \right)^{m} \arbpile$%
:
%
\begin{enumerate}

\item
%
if for each $j \in [m]$,
$A_{j} = \assignEmbed(\assignvec_j) \qsym$
for some $\assignvec_j \in SAT(\clause_j)$,
then
$\formSeg_\Rom{1}(\clause)
\in \bStart \backslash 0
\to
\bEnd \backslash (m(n+1) - 1)
$%
;

\item
otherwise, 
$\formSeg_\Rom{1}(\clause)
\in \bStart \backslash 0
\to \, \geq \bChainDisq \backslash m(n+1)$.

%\item
%$\bChainDisq \backslash 0 \backslash 0 
%\to \geq \bChainDisq \backslash 0 \backslash m$
%unconditionally.\todo{do we care though?}
\end{enumerate}
\end{lemma}

\begin{proof}
We start with the first case.
Due to Lemma~\ref{lemma:clause-plus-next},
for each $j \in [m-1]$,
the segment $\clauseSeg(\clause_j) \, \gtNext$
moves
from state $\tilde k_{j-1} = \bStart \backslash (j-1)(n+1)$
to state $\tilde k_j = \bStart \backslash j(n+1)$.
%
Then,
due to Lemma~\ref{lemma:clause-gadget},
$\clauseSeg(\clause_m)$
moves
from state $\tilde k_{m-1} = \bStart \backslash (m-1)(n+1)$
to state $\tilde k_m = \bEnd \backslash (m(n+1)-1)$.

In the second case,
there is at least one clause $\clause_j$ for which
$A_{j} \neq \assignEmbed(\assignvec_j) \qsym$ for any $\assignvec_j \in SAT(\clause_j)$.
%
Then $\clauseSeg(\clause_j)$ moves
from state $\tilde k_{j-1} \geq \bStart \backslash (j-1)(n+1)$
to $\tilde k_j \geq \bChainDisq \backslash j(n+1)$.
Then for each $j' \in (j+1) \ldots m$ (none if $j = m$),
%the segment 
$\gtNext \, \clauseSeg(\clause_j)$ moves from 
state $\tilde k_{j'-1} \geq \bChainDisq \backslash (j'-1)(n+1)$
to state
$\tilde k_{j'} \geq \bChainDisq \backslash j' (n+1)$.
%
\end{proof}




\begin{lemma}
\label{lemma:red1-language}
Given a formula $\clause$ of $m\geq 1$ CNF clauses on $n \geq1$ variables,
a chain $\pi \in \designAlign \backslash \arbpile^{n+1} \backslash \qsym^m$ accepts
the change profile $\formSeg_{\Rom{1}}(\clause)$
if and only if
$\pi = \designAlign \backslash \assignEmbed(\assignvec) \qsym \backslash \qsym^m$ for some $\assignvec \in SAT(\clause)$.
\end{lemma}

%
\begin{varscope}
\makecommand{\word}{A}
%
\begin{proof}
By definition every chain $\pi \in \designAlign \backslash \arbpile^{n+1} \backslash \qsym^m$ can be expressed as
$\pi = \designAlign \backslash A \backslash \qsym^m$ for some $A \in \arbpile^{n+1}$.
Then by Lemma~\ref{lemma:concat-lemma},
$\pi$ is equal to the concatenation
of $m$ copies of $\designAlign \backslash A \backslash \qsym = \designAlign \backslash A$, \ie,
$\pi
= \left(\designAlign \backslash A\right) \ldots \left(\designAlign \backslash A\right)
= \designAlign \backslash A \ldots A$.
%
Being one measure shorter than the chains 
of Lemma~\ref{lemma:formula-gadget},
$\pi$ cannot reach 
the state $\bChainDisq \backslash m(n+1)$
of the lemma's second case;
it reaches the terminal state instead.
%
Therefore
$\pi$ accepts the formula gadget if and only if
the condition of the first case holds.
That is exactly the condition of the present lemma:
$\word = \assignEmbed(\assignvec) \qsym$ for some $\assignvec$
such that $\assignvec \in SAT(\clause_j)$ for all $j$,
\ie, $\assignvec \in SAT(\clause)$.
\end{proof}
\end{varscope}

\makecommand{\theProblem}{\questionSet_{\Rom{1}}}
\makecommand{\theFormula}{\formSeg_{\Rom{1}}(\clause)}

\begin{corollary}
\label{cor:reduction-1}
For every instance $\questionCons_\SAT(\clause) \in \SAT$,
with formula $\clause$ of $m$ clauses on $n$ variables,
the instance
$\questionCons_\chainScript\left(
\theFormula,
\designAlign \backslash \arbpile^{n+1} \backslash \qsym^m
\right)$
is in $\theProblem'$
and has the same answer.
\end{corollary}
%
\begin{proof}
%
We can see by inspection that
the latter question is in $\theProblem'$ (Table~\ref{table:all-problems}).
%
We obtain the corollary from Lemma~\ref{lemma:red1-language} because
the permissible schedules 
$\designAlign \backslash \arbpile^{n+1} \backslash \qsym^m$
%by inspection,
contains the embedding
$\designAlign \backslash \assignEmbed(\assignvec) \qsym \backslash \qsym^m$
of every $\assignvec \in \{\top, \bot\}^n$.
%
Therefore, an accepting chain exists if and only if $\clause$ is satisfiable.
\end{proof}

\begin{lemma}
%Corollary~\ref{cor:reduction-1} allows us to prove that 
$\theProblem$ and $\theProblem'$ are \NPHard/.
\end{lemma}
%
\begin{proof}
Corollary~\ref{cor:reduction-1}
leaves only to prove that
its reduction is polynomial-time:
%
The output instance data includes the change profile $\theFormula$
and parameters $m$ and $n$ of the permissible set.
(The latter are negligible in transcription length.)
%
The change profile is composed of $m$ instances of $\gtClause$,
each of length $O(n)$, and so
can be transcribed in $O(mn)$ time.
%
The transcription length $|\clause|$ of a CNF formula $\clause$ 
of $m$ clauses on $n$ variables
is at least proportional to $m$ or $n$, whichever is larger,
so $O(mn) \subseteq O(|\clause|^2)$.
\end{proof}




