,
\]
%
where

$\clauseSeg_\Rom{2}(\clause_j) = \gtQ \, \clauseSeg(\clause_j)$,
with
$\gtQ \dfneq dadaaaadaaaaddddaaaa$.

\end{defn}
%
The word $\gtQ$ has the function
of forcing
its measure to be $\designAlign \backslash \qsym$
in accepting chains,
rather than $\designAlign \backslash \ssym$:
%
\begin{lemma}%[$\gtQ$]
\label{lemma:traj-force-q}

\makecommand{\pt}{\pileTypeSingle}

The following statements hold 
for every chain $
\designAlign \backslash \pt_0 \ldots \pt_{n} \in 
