\begin{lemma}
\label{lemma:formula2}
%
Given a formula $\clause$
of $m$ CNF clauses $\{ \clause_j \}_{j=1}^m$
on $n \geq 1$ variables,
%
the following statements hold
for every chain
$\designAlign \backslash A_1 \ldots A_{m} x \in \designAlign \backslash \left( \arbpile^{n+2} \right)^{m} \arbpile$:
