\end{lemma}
%
We leave the proof of the lemma as an exercise for the reader.
The logic is essentially the same as for Lemma~\ref{lemma:formula-gadget},
but 
with the placements of $\gtQ$ ensuring that
$A_j = \qsym \assignEmbed(\assignvec_j) \qsym$
rather than
$A_j = \assignEmbed(\assignvec_j) \qsym$
previously.
(We will soon exploit the symmetry
of having a $\qsym$ on each side
of an assignment embedding.)

For the next result we require an important property of factorable type schedules:
%
\begin{lemma}[Equivalence classes]
\label{lemma:equivs}
Given any two type schedules $\pileType_1$ and $\pileType_2$,
\[
\pileType_1 \backslash \pileType_2
=
\pileType_1^\dual \backslash {\invert \pileType_2}
.
\]
\end{lemma}
%
\begin{proof}
We offer a simple, purely algebraic proof based on previously-discussed properties of the two types of inverses:
%
\begin{align*}
\pileType_1 \backslash \pileType_2
&= \pileType_1 \backslash \qsym \backslash \pileType_2
= \pileType_1 \backslash (\ssym \backslash \ssym) \backslash \pileType_2
= (\pileType_1 \backslash \ssym) \backslash (\ssym \backslash \pileType_2)
= \pileType_1^\dual \backslash \invert \pileType_2
.
\end{align*}
\end{proof}

\begin{varscope}
\makecommand{\word}{A}
\begin{lemma}
\label{lemma:red2-language}
Given a formula $\clause$
of $m \geq 1$ CNF clauses
on $n \geq 1$ variables,
%
a chain $\pi \in \designAlign \backslash \arbpile^{n+2} \backslash \arbpile^m$ accepts
the change profile $\formSeg_{\Rom{2}}(\clause)$
if and only if
$\pi = \designAlign \backslash \qsym \assignEmbed(\assignvec) \qsym \backslash \qsym^m$ for some $\assignvec \in SAT(\clause)$.
\end{lemma}
%
\begin{proof}
By definition every chain $\pi \in \designAlign \backslash \arbpile^{n+2} \backslash \arbpile^m$ can be expressed by
$\pi = \designAlign \backslash A \backslash x_0 \ldots x_{m-1}$
for some $\word \in \arbpile^{n+2}$, $x_0 \ldots x_{m-1} \in \arbpile^m$.
Without loss of generality $x_0 = \qsym$, since otherwise, by Lemma~\ref{lemma:equivs},
$\pi$ can be equivalently expressed as $\designAlign \backslash A^\dual \backslash \invert x_0 \ldots \invert x_{m-1}$.
%
By Lemma~\ref{lemma:concat-lemma},
$\pi = 
\left( \designAlign \backslash A \backslash x_0 \right)
\ldots
\left( \designAlign \backslash A \backslash x_{m-1} \right)
$,
where
$\designAlign \backslash A \backslash x_j = \designAlign \backslash A$ if $x_j = \qsym$, otherwise, when $x_j = \ssym$,
$\designAlign \backslash A \backslash x_j = \designAlign \backslash A^\dual$.

%Similarly as in the proof of Lemma~\ref{lemma:red1-language},
Only the first case in Lemma~\ref{lemma:formula2} ends in
%a state strictly less than $0 \backslash 0 \backslash m = 6(n+2)m$,
%which is the non-accepting terminal state on the truncation represented by the DFA of $\pi$.
an accepting state on truncated $\pi$.
%
Therefore, the
acceptance criteria
become:
\begin{itemize}
\item wherever $x_j = \qsym$, $A = \qsym \assignEmbed(\assignvec) \qsym$ for some $\assignvec \in SAT(\clause_j)$; and

\item wherever $x_j = \ssym$, $A^\dual = \qsym \assignEmbed(\assignvec) \qsym$ for some $\assignvec \in SAT(\clause_j)$;
%---i.e., 
equivalently,
$A = \ssym \assignEmbed^\dual(\assignvec) \ssym$.
\end{itemize}
%
Clearly it is impossible for $A$ to be of 
%a mixture of the pile types among $x_0 \ldots x_{m-1}$ to satisfy 
both forms simultaneously.
Then since $x_0 = \qsym$,
acceptance can only occur if
%they are all $\qsym$.
$x_1 \ldots x_{m-1}$ % = \qsym^{m-1}$.
are all $\qsym$ as well.
%
In such case
the first condition is used uniformly for all $j$,
which obtains the lemma.
\end{proof}
\end{varscope}

