${\gtAlign}^{6n+1} \in \bStart \backslash k_1 \, \to \bStart \backslash \nextBlock$;
%\ie, from the start of $A_1$ to the start of $A_2$;

\item otherwise
${\gtAlign}^{6n+1} \in \bStart \backslash k_1 \, \to \, \geq \bChainDisq \backslash \nextBlock$;
%\ie, disqualified on the same measure;

\item
${\gtAlign}^{6n+1} \in \bChainDisq \backslash k_1 \, \to \, \geq \bChainDisq \backslash \nextBlock$;
%, unconditionally;

\end{itemize}

\item otherwise,
${\gtAlign}^{6n+1}
\in \bStart \backslash k_1 \, \to \, \geq \bChainDisq \backslash ( k_1 + 2(6n+1) + n )$.
%skipping $A_2$ entirely.

\end{itemize}
