%$\reverseFn_m^{2k+1} = \reverseFn_m$.

%
For each $\phase \in [\numphase]$,
let
\begin{equation}
\label{eq:pile-type-indicator}
\pileTypeInd_\phase(\pile)
\dfneq \left[ \pileType_\phase(\pile) = \ssym \right]
= \begin{cases}
0	& \pileType_\phase(\pile) = \qsym
\\
1	& \pileType_\phase(\pile) = \ssym
,
\end{cases}
\end{equation}
and
%
let $\{ \vrPileTypeFn_\phase \}_{\phase=1}^{\numphase + 1}$
be defined
by the backward recurrence starting from
$\vrPileTypeFn_{\numphase + 1} = 0$
with
%
\begin{varscope}
\makecommand{\realParity}{ \vrPileTypeFn_{\index+1}(\itTwo) }
%
\begin{align}
\label{eq:type-indicator-recurrence}
%
\vrPileTypeFn_{\index}(
	\itOne
	+
	\numpile_\index \itTwo
)
&=
%
\pileTypeFn_\index\left(
	\reverseFn_{\numpile_\index}^{\realParity}
	(\itOne)
\right)
%, \qquad 1 \leq \phase < \numphase - 1
\xor
\realParity
,
\qquad
\itOne \in [\numpile_\index] - 1
, \,
\itTwo \in [\vrNumPile_{\phase+1}] - 1
,
\end{align}
\end{varscope}%
%
where
$$ %\[
\vrNumPile_\phase \dfneq \prod_{\phase \leq \phase' \leq \numphase} \numpile_{\phase'}
,
\qquad 1 \leq \phase \leq \numphase + 1
;
$$
%
the operator $\xor$ denotes modulo-$2$ addition.
%
Note that
$\vrNumPile_{\numphase + 1} = 1$,
and
\eqref{eq:type-indicator-recurrence} defines
$\vrPileTypeFn_\phase$
over the co-domain $[\vrNumPile_\phase] - 1$
for each $\phase \in [\numphase]$.

The types assignment $\vrPileType_1$
of our virtual shuffle
is the assignment of types to $\vrNumPile_1$ virtual piles which satisfies
$$
\vrPileTypeFn_1(\pile)
= \left[ \vrPileType_1(\pile) = \ssym \right]
,
\qquad
\pile \in [\vrNumPile_1] - 1
.
$$
%
$\vrpile_1$ in turn falls out of the following reversible backward recurrence:
%
\begin{align}
\begin{cases}
\vrpile_\numphase = \pile_\numphase,
&
\\
%
\designpile_\phase(s)
=
\reverseFn_{\numpile_\phase}^{
	\vrPileTypeFn_{\phase+1}(\vrpile_{\phase+1}(s))
}(\pile_\phase(s))
,
&
1 \leq \phase \leq \numphase - 1, \, s \in [n],
\\
%
\vrpile_\phase
=
	\designpile_\phase
	+
	\numpile_\phase \vrpile_{\phase+1}
	,
&
1 \leq \phase \leq \numphase-1
.
\end{cases}
\label{eq:hetero-multi-embedding}
\end{align}
%
Each $\vrpile_\phase$ takes value on the range $[\vrNumPile_\phase]-1$.


